-- Sources: data/i18n/zhCN. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["item:gyromechanic-gear"] = {n="多档齿轮",s="在卡拉诺斯，发明家们正在寻找多档齿轮，用于一项大胆的实验。他们希望逆转麻风侏儒的变异。",h="在卡拉诺斯，发明家们正在寻找多档齿轮，用于一项大胆的实验。他们希望逆转麻风侏儒的变异。",kw={"诺莫瑞根","多档齿轮","卡拉诺斯","麻风侏儒","自动净化装置","拉兹·滑链","净化装置","自适应齿轮"},ang={["profession:Engineering"]="身为工程师，你了解侏儒回转机械零件的复杂设计和严格的公差要求。它们用于调节运行不稳定的原型机械。",["race:Gnome"]="身为侏儒，你每回收一个齿轮，就让工匠们离拯救同胞的机会更近一步，那些同胞正在诺莫瑞根外的雪地中饱受辐射之苦。"},sec={{t="重组装置的组件",b="侏儒们奋力驱逐穴居人时，辐射席卷了诺莫瑞根。许多幸存者变成了疯狂的、受到辐射的麻风侏儒。奥齐·电环和拉兹·滑链不愿放弃这些变异的同胞，于是设计了净化装置。这台机器旨在消除辐射的影响。\n\n它的原型机需要能承受内部不稳定压力的精密机械部件，包括多档齿轮和自适应齿轮。诺莫瑞根的陷落让当地的制造业停摆。如今，发明家们必须从游荡在丹莫罗的敌对麻风侏儒身上回收这些精密零件。"}},faq={{q="多档齿轮有什么用途？",a="卡拉诺斯的拉兹·滑链需要多档齿轮，用作净化装置的核心零件。原型机将把它们与自适应齿轮配合使用，尝试治愈受到辐射的麻风侏儒。",al={"多档齿轮用途","多档齿轮有什么用","多档齿轮任务"}},{q="这些齿轮从哪里来？",a="这些齿轮可以从诺莫瑞根外的麻风侏儒和丹莫罗的吉波维特身上回收。",al={"哪里能找到多档齿轮","多档齿轮掉落","谁掉落多档齿轮"}},{q="净化装置真的能治愈麻风侏儒吗？",a="拉兹·滑链信任奥齐·电环的设计图，相信改进燃烧活塞和电胶凝胶就能让同胞恢复原状。这台机器尚未经过大规模测试，能否治疗辐射中毒仍未得到验证。",al={"净化装置是否有效","麻风侏儒能否治愈","净化能否成功"}},{q="侏儒为什么不能直接制造新齿轮？",a="诺莫瑞根的陷落摧毁了侏儒的工业体系，也让他们无法再使用最精良的工具、工坊和自动化铸造厂。在城市外围回收完好的精密机械零件，往往比手工制造更快。",al={"为什么回收齿轮","为什么不制造多档齿轮"}}},fx={["93a017f3"]={q="多档齿轮是什么？",a="多档齿轮是为复杂侏儒机械打造的精巧零件。这些精密部件原本用于诺莫瑞根庞大的机械设施，如今却散落在废墟中，被潜伏在这座沦陷科技之城外的卑劣生物拾走。",al={"多档齿轮是什么","多档齿轮信息","关于多档齿轮"}}},fp="17,121,30.581.0,37.195.0,31.94.0,50.211.0,40.221.0"}
P.entries["item:hallowed-letter"] = {n="神圣信件",s="在北郡山谷，女牧师安妮塔召唤年轻的牧师前往北郡修道院。她的信件开启了他们研习圣光的道路。",h="在北郡山谷，女牧师安妮塔召唤年轻的牧师前往北郡修道院。她的信件开启了他们研习圣光的道路。",kw={"安妮塔","艾尔文森林","神圣信件","圣光","北郡修道院","牧师","女牧师安妮塔"},ang={["class:Priest"]="作为牧师，这封信认可你是圣光的使者，也将你与北郡修道院的训练师联系在一起。",["race:Human"]="作为人类，你传承着北郡山谷履行神圣职责的传统，那里的人们早在第一次兽人战争之前就已践行这一传统。"},sec={{t="信仰的召唤",b="神圣信件上印着女牧师安妮塔的个人徽记。初出茅庐的牧师在北郡山谷的狗头人营地完成最初的试炼后，便会收到这封信。她在每位新晋牧师身上都看到了圣光的火花，敦促他们进入修道院，为其效力。第三次大战之后，黑暗势力仍在艾泽拉斯各处盘踞。牧师团召集能够治愈、保护和指引他人的人，帮助一个艰难维持秩序的帝国。"}},faq={{q="神圣信件是什么？",a="神圣信件是女牧师安妮塔写给初到北郡修道院的牧师的书信。信中召唤他们前去接受最初的职业教导。",al={"神圣信件是什么","神圣信件物品","牧师信件北郡"}},{q="这封信是谁写的？",a="信上印着女牧师安妮塔的徽记。她负责训练和指引来到北郡的年轻人类牧师。",al={"谁寄的信","作者是谁","寄信人"}},{q="为什么牧师团此时召集新的入门者？",a="艾泽拉斯仍然动荡不安，燃烧军团的残余势力依旧在此肆虐。卡利姆多面临新的考验，而暴风城需要心怀仁慈的治疗者和领袖，来重建家园、保护人民。",al={"牧师为何需要帮助","世界局势","牧师背景故事黑暗之门开启后25年"}},{q="读完信后该做什么？",a="带着信进入北郡修道院，与女牧师安妮塔交谈。她会接受你对圣光的誓言，并随着你的旅程推进，传授你新的牧师技艺。",al={"信送到哪里","神圣信件任务交付","找谁交谈"}}},fx={["0a342f04"]={q="女牧师安妮塔为什么要让你收到神圣信件？",a="女牧师安妮塔寄出这封信，是为了召集北郡修道院内有潜力的圣光初学者。她看到你在保卫山谷时展现出了潜力，希望向你介绍自己，引导你的虔诚信仰，并进一步传授牧师的神圣技艺。",al={"为什么需要神圣信件","安妮塔为什么寄信","神圣信件用途"}}},fp="15,128,15.424.0,28.147.0,21.113.0,58.196.0,42.179.0"}
P.entries["item:hallowed-rune"] = {n="神圣符文",s="在寒脊山谷，布兰斯托克·卡德尔将神圣符文送给牧师新手，召他们前往安威玛尔开始训练。",h="在寒脊山谷，布兰斯托克·卡德尔将神圣符文送给牧师新手，召他们前往安威玛尔开始训练。",kw={"安威玛尔","布兰斯托克·卡德尔","寒脊山谷","丹莫罗","神圣符文","牧师","穴居人"},ang={["class:Priest"]="身为牧师，你从寒脊山谷的神圣符文开始，正式接受圣光的教导。",["race:Dwarf"]="身为矮人，你将对圣光的敬畏与对铁炉堡的责任融为一体，保卫山中的家园，抵御穴居人。"},sec={{t="圣光的召唤",b="神圣符文承载着圣光的教诲。年轻的牧师通过帮助山谷中的巡山人和守卫，证明自己的决心。随后，布兰斯托克派他们前往安威玛尔，在那里教导他们治疗伤口，运用神圣之力对抗威胁丹莫罗的穴居人。"}},faq={{q="神圣符文是什么？",a="神圣符文是一块刻有牧师新手指引的圣石。布兰斯托克·卡德尔送出这块符文，召他们到安威玛尔内开始接受精神与法术方面的教导。",al={"这是什么物品","神圣符文物品","符文用途"}},{q="是谁将神圣符文送给你？",a="布兰斯托克·卡德尔是安威玛尔的矮人牧师训练师，他将神圣符文送给寒脊山谷的牧师新手。",al={"谁送来的符文","谁给的这块符文","布兰斯托克符文"}},{q="收到神圣符文后该做什么？",a="阅读符文，然后前往安威玛尔的大厅，向布兰斯托克·卡德尔报到。他会教你新的祷言和法术。",al={"符文交到哪里","神圣符文怎么用"}},{q="布兰斯托克为什么希望牧师新手尽快接受训练？",a="布兰斯托克希望牧师新手接受训练，因为穴居人不断入侵寒脊山谷。巡山人需要治疗和神圣之力来保卫丹莫罗。",al={"为什么需要牧师","穴居人威胁与牧师"}}},fx={fac25589={q="为什么会有人把神圣符文交给我？",a="这枚符文是一份正式的召令，也是传给寒脊山谷牧师新人的信件。布兰斯托克·卡德尔托人送出符文，召集有志追随圣光的侍僧前往安威玛尔，以便指导他们的信仰，并传授保卫山谷所必需的神圣法术。",al={"为什么会有神圣符文","神圣符文用途","为什么需要神圣符文"}}},fp="13,114,22.281.0,26.185.0,35.121.0,51.138.0,58.152.0"}
P.entries["item:hallowed-scroll"] = {n="神圣卷轴",s="在丧钟镇，神圣卷轴召唤新近苏醒的被遗忘者牧师前往残破的礼拜堂。卷轴上盖着黑暗牧师杜斯滕的印章，由此开启他们对信仰、意志与暗影的研习。",h="在丧钟镇，神圣卷轴召唤新近苏醒的被遗忘者牧师前往残破的礼拜堂。卷轴上盖着黑暗牧师杜斯滕的印章，由此开启他们对信仰、意志与暗影的研习。",kw={"丧钟镇","杜斯坦","被遗忘者","神圣卷轴","光明","牧师","提瑞斯法"},ang={["class:Priest"]="身为被遗忘者牧师，这张羊皮纸标志着你与传统人类信仰的决裂。它指引你确立自己的信念，并研习Cult of the Forgotten Shadow的暗影法术。",["race:Undead"]="身为亡灵旅者，你收到这份召集令时，丧钟镇正急切地召集并训练新近苏醒者，将他们编入Sylvanas的部队。"},sec={{t="致无信者的召唤",b="新近复生的被遗忘者牧师感到，自己与世界的联系发生了剧变。丧钟镇在持续的混乱中逐渐被收复，神圣卷轴指引他们前往镇上残破的礼拜堂寻求指导。羊皮纸上盖着黑暗牧师杜斯滕的印章。卷轴向新晋牧师介绍了正式的教导，并命他们前去报到，开始研习塑造被遗忘者牧师之道的务实信条。"},{t="自立之路",b="黑暗牧师杜斯滕告诫应召而来的牧师，要抛下旧日的教义。圣光、先祖之灵与恶魔契约都不能成为他们的依靠。这份卷轴引领他们开始的修行，根基在于每位牧师自身的意志。卷轴中的教诲要求他们凭借信念生存并施行统治，让信仰成为自我驾驭与掌控的手段。"}},faq={{q="神圣卷轴是什么？",a="神圣卷轴是写给丧钟镇新近复生的被遗忘者牧师的一份召集令。它指引他们前往当地的礼拜堂，向黑暗牧师杜斯滕报到，接受正式训练。",al={"这份卷轴是什么","神圣卷轴用途","神圣卷轴物品"}},{q="是谁发出了神圣卷轴？",a="神圣卷轴上盖着黑暗牧师杜斯滕的私人印章。他在丧钟镇废弃的教堂中训练牧师。",al={"神圣卷轴是谁写的","谁发出了卷轴","杜斯滕卷轴"}},{q="把卷轴交给黑暗牧师杜斯滕时，他会传授什么？",a="黑暗牧师杜斯滕教导亡灵牧师，要摆脱对圣光、先祖之灵和异界力量的依赖。他说，被遗忘者凭借自身的意志存活至今，并敦促年轻的牧师建立对自己的信仰，以便引导并支配他人。",al={"杜斯滕说什么","被遗忘者牧师信条","丧钟镇牧师背景"}}},fp="15,183,26.374.0,25.351.0,28.161.0,29.118.0,66.279.0"}
P.entries["item:hallowed-sigil"] = {n="神圣符记",s="在幽影谷，神圣符记召唤年轻的暗夜精灵新兵前往奥达希尔。珊达送来符记，召他们为Elune效力。",h="在幽影谷，神圣符记召唤年轻的暗夜精灵新兵前往奥达希尔。珊达送来符记，召他们为Elune效力。",kw={"奥达希尔","神圣符记","新兵","卡多雷","牧师","幽影谷","珊达","泰达希尔"},ang={["class:Priest"]="身为暗夜精灵牧师，你收到的神圣符记，是召唤你在艾露恩姐妹会指导下接受正式训练的第一道召令。",["race:NightElf"]="身为卡多雷的虔诚信徒，这枚符记标志着你开始效力，此时联盟的旅人也开始踏上泰达希尔的枝干。"},sec={{t="牧师之道的召唤",b="幽影谷年轻的暗夜精灵牧师会从一位林地信使手中收到神圣符记。这枚信物上刻着神圣的符文，载有奥达希尔的牧师训练师珊达亲自发出的召唤。读过符记后，便前往奥达希尔上方巨大的树洞。在那里，这份召唤将引领学徒加入艾露恩姐妹会，开始为卡多雷效力，而新的旅人也正陆续抵达泰达希尔各处。"}},faq={{q="什么是神圣符记？",a="神圣符记是一枚刻有符文的神圣信物，交给幽影谷年轻的暗夜精灵牧师。符记上的召唤指引新兵去寻找他们的导师珊达。",al={"什么是神圣符记","牧师符记幽影谷"}},{q="是谁送来了神圣符记？",a="一位林地信使受奥达希尔内的牧师训练师珊达所托，送来神圣符记。",al={"谁送来了这枚符记","珊达牧师信物"}},{q="我该把符记带到哪里？",a="将符记带给奥达希尔内的珊达，那里位于泰达希尔的幽影谷中心。读过符记后，将这枚信物交给她，作为你与牧师导师们初次相识的引荐。",al={"神圣符记交到哪里","神圣符记交付"}}},fp="14,133,27.408.0,27.149.0,29.96.0,30.188.0"}
P.entries["item:hallowed-tablet"] = {n="神圣石板",s="在试炼谷，神圣石板召唤年轻的暗矛牧师前去拜见肯杰。石板上的文字引领他们开始学习如何与灵魂沟通。",h="在试炼谷，神圣石板召唤年轻的暗矛牧师前去拜见肯杰。石板上的文字引领他们开始学习如何与灵魂沟通。",kw={"暗矛","杜隆塔尔","高内克","神圣石板","肯杰","巨魔牧师","试炼谷"},ang={["class:Priest"]="这块石板标志着你在杜隆塔尔的正式牧师训练就此开始，也让你与你的导师肯杰建立了联系。",["race:Troll"]="对暗矛而言，成为牧师意味着与灵魂及洛阿密切沟通。石板邀请你踏入这些祖辈传承的通灵传统。"},sec={{t="灵魂的召唤",b="高内克将神圣石板交给一位初入试炼谷、颇有潜力的巨魔牧师。石板上的文字传达了肯杰的亲自邀请，他是大兽穴外的牧师训练师。肯杰解读征兆，聆听灵魂的低语，能感知到具有通灵潜质的年轻暗矛成员何时抵达杜隆塔尔。石板让这位新学徒读完留言后，去向肯杰请教如何驾驭灵魂的权能。"}},faq={{q="神圣石板是什么？",a="高内克在试炼谷将一块刻有文字的石板交给巨魔见习牧师。石板上的留言指引他们去找牧师训练师肯杰。",al={"这是什么物品","神圣石板的故事","石板有什么用"}},{q="是谁送来了石板？",a="肯杰托高内克送来了石板。灵魂预言了一位新学徒的到来，于是，大兽穴外的牧师训练师肯杰便捎来了口信。",al={"是谁写的","是谁给我的","石板作者"}},{q="巨魔牧师为什么要去见肯杰？",a="暗矛牧师与灵魂沟通，并号令灵魂。随着学徒与灵魂的联系日益加深，肯杰会从旁引导，帮助他们赢得灵魂的青睐，学到更强大的能力。",al={"肯杰是做什么的","为什么要见肯杰"}}},fp="15,147,26.486.0,28.144.0,20.144.0,41.186.0"}
P.entries["item:hand-of-dextren-ward"] = {n="迪克斯特·瓦德的手掌",s="夜色镇要求拿出证据，证明迪克斯特·瓦德已在暴风城监狱被处决。那只断手将被送往镇上，悲痛的家属正等着为死去的亲人讨回公道。",h="夜色镇要求拿出证据，证明迪克斯特·瓦德已在暴风城监狱被处决。那只断手将被送往镇上，悲痛的家属正等着为死去的亲人讨回公道。",kw={"夜色镇","迪克斯特·瓦德","暮色森林","埃伯洛克","迪克斯特·瓦德的手掌","贵族","米尔斯迪普","摩本特·费尔","监狱"},ang={["class:Mage"]="身为法师，你知道瓦德并非施法者。他挖出的尸体被用于摩本特·费尔的黑暗法术，因此，瓦德之死打击了那些贩卖死者的人。",["faction:Alliance"]="对联盟而言，瓦德被囚一事暴露了暴风城高高在上的贵族与暮色森林被遗弃的边境居民之间的深刻裂痕。"},sec={{t="亵渎者的代价",b="迪克斯特·瓦德在暮色森林的墓地挖掘尸体，卖给死灵法师摩本特·费尔，被抓获后，埃伯洛克公爵判处他死刑。镇上还没来得及行刑，暴风城便出面干预，将他押往监狱。对夜色镇悲痛的家属而言，瓦德的手掌证明，尽管贵族执意宽纵，这个亵渎者仍已伏法。"},{t="致贵族的口信",b="议员米尔斯迪普索要瓦德断手的要求，也是在挑战王权。暮色森林觉得自己被暴风城的权贵抛弃了，他们拒绝提供军事援助，却在有利可图时宣示权威。在首都最深的地牢里处决一名囚犯并取走他的手掌，就是在告诉贵族：当贵族辜负他们时，夜色镇议会会自行执行法律。"}},faq={{q="迪克斯特·瓦德是谁？",a="迪克斯特·瓦德从夜色镇的墓地挖出尸体，卖给死灵法师摩本特·费尔，随后被抓获。暮色森林判处他斩首，但暴风城当局没有执行死刑，而是将他押往监狱。",al={"迪克斯特·瓦德的故事","迪克斯特·瓦德是谁","瓦德的罪行"}},{q="夜色镇为什么要他的手掌？",a="议员米尔斯迪普要求拿到瓦德的断手，作为他已被刺杀的证据。这让祖先坟墓遭到盗掘的家属得以告慰，也向贵族表明，夜色镇的正义不容推翻。",al={"为什么要断手","为什么砍下瓦德的手","米尔斯迪普的证据"}},{q="在哪里能找到迪克斯特·瓦德的手掌？",a="这只手掌要直接从迪克斯特·瓦德身上取得，他就在暴风城监狱左侧深处的牢房里。他以战士的方式作战，还会发出令人恐惧的怒吼，迫使敌人逃跑。",al={"哪里能找到瓦德","监狱瓦德位置","迪克斯特·瓦德位置"}},{q="暴风城为什么囚禁瓦德，而不处决他？",a="贵族宣称对瓦德拥有司法管辖权，将他关进监狱，不让夜色镇执行死刑。在夜色镇的领袖看来，这是腐败势力的干涉，全然不顾这座边陲小镇的困境。",al={"瓦德为何免于处决","暴风城贵族议会瓦德","瓦德被囚"}}},fx={["48b9455f"]={q="什么是迪克斯特·瓦德的手掌？",a="这是臭名昭著的盗墓者、亵渎死者之人迪克斯特·瓦德被砍下的手。他因将暮色森林墓地里的尸体卖给死灵法师莫本特·费尔而被捕。它是他在暴风城监狱内遭到暗杀的实物证据，也残酷地证明了伊伯洛克勋爵的死刑判决终于得到了执行。",al={"什么是迪克斯特·瓦德的手掌","迪克斯特·瓦德的手掌物品","迪克斯特·瓦德的手"}},b59a9a35={q="迪克斯特·瓦德的手掌从何而来？",a="这是你在暴风城监狱的牢房中亲手从迪克斯特·瓦德身上砍下的手掌。它并非锻造或制作而成，而是作为无可辩驳的正义战利品，送还给暮色森林的议员米尔斯迪普。",al={"迪克斯特·瓦德的手掌从何而来","谁制造了迪克斯特·瓦德的手掌","迪克斯特·瓦德的手掌来源"}}},fp="20,181,16.374.0,23.378.1,21.246.0,33.225.0,40.189.0,57.245.0"}
P.entries["item:handful-of-oats-classic"] = {n="一捧燕麦",s="在西部荒野，法布隆一家的马车坏了，老布兰契需要燕麦充饥。",h="在西部荒野，法布隆一家的马车坏了，老布兰契需要燕麦充饥。",kw={"布兰契","法布隆","谷物","一捧燕麦","燕麦","燕麦袋","西部荒野"},ang={["faction:Alliance"]="作为一名在西部荒野旅行的联盟旅人，你可以在暴风城这片疏于照管的边疆收集燕麦，向法布隆一家这样受困的难民施以小小的援手。"},sec={{t="废墟间的草料",b="西部荒野曾为暴风城王国供应粮食。如今，这里的农场要么杂草丛生，要么落入迪菲亚匪徒和失控的收割傀儡手中。谷物袋和燕麦袋仍散落在谷仓与附属棚屋旁，以及杂草丛生的田野里。旅人和难民的马车若在尘土飞扬的道路上抛锚，便可收集这些遗留的燕麦，喂给疲惫的拉车马。"}},faq={{q="一捧燕麦有什么用途？",a="这些燕麦用来喂养老布兰契，她是法布隆家那匹疲惫的母马。他们的马车在西部荒野的一条路上坏了，她也因此又累又饿。",al={"燕麦有什么用","为什么收集燕麦","一捧燕麦的用途"}},{q="在哪里能找到这些燕麦？",a="燕麦装在袋子里，散落在西部荒野各处废弃的农场中。尤其可以去西南部找找。",al={"哪里能找到燕麦","燕麦袋的位置","如何获取燕麦"}},{q="为什么这些燕麦袋无人看守？",a="迪菲亚潜行者骤然崛起，失控的收割机械在田野中横冲直撞。农民们仓促逃离，把收获的谷物和其他物资留在了田地与谷仓里。",al={"为什么袋子被遗弃","谁留下了燕麦"}}},fx={["67495104"]={q="一捧燕麦是什么？",a="一捧燕麦是从散落在西部荒野各处农庄的粗麻袋中舀出的普通牲畜饲料。在土地丰饶的日子里，这些谷物养活了王国的役马和耕畜。如今，田地已荒废，失控的收割傀儡和强盗盘踞其间，散落的燕麦成了饥饿役畜所剩无几的干净草料。",al={"一捧燕麦是什么","一捧燕麦物品","什么是一捧燕麦"}},a4d08151={q="为什么有人需要一捧燕麦？",a="弗娜·法布隆急需这些燕麦，喂养家中忠实的役马老马布兰契。法布隆一家逃离家园后，马车在路上坏了，布兰契也已筋疲力尽，饥肠辘辘，奄奄一息。这家人仍被困在路边，只能靠几捧有营养的谷物，维系这匹忠诚母马的性命。",al={"谁需要一捧燕麦","为什么收集燕麦","为什么需要一捧燕麦"}}},fp="25,75,22.347.0,35.137.0,30.94.0,37.187.0"}
P.entries["item:handful-of-stardust"] = {n="一份星尘",s="在阿斯特兰纳以南的星尘废墟，灌木上凝着一层淡淡的霜。暗夜精灵医者用这种粉末来缓解高烧。",h="在阿斯特兰纳以南的星尘废墟，灌木上凝着一层淡淡的霜。暗夜精灵医者用这种粉末来缓解高烧。",kw={"灰谷","阿斯特兰纳","奥雷迪尔","皮尔图拉斯","药膏","蕾拉","星尘废墟","星尘"},ang={["profession:Herbalism"]="你用手从闪亮的灌木上采集星尘。这体现了暗夜精灵利用当地稀有植物配制疗伤药物的做法。",["race:NightElf"]="身为守卫灰谷的暗夜精灵，你能看到当地药物与你族古老的废墟及草药传统之间的联系。"},sec={{t="清凉的草药",b="星尘附着在阿斯特兰纳以南的星尘废墟中的灌木上。细腻的粉末如霜般闪亮。徘徊不去的元素之灵盘踞在废墟中，但植物仍在碎石间茁壮生长，吸收着罕见的微光。暗夜精灵医者将这些附着物制成药膏，用来治疗危险而持久的高烧。当普通药膏和月亮井水无法彻底缓解病情时，他们便会求助于星尘。"},{t="父亲的希望",b="皮尔图拉斯·怀特姆恩是阿斯特兰纳一位忧心忡忡的父亲，他听从草药师奥雷迪尔·阔叶的建议，寻找这种粉末。他年幼的女儿蕾拉患上了顽固的魔法疾病，还饱受噩梦折磨。一块受过艾露恩触碰的石头所赐予的祝福起初安抚了她的心神，但她依然高烧不退。皮尔图拉斯寻找星尘，希望制成清凉的药膏，挽救她的生命。"}},faq={{q="在哪里能找到一份星尘？",a="你可以在灰谷中部、阿斯特兰纳以南的星尘废墟，从闪亮的灌木上采集星尘。",al={"星尘位置","哪里能找到星尘","覆盖星尘的灌木"}},{q="这种星尘有什么用途？",a="皮尔图拉斯·怀特姆恩用这种粉末制成舒缓病痛的药膏，治疗女儿蕾拉持续不退的高烧。",al={"星尘的用途","皮尔图拉斯的疗法","星尘的作用"}},{q="星尘灌木周围有什么危险？",a="在生长着这些灌木的星尘废墟，敌对的水元素潜伏在岸边和倒塌的石柱之间。",al={"星尘废墟的敌人","星尘废墟的怪物"}},{q="星尘与女神艾露恩有关吗？",a="暗夜精灵崇敬天体的力量，废墟的名字也与星辰有关，但草药师推荐星尘作为药物，是因为它有着霜一般清凉的特性。",al={"星尘有魔法吗","艾露恩与星尘的联系"}}},fx={["8cce1335"]={q="什么是一份星尘？",a="一份星尘是从灰谷古老的星尘废墟中闪闪发亮的枝叶上采集的、泛着微光的霜状粉末。这种稀有的植物残留物具有舒缓、神奇的冷却特性，因此是制作强效草药膏、治疗顽固且危及生命的高烧的珍贵材料。",al={"什么是一份星尘","星尘是什么","星尘物品背景"}}},fp="19,128,23.366.0,15.368.1,39.106.0,31.160.0,42.126.0,41.119.0"}
P.entries["item:hardened-tortoise-shell"] = {n="硬化龟壳",s="硬化龟壳是取自闪光平原上游荡的闪壳龟的甲壳，异常坚固。沙漠赛道的侏儒赛车手对这些坚韧的有机甲片趋之若鹜，因为它们对性质不稳定、具有腐蚀性的实验燃料有着无与伦比的耐受力。",h="硬化龟壳是取自闪光平原上游荡的闪壳龟的甲壳，异常坚固。沙漠赛道的侏儒赛车手对这些坚韧的有机甲片趋之若鹜，因为它们对性质不稳定、具有腐蚀性的实验燃料有着无与伦比的耐受力。",kw={"硬化龟壳","沙漠赛道","火箭赛车","闪光平原","闪壳","维兹尔·铜栓"},ang={["profession:Engineering"]="用有机甲壳制作高压油箱并不常见，但当侏儒调制的燃料熔穿普通合金管道时，往往就得靠极其坚固的天然材料来顶上了。",["race:Gnome"]="只有侏儒的奇思妙想，才会让他们一看到沙漠里的陆龟，就立刻想到用它来制作轻便又极其坚固的容器，盛装危险的火箭燃料。"},sec={{t="抵御高速险情的天然护甲",b="烈日炙烤的闪光平原上生活着多个品种的闪壳龟，其中包括闪壳钳嘴龟和闪壳钻地龟，它们的甲壳已演化得异常坚韧，足以抵御沙漠盐分的侵蚀和四处游荡的捕食者。在这片盐滩上，普通合金油箱往往承受不住侏儒化学实验的折腾，频频遭到腐蚀或发生破裂。维兹尔·铜栓这样的机械师珍视这些龟壳，并不是为了制作护甲或盾牌，而是看中了这种足够坚韧的有机原料，可以将其改造成临时的耐酸油箱，用来容纳性质不稳定的火箭推进剂。"}},faq={{q="在哪里能找到硬化龟壳？",a="这些龟壳采集自千针石林的闪光平原上、在开阔盐滩间游荡的闪壳龟，具体包括闪壳钳嘴龟、闪壳钻地龟和普通的闪壳龟。",al={"哪里获取龟壳","坚硬龟壳位置","闪壳位置"}},{q="维兹尔·铜栓为什么想要这些龟壳？",a="维兹尔的兄弟正在研制一种威力极强、具有腐蚀性的火箭燃料，甚至可能直接熔穿他们赛车的底盘。维兹尔打算将这些异常坚固的龟壳掏空并加固，用作耐化学腐蚀的油箱。",al={"为什么需要龟壳","维兹尔的龟壳用途","龟壳有什么用"}},{q="普通工坊工具能轻松加工这些龟壳吗？",a="不能。这些甲壳硬得反常，侏儒机械师预计，光是尝试切削、钻孔，把它们加工成油箱，就会弄弯、毁掉整整一工具箱的金属工具。",al={"龟壳是否难以加工","龟壳弄弯工具"}}},fx={cc86b908={q="什么是硬化龟壳？",a="这是从盐碱地上游荡的大型闪壳龟身上取得的、极其坚韧的天然外甲。这种龟壳远比普通野兽皮革或常规护甲坚硬，能够抵御摩擦、盐分和强烈的化学侵蚀。",al={"什么是硬化龟壳","硬化龟壳物品","硬化龟壳"}},["4ed6fee7"]={q="硬化龟壳来自哪里？",a="这些龟壳完全是天然形成的，并非人工制造。它们直接取自千针石林闪光平原上那些在严酷、烈日炙烤的盐碱荒地中繁衍生息的闪壳龟、钳嘴龟和钻地龟。",al={"硬化龟壳的来源","谁制作了硬化龟壳","硬化龟壳来自哪里"}}},fp="23,236,36.355.0,43.181.0,45.238.0,46.156.0"}
P.entries["item:hardened-tumor"] = {n="硬瘤",s="被遗忘者研究人员正在寻找硬瘤，用于研究新的瘟疫。药剂师博拉尔德最早研究了这种增生组织，后来阿鲁高的诅咒使他成了一名没有心智的仆从。",h="被遗忘者研究人员正在寻找硬瘤，用于研究新的瘟疫。药剂师博拉尔德最早研究了这种增生组织，后来阿鲁高的诅咒使他成了一名没有心智的仆从。",kw={"药剂师法拉尼尔","药剂师伦弗利尔","博拉尔德","黎明岛","硬瘤","洛丹米尔湖","鱼人","新的瘟疫","邪鳍"},ang={["race:Undead"]="身为一名Undead，你协助推进大药剂师法拉尼尔对新的瘟疫的研究，为希尔瓦娜斯效力，并帮助被遗忘者对抗活人和亡灵敌人。"},sec={{t="罕见的生物异常",b="洛丹米尔湖沿岸的邪鳍鱼人有时会长出一种罕见的钙化增生组织。药剂师博拉尔德在研究银松森林东部边界的野生生物时，记录了这种异常现象。这种增生组织只出现在湖岸和黎明岛一带的成年个体身上。其成因尚不明确，但这种致密的组织引起了皇家药剂师学会的注意。"},{t="新的瘟疫的原料",b="阿鲁高的诅咒使博拉尔德成了一名没有心智的仆从，之后，他的日记被人从焚木村寻回，送到了瑟伯切尔的药剂师伦弗利尔手中。伦弗利尔看出了博拉尔德研究的潜力，派遣被遗忘者特工去取回一块硬瘤和当地的水生苔藓。大药剂师法拉尼尔掌管着幽暗城的炼金房，在那里寻找能够抵抗腐败或改变生物物质的试剂。他将这种增生组织用于学会正在进行的新的瘟疫研究。"}},faq={{q="什么是硬瘤？",a="硬瘤是一种罕见的异常钙化肿块，形成于洛丹米尔湖周边的邪鳍鱼人体内。药剂师博拉尔德发现了它，它能够抵抗通常的物理性腐坏，并具有不同寻常的生物特性。",al={"这是什么肿瘤","肿瘤背景故事","硬瘤掉落"}},{q="皇家药剂师学会为什么需要它？",a="皇家药剂师学会收集不同寻常的有毒标本和生物标本，用来制造新的瘟疫。大药剂师法拉尼尔认为，这种肿瘤的耐受性和细胞构成使它有望用于瘟疫实验。",al={"药剂师为什么需要肿瘤","死亡的配方肿瘤用途","法拉尼尔肿瘤"}},{q="这些肿瘤在哪里能找到？",a="银松森林的邪鳍鱼人身上带有这些肿瘤，包括洛丹米尔湖东部黎明岛附近，以及安伯米尔东北方村庄沿岸的鱼人。",al={"哪里能找到硬瘤","哪些鱼人掉落肿瘤","肿瘤位置"}},{q="药剂师博拉尔德是谁？",a="药剂师博拉尔德曾是皇家药剂师学会派驻银松森林的一名药剂师。阿鲁高的诅咒使他成了焚木村中一名没有心智的仆从。博拉尔德研究当地的动植物和鱼人变异，并发现了黎明岛苔藓和硬瘤的用途。",al={"博拉尔德是谁","博拉尔德背景故事","博拉尔德日记"}}},fp="14,179,25.353.0,23.477.1,25.212.0,46.223.0,29.175.0,26.287.0"}
P.entries["item:harpy-lieutenant-ring"] = {n="鹰身人首领之戒",s="在无水岭，鹰身人首领之戒是统领鹰身人群的巫翼杀戮者的标志。十字路口的达索克·快刀要求收集这些戒指，作为她们已被击杀的凭证。",h="在无水岭，鹰身人首领之戒是统领鹰身人群的巫翼杀戮者的标志。十字路口的达索克·快刀要求收集这些戒指，作为她们已被击杀的凭证。",kw={"十字路口","达索克·快刀","无水岭","鹰身人首领之戒","贫瘠之地","巫翼","巫翼杀戮者"},ang={["class:Rogue"]="作为潜行者，你或许会青睐达索克·快刀所寻求的精准打击：潜入鹰身人的巢穴，击杀她们的指挥官。",["faction:Horde"]="作为部落的一员，你要面对骚扰杜隆塔尔、莫高雷与北方哨站之间补给线的巫翼鹰身人。瓦解她们的指挥力量，有助于保障部落商队安全穿越贫瘠之地。"},sec={{t="地位的信物",b="巫翼杀戮者指挥着对贫瘠之地部落旅人的袭击。她们的戒指表明了她们在鹰身人群中的首领地位，高于那些作战时缺乏配合的普通掠袭者。在十字路口，达索克·快刀和守卫们需要从被击杀的巫翼杀戮者身上取下的戒指，以确认鹰身人的这部分指挥力量已被瓦解。"}},faq={{q="谁携带这些戒指？",a="巫翼杀戮者佩戴着这些戒指，担任无水岭巫翼鹰身人群中的副官。",al={"谁掉落鹰身人首领之戒","巫翼 杀戮者戒指","哪些鹰身人有戒指"}},{q="在哪里能找到巫翼杀戮者？",a="巫翼杀戮者栖息在无水岭，位于贫瘠之地北部、十字路口的西北方。",al={"巫翼 杀戮者位置","鹰身人副官在哪里","无水岭鹰身人"}},{q="达索克·快刀为什么需要这些戒指？",a="达索克需要这些戒指，作为巫翼杀戮者已被击杀的凭证。她们的死亡会瓦解鹰身人群的部分指挥力量。",al={"为什么收集鹰身人戒指","达索克·快刀戒指"}},{q="普通鹰身人掠袭者也携带这些戒指吗？",a="不会。这些戒指是巫翼杀戮者的标志，普通鹰身人掠袭者则是地位较低的手下。",al={"掠袭者会掉落戒指吗","巫翼掠袭者有戒指吗"}}},fp="21,180,14.331.0,24.88.0,37.94.0,38.129.0,43.96.0"}
P.entries["item:head-of-arugal"] = {n="阿鲁高的头颅",s="在影牙城堡，阿鲁高的头颅取自那位统领狼人的疯狂大法师。瑟伯切尔的被遗忘者想要这颗头颅，以此证明他已被消灭。",h="在影牙城堡，阿鲁高的头颅取自那位统领狼人的疯狂大法师。瑟伯切尔的被遗忘者想要这颗头颅，以此证明他已被消灭。",kw={"阿鲁高","除掉阿鲁高","达拉尔·道恩维沃尔","阿鲁高的头颅","瑟伯切尔","影牙城堡","银松森林"},ang={["class:Mage"]="身为法师，你将这位前肯瑞托大法师被斩下的头颅视作警示：绝望之下的召唤，即使对天赋出众的施法者，也可能招致疯狂与毁灭。",["race:Undead"]="身为被遗忘者，你协助铲除了银松森林南部边缘一名危险的巫师，并为黑暗女王巩固了这片土地。"},sec={{t="疯狂大法师的战利品",b="大法师阿鲁高在银松森林的影牙城堡中统领着狼人。瑟伯切尔的达拉尔·道恩维沃尔下令取下他的头颅。被遗忘者认为，阿鲁高的覆灭能打击那些妨碍希尔瓦娜斯女士掌控银松森林的野兽。将头颅交给道恩维沃尔，便能证明大法师的巫术已从这片土地上被铲除。"}},faq={{q="谁想要阿鲁高的头颅？",a="银松森林瑟伯切尔的使者达拉尔·道恩维沃尔想要这颗头颅，这是名为除掉阿鲁高的命令中的一项要求。",al={"谁需要阿鲁高的头颅","阿鲁高的头颅交付","谁收取阿鲁高的头颅"}},{q="在哪里可以取得阿鲁高的头颅？",a="阿鲁高的头颅取自大法师阿鲁高，他居住在影牙城堡的最高处，俯瞰着焚木村与银松森林的林地。",al={"如何取得阿鲁高的头颅","阿鲁高的头颅掉落","阿鲁高的头颅在哪里"}},{q="被遗忘者为何想要杀死阿鲁高？",a="被遗忘者想要杀死阿鲁高，是因为他和他的狼人群阻碍他们将银松森林建成希尔瓦娜斯女士与幽暗城的安全据点。",al={"为何杀死阿鲁高","被遗忘者杀死阿鲁高的原因","达拉尔为何想要阿鲁高死"}},{q="交出头颅后会发生什么？",a="收到头颅后，达拉尔·道恩维沃尔发誓要彻底清除阿鲁高法术的残余，并宣告银松森林已摆脱这位疯狂巫师的控制。",al={"阿鲁高死后","除掉阿鲁高的结果"}}},fx={c9f64370={q="什么是阿鲁高的头颅？",a="阿鲁高的头颅是大法师阿鲁高被砍下的头颅。他曾是达拉然的法师，后来陷入疯狂，并将狼人释放到银松森林。头颅取自影牙城堡，是这名疯狂的巫师终于被杀、黑暗魔法已被粉碎的确凿实物证据。",al={"什么是阿鲁高的头颅","阿鲁高的头颅物品","阿鲁高的头颅"}},["10305f38"]={q="阿鲁高的头颅来自哪里？",a="这个头颅是从影牙城堡高处的大法师阿鲁高身上取得的。攻入这座被诅咒的城堡并在战斗中击败这名疯狂的大法师后，你将他杀死并取下头颅，以确认他的死亡。",al={"在哪里能得到阿鲁高的头颅","谁会掉落阿鲁高的头颅","阿鲁高的头颅来源"}}},fp="14,152,26.345.0,29.128.0,39.144.0,37.160.0,41.147.1"}
P.entries["item:head-of-bazil-thredd"] = {n="巴基尔·斯瑞德的头颅",s="典狱官塞尔沃特要求拿出监狱暴动已被镇压的证据。巴基尔·斯瑞德被斩下的头颅将证明，叛乱首领已死，迪菲亚潜行者对暴风城监狱的控制也已终结。",h="典狱官塞尔沃特要求拿出监狱暴动已被镇压的证据。巴基尔·斯瑞德被斩下的头颅将证明，叛乱首领已死，迪菲亚潜行者对暴风城监狱的控制也已终结。",kw={"巴基尔·斯瑞德","迪菲亚潜行者","巴基尔·斯瑞德的头颅","监狱","监狱暴动","典狱官塞尔沃特"},ang={["faction:Alliance"]="对联盟而言，斯瑞德被斩下的头颅平息了首都眼下的恐慌，也证明王室的正义能够触及叛乱中的监狱。"},sec={{t="叛乱终结的证据",b="巴基尔·斯瑞德在暴风城地下的监狱中领导了暴动。他在忠于自己的迪菲亚潜行者囚犯协助下，从牢区内指挥骚乱。典狱官塞尔沃特不信任外来者，维持秩序也举步维艰。他要求拿到斯瑞德的头颅，以证明这名主谋已经伏诛，同时考验冒险者对暴风城的忠诚。"}},faq={{q="谁想要巴基尔·斯瑞德的头颅？",a="监狱入口处的典狱官塞尔沃特要求拿到巴基尔·斯瑞德的头颅。他要先看到主谋已死的证据，才肯透露自己掌握的斯瑞德同谋的消息。",al={"谁需要斯瑞德的头颅","斯瑞德的头颅交到哪里","斯瑞德的头颅任务给予者"}},{q="巴基尔·斯瑞德是谁？",a="巴基尔·斯瑞德曾是迪菲亚潜行者的高层成员，被关押在暴风城地下。囚犯暴动后，他接掌指挥，从东部牢区协调这场暴动。",al={"巴基尔·斯瑞德是谁","斯瑞德的背景故事","巴基尔做了什么"}},{q="在哪里能找到巴基尔·斯瑞德？",a="巴基尔·斯瑞德位于监狱东翼，在牢区尽头中央的一间牢房里。忠于他的迪菲亚潜行者囚犯守卫着牢房。",al={"斯瑞德在哪里","斯瑞德的位置","如何找到巴基尔·斯瑞德"}}},fx={["4fd859a6"]={q="什么是巴基尔·斯瑞德的头颅？",a="这是巴基尔·斯瑞德被砍下的头颅。他是在监狱深处策划叛乱的囚犯。对典狱官塞尔沃特而言，呈上这件阴森的战利品，是证明监狱暴动首领已被彻底铲除的确凿实物证据。",al={"什么是巴基尔·斯瑞德的头颅","巴基尔·斯瑞德的头颅物品","巴基尔·斯瑞德的头颅"}},fe91a8a0={q="巴基尔·斯瑞德的头颅来自哪里？",a="你在暴风城监狱的囚室中与巴基尔·斯瑞德交锋并将他杀死后，可直接从他身上取得头颅。他在那里指挥暴动，并由凶悍的守卫保护。",al={"在哪里能得到巴基尔·斯瑞德的头颅","如何获得巴基尔·斯瑞德的头颅","巴基尔·斯瑞德头颅的来源"}}},fp="20,202,22.327.0,35.171.0,21.197.0,28.143.0"}
P.entries["item:head-of-deepfury"] = {n="卡姆·深怒的头颅",s="在暴风城监狱，卡姆·深怒被斩下的头颅标志着一名黑铁阴谋者的末路。他在监狱暴动中丧命，让丹莫德的矮人守军得以雪恨。",h="在暴风城监狱，卡姆·深怒被斩下的头颅标志着一名黑铁阴谋者的末路。他在监狱暴动中丧命，让丹莫德的矮人守军得以雪恨。",kw={"深怒","丹莫德","卡姆·深怒的头颅","卡姆·深怒","长须","莫特雷·加玛森","监狱","萨多尔大桥"},ang={["faction:Alliance"]="索取深怒头颅的要求揭示了联盟内部的摩擦：暴风城的人类当局主张在法律处置上保持谨慎，而铁炉堡巡山人则要求严厉惩处。",["race:Dwarf"]="对铁炉堡矮人而言，取下深怒的头颅，便是为黑铁在萨多尔大桥的背叛行径雪恨。"},sec={{t="阴谋者的报应",b="卡姆·深怒因政治原因被关押在暴风城监狱，人类的外交斡旋使他免于立即处决。罗戈查明，深怒策划了对萨多尔大桥的袭击，导致麦格尼国王麾下的士兵和布莱德·长须的亲人丧命。驻守丹莫德的铁炉堡巡山人无法接受他继续被关押。莫特雷·加玛森必须坚守岗位，于是派遣联盟勇士进入暴动中的监狱，取下深怒的头颅，为矮人复仇。"}},faq={{q="卡姆·深怒是谁？",a="卡姆·深怒是一名黑铁矮人，曾参与策划破坏萨多尔大桥的行动，这座桥连接着湿地与阿拉希高地。他的阴谋夺去了多名矮人守军的性命，其中包括布莱德·长须的兄弟。",al={"卡姆·深怒背景故事","深怒是谁","卡姆·深怒过往"}},{q="卡姆·深怒为何被关进监狱，而没有被处决？",a="暴风城当局出于政治原因，留下了深怒的性命。铁炉堡巡山人对这种克制愤慨不已，要求处死他。",al={"深怒为何被囚禁","为何关进监狱"}},{q="谁想要卡姆·深怒的头颅？",a="驻守在湿地北部丹莫德的莫特雷·加玛森想要这颗头颅。荣誉要求他留在布莱德·长须身旁坚守岗位，因此他派人去完成自己无法亲自做的事。",al={"谁取深怒的头颅","怒火深渊交任务"}},{q="带回头颅能达成什么？",a="将深怒被斩下的头颅带回丹莫德，能让痛失亲人的矮人家庭得以雪恨。这既为布莱德·长须遇害的兄弟报了仇，也表明人类的政治手腕无法掩盖针对铁炉堡的罪行。",al={"为何带回深怒的头颅","怒火深渊结果"}}},fx={["42407f6f"]={q="什么是卡姆·深怒的头颅？",a="这是卡姆·深怒被砍下的头颅。他是一名被关押在暴风城监狱深处的黑铁矮人。你带回它，作为确凿无疑的实物证据，证明萨多尔大桥惨烈袭击的幕后阴谋者终于受到了惩罚。",al={"卡姆·深怒的头颅","什么是卡姆·深怒的头颅"}},ff6e9a29={q="卡姆·深怒的头颅来自哪里？",a="这个头颅是从暴风城地下监狱牢房中的卡姆·深怒身上直接取得的。虽然人类当局只是将他关押起来，并未处决他，但你必须在牢房中将他杀死才能取回头颅。",al={"在哪里能得到卡姆·深怒的头颅","谁会掉落卡姆·深怒的头颅","卡姆·深怒头颅的来源"}}},fp="16,185,23.478.0,21.230.0,57.148.0,31.183.0,44.228.0"}
P.entries["item:head-of-gath-ilzogg"] = {n="加塞尔佐格的头颅",s="取得加塞尔佐格的首级，便能证明这位黑石军阀已被击杀。他的倒下瓦解了围攻石堡要塞的指挥力量，也让危在旦夕的湖畔镇得以喘息。",h="取得加塞尔佐格的首级，便能证明这位黑石军阀已被击杀。他的倒下瓦解了围攻石堡要塞的指挥力量，也让危在旦夕的湖畔镇得以喘息。",kw={"黑石","加塞尔佐格","湖畔镇","所罗门镇长","赤脊山","石堡","石堡要塞"},ang={["faction:Alliance"]="王都因内部纷争而无暇他顾，联盟志愿者必须亲自保卫赤脊山，击杀黑石的首领。",["race:Human"]="对暴风城的人民而言，击杀加塞尔佐格，是为惨遭屠戮的无辜定居者复仇，也是洗刷石堡要塞沦陷的耻辱。"},sec={{t="遭到悬赏的军阀",b="加塞尔佐格率领黑石部队攻占了石堡要塞，赶走了守军，让山谷不断遭受袭击。湖畔镇濒临毁灭，暴风城却几乎没有派来任何军事援助。所罗门镇长悬赏征求这位军阀的首级。加塞尔佐格在要塞戒备森严的上层被击杀，取得他的首级便瓦解了当地黑石的指挥力量。对湖畔镇而言，这是为王国夺回要塞的第一步。"}},faq={{q="加塞尔佐格是谁？",a="加塞尔佐格是一位强大的黑石兽人军阀，他率军攻占了石堡要塞，并指挥部队袭击赤脊山的定居点，将湖畔镇逼到了崩溃的边缘。",al={"加塞尔佐格是谁","加塞尔佐格背景故事","石堡首领"}},{q="取得首级后要送到哪里？",a="首级要送到湖畔镇的城镇大厅，交给所罗门镇长，以此证明镇上通缉告示板发布的悬赏已经完成。",al={"谁要首级","交付加塞尔佐格的首级","所罗门镇长的悬赏"}},{q="加塞尔佐格的死对湖畔镇意味着什么？",a="加塞尔佐格的死，让黑石入侵者失去了他们在赤脊山的首席战术指挥官。许多黑石兽人仍盘踞在石堡各处，但指挥体系的瓦解让当地守军有机会守住这片地区。",al={"湖畔镇是否获救","击杀加塞尔佐格的意义"}},{q="加塞尔佐格在哪里？",a="加塞尔佐格占据了石堡要塞的高层，与他的贴身护卫和副官一同驻守在这座被攻占的堡垒深处。",al={"加塞尔佐格在哪里","石堡要塞位置"}}},fx={["0b5a65b1"]={q="什么是加塞尔佐格的头颅？",a="这是加塞尔佐格被砍下的头颅。他是黑石兽人督军，曾指挥对石堡要塞的袭击，并组织威胁湖畔镇的劫掠。砍下他的头颅，便能确凿证明在赤脊山策划黑石兽人攻势的残暴首领终于被铲除。",al={"什么是加塞尔佐格的头颅","加塞尔佐格的头颅"}},ca6d6fe9={q="加塞尔佐格的头颅来自哪里？",a="加塞尔佐格在石堡要塞高处被杀后，你可直接从他身上取得头颅。这名督军盘踞在自己征服的要塞中，谋划着进一步侵害赤脊山居民，直到一名冒险者勇闯他的据点，将头颅作为战利品带走。",al={"加塞尔佐格的头颅来自哪里","谁取走了加塞尔佐格的头颅","加塞尔佐格头颅的来源"}},a1bebb0c={q="所罗门镇长为什么想要加塞尔佐格的头颅？",a="所罗门镇长悬赏缉拿加塞尔佐格，并要求提交其死亡的实物证据。加塞尔佐格屠杀无辜的人类，还攻占了石堡要塞。看到他的头颅被送来，湖畔镇的领袖便能确信眼前的威胁已被消除，也能为受害者讨回公道，并重燃夺回要塞的希望。",al={"所罗门为什么想要加塞尔佐格的头颅","为什么要带回加塞尔佐格的头颅","加塞尔佐格头颅的悬赏"}}},fp="19,133,18.453.0,20.185.0,39.133.0,49.230.0,28.152.0"}
P.entries["item:head-of-grimson"] = {n="格瑞姆森的头颅",s="在埃利姆矿洞，白毛狼人格瑞姆森被砍下的头颅证明被遗忘者已掌控这里的财富。达拉尔·道恩维沃尔在瑟伯切尔接收这份战利品，矿洞中的矿产则可用于支援瓦里玛萨斯的军事行动。",h="在埃利姆矿洞，白毛狼人格瑞姆森被砍下的头颅证明被遗忘者已掌控这里的财富。达拉尔·道恩维沃尔在瑟伯切尔接收这份战利品，矿洞中的矿产则可用于支援瓦里玛萨斯的军事行动。",kw={"阿鲁高","达拉尔·道恩维沃尔","埃利姆矿洞","白毛狼人格瑞姆森","格瑞姆森的头颅","瑟伯切尔","银松森林","瓦里玛萨斯"},ang={["profession:Mining"]="埃利姆矿洞是银松森林最重要的矿区之一。监工已被除去，原矿可供部落的补给线使用。",["race:Undead"]="身为被遗忘者，夺取矿洞既能落实幽暗城最高指挥部的计划，也能证明你决心从疯狂的残部手中夺回洛丹伦的重要基础设施。"},sec={{t="夺取埃利姆矿洞",b="被称为亡灵哨兵的被遗忘者斥候发现，东南方的群山中正酝酿着战略威胁。大法师阿鲁高的暗影魔法腐化了埃利姆矿洞的工人，也让矿洞的监工白毛狼人格瑞姆森陷入疯狂。达拉尔·道恩维沃尔从瑟伯切尔派出勇士，命他们杀死格瑞姆森，并带回他被砍下的头颅。这份战利品证实矿洞已摆脱失控魔法的影响，地下的财富也归瓦里玛萨斯的部队所有。"},{t="献给恐惧魔王的战利品",b="格瑞姆森的头颅标志着他对埃利姆矿洞的统治已经终结。监工已被除去，被遗忘者可以开采这里丰富的矿脉，将矿石制成武器和护甲。这些物资支撑着他们在银松森林及洛丹伦邻近地区的推进。"}},faq={{q="白毛狼人格瑞姆森是谁？",a="白毛狼人格瑞姆森曾是埃利姆矿洞的监工，矿洞位于银松森林东南方的群山中。阿鲁高不断蔓延的暗影魔法腐化了他和其他矿工，直到被遗忘者出手干预。",al={"格瑞姆森 是谁","白毛狼人格瑞姆森 传说","格瑞姆森 背景"}},{q="达拉尔·道恩维沃尔为什么要格瑞姆森的头颅？",a="达拉尔·道恩维沃尔要用格瑞姆森的头颅证明，这名遭到腐化的监工已被除掉。瓦里玛萨斯需要矿洞的丰富矿产来支持被遗忘者的战事，而格瑞姆森的死打破了洞内被腐化矿工的抵抗。",al={"达拉尔为何要头颅","格瑞姆森的头颅用途","为何取头颅"}},{q="埃利姆矿洞在哪里？",a="埃利姆矿洞位于银松森林瑟伯切尔东南方的群山中。被遗忘者正与被阿鲁高魔法腐化的残部争夺这里的矿产。",al={"埃利姆矿洞在哪","格瑞姆森 位置","银松森林矿洞位置"}},{q="瓦里玛萨斯在这项任务中扮演什么角色？",a="瓦里玛萨斯在幽暗城指挥被遗忘者在洛丹伦各地扩张。矿洞的资源为他在银松森林的战事提供原材料，从而服务于他的战略目标。",al={"瓦里玛萨斯的作用","瓦里玛萨斯为何要矿洞","瓦里玛萨斯 银松森林"}}},fp="15,198,27.409.0,26.275.1,25.184.0,46.226.0,36.158.0,45.173.0"}
P.entries["item:head-of-kelris"] = {n="克尔里斯的头颅",s="银色黎明的密探正在寻找克尔里斯被斩下的头颅，以确认他已死去，献祭也已终结。",h="银色黎明的密探正在寻找克尔里斯被斩下的头颅，以确认他已死去，献祭也已终结。",kw={"阿库麦尔","银色黎明","巴珊娜·符文图腾","黑暗深渊","黑暗深渊的恶行","克尔里斯的头颅","塞尔高姆","梦游者克尔里斯"},ang={["faction:Alliance"]="身为联盟的勇士，你将克尔里斯的头颅带给达纳苏斯的哨兵塞尔高姆，为一座供奉Elune的古老暗夜精灵神殿遭到亵渎而复仇。",["faction:Horde"]="身为部落的冒险者，你将头颅呈交给雷霆崖的巴珊娜·符文图腾，赢得塞纳里奥议会的信任，并证明你致力于净化卡利姆多的腐化。"},sec={{t="毁灭的战利品",b="在黑暗深渊，梦游者克尔里斯主持向阿库麦尔献祭的仪式，后者是上古之神麾下的怪物仆从。斩下他的头颅，标志着他对洞窟中暮光之锤教徒及其娜迦盟友的统治宣告终结。必须将这颗头颅带回地表，让领袖们得知他的血腥仪式已经结束。"},{t="交予黎明的明证",b="银色黎明曾以为克尔里斯早已死去或失踪，直到数月后，他的势力随着侵蚀卡利姆多的暗影再次出现。将他的头颅带给达纳苏斯或雷霆崖的密探，便能结清悬而未决的赏金，并证实他将世界拖入原始混沌的企图已被挫败。"}},faq={{q="梦游者克尔里斯是谁？",a="梦游者克尔里斯曾领导黑暗深渊中的暮光之锤教派。他与娜迦结盟，将无辜者献祭给上古之神的多头蛇仆从阿库麦尔，企图获取黑暗力量，唤回远古的混沌。",al={"克尔里斯是谁","克尔里斯的故事","梦游者克尔里斯"}},{q="谁想要克尔里斯的头颅？",a="联盟的勇士将头颅交给达纳苏斯的哨兵塞尔高姆。部落的冒险者则将它带给雷霆崖长者高地的巴珊娜·符文图腾。塞尔高姆为银色黎明效力，而巴珊娜隶属于塞纳里奥议会。",al={"谁收取克尔里斯的头颅","克尔里斯的头颅交付","克尔里斯的头颅交给谁"}},{q="银色黎明为何关注克尔里斯？",a="银色黎明追查着威胁艾泽拉斯的势力。克尔里斯长期躲避着他们的追踪，而他对上古之神的崇拜和献祭无辜者的行径，威胁着卡利姆多的平衡。",al={"银色黎明为何关注克尔里斯","银色黎明 黑暗深渊"}},{q="从哪里取得这颗头颅？",a="这颗头颅取自梦游者克尔里斯的尸体，就在黑暗深渊内他的密室中，位于灰谷海岸的佐拉姆海岸下方。",al={"哪里获取克尔里斯的头颅","克尔里斯的头颅位置"}}},fx={c257c517={q="什么是克尔里斯的头颅？",a="这是暮光领主克尔里斯被砍下的头颅。他是深入黑暗深渊废墟扎根的暮光之锤教徒的首领。这件战利品是令人毛骨悚然且确凿无疑的证据，证明沉没神庙中的邪恶主宰已被杀死，他的仪式也已终结。",al={"克尔里斯的头颅","什么是克尔里斯的头颅","克尔里斯的头颅物品"}},["0e645b89"]={q="克尔里斯的头颅来自哪里？",a="这个头颅是从佐拉姆海岸附近黑暗深渊深处的暮光领主克尔里斯身上直接取得的。你必须杀出一条血路，突破他狂热的教徒和畸变的仆从，在他的内殿中将这位暮光领主杀死，然后才能取走头颅。",al={"在哪里能得到克尔里斯的头颅","克尔里斯头颅的来源","如何获得克尔里斯的头颅"}}},fp="14,116,16.305.0,18.291.0,29.202.0,29.236.0,43.156.0,27.139.0"}
P.entries["item:head-of-targorr"] = {n="塔格尔的头颅",s="在暴风城监狱里，可怕的塔格尔等待着行刑，但暴风城的贵族阻止了处决。这个被俘的兽人曾是加塞尔佐格在赤脊山的首席刽子手，如今湖畔镇的卫兵伯尔顿要求拿到他已死的证据。",h="在暴风城监狱里，可怕的塔格尔等待着行刑，但暴风城的贵族阻止了处决。这个被俘的兽人曾是加塞尔佐格在赤脊山的首席刽子手，如今湖畔镇的卫兵伯尔顿要求拿到他已死的证据。",kw={"黑石","加塞尔佐格","卫兵伯尔顿","塔格尔的头颅","湖畔镇","赤脊山","监狱","塔格尔","可怕的塔格尔"},ang={["faction:Alliance"]="对于保卫赤脊山的联盟勇士而言，塔格尔的死能为惨遭屠杀的湖畔镇守军复仇，也能绕过暴风城贵族腐败的官僚程序。",["race:Human"]="身为人类，你或许和士兵、城镇卫兵一样痛恨塔格尔，因为他曾在黑石的攻势期间折磨被俘的王国士兵。"},sec={{t="暂缓的处决",b="可怕的塔格尔是黑石氏族军阀加塞尔佐格手下残暴的刽子手，在赤脊山一带臭名昭著。他折磨并屠杀了暴风王国的守军，后来被捕，关进暴风城监狱并被判处死刑。暴风城的贵族出面干预，莫名地暂缓了行刑。伯尔顿等卫兵怀疑，王都中有人暗中作梗，贪赃枉法。"},{t="边境的正义",b="卫兵伯尔顿担心塔格尔会沦为政治棋子，或设法越狱，于是雇用一位外来的勇士进入动荡的监狱，完成法庭迟迟未能执行的处决。取下塔格尔的头颅，便能绕过停滞不前的司法程序，也能让悲痛的家属和饱受围困的湖畔镇守军得到慰藉，他们都曾饱受这名刽子手的刀锋之苦。"}},faq={{q="可怕的塔格尔是谁？",a="可怕的塔格尔是赤脊山一带黑石氏族中臭名昭著的兽人刽子手。他效命于军阀加塞尔佐格，折磨并处决被俘的暴风城士兵和守军。",al={"塔格尔","塔格尔背景故事","塔格尔是谁"}},{q="为什么塔格尔在监狱里仍然活着？",a="暴风城的贵族通过官僚程序干预，莫名地叫停了对塔格尔的处决。湖畔镇的卫兵怀疑其中存在政治阴谋与腐败，担心有人留着他充当谈判筹码。",al={"为何不处决塔格尔","塔格尔暂缓处决","监狱审判"}},{q="谁想要塔格尔的头颅？",a="驻守在湖畔镇旅店外的卫兵伯尔顿想要塔格尔被砍下的头颅。伯尔顿亲眼见过他在赤脊山造成的惨状，因此想要得到证据，确保这个刽子手永远不会重获自由。",al={"谁收取塔格尔的头颅","卫兵伯尔顿","交付塔格尔的头颅"}},{q="在哪里能找到塔格尔？",a="可怕的塔格尔被关押在暴风城监狱的中央牢区，与暴动的囚犯一起被锁在铁栏之后。",al={"塔格尔位置","寻找塔格尔","监狱里的位置"}}},fx={["1b8c229f"]={q="塔格尔的头颅是什么？",a="这是可怕的塔格尔被砍下的头颅。他是臭名昭著的刽子手头目，曾效力于黑石氏族军阀加塞尔佐格。塔格尔因折磨并处决王国的英勇守卫而被捕，关押在暴风城监狱，等待死刑。",al={"塔格尔的头颅是什么","塔格尔的头颅信息","塔格尔的头颅描述"}},["29061798"]={q="塔格尔的头颅来自哪里？",a="这颗头颅来自可怕的塔格尔本人，他被关押在暴风城监狱深处。一位暴风城贵族叫停了原定的处决后，卫兵伯尔顿便派一名冒险者自行了断此事，潜入牢房砍下这个残暴兽人的头颅。",al={"塔格尔的头颅来自哪里","谁掉落塔格尔的头颅","塔格尔头颅的来源"}}},fp="15,187,19.344.0,16.356.0,26.183.0,43.205.0,25.202.0,23.118.0"}
P.entries["item:head-of-vancleef"] = {n="范克里夫的头颅",s="在哨兵岭，范克里夫被斩下的头颅证明，迪菲亚潜行者的首领已经倒下。这颗从死亡矿井深处带出的头颅，为人民军带来了来之不易的复仇。",h="在哨兵岭，范克里夫被斩下的头颅证明，迪菲亚潜行者的首领已经倒下。这颗从死亡矿井深处带出的头颅，为人民军带来了来之不易的复仇。",kw={"死亡矿井","艾德温·范克里夫","格里安·斯托曼","范克里夫的头颅","人民军","哨兵岭","西部荒野"},ang={["class:Rogue"]="艾德温·范克里夫是人类历史上最致命的盗贼大师之一。他的死，终结了一段在暗影与破坏中无人能及的生涯。",["faction:Alliance"]="范克里夫的头颅为人民军带来了一场令人一吐积愤的胜利，同时也揭露了一个令人不安的事实：在西部荒野最黑暗的时刻，暴风城贵族议会始终缺席。"},sec={{t="首领倒下的明证",b="西部荒野的定居者需要证据，证明威胁已经消除。数月来，艾德温·范克里夫一直在死亡矿井最深处的密室中，指挥迪菲亚潜行者散播恐怖，身边有武装匪徒、地精工程师和一艘庞大的战争巨舰守卫。人民军的领袖格里安·斯托曼要求拿出实物证据，才肯宣布这片乡野已经安全。范克里夫被斩下的头颅重见天日，让疲惫不堪的守卫者确信，那个一手造成他们家园毁灭的人，再也无法威胁西部荒野。"},{t="沉重的胜利",b="范克里夫的死回应了斯托曼为西部荒野福祉发出的号召，但他的头颅也令人心情沉重。他曾是备受敬重的建筑大师，在第一次兽人战争之后重建了暴风城。背叛与拖欠的酬劳迫使他和石匠行会沦为反叛的亡命之徒。他的死标志着当地民兵作战的结束，也暴露了王国无力平息内部动乱的事实。伸张公义的重任，最终落在了自愿参战的农夫与外来的冒险者肩上。"}},faq={{q="谁需要范克里夫的头颅？",a="格里安·斯托曼是西部荒野哨兵岭的人民军队长，他需要这颗头颅，为对抗迪菲亚潜行者的漫长战事画上句号。",al={"交给谁","谁收范克里夫的头颅","范克里夫的头颅交到哪里"}},{q="格里安·斯托曼为什么一定要他的头颅？",a="迪菲亚潜行者控制西部荒野太久了，仅凭范克里夫的死讯，无法让人们信服。斯托曼需要实物证据，来安抚饱受侵扰的农夫，并证明民兵的抗争没有白费。",al={"为什么取他的头颅","为什么要范克里夫的头颅"}},{q="这颗头颅从哪里取得？",a="这颗头颅取自艾德温·范克里夫，他藏身于自己的秘密铁甲战舰上，就在西部荒野西南部月溪镇地下的死亡矿井最深处。",al={"哪里获取范克里夫的头颅","如何获取范克里夫的头颅"}},{q="取下范克里夫的头颅，就能终结迪菲亚潜行者吗？",a="斯托曼认为，范克里夫的死意味着兄弟会开始走向覆灭。分裂出去的团伙、四处流窜的匪徒和同情者，仍散布在西部荒野、艾尔文森林以及更远的地方。",al={"迪菲亚被消灭了吗","迪菲亚后来怎样了"}}},fx={["4a1d52aa"]={q="范克里夫的头颅是什么？",a="范克里夫的头颅是艾德温·范克里夫被砍下的头颅。他是藏身于死亡矿井深处的迪菲亚潜行者首脑。这颗头颅是血腥而确凿的证据，证明这场叛乱的领袖终于被击败。",al={"范克里夫的头颅是什么","范克里夫的头颅物品","艾德温·范克里夫的头颅"}}},fp="16,176,26.514.0,14.475.1,31.167.0,56.249.0,27.149.0,55.192.0"}
P.entries["item:heart-of-isha-awak"] = {n="依沙瓦克的心脏",s="猎人们在棘齿城以南的商旅海岸寻找依沙瓦克的心脏。玛伦·星眼想要这颗心脏，以证明海中的巨兽已被击败。",h="猎人们在棘齿城以南的商旅海岸寻找依沙瓦克的心脏。玛伦·星眼想要这颗心脏，以证明海中的巨兽已被击败。",kw={"海中的巨兽","依沙瓦克的心脏","依沙瓦克","玛伦·星眼","商旅海岸","棘齿城","贫瘠之地"},ang={["class:Hunter"]="身为猎人，你将在商旅海岸的波涛之下追踪并征服海中的巨兽，面对勇气的终极考验。",["race:Tauren"]="身为牛头人猎人，你在长者玛伦·星眼的指引下追猎依沙瓦克，借此与自然界最凶猛的掠食者进行灵魂的交流。"},sec={{t="海中的巨兽的战利品",b="依沙瓦克在棘齿城以南、商旅海岸外的海中游荡。水手和沿海居民对这头被称为海中的巨兽的庞大蛇颈龙既敬畏又恐惧。它已杀死许多侵入这片海岸的人类。牛头人秘术师玛伦·星眼认为，它是一头值得尊敬的掠食者，而非只知肆虐的祸害。她相信，它凶猛的灵魂栖居在心脏之中。玛伦嘱咐勇敢的猎人潜入波涛，在依沙瓦克自己的领地击败它，取走它的心脏，既作为战利品，也作为灵魂的祭品。"}},faq={{q="依沙瓦克的心脏是什么？",a="依沙瓦克的心脏来自棘齿城以南水域中游荡的巨型蛇颈龙。猎人们取走它，向玛伦·星眼证明自己已战胜海中的巨兽。",al={"依沙瓦克的心脏","这颗心脏是什么"}},{q="谁想要依沙瓦克的心脏？",a="玛伦·星眼是一位在棘齿城以南的商旅海岸扎营的牛头人先知，她希望猎人们取回这颗心脏。她想借此向这头野兽的力量致敬，并吸收它的灵魂。",al={"谁收这颗心脏","心脏交给谁","玛伦·星眼"}},{q="依沙瓦克在哪里？",a="依沙瓦克栖居在贫瘠之地东部、棘齿城以南的商旅海岸外的海中。",al={"依沙瓦克的位置","依沙瓦克在哪","哪里能找到依沙瓦克"}},{q="玛伦·星眼为什么想要这颗心脏？",a="玛伦·星眼认为，依沙瓦克是一位值得尊敬的猎手，也是一名可敬的对手。猎人杀死这头野兽、握住它的心脏，便能将这头海兽的灵魂纳入自身。",al={"为什么要杀依沙瓦克","玛伦为什么要心脏"}}},fp="18,147,23.489.0,31.174.0,33.189.0,25.94.0,39.171.0"}
P.entries["item:heartswood"] = {n="同心树",s="同心树取自灰谷西北部一棵扎根于奥迪拉兰废墟中的树。两位远古恋人殒命之处长出了这棵树，术士召唤魅魔时，它的木材能将魅魔引来。",h="同心树取自灰谷西北部一棵扎根于奥迪拉兰废墟中的树。两位远古恋人殒命之处长出了这棵树，术士召唤魅魔时，它的木材能将魅魔引来。",kw={"安娜瑟拉","灰谷","黑暗缚灵者加科因","同心树","拉瑟里安","奥迪拉兰","魅魔"},ang={["class:Warlock"]="对联盟术士而言，取得同心树是黑暗缚灵者加科因指引他们完成的一项成长试炼。木材的共鸣提供了情感诱饵，使他们能够强迫魅魔屈服，将其束缚为仆从。",["race:NightElf"]="身为暗夜精灵，你或许会将这棵树视为纪念War of the Ancients阵亡者的神圣丰碑。术士和邪教徒砍取它的木材，是对逝去先祖的亵渎。"},sec={{t="忠贞之爱的丰碑",b="在灰谷西北部的奥迪拉兰废墟中，一棵奇异的树在精灵留下的石块间扎下了根。传说数千年前，一对名叫安娜瑟拉和拉瑟里安的恋人在上古之战期间并肩倒在了这里。同心树从他们殒命之处的泥土中生长出来。即使如今，从树上砍下的木材仍承载着他们忠贞相爱的记忆。研究情感与灵魂羁绊的人对此颇感好奇。"},{t="奴役的工具",b="同心树会引起魅魔的注意，这些恶魔会被激情、渴望与情感利用所吸引。在暴风城向黑暗缚灵者加科因求教的人类和侏儒术士，会寻找这种稀有木材，制成仪式所用的诱饵。木材与恋人牺牲之间的共鸣，能诱使魅魔穿过虚空，进入召唤法阵。在那里，施术者便能束缚她，迫使她服从自己的意志。"}},faq={{q="同心树是什么？",a="同心树是一种木材，取自灰谷奥迪拉兰废墟中的一棵树，两位远古暗夜精灵恋人曾在上古之战期间一同殒命于此。",al={"同心树","同心树是什么","同心树背景故事"}},{q="安娜瑟拉和拉瑟里安是谁？",a="安娜瑟拉和拉瑟里安是一对在上古之战期间并肩作战的恋人。他们在战斗中倒下，最后的相拥滋养了脚下的土地，同心树从中生长出来，长久见证着他们忠贞不渝的爱情。",al={"安娜瑟拉和拉瑟里安","同心树的恋人","谁死在同心树下"}},{q="术士为什么需要同心树？",a="魅魔是受欲望与情感操纵吸引的恶魔。术士利用同心树与不朽爱情之间的共鸣作为诱饵，将魅魔引入物质世界，完成召唤。",al={"术士为什么想要同心树","同心树魅魔","同心树用途"}},{q="在哪里能找到同心树？",a="同心树来自灰谷森林西北部的奥迪拉兰废墟，那里靠近黑海岸边界。",al={"同心树位置","同心树在哪里","奥迪拉兰废墟同心树"}}},fx={["61f35e8f"]={q="同心树木材来自哪里？是谁创造了它？",a="同心树木材并非凡人所制，而是采自一棵孤树。这棵树生长在灰谷西北部的奥迪拉兰废墟中。数千年前，在灾难性的上古之战期间，一对名为阿纳瑟拉和拉瑟里昂的恋人双双战死。他们咽下最后一口气的地方长出了这棵树，成为他们永恒爱情的活见证。",al={"同心树木材的来源","同心树木材来自哪里","同心树木材如何形成"}}},fp="10,201,22.420.0,21.390.1,19.157.0,32.223.0,32.184.0,30.113.0"}
P.entries["item:heartswood-core"] = {n="同心树之核",s="在暴风城地下，术士用同心树之核召唤魅魔。黑暗缚灵者加科因提供这件由古树木材制成的附魔法器，用以开启通往扭曲虚空的通道。",h="在暴风城地下，术士用同心树之核召唤魅魔。黑暗缚灵者加科因提供这件由古树木材制成的附魔法器，用以开启通往扭曲虚空的通道。",kw={"黑暗缚灵者加科因","同心树之核","已宰的羔羊","暴风城","魅魔","召唤法阵","束缚","术士"},ang={["class:Warlock"]="作为联盟术士，你会在训练期间使用同心树之核，召唤并控制你的第一只魅魔。"},sec={{t="通往虚空的法器",b="在暴风城法师区的已宰的羔羊地下，术士避开城市卫兵的视线，举行仪式。同心树之核引导魔力，启动束缚仪式。它由古树的木材制成，残存的力量足以刺穿世界之间的帷幕。在经过祝圣的召唤法阵中，学徒通过这枚核心凝聚黑暗法术，开启通往扭曲虚空的通道。一只魅魔跨越了世界之间的界限。"},{t="束缚的试炼",b="召唤恶魔的术士必须证明自己能够压制它狡诈而善于诱惑的天性，才能将其控制。加科因将同心树之核交给有潜力的修习者，让他们与召唤出的恶魔交战。魅魔会利用弱点，能轻易击溃脆弱的心智。这场交锋是一场致命的入门试炼。渴望掌握力量的术士必须制服恶魔，将耗尽力量的核心交还给加科因，证明自己的意志足以永久束缚这个仆从。"}},faq={{q="同心树之核有什么用途？",a="术士在已宰的羔羊地下的召唤法阵中使用同心树之核，开启通往扭曲虚空的通道。一只魅魔会进入我们的世界，你必须与它战斗并将其束缚。",al={"同心树之核有什么作用","同心树之核用法","同心树之核用途"}},{q="谁提供同心树之核？",a="黑暗缚灵者加科因提供同心树之核。他是一位术士大师，在暴风城法师区的已宰的羔羊下方隐秘的地下墓穴中训练新手。",al={"哪里获得同心树之核","谁提供同心树之核"}},{q="必须在哪里使用核心？",a="在已宰的羔羊地下墓穴的召唤法阵中使用同心树之核，那里深藏于暴风城街道下方。",al={"同心树之核位置","哪里召唤魅魔"}},{q="仪式完成后会发生什么？",a="召唤出魅魔后，在战斗中击败它，将它送回虚空。然后将同心树之核交还给黑暗缚灵者加科因，学习如何随心所欲地指挥这个恶魔。",al={"召唤后做什么","交还同心树之核"}}},fx={["34d5c17e"]={q="同心树之核是什么？",a="同心树之核是一件专为召唤仪式制作的附魔秘器。它由黑暗魔法的修习者制备，充当魔法催化物，其力量足以刺穿世界之间的帷幕，将一只魅魔从扭曲虚空拉入召唤法阵。",al={"同心树之核背景","同心树之核是什么","同心树物品"}},a2df89b9={q="同心树之核从何而来，又是谁制作的？",a="这枚核心以从灰谷的奥迪拉兰废墟取回的同心树原材制备而成，在黑暗缚灵者加科因的指导下加工并注入力量。加科因将制成的秘器托付给在暴风城已宰的羔羊地下修习、颇有潜力的术士。",al={"谁制作了同心树之核","同心树之核来源","同心树之核如何制作"}},cef9a99d={q="加科因为什么要使用同心树之核？",a="想要束缚魅魔的术士，需要一个蕴藏巨大力量的锚点，才能打开通往虚空的门户。没有同心树之核，你就无法完成仪式法术，令恶魔现身并降服其狡诈的心智。",al={"为什么使用同心树之核","同心树之核用途背景","为什么需要同心树之核"}}},fp="15,202,22.443.0,20.458.1,37.194.0,33.176.0,28.125.0,42.179.0"}
P.entries["item:heavy-leaden-collection-phial"] = {n="沉重的铅瓶",s="在卡拉诺斯，奥齐·电环提供沉重的铅瓶，用于净化辐射污染的研究。它能从诺莫瑞根深处的变异生物身上抽取不稳定的放射性排出物，并将其封存在瓶内。",h="在卡拉诺斯，奥齐·电环提供沉重的铅瓶，用于净化辐射污染的研究。它能从诺莫瑞根深处的变异生物身上抽取不稳定的放射性排出物，并将其封存在瓶内。",kw={"诺莫瑞根","齿轮大厅","沉重的铅瓶","奥齐·电环","瓶子","放射性尘埃","唯一的疗法就是更多绿光"},ang={["profession:Engineering"]="身为工程师，你可以用这种瓶子收集不稳定的辐射尘。即使有合适的容器，采集一份样本也可能需要尝试数次。",["race:Gnome"]="身为侏儒，每将一份不稳定的辐射尘封存进瓶中，你就离夺回诺莫瑞根、弄清那场夺走家园的化学灾变更近一步。"},sec={{t="隔绝辐射的容器",b="沉重的铅瓶能从诺莫瑞根内仍然活着的受辐射生物身上抽取不稳定的残留物。要将辐射尘封存在瓶内并不容易。采集一份合适的样本可能需要尝试数次。"},{t="寻求解药",b="奥齐·电环提供这种瓶子，是为了研究如何逆转麻风侏儒身上可怕的变异。先前从地表穴居人身上采集的样本效力太弱，无法用于有效的化学分析。\n\n有了铅瓶，研究人员希望从带有剧毒的野兽身上采集样本，包括齿轮大厅中的辐射软泥怪和潜伏者。他们要找出城中有毒辐射尘里的活性成分，再设法制成有效的解毒剂。"}},faq={{q="沉重的铅瓶有什么用途？",a="这种瓶子能从诺莫瑞根内仍然活着的受辐射生物身上抽取高浓度的放射性排出物。卡拉诺斯的研究人员用这些样本进行净化辐射污染的试验。",al={"这种瓶子有什么用","瓶子用途","铅瓶是什么"}},{q="谁提供沉重的铅瓶？",a="奥齐·电环是丹莫罗卡拉诺斯的一名侏儒研究员，他提供这种瓶子，用于研究如何治愈那些饱受辐射与病痛折磨的麻风侏儒。",al={"谁提供瓶子","哪里获得瓶子","瓶子任务给予者"}},{q="为什么这种瓶子要用沉重的铅制成？",a="这种瓶子被描述为沉重的铅制容器，但其具体构造并未说明。奥齐警告说，放射性尘埃很难封存，样本也会迅速崩解。",al={"为什么用铅瓶","为什么用沉重的铅"}},{q="必须用这种瓶子从哪些生物身上采集样本？",a="必须对诺莫瑞根深处仍然活着、浑身发光的恐怖生物使用这种瓶子。其中包括辐射软泥怪、潜伏者，以及游荡在齿轮大厅下层的恐怖生物。",al={"对什么使用","目标生物","哪些怪物会发光"}}},fx={ca9f55e0={q="奥齐·电环为什么要你交还沉重的铅瓶？",a="奥齐·电环需要你将铅瓶和一份高强度辐射尘样本一同带回他在卡拉诺斯的工坊。他之前测试过辐射较弱的穴居人样本，认为它们达不到要求，因此需要直接从诺莫瑞根内部的生物身上取得纯净、未受污染的辐射，以推进治疗麻风侏儒的实验。",al={"为什么交还沉重的铅瓶","奥齐为什么需要铅瓶","为什么需要收集瓶"}}},fp="29,212,17.202.0,17.442.0,51.172.0,47.150.0,36.193.0,47.175.0"}
P.entries["item:hezrul-s-head"] = {n="赫兹鲁尔的头颅",s="在甜水绿洲，赫兹鲁尔·血印率领着贫瘠之地的科卡尔半人马。他的头颅被带到十字路口以西的雷戈萨·死门那里，作为他们的酋长已经倒下的证明。",h="在甜水绿洲，赫兹鲁尔·血印率领着贫瘠之地的科卡尔半人马。他的头颅被带到十字路口以西的雷戈萨·死门那里，作为他们的酋长已经倒下的证明。",kw={"血印","半人马","十字路口","死门","赫兹鲁尔","科卡尔","甜水","雷戈萨"},ang={["faction:Horde"]="作为部落的一员，取下科卡尔酋长的头颅，就能确保部落在甜水绿洲的重要取水权，并保护穿越贫瘠之地的部落旅人。",["race:Orc"]="作为兽人，你或许会认为科卡尔是一群缺乏纪律的暴徒，他们的狂怒终将败在兽人严明的战斗纪律之下。雷戈萨将这件战利品视为勇武荣耀的证明。"},sec={{t="斩首科卡尔",b="赫兹鲁尔·血印在十字路口以南的甜水绿洲统领着他的科卡尔半人马氏族。科卡尔占据了贫瘠之地的绿洲，威胁着部落的补给路线和新建的定居点。雷戈萨·死门是一名兽人老兵，负责保卫十字路口以西的土地，他看出这些半人马虽然狂暴凶猛，却缺乏纪律。他要求带回赫兹鲁尔被砍下的头颅，以瓦解氏族的指挥，让幸存的战士陷入混乱，削弱他们对部落的攻势。"}},faq={{q="这是谁的头颅？",a="这颗头颅属于赫兹鲁尔·血印，他是贫瘠之地中部科卡尔半人马氏族的首领。",al={"赫兹鲁尔是谁","赫兹鲁尔的身份","这是谁的头颅"}},{q="在哪里能找到赫兹鲁尔·血印？",a="赫兹鲁尔带领他的队伍在贫瘠之地十字路口以南的甜水绿洲一带活动。",al={"赫兹鲁尔的位置","赫兹鲁尔在哪里","寻找赫兹鲁尔"}},{q="谁想要赫兹鲁尔的头颅？",a="雷戈萨·死门是驻守在十字路口以西道路旁一处军事哨站的兽人，他想要这颗头颅，以证明赫兹鲁尔已被击败。",al={"交还赫兹鲁尔的头颅","谁收取赫兹鲁尔的头颅","雷戈萨·死门"}},{q="部落为什么一定要他的头颅，而不只是把他赶走？",a="部落需要确认赫兹鲁尔已经死去。半人马性情暴躁，容易内斗，除掉他们的酋长就能瓦解他们的指挥，减轻他们对十字路口的威胁。",al={"为何杀死赫兹鲁尔","为何取下他的头颅","半人马的威胁"}}},fp="13,177,23.465.0,29.70.0,32.85.0,24.143.0,69.186.0"}
P.entries["item:high-potency-radioactive-fallout"] = {n="高强度辐射尘",s="在诺莫瑞根深处，研究人员正在寻找高强度的辐射尘。他们希望查明这些淤泥如何使侏儒染上麻风病，并找到治愈的方法。",h="在诺莫瑞根深处，研究人员正在寻找高强度的辐射尘。他们希望查明这些淤泥如何使侏儒染上麻风病，并找到治愈的方法。",kw={"诺莫瑞根","绿色荧光","齿轮大厅","高强度辐射尘","受辐射的软泥怪","麻风侏儒","奥齐·电环"},ang={["profession:Engineering"]="不稳定的辐射尘会迅速衰变，因此要用特制的铅瓶携带，以免自身受到辐射。",["race:Gnome"]="诺莫瑞根深处的每一份有毒辐射尘样本，都为逆转那场在城市沦陷时摧残你同胞的变异，带来一丝微弱的希望。"},sec={{t="从源头采集",b="在齿轮大厅深处，受到辐射的恐兽、潜伏者和软泥怪游荡在诺莫瑞根的最底层。沦陷的首都外，研究人员需要从这些活物身上采集辐射尘。从城外受污染的拾荒者身上刮取的样本强度太低，无法用于研究。\n\n这些淤泥衰变得很快。必须将其密封在铅瓶中，赶在强度减弱前送到研究人员手中。"},{t="寻求复原之法",b="奥齐·电环和他的同事正在寻找治愈麻风侏儒的方法。他们相信，辐射淤泥中的秘密或许能为他们指明方向。穴居人入侵期间，排出的毒气使这些幸存者身体畸变，陷入疯狂。\n\n麻风侏儒仍被困在活生生的噩梦之中。对研究人员而言，深入废墟的探险虽然危险，却值得冒险。"}},faq={{q="这些辐射尘来自哪里？",a="这些辐射尘来自诺莫瑞根齿轮大厅下层深处仍然活着的受辐射生物，包括软泥怪、恐兽和潜伏者。",al={"哪里获取辐射尘","辐射尘位置","辐射尘来源"}},{q="为什么需要这种样本？",a="包括奥齐·电环在内的侏儒研究人员需要诺莫瑞根的高浓度辐射样本，以研究这种病症，并寻找治愈麻风侏儒的方法。",al={"谁需要辐射尘","辐射尘用途","为何收集辐射尘"}},{q="为什么必须如此小心地处理？",a="辐射尘会迅速衰变，强度随之降低。必须用铅瓶携带，赶在衰变前送回研究人员手中。",al={"辐射尘衰变","为何使用铅瓶","辐射尘不稳定"}},{q="为什么先前的穴居人残留物不合用？",a="城外穴居人身上的残留物强度太低，杂质太多，无法用于试验。研究人员需要从受到辐射的诺莫瑞根深处的生物身上，采集未经处理的高浓度辐射尘。",al={"为何不用穴居人的荧光","穴居人辐射与辐射尘的区别","先前样本失效"}}},fx={["30a827ed"]={q="高强度辐射尘是什么？",a="这种辐射尘是浓缩而易变的残留物，直接采集自诺莫瑞根残破大厅中翻涌的重度辐射软泥怪、恐兽和潜伏者。它极不稳定，闪耀着剧毒能量的光芒，是残留在灾难核心的原始污染物。",al={"高强度辐射尘是什么","辐射尘背景","辐射尘是什么"}}},fp="32,146,21.383.0,24.362.0,46.145.0,26.163.0,36.138.0,45.166.0"}
P.entries["item:highborne-relic-classic"] = {n="上层精灵的遗物",s="在黑海岸，上层精灵的遗物仍握在游荡于亚米萨兰的幽灵手中。暗夜精灵学者希望将它们收集起来销毁，以免其中沉睡的魔法造成更多伤害。",h="在黑海岸，上层精灵的遗物仍握在游荡于亚米萨兰的幽灵手中。暗夜精灵学者希望将它们收集起来销毁，以免其中沉睡的魔法造成更多伤害。",kw={"亚米萨兰","奥术","黑海岸","上层精灵","上层精灵的遗物","哨兵","桑迪斯·织风"},ang={["class:Mage"]="身为法师，你或许会觉得这些遗物的奥术工艺令人着迷。当地暗夜精灵的掌权者坚持要将它们销毁。",["race:NightElf"]="对暗夜精灵而言，这些遗物让他们想起了那份撕裂其古老文明的奥术傲慢。"},sec={{t="大灾变的遗物",b="一万年前，上层精灵阶层滥用奥术魔法，给古代卡利姆多带来了毁灭。他们的庄园化作断壁残垣，散落在黑海岸各处。在亚米萨兰，哀嚎的幽灵游荡在崩塌的石柱之间，仍紧握着昔日施法所用的器具。这些遗物将奥术污秽与幽灵束缚在一起，而幽灵始终不肯放开那些与自身覆灭息息相关的物件。"},{t="净化奥术污秽",b="大灾变之后，暗夜精灵社会大体上摒弃了奥术魔法，学者们也将这些遗物视为重大隐患。根据哨兵的报告，奥伯丁的桑迪斯·织风派遣旅人，从受诅咒的幽灵手中夺取这些遗物。收集到的遗物会被销毁，以免上层精灵古老的邪恶与灾难性的错误重演。"}},faq={{q="上层精灵的遗物来自哪里？",a="在黑海岸南部主路以东的古代废墟中，游荡于亚米萨兰的幽灵携带着上层精灵的遗物。那些哀嚎的鬼魂在乱石之间紧握着它们。",al={"哪里能找到上层精灵的遗物","谁掉落上层精灵的遗物","遗物位置"}},{q="桑迪斯·织风为什么想要这些遗物？",a="桑迪斯·织风担忧附着在遗物上的奥术腐化。他收集这些遗物是为了将其销毁，以免有人复兴上层精灵危险的魔法。",al={"为何收集遗物","遗物如何处置","织风的目的"}},{q="上层精灵的幽灵为什么仍留在亚米萨兰？",a="这些幽灵是古代的上层精灵贵族，在一万年前世界崩裂时丧生。他们因自身的傲慢和对奥术魔法的执迷而受到诅咒，不得安息的灵魂仍被束缚在故城的废墟中。",al={"亚米萨兰为何有鬼魂","受诅咒的上层精灵是谁","黑海岸为何有鬼魂"}},{q="上层精灵的遗物可以安全使用吗？",a="不可以。暗夜精灵认为，这些遗物沾染了肆意施展奥术所留下的污秽，而正是这种行径引发了大灾变。其中沉睡的魔法十分危险，因此学者们要求销毁它们，而非加以研究。",al={"上层精灵的遗物能否使用","遗物是否危险"}}},fp="25,141,25.381.0,24.381.0,36.173.0,47.157.0,50.228.0,33.202.0"}
P.entries["item:highperch-venom-sac"] = {n="风巢双足飞龙的毒囊",s="风巢双足飞龙的毒囊采自野生双足飞龙，它们在千针石林风巢的高耸石柱上筑巢。兽人珍视双足飞龙，将它们用作飞行坐骑，而某些药剂师和商人更看重它们剧毒的尾刺，甚至胜过活着的野兽。",h="风巢双足飞龙的毒囊采自野生双足飞龙，它们在千针石林风巢的高耸石柱上筑巢。兽人珍视双足飞龙，将它们用作飞行坐骑，而某些药剂师和商人更看重它们剧毒的尾刺，甚至胜过活着的野兽。",kw={"菲欧拉·长耳","哈特拉斯","风巢","毒药","塞拉摩","千针石林","毒囊","双足飞龙"},ang={["class:Rogue"]="从千针石林未被驯服的双足飞龙身上采集的高浓度麻痹毒液，是卡利姆多最强效的天然毒素之一。",["faction:Alliance"]="对联盟而言，袭击风巢的巢穴有双重目的：既能收集珍贵的生物试剂用于贸易，也能削减野生飞龙的数量，免得它们被部落捕获并驯服为坐骑。"},sec={{t="剧毒的收获",b="千针石林的高耸石柱上栖息着繁盛的野生双足飞龙群，风巢的高崖周围尤其如此。这些长着翅膀的掠食者用带倒钩的尾巴注入强效毒液，麻痹并杀死猎物。部落常将这些生物驯养成忠诚的驭风者，而它们的毒囊在卡利姆多各地的炼金师、猎人和投机商人之间也能卖出极高的价钱。"},{t="远方的买家",b="这种毒液出自卡利姆多中部的深邃峡谷，却引起了远方买家的兴趣。在港口城镇塞拉摩，高等精灵菲欧拉·长耳出高价收购从风巢飞龙群中采集的新鲜毒囊。她要的是饱含毒液的样本——通常只有年幼的双足飞龙或具有繁殖能力的雌性才有这样的毒囊——这也让危险试剂的贸易延伸到了远离这些野兽天然沙漠栖息地的地方。"}},faq={{q="哪些生物携带这些毒囊？",a="这些毒囊直接采自栖息在千针石林风巢的野生双足飞龙，包括巨翼双足飞龙、风巢雄翼龙、风巢雌翼龙，以及雌性首领哈特拉斯。",al={"毒囊哪里掉落","谁掉落风巢毒液","双足飞龙毒液掉落"}},{q="塞拉摩的菲欧拉·长耳为什么需要这种毒液？",a="菲欧拉·长耳知道，双足飞龙的毒液在某些贸易圈子里极为值钱——有时甚至比坐骑本身更赚钱。她委托前往千针石林风巢的旅人带回完整的毒囊，用于贸易。",al={"菲欧拉为何需要毒液","塞拉摩毒液买家","谁收购双足飞龙毒液"}},{q="所有双足飞龙的毒囊都一样吗？",a="毒液的效力和分量各不相同。最珍贵的毒囊鼓胀饱满，几乎要被毒液撑破，通常见于年幼的双足飞龙或具有繁殖能力的雌性。",al={"双足飞龙毒液品质","饱胀的毒囊"}},{q="部落和联盟利用这些双足飞龙的方式有何不同？",a="部落主要捕捉并繁育双足飞龙，将它们用作飞行坐骑和空中斥候，称为驭风者。独立商人和联盟的联络人缺乏驯养体系，因此会直接猎杀这些野兽，获取致命的化学试剂。",al={"部落双足飞龙用途","兽人使用毒液吗"}}},fx={["98761a97"]={q="风巢双足飞龙的毒囊是什么？",a="风巢双足飞龙的毒囊是从野生双足飞龙身上采集的器官。这些双足飞龙栖息在千针石林风巢的高耸台地上。双足飞龙在卡利姆多以部落使用的飞行坐骑而闻名，但它们的毒液也因药效猛烈而备受珍视。从风巢双足飞龙身上取下的毒囊尤其饱满，富含致命毒素，因此成为炼金师和异兽材料商人的高价货品。",al={"风巢双足飞龙的毒囊是什么","风巢双足飞龙的毒囊","双足飞龙毒囊"}}},fp="19,123,16.261.0,15.310.0,38.125.0,53.203.0,36.137.0,66.206.0"}
P.entries["item:highperch-wyvern-egg"] = {n="风巢双足飞龙的蛋",s="风巢的双足飞龙卵采自千针石林高耸台地上的巢穴。立志成为部落风骑士的学徒们四处寻求这些卵，以孵育并训练新的飞行坐骑。",h="风巢的双足飞龙卵采自千针石林高耸台地上的巢穴。立志成为部落风骑士的学徒们四处寻求这些卵，以孵育并训练新的飞行坐骑。",kw={"艾鲁","乱风岗","风巢","风巢双足飞龙的蛋","千针石林","风骑士","双足飞龙"},ang={["class:Hunter"]="要穿行于风巢险峻的高地，就必须了解这些凶猛掠食者的习性，因为成年双足飞龙会用利爪和带毒的尾刺保卫巢穴。",["faction:Horde"]="在卡利姆多辽阔的疆域上，可靠的空中交通对维持通信和战备至关重要，因此补充新的双足飞龙也具有战略意义。"},sec={{t="台地上的巢穴",b="千针石林的风巢地势高耸，是当地双足飞龙栖息和养育幼崽的天然庇护所。通往这些巢穴的只有沿峡谷岩壁蜿蜒而上的陡峭小径，成年双足飞龙在此严密守卫。巢中的卵坚实而温暖，其中正在发育的幼崽能够适应卡利姆多严酷的天空环境。"},{t="培养新的风骑士",b="随着部落的信使和侦察网络不断扩张，卡利姆多各地训练有素的双足飞龙始终供不应求。在乱风岗，牛头人艾鲁这样的学徒直接前往野外巢穴，寻找完好无损的卵。驯养者希望从破壳之初便开始养育幼崽，与它们建立深厚的羁绊，为部落风骑士训练值得信赖的飞行坐骑。"}},faq={{q="这些卵在哪里可以找到？",a="这些卵散布在风巢各处的巢穴中。风巢是一座位于千针石林西侧岩壁上的高耸台地，沿着从谷底向上延伸的小径即可抵达。",al={"飞龙卵位置","哪里能找到双足飞龙卵","风巢飞龙卵位置"}},{q="部落为什么要收集野生双足飞龙卵？",a="部落风骑士的队伍日益壮大，驯养者难以训练出足够的成年双足飞龙来满足需求。艾鲁这样的学徒收集飞龙卵，以便从幼崽出生时就开始养育，让飞龙和骑手都为执行空中任务做好准备。",al={"为什么要偷双足飞龙卵","飞龙卵有什么用途","艾鲁飞龙卵任务目的"}},{q="双足飞龙父母会敌视采卵者吗？",a="会。野生双足飞龙会拼死保护自己的巢穴，猛烈攻击任何闯入风巢、企图动它们的卵的入侵者。",al={"双足飞龙会攻击吗","双足飞龙会护巢吗"}},{q="乱风岗有谁接收这些卵？",a="艾鲁是一名驻扎在乱风岗、立志成为风骑士的学徒。他收集这些卵，希望借此开始正式的坐骑训练。",al={"谁收双足飞龙卵","艾鲁乱风岗"}}},fx={efbaa71b={q="风巢双足飞龙的蛋是什么？",a="这些是野生双足飞龙产下的可孵化的蛋，它们在千针石林高耸的峡谷台地上筑巢。坚硬的蛋壳中孕育着卡利姆多的飞行掠食者幼崽，许多人都想从幼年开始饲养它们，将其培养成忠诚的飞行坐骑。",al={"风巢双足飞龙的蛋是什么","双足飞龙蛋信息","这些蛋是什么"}},bbfa5024={q="风巢双足飞龙的蛋来自哪里？",a="这些蛋由野生双足飞龙产下，位于风巢的悬崖巢穴中。风巢是一片高耸于千针石林峡谷之上的高地。成年双足飞龙会凶猛地保护自己的巢穴，抵御掠食者和胆大的拾荒者。",al={"风巢双足飞龙的蛋来自哪里","谁产下了这些蛋","双足飞龙蛋的来源"}}},fp="20,116,17.269.0,23.290.0,27.139.0,44.168.0,48.118.0,40.107.0"}
P.entries["item:hildelve-s-journal"] = {n="莫里·铁钻的日记",s="在丹莫罗，莫里·铁钻的日记记载了一名丧命于凶熊之爪的矮人的遗言。日记讲述了他遇袭的经过，以及他请求他人为自己复仇的心愿。",h="在丹莫罗，莫里·铁钻的日记记载了一名丧命于凶熊之爪的矮人的遗言。日记讲述了他遇袭的经过，以及他请求他人为自己复仇的心愿。",kw={"丹莫罗","铁钻","冰爪熊","日记","癞爪","驾驶员塞克·锤足","攻城旅"},ang={["faction:Alliance"]="身为联盟的一员，你找回铁钻等阵亡士兵的遗物，便能加深联盟与铁炉堡攻城坦克旅之间的联系。",["race:Dwarf"]="身为矮人，你可以向驾驶员们不屈的精神致敬，他们冒着严寒与野兽的威胁，守卫卡兹莫丹的高地。"},sec={{t="驾驶员的遗言",b="矮人驾驶员铁钻的蒸汽坦克发生故障后，他独自深入丹莫罗。他留下搭档锤足看守坦克，自己前往风雪肆虐的峭壁，寻找传闻中的奇隆矿石。铁钻在日记中写道，一头名叫癞爪的巨型冰爪熊跟踪了他数日，随后发动了袭击。\n\n铁钻奋勇抵抗，赶走了巨熊，但癞爪将他撕咬成重伤，把他留在了严寒之中。他在痛苦中度过了生命最后的时光。在巨熊返回之前，铁钻只留下了一个请求：无论谁发现他的尸体，都请猎杀癞爪，为他报仇。"},{t="返回攻城旅",b="铁钻的战友驾驶员塞克·锤足驻扎在丹莫罗东部的北门哨岗附近。锤足隶属于铁炉堡攻城坦克旅，搭档外出寻矿迟迟未归，让他担心对方已经遭遇不测。日记和癞爪被斩下的利爪证明，铁钻的遗愿已经实现，他的灵魂也得以安息。"}},faq={{q="铁钻是谁？",a="铁钻是一名矮人，为铁炉堡攻城坦克旅驾驶蒸汽坦克。坦克发生故障后，他独自深入丹莫罗，寻找奇隆矿石。他还没来得及返回，就被癞爪杀死了。",al={"铁钻的故事","铁钻是谁","矮人驾驶员铁钻"}},{q="癞爪是什么？",a="癞爪是一头体型异常庞大、性情凶残的冰爪熊，在丹莫罗积雪覆盖的山脊间出没。铁钻被困期间，这头熊伏击了他，将他撕咬成重伤。随后，癞爪返回，夺去了他的性命。",al={"癞爪是谁","什么杀死了铁钻","杀死铁钻的熊"}},{q="找到日记后要交给谁？",a="日记要交给驾驶员塞克·锤足。这位铁钻的战友是一名攻城战车驾驶员，驻扎在丹莫罗东部的北门哨岗附近。他一直在打听这位失踪驾驶员的消息。",al={"日记交到哪里","莫里·铁钻的日记交给谁","交还莫里·铁钻的日记"}},{q="铁钻在日记中提出了什么请求？",a="铁钻请求发现他遗骸的人猎杀癞爪，为他报仇。在日记的最后几页，他写下了袭击自己的野兽的名字，并在明知自己伤重不治的情况下，留下了这一请求。",al={"铁钻的遗愿","日记的内容","驾驶员的临终心愿"}}},fx={b58cc0e1={q="莫里·铁钻的日记是什么？",a="这本破旧的日志属于铁钻，他是铁炉堡攻城坦克旅的一名遇难矮人驾驶员。日记在丹莫罗冰封之地的遗骸旁被发现，记录了他最后那段惨痛时光——他在巨熊癞爪第一次凶猛的袭击中幸存，并在野兽返回夺走他性命之前，写下了复仇的临终遗愿。",al={"这本日记是什么","莫里·铁钻的日记背景","关于莫里·铁钻的日记"}},["308c8265"]={q="莫里·铁钻的日记从何而来，又是谁写的？",a="这本日记由驾驶员铁钻亲笔写下，记述了他在丹莫罗的苦难遭遇。他的蒸汽坦克发生故障后，他徒步寻找希隆矿石，却遭到巨熊癞爪的撕咬；他直到临死前都在撰写这份私人记录，留下了记述自己挣扎求生与最后请求的文字。",al={"谁写了这本日记","莫里·铁钻的日记从何而来","莫里·铁钻的日记来源"}},["856dae3f"]={q="为什么有人需要莫里·铁钻的日记？",a="他的同伴、同为蒸汽坦克驾驶员的驾驶员塞克·锤足，正焦急地寻找失踪战友的消息。这本日记为铁钻的命运提供了确凿证据，也让人得以遵从他的遗愿，向夺去他性命的怪物复仇，使他在铁炉堡攻城坦克旅的朋友们得以了却心事。",al={"为什么保留莫里·铁钻的日记","谁需要这本日记","为什么带回莫里·铁钻的日记"}}},fp="18,145,21.567.0,27.344.1,17.205.0,18.207.0,42.179.0,42.197.0"}
P.entries["item:hillsbrad-human-skull"] = {n="希尔斯布莱德人类颅骨",s="在希尔斯布莱德丘陵各地，被遗忘者收集着被杀人类的颅骨。在塔伦米尔，他们将这些颅骨留作阴森的纪念品，纪念对当地聚落的袭击。",h="在希尔斯布莱德丘陵各地，被遗忘者收集着被杀人类的颅骨。在塔伦米尔，他们将这些颅骨留作阴森的纪念品，纪念对当地聚落的袭击。",kw={"达萨利亚","希尔斯布莱德","沙穆萨","颅骨","南海镇","塔伦米尔","战利品"},ang={["faction:Alliance"]="身为联盟的一员，你看到希尔斯布莱德的农夫和士兵沦为小玩物，显露出被遗忘者在洛丹伦发动的战役有多么残酷。",["race:Undead"]="身为被遗忘者，你或许会将这些颅骨视为复仇的象征，也视为阴森的提醒，让你想起那些排斥你的活人亲族。"},sec={{t="惨烈战争的战利品",b="来自塔伦米尔的被遗忘者部队与南海镇及附近聚落的人类交战。在希尔斯布莱德之战中，亡灵哨兵和士兵执行着达萨利亚下令展开的清洗。留下放哨的卫兵也想参与这场屠杀。亡灵卫兵沙穆萨从前线战士手中收集颅骨，乐于收藏那些曾与被遗忘者共同生活的人们的遗骸。战火仍在燃烧，这些战利品便是杀戮的明证。"}},faq={{q="谁想要这些人类颅骨？",a="亡灵卫兵沙穆萨是塔伦米尔的一名被遗忘者哨兵，负责收集这些颅骨。他羡慕那些被派往希尔斯布莱德征战劫掠的士兵，自己却只能留下站岗，于是请求过路的冒险者为他带来三十个人类颅骨，充实他的私人收藏。",al={"谁要颅骨","谁收人类颅骨","亡灵卫兵沙穆萨颅骨"}},{q="希尔斯布莱德人类颅骨在哪里收集？",a="被遗忘者从希尔斯布莱德丘陵各地的人类战斗人员和劳工身上收集颅骨，尤其是在希尔斯布莱德之战中遭到袭击的人类农场、矿井和城镇防御工事附近。",al={"哪里掉落颅骨","刷人类颅骨","谁掉落人类颅骨"}},{q="被遗忘者为什么收集人类遗骸？",a="一些被遗忘者出于仇恨和阴暗的幽默感收集人类遗骸。像沙穆萨这样的士兵将颅骨视为珍贵的奇物，也视为希尔斯布莱德即将战败的证明。",al={"被遗忘者 为什么要颅骨","被遗忘者 颅骨收藏"}}},fx={["0091f8c0"]={q="希尔斯布莱德人类颅骨是什么？",a="这些是从散落在希尔斯布莱德丘陵各处的人类守军和居民遗体上砍下的可怖战利品。塔伦米尔的被遗忘者与希尔斯布莱德的生者之间战火不断，这些骇人的信物是联盟在这片争夺之地伤亡的实物证据。",al={"希尔斯布莱德人类颅骨是什么","希尔斯布莱德颅骨物品","希尔斯布莱德人类颅骨信息"}},["9eb161fa"]={q="希尔斯布莱德人类颅骨来自哪里？是谁制作的？",a="这些颅骨直接取自居住在希尔斯布莱德丘陵的人类，由参与边境战事的部落战士收集。它们并非人工制品，而是从阵亡的士兵、农夫和居民身上取下的阴森战场遗物；这些人曾守卫当地的人类定居点，抵御被遗忘者。",al={"希尔斯布莱德人类颅骨的来源","希尔斯布莱德颅骨来自哪里","谁制作希尔斯布莱德颅骨"}},a9ea879b={q="亡灵卫兵沙穆萨为什么想要希尔斯布莱德人类头骨？",a="驻扎在塔伦米尔执行守卫任务的亡灵卫兵沙穆萨，嫉妒那些被派去劫掠并与生者作战的战士。他被困在前线后方，便收集头骨作为珍贵的私人死亡纪念品，以此间接分享屠杀希尔斯布莱德人类守军的快感。",al={"沙穆萨为什么想要头骨","谁想要希尔斯布莱德人类头骨，为什么","为什么收集希尔斯布莱德人类头骨"}}},fp="21,143,24.447.0,29.227.0,42.203.0,42.160.0"}
P.entries["item:hillsbrad-town-registry"] = {n="希尔斯布莱德城镇文档",s="在希尔斯布莱德农场，城镇大厅里存放着一本账册，记载着定居点中幸存的居民和土地所有者。希尔斯布莱德城镇文档记录着城镇事务，被遗忘者在进攻这座人类据点时，想要夺取它。",h="在希尔斯布莱德农场，城镇大厅里存放着一本账册，记载着定居点中幸存的居民和土地所有者。希尔斯布莱德城镇文档记录着城镇事务，被遗忘者在进攻这座人类据点时，想要夺取它。",kw={"希尔斯布莱德之战","达萨利亚","希尔斯布莱德农场","希尔斯布莱德城镇大厅","希尔斯布莱德城镇文档","波恩塞德镇长"},ang={["faction:Horde"]="对部落而言，夺取城镇文档有助于瓦解人类在丘陵地带的统治，并巩固被遗忘者在塔伦米尔的据点。",["race:Human"]="对人类而言，这本账册记载着希尔斯布莱德剩余镇民的正式身份与权利。失去它将使当地居民遭受沉重打击。"},sec={{t="抗争的记录",b="希尔斯布莱德城镇文档记录着镇民及其权利。它存放在城镇大厅内，靠近波恩塞德镇长的讲台。被遗忘者从塔伦米尔出击，力图瓦解人类在丘陵地带的抵抗。达萨利亚派遣部落勇士进入城镇大厅，杀死议会成员并夺取账册。其中记录着希尔斯布莱德的人口、住户和行政权利。这份文档将使城镇丧失其自治秩序，并为幽暗城提供有关幸存居民及其资产的情报。"}},faq={{q="希尔斯布莱德城镇文档存放在哪里？",a="文档存放在希尔斯布莱德农场城镇大厅的一处角落，靠近通往波恩塞德镇长高台的楼梯。",al={"文档位置","城镇文档在哪里","寻找希尔斯布莱德文档"}},{q="被遗忘者为什么想偷走它？",a="高级执行官达萨利亚想要瓦解人类在丘陵地带的统治。文档记录着镇上的居民、住户、行政权利和财产，能为被遗忘者提供有关幸存居民群体的情报。",al={"为什么偷文档","达萨利亚文档任务","文档用途"}},{q="谁在守卫文档？",a="波恩塞德镇长和希尔斯布莱德议员守卫着文档。他们施展防御魔法，在城镇大厅内外集结。",al={"谁保护文档","城镇大厅守卫"}}},fx={["188a667c"]={q="希尔斯布莱德城镇文档是什么？",a="希尔斯布莱德城镇文档是一本官方记录簿，存放在希尔斯布莱德农场聚居地的市政厅内。它由当地人类行政机构在治安官伯恩赛德的主持下维护，记录了公民事务、人口和治理情况，记载着联盟在山麓地带尚存的一处据点。",al={"希尔斯布莱德城镇文档是什么","希尔斯布莱德城镇文档","记录簿是什么"}}},fp="23,209,20.486.0,42.136.0,37.220.0,24.138.0"}
P.entries["item:hollow-vulture-bone"] = {n="空心秃鹫骨",s="空心秃鹫骨取自闪光平原上的食腐鸟类，质地轻盈而坚固。在沙漠赛道，地精机械师将它们视为珍贵的专用建材，用来减轻火箭赛车的重量，同时保持结构牢固。",h="空心秃鹫骨取自闪光平原上的食腐鸟类，质地轻盈而坚固。在沙漠赛道，地精机械师将它们视为珍贵的专用建材，用来减轻火箭赛车的重量，同时保持结构牢固。",kw={"空心秃鹫骨","减轻负重","沙漠赛道","普兹克","食腐动物","闪光平原","千针石林"},ang={["class:Hunter"]="闪光平原的秃鹫是生命力顽强的食腐鸟类，自然也成了这片刺眼盐滩上的追踪目标。",["profession:Engineering"]="常规设计图依赖沉重的铁和青铜，而中空鸟骨的运用，则展现了地精赛车创新的核心：就地取材、减轻重量的务实作风。"},sec={{t="平原上的赛车材料",b="在这片盐滩上，速度就是一切，而重量是速度的大敌。常规工程设计大量使用铁和铜，沙漠赛道的地精维修队却会利用沙漠提供的一切来争取优势。秃鹫骨天生中空，却异常坚固，强度与重量的比例十分理想，适合制作内部支架、转向装置和小型承重构件。对普兹克这样的首席技师来说，从当地食腐鸟类身上采集骨头，是缩短赛道用时的一条实用又廉价的捷径。"}},faq={{q="地精为什么要秃鹫骨？",a="普兹克这样的地精工程师用空心秃鹫骨来减轻火箭赛车的多余重量。鸟骨天生轻盈，强度却出人意料，因此是制作转向装置和小型结构框架的理想材料。",al={"为什么要骨头","地精骨头用途","普兹克骨头用途"}},{q="这些骨头从哪里来？",a="这些骨头采自盘旋在千针石林闪光平原上的盐石食腐鸟和盐石秃鹫，尤其是在盐漠各处的巨型骸骨附近。",al={"哪里能找到空心秃鹫骨","秃鹫骨位置","如何获取秃鹫骨"}},{q="普兹克是谁？",a="普兹克是驻扎在沙漠赛道的地精工程师兼首席机械师。他不断调校和改装火箭赛车，与菲兹尔·铜栓率领的侏儒车队竞争。",al={"普兹克是谁","普兹克赛道","谁收骨头"}}},fx={["2d4c7633"]={q="空心秃鹫骨是什么？",a="这些是从盘旋于闪光平原上空的食腐鸟身上搜集来的骨头，轻巧而坚固。鸟类骨骼天生中空，有助于飞行，因此在机械工程中格外适用，尤其是需要尽可能减轻重量的场合。沙漠赛道的地精技师用它们为火箭赛车制作耐用的结构部件和转向零件。",al={"空心秃鹫骨是什么","空心秃鹫骨"}}},fp="19,195,29.384.0,38.158.0,31.189.0,14.164.0"}
P.entries["item:honorary-picks"] = {n="荣誉锄",s="铁炉堡的荣誉锄即将送往塞尔萨玛，交给布洛克·寻石者的采矿学徒。狮鹫将这些礼仪用具运往洛克莫丹，作为学徒们已准备好开采当地矿脉的标志。",h="铁炉堡的荣誉锄即将送往塞尔萨玛，交给布洛克·寻石者的采矿学徒。狮鹫将这些礼仪用具运往洛克莫丹，作为学徒们已准备好开采当地矿脉的标志。",kw={"布洛克·寻石者","格莱斯·瑟登","荣誉锄","铁炉堡","洛克莫丹","采矿锄","塞尔萨玛","索格拉姆·伯雷森"},ang={["profession:Mining"]="身为矿工，你知道一把结实的矿锄有多大价值。一件象征荣誉的工具，标志着新手正式入行。",["race:Dwarf"]="身为矮人，你明白将铁炉堡锻造的工具赠予在外地劳作的学徒，承载着怎样的同族情谊与工匠精神。"},sec={{t="交给下一代的工具",b="采矿让巨大的熔炉长燃不息，也为矮人带来了所需的铁与石。在塞尔萨玛，布洛克·寻石者教导年轻的学徒采矿。来自铁炉堡的荣誉锄，标志着这些学徒已准备好开采洛克莫丹各处露天的矿藏。"},{t="测试狮鹫航线",b="这些矿锄通过联盟的狮鹫运输网络运送，这一网络将铁炉堡与外围的定居点相连。在铁炉堡的大锻炉，格莱斯·瑟登接收这批货物。他将货物送过群山，交给塞尔萨玛的索格拉姆·伯雷森。"}},faq={{q="荣誉锄有什么用途？",a="洛克莫丹的采矿学徒将从导师布洛克·寻石者那里获得荣誉锄。这些礼仪用具已准备就绪，可供学徒们开采当地各处的矿脉。",al={"荣誉锄是什么","荣誉锄的用途","荣誉锄的作用"}},{q="谁送出这些矿锄，又由谁接收？",a="这些矿锄在铁炉堡备好后，会被送到城内的狮鹫栖木，交给格莱斯·瑟登。随后，它们从那里向东飞往塞尔萨玛，由采矿训练师布洛克·寻石者接收。",al={"谁获得荣誉锄","荣誉锄运送","荣誉锄接收者"}},{q="为什么要用狮鹫运送这些矿锄？",a="狮鹫沿着联盟已有的飞行路线，在铁炉堡与洛克莫丹之间快速运送这些矿锄。这条运输路线也让旅行者学会使用这些航线。这些矿锄也可以由人徒步穿过北门小径运送。",al={"为什么空运矿锄","为什么乘坐狮鹫","荣誉锄航线"}},{q="荣誉锄是可以装备的武器或工具吗？",a="不是。信使将这些矿锄作为货物携带，送给布洛克·寻石者的采矿学徒。他们迫不及待地想用这些矿锄开采洛克莫丹的矿藏。",al={"荣誉锄能否装备","荣誉锄是物品吗","荣誉锄能否使用"}}},fx={a7b14bb4={q="荣誉锄是什么？",a="荣誉锄是一捆在铁炉堡打造的礼仪或纪念用采矿工具。它们是专门准备的赠礼，要送给那些在洛克莫丹丘陵间接受资深勘探者指导、学习采矿技艺的新手矿工。",al={"荣誉锄是什么","荣誉锄物品","荣誉锄背景"}},["0ecadd79"]={q="荣誉锄来自哪里，是谁打造的？",a="这些矿锄采购自矮人的都城铁炉堡。城中大锻炉里技艺精湛的高山铁匠打造了它们，并将其专门打包，以便运往丹莫罗边境之外，交给训练学徒的导师。",al={"谁打造了荣誉锄","荣誉锄来源","矿锄来自哪里"}},["1a632b74"]={q="为什么有人需要荣誉锄？",a="塞尔萨玛的采矿训练师布洛克·寻石者订购了这些矿锄，准备赠给他的新学员。这些立志成为勘探者的学员在洛克莫丹劳作，热切盼望着得到这份荣誉和工具，好开始开采当地丰富的矿脉。",al={"为什么要运送荣誉锄","谁需要荣誉锄","布洛克为什么需要矿锄"}}},fp="14,202,29.256.0,25.237.0,37.165.0,43.192.0,49.237.0,61.144.0"}
P.entries["item:horn-of-arra-chea"] = {n="阿兰其亚的角",s="阿兰其亚漫游在莫高雷各处，凯恩·血蹄则召集年轻的猎手，要求他们证明自己的价值。这头科多兽的角证明，猎手能够追踪猎物，为 舒哈鲁 提供生计。",h="阿兰其亚漫游在莫高雷各处，凯恩·血蹄则召集年轻的猎手，要求他们证明自己的价值。这头科多兽的角证明，猎手能够追踪猎物，为 舒哈鲁 提供生计。",kw={"阿兰其亚","凯恩·血蹄","阿兰其亚的角","科多兽","莫高雷","大地之母仪祭","雷霆崖"},ang={["class:Hunter"]="身为猎手，沿着阿兰其亚在莫高雷循环游荡的路线追踪它，考验的是猎手所重视的潜踪与野外生存本领。",["race:Tauren"]="身为牛头人，向 High Chieftain Cairne 献上阿兰其亚的角，标志着你完成成年仪式，也证明你已准备好供养和保卫雷霆崖上的族人。"},sec={{t="酋长的考验",b="通过大地之母仪祭，年轻人便能在雷霆崖获得一席之地，但 大酋长 凯恩·血蹄仍要求族人证明自己的价值。对牛头人而言，狩猎将自身的认同与同大地长久和谐共处联系在一起。凯恩派年轻的猎手追踪阿兰其亚，这头体型庞大的独居雄性科多兽在下方的草原上漫游。取得它的角，便证明猎手已掌握跨越辽阔地域追踪猎物的本领。"},{t="供养部族",b="将阿兰其亚的角带到雷霆崖，不仅能展示力量，也能帮助维持族人的生计。牛头人会利用猎获野兽身上的每一个部位。这件战利品能让 大酋长 知道阿兰其亚倒在何处，好派采集队下到平原，收取科多兽厚实的皮革和丰足的肉食，供给这座初建的都城。"}},faq={{q="阿兰其亚的角是什么？",a="阿兰其亚的角取自阿兰其亚，这头强大而行踪难觅的科多兽在莫高雷的平原上漫游。猎手将它带给凯恩·血蹄，以此完成成年仪式，并证明自己的追踪本领。",al={"阿兰其亚的角","阿兰其亚 的角","这只角是什么"}},{q="阿兰其亚是谁？",a="阿兰其亚是一头有名的雄性科多兽，在雷霆崖东北方的草原上循环游荡。它力量强大，迁徙路线绵长，对那些想向部族证明自身价值的猎手而言，是极具挑战的猎物。",al={"阿兰其亚","阿兰其亚 是谁","阿兰其亚 的故事"}},{q="凯恩·血蹄为何索要这件战利品？",a="凯恩·血蹄索要这件战利品，是因为他期望族人不断证明自己的价值。追踪并击杀阿兰其亚，既能展现猎手对 大地母亲 传统的忠诚，也能为族人提供物资。",al={"凯恩 为何要兽角","凯恩 阿兰其亚","大地之母仪祭 兽角"}},{q="野兽被杀死后，身体其余部分会如何处理？",a="牛头人会利用猎获动物身上的每一个部位。兽角确认猎物已被击杀后，凯恩便派一支采集队下到莫高雷，为雷霆崖收取皮革和肉食。",al={"阿兰其亚 的肉","牛头人狩猎传统","阿兰其亚 的尸体"}}},fp="17,138,18.421.0,23.316.0,30.173.0,17.199.0,46.233.0,57.169.0"}
P.entries["item:horn-of-awakening"] = {n="唤醒号角",s="在黑海岸南部，克罗尼亚·恒影随身带着一支号角。每当他在前往灰谷的路上睡着，号角声便会将他唤醒。",h="在黑海岸南部，克罗尼亚·恒影随身带着一支号角。每当他在前往灰谷的路上睡着，号角声便会将他唤醒。",kw={"灰谷","黑海岸","利爪德鲁伊","翡翠梦境","唤醒号角","克罗尼亚·恒影","迈斯特拉岗哨"},ang={["class:Druid"]="身为德鲁伊，你知道Druids of the Claw曾在兽穴中沉睡了数代人的光阴，与翡翠梦境交流。重新醒来后，他们可能会头脑昏沉，不辨方向。",["race:NightElf"]="身为暗夜精灵，从克罗尼亚这段睡意缠身的旅途中，你能看出，你们的德鲁伊在翡翠梦境中长眠之后，要重新适应清醒的生活有多么艰难。"},sec={{t="嗜睡德鲁伊的良方",b="克罗尼亚·恒影在翡翠梦境中沉睡了数百年，直到最近才醒来，仍难以保持清醒。这位利爪德鲁伊向南前往迈斯特拉岗哨，并将号角托付给愿意护送他的旅人。当他在荒野小径上因疲惫而睡去时，一声清亮的号角便能将他惊醒，让他赶在野兽或教徒靠近之前重新站起身来。"}},faq={{q="在哪里可以找到唤醒号角？",a="号角放在克罗尼亚的箱子里，箱子就在克罗尼亚·恒影位于黑海岸南部的营地旁，靠近灰谷边界。",al={"号角位置","唤醒号角在哪里","克罗尼安的箱子"}},{q="克罗尼亚为什么需要号角来保持清醒？",a="在翡翠梦境中沉睡了漫长岁月后，克罗尼亚难以适应凡世的清醒生活，常常在旅途中突然陷入酣睡。",al={"克罗尼亚为什么在睡觉","他为什么会睡着","翡翠梦境沉睡"}},{q="克罗尼亚要去哪里？",a="克罗尼亚正设法前往灰谷北部的迈斯特拉岗哨，与利拉迪斯·月河会面。",al={"克罗尼亚的目的地","他要走到哪里","迈斯特拉岗哨护送"}}},fp="17,119,26.391.0,37.127.0,47.148.0,32.93.0"}
P.entries["item:horn-of-echeyakee"] = {n="埃其亚基的号角",s="在十字路口，瑟格拉·黑棘将埃其亚基的号角交给猎人。在聚落东北方的古老科多兽遗骸间吹响它，便能唤来贫瘠之地传说中的白色掠食者。",h="在十字路口，瑟格拉·黑棘将埃其亚基的号角交给猎人。在聚落东北方的古老科多兽遗骸间吹响它，便能唤来贫瘠之地传说中的白色掠食者。",kw={"贫瘠之地","十字路口","埃其亚基","号角","科多兽骸骨","瑟格拉·黑棘","白雾"},ang={["class:Hunter"]="身为猎人，你将在一场传说中的成年仪式上面对埃其亚基，以自己的感官挑战这头凭借近乎完美的潜行本领闻名于贫瘠之地的掠食者。",["race:Tauren"]="身为牛头人，你明白埃其亚基的狩猎承载着精神上的意义。你的族人认为，他迅捷而无痛的杀戮既是仁慈，也体现了死亡残酷而不可避免的一面。"},sec={{t="呼唤白雾",b="接受狩猎考验的猎人会获得这支号角。号角声能召来埃其亚基，他的名字在 牛头人语 中意为“白雾”。牛头人猎人敬奉这位草原狮王，视他为仁慈与死亡的化身。他出击迅疾，猎物既感受不到恐惧，也感受不到痛苦。这支号角应在掠食者的巢穴吹响，那里位于十字路口东北方的山丘后，遍布巨大的科多兽骸骨。"}},faq={{q="埃其亚基的号角有什么作用？",a="这支号角能引出行踪难觅的白色草原狮埃其亚基。在十字路口东北方的巨大科多兽骸骨附近吹响它，这头野兽便会现身，迎接猎人的挑战。",al={"使用埃其亚基的号角","埃其亚基的号角用途"}},{q="这支号角从何而来？",a="瑟格拉·黑棘是贫瘠之地十字路口的一名兽人女猎手，她将号角交给那些想要证明自己潜行与追踪本领的冒险者。",al={"谁给予号角","埃其亚基的号角来源"}},{q="埃其亚基这个名字是什么意思？",a="在牛头人的语言 牛头人语 中，埃其亚基意为“白雾”。这个名字赞颂了这头野兽浅白的皮毛，以及他悄无声息地潜行于枯草间、不被察觉的本领。",al={"埃其亚基的含义","白雾的含义"}},{q="在哪里吹响号角？",a="在十字路口东北方山丘后的巨大科多兽肋骨与遗骸间吹响号角，白狮就在那一带游荡。",al={"号角使用地点","埃其亚基的位置"}}},fp="17,207,21.375.0,35.165.0,30.144.0,34.134.0,27.135.0"}
P.entries["item:huge-gnoll-claw"] = {n="巨大的豺狼人爪",s="在艾尔文西南部，霍格那巨大的爪子就是他的死亡证明。驻闪金镇的暴风城官员需要这件证物才会支付赏金。",h="在艾尔文西南部，霍格那巨大的爪子就是他的死亡证明。驻闪金镇的暴风城官员需要这件证物才会支付赏金。",kw={"赏金","艾尔文森林","闪金镇","霍格","巨大的豺狼人爪","治安官杜汉","河爪"},ang={["class:Hunter"]="作为猎人，取得这个经常击败武装小队的掠食者的爪子，足以展现你追踪和猎杀野兽的本领。",["faction:Alliance"]="对联盟而言，取得霍格的爪子，意味着为王国腹地铲除了最臭名昭著的林地祸患。这向治安官杜汉和闪金镇疲于应付的驻军证明了你的英勇。"},sec={{t="赏金猎人的证物",b="几个月来，霍格一直在林边空地南部的林地肆虐。巡逻队未能阻止他，当地驻军也无法围住或制服这个蛮横的家伙。暴风城军队在艾尔文各处兵力吃紧，因此公开悬赏捉拿他。闪金镇的治安官杜汉需要确凿的证据才会支付赏金。霍格那硕大的爪子足以证明，这个臭名昭著的劫掠者已经毙命。"}},faq={{q="巨大的豺狼人爪有什么用？",a="将霍格的爪子带给闪金镇的治安官杜汉，作为霍格的死亡证明，领取悬赏的赏金。",al={"霍格的爪子有什么用","巨大的豺狼人爪用途","谁要爪子"}},{q="这只爪子从哪里来？",a="爪子就在霍格身上。这个精英豺狼人游荡在艾尔文森林中林边空地西南边界的河爪营地附近。",al={"谁掉落爪子","如何获得巨大的豺狼人爪","哪里能找到巨大的豺狼人爪"}},{q="治安官杜汉为什么要爪子，而不是头颅？",a="霍格的体型远超寻常豺狼人，他那巨大的爪子特征鲜明，一眼就能认出。一只爪子就足以向暴风城军队证明，这个臭名昭著的劫掠者已被杀死。",al={"为什么用爪子证明死亡","为什么不用霍格的头颅","杜汉赏金证物"}},{q="如果弄丢了爪子，还能再得到一只吗？",a="可以。如果在将爪子交给治安官杜汉之前弄丢了它，你可以回到艾尔文森林西南部，再次猎杀霍格，取得另一只爪子。",al={"巨大的豺狼人爪丢失","能否再次获得爪子","霍格爪子刷新"}}},fx={d9093290={q="巨大的豺狼人爪是什么？",a="巨大的豺狼人爪是从霍格身上斩下的实物，证明这头恶名昭彰、体型庞大的豺狼人已经毙命。他曾在艾尔文森林西南部肆虐。由于当地治安人员每次试图抓捕霍格都被他击败，这只特征鲜明的利爪便成了治安官杜汉眼中无可辩驳的证据，证明这头蛮兽终于被杀死了。",al={"巨大的豺狼人爪是什么","巨大的豺狼人爪资料","霍格的爪子"}},["7983cdb8"]={q="治安官杜汉为什么需要巨大的豺狼人爪？",a="霍格这头巨兽屡次逃脱追捕，还击败了巡逻队，治安官杜汉和暴风城军队因此悬赏捉拿他。杜汉要求以这头豺狼人的巨爪作为死亡证明，才会在闪金镇发放赏金，终于了结霍格给他手下造成的麻烦。",al={"杜汉为什么需要爪子","谁需要巨大的豺狼人爪","为什么需要巨大的豺狼人爪"}}},fp="15,140,21.406.0,37.104.0,31.138.0,56.179.0,36.142.0"}
P.entries["item:humbert-s-sword"] = {n="亨伯特的长剑",s="亨伯特的长剑如今就在丹加洛克的矮人手中，是他们从他的营地里抢走的。亡灵卫兵亨伯特在侦察这座要塞时，曾离开哨位去拾柴。",h="亨伯特的长剑如今就在丹加洛克的矮人手中，是他们从他的营地里抢走的。亡灵卫兵亨伯特在侦察这座要塞时，曾离开哨位去拾柴。",kw={"达萨利亚","亡灵卫兵亨伯特","丹加洛克","希尔斯布莱德","亨伯特的长剑","塔伦米尔"},ang={["faction:Horde"]="找回长剑也是部落针对丹加洛克矮人据点展开的一系列行动的一部分，其中还包括收集矮人的血液和军用徽记。",["race:Undead"]="高级执行官达萨利亚对希尔斯布莱德的被遗忘者部队执行严格的纪律。像亨伯特这样疏于职守的哨兵，都急于掩盖自己的过失。"},sec={{t="斥候的一时疏忽",b="一天早晨，亡灵卫兵亨伯特离开了丹加洛克附近的隐蔽哨位，去拾些柴火烧水。高级执行官达萨利亚派他监视那里的矮人。他离开期间，一支矮人巡逻队发现了他的营地，抢走了他的装备，其中包括他的佩剑。要搜查的矮人实在太多，亨伯特需要部落的勇士进入要塞，找回长剑。"},{t="矮人的赃物",b="丹加洛克的守军将亨伯特的物品带到了要塞的路障后方。火枪手、巡山人和牧师在驻军中传递着补给。要找到窃贼，就得搜查战壕和堡垒中的守军。"}},faq={{q="这把剑是谁的？",a="这把剑属于亡灵卫兵亨伯特，他是一名驻守塔伦米尔的被遗忘者哨兵，奉命侦察丹加洛克。",al={"这是谁的剑","亨伯特 长剑主人","亨伯特是谁"}},{q="矮人是怎么拿到亨伯特的剑的？",a="一天早晨，亨伯特离开了丹加洛克外的侦察营地，去拾些柴火。他离开期间，一支矮人巡逻队洗劫了营地，抢走了他的装备。",al={"矮人怎么拿到的","矮人为什么有这把剑","长剑怎么被偷的"}},{q="亨伯特为什么如此急于找回长剑？",a="亨伯特需要自己的武器，才能按照高级执行官达萨利亚的命令继续监视丹加洛克。驻军中的矮人太多，他独自一人无法找到窃贼。",al={"亨伯特为什么要找回长剑","亨伯特丢了长剑会怎样","亨伯特为什么在意"}},{q="在哪里能找到这把剑？",a="这把剑在希尔斯布莱德丘陵东南部丹加洛克的矮人部队手中。可以从驻守在哨站各处的巡山人、火枪手或牧师身上找回它。",al={"长剑在哪里掉落","长剑位置","如何找到亨伯特的长剑"}}},fp="15,163,25.357.0,17.242.0,20.116.0,40.156.0,50.171.0,29.181.0"}
P.entries["item:hyacinth-mushroom"] = {n="紫蓝色蘑菇",s="在幽影谷，紫蓝色蘑菇生长在遍布泰达希尔的树木根部。暗夜精灵草药师用它们制药，劣魔和劣魔仆从也会采集它们。",h="在幽影谷，紫蓝色蘑菇生长在遍布泰达希尔的树木根部。暗夜精灵草药师用它们制药，劣魔和劣魔仆从也会采集它们。",kw={"解毒剂","迪兰妮亚·月光","劣魔","小劣魔","紫蓝色蘑菇","埃沃隆","幽影谷","泰达希尔"},ang={["profession:Herbalism"]="在幽影谷采集这些蘑菇不需要接受正规训练。初学草药学的人也能了解它们如何帮助抵御森林中的毒素。",["race:NightElf"]="作为一名在幽影谷接受训练的年轻暗夜精灵，你可以采集紫蓝色蘑菇等野生植物，帮助同胞维持生计。"},sec={{t="幽影谷的植物",b="紫蓝色蘑菇生长在幽影谷，散布于奥达希尔的树木与根系之间。森林中的医者用它们配制药物，治疗被有毒生物所伤的年轻暗夜精灵哨兵和受训者。黑丝洞的蜘蛛就是他们面临的危险之一，而这些蘑菇则被用来配制舒缓伤痛的药剂和解毒剂。腐化的劣魔也会囤积它们。"}},faq={{q="紫蓝色蘑菇有什么用途？",a="迪兰妮亚·月光用紫蓝色蘑菇为埃沃隆配制解毒药。这位年轻的暗夜精灵在探索黑丝洞时中了毒蜘蛛的毒。",al={"紫蓝色蘑菇用途","有什么作用","埃沃隆的解药"}},{q="紫蓝色蘑菇生长在哪里？",a="紫蓝色蘑菇生长在泰达希尔的幽影谷，常见于粗大树干和树根附近的地面，以及巨石旁边。",al={"蘑菇位置","哪里能找到紫蓝色蘑菇","幽影谷蘑菇"}},{q="劣魔为什么会携带紫蓝色蘑菇？",a="幽影谷南部的劣魔和劣魔仆从会采集紫蓝色蘑菇，并将它们囤积在营地里。",al={"劣魔掉落蘑菇","劣魔为什么有蘑菇","劣魔蘑菇"}},{q="紫蓝色蘑菇本身有毒吗？",a="没有。当地医者可以安全地用紫蓝色蘑菇配制疗伤药膏和解毒剂。",al={"紫蓝色蘑菇有毒吗","有毒蘑菇"}}},fp="17,161,19.329.0,37.158.0,33.121.0,42.102.0,44.84.0"}
P.entries["item:hypercapacitor-gizmo"] = {n="超适应齿轮",s="超适应齿轮是一件从千针石林谷底找回的古怪工程装置。它曾挂在一支被毁商队中一头笼中猛兽的脖子上，就连自称是它主人的工匠，也不知道它究竟有什么用途。",h="超适应齿轮是一件从千针石林谷底找回的古怪工程装置。它曾挂在一支被毁商队中一头笼中猛兽的脖子上，就连自称是它主人的工匠，也不知道它究竟有什么用途。",kw={"半人马","暴怒的黑豹","装置","超适应","千针石林","白沙岗哨","维兹罗"},ang={["faction:Horde"]="援助白沙岗哨的旅人会帮忙清剿凶悍的半人马，并从散落谷底的商队残骸中找回遗失的古怪物件。",["profession:Engineering"]="这件装置体现了典型的地精工程学：结构复杂，名字透着危险，制造时满腔热情，却没人费心先想好它究竟该有什么用。"},sec={{t="商队的古怪遗物",b="半人马劫掠者伏击了一支途经千针石林的地精商队，几乎把眼前的一切洗劫一空。唯一的幸存者维兹罗设法爬到了白沙岗哨，终于脱离险境，却留下了自己最得意的装置：超适应齿轮。奇怪的是，这件装置最后竟被固定在一头凶猛暴怒的黑豹脖子上，而黑豹被锁在运输笼里。劫掠商队的半人马十分惧怕这头猛兽，任由笼子留在燃烧的残骸中，丝毫不敢碰它，无意间保住了维兹罗的古怪机器。"},{t="摸索中的修修补补",b="维兹罗虽然自豪地称这件装置是自己最得意的作品，却在它被找回后承认，自己其实根本不知道它有什么用。和许多地精造物一样，超适应齿轮将勃勃野心与不稳定的零件纠缠在一起，注定要让主人没完没了地摆弄，而非发挥什么明确的实用功能。"}},faq={{q="超适应齿轮是什么？",a="它是一件属于地精维兹罗的工程装置。虽然名字听起来气派，就连维兹罗也不知道它究竟有什么功能，打算花时间研究它，弄清它的用途。",al={"装置是什么","超适应","装置有什么用"}},{q="这件装置怎么会挂在黑豹脖子上？",a="维兹罗的商队在千针石林北部遭到半人马袭击，被洗劫一空。混乱中，这件装置被固定在一头暴怒的黑豹脖子上，而黑豹被锁在运输笼里，让迷信的半人马不敢抢走它。",al={"黑豹为什么戴着装置","黑豹怎么得到它的"}},{q="谁想找回超适应齿轮？",a="遭劫商队唯一的幸存者维兹罗想找回它。他已经在白沙岗哨避难，那是千针石林西北部的一处牛头人营地。",al={"谁需要装置","维兹罗的装置"}},{q="半人马为什么没有偷走它？",a="半人马洗劫了整支商队，却十分惧怕笼中那头凶猛的黑豹。他们任由猛兽和它的金属项圈留在废墟中，丝毫没有碰过。",al={"半人马为什么没拿走它","半人马与黑豹"}}},fx={["240fe489"]={q="超适应齿轮来自哪里？是谁制作的？",a="这件装置原本由地精技师维兹罗持有。他当时正乘坐商队穿越千针石林，途中遭到半人马伏击。维兹罗称它是自己最珍爱的齿轮装置，但它的确切发明者仍是个谜——就连维兹罗也承认，他并不完全明白这台奇特机器究竟有什么用途。",al={"谁制作了超适应齿轮","超适应齿轮的来历","维兹罗从哪里得到超适应齿轮"}}},fp="20,178,25.378.0,21.227.0,33.172.0,50.235.0,40.175.0,32.147.0"}
P.entries["item:ignition-key"] = {n="打火钥匙",s="在淤泥沼泽的荆棘谷地精钻探工地，打火钥匙由鲁格维兹主管保管。维兹克兰克需要用它解锁一台先进伐木机的操纵柱，启用各项控制装置。",h="在淤泥沼泽的荆棘谷地精钻探工地，打火钥匙由鲁格维兹主管保管。维兹克兰克需要用它解锁一台先进伐木机的操纵柱，启用各项控制装置。",kw={"打火钥匙","伐木机","淤泥沼泽","斯布特瓦夫","鲁格维兹主管","荆棘谷地精","维兹克兰克"},ang={["profession:Engineering"]="打火钥匙能解锁一台配备先进控制装置的伐木机，其速度调节和精细的机械臂动作控制都胜过一般的地精设计。"},sec={{t="谍报行动缺失的一环",b="棘齿城的斯布特瓦夫派出一名特工，前往淤泥沼泽窃取一台荆棘谷地精的伐木机，但计划陷入了僵局。卧底驾驶员维兹克兰克爬进驾驶舱后，发现操纵柱被锁住了。他假装机器出了故障，以免工头们起疑，同时等待有人取来打火钥匙。鲁格维兹主管将钥匙保管在中央石油井架的高处，掌握着伐木机机械臂、速度和转向装置的控制权。"}},faq={{q="在哪里能找到打火钥匙？",a="鲁格维兹主管将打火钥匙保管在淤泥沼泽石油井架顶端的控制室里，并在那里监督钻探工作。",al={"打火钥匙位置","谁掉落打火钥匙","如何获得打火钥匙"}},{q="为什么维兹克兰克非得要这把钥匙？",a="这台先进的荆棘谷地精伐木机的操纵柱被锁住了。没有它的打火钥匙，维兹克兰克就无法充分控制它的转向、速度、稳定性和机械臂，也就无法把它开走。",al={"为什么需要钥匙","钥匙有什么用","伐木机钥匙用途"}},{q="是谁想要偷走伐木机？",a="棘齿城的地精工程师斯布特瓦夫策划了这次盗窃，目的是获取荆棘谷地精更为先进的工程设计。",al={"谁派出了维兹克兰克","为什么偷伐木机","棘齿城伐木机"}},{q="交付钥匙后会发生什么？",a="拿到钥匙后，维兹克兰克便能解锁操纵柱，启动伐木机的引擎。随后，他必须冲过淤泥沼泽充满敌意的劳工，向棘齿城逃去。",al={"交付钥匙后","逃脱","接下来做什么"}}},fp="12,80,28.444.0,36.136.0,44.180.0,30.124.0,39.169.1"}
P.entries["item:ilkrud-magthrull-s-tome"] = {n="伊克鲁德·玛格苏尔之书",s="在火痕神殿，伊克鲁德·玛格苏尔之书引起了净化者德尔格伦的注意。书中的内容揭示了这名术士与奥萨拉克斯之塔邪教徒之间的联系。",h="在火痕神殿，伊克鲁德·玛格苏尔之书引起了净化者德尔格伦的注意。书中的内容揭示了这名术士与奥萨拉克斯之塔邪教徒之间的联系。",kw={"灰谷","净化者德尔格伦","火痕神殿","伊克鲁德·玛格苏尔","迈斯特拉岗哨","典籍","奥萨拉克斯之塔","术士"},ang={["class:Paladin"]="身为圣骑士，你协助德尔格伦修士，这位与你同为圣光而战的勇士，在灰谷的荒野中对抗暗影与腐化。",["class:Warlock"]="身为术士，你可以研究玛格苏尔的魔典，其中记载了在遭受污染的火痕神殿施行的黑暗束缚仪式，以及对虚空行者和魅魔的奴役。"},sec={{t="魔典：腐蚀术",b="伊克鲁德·玛格苏尔盘踞在灰谷西南部的火痕神殿，恶魔的影响已使这里受到污染。这名强大的兽人术士身边围绕着召唤而来的仆从。他的私人典籍记载着邪恶的仪式和隐秘的通信。银色黎明的圣骑士净化者德尔格伦早已知晓玛格苏尔的存在，但这名术士与聚集在奥萨拉克斯之塔的黑暗邪教徒有所勾结，因此必须尽快取回这本书。"},{t="揭开邪教的秘密",b="玛格苏尔被杀死后，他的典籍被送到迈斯特拉岗哨的德尔格伦手中。德尔格伦着手破译这名术士的文字，试图弄清在黑海岸与灰谷边界一带协调恶魔活动的网络。书中的内容提供了重要情报，揭露了那些在暗中操纵阴谋、驱使腐化蔓延至卡利姆多北部的幕后黑手。"}},faq={{q="这本典籍属于谁？",a="这本典籍属于伊克鲁德·玛格苏尔。他是一名强大的兽人术士，盘踞在灰谷西南部火痕神殿的恶魔废墟之中。",al={"伊克鲁德·玛格苏尔是谁","典籍是谁写的","伊克鲁德·玛格苏尔"}},{q="在哪里能找到这本典籍？",a="这本典籍从火痕神殿的伊克鲁德·玛格苏尔身上取得，那里位于灰谷的艾森娜神殿以南。",al={"典籍位置","如何获得典籍","在哪里找到伊克鲁德"}},{q="净化者德尔格伦为什么想要这本书？",a="德尔格伦希望研究玛格苏尔的文字，揭开当地恶魔崇拜者与盘踞在奥萨拉克斯之塔的邪教徒之间的联系。",al={"德尔格伦为什么想要典籍","典籍里有什么","德尔格伦要书的目的"}},{q="取回典籍之后会发生什么？",a="德尔格伦在迈斯特拉岗哨研读这本典籍，试图破译玛格苏尔与恶魔的通信，并找出瓦解邪教网络的方法。",al={"交还典籍","德尔格伦如何处理这本书"}}},fp="23,159,24.434.0,19.342.1,19.142.0,24.109.0,44.139.0,41.138.0"}
P.entries["item:incantations-from-the-nether"] = {n="扭曲虚空的魔法",s="在奥格瑞玛地下，灼热之刃邪教徒掌握着《扭曲虚空的魔法》，一本记载恶魔魔法的魔典。希尔瓦娜斯·风行者和瓦里玛萨斯想为被遗忘者获取其中的邪能知识。",h="在奥格瑞玛地下，灼热之刃邪教徒掌握着《扭曲虚空的魔法》，一本记载恶魔魔法的魔典。希尔瓦娜斯·风行者和瓦里玛萨斯想为被遗忘者获取其中的邪能知识。",kw={"扭曲虚空的魔法","怒焰裂谷","灼热之刃","暗影议会","暗影法术研究","希尔瓦娜斯","毁灭之力","瓦里玛萨斯"},ang={["class:Warlock"]="直接源自虚空的魔典蕴藏着强大的邪能魔法，令野心勃勃的黑暗魔法修习者垂涎不已。",["race:Undead"]="取回这本书能帮助幽暗城中黑暗女王的心腹。他们需要这些黑暗知识来对 Scourge 作战。"},sec={{t="燃烧军团的馈赠",b="灼热之刃是一个与 暗影议会 有联系的地下教派，在奥格瑞玛赤红石街下方、怒焰裂谷灼热的隧道中活动。教徒们珍视《扭曲虚空的魔法》，这本记载恶魔仪式的法术书由燃烧军团的爪牙赐予。他们利用书中的秘密，在兽人的都城密谋叛乱。这本魔典的消息已经传到了幽暗城的皇家区。"},{t="被遗忘者的野心",b="瓦里玛萨斯派遣忠诚的部落冒险者深入怒焰裂谷，取回《扭曲虚空的魔法》及其姊妹篇《暗影法术研究》。希尔瓦娜斯·风行者和她麾下的恐惧魔王副官认为，这些邪能遗物落在目光短浅的邪教徒手中，实在是浪费。黑暗女王打算运用书中由虚空铸就的力量对抗巫妖王，向 天灾军团 复仇。"}},faq={{q="在哪里能找到《扭曲虚空的魔法》？",a="灼热之刃邪教徒和术士在怒焰裂谷中随身携带着这本书，那里是奥格瑞玛地下相互连通的火山洞穴。",al={"扭曲虚空的魔法获取地点","扭曲虚空的魔法由谁掉落","扭曲虚空的魔法位置"}},{q="谁想要这本书，又是为什么？",a="希尔瓦娜斯·风行者女士和恐惧魔王瓦里玛萨斯想要这本书。他们认为灼热之刃邪教徒胸无大志、目光短浅，想用书中的恶魔魔法对抗他们的死敌巫妖王。",al={"谁需要扭曲虚空的魔法","希尔瓦娜斯 为什么想要这本书","瓦里玛萨斯书籍任务"}},{q="灼热之刃是什么？",a="灼热之刃是一个在奥格瑞玛地下活动的隐秘教派，由术士和邪教徒组成，与 暗影议会 结盟。其成员效忠于燃烧军团，暗中破坏萨尔新建的部落。",al={"灼热之刃 背景故事","灼热之刃 是谁"}},{q="与这本书配对的另一本书是什么？",a="瓦里玛萨斯需要两本书：《扭曲虚空的魔法》和《暗影法术研究》。必须从怒焰裂谷的邪教徒手中夺取这两本书，才能完成他的任务。",al={"瓦里玛萨斯需要的另一本书","毁灭之力 书籍"}}},fp="28,178,19.393.0,17.383.1,53.136.0,28.188.0,26.215.0,40.164.0"}
P.entries["item:incendia-agave"] = {n="火岩龙舌兰",s="火岩龙舌兰生长在黑云峰下的沸腾之池中。技艺娴熟的萨满祭司能为它施加魔法，用它点燃生命圣火。",h="火岩龙舌兰生长在黑云峰下的沸腾之池中。技艺娴熟的萨满祭司能为它施加魔法，用它点燃生命圣火。",kw={"阿利卡拉","沸腾之池","黑云峰","火岩龙舌兰","玛加萨·野性图腾","圣火","千针石林"},ang={["class:Shaman"]="身为萨满祭司，你可以运用原始的元素之术，将这种水生植物制成粉末，其力量足以点燃神圣的仪式之火。",["profession:Herbalism"]="身为草药师，你的追踪能力能帮助你在沸腾之池浑浊的水底找到一丛丛尖叶的火岩龙舌兰。"},sec={{t="稀有的沙漠草药",b="在千针石林，火岩龙舌兰生长在黑云峰下沸腾之池的水中及周边。游荡的蒸汽元素守护着这种稀少的植物，让采集变得十分困难。虽然生长在水下，这种植物却蕴含着适合火焰仪式的自然元素。"},{t="圣火",b="牛头人祭司无法用普通的火花点燃沉寂的生命圣火。位于雷霆崖长者高地的长者玛加萨·野性图腾，能将采集来的成捆火岩龙舌兰施法制成神秘粉末。这种粉末能点燃仪式火盆，用来召唤满怀复仇之心的风蛇阿利卡拉。"}},faq={{q="火岩龙舌兰生长在哪里？",a="火岩龙舌兰生长在千针石林北部黑云峰下沸腾之池的湖水中及周边。大部分都浸没在湖底。",al={"哪里能找到龙舌兰","火岩龙舌兰位置","龙舌兰在哪里"}},{q="火岩龙舌兰有什么用途？",a="采集十蒲式耳火岩龙舌兰后，可以将其制成仪式粉末。玛加萨·野性图腾在雷霆崖为它施加魔法，用来点燃生命圣火并召唤阿利卡拉。",al={"火岩龙舌兰用途","为什么采集龙舌兰","龙舌兰有什么用"}},{q="谁能为火岩龙舌兰施加魔法？",a="玛加萨·野性图腾是雷霆崖长者高地一位颇具影响力的萨满祭司，她掌握着为火岩龙舌兰施加魔法的仪式知识。",al={"谁为龙舌兰施加魔法","玛加萨·野性图腾 龙舌兰","谁把龙舌兰制成粉末"}},{q="火岩龙舌兰周围有哪些威胁？",a="敌对的蒸汽元素在沸腾之池的水中和岸边游荡。它们对冰霜和火焰法术的抗性极高。",al={"龙舌兰周围的危险","什么守护着龙舌兰","沸腾之池的危险"}}},fp="14,136,18.272.0,15.238.1,31.165.0,32.172.0,35.131.0,41.131.0"}
P.entries["item:incendia-powder"] = {n="火岩粉",s="在雷霆崖，火岩粉被制备出来，用于将一位神圣的灵体召至现世。玛加萨·野性图腾为它施加魔法，以便在千针石林的黑云峰使用。",h="在雷霆崖，火岩粉被制备出来，用于将一位神圣的灵体召至现世。玛加萨·野性图腾为它施加魔法，以便在千针石林的黑云峰使用。",kw={"阿利卡拉","黑云峰","火岩粉","莫特加·火鬃","神圣的生命之火","千针石林","白沙岗哨"},ang={["class:Shaman"]="身为萨满祭司，你能看出元素火焰与灵魂守护如何结合，唤醒沉睡的先祖之灵。",["race:Tauren"]="身为牛头人，你知道仪式粉末可以点燃安葬死者的火焰，神圣的传统与守护部族领袖的职责在此交汇。"},sec={{t="召唤的火花",b="火岩粉将萨满魔法带入黑云峰顶的圣火之中。玛加萨·野性图腾在雷霆崖的长者高地将它托付给旅人。将粉末撒入安放死者的神圣火盆，便会召出阿利卡拉，一条满怀复仇之心的飞蛇。"},{t="不祥的预兆",b="玛加萨·野性图腾制定了使用火岩粉的仪式。她认为，牛头人习俗的变化惊动了古老的灵魂，使它们开始追猎大酋长凯恩·血蹄，因此她为粉末施加魔法，要将幽灵引出来并消灭。粉末召出了凶猛的飞蛇，但这场遭遇仍留下了疑问：阿利卡拉究竟为何被惊动。"}},faq={{q="火岩粉有什么用途？",a="在千针石林的黑云峰，将火岩粉撒入神圣的生命之火。火焰随即会召出阿利卡拉，那条满怀复仇之心的灵蛇。",al={"火岩粉用途","为什么需要火岩粉","火岩粉有什么作用"}},{q="是谁为粉末施加了魔法？",a="玛加萨·野性图腾在雷霆崖的长者高地，将采集来的火岩龙舌兰施以魔法，制成精炼的粉末。白沙岗哨的莫特加·火鬃此前传来了阿利卡拉的消息。",al={"谁制作了火岩粉","谁为火岩粉施加了魔法"}},{q="粉末需要在哪里使用？",a="将粉末撒入黑云峰内一座孤立的墓葬石峰上的神圣火坑，那里高悬于千针石林的盐碱峡谷之上。",al={"火岩粉位置","火岩粉撒在哪里","火岩粉在哪里使用"}},{q="为什么必须召唤阿利卡拉？",a="玛加萨·野性图腾担心，牛头人传统的变化激怒了阿利卡拉，而这条飞蛇可能正在跟踪凯恩·血蹄。她要求在凯恩受到伤害之前，将阿利卡拉召出并杀死。",al={"为什么召唤阿利卡拉","为什么与阿利卡拉战斗"}}},fp="15,164,20.287.0,15.324.1,33.156.0,43.164.0,38.153.0,36.192.0"}
P.entries["item:insane-scribbles"] = {n="令人发狂的书页",s="在黑海岸，邪教徒随身携带着从暮光之书上撕下的令人发狂的书页，那是一部黑暗典籍的残页。游移的文字与扭曲的卷纹令人头晕目眩，精神紧绷。古老的森林守护者研究这些残页，试图查明暮光之锤的动机。",h="在黑海岸，邪教徒随身携带着从暮光之书上撕下的令人发狂的书页，那是一部黑暗典籍的残页。游移的文字与扭曲的卷纹令人头晕目眩，精神紧绷。古老的森林守护者研究这些残页，试图查明暮光之锤的动机。",kw={"黑海岸","令人发狂的书页","疯狂","上古之神","安努","暮光之书","暮光之锤"},ang={["class:Priest"]="身为牧师，你或许能认出，这些扭曲的字迹是一股危险的疯狂冲击，与 Light 的澄明相悖。",["race:NightElf"]="身为暗夜精灵，你知道暮光之锤的遗物威胁着黑海岸古老的安宁与神圣的土地。"},sec={{t="令人发狂的手稿",b="阅读暮光之书可能危及凡人的心智。字迹在羊皮纸上蠕动，优美的卷纹在读者眼前扭曲成怪诞的图像。哪怕只撕下一张被称为令人发狂的书页的纸页，也会让携带者头晕目眩，辨不清方向。尽管文字难以理解，羊皮纸仍嗡鸣着原始而极其古老的魔力，与深埋于艾泽拉斯地下已久的黑暗力量相连。"},{t="古树的线索",b="主持古树之林事务的古树安努正在研究这些书页，寻找黑海岸遭受侵蚀的线索。安努认出，附着在羊皮纸上的混乱能量出自上古之神之手。卡利姆多的守护者试图拼合这些书页，查明暮光之锤为何聚集在迷雾笼罩的海岸。"}},faq={{q="试着阅读这些书页会怎样？",a="这些文字很难译读。看向羊皮纸时，字母会游移，周围的纹饰会扭曲成可怕的形状，让试图解读它们的人突然感到眩晕，精神疲惫。",al={"阅读令人发狂的书页","文字写了什么","能否读懂书页"}},{q="这些书页是从哪里撕下来的？",a="这些书页撕自暮光之书，那是在黑海岸活动的暮光之锤邪教徒持有的一部邪恶魔典。",al={"书页来自哪里","暮光之书 来源"}},{q="谁能理解或研究这些书页？",a="知识古树安努正在检查找回的羊皮纸。凭借数百年积累的知识，安努感知到凝结于墨迹中的古老原始魔力，并试图查明邪教在这片地区的目的。",al={"谁想要书页","安努 书页"}},{q="羊皮纸散发着怎样的力量？",a="羊皮纸涌动着混乱而原始的魔力，与暮光之锤崇拜的黑暗神祇上古之神相连。",al={"书页中有什么魔法","魔法类型"}}},fp="16,246,22.397.0,22.356.1,48.213.0,37.122.0,42.200.0,47.123.0"}
P.entries["item:inscribed-bark"] = {n="刻字的树皮",s="在泰达希尔，刻字的树皮向大德鲁伊范达尔·鹿盔传递着世界之树的近况。神谕之树托它带去有关枝桠状况与林中威胁的消息。",h="在泰达希尔，刻字的树皮向大德鲁伊范达尔·鹿盔传递着世界之树的近况。神谕之树托它带去有关枝桠状况与林中威胁的消息。",kw={"塞纳里奥议会","达纳苏斯","范达尔·鹿盔","刻字的树皮","神谕之树","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，你认出刻字的树皮是一位古老盟友传来的紧急消息，讲述着这棵年轻的世界之树脆弱的平衡，以及困扰它的种种病患。",["race:NightElf"]="身为Kaldorei，你知道，古老树皮上传递的消息将自然与它的守护者紧密相连，也将荒野中的林地与达纳苏斯的大理石露台联系在一起。"},sec={{t="来自神谕的消息",b="神谕之树将刻字的树皮送往达纳苏斯的塞纳里奥议会。你将鹰身人赶出巢穴后，这棵古树便将消息交给了你，因为它不放心让普通信使走过泰达希尔那些受到污染的小径。这份报告向大德鲁伊范达尔·鹿盔讲述了近期的胜利，以及依旧笼罩着森林的深重枯萎。"}},faq={{q="刻字的树皮是什么？",a="刻字的树皮承载着神谕之树送给达纳苏斯的大德鲁伊范达尔·鹿盔的一份报告，讲述了枝桠的健康状况与面临的危险。",al={"刻字的树皮是什么","神谕之树的树皮","刻字的树皮用途"}},{q="这是谁送来的消息，又为何送来？",a="你将鹰身人赶出巢穴后，神谕之树便将刻字的树皮交给了你。它不放心让普通信使穿过危机四伏的林间小径，于是将报告托付给了一位已经证明自身能力的旅人。",al={"谁在树皮上刻字","谁给予刻字的树皮","神谕之树的信使"}},{q="大德鲁伊范达尔·鹿盔对这份消息有何反应？",a="范达尔承认，清除鹰身人带来了喘息之机，但他表示，更深层的问题依然存在。这份报告再次勾起了他的忧虑：他在泰达希尔所做的一切，能否让暗夜精灵重获失去的永生。",al={"范达尔对树皮的反应","范达尔如何评价树皮"}}},fp="14,166,25.352.0,23.152.0,31.202.0,58.213.1"}
P.entries["item:intact-raptor-horn"] = {n="完整的迅猛龙角",s="在贫瘠之地的稀树草原上，人们猎杀迅猛龙，获取完整的龙角。棘齿城的麦伯克·米希瑞克斯想要这些龙角，用来实施一个源于迅猛龙智慧传闻的计划。",h="在贫瘠之地的稀树草原上，人们猎杀迅猛龙，获取完整的龙角。棘齿城的麦伯克·米希瑞克斯想要这些龙角，用来实施一个源于迅猛龙智慧传闻的计划。",kw={"完整的龙角","伊沙姆哈尔","麦伯克·米希瑞克斯","迅猛龙角","棘齿城","智慧饮料","赤鳞镰爪龙","“跳跃者”塔克"},ang={["class:Hunter"]="身为猎人，若想取得一只完整的龙角作为战利品，就得干净利落地杀死稀树草原上最凶猛的一些掠食者。",["profession:Cooking"]="身为厨师，你可能会听说麦伯克打算把龙角磨成粉末，用来泡酒。讲求实用的野外生存者更愿意用迅猛龙的身体部位制作工具，而非烹调美味。"},sec={{t="可疑的原料",b="猎人珍视迅猛龙的皮、爪和战利品，但在野外想取得完整的龙角却更难。麦伯克·米希瑞克斯是棘齿城一位古怪的地精炼金师，他相信贫瘠之地的迅猛龙比其他地方的同类更加狡猾。他怀疑它们的智慧就藏在角里。麦伯克希望把完整的龙角磨碎，熬制成滋补药剂，将那所谓的天才头脑装进瓶里，制成饮料出售。"},{t="潜踪猎群",b="适合酿制饮料的龙角必须取自格外凶猛的掠食者，随便一只年幼的迅猛龙可不行。赤鳞镰爪龙在南部平原和靠近灰谷的北部边境游荡。“跳跃者”塔克和行踪难觅的伊沙姆哈尔是草原上赫赫有名的凶兽，它们粗壮的角能在狩猎的搏斗中保持完整。"}},faq={{q="谁想要这些完整的迅猛龙角？",a="麦伯克·米希瑞克斯是棘齿城的地精商人，一心想成为酿酒师，正在收集完整的龙角。他相信这些龙角是他下一款快速致富产品的关键。",al={"谁需要迅猛龙角","龙角买家","谁收购迅猛龙角"}},{q="为什么龙角必须完整？",a="麦伯克打算把完整的龙角磨成细粉，供人服用。猎人会丢弃有缺口或折断的龙角，或认为它们已经失效，因为这些角不再具备他希望用于配方的全部效力。",al={"为何要完整","破碎的龙角"}},{q="哪些迅猛龙长着这样的角？",a="贫瘠之地最北端和最南端的成年赤鳞镰爪龙长着这样的角。伊沙姆哈尔和“跳跃者”塔克等恶名昭彰的独特迅猛龙也有。",al={"哪里掉落龙角","哪些迅猛龙","谁掉落完整的龙角"}},{q="迅猛龙角真的能让人变聪明吗？",a="贫瘠之地的迅猛龙在群体行动中表现出非同寻常的狡诈与协作能力，但还没有人证明它们的智慧藏在角里，或是能通过饮料传给别人。",al={"智慧饮料有效吗","迅猛龙聪明吗","迅猛龙的智慧"}}},fp="18,157,25.376.0,19.322.0,36.152.0,35.210.0,25.168.0,42.162.0"}
P.entries["item:intrepid-strongbox-key"] = {n="无畏号的保险箱钥匙",s="在无畏号的残骸上，哈林多尔船长仍守着自己保险箱的钥匙。这把锈铁钥匙曾将一件神秘物品锁在这艘于湿地近海遭难的联盟船只上。",h="在无畏号的残骸上，哈林多尔船长仍守着自己保险箱的钥匙。这把锈铁钥匙曾将一件神秘物品锁在这艘于湿地近海遭难的联盟船只上。",kw={"哈林多尔船长","受诅咒的船员","戈罗林·钢眉","无畏号","沉船","保险箱","第三舰队","湿地"},ang={["class:Priest"]="身为牧师，你可以将这件受诅咒的神器带给米奈希尔港的戈罗林·钢眉，请他净化，让船员们的灵魂摆脱折磨。",["faction:Alliance"]="身为联盟的一员，你知道这把钥匙属于第三舰队的一位指挥官，这支舰队在米奈希尔港近海覆灭。对港口的幸存者来说，舰队的覆灭至今仍是一道未愈的伤口。"},sec={{t="船长的秘密",b="无畏号随第三舰队一同在湿地近海沉没，船员们化作了受诅咒的亡魂，不得安息。哈林多尔船长看守着船上沉重保险箱中的一件神秘物品。如今，他的鬼魂仍在浸水的甲板上游荡，紧握着那把能打开保险箱的锈铁钥匙。"},{t="斩断束缚",b="哈林多尔船长的钥匙能打开无畏号的保险箱，箱中受诅咒的遗物让船员们始终无法摆脱折磨。可以将这件遗物带给米奈希尔港的矮人牧师戈罗林·钢眉，请他净化。"}},faq={{q="谁带着无畏号的保险箱钥匙？",a="哈林多尔船长带着这把钥匙，在湿地西北海岸外北侧沉船的上层甲板上踱步。",al={"谁有钥匙","无畏号钥匙掉落","哈林多尔钥匙"}},{q="无畏号的保险箱钥匙能打开什么？",a="这把钥匙能打开无畏号的保险箱，它位于船长甲板下方破裂的船体内，浸没在水中。",al={"能打开什么","无畏号保险箱位置","箱子在哪"}},{q="为什么保险箱一直锁着？",a="哈林多尔船长将一件受诅咒的物品锁在箱中，以确保它隐秘而安全。舰队沉没后，物品中挥之不去的邪恶将船员们束缚在亡灵之躯中。",al={"箱中有什么","为何上锁"}},{q="谁能净化箱中受诅咒的物品？",a="打开箱子后，米奈希尔港的矮人牧师戈罗林·钢眉可以净化这件受诅咒的神器。",al={"谁能净化","戈罗林·钢眉箱子"}}},fx={b4277111={q="什么是无畏号的保险箱钥匙？",a="这是一把生锈的船钥匙，由船长哈林多尔保管在沉船无畏号上。即使死后，这位被诅咒的船长仍严密看守着钥匙，因为它是打开船体残骸中那只加固保险箱的唯一办法。",al={"无畏号的保险箱钥匙","这把钥匙是什么","无畏号钥匙"}},["90ec2e74"]={q="为什么需要无畏号的保险箱钥匙？",a="必须用这把钥匙打开无畏号的保险箱，取回锁在里面的黑暗遗物。大副菲兹莫斯认为，这件被藏起来的物品招致了可怕的诅咒，使哈林多尔和他的船员被束缚在沉船上。打开箱子是解除诅咒的第一步。",al={"为什么需要这把钥匙","为什么要拿到这把钥匙","无畏号钥匙的用途"}}},fp="22,188,18.260.0,17.194.1,39.122.0,42.110.0,34.154.0,49.114.0"}
P.entries["item:invisibility-liquor"] = {n="隐形水",s="梅贝尔·马科伦借助隐形水避开家人的视线，去与托米·乔·斯通菲尔德相会。两家之间依然积怨深重。",h="梅贝尔·马科伦借助隐形水避开家人的视线，去与托米·乔·斯通菲尔德相会。两家之间依然积怨深重。",kw={"水晶海藻","艾尔文森林","隐形水","梅贝尔·马科伦","斯通菲尔德的仇怨","脱身","托米·乔·斯通菲尔德"},ang={["class:Mage"]="身为法师，你知道肯瑞托的奥术师要花费多年时间，才能掌握幻术和隐形法术。艾尔文的当地人却用发酵的烈酒和浸透水的海藻，制出了粗糙的仿品。",["race:Human"]="身为人类，你知道斯通菲尔德和马科伦这两个乡间家族的仇怨已经到了极其激烈的地步。"},sec={{t="苦命恋人的药水",b="托米·乔·斯通菲尔德想与梅贝尔·马科伦私下相会。但两家的仇怨让他们无法往来，亲人们也盯得很紧。寻常的掩人耳目之法并不管用。隐形水能让饮用者悄无声息地穿过双方争执的农田。"},{t="艾尔文的偏门炼金术",b="这酒用到了鱼人栖息水域中的水晶藻叶。梅贝尔·马科伦喝下隐形水，身形便从视野中消失。随后，她悄悄溜进树林，前去秘密相会。"}},faq={{q="隐形水有什么作用？",a="隐形水能让饮用者短暂隐形。它的魔力蕴藏在酒液之中。",al={"酒的效果","隐形药酒","有什么作用"}},{q="谁会使用隐形水？",a="梅贝尔·马科伦得到隐形水后，便能避开家人的视线，与托米·乔·斯通菲尔德相会，尽管两家仍有仇怨。",al={"谁喝","梅贝尔·马科伦的酒"}},{q="这种酒是如何酿制的？",a="这种酒用到了从艾尔文森林的河床和湖岸采集的水晶藻叶。鱼人会囤积这些植物。",al={"酒的原料","水晶海藻酒"}},{q="玩家能自己喝下隐形水吗？",a="不能。隐形水是为梅贝尔·马科伦准备的，好让她悄悄避开家人。",al={"能自己喝吗","饮用隐形水"}}},fx={["19edabb3"]={q="隐形水是什么？",a="隐形水是一种在艾尔文森林调制的强效炼金药剂。它表面上是一种酒，却蕴含着源自水晶海藻叶的魔力，能让饮用者暂时完全避开凡人的视线。",al={"隐形水是什么","隐形水背景","隐形水是哪种饮料"}},f0e7bc08={q="为什么有人需要隐形水？",a="人们寻找这种药剂，是为了一段被禁止的恋情。梅贝尔·马科伦和托米·乔·斯通菲尔德的家族在艾尔文森林结下了深仇，两人因此被迫分隔两边，而这剂药水能让梅贝尔悄然避开亲人的严密看守，去探望心上人。",al={"为什么需要隐形水","谁需要隐形水","为什么想要这种药剂"}}},fp="19,148,32.249.0,25.180.1,33.110.0,33.143.0,23.120.0,53.91.0"}
P.entries["item:iron-pike"] = {n="铁矛",s="湖畔镇需要铁矛来修复止水湖上的桥。从暴风城运来的货物被赤脊山豺狼人劫走，镇上因此缺少铁料。",h="湖畔镇需要铁矛来修复止水湖上的桥。从暴风城运来的货物被赤脊山豺狼人劫走，镇上因此缺少铁料。",kw={"止水湖上的桥","工头奥斯洛","铁矛","铁铆钉","湖畔镇","赤脊山豺狼人","赤脊山"},ang={["faction:Alliance"]="作为一名联盟旅人，夺回被盗的补给有助于保障湖畔镇各处渡口的安全，并巩固暴风城的东部边境，抵御黑石的侵袭。",["profession:Blacksmithing"]="作为铁匠，你能看出战争给当地同行带来的压力：他们所有的生铁都得用来打造武器。"},sec={{t="被劫的商队货物",b="近期遭到黑石兽人袭击后，湖畔镇耗尽了金属储备，用来锻造护甲、刀剑和弹药。工匠们向暴风城请求增援铁料，但赤脊山豺狼人在途中劫持了商队。他们将一箱箱铁矛和铆钉搬进北方的山丘，导致止水湖上的桥的修复工程停滞。"},{t="重建桥梁",b="工头奥斯洛负责桥梁的重建，需要找回被盗的五金材料。没有沉重的铁矛加固石料和木材构成的桥架，湖畔镇通往北方道路的交通就难以完全恢复，也容易再遭入侵。"}},faq={{q="豺狼人为什么带着建筑用的铁矛？",a="豺狼人伏击了一支从暴风城前往湖畔镇的补给商队，随后带着一箱箱偷来的建筑物资，分散逃入赤脊山的山丘，其中就有铁矛和铆钉。",al={"豺狼人为什么有铁矛","豺狼人的铁矛从哪来"}},{q="湖畔镇有谁需要这些铁矛？",a="工头奥斯洛需要这些铁矛来重建横跨止水湖的止水湖上的桥。在近期的兽人袭击中，湖畔镇将储备的铁料熔铸成了武器和护甲，已无余铁可用。",al={"谁需要铁矛","工头奥斯洛铁矛"}},{q="去哪里能找回这些铁矛？",a="赤脊山豺狼人将铁矛存放在湖畔镇北方丘陵和山脊间的营地中。",al={"哪里找铁矛","铁矛位置"}},{q="湖畔镇为什么不能自己锻造铁矛？",a="湖畔镇在对抗黑石兽人时耗尽了当地的铁料，将金属熔铸成了剑、子弹和防具。镇上不得不向暴风城请求新的建筑用铁料。",al={"湖畔镇为什么订购铁料","湖畔镇缺铁"}}},fx={c6b2b586={q="什么是铁矛？",a="铁矛是一种沉重的铁制建筑桩，用来加固石砌结构。工头奥斯洛和他的工人需要这些结实的结构桩，来修复并稳固湖畔镇损毁的静水桥。",al={"什么是铁矛","铁矛是什么","赤脊山的铁矛"}}},fp="9,162,20.307.0,19.266.0,47.197.0,40.193.0,40.89.0,55.180.0"}
P.entries["item:iron-pommel"] = {n="铁质柄头",s="在灰谷，铁质柄头是达图尔的魔棒最后一块尚未寻回的部件。法杖由早已逝去的巫师达图尔制成，阿斯特兰纳的暗夜精灵正寻找它，以减缓熊怪对族人的袭击。朵丹尼尔兽穴的德鲁伊曾妥善保管着柄头，直到他们的圣所被攻陷，所有人惨遭杀戮。",h="在灰谷，铁质柄头是达图尔的魔棒最后一块尚未寻回的部件。法杖由早已逝去的巫师达图尔制成，阿斯特兰纳的暗夜精灵正寻找它，以减缓熊怪对族人的袭击。朵丹尼尔兽穴的德鲁伊曾妥善保管着柄头，直到他们的圣所被攻陷，所有人惨遭杀戮。",kw={"灰谷","达图尔的魔棒","朵丹尼尔","铁质柄头","奥索的箱子","莱恩的净化","莎尔蒂恩"},ang={["class:Druid"]="身为德鲁伊，你可以缅怀朵丹尼尔那些陨落的德鲁伊，他们的神圣职责在林边空地的一场屠戮中终结。",["faction:Alliance"]="身为联盟的一员，寻回柄头便能让Dartol's Rod离完整更近一步，为灰谷抵御日渐蔓延的腐化提供重要助力。"},sec={{t="罹难结社的重担",b="为了守护其神秘力量，达图尔的魔棒被拆散，分藏在灰谷各处。通往南方贫瘠之地的道路附近，一群暗夜精灵德鲁伊负责保管铁质柄头。他们的结社在朵丹尼尔兽穴惨遭屠戮，庇护所也化为一片死寂的废墟。柄头在这场浩劫中消失，被如今游荡在这片亵渎林地中的冒泡软泥怪吞入体内。"},{t="从泥沼中寻回",b="柄头藏在碎木岗哨以南受污染的洼地中，装在一个坚固的箱子里。搜寻那些腐化软泥怪的人，会在一只软泥怪的酸性躯体中找到完好无损的箱子。铁质柄头是重铸达图尔的魔棒所需的最后一个部件。"}},faq={{q="铁质柄头有什么用途？",a="铁质柄头是重新组装达图尔的变形魔棒所需的最后一个部件。将它带给月亮井旁的莎尔蒂恩，她便能修复这件古老的神器，帮助减缓熊怪对灰谷暗夜精灵的袭击。",al={"铁质柄头用途","为什么需要铁质柄头","铁质柄头有什么用"}},{q="柄头最初由谁保管？",a="通往贫瘠之地的道路附近，一群暗夜精灵德鲁伊负责保管柄头。法杖尚未重新拼合，他们的结社便惨遭屠戮，庇护所也沦为废墟。",al={"谁守护柄头","谁保管铁质柄头","朵丹尼尔德鲁伊"}},{q="在哪里能找到柄头？",a="柄头锁在一个箱子里，箱子就在主路以东受污染洼地中的一只腐化软泥怪体内。这片洼地位于碎木岗哨以南、贫瘠之地边界以北。",al={"铁质柄头位置","铁质柄头在哪里","哪里获得铁质柄头"}},{q="我该把柄头交给谁？",a="将柄头带给莎尔蒂恩，她是一位照料着伊瑞斯湖以东月亮井的树妖。她知晓重铸达图尔的变形魔棒所需的仪式。",al={"交还铁质柄头","铁质柄头交到哪里","谁需要柄头"}}},fx={["9716c2ef"]={q="什么是铁质柄头？",a="铁质柄头是重组达托尔之杖所需的最后一件遗失部件。这根法杖由早已逝去的法师达托尔打造。在遭遇悲剧之前，居住在朵丹尼尔兽穴的德鲁伊受托保管这块沉重的金属部件。庇护所沦陷于腐化与暴力之中时，柄头遗失了，最终被锁在荒野中的一只旧箱子里，等待有能力的人将它寻回。",al={"什么是铁质柄头","铁质柄头的背景","达托尔之杖的柄头是什么"}}},fp="11,302,23.366.0,23.246.1,33.213.0,30.169.0,26.199.0,29.136.0"}
P.entries["item:iron-rivet"] = {n="铁铆钉",s="从暴风城运来的铁铆钉如今散落在止水湖北面的豺狼人营地里。工头奥斯洛需要它们来修复湖畔镇受损的桥梁。",h="从暴风城运来的铁铆钉如今散落在止水湖北面的豺狼人营地里。工头奥斯洛需要它们来修复湖畔镇受损的桥梁。",kw={"止水湖上的桥","工头奥斯洛","铁矛","铁铆钉","湖畔镇","赤脊山豺狼人","赤脊山"},ang={["faction:Alliance"]="追回被盗的补给有助于湖畔镇修复基础设施，并遏制豺狼人对镇子的威胁。",["profession:Blacksmithing"]="这些粗重的紧固件在暴风城锻造，用于大型建筑工程，包括石木结构的桥梁。"},sec={{t="被劫走的商队货物",b="黑石兽人进攻时，湖畔镇储备的铁都被用来打造武器和护甲。攻势减弱后，工头奥斯洛向暴风城请求物资，以修复受损的止水湖上的桥。商队还没抵达镇上，就遭到了赤脊山豺狼人的伏击。它们将货车和驮兽拖进止水湖北面的山丘，把铁铆钉和铁矛散放在各处营地中。"},{t="修复桥梁",b="止水湖上的桥需要用粗重的铁铆钉将石木框架固定在一起，才能承受车辆和行人的重量。没有这些铆钉，工头奥斯洛就无法安全地进行修缮。这座桥连接着湖畔镇与西部的山谷，修复它将有助于巩固镇子的外围防线，抵御进一步的入侵。"}},faq={{q="铁铆钉有什么用途？",a="工头奥斯洛需要铁铆钉来修复湖畔镇受损的止水湖上的桥。桥上原有的铁料在与黑石兽人交战期间被熔掉了。",al={"铁铆钉用途","为什么需要铁铆钉","铁铆钉有什么用"}},{q="豺狼人为什么会有这些铆钉？",a="赤脊山豺狼人伏击了一支来自暴风城的补给商队，抢走了运载的建筑物资。铆钉和铁矛如今都在湖畔镇北面的豺狼人营地里。",al={"豺狼人为什么有铆钉","豺狼人如何得到铁铆钉","谁偷走了铆钉"}},{q="湖畔镇最初为什么会缺铁？",a="兽人入侵期间，湖畔镇的守军熔掉了镇上储备的铁，用来制造剑、子弹和护甲。",al={"湖畔镇缺铁","湖畔镇为什么没有铁"}},{q="谁在寻找这些铆钉？",a="负责止水湖上的桥修复工作的工头奥斯洛正在寻找这些铆钉。",al={"谁需要铁铆钉","谁收铁铆钉"}}},fx={["0d91405a"]={q="什么是铁铆钉？",a="铁铆钉是一种结实的金属紧固件，由王国锻造，用于重型建筑工程。暴风城曾向湖畔镇运送一批铁铆钉，帮助重建镇上损毁的基础设施，尤其是至关重要的静水桥。",al={"铁铆钉是什么","铁铆钉说明"}},a8a8e120={q="这些铁铆钉从哪里来？是谁制造的？",a="这些铆钉是暴风城派出的救援车队所运物资的一部分，车队还载有运往赤脊山的原材料和建筑用品。车队尚未抵达湖畔镇便遭到赤脊山豺狼人的伏击与洗劫，铁料散落在他们山坡上的营地里。",al={"铁铆钉从哪里来","谁制造了铁铆钉","铁铆钉的来源"}}},fp="10,141,20.378.0,18.284.0,30.169.0,36.153.0,46.111.0,32.90.0"}
P.entries["item:iron-shaft"] = {n="铁杆",s="在费伍德森林附近，铁杆静静躺在一只上锁的箱子里。它是达图尔的魔棒的一个部件，泰洛尼斯正寻找它，以减缓熊怪对灰谷的袭击。",h="在费伍德森林附近，铁杆静静躺在一只上锁的箱子里。它是达图尔的魔棒的一个部件，泰洛尼斯正寻找它，以减缓熊怪对灰谷的袭击。",kw={"灰谷","发狂的古树","达图尔的魔棒","费伍德森林","铁杆","莱恩的净化","莎尔蒂恩","枯萎的古树","木制钥匙"},ang={["class:Druid"]="作为德鲁伊，重新组装Dartol's Rod呼应着你照料大地的职责，让你用被遗忘的工具治愈这片土地。",["race:NightElf"]="作为暗夜精灵，找回铁杆意味着你必须杀死那些你所珍爱的森林树人，它们已被费伍德森林渗出的恶魔瘟疫腐化。"},sec={{t="达图尔的魔棒的部件",b="达图尔制成了这根法杖，后来它的部件散落在灰谷各处。其中一个部件交由朵丹尼尔的德鲁伊保管。铁杆是这根法杖坚固的金属杖芯，存放在灰谷北部边界附近一片林间空地的上锁箱子里，那里靠近费伍德森林。"},{t="森林的枯萎",b="铁杆所在箱子的钥匙在那些曾经照料这片树林的树人身上。来自费伍德森林的恶魔腐化使疯狂的古树和枯萎的古树陷入了疯狂。树妖莎尔蒂恩请求旅人找回铁杆，以便重铸达图尔的魔棒，完成泰洛尼斯的工作。"}},faq={{q="铁杆有什么用途？",a="铁杆是断裂的达图尔的变形魔棒的一个部件。莎尔蒂恩正在寻找这些部件，以便重新组装法杖，完成泰洛尼斯减缓熊怪袭击灰谷的工作。",al={"铁杆用途","这根铁杆是什么","为什么需要铁杆"}},{q="在哪里能找到铁杆？",a="铁杆位于灰谷北部，通往费伍德森林的道路西侧，一片林间空地上的上锁箱子里。",al={"铁杆位置","寻找铁杆","箱子在哪里"}},{q="如何打开装着铁杆的箱子？",a="木制钥匙可以打开箱子。这把钥匙由遭到腐化的疯狂的古树和枯萎的古树携带，它们徘徊在林中树居东北方的树林里。",al={"如何打开箱子","箱子钥匙","铁杆钥匙"}},{q="谁在寻找铁杆？",a="莎尔蒂恩是灰谷中部一口月亮井旁的树妖，她指引旅人收集达图尔的变形魔棒的部件，帮助净化森林。",al={"谁需要铁杆","铁杆任务给予者"}}},fx={ad78a81b={q="什么是铁杆？",a="铁杆是达托尔之杖的重要组成部分，这件遗物由达托尔打造。法杖的部件散落在灰谷各处，而这根铁杆被锁在费伍德森林边界附近的一只隐秘箱子里，钥匙则由附近被腐化的树人持有。",al={"什么是铁杆","铁杆物品","达托尔之杖的铁杆"}},["45340e91"]={q="铁杆从哪里来？是谁制造的？",a="它是达托尔打造的一根魔法杖的一部分。后来，法杖的部件四散而失，这根铁杆被收在一只破旧的箱子里，箱子藏在费伍德森林附近的一处林间空地上；持有箱子钥匙的被腐化树人也间接守卫着它。",al={"谁制造了铁杆","铁杆的来源","达托尔的铁杆"}},["3705c59d"]={q="为什么要寻找铁杆？",a="莱恩·狼行者和莎尔蒂恩想要重新拼合达托尔之杖。特尔尼亚斯认为，这根法杖能够减缓灰谷暗夜精灵遭受的熊怪袭击。要重组这件遗物，就必须找齐失落的部件；这根结实的铁杆是法杖的中央握柄与核心，能将法杖的魔法宝石和柄头固定在一起。",al={"他们为什么要找铁杆","为什么要收集铁杆","寻找铁杆的任务原因"}}},fp="10,146,23.242.0,19.262.1,32.190.0,30.104.0,47.138.0,34.139.0"}
P.entries["item:ironband-s-progress-report"] = {n="铁环挖掘场的进度报告",s="在洛克莫丹东部，穴居人迫使勘察员基恩萨·铁环的挖掘工作陷入停顿。他在报告中请求增援爆破火药，尽管探险者协会几周前就已送出补给。",h="在洛克莫丹东部，穴居人迫使勘察员基恩萨·铁环的挖掘工作陷入停顿。他在报告中请求增援爆破火药，尽管探险者协会几周前就已送出补给。",kw={"爆破火药","探险者协会","铁环","吉恩·角盔","洛克莫丹","勘察员塔伯斯·雷矛","塞尔萨玛","穴居人"},ang={["profession:Mining"]="身为矿工，你知道爆破火药能炸开坚硬的岩石。你也知道，在穴居人的领地上丢失补给有多危险。",["race:Dwarf"]="身为从事勘探或采矿的矮人，你知道在卡兹莫丹挖掘古老泰坦遗址的危险。"},sec={{t="请求增援火药",b="吉恩·角盔在塞尔萨玛收到这份急件，并将其转交给铁炉堡的探险者协会。铁环报告说，工作已陷入停顿，并请求增援重型军火。联盟的领导者们对此十分困惑。他们几周前就给他送去了充足的爆破火药，如今却不知道这些火药去了哪里。"}},faq={{q="铁环挖掘场的进度报告是什么？",a="勘察员基恩萨·铁环的报告描述了穴居人如何干扰他在洛克莫丹的挖掘工作，并请求增援爆破火药。",al={"进度报告","铁环的报告","这份报告是什么"}},{q="谁接收这份报告？",a="吉恩·角盔在塞尔萨玛收到报告，随后将其送交给铁炉堡探险者协会总部的勘察员塔伯斯·雷矛。",al={"谁接收报告","报告交给谁","递交进度报告"}},{q="铁环为什么需要更多爆破火药？",a="铁环说，他的挖掘工作需要爆破火药，不过附近穴居人的袭击也可能让炸药派上防御的用场。角盔和雷矛认为，他们几周前就给他送去了充足的火药。",al={"为什么需要爆破火药","火药出了什么事","火药短缺"}},{q="勘察员塔伯斯·雷矛对报告有何反应？",a="勘察员塔伯斯·雷矛对工作进展如此缓慢感到十分愤怒。铁环竟然没有提及先前送出的大批物资，这让他十分困惑，也让他想知道那些失踪的爆破火药去了哪里。",al={"雷矛的反应","雷矛生气了吗"}}},fx={["9e6c80e6"]={q="铁环挖掘场的进度报告来自哪里，由谁撰写？",a="这份文件由勘察员基恩萨·铁环本人在洛克莫丹东部的挖掘场起草。他监督着艰难的挖掘工作，还要应对穴居人持续不断的骚扰，因此写下这份报告，正式汇报工程进展缓慢的情况，并将持续提出的物资需求记录在案。",al={"铁环挖掘场的进度报告是谁写的","铁环的报告是谁制作的","铁环的报告来自哪里"}},["2cf6b481"]={q="为什么有人需要铁环挖掘场的进度报告？",a="这份报告是塞尔萨玛的行政联络人员和铁炉堡的探险者协会总部所需的重要文件。没有这份详述挖掘场困境及穴居人干扰的正式报告，勘察员塔伯斯·雷矛等上级就不会批准调拨并运送新一批爆破火药。",al={"为什么需要铁环挖掘场的进度报告","为什么要带走铁环的报告","铁环挖掘场的进度报告用途"}}},fp="26,178,20.281.0,35.116.0,25.137.0,40.185.0,50.191.0"}
P.entries["item:ishamuhale-s-fang"] = {n="伊沙姆哈尔的牙齿",s="在陶拉祖营地，乔恩·星眼正等待着伊沙姆哈尔的牙齿，它来自贫瘠之地令人畏惧的赤鳞迅猛龙矛齿。这颗牙齿证明，猎人战胜了卡利姆多最致命的野生掠食者之一。",h="在陶拉祖营地，乔恩·星眼正等待着伊沙姆哈尔的牙齿，它来自贫瘠之地令人畏惧的赤鳞迅猛龙矛齿。这颗牙齿证明，猎人战胜了卡利姆多最致命的野生掠食者之一。",kw={"贫瘠之地","獠牙","伊沙姆哈尔","乔恩","迅猛龙","瑟格拉","矛齿","赤鳞","陶拉祖"},ang={["class:Hunter"]="身为猎人，取得Speartooth的獠牙是贫瘠之地的一项成长仪式。它考验你引诱、直面并战胜狡猾掠食者的本领。",["race:Tauren"]="身为牛头人，取得这颗牙齿意味着接纳掠食者的原始力量，同时保持自律与平衡。"},sec={{t="矛齿的战利品",b="在中部草原上，猎人们都畏惧伊沙姆哈尔，它是现存最凶猛的赤鳞迅猛龙。有人说，这个顶级掠食者杀戮是出于捕猎的狂热，而非饥饿。新鲜的斑马肉能将这头野兽引到棘齿城西北方一棵枯树旁的空地上，它在那里绝不留情。取得它巨大的獠牙，就能向部落的狩猎导师证明，旅人已经战胜了平原上的凶蛮。"},{t="节制的考验",b="在陶拉祖营地，乔恩·星眼从伊沙姆哈尔的牙齿中看到的不只是牙质与鲜血。在那里的牛头人看来，取得这颗牙齿，就意味着掠食者的凶猛力量传给了战胜它的猎人。接下来的考验是节制：猎人必须驾驭那股野蛮的怒火，而不能任它支配灵魂。"}},faq={{q="伊沙姆哈尔的牙齿是什么？",a="伊沙姆哈尔的牙齿是从伊沙姆哈尔身上取得的战利品，这头恶名昭彰的日鳞迅猛龙矛齿在贫瘠之地游荡。",al={"伊沙姆哈尔牙齿","矛牙獠牙","贫瘠之地迅猛龙獠牙"}},{q="谁想要伊沙姆哈尔的牙齿？",a="陶拉祖营地的乔恩·星眼想要这颗獠牙，这是狩猎试炼的一环，而试炼始于十字路口的瑟格拉·黑棘。",al={"伊沙姆哈尔的牙齿交给谁","交付伊沙姆哈尔的牙齿","伊沙姆哈尔的牙齿交到哪里"}},{q="如何找到野兽伊沙姆哈尔？",a="将一具新鲜的斑马尸体放在棘齿城西北方的一棵枯树附近，就能将伊沙姆哈尔从藏身处引出。",al={"如何让伊沙姆哈尔出现","召唤伊沙姆哈尔","伊沙姆哈尔在哪里"}},{q="对牛头人而言，取得这颗獠牙代表什么？",a="对牛头人而言，取得伊沙姆哈尔的牙齿意味着这头迅猛龙的传奇力量如今已融入猎人体内，而猎人必须以节制与荣誉运用这股力量。",al={"獠牙的意义","牛头人猎人仪式伊沙姆哈尔"}}},fp="17,199,20.409.0,22.293.1,26.117.0,28.129.0,34.105.0,52.166.0"}
P.entries["item:ivar-s-head"] = {n="伊瓦的头颅",s="在银松森林北部，伊瓦的头颅证明邪恶的伊瓦已死。兰妮·尤瑞克想要拿到这颗头颅，好让她受伤的兄弟奎恩安心养伤。",h="在银松森林北部，伊瓦的头颅证明邪恶的伊瓦已死。兰妮·尤瑞克想要拿到这颗头颅，好让她受伤的兄弟奎恩安心养伤。",kw={"亡灵哨兵","伊瓦农场","邪恶的伊瓦","伊瓦的头颅","奎恩·尤瑞克","兰妮·尤瑞克","银松森林"},ang={["faction:Horde"]="身为部落的一员，你知道，清除伊瓦这样的Scourge残余，可以保护那些穿过银松森林北部、前往瑟伯切尔的部落信使。",["race:Undead"]="身为被遗忘者斥候，你知道，野生食尸鬼是毫无心智的祸患。它们干扰军事侦察，威胁着洛丹伦刚刚建立的安全局面。"},sec={{t="斩断的威胁",b="兰妮·尤瑞克和奎恩·尤瑞克奉高级执行官哈德瑞克之命，在银松森林北部执行侦察任务，却在一处废弃农庄遭到邪恶的伊瓦伏击。这两名被遗忘者亡灵哨兵击退了这只狂野的食尸鬼，但奎恩被咬成重伤。兰妮留在破败的农场照顾他，无法放心离开，完成他们的任务。伊瓦被斩下的头颅证明，这只食尸鬼再也无法威胁这片庄园，让奎恩有时间在兰妮的照料下康复。"}},faq={{q="这是谁的头颅？",a="这颗头颅属于邪恶的伊瓦，一只凶残的食尸鬼，出没于银松森林北部一处名为伊瓦农场的废弃农庄。",al={"伊瓦是谁","伊瓦的头颅身份","伊瓦是什么"}},{q="兰妮·尤瑞克为什么想要伊瓦的头颅？",a="兰妮想要伊瓦已死的证据。这只食尸鬼将她的兄弟奎恩咬成重伤，在回去向高级执行官哈德瑞克复命之前，他需要时间安心养伤，不必担心再次遭到伏击。",al={"兰妮为何想要头颅","伊瓦的头颅交付","为何杀死伊瓦"}},{q="在哪里能找到邪恶的伊瓦？",a="邪恶的伊瓦潜伏在伊瓦农场破败的谷仓内，等待受伤的亡灵哨兵放松警惕。",al={"伊瓦位置","伊瓦在哪里"}}},fp="11,174,16.448.0,19.136.0,38.183.0,30.129.0"}
P.entries["item:iverron-s-antidote-item"] = {n="埃沃隆的解药",s="在幽影谷，埃沃隆的解毒剂必须在失效前送到一名年轻的暗夜精灵手中。迪兰妮亚·月光配制了这种药剂，用来对抗当地树林蜘蛛的致命毒液，但它的药效只能维持五分钟。",h="在幽影谷，埃沃隆的解毒剂必须在失效前送到一名年轻的暗夜精灵手中。迪兰妮亚·月光配制了这种药剂，用来对抗当地树林蜘蛛的致命毒液，但它的药效只能维持五分钟。",kw={"奥达希尔","迪兰妮亚·月光","埃沃隆","埃沃隆的解毒剂","幽影谷","蜘蛛毒素","泰达希尔","树林毒液"},ang={["profession:Herbalism"]="作为一名草药师，你能看出泰达希尔本土药材的不稳定性如何使某些药剂必须立即使用。",["race:NightElf"]="作为幽影谷的一名年轻暗夜精灵冒险者，你赶着将解药送给埃沃隆，这表明族人如何依靠迅速的行动和草药知识，对抗泰达希尔枝桠间的腐化。"},sec={{t="易失效的解药",b="迪兰妮亚·月光在奥达希尔为埃沃隆配制解毒剂，他是一名被树林蜘蛛咬伤的年轻暗夜精灵。药剂中的不稳定成分和草药催化剂使其只能保存五分钟。送药人必须赶往北面的树林洞穴，在药剂失效前将其送达。"}},faq={{q="埃沃隆的解毒剂有什么用途？",a="埃沃隆在幽影谷北部的树林蜘蛛洞穴外被蜘蛛咬伤并中毒，埃沃隆的解毒剂能为他解毒。",al={"解毒剂用途","埃沃隆的解毒剂有什么用"}},{q="为什么解毒剂有时间限制？",a="迪兰妮亚·月光说，这种容易失效的药剂在配制完成后只能维持五分钟的药效。之后，它的药用成分就会分解。",al={"为什么只有五分钟","解毒剂计时","为什么会过期"}},{q="是谁配制了解毒剂？",a="迪兰妮亚·月光是幽影谷奥达希尔的一名暗夜精灵治疗者，她用收集来的材料配制药剂，以挽救埃沃隆。",al={"谁配制了解毒剂","解毒剂配制者"}},{q="解毒剂过期后会怎样？",a="五分钟一过，药剂就会变质，不再有效。送药人必须返回奥达希尔，找迪兰妮亚·月光领取新配制的药剂。",al={"解毒剂已过期","计时结束"}}},fp="25,204,16.292.0,36.115.0,40.143.0,23.127.0,37.142.0"}
P.entries["item:jade-phial"] = {n="翡翠瓶",s="在多兰纳尔，科瑞萨斯·月怒将翡翠瓶托付给年轻的入门者。它盛装着泰达希尔月亮井中的圣水，用来补充德鲁伊在达纳苏斯的中央月亮井。",h="在多兰纳尔，科瑞萨斯·月怒将翡翠瓶托付给年轻的入门者。它盛装着泰达希尔月亮井中的圣水，用来补充德鲁伊在达纳苏斯的中央月亮井。",kw={"科瑞萨斯·月怒","大地之冠","多兰纳尔","翡翠瓶","月亮井","星风村","泰达希尔"},ang={["class:Druid"]="作为一名年轻的德鲁伊，携带翡翠瓶是你学习照料泰达希尔月亮井的早期一课，这些月亮井的生机需要长久的敬重与呵护。",["race:NightElf"]="作为暗夜精灵，你知道月亮井象征着kaldorei与Elune之间恒久的纽带。用翡翠瓶这样的容器照料月亮井，是一项神圣的职责。"},sec={{t="盛装圣水的容器",b="翡翠瓶用来采集星风村附近一口月亮井中的井水。泰达希尔的众多月亮井引导着月亮与自然的能量，这些能量对暗夜精灵社会和德鲁伊的信仰意义重大。德鲁伊会不时从巨树枝桠各处的月亮井中取水，补充他们在达纳苏斯的中央月亮井。科瑞萨斯·月怒将翡翠瓶托付给年轻的入门者，让他们用它采集纯净的井水，同时不扰动月亮井的灵力。"}},faq={{q="翡翠瓶有什么用途？",a="翡翠瓶用来采集星风村外那口月亮井中的圣水。装满后，将它交还给多兰纳尔的科瑞萨斯·月怒，以便德鲁伊补充他们在达纳苏斯的月亮井。",al={"翡翠瓶用途","为什么需要翡翠瓶","翡翠瓶有什么用"}},{q="谁提供翡翠瓶？",a="科瑞萨斯·月怒是多兰纳尔的一位暗夜精灵德鲁伊，他会向参与名为大地之冠的仪式的冒险者提供翡翠瓶。",al={"谁给翡翠瓶","哪里获得翡翠瓶","科瑞萨斯·月怒 翡翠瓶"}},{q="瓶中的井水最终会送往何处？",a="瓶中采集的井水会被送往达纳苏斯，用来补充由塞纳里奥德鲁伊维护的中央月亮井。",al={"月亮井水送往哪里","翡翠瓶目的地","谁使用这些井水"}}},fp="10,185,26.442.0,32.207.0,28.143.0,44.125.0"}
P.entries["item:jennea-s-flask"] = {n="詹妮亚的瓶子",s="在暴风城的巫师圣殿，詹妮亚·坎农派学徒前往明镜湖取水。他们带回水样，用于奥术研究。",h="在暴风城的巫师圣殿，詹妮亚·坎农派学徒前往明镜湖取水。他们带回水样，用于奥术研究。",kw={"艾尔文森林","詹妮亚·坎农","詹妮亚的瓶子","明镜湖","暴风城","水样","巫师圣殿"},ang={["class:Mage"]="作为一名法师，携带这个瓶子是你为巫师圣殿执行的最初几项野外任务之一。这项任务考验你能否谨慎开展奥术研究，并留意魔网能量线的变化。"},sec={{t="奥术研究的容器",b="遍及艾泽拉斯的魔法冲突，使奥术能流偏离了古老的通道。詹妮亚·坎农想了解这些变化对艾尔文森林造成了怎样的影响。她给有潜力的学徒一个玻璃瓶，派他们前往暴风城城门西南方的明镜湖瀑布底部。\n\n瓶子能保护水样，让它安然送回巫师圣殿。在那里，詹妮亚可以检查水样中是否存在奥术扰动。"},{t="守护湖水",b="有了詹妮亚的瓶子，暴风城的法师就能检验魔网能量线的变化是否污染了明镜湖。水中的有害魔法可能使周围的生灵，以及任何饮用湖水的人染上怪病。一份水样或许就能在受污染的水流蔓延至乡野之前，揭示其中的魔法残留。"}},faq={{q="詹妮亚的瓶子有什么用途？",a="用詹妮亚的瓶子在艾尔文森林的明镜湖瀑布处取水。",al={"瓶子用途","瓶子有什么用","瓶子的用法"}},{q="谁会给你这个瓶子？",a="暴风城巫师圣殿的法师训练师詹妮亚·坎农会给你这个瓶子。",al={"谁给瓶子","詹妮亚的瓶子来源"}},{q="詹妮亚为什么想要明镜湖的水？",a="近期的魔法冲突扰乱了世界各地的魔法流动。詹妮亚担心游离的能流可能正渗入艾尔文的水域，危及所有饮用湖水的人。",al={"为何取明镜湖水","为何采集水样"}},{q="在哪里把瓶子装满？",a="前往艾尔文森林中、暴风城正门西南方，在汇入明镜湖的瀑布底部把瓶子装满。",al={"在哪装满瓶子","瓶子位置","湖泊位置"}}},fx={b836f408={q="詹妮亚的瓶子是什么？",a="这是暴风城法师区的导师詹妮亚·坎农提供的一种专用样本容器。她将瓶子交给有潜力的学徒，让他们直接从明镜湖的瀑布采集水样，以便检查水中是否受到魔法污染。",al={"詹妮亚的瓶子是什么","詹妮亚的瓶子"}}},fp="14,138,28.439.0,19.309.0,32.86.0,25.88.0,44.184.0,28.126.0"}
P.entries["item:jitters-completed-journal"] = {n="基特斯的日记",s="基特斯交出了写完的日记，希望洗清自己的嫌疑，揭露盘踞暮色森林的邪恶势力。这个离群索居的男人逃离了斯温农场的屠杀现场，害怕遭到斯温·约根的报复。",h="基特斯交出了写完的日记，希望洗清自己的嫌疑，揭露盘踞暮色森林的邪恶势力。这个离群索居的男人逃离了斯温农场的屠杀现场，害怕遭到斯温·约根的报复。",kw={"主教法席恩","光明大教堂","黑暗骑士","暮色森林","荒弃鬼屋","基特斯","日记","摩本特·费尔","斯温·约根"},ang={["class:Priest"]="身为牧师，将日记带给光明大教堂的主教法席恩，便是投身于借助神圣遗物净化邪恶污秽的事业。",["faction:Alliance"]="身为联盟的一员，你能从日记中看到，当暴风城的领袖们将注意力放在别处时，暮色森林已陷入何等险境。"},sec={{t="懦夫的忏悔",b="斯温的农场遇袭时，基特斯逃走了，将写到一半的日记留在了废墟中。在写完的日记里，他讲述了神秘的黑暗骑士如何杀害斯温的家人。躲藏在暮色森林的数周里，这些文字是他唯一的慰藉。如今，他自愿交出写完的日记，希望真相能让他免受斯温盛怒之下的报复。"},{t="揭开黑暗",b="这本日记让斯温说出了自己的所见：身披黑色斗篷的骑士在荒弃鬼屋与巫师摩本特·费尔交谈。斯温托旅人将手稿带往北方，送到暴风城的光明大教堂。主教法席恩阅读了基特斯的记述，以了解暮色森林的邪恶污染，随后利用其中揭示的线索，协助制作一件能够穿透费尔的黑暗结界的神圣武器。"}},faq={{q="基特斯为什么交出日记？",a="斯温的农场遇袭时，基特斯逃走了，留下一本尚未写完的日记。他将写完的日记交给冒险者，让他们带给斯温，希望完整的真相能洗清自己的嫌疑，让自己免受斯温怒火的波及。",al={"基特斯为何交出日记","基特斯日记","基特斯为何写下这些"}},{q="日记揭示了斯温农场的什么事？",a="基特斯在写完的日记中，以目击者的身份记述了斯温·约根农场的惨剧，补全了未写完的日记中缺失的内容。",al={"斯温农场发生了什么","斯温家人遇袭","黑暗骑士 斯温农场"}},{q="摩本特·费尔是谁，他与日记有什么联系？",a="摩本特·费尔是荒弃鬼屋的一名死灵法师。这本日记让斯温说出，他曾看见身披黑色斗篷的骑士与费尔交谈。",al={"摩本特·费尔的联系","摩本特·费尔是谁","荒弃鬼屋巫师"}},{q="为什么要把日记送到暴风城？",a="斯温将日记送给暴风城光明大教堂的主教法席恩。法席恩阅读日记，以了解暮色森林的污染，并协助准备一件能够穿透摩本特·费尔魔法结界的神圣武器。",al={"为何找主教法席恩","将日记带到教堂","寻求智慧 日记"}}},fx={["3f8dfebe"]={q="什么是基特斯的日记？",a="这是基特斯留下的完整个人纪事。基特斯是个躲藏在暮色森林中的惊恐流浪者。与他逃离斯温·约根的农场时遗落的零散笔记不同，这份完整手稿详述了降临在那座农场上的一系列悲剧、森林中日益逼近的恐怖，以及在阴影中活动的邪恶身影。",al={"基特斯的日记","这本日记是什么"}},e7121643={q="基特斯的日记从何而来？是谁写的？",a="这本日记是基特斯亲笔写下的。在逃离斯温的农场遭遇的屠杀并丢下早先的一本日记后，他躲藏了数周，惊慌地记录自己的想法，以及在暮色森林中徘徊的邪恶势力。他一直将写完的日记作为唯一的伴侣，直到为了避免面对斯温·约根的怒火，才把它交了出去。",al={"谁写了基特斯的日记","基特斯日记的来历","这本日记从何而来"}},["5c3c5710"]={q="为什么有人想要基特斯的日记？",a="斯温·约根想要这本日记，因为其中记载了基特斯对农场悲剧的亲眼见闻。后来，光明大教堂的主教法席恩也会研读它，以帮助一位冒险者做好准备，对抗侵扰暮色森林的邪恶。",al={"为什么他们想要这本日记","基特斯的日记为何重要","谁想要这本日记"}}},fp="26,161,21.343.1,23.373.1,36.219.0,47.140.1,58.142.1,38.206.1"}
P.entries["item:johaan-s-findings"] = {n="乔汉的研究成果",s="药剂师乔汉将研究成果从布瑞尔送往南方的瑟伯切尔。他的研究将提瑞斯法林地近期的炼金成果带给了银松森林的药剂师伦弗利尔。",h="药剂师乔汉将研究成果从布瑞尔送往南方的瑟伯切尔。他的研究将提瑞斯法林地近期的炼金成果带给了银松森林的药剂师伦弗利尔。",kw={"药剂师乔汉","药剂师伦弗利尔","布瑞尔","乔汉","乔汉的研究成果","新的瘟疫","皇家药剂师学会","瑟伯切尔"},ang={["faction:Horde"]="作为部落的一员，你带着研究资料南下，从熟悉的提瑞斯法林地踏入银松森林更为黑暗的纷争之中。",["race:Undead"]="作为 Undead，这些研究成果向你揭示了皇家药剂师学会奋力追求的目标：研制出向黑暗女王承诺的新的瘟疫。"},sec={{t="药剂师的书信",b="药剂师乔汉将研究资料从布瑞尔送往瑟伯切尔，交给药剂师伦弗利尔。皇家药剂师学会奉希尔瓦娜斯·风行者女士之命，研制一种能够同时消灭生者与 天灾军团 的新的瘟疫。研究人员散布在洛丹伦饱受争夺的废墟之中，因此必须在各个哨站之间共享研究成果。伦弗利尔在银松森林指挥协会的研究工作，而乔汉则在布瑞尔记录当地的试验。他的文献汇入了协会更广泛的研究，用于改进那些致命的药剂。"}},faq={{q="乔汉的研究成果是什么？",a="乔汉的研究成果是药剂师乔汉在布瑞尔整理的炼金笔记与研究资料。其中记录了他近期在提瑞斯法林地进行的测试与实验。",al={"乔汉的研究成果","乔汉的研究成果是什么","乔汉 研究文献"}},{q="这件物品应该交给谁？",a="这些研究成果应当交给药剂师伦弗利尔。他是皇家药剂师学会的资深成员，驻扎在银松森林北部的瑟伯切尔。",al={"乔汉的研究成果交给谁","乔汉的研究成果送到哪里","伦弗利尔 递送"}},{q="药剂师之间为什么要共享这项研究？",a="皇家药剂师学会在分散各地的研究人员之间共享知识，以加快研究进展。希尔瓦娜斯·风行者要求尽快推进新的瘟疫的研制，因此银松森林的研究人员需要了解提瑞斯法的新发现。",al={"为何共享研究成果","乔汉的研究成果的用途","皇家药剂师学会 研究"}},{q="这些文献是谁写的？",a="这些文献由药剂师乔汉撰写。他是皇家药剂师学会的炼金师，位于布瑞尔的绞刑架附近，在那里测试当地的样本，为被遗忘者的炼金研究效力。",al={"药剂师乔汉是谁","这是谁写的","药剂师乔汉"}}},fp="17,181,25.524.0,26.156.0,37.156.0,55.236.0,26.169.0"}
P.entries["item:johaan-s-special-drink"] = {n="乔汉的特制饮料",s="在布瑞尔，药剂师乔汉提供了一杯用途致命的饮料。它伪装成普通饮品，用于测试皇家药剂师学会正在研制的瘟疫。",h="在布瑞尔，药剂师乔汉提供了一杯用途致命的饮料。它伪装成普通饮品，用于测试皇家药剂师学会正在研制的瘟疫。",kw={"药剂师乔汉","布瑞尔","被俘虏的巡山人","恐惧之末旅店","乔汉","乔汉的特制饮料","新瘟疫"},ang={["race:Dwarf"]="身为矮人，你面临着在提瑞斯法林地附近被亡灵卫兵俘虏并用作试验对象的危险。",["race:Undead"]="身为被遗忘者，你协助皇家药剂师学会，推进Sylvanas女士针对生者的图谋。"},sec={{t="剧毒饮剂",b="在布瑞尔，药剂师乔汉用有毒成分和当地的试剂调制饮剂。虽然看起来像旅店里的饮品，这种混合物却是用来测试瘟疫对活物的毒性有多强。乔汉将它交出，仿佛只是为了给一名俘虏解渴。这项工作服务于被遗忘者药剂师们的目标：制造一种足够强大的武器，实现希尔瓦娜斯·风行者对艾泽拉斯的图谋。"},{t="地窖试验",b="在恐惧之末旅店地下，亡灵卫兵将误入此地的闯入者关在地窖的牢房里。一名被俘虏的矮人巡山人被锁在那里，迫不及待地喝下了他误以为是粗劣麦酒的饮剂。饮剂让他当场毙命，向皇家药剂师学会证明，其最新的瘟疫毒株能迅速夺走活物的性命。"}},faq={{q="乔汉的特制饮料是什么？",a="药剂师乔汉在布瑞尔调制了一种致命饮料，用来测试被遗忘者正在研制的瘟疫对活物的效果。",al={"乔汉的饮料是什么","乔汉的饮料","这件物品是什么"}},{q="这杯饮料交给了谁？",a="这杯饮料被送到布瑞尔的恐惧之末旅店地下的地窖，交给一名被当地亡灵卫兵关押的被俘虏的巡山人。",al={"谁喝下它","饮料交给谁","饮料的目标"}},{q="喝下它会发生什么？",a="那名囚犯以为饮剂是烈性麦酒，喝下后当场毙命。",al={"矮人会死吗","饮料的效果","它有什么作用"}},{q="药剂师乔汉为什么要调制这杯饮料？",a="药剂师乔汉调制这杯饮料，是为了测试皇家药剂师学会的新瘟疫。他将饮料交给一名被俘虏的矮人，以检验它杀死血肉生灵的效力。",al={"乔汉为什么调制它","药剂师乔汉的动机","为什么测试瘟疫"}}},fp="22,174,12.359.0,16.323.1,31.117.0,26.139.0,36.68.1,43.163.0"}
P.entries["item:jordan-s-ore-shipment"] = {n="乔丹的矿石",s="在洛克莫丹东北部的群山中，莫格罗什食人魔占据着乔丹的矿石。这批矿石由商队从湿地运来，原本要交给白洛尔·石手，为铁匠乔丹·斯迪威尔精炼成合金。",h="在洛克莫丹东北部的群山中，莫格罗什食人魔占据着乔丹的矿石。这批矿石由商队从湿地运来，原本要交给白洛尔·石手，为铁匠乔丹·斯迪威尔精炼成合金。",kw={"合金","白洛尔·石手","乔丹·斯迪威尔","乔丹的矿石","洛克莫丹","莫格罗什","正义试炼"},ang={["class:Paladin"]="身为圣骑士，从莫格罗什食人魔手中夺回被抢走的合金，是完成乔丹·斯迪威尔委托的关键一步。这也能在正义试炼中证明你的虔诚。",["profession:Blacksmithing"]="身为铁匠，你能看出白洛尔·石手的特制合金凝聚着精湛的矮人冶金技艺。乔丹·斯迪威尔不肯用普通材料代替它来完成锻造。"},sec={{t="遭伏击的货运",b="乔丹·斯迪威尔的矿石原本要送到矮人白洛尔·石手手中，由他精炼成特制合金。商队载着矿石，从湿地穿过群山，向南进入洛克莫丹。随后，莫格罗什食人魔伏击了商队，将货物拖回了荒野中的据点。幸存的护卫也因伤重而死，乔丹·斯迪威尔的锻造计划仍在等待矿石归来。"}},faq={{q="这批货物里装着什么？",a="这批货物里装着矿石，要由白洛尔·石手精炼成特制合金。乔丹·斯迪威尔在铁炉堡打造金属制品时需要用到它。",al={"乔丹的矿石里有什么","这是什么矿石","乔丹 矿石内容"}},{q="谁抢走了乔丹的矿石？",a="莫格罗什食人魔伏击了从湿地南下的商队。他们杀光了护卫，将货箱拖到了洛克湖东北部的领地。",al={"谁抢走了这批矿石","谁偷走了它","食人魔矿石货物"}},{q="白洛尔·石手是谁？",a="白洛尔·石手是一位驻留洛克莫丹的矮人工匠，也是乔丹·斯迪威尔的老朋友。他安排了这批合金的运输，货物却遭到了食人魔的劫掠。",al={"白洛尔·石手","白洛尔 是谁"}},{q="这批货物为何对圣骑士如此重要？",a="接受正义试炼的圣骑士要寻找这批合金，帮助乔丹·斯迪威尔锻造一件受圣光祝福的武器。",al={"圣骑士矿石货物","正义试炼 矿石","圣骑士为何需要这个"}}},fx={bb183b6f={q="乔丹的矿石是什么？",a="乔丹的矿石是一箱矿石，原本应由矮人白洛尔·石手将其精炼成他的特制合金，供铁炉堡的铁匠乔丹·斯迪威尔使用。这批货物由一支从湿地赶来的商队运送，途中在洛克莫丹北部遭到莫格罗什食人魔伏击并被夺走。",al={"乔丹的矿石是什么","乔丹的矿石资料","白洛尔的矿石是什么"}},["84b5d642"]={q="乔丹的矿石来自哪里，由谁制成？",a="这批货物是由商队从湿地运往洛克莫丹的矿石，白洛尔·石手原本要在那里将其精炼成自己的合金，交给老朋友乔丹·斯迪威尔。运输队尚未抵达，食人魔就截住了他们，并杀死了护卫。",al={"乔丹的矿石是谁制作的","乔丹的矿石来自哪里","乔丹的矿石来源"}}},fp="21,201,20.399.0,28.134.0,32.168.0,24.157.0,43.126.0"}
P.entries["item:jordan-s-refined-ore-shipment"] = {n="乔丹的精炼矿石",s="乔丹的精炼矿石运抵铁炉堡，用于正义试炼。这些金属是为铁匠乔丹·斯迪威尔打造神圣武器而准备的。",h="乔丹的精炼矿石运抵铁炉堡，用于正义试炼。这些金属是为铁匠乔丹·斯迪威尔打造神圣武器而准备的。",kw={"白洛尔","铁炉堡","乔丹·斯迪威尔","圣骑士武器","精炼矿石","正义试炼"},ang={["class:Paladin"]="身为圣骑士，你必须展现耐心与奉献精神，才能取得这批精炼矿石。这是打造象征圣光的武器所需经历的实际考验之一。",["profession:Blacksmithing"]="身为铁匠，你知道，锻造精良武器需要毫无瑕疵、精心制备的金属锭，而非野外开采的原矿。"},sec={{t="铁匠的材料",b="乔丹·斯迪威尔需要稀有材料，打造一件配得上圣骑士的武器。他需要一颗净化过的科尔宝石、坚固的白石橡木、他遗失的铁匠之锤，以及精炼矿石。这批货物将金属运到铁炉堡，供这项神圣的锻造工作使用。"}},faq={{q="乔丹的精炼矿石有什么用途？",a="这些精炼矿石要交给铁炉堡城外的乔丹·斯迪威尔。它是四种关键材料之一，用于为接受正义试炼的圣骑士打造一件精良武器。",al={"精炼矿石用途","乔丹用矿石做什么","矿石货物用途"}},{q="谁负责准备这些精炼矿石？",a="白洛尔负责安排运输，并监督乔丹·斯迪威尔所需特殊金属的精炼和发运。",al={"谁制备了矿石","白洛尔矿石","谁精炼乔丹的矿石"}},{q="乔丹为什么需要这批特定的矿石？",a="乔丹·斯迪威尔打算打造一件象征圣骑士身份与圣光的武器。他需要比普通锻造边角料更优质的材料，而经过特殊处理的金属，能让剑刃或锤头拥有配得上神圣骑士的平衡与纯净。",al={"为什么需要特殊矿石","为什么乔丹不能用普通铁","精炼矿石的原因"}}},fx={ec64bb0f={q="乔丹的精炼矿石是什么？",a="乔丹的精炼矿石是一箱经过特殊加工的优质金属，为武器锻造师乔丹·斯迪威尔准备。这批精炼矿石用于精细锻造，而非普通的熔铸，为乔丹提供了纯净的金属原料，让他能打造出一件配得上虔诚侍奉圣光的圣骑士的非凡武器。",al={"乔丹的精炼矿石是什么","乔丹的精炼矿石背景"}}},fp="29,158,19.241.0,47.167.0,29.114.0,44.240.0"}
P.entries["item:jordan-s-smithing-hammer"] = {n="乔丹的铁锤",s="乔丹·斯迪威尔在铁炉堡外等待父亲的铁锤归来，那柄铁锤遗失在影牙城堡中。",h="乔丹·斯迪威尔在铁炉堡外等待父亲的铁锤归来，那柄铁锤遗失在影牙城堡中。",kw={"丹莫罗","铁炉堡","乔丹·斯迪威尔","圣骑士武器","影牙城堡","锻造铁锤","正义试炼"},ang={["class:Paladin"]="身为圣骑士，你必须深入险地，取回这柄祖传铁锤，在正义的试炼中证明自己的决心。",["profession:Blacksmithing"]="身为铁匠，你深知锻造大师与祖辈传下的铁锤之间的深厚情谊。"},sec={{t="工匠的传承",b="乔丹·斯迪威尔是一位在铁炉堡外打铁的人类铁匠。他父亲的铁锤遗落在银松森林的影牙城堡中。没有这柄铁锤，乔丹就无法打造出配得上神圣勇士的武器，而那正是他渴望完成的杰作。"}},faq={{q="乔丹的铁锤在哪里？",a="乔丹的铁锤就在银松森林的影牙城堡内。接受正义试炼的圣骑士必须进入这座被占据的堡垒，将它取回。",al={"铁锤位置","乔丹的铁锤在哪里","哪里能找到乔丹的铁锤"}},{q="这柄铁锤为什么对乔丹·斯迪威尔如此重要？",a="乔丹从父亲那里继承了这柄铁锤，它对他意义非凡。他需要用它打造自己最出色的作品，一件奉献给圣光的神圣武器。",al={"乔丹为什么需要铁锤","乔丹·斯迪威尔的铁锤故事"}},{q="取回铁锤后，它有什么用途？",a="将铁锤连同木材、矿石和一颗宝石一起交给铁炉堡大门外的乔丹。他会为帮助过他的圣骑士打造一件神圣武器。",al={"铁锤能打造什么","正义试炼铁锤用途"}}},fx={["126e648c"]={q="乔丹的铁锤是什么？",a="乔丹的铁锤是锻造大师乔丹·斯迪威尔珍爱的锻造工具。除了在铁砧旁的实用价值，它还是乔丹的父亲亲手传给他的传家宝，寄托着深厚的情感。",al={"乔丹的铁锤是什么","乔丹的铁锤物品","关于乔丹的铁锤"}},["1df19239"]={q="乔丹的铁锤来自哪里，由谁打造？",a="这把铁锤由乔丹·斯迪威尔的父亲传给他。究竟是谁打造了它，已无从查考，但在你找回它之前，这件传家宝不知为何流落到了远离铁炉堡的影牙城堡，藏在阴暗的城垛之中。",al={"乔丹的铁锤来自哪里","乔丹的铁锤是谁打造的","乔丹的铁锤来源"}}},fp="24,93,20.244.0,42.172.0,51.148.0,43.150.0"}
P.entries["item:kadrak-s-flag"] = {n="卡德拉克的旗子",s="在贫瘠之地与灰谷的交界处，卡德拉克交给部落一面旗子，要他们将这一标志带入敌境。杀死掌钥者琳萨瑞尔后，这面旗子便会插在猛禽洞穴内。",h="在贫瘠之地与灰谷的交界处，卡德拉克交给部落一面旗子，要他们将这一标志带入敌境。杀死掌钥者琳萨瑞尔后，这面旗子便会插在猛禽洞穴内。",kw={"贫瘠之地","部落势力","卡德拉克","卡德拉克的旗子","琳萨瑞尔","石爪山","石爪峰","猛禽洞穴"},ang={["faction:Horde"]="将旗帜插在猛禽洞穴深处，宣示了部落的力量，也表明部落在受到挑衅时会袭击暗夜精灵的庇护所。",["race:NightElf"]="对暗夜精灵而言，猛禽洞穴内的部落旗帜是对石爪峰守护者的直接侮辱。"},sec={{t="抗争的标志",b="卡德拉克派人将部落的旗帜带入石爪峰上的猛禽洞穴。树妖琳萨瑞尔是大兽穴的掌钥者，她曾派人越过边境传递消息，而卡德拉克认为，仅仅杀死她还不足以回应这些举动。他将这面深红色的旗帜交给你，要你将它插在大兽穴深处。在那里飘扬的部落旗帜向暗夜精灵和树妖发出警告：侵入贫瘠之地的行为，将招致部落在联盟领土上的报复。"}},faq={{q="卡德拉克的旗子有什么用途？",a="杀死掌钥者琳萨瑞尔后，将卡德拉克的旗子插在石爪峰顶的猛禽洞穴内。这面部落旗帜警告暗夜精灵，不要再向贫瘠之地派遣斥候和信使。",al={"旗子用途","为何插旗","旗子有什么用"}},{q="谁会把旗子交给你？",a="卡德拉克是一名兽人斥候，驻守在贫瘠之地北部与灰谷之间的边境哨所，他在设法确保这一地区安全的同时，将旗帜交给你。",al={"谁给旗子","哪里获得旗子","卡德拉克位置"}},{q="旗子要插在哪里？",a="将旗帜插在猛禽洞穴内，这处洞穴庇护所位于石爪山脉的石爪峰西坡。",al={"在哪里插旗","旗子位置","猛禽洞穴插旗地点"}},{q="琳萨瑞尔是谁？",a="琳萨瑞尔是一名树妖，也是猛禽洞穴的掌钥者。她不断向部落领地派遣信使，直到卡德拉克截获她的通信，并下令将她杀死。",al={"树妖琳萨瑞尔","琳萨瑞尔是谁","掌钥者"}}},fp="13,140,18.386.0,31.202.0,23.145.0,26.127.0,18.161.0"}
P.entries["item:keg-of-shindigger-stout"] = {n="矿工烈酒",s="在丹加洛克，矮人烈酒 装满了矮人的酒桶，也引起了塔伦米尔的兴趣。皇家药剂师学会想要这些麦酒，其用途远比饮用更为阴暗。",h="在丹加洛克，矮人烈酒 装满了矮人的酒桶，也引起了塔伦米尔的兴趣。皇家药剂师学会想要这些麦酒，其用途远比饮用更为阴暗。",kw={"药剂师林度恩","丹加洛克","矮人麦酒","苦楚药剂","矿工烈酒","挖掘场烈酒","塔伦米尔"},ang={["faction:Horde"]="身为部落的一员，你可以进攻丹加洛克，那是联盟在希尔斯布莱德丘陵东南部山地的军事据点。",["race:Undead"]="身为被遗忘者的一员，你可以用酒掩盖为希尔瓦娜斯调制的致命药剂的气味和味道。"},sec={{t="矮人的心头好",b="铁炉堡的矮人驻守着希尔斯布莱德丘陵东南部的丹加洛克。在营房和食堂里，守军分享着 矮人烈酒，熬过严寒，以及与当地敌人之间的围城战。这种酒是驻军日常生活中不可或缺的一部分。"},{t="药剂师林度恩的盛毒容器",b="塔伦米尔的药剂师林度恩正在寻找一桶完好无损的 矿工烈酒，用于被遗忘者的苦楚药剂。他不愿在野兽身上试验配方，打算将毒药掺入麦酒，给关押在塔伦米尔的被俘人类农夫喝下。"}},faq={{q="矮人烈酒 有什么用途？",a="塔伦米尔的药剂师林度恩想要 矮人烈酒，用于苦楚药剂。他打算将毒药掺入麦酒，在人型生物身上试验。",al={"为什么要获取 矮人烈酒","矿工烈酒 的用途","林度恩 用酒桶做什么"}},{q="在哪里能找到矿工烈酒？",a="一桶桶 矮人烈酒 存放在希尔斯布莱德丘陵东南部的丹加洛克。矮人将这些酒桶储藏在要塞的食堂和下层营房里。",al={"酒桶位置","矿工烈酒 在哪里","寻找烈酒"}},{q="谁酿造了 矮人烈酒？",a="丹加洛克的矮人酿造并储藏着 矮人烈酒。他们为铁炉堡驻守着希尔斯布莱德丘陵的一处设防据点。",al={"谁酿造 矿工烈酒","这是矮人麦酒吗"}},{q="药剂师林度恩为什么不自己酿酒来做试验？",a="林度恩要求取来一桶存放在丹加洛克的麦酒，用于他的试验。记载只提到他需要这些麦酒，没有给出其他原因，也没有提及他自己酿酒的事。",al={"为什么要偷矮人的啤酒","为什么要丹加洛克的啤酒"}}},fx={b55cb0ca={q="什么是矿工烈酒？",a="矿工烈酒是一桶浓烈的矮人麦酒，由驻扎在丹加洛克要塞中的铁炉堡矮人保存。这桶酒原本是供驻守希尔斯布莱德丘陵的矮人士兵饮用的，但其烈性酒液也使它成为药剂师林度恩代表皇家药剂师协会进行试验的理想媒介。",al={"什么是矿工烈酒","矿工烈酒桶的信息"}}},fp="23,169,18.253.0,32.234.1,34.150.0,45.163.0,27.125.0,63.144.0"}
P.entries["item:ken-zigla-s-draught"] = {n="肯兹格拉的伤药",s="在石爪山脉，肯兹格拉为重伤者调制一种苦涩的伤药。谨慎服用半剂，就能恢复足以行动的体力，服用更多却可能让伤者失血而亡。",h="在石爪山脉，肯兹格拉为重伤者调制一种苦涩的伤药。谨慎服用半剂，就能恢复足以行动的体力，服用更多却可能让伤者失血而亡。",kw={"陶拉祖营地","多格兰","步兵劳格玛","肯兹格拉的伤药","肯兹格拉","石爪山脉","魅魔任务","贫瘠之地"},ang={["class:Warlock"]="作为术士，你必须在召唤并束缚魅魔的试炼中，找到并送去伤药。穿越贫瘠之地的旅途将考验你的应变能力和追踪本领。",["faction:Horde"]="陶拉祖营地因外出觅食的巡逻队而人手不足，伤药成了一名被俘于野猪人敌后的特工唯一的生机。"},sec={{t="苦涩的良药",b="肯兹格拉在石爪山脉为濒死之人调制伤药。药量必须仔细斟酌：一次服用超过半剂，就可能使伤者血流骤然加快，最终失血而亡。半剂伤药能让伤者恢复足够的体力，得以行动并逃离险境。剩下的半剂必须等伤者休息一整夜，身体状况稳定后才能服用。"},{t="贫瘠之地的仁慈",b="部落术士带着伤药，深入陶拉祖营地以北一处敌对的钢鬃营地，多格兰就被关押在那里。这名特工被野猪人俘虏，遭受了酷刑。伤药让他恢复了一些体力，得以蹒跚逃离，但严重的伤势已使他的四肢永久残废。"}},faq={{q="肯兹格拉的伤药有什么用途？",a="肯兹格拉的伤药能为濒死或身受重伤的人恢复体力。谨慎用药，就能帮助伤者行动并逃离囚禁，避免致命的失血。",al={"肯兹格拉的伤药有什么作用","伤药用途","为什么需要肯兹格拉的伤药"}},{q="伤药是谁调制的？",a="伤药由住在石爪山脉的肯兹格拉调制。",al={"谁调制伤药","肯兹格拉是谁","肯兹格拉位置"}},{q="为什么伤药每次只能服用半剂？",a="这种伤药对身体的刺激极强。半剂就能恢复足以行动的体力，又不至于引发严重出血；另外半剂必须等伤者休息一夜后才能服用，以免身体承受不住，危及性命。",al={"肯兹格拉的伤药怎么服用","半剂伤药","伤药服用说明"}},{q="伤药是给谁的？",a="伤药是给多格兰的。他是一名特工，被囚禁在贫瘠之地陶拉祖营地以北的一处野猪人营地中，身受重伤。",al={"谁服用伤药","多格兰是谁","伤药送到哪里"}},{q="为什么要派术士去取这种药？",a="寻求束缚魅魔的部落术士会被指引去寻找多格兰，他持有一件承载着深厚情感的物品。送去伤药能帮助他们接触到他，并取得召唤仪式所需之物。",al={"术士为什么需要伤药","魅魔任务伤药","术士任务肯兹格拉"}}},fx={["6eadaa9a"]={q="什么是肯兹格拉的伤药？",a="这是石爪山脉的巨魔药剂师肯兹格拉调制的一剂强效苦涩药剂。它旨在帮助伤者承受严重创伤，药效强大到足以恢复一名身受致命重伤的士兵的活力，让其能够行动，不过使用时必须格外谨慎。",al={"什么是伤药","肯兹格拉的伤药","肯兹格拉的药剂"}},["42d17912"]={q="为什么需要肯兹格拉的伤药？",a="一个名叫多格兰的兽人被贫瘠之地的野猪人抓获并残酷折磨。他身受重伤、濒临死亡，被囚禁期间若没有伤药的恢复魔力，就无法活下来或逃脱。陶拉祖营地的步兵劳格玛急需这种药剂，好让多格兰支撑着伤势逃离俘虏。",al={"为什么需要伤药","谁需要肯兹格拉的伤药","为什么要制作伤药"}}},fp="19,177,15.340.0,20.294.1,37.180.0,22.59.0,50.208.0,25.136.0,48.207.0"}
P.entries["item:khazgorm-s-journal"] = {n="卡兹戈姆的日记",s="在巴尔莫丹，勘探员卡兹戈姆领导着铁炉堡矮人在南贫瘠之地的挖掘工作。他的野外记录记载了探险者协会在石塔牛头人宣称拥有的土地上开展的工作。",h="在巴尔莫丹，勘探员卡兹戈姆领导着铁炉堡矮人在南贫瘠之地的挖掘工作。他的野外记录记载了探险者协会在石塔牛头人宣称拥有的土地上开展的工作。",kw={"巴尔莫丹","贫瘠之地","矮人","探险者协会","加恩·石塔","日记","卡兹戈姆","勘探员"},ang={["faction:Horde"]="身为部落的一员，你可以帮助加恩·石塔保卫卡利姆多，抵御不断深入部落领土的联盟探险队。",["race:Tauren"]="身为牛头人，你可以将这本日记视为证据，证明铁炉堡入侵者在炸开石塔部族的祖地时，对这个部族毫不顾惜。"},sec={{t="毁坏的记录",b="勘探员卡兹戈姆指挥重型机械和爆破作业，开凿南贫瘠之地的山坡。他的笔记表明，这场挖掘与探险者协会承诺的求知之旅相去甚远：他们的作业使石塔部族流离失所。牛头人曾试图和平解决争端，但矮人拒绝了。加恩·石塔想要这本日记，以了解铁炉堡在他家园中的势力，并找到将其瓦解的办法。"},{t="战术的转变",b="加恩·石塔在挖掘场的帐篷和石柱附近，从卡兹戈姆的遗骸中找到了日记。笔记让他了解到这支矮人探险队的组织方式、使用的设备，以及薄弱之处。掌握这些情报后，加恩不再只是驱赶劳工，而是转向袭击挖掘机械。这本日记改变了围绕巴尔莫丹展开的斗争。"}},faq={{q="这本日记属于谁？",a="这本日记属于勘探员卡兹戈姆，他是铁炉堡矮人在南贫瘠之地巴尔莫丹开展挖掘工作的一名领队。",al={"日记属于谁","卡兹戈姆","勘察员卡兹戈姆"}},{q="加恩·石塔为什么想要这本书？",a="加恩·石塔想要这本日记，以研究那些迫使他的部族背井离乡的矮人的计划和秘密。卡兹戈姆的笔记帮助他筹划对巴尔莫丹营地的进一步袭击。",al={"加恩为何想要日记","加恩任务日记","加恩的报复书籍"}},{q="在哪里可以找到这本日记？",a="勘探员卡兹戈姆随身携带着这本日记，他就在巴尔莫丹正南方仍在作业的挖掘场中，周围是帐篷和石柱。",al={"卡兹戈姆的日记在哪","寻找卡兹戈姆的日记","卡兹戈姆位置"}},{q="这本日记揭示了矮人的什么情况？",a="日记表明，探险者协会对地下遗物和泰坦遗产的追寻，直接以暴力侵害了石塔牛头人等部族的利益。",al={"探险者协会 贫瘠之地","矮人挖掘场秘密","巴尔莫丹的目的"}}},fp="18,180,23.415.0,18.357.1,31.122.0,40.187.0,31.123.0,47.163.0"}
P.entries["item:klaven-mortwake-s-journal"] = {n="克拉文·摩特维克的日记",s="SI:7特工从迪菲亚高塔中取回了克拉文·摩特维克的日记。日记记载了兄弟会寻找复活死者之法的经过。",h="SI:7特工从迪菲亚高塔中取回了克拉文·摩特维克的日记。日记记载了兄弟会寻找复活死者之法的经过。",kw={"迪菲亚高塔","暮色森林的箱子","日记","克拉文·摩特维克","马迪亚斯·肖尔","毒药","si:7","赞吉尔"},ang={["class:Rogue"]="作为一名潜行者，你潜入高塔，取走摩特维克的日记，以此证明自己的开锁和潜行本领。这项任务也让你开始学习调配致命毒药。",["faction:Alliance"]="作为联盟的一员，你为暴风城的间谍首领们提供了证据，证明迪菲亚叛乱牵涉的远不止心怀不满的劳工。日记揭示了他们与巨魔巫医及炼金通灵术的联系。"},sec={{t="骇人的配方",b="迪菲亚高塔矗立在西部荒野北部的山脊上。诡异的货物从暮色森林幽暗的边境运来，扭曲的非人哨兵守卫着高塔。SI:7监视这里已有很长时间。他们在最上层的箱子里找到了克拉文·摩特维克的日记，得知了那些货物的内容。\n\n克拉文·摩特维克记录了用炼金术唤起无意识亡灵仆从的研究。与荆棘谷的赞吉尔巨魔有关联的炼金师，已经找到了利用特殊毒药和药剂实现这一目的的方法。迪菲亚潜行者试图仿效这种方法，用于自己的队伍。"},{t="交给SI:7的情报",b="马迪亚斯·肖尔领导着暴风城的情报机构SI:7。他想取得摩特维克的日记，以追查兄弟会更广泛的盟友关系。这些笔记证实了复活死者的实验，以及暮色森林、荆棘谷地精和迪菲亚之间的非法援助关系。对于效忠王室的潜行者而言，取回这份研究资料是迈向精通毒药的一步。"}},faq={{q="克拉文·摩特维克的日记是什么？",a="克拉文·摩特维克的日记是克拉文·摩特维克编写的研究笔记，他是西部荒野东北部迪菲亚高塔中的一名特工。其中记载了炼金通灵术和非法补给路线。",al={"克拉文的日记是什么","摩特维克的日记","这件物品是什么"}},{q="在哪里能找到这本日记？",a="日记锁在西部荒野北部迪菲亚高塔顶层的暮色森林的箱子里。亡灵哨兵守卫着它，从克拉文手下一名怪物守卫身上取得的钥匙可以打开箱子。",al={"哪里能找到克拉文的日记","克拉文日记位置","暮色森林的箱子位置"}},{q="日记里记载了什么秘密？",a="日记记载，荆棘谷的赞吉尔巨魔研制出了能够复活并控制死者的有毒药剂。迪菲亚潜行者当时正试图获取并使用这一配方。",al={"日记写了什么","日记的秘密","赞吉尔毒药"}},{q="谁想要这本日记？",a="马迪亚斯·肖尔是暴风城SI:7情报机构的首领，他想取得这本日记，以监视迪菲亚的后勤活动，并教导王室特工了解战术毒药的危险和用途。",al={"克拉文日记交给谁","日记交给谁","马迪亚斯·肖尔日记"}}},fx={["887d3337"]={q="克拉文·摩特维克的日记来自哪里，由谁撰写？",a="这本日记属于克拉文·摩特维克，他负责掌管迪菲亚潜行者在西部荒野高塔中的据点。日记与凶险的亡灵守卫及一只箱子一同从暮色森林运来，详细记载了源于荆棘谷流亡者赞吉尔麾下巨魔的黑暗炼金秘密。",al={"克拉文的日记是谁写的","克拉文·摩特维克的日记来源","克拉文从哪里得到日记"}}},fp="25,137,18.586.1,21.348.0,34.203.0,27.201.0,44.188.0,23.183.0"}
P.entries["item:kodo-horn"] = {n="科多兽角",s="在贫瘠之地，人们从四处游荡的科多兽身上采集科多兽角。图加·符文图腾用它们配制草药，救治中毒的野生动物。",h="在贫瘠之地，人们从四处游荡的科多兽身上采集科多兽角。图加·符文图腾用它们配制草药，救治中毒的野生动物。",kw={"贫瘠之地","塞纳里奥","地根草","瞪羚","科多兽角","毒药","图加·符文图腾"},ang={["class:Druid"]="身为部落的德鲁伊，你在图加·符文图腾的指导下采集兽角，学习掌控自然界的毒素。",["race:Tauren"]="身为牛头人，你对科多兽怀有深深的敬意，每次索取都谨慎而有明确的目的，这一次是为了保护贫瘠之地脆弱的生态平衡。"},sec={{t="平原上的施法材料",b="图加·符文图腾用完整的科多兽角配制草药，救治贫瘠之地的野生动物。他在十字路口配药，用兽角增强药膏的效力。碎屑和残片的药力不足，因此他从漫步平原的成年科多兽身上采集完整的兽角。"}},faq={{q="科多兽角有什么用途？",a="图加·符文图腾将科多兽角与地根草和纯净的水混合，熬制药膏，救治贫瘠之地各处中毒的瞪羚。制作这种药物，是德鲁伊学习用自然疗法解毒的训练内容之一。",al={"科多兽角的用途","为何采集科多兽角","科多兽角的用处"}},{q="这些兽角在哪里采集？",a="你可以在贫瘠之地北部，从十字路口到周边灌木地带之间的贫瘠之地科多兽和迷失的贫瘠之地科多兽身上采集兽角。",al={"哪里能找到科多兽角","科多兽角的位置","哪些科多兽掉落兽角"}},{q="为什么德鲁伊不能用兽角碎片代替？",a="图加·符文图腾说，碎屑和残片的药力不足，无法调和药膏。他需要完整的兽角，才能制出足以对抗烈性毒素的药物。",al={"为何不用断角","兽角碎屑"}},{q="德鲁伊猎杀科多兽，也算尊重它们吗？",a="是的。为了维护自然的平衡，德鲁伊也会猎杀科多兽，取用所需之物来消除更大范围的灾害，比如侵害当地瞪羚群的神秘毒害。",al={"德鲁伊猎杀科多兽","平衡与科多兽"}}},fp="9,116,23.263.0,29.184.0,32.146.0,44.156.0,51.166.0"}
P.entries["item:kodo-liver"] = {n="科多兽的肝脏",s="在棘齿城，酿酒师德罗恩需要科多兽的肝脏来酿造一种奇特的啤酒。他从游历四方的酿酒师老陈风暴烈酒那里学会了酿造穴居人啤酒。",h="在棘齿城，酿酒师德罗恩需要科多兽的肝脏来酿造一种奇特的啤酒。他从游历四方的酿酒师老陈风暴烈酒那里学会了酿造穴居人啤酒。",kw={"贫瘠之地","酿酒","老陈 风暴烈酒","德罗恩","科多兽","科多兽的肝脏","棘齿城","穴居人啤酒"},ang={["profession:Cooking"]="卡利姆多中部各地的人们以科多兽肉为食，但科多兽的肝脏被认为腥臭刺鼻，不适合日常烹饪。它因被用于酿造棘齿城的穴居人啤酒而声名狼藉。",["race:Tauren"]="牛头人珍视猎获的科多兽身上的每一部分。即便是经验丰富的平原行者，也对那些在棘齿城用科多兽内脏酿造猎奇啤酒的地精和外来者颇有微词。"},sec={{t="古怪的酿酒原料",b="科多兽漫步于贫瘠之地，牛头人和捕食者在这里猎杀它们，获取皮肉。在棘齿城，酿酒师德罗恩用新鲜的科多兽的肝脏，配上雷鹰的唾液腺和闪电腺，酿造穴居人啤酒。老陈风暴烈酒将配方传授给了德罗恩，而德罗恩说，这种混合酒能让喜好冒险的旅人感受到强劲的酒劲。这些原料都来自卡利姆多中部的荒野。"}},faq={{q="科多兽的肝脏有什么用途？",a="棘齿城的酿酒师德罗恩用科多兽的肝脏酿造穴居人啤酒。老陈风暴烈酒将配方传授给了他。",al={"科多兽的肝脏用途","为什么需要科多兽的肝脏","科多兽的肝脏有什么用"}},{q="哪些生物能提供科多兽的肝脏？",a="科多兽的肝脏来自贫瘠之地的科多兽，包括普通科多兽、长毛科多兽、迷失的科多兽和大型科多兽，以及拉克塔曼尼和布隆塔斯。",al={"哪里获取科多兽的肝脏","谁掉落科多兽的肝脏","科多兽的肝脏来源"}},{q="为什么会有人把动物内脏放进啤酒里？",a="酿酒师德罗恩遵循老陈风暴烈酒传授给他的古怪配方。在穴居人啤酒中，科多兽的肝脏等生内脏和元素腺体赋予了酒液强劲的酒劲与辛烈的风味。",al={"为什么啤酒里放肝脏","酒中的科多兽的肝脏"}}},fp="10,128,25.371.0,30.101.0,35.127.0,42.165.0"}
P.entries["item:kodobane-s-head"] = {n="科多班恩的战利品",s="在遗忘之池附近，巴拉克·科多班恩被斩下的首级证明了这位狡诈酋长的死讯。兽人督军雷戈萨·死门收下了这颗首级，作为当地半人马威胁已被粉碎的证据。",h="在遗忘之池附近，巴拉克·科多班恩被斩下的首级证明了这位狡诈酋长的死讯。兽人督军雷戈萨·死门收下了这颗首级，作为当地半人马威胁已被粉碎的证据。",kw={"巴拉克","贫瘠之地","半人马","十字路口","死门","遗忘之池","科多班恩","科卡尔","雷戈萨"},ang={["faction:Horde"]="贫瘠之地的十字路口通过陆路连接着奥格瑞玛和雷霆崖。铲除科多班恩这样的半人马首领，有助于保障商队沿途的安全。",["race:Tauren"]="一代又一代，半人马在卡利姆多各地追逐驱赶着逐水草而居的牛头人，将他们逼到了灭绝的边缘。杀死巴拉克·科多班恩，既是为数百年来的血债复仇，也是在保护莫高雷和贫瘠之地的牧场。"},sec={{t="战争的战利品",b="贫瘠之地的科卡尔部族长期以来各自为政，但如今，野心勃勃的督军们正试图将他们集结成一支大军。巴拉克·科多班恩在水草丰美的遗忘之池旁扎营，那里的绿洲提供了至关重要的资源，附近的道路也容易遭到袭击。雷戈萨·死门驻守在十字路口以西的一座地堡中，要求带回科多班恩被斩下的首级，证明这名指挥官再也无法召集同族对抗部落。"}},faq={{q="巴拉克·科多班恩是谁？",a="巴拉克·科多班恩是科卡尔半人马中一位显赫的酋长。他的许多同族缺乏纪律，他却狡诈而善于统御，组织起战团，在遗忘之池周围扎营，以确立科卡尔在贫瘠之地北部的霸权。",al={"巴拉克·科多班恩","科多班恩是谁","巴拉克的故事"}},{q="雷戈萨·死门为什么要他的首级？",a="雷戈萨·死门负责保卫部落在贫瘠之地的领土。半人马通常内斗不休，因此那些具备战术眼光的首领成了重点打击的目标。雷戈萨要求带回科多班恩的首级，以确保这位酋长已经死去，而非仅仅被逐走。",al={"为何取首级","雷戈萨·死门首级","科多班恩悬赏"}},{q="在哪里能找到巴拉克·科多班恩？",a="巴拉克·科多班恩在遗忘之池附近扎营，那是贫瘠之地北部的一片绿洲，就在十字路口的西北方。",al={"巴拉克位置","科多班恩在哪里","巴拉克刷新"}},{q="杀死巴拉克就能消除科卡尔的威胁吗？",a="不能。巴拉克·科多班恩只是数名正在集结科卡尔的督军中的第一个。他的死削弱了他们在遗忘之池的势力，但狂热的维罗戈和赫兹鲁尔·血印仍在指挥半人马侵袭贫瘠之地各处。",al={"半人马被击败了吗","巴拉克死后会怎样"}}},fp="15,171,15.418.0,23.242.0,41.246.0,30.114.0,42.231.0"}
P.entries["item:kravel-s-crate"] = {n="克拉维尔的箱子",s="克拉维尔的箱子是克拉维尔·浓须从闪光平原的沙漠赛道发出的沉重包裹。它的目的地是荆棘谷的奈辛瓦里远征队，里面装着专用狩猎弹药，用于击倒丛林中最致命的猎物。",h="克拉维尔的箱子是克拉维尔·浓须从闪光平原的沙漠赛道发出的沉重包裹。它的目的地是荆棘谷的奈辛瓦里远征队，里面装着专用狩猎弹药，用于击倒丛林中最致命的猎物。",kw={"弹药","赫米特·奈辛瓦里","克拉维尔·浓须","克拉维尔的箱子","沙漠赛道","闪光平原","荆棘谷"},ang={["class:Hunter"]="箱子里装着专为高档矮人狩猎步枪设计的特制重型弹药，适合远征狩猎大型猎物。",["race:Dwarf"]="这次送货完全是矮人之间的事务，将克拉维尔·浓须在盐滩的生意与东部王国声名远扬的奈辛瓦里狩猎队联系起来。"},sec={{t="送往丛林的货物",b="克拉维尔的箱子由精明的商人克拉维尔·浓须在沙漠赛道交给冒险者，牵涉着一笔尚未完成的跨大陆交易。这批货物是一位富有的矮人顾客几周前订购的，却迟迟未到，买主早已离开卡利姆多。为了留住这位已经付过转运费的有钱顾客，克拉维尔委托路过的冒险者将箱子一路运往荆棘谷北部。"},{t="特殊口径弹药",b="箱子虽然外表普通，在闪光平原还积了一层盐尘，里面却装着致命的货物：专为狩猎步枪配制的特殊口径重型弹药。货物送到格罗姆高北面的远征队营地后，收货人提到，这些威力强大的弹药深受大型猎物猎人的青睐，也是应对丛林树冠间游荡的掠食者、保住性命的必需品。"}},faq={{q="克拉维尔的箱子里装着什么？",a="箱子里装满了特殊口径的狩猎弹药。这些大口径弹丸专供大型猎物步枪使用，用来击倒野外的危险猛兽。",al={"箱子里有什么","箱子里的物品","克拉维尔的箱子里有什么"}},{q="克拉维尔的箱子是谁寄出的？",a="寄件人是克拉维尔·浓须，一位在千针石林闪光平原的沙漠赛道经营生意的矮人商人，周围尽是赛车与赌博活动。",al={"谁给箱子","克拉维尔的箱子是谁的"}},{q="这个箱子需要送到哪里？",a="箱子必须运往荆棘谷北部的奈辛瓦里狩猎远征队营地，营地位于格罗姆高营地以北的河边。",al={"箱子送到哪里","箱子的目的地","克拉维尔的箱子交给谁"}},{q="货物为什么耽搁了？",a="包裹花了几周才抵达千针石林的盐滩，在这期间，顾客早已收拾行装，动身前往荆棘谷的丛林。",al={"克拉维尔为什么花了这么久","为什么耽搁"}}},fx={["3beca7b7"]={q="什么是克拉维尔的箱子？",a="这是克拉维尔·浓须在闪光平原的沙漠赛道保管的一件沉重货物。箱子经过妥善包装，适合长途运输，准备横越卡利姆多和无尽之海，里面装着专门的狩猎补给品，供前往荆棘谷荒野的探险队使用。",al={"什么是克拉维尔的箱子","克拉维尔的箱子信息","克拉维尔的箱子物品"}},["6061fde3"]={q="为什么有人想要克拉维尔的箱子？",a="箱子里装着专为大型猎物狩猎订购的特殊口径弹药。荆棘谷的奈辛瓦里狩猎队依靠沉重可靠的弹药猎杀丛林中最凶猛的野兽，因此这批延误的货物对他们营地的补给至关重要。",al={"奈辛瓦里为什么想要箱子","克拉维尔的箱子为什么重要","克拉维尔的箱子用途"}}},fp="14,186,24.367.0,24.340.0,30.134.0,24.154.0,33.152.0,29.147.0"}
P.entries["item:kreenig-snarlsnout-s-tusk"] = {n="克里尼格·糟鼻的獠牙",s="在十字路口，索克正等待着克里尼格·糟鼻已被击杀的证据。他的獠牙标志着这位钢鬃首领对贫瘠之地北部部落商队的袭击就此终结。",h="在十字路口，索克正等待着克里尼格·糟鼻已被击杀的证据。他的獠牙标志着这位钢鬃首领对贫瘠之地北部部落商队的袭击就此终结。",kw={"贫瘠之地","十字路口","克里尼格","野猪人","钢鬃","糟鼻","索克","獠牙"},ang={["faction:Horde"]="商队从杜隆塔尔运来武器、补给和定居者，支撑着部落在贫瘠之地的扩张。把这颗獠牙交给索克，有助于保护这些生命线。",["race:Orc"]="对十字路口的兽人来说，从战败的指挥官身上取走战利品是一种务实的作战手段：既能彰显力量，也能在敌人中散播恐慌。"},sec={{t="斩断野心的战利品",b="从杜隆塔尔向西行进的部落商队，在贫瘠之地不断遭到袭击。在凶悍的钢鬃首领克里尼格·糟鼻的带领下，这些袭击变得愈发猖獗。十字路口卫队指挥官索克下令击杀克里尼格，以破坏野猪人的协同作战。他的獠牙既能证明这位首领已死，也能羞辱钢鬃，削弱他们的斗志，让他们的战士失去统一指挥。"}},faq={{q="克里尼格·糟鼻是谁？",a="克里尼格·糟鼻率领着驻扎在十字路口东北方的钢鬃野猪人。他组织袭击沿杜隆塔尔主干道行进的部落商队，直到他死去，这条补给线才摆脱了威胁。",al={"克里尼格·糟鼻","克里尼格是谁","糟鼻的故事"}},{q="索克为什么偏偏要这颗獠牙？",a="索克想用这颗獠牙证明克里尼格已死，同时羞辱钢鬃。取走阵亡酋长的獠牙，会挫伤他们的自尊，打击幸存袭击者的士气。",al={"为什么要獠牙","为什么把獠牙交给索克","索克的獠牙"}},{q="这颗獠牙是从哪里取来的？",a="这颗獠牙取自十字路口东北方的克里尼格·糟鼻营地，那里靠近山脚，就在从杜隆塔尔通往贫瘠之地的主干道南侧。",al={"克里尼格在哪里","哪里能取得獠牙","糟鼻的位置"}},{q="击杀克里尼格会对贫瘠之地产生什么影响？",a="索克相信，失去克里尼格的领导，钢鬃袭击者就会陷入困境。他的死让他们的队伍陷入混乱，遏制了他们对重要补给运输的进一步袭击。",al={"袭击停止了吗","克里尼格之死的后果"}}},fp="25,173,28.413.0,27.207.0,42.176.0,26.185.0,57.174.0"}
P.entries["item:kron-s-amulet"] = {n="克鲁恩的护身符",s="怒水河畔，克鲁恩的护身符让人想起一位失踪的年轻兽人猎手。",h="怒水河畔，克鲁恩的护身符让人想起一位失踪的年轻兽人猎手。",kw={"护身符","恐齿鳄鱼","克鲁恩","米莎·托克伦","剃刀岭","怒水河"},ang={["class:Hunter"]="对猎人而言，克鲁恩的命运是一个惨痛的教训，表明在陌生的河流地带低估凶猛野兽有多么危险。",["race:Orc"]="对兽人而言，克鲁恩的命运表明，骄傲和对武勇荣耀的追求会让人无视长者的智慧，最终招致杀身之祸。"},sec={{t="怒水河上的悲剧",b="克鲁恩是个年轻而莽撞的兽人，来自剃刀岭西北方的一处农庄。他前往与贫瘠之地交界的怒水河沿岸，猎杀凶猛的恐鳄。他的母亲米莎·托克伦曾警告他那里很危险，但骄傲驱使他继续前行。克鲁恩再也没有回来。他的护身符在河中一头猛兽的腹内被发现，证实他已遭到杀害并被吞食。这让米沙痛苦地确认了儿子的命运。"}},faq={{q="克鲁恩是谁？",a="克鲁恩是个年轻而莽撞的兽人猎手，与母亲米莎·托克伦一同住在剃刀岭西北方的一处农庄。尽管有人警告过他河中野兽十分凶猛，他仍独自前去，想与它们较量一番。",al={"克鲁恩是谁","克鲁恩的身世","克鲁恩的故事"}},{q="在哪里能找到克鲁恩的护身符？",a="杜隆塔尔怒水河沿岸的巨齿鳄鱼和堕落的巨齿鳄鱼腹中藏着克鲁恩的护身符。",al={"哪里能找到护身符","克鲁恩的护身符位置","谁掉落克鲁恩的护身符"}},{q="谁希望找回克鲁恩的护身符？",a="米莎·托克伦希望找回克鲁恩的护身符。她在剃刀岭西北方的农庄里等候儿子的消息，而这枚护身符让她痛苦地确认了他的命运。",al={"谁需要护身符","在哪里交还克鲁恩的护身符","米莎·托克伦"}}},fx={["5d838632"]={q="什么是克鲁恩的护身符？",a="这件私人物品属于克鲁恩，他是剃刀岭西北方一座农场里的年轻兽人。他心高气傲，急于证明自己的实力，于是独自前往怒水河，想猎杀贫瘠之地边境附近凶猛的恐怖利口鳄。他没有凯旋而归，反而成了自己想要猎杀的野兽的猎物。这枚护身符连同他的遗骸一起被吞下，是这位年轻猎人仅存的遗物，也能证明他惨死的结局。",al={"什么是护身符","克鲁恩的护身符背景","护身符属于谁"}}},fp="13,87,24.445.1,13.218.0,29.141.1,33.172.1"}
P.entries["item:kuz-s-skull"] = {n="卡兹的颅骨",s="在南贫瘠之地，卡兹的颅骨标志着一名令人畏惧的钢鬃劫掠者的末路。卡兹来自剃刀沼泽，曾协助率领对部落哨站的袭击，后来，一名被囚禁的昔日同族向她寻仇。",h="在南贫瘠之地，卡兹的颅骨标志着一名令人畏惧的钢鬃劫掠者的末路。卡兹来自剃刀沼泽，曾协助率领对部落哨站的袭击，后来，一名被囚禁的昔日同族向她寻仇。",kw={"贫瘠之地","陶拉祖营地","卡兹","卡兹的颅骨","洛克·奥克班恩","碎牙","纳克","钢鬃"},ang={["faction:Horde"]="身为部落的一员，取下卡兹的首级有助于保护十字路口和陶拉祖营地等定居点，使其免受野猪人有组织的袭击。"},sec={{t="深重的仇怨",b="卡兹、纳克和他们的酋长洛克·奥克班恩率领钢鬃在南贫瘠之地四处发动袭击。这三名从剃刀沼泽派出的劫掠者袭击旅人，也袭击十字路口等定居点。他们背叛了同为野猪人的碎牙，使这名同族与他们反目成仇。他们把碎牙丢在陶拉祖营地的笼子里，任其自生自灭。在笼子里，他向愿意杀死卡兹并取下她首级的部落勇士透露了她的位置。"},{t="复仇的凭证",b="卡兹的颅骨向碎牙证明，南方战团的三名首领之一已经死去。对他而言，这颗首级让他尝到了报复那个抛弃他的部族的快意。在贫瘠之地，卡兹之死瓦解了钢鬃袭击行动背后的指挥力量，让横穿平原的补给道路获得了短暂的安宁。"}},faq={{q="卡兹是谁？",a="卡兹是从剃刀沼泽派往南贫瘠之地的三名钢鬃野猪人之一。她与纳克和洛克·奥克班恩一同指挥伏击和劫掠，攻击部落营地与补给线。",al={"卡兹是谁","卡兹背景故事","库兹 钢鬃"}},{q="碎牙为什么想要卡兹的颅骨？",a="碎牙想要卡兹的颅骨，是因为卡兹和其他钢鬃把他丢在陶拉祖营地的笼子里等死。为了在自己死前报仇，他指引部落勇士去寻找仇敌，并要求带回他们的颅骨作为凭证。",al={"碎牙为什么想杀死卡兹","碎牙复仇"}},{q="在贫瘠之地的哪里能找到卡兹？",a="卡兹位于南贫瘠之地，与钢鬃野猪人待在陶拉祖营地以南、靠近荆棘丛生的边境地带。",al={"卡兹位置","哪里能找到卡兹"}},{q="卡兹被杀死后会怎样？",a="当卡兹的颅骨以及纳克和洛克·奥克班恩的首级被送到碎牙手中时，钢鬃袭击行动背后的领导力量便被瓦解，南方商路的安全也因此得到保障。",al={"卡兹任务奖励","内奸结局"}}},fp="11,189,13.399.0,20.287.1,12.193.0,38.228.0,34.120.0,32.167.0"}
P.entries["item:laced-pumpkin"] = {n="斑纹南瓜",s="在药剂师乔汉手中，斑纹南瓜让普通的瓜果变成了被遗忘者炼金术的致命试验品。在布瑞尔，皇家药剂师学会正寻求用来对付天灾军团和活人人类部队的武器。",h="在药剂师乔汉手中，斑纹南瓜让普通的瓜果变成了被遗忘者炼金术的致命试验品。在布瑞尔，皇家药剂师学会正寻求用来对付天灾军团和活人人类部队的武器。",kw={"药剂师乔汉","布瑞尔","血色十字军俘虏","恐惧之末","斑纹南瓜","皇家药剂师学会","提瑞斯法林地"},ang={["faction:Alliance"]="身为联盟的一员，你知道一名被俘的狂热者在被遗忘者领地中遭遇了可怖的命运。他的下场清楚地提醒着人们，被生擒的人类可能面临怎样的结局。",["race:Undead"]="身为被遗忘者的一员，你知道皇家药剂师学会会不择手段，确保提瑞斯法免受狂热的活人十字军侵扰。把普通食物变成武器，正体现了他们务实的作风。"},sec={{t="苦涩的收获",b="在提瑞斯法林地，这南瓜看起来只是从枯萎的土地中抢收的普通作物。布瑞尔的药剂师乔汉用实验性毒素处理南瓜，意在发挥亡灵的全部潜能。皇家药剂师学会正寻求用来对付北方的天灾军团和从南方推进的活人人类部队的武器。即便是普通的收成，也可能携带病原体与致命毒剂。"},{t="地窖中的实验",b="在恐惧之末旅店的地窖里，被遗忘者看守囚禁着一名饥肠辘辘的血色十字军俘虏。俘虏急需食物充饥，便接受了送来的有毒食物。斑纹南瓜中含有药剂师乔汉调制的药剂，吃下后便会引发剧烈的变异。这名狂热的人类变成了毫无心智的食尸鬼，在痛苦中踉跄了片刻，随后倒毙在冰冷的石地板上。"}},faq={{q="斑纹南瓜是什么？",a="斑纹南瓜是普通的田间瓜果，用布瑞尔的药剂师乔汉调制的实验配方处理而成。这种配方旨在测试被遗忘者炼金术对活体的影响。",al={"斑纹南瓜","有毒南瓜","乔汉南瓜"}},{q="谁吃下了斑纹南瓜？",a="一名血色十字军俘虏被被遗忘者看守囚禁在布瑞尔恐惧之末旅店下方的地窖中，挨饿后吃下了送来的有毒食物。",al={"谁吃了它","南瓜的目标","喂食南瓜"}},{q="吃下南瓜后会发生什么？",a="南瓜中的药剂引发了剧烈的变异：俘虏变成了毫无心智的食尸鬼，在痛苦中踉跄了片刻，随后倒毙在冰冷的石地板上。",al={"南瓜效果","狂热者会怎样","狂热者食尸鬼"}},{q="被遗忘者为什么要制作这种东西？",a="药剂师乔汉和皇家药剂师学会调制新的生化药剂，用来对付北方的天灾军团和从南方推进的活人人类。他们用俘获的敌人作为实验对象。",al={"为什么制作有毒南瓜","被遗忘者瘟疫试验"}}},fp="13,177,16.375.0,21.383.1,26.160.0,27.168.0,43.170.1,31.201.0"}
P.entries["item:laird-s-response"] = {n="莱尔德的回信",s="在泰达希尔沿岸，莱尔德的回信为尼莎·影歌带来了一个谜题。那里的鱼比黑海岸大陆沿岸的鱼更大，数量也更多。",h="在泰达希尔沿岸，莱尔德的回信为尼莎·影歌带来了一个谜题。那里的鱼比黑海岸大陆沿岸的鱼更大，数量也更多。",kw={"奥伯丁","黑海岸","钓鱼","莱尔德","莱尔德的回信","尼莎·影歌","鲁瑟兰村","泰达希尔"},ang={["race:NightElf"]="作为一名照看泰达希尔海岸的暗夜精灵，你或许会觉得莱尔德的记录引人入胜，又有些令人不安：这棵年轻的世界之树可能已经开始影响周围的自然环境。"},sec={{t="鱼鳞与树根之谜",b="莱尔德比较了迷雾之海两岸的渔获。泰达希尔沿海的鱼比黑海岸大陆海滩一带的鱼更大，数量也更多。在给尼莎·影歌的回信中，奥伯丁的莱尔德提出了一种推测：新近种下的世界之树所散发的非凡气息与生命力，或许正在改变周围的海洋生物。旅人带着他的信渡海前往鲁瑟兰村，那里的渔民怀着惊奇与淡淡的好奇，听取了这个消息。"}},faq={{q="莱尔德的回信是什么？",a="莱尔德的回信是奥伯丁的鱼商兼腌鱼师莱尔德写的一封信，答复了身在泰达希尔的尼莎·影歌的询问。",al={"这是什么物品","莱尔德的回信","莱尔德的回信是什么"}},{q="莱尔德在给谁写信？",a="莱尔德写信给尼莎·影歌，她是一名暗夜精灵，住在泰达希尔南部树脚下的鲁瑟兰村。",al={"谁收到莱尔德的回信","这封信交给谁","尼莎 莱尔德 信件"}},{q="信中是怎么说这些鱼的？",a="莱尔德在信中写道，泰达希尔沿岸的鱼比黑海岸大陆沿岸的鱼更大，数量也更多。他怀疑世界之树可能影响了附近的海洋生物。",al={"鱼为什么这么大","黑海岸 泰达希尔 鱼的差异","莱尔德发现了什么"}},{q="这封信如何送回鲁瑟兰村？",a="送信人可以从奥伯丁的码头搭乘定期渡船，也可以找飞行管理员凯莱斯·月羽安排角鹰兽航程。",al={"如何返回尼莎身边","鲁瑟兰村 船 黑海岸","奥伯丁 渡船 前往尼莎"}}},fp="16,154,28.461.0,25.127.0,24.108.0,40.176.0,55.135.0"}
P.entries["item:lake-creeper-moss"] = {n="湖岸爬行者苔藓",s="在洛丹米尔湖南部的黎明岛周围，湖岸爬行者苔藓生长在水生野兽身上。皇家药剂师学会正在搜集这种有机化合物，将其作为研制致命新瘟疫的关键试剂。",h="在洛丹米尔湖南部的黎明岛周围，湖岸爬行者苔藓生长在水生野兽身上。皇家药剂师学会正在搜集这种有机化合物，将其作为研制致命新瘟疫的关键试剂。",kw={"博拉尔德","黎明岛","老年湖岸爬行者","大药剂师法拉尼尔","湖岸爬行者","湖岸爬行者苔藓","洛丹米尔湖","新的瘟疫","皇家药剂师学会"},ang={["profession:Herbalism"]="尽管这种苔藓生长在水生野兽身上而非土壤中，它仍属于洛丹伦那些被采集用于药剂研究的阴暗实验性植物。",["race:Undead"]="每一份送往炼金房的样本，都让被遗忘者离完善新的瘟疫更近一步，也让他们更有把握向Scourge和生者复仇。"},sec={{t="炼金采集",b="湖岸爬行者苔藓生长在南部黎明岛附近水域的淡水野兽皮肤上。洛丹伦遭受污染的水域造就了它独特的性质。在阿鲁高的诅咒吞噬其心智之前，药剂师博拉尔德曾在日记中记录这种苔藓。他指出，它与湖中死于古老瘟疫的生物化石上发现的痕迹相似。被遗忘者的特工将收集到的样本送往幽暗城的炼金房，供大药剂师法拉尼尔研究。"},{t="助力研制新的瘟疫",b="湖岸爬行者苔藓是研制被遗忘者标志性武器的关键一环。它与从湖岸潜藏者身上采集的苔藓，以及从当地邪鳍鱼人身上取下的病变肿瘤一起，为改良一种旨在同时灭绝活体组织和天灾军团的瘟疫菌株提供有机基础。尽管发现其用途的药剂师已不复往昔，皇家药剂师学会仍在为黑暗女王效命，继续按他的配方调制药剂。"}},faq={{q="湖岸爬行者苔藓有什么用途？",a="大药剂师法拉尼尔和皇家药剂师学会在幽暗城将湖岸爬行者苔藓用作炼金试剂，调制并改良他们的新的瘟疫。",al={"湖岸爬行者苔藓用途","为何收集湖岸爬行者苔藓","湖岸爬行者苔藓用处"}},{q="这种苔藓来自哪里？",a="湖岸爬行者苔藓生长在洛丹米尔湖东部、南部黎明岛周围水域的湖岸爬行者和老迈的湖岸爬行者身上。",al={"哪里获取湖岸爬行者苔藓","湖岸爬行者苔藓位置","湖岸爬行者位置"}},{q="谁发现了这种苔藓的炼金价值？",a="在阿鲁高的诅咒使药剂师博拉尔德沦为焚木村中失去心智的仆从之前，他曾在野外日志中记下这种苔藓的炼金特性。药剂师伦弗利尔后来找回了他的笔记。",al={"谁发现了苔藓","博拉尔德苔藓","谁记录了湖岸爬行者苔藓"}},{q="采集的苔藓交给谁？",a="大药剂师法拉尼尔在幽暗城的炼金房接收这些苔藓。他在研究中将它与湖岸潜藏者苔藓和硬瘤结合使用。",al={"谁需要湖岸爬行者苔藓","交付湖岸爬行者苔藓","大药剂师法拉尼尔苔藓"}}},fp="17,190,18.486.0,22.414.1,35.160.0,31.139.0,43.207.0,32.158.0"}
P.entries["item:lake-skulker-moss"] = {n="湖岸潜藏者苔藓",s="在洛丹米尔湖北部，湖岸潜藏者苔藓引起了皇家药剂师学会的注意。在阿鲁高的诅咒吞噬他的心智之前，药剂师博拉尔德已将它认定为研制新的瘟疫所需的一种有机成分。",h="在洛丹米尔湖北部，湖岸潜藏者苔藓引起了皇家药剂师学会的注意。在阿鲁高的诅咒吞噬他的心智之前，药剂师博拉尔德已将它认定为研制新的瘟疫所需的一种有机成分。",kw={"博拉尔德","黎明岛","法拉尼尔","洛丹米尔湖","湖岸潜藏者","湖岸潜藏者苔藓","新的瘟疫","伦弗利尔"},ang={["race:Undead"]="身为Undead，你帮助皇家药剂师学会进一步完善新的瘟疫，被遗忘者打算用这种武器对付Scourge和生者。"},sec={{t="瘟疫试剂",b="湖岸潜藏者苔藓采自黎明岛的湖岸潜藏者和老年 湖岸潜藏者。在阿鲁高的诅咒吞噬他的心智之前，药剂师博拉尔德曾记录银松森林东部的动植物。他在日记中写道，湖岸潜藏者和湖岸爬行者身上的苔藓可以稳定其他成分，或与之发生反应。博拉尔德沦为阿鲁高毫无心智的仆从后，有人从焚木村找回了他的日记，交给药剂师伦弗利尔。伦弗利尔派遣被遗忘者的勇士收集苔藓，以及当地邪鳍鱼人身上的一种稀有肿瘤，再将两者送交幽暗城的大药剂师法拉尼尔。"}},faq={{q="湖岸潜藏者苔藓有什么用途？",a="幽暗城的皇家药剂师学会将湖岸潜藏者苔藓用作配制新的瘟疫的有机基质，以实现希尔瓦娜斯·风行者女士为被遗忘者定下的目标。",al={"苔藓用途","为何收集湖岸潜藏者苔藓","湖岸潜藏者苔藓的作用"}},{q="这种苔藓来自哪里？",a="湖岸潜藏者苔藓刮取自黎明岛周围水域中的湖岸潜藏者和老迈的湖岸潜藏者。那里位于银松森林近岸的洛丹米尔湖东北部。",al={"哪里获取湖岸潜藏者苔藓","湖岸潜藏者苔藓位置","谁掉落湖岸潜藏者苔藓"}},{q="是谁发现了这种苔藓的用途？",a="药剂师博拉尔德在研究银松森林时发现了这种苔藓的潜力。阿鲁高的诅咒使他沦为毫无心智的仆从后，他的日记帮助药剂师伦弗利尔和大药剂师法拉尼尔继续进行实验。",al={"谁发现了苔藓","博拉尔德苔藓","药剂师博拉尔德的研究"}},{q="谁需要这种试剂？",a="大药剂师法拉尼尔是幽暗城炼金房中皇家药剂师学会的领袖，他的生物战计划需要这种苔藓。",al={"谁需要湖岸潜藏者苔藓","法拉尼尔湖岸潜藏者苔藓"}}},fp="17,194,16.613.0,35.178.0,31.179.0,37.225.0,26.149.0"}
P.entries["item:large-candle"] = {n="大蜡烛",s="在艾尔文的矿洞里，狗头人携带大蜡烛，用来照明和提供蜡料。药剂师很看重这些蜡料，将其用于制药。",h="在艾尔文的矿洞里，狗头人携带大蜡烛，用来照明和提供蜡料。药剂师很看重这些蜡料，将其用于制药。",kw={"法戈第矿洞","闪金镇","金牙","玉石矿洞","狗头人蜡烛","大蜡烛","蜡","威廉·匹斯特"},ang={["faction:Alliance"]="联盟冒险者夺取艾尔文狗头人的蜡烛，既削弱了矿洞中这些害物的势力，也为暴风城的制药业提供了重要原料。",["profession:Mining"]="在法戈第和玉石开采矿脉的矿工，常常遭到盘踞其中的狗头人侵扰。狗头人既觊觎黄金，也贪恋大蜡烛的光亮。"},sec={{t="地下的烛光与蜡料",b="狗头人借着烛光，穿行于艾尔文森林地下漆黑的矿道。它们把蜡烛固定在头上，狗头人矿工、狗头人隧道工和狗头人地卜师会拼死保护蜡烛，不让入侵者夺走。法戈第矿洞和玉石矿洞出产的大蜡烛虽然制作粗糙，却含有宝贵的蜡料。地表的工匠无法一次制出大量蜡料，因此这些蜡烛既是狗头人的工具，也是炼金师需要的货物。"},{t="蜡料生意与药剂师",b="威廉·匹斯特是一名来自暴风城的药剂师代理人，在闪金镇的狮王之傲旅店收集大蜡烛。他的家族经营着一家药剂店，需要熔炼出的蜡料来制作药剂、香膏和药膏。匹斯特雇用过路的冒险者清剿盘踞在矿洞中的狗头人，并夺取它们的蜡烛。"}},faq={{q="大蜡烛有什么用途？",a="威廉·匹斯特在闪金镇收集大蜡烛，供他与兄弟在暴风城合开的药剂店使用。他们熔化蜡烛，提取蜡料，用于制作药膏、香膏和炼金配方中的制品。",al={"大蜡烛用途","为什么收集大蜡烛","谁需要大蜡烛"}},{q="哪里能找到大蜡烛？",a="艾尔文森林矿洞中的狗头人携带着大蜡烛，尤其是在闪金镇以南的法戈第矿洞和东面的玉石矿洞。挖掘工、矿工和地卜师都会携带大蜡烛。",al={"大蜡烛位置","哪里获取大蜡烛","狗头人蜡烛掉落"}},{q="狗头人为什么把蜡烛顶在头上？",a="狗头人借助烛光挖掘，并在漆黑的地下隧道中辨认方向。它们把蜡烛固定在头上，腾出双手使用矿镐、施展地卜法术和挥舞武器。",al={"狗头人为什么带蜡烛","狗头人头顶蜡烛背景"}},{q="威廉·匹斯特是谁？",a="威廉·匹斯特是一名来自暴风城的药剂师代理人，在闪金镇的狮王之傲旅店经营生意。他从荒野和矿洞中收集原料，供应他与兄弟合开的药剂店。",al={"威廉·匹斯特背景","闪金镇的药剂师是谁"}}},fx={["05873d56"]={q="大蜡烛是什么？",a="大蜡烛是一种粗制而粗大的蜡烛，由栖居在艾尔文森林矿洞中的狗头人随身携带。狗头人对光源的看护出了名地严密，在法戈第和玉石等矿洞中挖掘黄金与矿物时，会用这些粗大的蜡烛照亮漆黑的地下隧道。",al={"大蜡烛是什么","大蜡烛 艾尔文","大蜡烛背景"}}},fp="12,108,26.430.0,24.316.0,32.199.0,33.177.0,44.194.0,22.229.0"}
P.entries["item:large-soran-ruk-fragment"] = {n="索兰鲁克宝珠的大碎片",s="索兰鲁克宝珠的大碎片藏于影牙城堡，远离其他碎片。它所属的破碎宝珠曾囚禁着一名蒙羞的燃烧军团恶魔。",h="索兰鲁克宝珠的大碎片藏于影牙城堡，远离其他碎片。它所属的破碎宝珠曾囚禁着一名蒙羞的燃烧军团恶魔。",kw={"燃烧军团","杜安·卡汉","索兰鲁克宝珠的大碎片","索兰鲁克宝珠","影牙城堡","索兰鲁克"},ang={["class:Warlock"]="夺回索兰鲁克宝珠的大碎片，就能让你掌控其中受困的恶魔灵魂，并帮助杜安·卡汉重铸一件施展恶魔法术的强大武器。"},sec={{t="索兰鲁克的遗产",b="蒙羞的燃烧军团恶魔可能会被判囚禁于附有魔法的宝珠之中。效忠于燃烧军团的法师和术士会得到这些容器，汲取其中封存的邪能力量。即使宝珠破碎，被束缚的恶魔留下的精华仍会散发力量。每块碎片都会吸引野心勃勃的暗影魔法修习者。"},{t="暗影之牙中的碎片",b="索兰鲁克宝珠很久以前就裂成了两半。别处的邪教徒将其中一半打散成了更小的碎片。一名巫师占有了较大的那一半，藏于受诅咒的影牙城堡。暗影之牙 暗魂携带着索兰鲁克宝珠的大碎片，其中束缚着那个灵魂，直到有人前来寻求重铸这件古老的容器。"}},faq={{q="索兰鲁克宝珠的大碎片是什么？",a="索兰鲁克宝珠的大碎片是索兰鲁克宝珠较大的那一半，这件古老的容器中束缚着一名蒙羞的燃烧军团恶魔的灵魂。",al={"索兰鲁克宝珠的大碎片","这块碎片是什么"}},{q="在哪里能找到这块碎片？",a="暗影之牙 黑魂在影牙城堡中持有这块碎片，那是一座位于银松森林的闹鬼要塞。",al={"大碎片在哪里","大碎片位置","谁掉落索兰鲁克宝珠的大碎片"}},{q="宝珠为何破碎？",a="原本的宝珠被分成了两大块。较小的那一半被打成碎片，带到了黑暗深渊的海滨洞穴中，而黑暗巫师将较大的那一半留在了影牙城堡。",al={"宝珠如何破碎","宝珠为何碎裂","索兰鲁克宝珠的历史"}},{q="谁想重新拼合宝珠？",a="杜安·卡汉是南贫瘠之地一位深居简出的隐士，他毕生致力于研究并重铸燃烧军团失落的宝珠。",al={"谁需要大碎片","谁重新拼合宝珠"}}},fp="24,146,23.317.0,23.330.0,37.138.0,28.99.0,23.199.0,27.145.0"}
P.entries["item:laughing-sister-s-hair"] = {n="欢笑姐妹的头发",s="在灰谷，欢笑姐妹的头发蕴含着自然魔法，吸引着前来寻觅的织工。十字路口的基尔哈拉用收集来的发丝制作附魔长袍。",h="在灰谷，欢笑姐妹的头发蕴含着自然魔法，吸引着前来寻觅的织工。十字路口的基尔哈拉用收集来的发丝制作附魔长袍。",kw={"灰谷","布料","十字路口","迪诺","树妖","头发","基尔哈拉","欢笑的姐妹","林中树居"},ang={["faction:Horde"]="身为部落的一员，你必须进入灰谷的暗夜精灵领地，杀死林地精魂，夺取她们的发丝，以武力攫取当地的魔法。",["profession:Tailoring"]="对裁缝而言，树妖的发丝是一种珍奇的丝线，能将自然魔法织入布料之中。"},sec={{t="稀有的纺织材料",b="在灰谷的林中树居附近，欢笑姐妹是一群头发蕴含自然魔法的树妖。树妖守护着森林，与塞纳留斯和暗夜精灵有着联系。部落工匠视她们的头发为效力强大的制作材料。基尔哈拉是十字路口的一名巨魔裁缝，他将这些发丝织成附魔长袍，供迪诺门下前途无量的奥术学徒穿用。"}},faq={{q="欢笑姐妹的头发从何而来？",a="这些头发来自欢笑姐妹，她们是在灰谷中部、林中树居附近的魔法林地中游荡的树妖。",al={"哪里获取欢笑姐妹的头发","欢笑姐妹的头发位置","树妖头发来源"}},{q="基尔哈拉为什么要寻找树妖的头发？",a="基尔哈拉是贫瘠之地十字路口的一名裁缝，他用这些充满魔力的发丝编织附魔布袍，供迪诺门下前途无量的学徒穿用。",al={"基尔哈拉为何需要头发","欢笑姐妹的头发用途","巨魔裁缝树妖头发"}},{q="欢笑姐妹会自愿交出头发吗？",a="不会。欢笑姐妹守护自然，保卫灰谷。正如基尔哈拉所说，树妖绝不会自愿将头发交给部落的爪牙。",al={"能否向树妖索取头发","树妖是否捐出头发"}}},fx={["3a458879"]={q="什么是欢笑姐妹的头发？",a="欢笑姐妹的头发是从欢笑姐妹身上剪下的发束。她们是居住在灰谷林中树居附近的林地树妖。这些发丝蕴含着塞纳留斯女儿们的自然优雅与魔力，技艺精湛的裁缝将其视为珍贵的织布材料，可用来制作强大的施法衣物。",al={"什么是欢笑姐妹的头发","欢笑姐妹的头发信息","树妖头发材料"}}},fp="22,138,24.333.0,44.136.0,39.136.0,55.149.0"}
P.entries["item:legacy-of-the-aspects"] = {n="巨龙的遗产",s="《巨龙的遗产》是一本古老的典籍，藏在灰谷南部的朵丹尼尔兽穴深处。这本书是在部落的一场智力试炼中取回的，记载了塑造远古艾泽拉斯的守护巨龙的重要 传说。",h="《巨龙的遗产》是一本古老的典籍，藏在灰谷南部的朵丹尼尔兽穴深处。这本书是在部落的一场智力试炼中取回的，记载了塑造远古艾泽拉斯的守护巨龙的重要 传说。",kw={"灰谷","兽穴","布劳格·幽魂","朵丹尼尔","巨龙的遗产","石爪小径","知识试炼"},ang={["class:Druid"]="典籍藏在朵丹尼尔兽穴深处，周围尽是死去的暗夜精灵德鲁伊悲苦而饱受折磨的灵魂。",["faction:Horde"]="这本典籍是一项传统成人仪式的核心，用来考验部落冒险者是否拥有与自身力量相称的智慧与学识。"},sec={{t="心智的考验",b="牛头人长者先前设下的试炼考验体能与意志，而寻找《巨龙的遗产》则旨在考验心智。布劳格·幽魂在石爪山脉的石爪小径入口处交付任务，要求试炼者深入朵丹尼尔闹鬼的兽穴。古老的典籍放在一座石台上，由死去德鲁伊的不安亡魂，以及杀害他们的凶恶生物守护。取得典籍只是第一步；求知者必须在交出书本前牢记其中的内容，因为接下来要接受书中历史知识的考验。"}},faq={{q="这本书在哪里？",a="这本书放在朵丹尼尔兽穴下层洞室的一座石台上，兽穴位于灰谷南部、碎木岗哨以南。",al={"寻找巨龙的遗产","书的位置","书在哪里"}},{q="布劳格·幽魂为什么想要这本书？",a="布劳格·幽魂用这本典籍进行知识试炼。这场试炼与体能挑战不同，旨在判断冒险者是否具备研读并记住重要历史知识所需的才智与专注。",al={"布劳格为何要书","知识试炼的目的"}},{q="如果没有研读典籍就去与布劳格交谈，会发生什么？",a="布劳格收下典籍后，会立即就书中的知识向求知者提问。答错的人会立刻遭到魔法放逐，毫无准备的求教者会被传送到遥远的贫瘠之地陶拉祖营地。",al={"答错的后果","试炼失败"}}},fx={["32a02485"]={q="什么是巨龙的遗产？",a="巨龙的遗产是一部古老而珍贵的典籍，深藏在灰谷南部的朵丹尼尔兽穴中。它由陨落德鲁伊的躁动灵魂和杀害他们的邪恶生物把守，书中记载着关于巨龙守护者的历史传说。想要取回它的人，必须经受严格的智慧与记忆考验。",al={"什么是巨龙的遗产","巨龙的遗产典籍","这本书是什么"}}},fp="21,226,18.582.0,26.144.0,40.174.0,68.193.0"}
P.entries["item:letter-to-delgren"] = {n="写给德尔格伦的信",s="巴苏尔·影击从黑海岸北部的奥萨拉克斯之塔发来警告。他写给净化者德尔格伦的信描述了暗滩教派教团的恶魔勾当，必须送到灰谷的迈斯特拉岗哨。",h="巴苏尔·影击从黑海岸北部的奥萨拉克斯之塔发来警告。他写给净化者德尔格伦的信描述了暗滩教派教团的恶魔勾当，必须送到灰谷的迈斯特拉岗哨。",kw={"灰谷","巴苏尔·影击","暗滩教派","黑海岸","净化者德尔格伦","写给德尔格伦的信","迈斯特拉岗哨","奥萨拉克斯之塔"},ang={["class:Paladin"]="身为圣骑士，你可以看到一名人类圣骑士向一名暗夜精灵传授圣光之道，将Kaldorei的土地与东部王国的尚武信仰联系起来。",["faction:Alliance"]="身为联盟的一员，你可以看到人类勇士与暗夜精灵Sentinels并肩作战，对抗卡利姆多北部的恶魔教团。"},sec={{t="送往南方的警告",b="巴苏尔·影击监视着聚集在奥萨拉克斯之塔废墟周围的暗滩教派教团。他无法独自消灭这个教团，于是写信向教导他圣光之道的导师净化者德尔格伦求援。教团的邪恶仪式威胁的不只是黑海岸沿岸。这封信必须向南穿过这片地区，送往灰谷西部，德尔格伦正在那里与暗夜精灵哨兵共同对抗恶魔和亡灵的威胁。"}},faq={{q="写给德尔格伦的信是什么？",a="写给德尔格伦的信是巴苏尔·影击发出的一封密封信件，讲述了暗滩教派教团在奥萨拉克斯之塔日益频繁的活动。收信人是净化者德尔格伦。",al={"这封信是什么","写给德尔格伦的信","巴苏尔的信"}},{q="净化者德尔格伦是谁？",a="净化者德尔格伦是驻守灰谷西部迈斯特拉岗哨的一名人类圣骑士。他侍奉圣光，协助暗夜精灵哨兵对抗古老森林中的恶魔和亡灵，并指导巴苏尔如何以神圣之力作战。",al={"德尔格伦是谁","德尔格伦的故事","德尔格伦在哪里"}},{q="巴苏尔为什么要把信送到那么远的地方？",a="巴苏尔是德尔格伦的学生，希望借助导师的本领对抗恶魔腐化。在迈斯特拉岗哨，德尔格伦可以凭借自己的战斗技艺和当地哨兵的兵力，阻止暗滩教派的黑暗仪式。",al={"为什么送往灰谷","为什么不告诉奥伯丁"}},{q="这封信需要送到哪里？",a="带着信向南穿过黑海岸，越过边界进入灰谷，送到西部道路沿线的迈斯特拉岗哨。",al={"信送到哪里","信件送达地点"}}},fp="17,204,20.414.0,30.134.0,28.229.0,47.214.0,44.122.0"}
P.entries["item:letter-to-ello"] = {n="写给艾尔罗的信",s="亚伯克隆比给夜色镇的镇长埃伯洛克寄去了一封密封的信。这位隐士住在乌鸦岭墓地正北边的一间小屋里，自称是镇长的老朋友，用古老的文字写下了这封信。",h="亚伯克隆比给夜色镇的镇长埃伯洛克寄去了一封密封的信。这位隐士住在乌鸦岭墓地正北边的一间小屋里，自称是镇长的老朋友，用古老的文字写下了这封信。",kw={"亚伯克隆比","夜色镇","暮色森林","埃伯洛克","写给艾尔罗的信","给镇长的信","希拉·沃宁迪"},ang={["faction:Alliance"]="作为一名在暮色森林旅行的联盟旅者，你可能会替一位古怪的隐士给镇长送信。夜色镇的官员们对来历蹊跷的信件始终心存戒备。"},sec={{t="古怪的问候",b="你帮助亚伯克隆比完成暮色森林各处的差事后，这位年迈的隐士交给你一封信，要你转交给镇长埃伯洛克。他说镇长是他的老朋友，会为你的成就而庆贺。艾尔罗拆开信封，却完全不记得有谁叫亚伯克隆比，也读不懂那些古老文字中的任何一句话。他把信交给夜色镇的学者希拉·沃宁迪翻译。"},{t="不祥之兆",b="亚伯克隆比的符文为夜色镇带来了不祥的消息。信中讲述的并非镇上熟人之间的旧日情谊，而是整个镇子即将面临的灭顶之灾。"}},faq={{q="《写给艾尔罗的信》是谁写的？",a="这封信是亚伯克隆比写的。他是一位隐士，住在暮色森林西部乌鸦岭墓地附近的一间破旧小屋里。",al={"信是谁写的","写给艾尔罗的信作者","谁寄的信"}},{q="镇长埃伯洛克能读懂这封信吗？",a="不能。埃伯洛克拆开信封后，完全看不懂信上的文字，那似乎是一种古老而无法辨认的语言。",al={"艾尔罗能读懂信吗","艾尔罗为什么读不懂信","艾尔罗信件语言"}},{q="谁能翻译这封信？",a="希拉·沃宁迪能翻译这封信。埃伯洛克镇长把信交给了这位住在夜色镇的学者，她通晓古代文字和晦涩的语言。",al={"谁翻译这封信","翻译亚伯克隆比的信","谁能读懂这封信"}},{q="埃伯洛克镇长真的认识亚伯克隆比吗？",a="不认识。尽管亚伯克隆比声称他们是老朋友，埃伯洛克却说自己从未听说过有谁叫亚伯克隆比。",al={"艾尔罗认识亚伯克隆比吗","艾尔罗和亚伯克隆比是朋友吗","亚伯克隆比的老朋友艾尔罗"}}},fx={["74d18927"]={q="写给艾尔罗的信是什么？",a="写给艾尔罗的信是一封神秘信件，由隐士亚伯克隆比用一种古老而难以辨认的语言写成。信直接寄给夜色镇镇长艾尔罗·埃伯洛克，隐士声称，这封信会让他的“老朋友”知道你在墓地里所做的事。",al={"写给艾尔罗的信","写给艾尔罗的信是什么","亚伯克隆比的便条"}},ee8215fa={q="艾伯洛克镇长为什么想要写给艾尔罗的信？",a="艾伯洛克镇长想要这封信，只是因为你带来了消息，说一位名叫亚伯克隆比的老朋友寄信给他。然而收到信后，镇长发现自己看不懂上面的古老文字，于是急切地想找人翻译，以弄清隐士的真实意图。",al={"艾尔罗为什么想要这封信","为什么想要写给艾尔罗的信","为什么要把信送给艾尔罗"}}},fp="14,205,18.399.0,10.165.1,29.117.0,41.155.0,27.151.0,47.119.1"}
P.entries["item:letter-to-jin-zil"] = {n="写给金吉尔的信",s="在十字路口，写给金吉尔的信带来了塞瑞娜·血羽败亡的消息。达索克·快刀将信寄给石爪山脉的暗矛巫医，告诉他贫瘠之地北部已摆脱血羽的威胁。",h="在十字路口，写给金吉尔的信带来了塞瑞娜·血羽败亡的消息。达索克·快刀将信寄给石爪山脉的暗矛巫医，告诉他贫瘠之地北部已摆脱血羽的威胁。",kw={"达索克·快刀","鹰身人","金吉尔","写给金吉尔的信","玛拉卡金","洛克汉","塞瑞娜·血羽","石爪山"},ang={["faction:Horde"]="身为部落旅人，你带着保卫贫瘠之地的消息，走进石爪山脉更深重的纷争之中。",["race:Troll"]="身为巨魔，你可以将信交给巫医金吉尔。这位年长的巫医在回音群岛之外传承着传统巫毒术。"},sec={{t="前往石爪山的信使",b="无水岭的鹰身人被剿灭，塞瑞娜·血羽被杀后，达索克·快刀给一位老战友写了封信。贫瘠之地的鹰身人最初栖居在石爪山脉的群峰之中。达索克将鹰身人主母殒命的消息传给巫医金吉尔，并引荐一位前途可期的勇士，让其走向更广阔的边疆。"},{t="玛拉卡金的旧日回忆",b="在玛拉卡金的洞穴里，金吉尔收到消息，怀念往事之余也感到欣慰。塞瑞娜的死让他想起第三次战争后建立杜隆塔尔的往事，当时他的朋友洛克汉与半食人魔兽王雷克萨联手，杀死了塞瑞娜的姐姐血羽。如今塞瑞娜也已殒命，金吉尔相信血羽一族的复仇就此终结。"}},faq={{q="写给金吉尔的信是谁写的？",a="这封信出自达索克·快刀之手，他是驻守贫瘠之地十字路口的一名兽人。他负责协调防御，抵御四处劫掠的鹰身人族群。",al={"这是谁写的","寄信人","达索克的信"}},{q="金吉尔在哪里？",a="金吉尔住在玛拉卡金的一处洞穴里。玛拉卡金是暗矛巨魔的哨站，位于石爪山脉东南部的峭壁间。",al={"金吉尔在哪里","金吉尔的位置","寻找金吉尔"}},{q="信里带来了什么消息？",a="信中告诉金吉尔，率领鹰身人侵入贫瘠之地北部的塞瑞娜·血羽已被杀死。她的死让十字路口北面的边界得以安宁。",al={"信里说了什么","信中消息"}},{q="金吉尔为何关心血羽一族？",a="金吉尔记得第三次战争后建立杜隆塔尔的往事，当时他的同伴洛克汉与半食人魔战士雷克萨杀死了塞瑞娜的姐姐。自那以后，塞瑞娜一直谋求向部落复仇，因此她的败亡为这段恩怨带来了令人欣慰的了结。",al={"金吉尔为何关心鹰身人","血羽的历史","洛克汉与血羽"}}},fx={f9426e82={q="金吉尔为什么要你把写给金吉尔的信送给他？",a="这封信带来了他久未谋面的老友达索克·快刀从贫瘠之地寄来的消息。金吉尔多年没有达索克的音讯，而信中确认了塞蕾娜·血羽的死讯，终结了长期侵扰贫瘠之地和石爪山的鹰身人族母的威胁。",al={"为什么要把信送给金吉尔","谁想要写给金吉尔的信","金吉尔为什么在意这封信"}}},fp="17,157,25.330.0,26.369.1,32.137.0,25.116.0,41.183.0,46.243.1"}
P.entries["item:letter-to-jorgen"] = {n="写给乔贞的信",s="在暴风城，一封密封的信召请乔贞协助寻找一位失踪的外交官。",h="在暴风城，一封密封的信召请乔贞协助寻找一位失踪的外交官。",kw={"吉安娜·普罗德摩尔","乔贞","写给乔贞的信","失踪的外交官","暴风城","塞拉摩","英雄谷"},ang={["class:Rogue"]="身为潜行者，你知道秘密传递的信件和不情愿开口的街头线人，都能帮助查出首都潜藏的祸患。",["faction:Alliance"]="这封信关乎联盟脆弱的稳定局势，希望低调应对一起威胁暴风城与塞拉摩关系的事件。"},sec={{t="冷淡的召请",b="一位前往塞拉摩的外交官迟迟没有抵达，未能与吉安娜·普罗德摩尔会谈。王室调查人员迅速行动，力求不让此事声张。官方密探搜查首都的同时，其他渠道也有了动静。这封信绕过军中的层层官阶，找上了乔贞，一位在英雄谷巨像下垂钓、脾气粗暴的老兵。信中提及他昔日欠下的人情，将他卷入一场秘密调查，而有关迪菲亚潜行者阴谋的传言正四处流传。"}},faq={{q="这封信有什么用？",a="这封信介绍了送信人的身份，并要求乔贞偿还昔日的人情。它指引送信人前往英雄谷，协助秘密调查外交官失踪一事。",al={"写给乔贞的信有什么用","为什么要写给乔贞的信","信的用途"}},{q="乔贞是谁？",a="乔贞是个深居简出的联络人，就在暴风城城门内，平日里在英雄谷钓鱼。他不喜欢被人打扰，但昔日欠下的人情让他在见到这封信后不得不出手相助。",al={"乔贞是谁","乔贞非玩家角色","乔贞暴风城"}},{q="这封信与哪起失踪事件有关？",a="一位地位显赫的外交官乘船离开暴风城，前往塞拉摩会见吉安娜·普罗德摩尔，却在途中失踪。嫌疑指向迪菲亚潜行者，但整个阴谋的内情仍被严密封锁。",al={"哪位外交官失踪了","谁失踪了","失踪的外交官"}},{q="这封信要送到哪里？",a="这封信要送到英雄谷，那里是暴风城宏伟的入口，两侧矗立着纪念第二次战争英雄的纪念碑。乔贞就在正门附近的水边钓鱼。",al={"信要送到哪里","乔贞的位置","乔贞在哪里"}}},fx={["0eeb183b"]={q="写给乔贞的信是什么？",a="这封信是一份机密消息，涉及一名暴风城外交官在前往塞拉摩途中悄然失踪的事件。由于王室的官方密探已经在城中公开展开搜查，这封密封信函便通过王室常规渠道之外的私人关系，召集行事谨慎的人手，调查迪菲亚潜行者涉嫌参与此事的线索。",al={"写给乔贞的信是什么","写给乔贞的信物品","关于写给乔贞的信"}},["5d64bfbf"]={q="写给乔贞的信来自哪里，是谁写的？",a="这封信出自暴风城的德拉维主教之手，他希望就外交官失踪一事展开独立调查。比起引人注目的王室调查人员，他更信任自己的私人盟友，因此特意写下这封信，向一位名叫乔贞的老友求助，此人眼下正在英雄谷的水边低调度日。",al={"谁写了写给乔贞的信","谁寄出了写给乔贞的信","写给乔贞的信来源"}},["9fd54092"]={q="为什么需要写给乔贞的信？",a="乔贞需要这封信，因为信中交代了一项他无法推卸的秘密职责。虽然他不愿离开安静的垂钓生活，信中的内容还是说服了他，让他在恐慌席卷首都之前，协助查明迪菲亚潜行者的阴谋。",al={"为什么要送写给乔贞的信","乔贞为什么需要这封信","给乔贞送信的目的"}}},fp="16,80,23.440.0,35.174.0,14.196.0,45.206.0,30.181.0"}
P.entries["item:lewis-note"] = {n="刘易斯的便笺",s="在哨兵岭，军需官刘易斯派出一名信使，乘狮鹫为西部荒野的驻军求购护甲。这份订货单将送往暴风城的一名私人护甲商。",h="在哨兵岭，军需官刘易斯派出一名信使，乘狮鹫为西部荒野的驻军求购护甲。这份订货单将送往暴风城的一名私人护甲商。",kw={"狮鹫","刘易斯的便笺","有限的无敌","旧城区","奥斯瑞克·斯图恩","军需官刘易斯","哨兵岭","索尔"},ang={["race:Human"]="作为一名人类冒险者，递送这份订货单能让你学会使用王国的狮鹫航线。这也让你看到，暴风城的统治者在为西部荒野守军配备装备一事上做得有多么少。"},sec={{t="求购护甲",b="哨兵岭的人民军几乎得不到暴风城贵族的支持。与迪菲亚潜行者的零星交战不断消耗着他们本就不多的装备。因此，军需官刘易斯转向私人商贩，为守军补充装备。他的订货单没有通过王国的军需渠道。一名联盟信使必须乘狮鹫飞往旧城区，将订货单交给有限防护的店主奥斯瑞克·斯图恩。"}},faq={{q="刘易斯的便笺是什么？",a="刘易斯的便笺是军需官刘易斯写给暴风城护甲商奥斯瑞克·斯图恩的订货单，请他为西部荒野的驻军送去防护装备。",al={"这是什么物品","刘易斯的便笺用途","便笺有什么用"}},{q="这张便笺是谁写的？",a="这张便笺由军需官刘易斯撰写。他负责管理哨兵岭人民军的物资、给养和军备。",al={"刘易斯是谁","军需官刘易斯"}},{q="这张便笺交给谁？",a="这张便笺先交给哨兵岭的狮鹫管理员索尔。随后，它会被送到奥斯瑞克·斯图恩手中，他的护甲店有限防护位于暴风城的旧城区。",al={"便笺送到哪里","刘易斯的便笺交给谁","奥斯瑞克·斯图恩便笺"}},{q="驻军为什么不直接向王国领取护甲？",a="暴风城的政府对西部荒野多有忽视。当地守军既得不到王室直接拨付的军费，也领不到护甲，因此刘易斯只能依靠奥斯瑞克·斯图恩这样的商人为民兵配备装备。",al={"为什么向奥斯瑞克购买","暴风城为什么不援助","暴风城援助西部荒野"}}},fp="11,153,16.423.0,20.153.0,20.125.0,22.166.0,57.204.0"}
P.entries["item:lieutenant-s-insignia"] = {n="军官的徽章",s="在奥格瑞玛附近，邪教徒携带着军官的徽章，身上带有火刃氏族的印记。部落冒险者从他们身上夺得了这枚徽章。",h="在奥格瑞玛附近，邪教徒携带着军官的徽章，身上带有火刃氏族的印记。部落冒险者从他们身上夺得了这枚徽章。",kw={"火刃氏族","暗影裂口","杜隆塔尔","隐藏的敌人","军官的徽章","尼尔鲁·火刃","暗影议会","骷髅石","萨尔"},ang={["class:Warlock"]="对术士而言，军官的徽章表明火刃氏族正利用邪能魔法为燃烧军团效力。这让萨尔对部落中守法术士的容忍面临考验。",["faction:Horde"]="对年轻的部落而言，军官的徽章揭示了一重威胁：恶魔的腐化正试图从内部颠覆萨尔的新国度。"},sec={{t="邪教的印记",b="杜隆塔尔东海岸骷髅石的邪教徒携带着军官的徽章。这枚徽章表明，佩戴者是火刃氏族的一名军官。大酋长萨尔绝不容忍自己的新国度中出现叛徒。然而，清剿可能会在邪教幕后首脑暴露之前，就让教徒四散逃遁。因此，他将徽章交给一位勇士，用来试探那些涉嫌潜入奥格瑞玛地下的可疑之人。"},{t="暗影裂口",b="大酋长萨尔派遣密探带着军官的徽章前往暗影裂口，向尼尔鲁·火刃出示徽章。尼尔鲁误以为这名密探是刚刚晋升的下属。这位术士自恃地位稳固，夸口说火刃氏族效忠于暗影议会和燃烧军团。这番话让萨尔有了揭露城下腐化势力的突破口。"}},faq={{q="军官的徽章从何而来？",a="骷髅石中的火刃氏族狂热者和学徒携带着军官的徽章。这座洞穴位于奥格瑞玛以东的杜隆塔尔海岸。",al={"如何获得军官的徽章","谁掉落军官的徽章","军官的徽章来源"}},{q="这枚徽章有什么用途？",a="大酋长萨尔将军官的徽章交给密探，用于伪装身份。佩戴它的年轻冒险者可以冒充火刃氏族军官，进入萨尔的密探无法到达的地方，查明是谁在领导这个邪教。",al={"为什么需要军官的徽章","军官的徽章任务用途","徽章有什么用"}},{q="尼尔鲁·火刃是谁？",a="尼尔鲁·火刃是奥格瑞玛暗影裂口中的一名兽人术士。他声称自己效忠萨尔，向人们展示术士如何帮助部落，暗中却领导着当地的火刃氏族邪教。",al={"尼尔鲁是谁","尼尔鲁·火刃背景故事"}},{q="萨尔为什么不直接杀死尼尔鲁·火刃？",a="萨尔知道尼尔鲁是叛徒，但过早出手可能会惊动邪教真正的首脑，让其爪牙四散逃遁。他让尼尔鲁在不知情的情况下充当线人，以查明暗影议会在杜隆塔尔更广泛的势力分布。",al={"萨尔为什么不杀尼尔鲁","为什么留尼尔鲁活口","为什么要潜入尼尔鲁身边"}}},fx={["2e1cfb76"]={q="军官的徽章是什么？",a="这是火刃氏族成员携带的一种徽记，表明持有者是氏族认可的高阶军官。在杜隆塔尔各处秘密活动的恶魔邪教徒会以此信物表明自己对暗影议会网络的忠诚、地位与权威。",al={"军官的徽章是什么","军官徽章是什么东西","火刃氏族徽章"}}},fp="21,121,18.363.0,19.359.1,47.135.0,30.207.1,23.183.2,57.211.1"}
P.entries["item:lightning-gland"] = {n="闪电腺",s="在贫瘠之地，闪电腺取自漫游平原的雷角蜥蜴。棘齿城的酿酒师德罗恩需要它们来酿造洞穴麦酒，这种烈性酒的酿法是老陈风暴烈酒教给他的。",h="在贫瘠之地，闪电腺取自漫游平原的雷角蜥蜴。棘齿城的酿酒师德罗恩需要它们来酿造洞穴麦酒，这种烈性酒的酿法是老陈风暴烈酒教给他的。",kw={"贫瘠之地","酿酒师德罗恩","老陈 风暴烈酒","闪电腺","棘齿城","雷皮蜥蜴","洞穴麦酒"},ang={["profession:Cooking"]="作为厨师，你可以了解酿酒师德罗恩和老陈风暴烈酒如何用生的野兽内脏酿造烈酒，尽管闪电腺并不是普通的食材。"},sec={{t="带电的原料",b="雷角蜥蜴漫游在贫瘠之地的草原上，与其他受到元素影响的掠食者为伍。它们体内有闪电腺，这些器官蕴藏着电能。这些腺体本身并不适合食用，但酿酒师很看重它们为酒液带来的刺激口感。"},{t="德罗恩的洞穴麦酒",b="酿酒师德罗恩在棘齿城延续着老陈风暴烈酒的酿酒传统。为了酿造烈性的洞穴麦酒，德罗恩需要五个闪电腺、一个雷鹰的唾液腺，以及一份新鲜的科多兽的肝脏。酿成的酒入口辛烈，冒险者觉得它既提神又有劲。"}},faq={{q="哪些生物体内有闪电腺？",a="漫游贫瘠之地草原的雷鳞蜥蜴体内有闪电腺。",al={"闪电腺获取地点","闪电腺掉落","雷鳞蜥蜴闪电腺"}},{q="谁需要闪电腺，用来做什么？",a="棘齿城的酿酒师德罗恩需要闪电腺来酿造洞穴麦酒，配方是云游的酿酒师老陈风暴烈酒传授给他的。",al={"谁需要闪电腺","闪电腺交付","闪电腺用途"}},{q="除了闪电腺，还需要什么？",a="德罗恩需要五个闪电腺、一个取自大型雷鹰的雷鹰的唾液腺，以及一份取自贫瘠之地野兽的新鲜的科多兽的肝脏。",al={"德罗恩的洞穴麦酒原料","老陈的空酒桶三种物品"}}},fp="15,155,21.241.0,17.277.0,38.63.0,35.131.0,50.143.0"}
P.entries["item:logging-rope"] = {n="伐木绳",s="在战歌伐木营地，伐木绳是维持锯木厂和机械运转的物资。熊怪部族在灰谷各地劫走了运送的物资，战歌只得夺回所需的绳索。",h="在战歌伐木营地，伐木绳是维持锯木厂和机械运转的物资。熊怪部族在灰谷各地劫走了运送的物资，战歌只得夺回所需的绳索。",kw={"灰谷","污林","洛克·奥卡尔","伐木绳","碎木岗哨","蓟皮","战歌伐木营地","战歌物资"},ang={["faction:Horde"]="夺回伐木绳有助于战歌氏族在熊怪的伏击下维持木材供应。",["race:Orc"]="身为兽人，你依靠灰谷的木材在卡利姆多定居。伐木物资被盗，威胁着这项工作。"},sec={{t="被盗的绳索",b="运往战歌伐木营地的伐木绳被盗了。污林和蓟皮熊怪在绳索送到伐木工手中之前将其截走。这些部族将绳索藏在灰谷北部和中部各处的营地中。腐化使熊怪陷入疯狂，它们拼死守护着祖传的林地。"},{t="供应战备物资",b="碎木岗哨的洛克·奥卡尔希望在战歌伐木营地停工之前追回被盗的补给。这种粗重的绳索可供部落固定木材、捆扎原木和架设锯木机械。熊怪仍在森林各处抵抗。"}},faq={{q="伐木绳有什么用途？",a="战歌伐木营地使用伐木绳在灰谷固定采伐的木材、拖运原木，以及装配重型机械。",al={"伐木绳用途","战歌为何需要绳索","战歌伐木绳"}},{q="谁偷走了伐木绳？",a="污林和蓟皮熊怪偷走了伐木绳，并将其藏在灰谷各地村落的巢穴和营地中。",al={"谁拿走了绳索","偷绳者","哪些熊怪持有绳索"}},{q="谁想要回这些绳索？",a="碎木岗哨的洛克·奥卡尔希望追回绳索和其他被盗的补给，让战歌伐木营地能够继续运作。",al={"谁需要伐木绳","伐木绳任务给予者"}},{q="熊怪为什么要偷伐木物资？",a="熊怪偷走伐木物资，是为了扰乱部落锯木厂的运作，抵抗部落在它们祖传林地中的采伐。",al={"熊怪的动机","熊怪为何袭击运输队"}}},fx={["26f07746"]={q="伐木绳是什么？",a="伐木绳是战歌氏族在灰谷开展大规模伐木作业时不可或缺的重型绳索。它用于固定、拖运和捆绑砍伐下来的巨木，是伐木营地日常采伐作业的重要物资。",al={"伐木绳是什么","伐木绳信息","战歌氏族伐木绳"}}},fp="12,184,12.342.0,24.231.0,30.118.0,27.130.0,25.136.0,43.120.0"}
P.entries["item:lok-s-skull"] = {n="洛克·奥克班恩的颅骨",s="在贫瘠之地南部，洛克·奥克班恩的颅骨标志着一位令人畏惧的钢鬃首领的覆灭。洛克·奥克班恩率领野猪人猛烈袭击部落的补给路线，而这颗颅骨正是他被斩下的头颅。",h="在贫瘠之地南部，洛克·奥克班恩的颅骨标志着一位令人畏惧的钢鬃首领的覆灭。洛克·奥克班恩率领野猪人猛烈袭击部落的补给路线，而这颗颅骨正是他被斩下的头颅。",kw={"内部的背叛","陶拉祖营地","十字路口","洛克·奥克班恩","洛克·奥克班恩的颅骨","碎牙","钢鬃","索克"},ang={["faction:Horde"]="身为部落的一员，取下洛克·奥克班恩的颅骨，就能瓦解南方野猪人的首领集团，阻止他们继续骚扰往来于陶拉祖营地与十字路口之间的补给商队。",["race:Orc"]="身为兽人，展示一名叫作“奥克班恩”的野猪人酋长被斩下的头颅，能让保卫贫瘠之地的人们深感快慰，也让他们更加安全。"},sec={{t="酋长的覆灭",b="洛克·奥克班恩率领钢鬃在贫瘠之地南部大举袭击部落的补给线。他与副官纳克和卡兹一同走出剃刀沼泽。洛克背叛了碎牙，将他抛下，任其被囚禁在陶拉祖营地，此后便因残酷的袭击而为兽人守军所知，守军也难以遏制他的攻势。碎牙指引部落勇士前往洛克的营地，取下洛克·奥克班恩的颅骨，为被囚禁的碎牙复仇，并打击指挥钢鬃攻势的首领。"},{t="呈交十字路口的凭证",b="碎牙要求取来三名同谋的颅骨，以报仇雪恨，随后将洛克·奥克班恩的颅骨送往北方，交给十字路口的索克。索克和部落指挥官原本怀疑是另一名野猪人率领了这些袭击。洛克·奥克班恩的颅骨带来了令人不寒而栗的意外，也证明威胁贫瘠之地中部贸易路线的敌人已被铲除。"}},faq={{q="洛克·奥克班恩是谁？",a="洛克·奥克班恩是一名强大的钢鬃战士，他走出剃刀沼泽，率领野猪人劫掠队横行于贫瘠之地南部。他憎恨兽人，与信任的盟友纳克和卡兹一同猛烈袭击部落的商队和哨所。",al={"洛克是谁","洛克·奥克班恩的故事","洛克·奥克班恩是谁"}},{q="碎牙为什么想要洛克·奥克班恩的颅骨？",a="洛克·奥克班恩和同伴背叛了碎牙，将他抛下，任由陶拉祖营地的牛头人将他抓获并关进牢笼。碎牙确信自己死期将近，一心向抛弃他的人复仇，便指引部落冒险者杀死他昔日的同伴。",al={"碎牙为何想要颅骨","碎牙的复仇","为何杀死洛克"}},{q="为什么要将颅骨送到十字路口交给索克？",a="索克负责十字路口的防务，致力于保护部落的补给路线免遭野猪人袭击。洛克·奥克班恩的颅骨向这位兽人指挥官证明，率领南方袭击的首领已经被杀，这片地区的旅人也因此得以平安通行。",al={"为何将颅骨交给索克","索克 洛克·奥克班恩的颅骨","洛克·奥克班恩的颅骨交给谁"}},{q="纳克和卡兹是谁？",a="纳克和卡兹与洛克·奥克班恩一同在贫瘠之地南部率领劫掠。碎牙说，他们一个是施法者，另一个是追踪者，在袭击部落时辅佐身为战士的洛克。",al={"纳克和卡兹","洛克·奥克班恩的副官","卡兹和纳克"}}},fp="11,183,18.461.0,24.319.1,20.250.0,38.265.0,52.240.0,21.196.0"}
P.entries["item:lonebrow-s-journal"] = {n="亨里格·独眉的日记",s="亨里格·独眉的日记是一本饱经风霜的日记，发现时仍被矮人探险家亨里格·独眉的骸骨紧握着，地点就在升降梯底部。日记详细记述了独眉穿越贫瘠之地的最后一段悲惨旅程，并揭示了潜伏在剃刀沼泽中的危险。",h="亨里格·独眉的日记是一本饱经风霜的日记，发现时仍被矮人探险家亨里格·独眉的骸骨紧握着，地点就在升降梯底部。日记详细记述了独眉穿越贫瘠之地的最后一段悲惨旅程，并揭示了潜伏在剃刀沼泽中的危险。",kw={"卡尔加·刺肋","法芬德尔","升降梯","亨里格·独眉","剃刀沼泽","萨兰纳尔","千针石林"},ang={["faction:Alliance"]="亨里格·独眉最后留下的文字，在联盟斥候与守卫菲拉斯边境的德鲁伊之间建立了至关重要的联系，召集援手对抗野猪人的威胁。",["race:Dwarf"]="在如此偏远而危机四伏的土地上发现一位逝去的同胞，令人沉重地想起矮人探险家远离卡兹莫丹进行勘察时所面对的凶险。"},sec={{t="升降梯下的遗愿",b="亨里格·独眉在连接贫瘠之地与千针石林的升降梯底部附近不幸身亡。他的骸骨被遗弃在一处岩石平台上，仍紧握着这本饱经风霜的日记。这本日记见证了他最后的旅程，并嘱托发现它的人前往通向菲拉斯的边境哨站萨兰纳尔，向那里的暗夜精灵德鲁伊法芬德尔报信。独眉的笔记提供了重要线索，揭示了南贫瘠之地正在酝酿的野猪人威胁。"},{t="与剃刀的关联",b="独眉的记录送到法芬德尔手中后，证实了联盟对剃刀沼泽野猪人日益加深的忧虑。日记的内容直接促成了对英雄们的召集，号召他们深入荆棘巢穴的腹地，击败策动野猪人威胁的卡尔加·刺肋，也就是卡尔加·刺肋。"}},faq={{q="亨里格·独眉是谁？",a="亨里格·独眉是一名矮人旅行者，在千针石林的升降梯脚下丧生。他死时仍将日记紧握在手中，希望其中的内容能传到驻守萨兰纳尔的暗夜精灵手中。",al={"亨里格·独眉","独眉是谁","升降梯死去的矮人"}},{q="日记在哪里？",a="日记就在亨里格·独眉的骸骨旁，位于千针石林北部升降梯底部坡道旁的一处低矮岩石平台上。",al={"亨里格·独眉的日记在哪","寻找亨里格·独眉的日记","升降梯旁的骸骨"}},{q="亨里格·独眉的日记该交给谁？",a="应带着日记向西穿过千针石林，交给驻守在菲拉斯边境萨兰纳尔的暗夜精灵德鲁伊法芬德尔。",al={"日记交给谁","法芬德尔","日记在哪交"}},{q="日记会引出什么任务？",a="阅读日记并向法芬德尔报告后，便能获知野猪人的情报，随后接到深入剃刀沼泽、击败老妪卡尔加·刺肋的任务。",al={"卡尔加·刺肋任务","亨里格·独眉的日记后续"}}},fx={a9190e03={q="亨里格·独眉的日记是什么？",a="亨里格·独眉的日记是一册饱经风霜的私人日志，发现时正握在矮人亨里格·独眉的骷髅手中。它在千针石林升降梯脚下被发现，记录了他在峡谷中丧命前的旅途与遗愿。",al={"亨里格·独眉的日记是什么","这本书是什么","亨里格·独眉的日记"}},["090ee1d4"]={q="亨里格·独眉的日记来自哪里？是谁写的？",a="这本日记由矮人旅行者亨里格·独眉写成，他曾穿行于千针石林危机四伏的峡谷之中。他一直随身携带日记，直到在升降梯附近丧命；后来，人们在那里发现了他的遗骸和这本日记。",al={"谁写了亨里格·独眉的日记","亨里格·独眉日记的作者","这本日记来自哪里"}},ea8f453f={q="为什么有人想要亨里格·独眉的日记？",a="送交日记是为了完成这位已故矮人的遗愿。驻扎在菲拉斯边境萨兰纳尔的暗夜精灵德鲁伊法芬德尔，想要阅读日记内容，了解亨里格的遭遇，并查明剃刀沼泽中正在酝酿的危险。",al={"为什么要送交亨里格·独眉的日记","谁需要亨里格·独眉的日记","为什么想要亨里格·独眉的日记"}}},fp="18,144,30.432.0,20.245.1,24.192.0,27.150.0,38.134.0,30.133.1"}
P.entries["item:lorgalis-manuscript"] = {n="洛迦里斯手稿",s="洛迦里斯手稿藏在灰谷地下、黑暗深渊沉没的废墟之中。这部古籍记述了上古之神，研习黑暗的学者觊觎其中有关沉睡力量的文字。",h="洛迦里斯手稿藏在灰谷地下、黑暗深渊沉没的废墟之中。这部古籍记述了上古之神，研习黑暗的学者觊觎其中有关沉睡力量的文字。",kw={"黑暗深渊","荒弃的洞穴","葛利·硬骨","铁炉堡","洛迦里斯","手稿","上古之神","沉睡之人"},ang={["class:Warlock"]="身为术士，这部手稿让你得以一窥有关上古之神和深渊存在的禁忌知识，这些知识正是修习黑暗法术之人所渴求的。",["race:NightElf"]="身为暗夜精灵，你在族人曾经生活过的沉没废墟中找到了这部古籍。书中对阿库麦尔和上古之神的崇敬，揭示了扎根于那些陷落殿堂中的黑暗信仰。"},sec={{t="沉睡者之书",b="洛迦里斯手稿位于黑暗深渊底部，早已死去的精灵曾在这里生活，直到他们的城市陷落。洛迦里斯记述了上古之神，他们曾在艾泽拉斯初生之时肆虐，如今则被锁链束缚，陷入沉睡。书中颂扬了阿库麦尔，这位上古之神的仆从栖居于黑暗深渊。据说，其中的知识能开启神秘的门户，惊动沉睡在世界深处的古老存在。手稿存放在被水淹没的廊道间一只锈蚀斑驳的铁箱里，引来了邪教徒和暗影学者的关注。"},{t="暗影中的目光",b="在铁炉堡的荒弃的洞穴，古怪的收藏家葛利·硬骨雇用冒险者渡海取回这部古籍。硬骨怀着敬畏谈论末日，以及沉睡神祇的苏醒。他打算让人抄录手稿，在他那隐秘团体的兄弟姐妹之间传阅，散播地表居民本不该知晓的禁忌知识。"}},faq={{q="洛迦里斯手稿是什么？",a="洛迦里斯手稿是洛迦里斯撰写的一部关于上古之神的古籍。据说，书中揭示了开启门户、唤醒沉睡的远古存在的方法。",al={"洛迦里斯手稿是什么","洛迦里斯书籍背景","手稿有什么作用"}},{q="手稿在哪里？",a="手稿存放在黑暗深渊深处一只锈蚀斑驳的铁箱里，那是一座位于灰谷佐拉姆海岸的暗夜精灵神殿废墟。",al={"哪里能找到洛迦里斯手稿","手稿位置","黑暗深渊箱子"}},{q="谁想得到手稿？",a="在铁炉堡荒弃的洞穴活动的葛利·硬骨想要找回手稿。他计划抄录手稿，将其中的学说分享给那些行事隐秘的同道。",al={"谁想要洛迦里斯手稿","葛利·硬骨任务","硬骨是谁"}},{q="葛利·硬骨为什么谈论末日？",a="硬骨敬奉并研究上古之神。他寻找记载如何唤醒沉睡之人的精灵古籍，相信他们的苏醒预示着末日将至。",al={"葛利末日","硬骨邪教徒","硬骨 上古之神"}}},fx={["61ae2bf7"]={q="洛迦里斯手稿来自哪里？是谁写的？",a="这份手稿由一位名叫洛迦里斯的人写成，藏在黑暗深渊底部的沉没废墟中。那座城市陷落之前，早已逝去的精灵曾在那里居住。关于洛迦里斯的身份，并无记载。手稿记述了上古之神和沉睡者的禁忌秘闻，并赞颂了居住在深渊中的上古之神仆从阿库麦尔。它被锁在洪水淹没的大厅里一只布满凹坑的铁箱中。",al={"洛迦里斯手稿的来源","谁写了洛迦里斯手稿","洛迦里斯手稿写于何处"}}},fp="19,187,25.525.0,19.394.1,32.172.0,32.139.0,25.164.0,49.155.0"}
P.entries["item:lunar-fungus"] = {n="月亮菇",s="月亮菇生长在黑海岸的洞穴中，德鲁伊会采集它来疗伤。将它与地根草和水混合，便能制成治疗病鹿的药膏。",h="月亮菇生长在黑海岸的洞穴中，德鲁伊会采集它来疗伤。将它与地根草和水混合，便能制成治疗病鹿的药膏。",kw={"奥兰达利亚·夜歌","奥伯丁","解毒","黑海岸","地根草","月光蘑菇","月亮菇"},ang={["class:Druid"]="身为年轻的德鲁伊，你在黑海岸的洞穴中寻找月亮菇，作为早期学习治疗魔法和救治中毒野生动物的训练内容。",["race:NightElf"]="身为暗夜精灵，你使用月亮菇等当地药材，帮助照料奥伯丁周围受到腐化的林地生物。"},sec={{t="特性与生态",b="月亮菇生长于黑海岸地下洞穴中的月光蘑菇。塞纳里奥议会看重它增强药效的作用。将它与舒缓的清水和常见的地根草混合，便能增强药膏的效力，抵御使身体衰弱的病症。它生长的潮湿洞穴中也常有领地意识很强的枭兽出没，因此采集时必须小心行进。"},{t="疗愈之道",b="在奥伯丁，奥兰达利亚·夜歌让年轻的德鲁伊采集月亮菇，以此学习自然的疗愈之道。他们会观察这类真菌等实物药材如何化解当地鹿群体内的毒素。通过学习草药疗法的原理，学徒们为日后借助变形和精神力量引导自然的解毒之力做好准备。"}},faq={{q="月亮菇有什么用途？",a="月亮菇能增强恢复药膏的疗效。奥兰达利亚·夜歌将它与地根草和清水混合，用来治疗黑海岸的病鹿。",al={"月亮菇用途","月亮菇有什么作用","为什么采集月亮菇"}},{q="月亮菇生长在哪里？",a="月亮菇生长于黑海岸奥伯丁以东洞穴中的月光蘑菇。脾气暴躁的枭兽也栖息在这些洞穴中，会抵御闯入者，保卫自己的领地。",al={"月亮菇位置","哪里能找到月亮菇","月亮菇花簇"}},{q="奥伯丁有谁需要这种真菌？",a="奥兰达利亚·夜歌要求研习自然之道的学徒采集月亮菇，作为训练的一部分。这种真菌用于制作药物，治疗患病的森林动物。",al={"谁需要月亮菇","奥伯丁草药任务"}},{q="为什么德鲁伊学徒必须采集实物草药来解毒？",a="了解实物解毒剂的作用原理，是德鲁伊教育的基础。采集月亮菇等材料并观察药材如何化解毒素，能让学徒在学习通过精神魔法驱毒之前，掌握治疗的原理。",al={"德鲁伊为什么采集草药","德鲁伊解毒训练"}}},fp="12,136,22.338.0,19.318.0,30.136.0,29.166.0,38.154.0,68.254.0"}
P.entries["item:lurker-venom"] = {n="潜伏者的毒液",s="在洛克莫丹，矮人守卫需要潜伏者的毒液来应对黑铁的破坏。岩石遍布的山丘和林地中，捕食猎物的蜘蛛提供了这种毒素。",h="在洛克莫丹，矮人守卫需要潜伏者的毒液来应对黑铁的破坏。岩石遍布的山丘和林地中，捕食猎物的蜘蛛提供了这种毒素。",kw={"首席工程师辛德维尔七世","悬崖潜伏者","洛克莫丹","潜伏者的毒液","纺织者杉达","蜘蛛毒液","巨石水坝","树林潜伏者"},ang={["profession:Engineering"]="利用有机毒素使敌方炸药失效，展现了矮人工程师在战斗中灵活运用活性材料的本领。",["race:Dwarf"]="身为矮人，你知道洛克莫丹的巡山人和守卫会利用当地荒野中的危险之物，保护卡兹莫丹的重要工程免遭黑铁氏族破坏。"},sec={{t="不稳定的试剂",b="潜伏者的毒液能帮助矮人拆除黑铁安放的炸药。爆破专家阿什兰·暗石指出，首席工程师辛德维尔七世配制的混合剂需要以蜘蛛毒液为原料。这种溶剂将毒液、稀有矿物和洛克湖中鳄鱼的眼泪混合在一起。它们共同形成一种活性化合物，能够解除构造复杂的爆炸装置。\n\n潜伏者蜘蛛种类繁多，从常见的wood lurkers到族母珊达 the Spinner都有。它们的毒牙威胁着穿行于洛克莫丹山丘与峭壁之间的旅人和巡山人。"}},faq={{q="潜伏者的毒液从何而来？",a="洛克莫丹的潜伏者蜘蛛提供这种毒液。它们包括悬崖潜伏者、森林潜伏者、树林潜伏者，以及它们的族母纺织者杉达。",al={"如何获取潜伏者的毒液","谁掉落潜伏者的毒液","哪里能找到潜伏者的毒液"}},{q="潜伏者的毒液有什么用途？",a="首席工程师辛德维尔七世将这种毒液用于化学混合剂，以中和并拆除黑铁渗透者在巨石水坝周围安放的炸药。",al={"为什么需要潜伏者的毒液","潜伏者的毒液用途","辛德维尔七世用毒液做什么"}},{q="为什么用毒液拆除爆炸装置？",a="矮人工程师使用具有反应活性、酸性或腐蚀性的混合剂，溶解精密的机械部件，或在不引爆的情况下中和不稳定的爆破火药。",al={"为什么用蜘蛛毒液拆炸弹","毒液如何使黑铁炸弹失效"}},{q="纺织者杉达是唯一的来源吗？",a="纺织者杉达身上带有这种毒液，但洛克莫丹林地和岩石峭壁间常见的野生潜伏者蜘蛛也能提供。",al={"是否必须杀死珊达","珊达 潜伏者的毒液"}}},fx={["0e11e6d3"]={q="潜伏者的毒液是什么？",a="潜伏者的毒液是一种强效天然毒素，采集自洛克莫丹崎岖荒野中的掠食性潜伏者蜘蛛。它虽然对猎物十分致命，但独特的化学性质使其受到专业工匠和工程师的重视。首席工程师辛德维尔七世专门将这种不稳定的液体用作炼金中和溶剂的关键试剂，以安全地拆除黑铁矮人的爆炸物。",al={"潜伏者的毒液是什么","潜伏者的毒液背景","潜伏者的毒液是什么物品"}}},fp="12,147,18.533.0,34.147.0,30.160.0,37.163.0,38.133.0"}
P.entries["item:lydon-s-toxin"] = {n="林度恩的毒药",s="在塔伦米尔，药剂师林度恩制成了一种毒药，用来扰乱荆棘谷地精在石爪山脉的伐木活动。部落冒险者将它送往雷霆崖，交给药剂师扎玛，由她设法将毒药散布开来。",h="在塔伦米尔，药剂师林度恩制成了一种毒药，用来扰乱荆棘谷地精在石爪山脉的伐木活动。部落冒险者将它送往雷霆崖，交给药剂师扎玛，由她设法将毒药散布开来。",kw={"药剂师林度恩","药剂师扎玛","林度恩的毒药","皇家药剂师学会","雷霆崖","剧毒粮草","荆棘谷地精"},ang={["race:Tauren"]="Tauren 欢迎有人协助制止荆棘谷地精破坏自然，但皇家药剂师学会的化学手段也考验着他们的萨满信念。",["race:Undead"]="林度恩的毒药的运送，展现了皇家药剂师学会联络网络的广度。该组织协调洛丹伦与卡利姆多之间的实地研究，向盟友证明被遗忘者的用处。"},sec={{t="皇家药剂师的方案",b="药剂师林度恩在希尔斯布莱德丘陵制成了这种毒药，用来对付破坏石爪山脉的荆棘谷地精伐木工。他说，这种化合物一经接触便可致命，还可能从一个目标传播到另一个目标。在用它对付狂风峭壁附近的地精之前，必须先将这份混合物跨越大陆送往雷霆崖。药剂师扎玛是皇家药剂师学会驻当地的代表，她需要用未经加工的毒药研制一种名为剧毒粮草的大范围散布装置。"}},faq={{q="林度恩的毒药有什么用途？",a="药剂师林度恩制成这种毒药，是为了扰乱荆棘谷地精在狂风峭壁一带的活动。它一经接触便可致命，还可能在地精劳工之间传播。",al={"林度恩 毒药用途","毒药有什么作用","为什么制造林度恩的毒药"}},{q="药剂师林度恩是谁？",a="药剂师林度恩是皇家药剂师学会的成员，驻扎在希尔斯布莱德丘陵的塔伦米尔。他制造剧毒药剂和实验性化合物，为被遗忘者的目标效力。",al={"林度恩 是谁","药剂师林度恩","林度恩 毒药制作者"}},{q="为什么要把毒药送到雷霆崖？",a="雷霆崖的药剂师扎玛需要这种毒药，因为目前还没有切实可行的方法将它大范围散布。她研究当地植物，协调皇家药剂师学会在卡利姆多的行动，并将这份混合物改制成便携式喷雾装置。",al={"为什么去雷霆崖","为什么把毒药交给 扎玛","药剂师扎玛 的目的"}},{q="扎玛收到毒药后会做什么？",a="药剂师扎玛将毒药制成一种名为剧毒粮草的加压气雾装置。行动人员可以用它将毒药散布到荆棘谷地精的营地中。",al={"剧毒粮草的制造","扎玛 如何使用毒药"}}},fp="13,212,27.420.0,31.148.0,24.179.0,47.216.0,44.177.0"}
P.entries["item:macgrann-s-dried-meats"] = {n="马克格拉恩的干肉",s="在丹莫罗，冰须搬走了图德拉·马克格拉恩储备的过冬肉食。",h="在丹莫罗，冰须搬走了图德拉·马克格拉恩储备的过冬肉食。",kw={"寒风峡谷","丹莫罗","马克格拉恩的干肉","储肉柜","冰须","图德拉·马克格拉恩"},ang={["profession:Cooking"]="身为厨师，你可以用盐腌制野味，让肉食在丹莫罗的严寒中得以保存。像 MacGrann 这样的猎人就靠这种方法储存过冬的食物。",["race:Dwarf"]="身为矮人，你知道在高山上，做好准备才能生存。失去过冬的储粮，可能就意味着生与死的差别。"},sec={{t="过冬的储粮",b="图德拉·马克格拉恩猎取野味，用盐腌制，留待过冬。他将足够吃上数周的食物装进一个结实的箱子，放在瑟银储肉柜里，免得四处觅食的熊和徘徊的猛兽靠近他的家园。然而，他从未料到，竟有入侵者力气大到能搬走整只箱子。"},{t="深入雪人巢穴",b="趁这位矮人外出追踪鹿群时，冰须洗劫了 马克格拉恩 的营地。这个雪人把沉重的箱子拖进了寒风峡谷的巢穴。箱子坚固的瑟银护板依然完好，但 马克格拉恩 的腿受了伤，无法迅速进洞取回储粮。如果没人帮他在冬天到来之前找回储粮，这位受困的猎人就将面临在雪山中饿死的命运。"}},faq={{q="马克格拉恩的干肉是什么？",a="图德拉·马克格拉恩用盐腌制并保存了一个月的食物，供自己在丹莫罗过冬。",al={"马克格拉恩的干肉是什么","图德拉 的肉","马克格拉恩 的肉食储备"}},{q="为什么要把肉锁在箱子里？",a="丹莫罗饥饿的猛兽，包括山中的熊，可能会撕咬这些干肉。马克格拉恩 把过冬的食物锁进加固的瑟银储肉柜，防止它们偷吃。",al={"为什么把肉锁起来","为什么用瑟银储肉柜","马克格拉恩 的箱子"}},{q="谁偷走了储肉柜？",a="冰须趁 马克格拉恩 外出猎鹿时偷走了整个储肉柜，然后把它拖进了寒风峡谷的巢穴。",al={"谁拿走了肉","谁偷走了它","偷储肉柜的贼"}},{q="为什么图德拉·马克格拉恩不能自己取回肉食？",a="他的腿受了伤，无法亲自进入冰须的洞穴，把箱子搬出来。",al={"马克格拉恩 为什么不自己取回","图德拉 为什么需要帮助","图德拉 受伤"}}},fx={["1f8f3b04"]={q="马克格拉恩的干肉从哪里来，是谁制作的？",a="这些干肉由图德拉·马克格拉恩制作并腌渍，他是一名住在丹莫罗寒冷荒野中的登山者。他腌制了足足一个月的口粮，以熬过即将到来的严寒季节，并将它们小心地存放在一只沉重的瑟银储物箱中，随后当地的野兽冰须却横插一脚。",al={"马克格拉恩的干肉是谁制作的","干肉从哪里来","马克格拉恩的干肉来源"}},["6a0307bf"]={q="为什么图德拉·马克格拉恩想要拿回干肉？",a="如果失去这批储存的食物，当猛烈的风雪席卷丹莫罗时，图德拉·马克格拉恩就会面临饥饿。那是足足一个月的腌制口粮。他的腿伤使他无法冒险进入冰须的巢穴取回食物，因此找回这些干肉，是他熬过即将到来的寒冬的关键。",al={"为什么图德拉·马克格拉恩想要干肉","为什么要取回干肉","为什么需要马克格拉恩的干肉"}}},fp="22,76,14.284.0,20.360.0,32.102.0,37.177.0,26.124.0,53.94.0"}
P.entries["item:mackreel-s-moonshine"] = {n="马克里尔的月光酒",s="在断裂的萨多尔大桥上，醉鬼马克里尔酿出的月光酒烈得足以放倒一名哨兵。南海镇的布鲁米·比格尔收下一批酒，抵清醉鬼马克里尔的欠账。",h="在断裂的萨多尔大桥上，醉鬼马克里尔酿出的月光酒烈得足以放倒一名哨兵。南海镇的布鲁米·比格尔收下一批酒，抵清醉鬼马克里尔的欠账。",kw={"布鲁米·比格尔","矮人酿酒","醉鬼马克里尔","马克里尔的月光酒","月光酒","南海镇","湿地"},ang={["profession:Cooking"]="身为厨师，你知道，像醉鬼马克里尔酿的粗烈月光酒这样的地方烈酒，是边地各处酒馆的常见贸易货物。",["race:Dwarf"]="身为矮人，好烈酒只要一闻，你就能辨认出来。醉鬼马克里尔的月光酒劲道十足，足以把一名巡山人放倒。"},sec={{t="烈性佳酿",b="醉鬼马克里尔在萨多尔大桥担任守卫时酿造月光酒。这种酒以烈性闻名，连久经考验的矮人哨兵也会在痛饮一夜后醉倒。他们醒来时头痛欲裂，仿佛有攻城器械从头顶碾过。旅人看重它带来的暖意，借此抵御洛丹伦和卡兹莫丹的湿冷。"},{t="送往南海镇的抵账酒",b="醉鬼马克里尔欠南海镇的旅店老板兼酿酒大师布鲁米·比格尔一笔尚未还清的债。他送去一批月光酒代替钱币，抵清自己的酒账。布鲁米·比格尔接受用酒抵金，并将马克里尔酿的烈酒添入存货，以备希尔斯布莱德丘陵沿海的寒冷时日。"}},faq={{q="马克里尔的月光酒是谁酿的？",a="醉鬼马克里尔是一名驻守在湿地与阿拉希高地之间那座断裂的萨多尔大桥上的矮人哨兵，这种月光酒就是他蒸馏酿制的。",al={"马克里尔的月光酒酿造者","谁酿的","醉鬼马克里尔的烈酒"}},{q="为什么要把这种月光酒送往南海镇？",a="醉鬼马克里尔欠南海镇的布鲁米·比格尔一笔债。他答应用一批新酿的月光酒代替钱币，送给布鲁米·比格尔抵账。",al={"为何送往南海镇","月光酒运送","布鲁米·比格尔的债务"}},{q="马克里尔的月光酒有多烈？",a="马克里尔的月光酒烈性非凡。醉鬼马克里尔承认，他喝了这种酒后在值勤时醉倒，醒来时头痛得仿佛有攻城器械从头骨上隆隆碾过。",al={"有多烈","月光酒烈度","马克里尔的月光酒的效果"}},{q="为什么必须抓紧时间送酒？",a="醉鬼马克里尔喝得酩酊大醉，整个值勤期间都在酣睡。他醒来时，距离与布鲁米·比格尔约定的还债期限只剩几分钟了。",al={"为何限时","任务是否限时","为何赶时间"}}},fx={abca7076={q="马克里尔的月光酒是什么？",a="马克里尔的月光酒是醉鬼马克里尔在湿地酿造的一种烈性手工酒。它以酒劲惊人而臭名昭著，甚至能让强壮的矮人宿醉不已，仿佛一队攻城器械从他脑袋上碾过。除了酒劲十足，它还是颇受欢迎的交易品，远至希尔斯布莱德丘陵的人们也会在寒冷的日子里买来暖身。",al={"马克里尔的月光酒是什么","马克里尔的月光酒","醉鬼马克里尔酿的酒"}}},fp="20,161,13.281.0,21.302.0,31.138.0,47.148.0,35.182.0,40.134.0"}
P.entries["item:maggot-eye-s-paw"] = {n="蛆眼的爪子",s="在加伦鬼屋，蛆眼的爪子证明了那名豺狼人酋长已死。这只爪子被带往布瑞尔，作为他因替天灾军团盗取尸体而被处决的证据。",h="在加伦鬼屋，蛆眼的爪子证明了那名豺狼人酋长已死。这只爪子被带往布瑞尔，作为他因替天灾军团盗取尸体而被处决的证据。",kw={"悬赏","布瑞尔","执行官塞加德","加伦鬼屋","豺狼人","蛆眼","蛆眼的爪子","提瑞斯法林地"},ang={["race:Undead"]="身为布瑞尔的被遗忘者，带回蛆眼的爪子，就是打击那些为可恨的巫妖王提供尸体的盗尸贼。"},sec={{t="处决的证据",b="蛆眼挖掘坟墓，劫掠加伦鬼屋附近的乡野，为巫妖王的军队提供尸体。被遗忘者在布瑞尔公布了对他的死刑判决和悬赏。要领取赏金、了结此事，猎手们必须将这名豺狼人被砍下的爪子带回镇上。执行官塞加德只认这份证据，不接受关于蛆眼已死的传言。"}},faq={{q="执行官塞加德为什么要蛆眼的爪子？",a="执行官塞加德要蛆眼的爪子，是为了证明这名被判处死刑的豺狼人已被杀死。确认处决后，布瑞尔才会支付赏金。",al={"为什么要爪子","蛆眼悬赏证据","塞加德爪子"}},{q="蛆眼对被遗忘者犯下了什么罪行？",a="蛆眼率众袭击了提瑞斯法林地北部各处，并从加伦鬼屋等农庄盗走埋葬的尸体。他将这些尸体提供给巫妖王的军队。",al={"蛆眼罪行","蛆眼为何被通缉","蛆眼做了什么"}},{q="蛆眼在哪里？",a="蛆眼位于加伦鬼屋，那是提瑞斯法林地中布瑞尔以北的一座荒废农庄。他通常潜伏在破败的农舍里。",al={"蛆眼位置","哪里能找到蛆眼","加伦鬼屋豺狼人"}},{q="豺狼人为什么与巫妖王的部队合作？",a="在提瑞斯法林地，一些四处劫掠的豺狼人团伙与天灾军团结盟，或受其控制。他们盗掘人类和被遗忘者的坟墓，将尸体送给亡灵法师。",al={"豺狼人与天灾军团","豺狼人为何盗取尸体","天灾军团豺狼人"}}},fp="16,148,18.356.0,47.139.0,55.167.0,26.138.0,51.166.0"}
P.entries["item:maggran-s-reserve-letter"] = {n="马格兰的信件",s="马格兰在烈日石居发出命令，安排人手接替升降梯的一名守卫。信中准许瑞什·远行者休假，回家探望家人。",h="马格兰在烈日石居发出命令，安排人手接替升降梯的一名守卫。信中准许瑞什·远行者休假，回家探望家人。",kw={"贫瘠之地","缚地者","格瑞什","信件","升降梯","长跑者","玛格兰","预备兵","石爪山"},ang={["faction:Horde"]="身为部落的一员，你能看到部落如何向遍布卡利姆多的偏远哨站派遣新的预备兵力，照顾分散各地的部队。"},sec={{t="哨兵换岗",b="马格兰从烈日石居向升降梯发出命令。驻守那里的部落哨兵瑞什·远行者将由一名战士接替。升降梯的木制绞盘远在南方，瑞什·远行者一直在那里守望。新来的战士接替他之后，他便能离开岗位，回家探望家人。"}},faq={{q="马格兰的信件有什么用途？",a="马格兰的命令安排人手接替瑞什·远行者在贫瘠之地南部升降梯的岗位，让他能够回家探望家人。",al={"这封信有什么用","马格兰信件用途","为什么要送信"}},{q="这封信是谁写的？",a="这封信是马格兰写的。他是石爪山脉烈日石居的一位长者。",al={"谁写的","预备兵信件作者","马格兰"}},{q="这封信是写给谁的？",a="这封信是写给瑞什·远行者的，他是驻守升降梯顶端的一名部落守卫，升降梯连接着贫瘠之地南部与千针石林。",al={"信交给谁","收信人","送到哪里"}},{q="这封信要送到哪里？",a="带着这封信向南穿过贫瘠之地，前往千针石林峡谷的边缘，升降梯就在那里。",al={"送信地点","格里什在哪里","升降梯位置"}}},fx={["419ae143"]={q="马格兰的信件是什么？",a="这是一封由马格兰在石爪山脉的烈日石居亲笔写下的正式公文。信中告知驻守的部落卫兵瑞什·远行者，一名预备队战士即将前来接替他的岗位，让他得以休假探望家人。",al={"马格兰的信件是什么","马格兰的信件","预备队信件"}},eb8a36e5={q="瑞什·远行者为什么想要马格兰的信件？",a="瑞什早就请求有人接替他的岗位，因此一直盼着收到消息。在南贫瘠之地看守升降梯是一项单调的差事，而这封信正式批准由一名预备队战士接替他，终于让他得以盼来已久地休假探亲。",al={"瑞什为什么想要这封信","为什么需要这封预备队信件","为什么需要马格兰的信件"}}},fp="24,172,17.346.0,48.187.0,21.101.0,27.158.0,30.114.0"}
P.entries["item:mangy-claw"] = {n="肮脏的爪子",s="在丹莫罗，肮脏的爪子标志着一场致命狩猎的终结。巨大的冰爪熊癞爪杀死了一名受困的矮人驾驶员，而这只被斩下的爪子证明，那头野兽已被杀死。",h="在丹莫罗，肮脏的爪子标志着一场致命狩猎的终结。巨大的冰爪熊癞爪杀死了一名受困的矮人驾驶员，而这只被斩下的爪子证明，那头野兽已被杀死。",kw={"丹莫罗","铁钻","冰爪熊","癞爪","肮脏的爪子","驾驶员塞克·锤足","攻城坦克旅"},ang={["class:Hunter"]="作为猎人，在丹莫罗山间肆虐的暴风雪中追踪癞爪，将考验你应对危险且领地意识强烈的野兽的本领。",["race:Dwarf"]="作为矮人，完成阵亡战友的临终遗愿，为铁炉堡攻城坦克旅的一员复仇，关乎你个人与氏族的深厚荣誉。"},sec={{t="垂死驾驶员的遗愿",b="驾驶员铁钻的蒸汽坦克在丹莫罗冰封的群山中出了故障。他徒步寻找矿石，独自面对山间的荒野。他在日记中写道，自己击退了冰爪熊癞爪，却也被它抓咬得身受重伤。那头熊随后折返，杀死了虚弱的驾驶员。铁钻在最后一篇日记中恳求有人为他报仇。从倒下的熊身上取走肮脏的爪子，便能完成他的遗愿。"},{t="为攻城坦克旅复仇",b="驾驶员塞克·锤足派人深入积雪，盼望能找到仍然活着的朋友铁钻。铁钻的日记和肮脏的爪子表明，他已经遇难，而他的遗愿也已完成。将它们带给驾驶员塞克·锤足，能让铁炉堡攻城坦克旅得到慰藉，也能赢得铁炉堡驾驶员们的感激。"}},faq={{q="肮脏的爪子是什么？",a="肮脏的爪子是从癞爪身上斩下的爪子，癞爪是丹莫罗的一头凶猛冰爪熊。它证明这头野兽已被猎杀。",al={"肮脏的爪子用途","这只爪子是什么","癞爪物品"}},{q="谁需要肮脏的爪子？",a="驾驶员塞克·锤足需要肮脏的爪子，以及他已故朋友铁钻的日记。它们能证实那头杀人的熊已经死去。驾驶员塞克·锤足驻扎在丹莫罗的山口附近。",al={"谁收肮脏的爪子","肮脏的爪子交付","驾驶员塞克·锤足交付"}},{q="为什么要猎杀癞爪？",a="矮人驾驶员铁钻的蒸汽坦克出了故障，他便徒步寻找矿石，却遭到癞爪的抓咬，最终被它杀死。铁钻的日记记下了他的临终遗愿，希望有人能为他报仇。",al={"为什么杀癞爪","谁被癞爪杀死","铁钻背景故事"}},{q="野兽癞爪在哪里游荡？",a="癞爪在丹莫罗积雪覆盖的山脊和丘陵间徘徊，那里离驾驶员铁钻遗骸的发现地点不远。",al={"癞爪位置","癞爪在哪里","癞爪丹莫罗"}}},fx={["554d85fa"]={q="肮脏的爪子从哪里来？",a="肮脏的爪子直接取自癞爪，一头徘徊在丹莫罗冰封荒野中的凶猛冰爪熊。它并非人工制作的物品，而是在这头野兽被杀死后，从它身上割下的骇人战利品。",al={"肮脏的爪子来源","肮脏的爪子在哪里掉落","谁有肮脏的爪子"}}},fp="10,173,20.396.0,31.302.1,23.125.0,25.184.0,36.192.0,36.105.0"}
P.entries["item:marshal-haggard-s-badge"] = {n="治安官哈迦德的徽章",s="在艾尔文森林的群山中，治安官哈迦德已从暴风城退役，过着退休生活。蛀牙杰克骗走了他的旧徽章，迪菲亚可以用它冒充城里的官员。",h="在艾尔文森林的群山中，治安官哈迦德已从暴风城退役，过着退休生活。蛀牙杰克骗走了他的旧徽章，迪菲亚可以用它冒充城里的官员。",kw={"蛀牙杰克","迪菲亚","艾尔文森林","治安官杜汉","治安官哈迦德","治安官哈迦德的徽章","暴风城","保险箱"},ang={["class:Warrior"]="身为战士，找回哈迦德的徽章，就能向这位暴风城老兵证明你的勇气与实力。他会用自己征战时留下的、保养良好的备用武器，奖励有前途的战士。",["faction:Alliance"]="身为联盟的一员，取回徽章可以保护暴风城的军事指挥体系，并阻止迪菲亚潜行者从内部破坏当地防御。"},sec={{t="失窃的徽记",b="一天夜里，蛀牙杰克身穿暴风城战袍，来到哈迦德的农场。这名迪菲亚潜行者假扮成闪金镇驻军指挥官治安官杜汉，声称哈迦德从前的同僚需要这枚徽记来处理公务。\n\n年迈的治安官毫无疑心地交出了徽记。在哈迦德识破骗局之前，Jack 就逃进了树林。即使落入迪菲亚手中，这枚徽章仍代表着暴风城治安官的权威。歹徒可以用它通过关卡，或迷惑当地的巡逻队。"}},faq={{q="治安官哈迦德的徽章是什么？",a="治安官哈迦德在暴风城王国服役期间，佩戴这枚徽章以表明自己的军衔。虽然他已经退役，但这枚徽章仍具有真正的权威。",al={"哈迦德 徽章","治安官徽章","哈迦德 的徽章"}},{q="蛀牙杰克是如何拿到徽章的？",a="蛀牙杰克身穿暴风城战袍，趁夜来到治安官哈迦德的家中。哈迦德将他误认成了闪金镇的治安官杜汉，在 杰克 索要徽章时便交给了他。",al={"徽章如何被盗","谁偷走了徽章","蛀牙杰克 的骗局"}},{q="徽章落入迪菲亚手中为何会带来危险？",a="一名迪菲亚密探只要拿着真正的徽章，再加以伪装，就能冒充暴风城的高级官员。这名密探可以绕过哨兵、进入驻地，或向城镇卫兵下达假命令。",al={"杰克 为何想要徽章","迪菲亚 如何使用徽章","徽章的危险"}},{q="徽章存放在哪里？",a="蛀牙杰克将徽章锁在他营地里的保险箱中，营地位于艾尔文森林中治安官哈迦德的农场以南。",al={"徽章位置","哪里能找到徽章","死牙 保险箱"}}},fp="23,205,17.489.0,32.160.0,38.185.0,54.192.0,24.115.0"}
P.entries["item:mary-s-looking-glass"] = {n="玛丽的眼镜",s="在暮色森林，玛丽丢弃的镜子从一只食尸鬼手中辗转来到一位观星者手里。",h="在暮色森林，玛丽丢弃的镜子从一只食尸鬼手中辗转来到一位观星者手里。",kw={"盲眼玛丽","夜色镇","暮色森林","疯狂的食尸鬼","仰望星空","镜子","玛丽的眼镜","静谧花园墓场","维克托·安特拉斯"},ang={["faction:Alliance"]="从静谧花园墓场的恐怖生物手中找回遗物，能让夜色镇饱受困扰的居民稍感释怀，也能帮助镇上的各项工程。",["profession:Engineering"]="工程师会欣赏维克托的巧思：他将一面古老的家用镜子改作观星装置的光学反射镜。"},sec={{t="被遗弃的珍宝",b="盲眼玛丽曾十分珍爱这面光洁的镜子。死去并失去双眼后，镜中的倒影成了痛苦的提醒，让她想起自己失去的一切。她把镜子扔到谷仓后面，暮色森林的阴霾笼罩着那里。一只疯狂的食尸鬼在破败的郊野中找到了它，将它带往南边静谧花园墓场的墓穴。"},{t="仰望苍穹",b="在夜色镇，观星者维克托·安特拉斯梦想着看穿暮色森林永恒的暮色，望见上方澄澈的天空。他的望远镜需要特殊的光学镜片和反光玻璃。玛丽让冒险者前往墓场中破败的礼拜堂，追寻那里的狂暴亡灵，取回她的镜子。维克托需要用它作为观星装置中的反射镜。"}},faq={{q="玛丽为什么扔掉镜子？",a="这面镜子曾是玛丽最珍贵的宝物之一，但一件她未曾详述的事发生后，她把它扔到了谷仓后面。在另一次交谈中，她解释说，自己因无法忍受自己的容貌而挖出了双眼。",al={"玛丽为何扔掉镜子","为何丢弃镜子","盲眼玛丽镜子的故事"}},{q="玛丽丢弃镜子后，镜子最终落到了谁手里？",a="一只在玛丽旧农庄后方树林里游荡的疯狂的食尸鬼捡到了这面被丢弃的镜子。这个亡灵生物最终在静谧花园墓场废弃的礼拜堂里安了身。",al={"镜子在谁手里","谁掉落镜子","镜子在哪里"}},{q="维克托·安特拉斯为什么想要玛丽的眼镜？",a="维克托正在建造一架精密的望远镜，以看穿暮色森林的阴霾，研究群星。他需要一个优良的反射面，让光线在装置中传递，而玛丽的镜子正合他的设计。",al={"维克托为何需要镜子","维克托镜子的用途","望远镜反射镜"}},{q="在哪里能找到拿着镜子的疯狂的食尸鬼？",a="疯狂的食尸鬼潜伏在暮色森林最东南端，出没于静谧花园墓场中破败的石砌礼拜堂。",al={"疯狂的食尸鬼位置","疯狂的食尸鬼在哪里","静谧花园墓场食尸鬼"}}},fx={afb2ba8d={q="玛丽的眼镜是什么？",a="玛丽的眼镜是一面手持镜子，曾属于盲眼玛丽。玛丽视它为自己最珍贵的私人物品之一，后来在一场可怕的事故发生后，她把它扔在了谷仓后面。之后，这面镜子落入了一只在暮色森林游荡的亡灵食尸鬼手中。",al={"玛丽的眼镜是什么","玛丽的眼镜物品","盲眼玛丽的眼镜"}}},fp="20,79,19.356.0,19.366.0,42.247.0,53.196.0,56.195.0,55.124.0"}
P.entries["item:mathystra-relic"] = {n="黑暗深渊遗物",s="在黑海岸北部草木丛生的玛塞斯特拉废墟中，古老的暗夜精灵遗物仍残留着魔力。暮光之锤教派已经盯上了它们。",h="在黑海岸北部草木丛生的玛塞斯特拉废墟中，古老的暗夜精灵遗物仍残留着魔力。暮光之锤教派已经盯上了它们。",kw={"黑海岸","古树之林","主宰之剑","玛塞斯特拉","黑暗深渊遗物","安努","玛塞斯特拉废墟","暮光之锤"},ang={["class:Druid"]="身为德鲁伊，你与安努这样的古树携手，守护黑海岸的平衡，防止被遗忘的魔法助长黑暗召唤。",["race:NightElf"]="身为Kaldorei，找回这些遗物有助于防止危险的古老魔法落入暮光之锤之手，也是在缅怀一座毁于Sundering的城市。"},sec={{t="陷落堡垒的遗存",b="玛塞斯特拉曾是卡利姆多海岸上的一座城市，也是精灵文明的堡垒。在大灾变之前，这里曾是一处引以为傲的所在。如今，倒塌的石柱和开裂的石块半掩在灌木与海雾中，不安的幽魂和潜伏的野兽出没其间。那个时代的遗物散落在废墟各处。一万年的荒废让它们饱经磨损，但精灵奥术技艺的痕迹依然留存，落入粗心大意的人手中便会带来危险。"},{t="迫近的危机",b="安努是一位古老的知识古树，得知暮光之锤教派正试图将主宰之剑发现的失传精灵文献化为武器后，他开始寻求这些遗物。这个教派想要掌控古老的卡多雷魔法，加速其黑暗主人的归来。安努与黑海岸的守护者研究这些散落的遗物，试图查明教派的意图，防止玛塞斯特拉日渐消逝的力量被用于黑暗目的。"}},faq={{q="黑暗深渊遗物是什么？",a="黑暗深渊遗物是那座古老暗夜精灵城市留下的残片和器物。尽管数千年已经过去，它们仍保留着大分裂之前精灵魔法技艺的痕迹。",al={"黑暗深渊遗物是什么","玛塞斯特拉精灵遗物","这些遗物是什么"}},{q="这些遗物在哪里？",a="这些遗物散落在黑海岸北部的玛塞斯特拉废墟中，藏于碎石、倒塌的石柱和高草之间。",al={"黑暗深渊遗物位置","哪里能找到遗物","遗物位置"}},{q="谁想要黑暗深渊遗物？",a="安努是一位居住在黑海岸南部古树之林的知识古树，他请旅行者收集这些遗物以供研究。",al={"谁需要遗物","遗物交给谁","安努遗物"}},{q="暮光之锤为什么对它们感兴趣？",a="暮光之锤教派正在研究主宰之剑发现的古老精灵文献。它企图扭曲精灵的古老魔法，用来将其隐于暗影中的主人召唤到这个世界。",al={"暮光之锤为什么想要遗物","暮光之锤 玛塞斯特拉"}}},fp="15,130,28.460.0,15.426.1,30.195.0,29.128.0,31.132.0,48.180.0"}
P.entries["item:melenas-head"] = {n="迈雷纳斯的头颅",s="在地狱石，迈雷纳斯的头颅标志着盘踞泰达希尔已久的恶魔威胁终于终结。这颗头颅取自驻扎于此的萨特指挥官迈雷纳斯，作为悬赏的凭证，证明他已被杀死。",h="在地狱石，迈雷纳斯的头颅标志着盘踞泰达希尔已久的恶魔威胁终于终结。这颗头颅取自驻扎于此的萨特指挥官迈雷纳斯，作为悬赏的凭证，证明他已被杀死。",kw={"地狱石","劣魔","迈雷纳斯","迈雷纳斯的头颅","萨特","泰达希尔","扭曲的仇恨"},ang={["class:Warrior"]="身为战士，你知道，斩下敌方军阀的头颅，就是确凿的证据，证明这个危险的对手及其劣魔大军已被击溃。",["race:NightElf"]="身为暗夜精灵，你知道萨特是你古老族裔遭恶魔腐化后的悲惨产物。秘密处决迈雷纳斯既是必要之举，也令整个族群蒙羞。"},sec={{t="难以启齿的耻辱",b="萨特出现在泰达希尔这棵新生的世界之树上，令守卫幽影谷及周边地区的暗夜精灵蒙羞。迈雷纳斯在精灵聚居地北面的地狱石蜿蜒洞穴中筑巢，并将好斗的劣魔战士集结到麾下。面对如此接近腹地的腐化，卡多雷尤为重视谨慎行事。迈雷纳斯的头颅是一份不为外人所知的证据，证明他的阴谋已在其影响扩散之前终结。"}},faq={{q="迈雷纳斯是谁？",a="迈雷纳斯是一名萨特指挥官，潜藏在泰达希尔的地狱石中。他将劣魔战士召集到麾下，密谋对付附近的卡多雷哨站。",al={"迈雷纳斯背景故事","迈雷纳斯是谁","迈雷纳斯的故事"}},{q="为何必须对他的死保密？",a="萨特是遭受恶魔腐化而被诅咒、扭曲的古代暗夜精灵，他们出现在离泰达希尔神圣枝干如此之近的地方，令卡多雷当权者深感耻辱。迅速而秘密地除掉迈雷纳斯，能避免恐慌，也能减少羞辱。",al={"为何保密","扭曲的仇恨的秘密","为何秘密行事"}},{q="迈雷纳斯的头颅取自何处？",a="迈雷纳斯的头颅取自地狱石深处，那是一处遭到腐化的洞穴，位于泰达希尔中部、多兰纳尔以北。",al={"哪里能找到迈雷纳斯","地狱石位置","迈雷纳斯位置"}}},fp="13,141,20.426.0,21.159.0,32.242.0,35.110.0"}
P.entries["item:menethil-statuette"] = {n="米奈希尔雕像",s="在湿地近海，一场海难让米奈希尔雕像遗失于此。这尊罕见的银像纪念着洛丹伦逝去的国王。",h="在湿地近海，一场海难让米奈希尔雕像遗失于此。这尊罕见的银像纪念着洛丹伦逝去的国王。",kw={"盲眼公主","蓝腮","伯瓦尔·弗塔根","光明大教堂","格雷森·沙东布瑞克","米奈希尔雕像","泰瑞纳斯·米奈希尔","湿地"},ang={["class:Paladin"]="身为圣骑士，你看到的泰瑞纳斯国王是一位年轻的圣光勇士，正高举战锤。他的形象触动着那些为沦陷王国哀悼的神圣骑士。",["faction:Alliance"]="身为联盟的一员，你知道泰瑞纳斯是一位凝聚人心的领袖，缔造了Grand Alliance。在这个分崩离析的世界里，任何幸存的、纪念他的遗物，都是鼓舞人心的珍宝。"},sec={{t="洛丹伦的珍稀遗物",b="雕像呈现了泰瑞纳斯·米奈希尔二世国王年轻时的模样：一位长发圣骑士，向天空高举战锤。他为人谦逊，不喜为自己树碑立像，因此为纪念他而制作的雕像和画像寥寥无几。天灾军团攻陷洛丹伦时，几乎将它们全部摧毁。这尊幸存的雕像对联盟而言价值非凡。"},{t="遗失沼泽",b="盲眼公主号载着雕像，驶向联盟的米奈希尔港。蓝腮鱼人在沼泽海岸附近袭击了这艘商船，船上的货物散落各处。雕像被困在岸边一只半埋的木桶中。附近有龙喉氏族兽人和其他当地威胁，守卫们急忙将寻回的雕像南送至暴风城。在那里，伯瓦尔·弗塔根公爵将它托付给了光明大教堂。"}},faq={{q="雕像上的人物是谁？",a="雕像刻画的是泰瑞纳斯·米奈希尔二世国王，他曾是洛丹伦的统治者，也是最初联盟的缔造者。他以年轻圣骑士的形象出现，高举着一柄战锤。",al={"雕像上的人物是谁","雕像刻画了什么","米奈希尔雕像是谁"}},{q="雕像是如何遗失的？",a="商船盲眼公主号载着它横渡无尽之海。蓝腮鱼人在湿地袭击了这艘船，船上的货物被冲上岸，埋进了淤泥。",al={"如何遗失","谁遗失了雕像","海难 湿地 雕像"}},{q="为何泰瑞纳斯国王的雕像和画像如此罕见？",a="泰瑞纳斯国王不喜欢为自己歌功颂德的纪念物，因此他的雕像很少。天灾军团对洛丹伦的蹂躏，几乎摧毁了北方留存的所有画像与雕像。",al={"为何泰瑞纳斯的雕像很少","泰瑞纳斯纪念物"}},{q="雕像最终去了哪里？",a="雕像在湿地被寻回后，被送到了暴风要塞的伯瓦尔·弗塔根公爵手中。他感受到了这件遗物中的圣光，将它托付给了光明大教堂的格雷森·沙东布瑞克公爵。",al={"雕像送往何处","谁保管雕像","雕像 大教堂"}}},fx={["00c7d589"]={q="米奈希尔雕像是什么？",a="米奈希尔雕像是一尊银色小雕像，刻画的是年轻时的泰瑞纳斯·米奈希尔二世：他留着长发，举起战锤，身着圣骑士装束。除了精妙再现这位已故洛丹伦君王的形象，这件遗物似乎还凝聚着圣光，使它既是珍贵的历史纪念物，也是受祝福的圣物。",al={"米奈希尔雕像是什么","米奈希尔雕像","这尊小雕像是什么"}},["0d8a0354"]={q="为什么人们如此渴求米奈希尔雕像？",a="泰瑞纳斯国王厌恶个人纪念碑和纪念物，因此留存下来的肖像极少；其中几乎所有都在洛丹伦被天灾军团攻陷时遭到毁坏。它的稀有性、蕴含的圣光，以及它与联盟创始者之间深厚的情感联系，使其成为无可替代的传家宝。如果无人看守，像当地龙喉兽人这样的敌人定会乐于亵渎或掠走它。",al={"为什么人们想要米奈希尔雕像","为什么这尊小雕像很值钱","谁想要这尊小雕像"}}},fp="18,131,25.338.0,16.448.0,30.162.0,27.169.0,43.200.0,32.222.1"}
P.entries["item:merrin-s-letter"] = {n="麦琳的信件",s="麦琳·石纹从湿地的维尔加挖掘场发出了一封紧急信件。迅猛龙已经占领了挖掘场，但麦琳向亲人报了平安。",h="麦琳·石纹从湿地的维尔加挖掘场发出了一封紧急信件。迅猛龙已经占领了挖掘场，但麦琳向亲人报了平安。",kw={"探险者协会","麦琳·石纹","麦琳的信件","杂斑迅猛龙","塔雷尔·石纹","湿地","维尔加挖掘场"},ang={["faction:Alliance"]="对联盟旅人而言，送达这封信能为守望湿地大路的哨兵带去重要情报，以及悲喜交织的慰藉。",["race:Dwarf"]="对矮人而言，麦琳的信揭示了探险者协会在卡兹莫丹危机四伏的荒野中探寻远古历史时，成员们付出的切身代价。"},sec={{t="废墟中的急信",b="麦琳·石纹在湿地的维尔加挖掘场写下这封信时，挖掘场已是一片废墟。矮人探险队在发掘巨大的史前化石和遗物时，惊扰了一窝杂斑迅猛龙。这些野兽涌入挖掘沟，杀死了数名工人，将幸存的研究人员困住。混乱之中，麦琳向身在米奈希尔港的丈夫塔雷尔传去了消息。她、勘察员维尔加和奥莫尔·铁衣躲在设有路障的避难所里，幸存了下来。"}},faq={{q="麦琳的信件是谁写的？",a="麦琳·石纹在湿地米奈希尔港以东的挖掘场参加考古探险期间，写下了这封信。",al={"麦琳的信件作者","麦琳是谁"}},{q="这封信是写给谁的？",a="麦琳把信写给了塔雷尔·石纹，他正在米奈希尔港的桥上焦急地等待消息。",al={"麦琳的信件收信人","谁收到麦琳的信件"}},{q="挖掘队遭遇了什么？",a="考古队在发掘巨大的骨骼化石时，遭到了杂斑迅猛龙的围攻。许多矮人工人遇害，只有少数人躲进临时营地的路障后面，幸存了下来。",al={"挖掘场发生了什么","探险队为何失败"}},{q="谁帮助麦琳在袭击中活了下来？",a="奥莫尔·铁衣帮助麦琳在袭击中活了下来。他保护着麦琳和首席勘察员，为他们争取时间撤入避难所，而迅猛龙则攻陷了挖掘场的其余地方。",al={"谁救了麦琳","奥莫尔·铁衣"}}},fx={bce088a8={q="麦琳的信件是什么？",a="麦琳的信件是一封由麦琳·石纹写下的紧急消息。她是湿地挖掘现场遭到迅猛龙袭击后的幸存者。信是写给她深爱的塔雷尔·石纹的，叙述了他们的挖掘队遭遇的灾难，并确认她、勘察员维尔加和奥莫尔·铁衣都侥幸逃过一劫。",al={"麦琳的信件","麦琳的信件是什么","麦琳的便笺"}},ded8799c={q="塔雷尔为什么想要麦琳的信件？",a="塔雷尔·石纹派你前往危险的沼泽，专门打探他爱人的消息，以及失踪的挖掘队员的下落。麦琳的信件确认她仍然活着，这对他至关重要；信中还详细讲述了挖掘现场的惨重损失，以及他们为躲避周围的迅猛龙而逃往何处。",al={"为什么要送交麦琳的信件","塔雷尔为什么想要这封信","麦琳信件的用途"}}},fp="15,152,25.471.0,26.142.0,31.112.0,37.190.0,37.183.0"}
P.entries["item:middle-of-gelkak-s-key"] = {n="基尔卡克钥匙的中部",s="在黑海岸近海，蛇颈龙击沉了基尔卡克·旋杆的船，他的钥匙也断成了三截。灰雾鱼人从岸边拿走了中间的碎片。",h="在黑海岸近海，蛇颈龙击沉了基尔卡克·旋杆的船，他的钥匙也断成了三截。灰雾鱼人从岸边拿走了中间的碎片。",kw={"发条","黑海岸","基尔卡克·旋杆","灰雾","基尔卡克钥匙的中部","鱼人","船只残骸"},ang={["profession:Engineering"]="身为工程师，你能看出这个特制的机械部件如何为发条大副上弦并驱动它，展现出海盗手中的侏儒才智。"},sec={{t="淤泥中的碎片",b="蛇颈龙将基尔卡克·旋杆的船拖入海中时，他的发条钥匙断裂了。这名侏儒海盗被冲上岸，随身物品在礁石浅滩上摔得粉碎。这把特制钥匙是为他的机械大副打造的，但海难让它断成了三截，散落在海滩各处。海边的野兽叼走了顶部和底部。在黑海岸浪涛间游荡的灰雾鱼人拿走了中间一截，将它留在营地和它们占据的船只残骸中。"}},faq={{q="基尔卡克钥匙的中部有什么用途？",a="基尔卡克钥匙的中部是基尔卡克·旋杆需要的三块碎片之一。将它与顶部和底部拼合，就能组成重新启动他的机械大副所需的钥匙。",al={"基尔卡克的钥匙有什么用","基尔卡克钥匙的中部用途","为什么需要这把钥匙"}},{q="这块钥匙碎片落到了哪里？",a="灰雾鱼人捡走了中间的碎片。在黑海岸的沙滩和船只残骸附近，可以从袭击者、神谕者、撒网者、潮汐猎手及其他部族成员身上找到它。",al={"钥匙中部在谁手里","哪里能找到基尔卡克钥匙的中部","钥匙中部由谁掉落"}},{q="钥匙最初为什么会断裂？",a="凶猛的蛇颈龙在近海击沉了基尔卡克的船。这名侏儒被冲上岸时，钥匙撞上海边的岩石，断成了三截，随后被当地的食腐动物和拾荒者带走。",al={"钥匙是怎么断的","为什么断成碎片"}}},fp="22,138,22.481.0,44.163.0,32.176.0,42.190.0"}
P.entries["item:milly-s-harvest"] = {n="米莉的葡萄",s="迪菲亚到来后，北郡农场的米莉的葡萄被遗弃在田间。一箱箱、一桶桶葡萄随时可能被偷走，或被修道院卫兵的靴子踩烂。",h="迪菲亚到来后，北郡农场的米莉的葡萄被遗弃在田间。一箱箱、一桶桶葡萄随时可能被偷走，或被修道院卫兵的靴子踩烂。",kw={"迪菲亚","艾尔文森林","葡萄","米莉·奥斯沃斯","米莉的葡萄","北郡修道院","北郡农场"},ang={["faction:Alliance"]="北郡农民面临的威胁，显露出暴风城驻军的兵力已何等薄弱。普通百姓要依靠过路的冒险者来保住生计。",["race:Human"]="作为一名从北郡踏上旅途的人类，你在取回米莉的葡萄时，或许就会在家门口初次领教迪菲亚潜行者的无法无天。"},sec={{t="脆弱的收成",b="米莉·奥斯沃斯在北郡农场采摘葡萄。这些收成对当地的酿酒人和修道院里的人们十分重要。戴着红色面罩的武装匪徒闯进田间时，米莉逃到了修道院内。她刚摘下的葡萄散落在一排排葡萄藤之间。"},{t="战火殃及",b="暴风城卫兵守着山谷入口，但人数太少，北郡仍易受袭击。驻军承诺赶走迪菲亚。米莉担心，卫兵与盗贼之间旷日持久的争斗会毁掉她的收成。这些箱子可能遭到践踏，或被当作补给搬走，让北郡失去难得在平静日子里收获的果实。"}},faq={{q="米莉的葡萄是什么？",a="米莉的葡萄是米莉·奥斯沃斯在迪菲亚暴徒占据北郡农场之前采摘并装进箱子和桶里的葡萄。",al={"米莉的葡萄","收成是什么","米莉·奥斯沃斯的葡萄"}},{q="为什么那些箱子被留在了葡萄园里？",a="米莉采摘葡萄时，迪菲亚强盗袭击了葡萄园。她只得丢下葡萄，逃往北郡修道院。",al={"为何被遗弃","米莉为何丢下葡萄","为何丢下收成"}},{q="为什么北郡的卫兵无法取回收成？",a="迪菲亚的入侵和当地的威胁让北郡的卫兵疲于应付。米莉也担心，卫兵在驱赶强盗时会用靴子踩烂葡萄。",al={"为何不由卫兵取回","卫兵为何无法取回","暴风城卫兵 北郡"}},{q="威胁这些收成的强盗是什么人？",a="威胁这些收成的强盗属于迪菲亚潜行者，这伙不法之徒和匪盗在艾尔文森林各处制造动乱。",al={"谁占据了葡萄园","谁在袭击葡萄园","葡萄园强盗"}}},fx={["1d7cbab4"]={q="为什么米莉想要找回收获的葡萄？",a="米莉·奥斯沃斯亲手采收了这些葡萄，并以此为生，但迪菲亚匪徒占领葡萄园时，她不得不将它们丢下。她担心，就算盗贼没有先把果实抢走，修道院的卫兵也会在驱逐匪徒时，将这些脆弱的葡萄踩进泥里。",al={"为什么 米莉 想要收获的葡萄","为什么要找回米莉的葡萄","葡萄为什么重要"}}},fp="15,174,15.261.0,17.328.0,24.138.0,48.128.0,56.161.0,44.141.0"}
P.entries["item:miners-gear"] = {n="矿工装备",s="矿工装备存放在洛克莫丹北部的银泉矿洞中。狗头人占据了矿道，矿工联盟希望在当地守卫发起进攻前收回工具。",h="矿工装备存放在洛克莫丹北部的银泉矿洞中。狗头人占据了矿道，矿工联盟希望在当地守卫发起进攻前收回工具。",kw={"肮脏的爪子","狗头人","洛克莫丹","矿工装备","矿工联盟","巡山人卡尔·雷矛","银泉矿洞"},ang={["profession:Mining"]="身为矿工，你深知精心锻造的矮人铁器有多珍贵。让那些头顶蜡烛的拾荒者占着优质矿镐和铁锹，实在令人惋惜。",["race:Dwarf"]="身为矮人，你或许无法容忍狗头人将肮脏的爪子伸向矮人的工艺品，这是莫大的侮辱。矿洞亟待清剿。"},sec={{t="矿工联盟的物资",b="银泉矿洞的矿石耗尽后，矿工联盟便将寂静的矿道用作采矿设备仓库。狗头人占领了矿洞，夺走了储存的物资，还在板条箱之间筑起了巢穴。矿工联盟担心巡山人的进攻会损毁这些矮人装备，也担心拾荒者会糟蹋它们。进入矿洞，赶在这两种厄运降临之前，将板条箱搬到安全的地方。"}},faq={{q="矿工装备是什么？",a="矿工装备是矿工联盟存放在银泉矿洞干燥矿道中的成箱矮人挖掘工具，其中包括矿镐和铁锹。",al={"矿工装备是什么","矿工装备物品","洛克莫丹矿工装备"}},{q="为什么把装备留在矿洞里？",a="银泉矿洞的矿石耗尽后，矿工联盟将空置的矿道改成了仓库。这些装备一直存放在那里，直到狗头人侵占了矿井。",al={"装备为什么在银泉矿洞","为什么把装备留在那里"}},{q="谁想收回这些装备？",a="巡山人卡尔·雷矛负责指挥矿工联盟的回收行动。他希望在战友们进军剿灭狗头人之前，将这些工具抢救出来。",al={"谁想要矿工装备","谁需要这些装备","巡山人卡尔·雷矛的装备"}},{q="在哪里能找到矿工装备？",a="矿工联盟的板条箱散落在银泉矿洞的矿井各处，矿洞位于洛克莫丹北部、奥加兹岗哨以东。",al={"矿工装备位置","哪里能找到矿工装备","矿工联盟板条箱位置"}}},fp="12,184,30.382.0,21.149.0,34.167.0,30.152.0,32.128.0"}
P.entries["item:miners-union-card"] = {n="矿业工会会员卡",s="在月溪镇，工会会员卡记录着那些葬身地下的劳工。工人们曾随身带着它们穿行于矿井，如今，这些卡片仍留在黑暗矿道中的骷髅亡者身上。",h="在月溪镇，工会会员卡记录着那些葬身地下的劳工。工人们曾随身带着它们穿行于矿井，如今，这些卡片仍留在黑暗矿道中的骷髅亡者身上。",kw={"塌方","收集记忆","死亡矿井","矿业工会会员卡","月溪镇","骷髅矿工","暴风城","工会会员卡"},ang={["faction:Alliance"]="暴风城王国各地的一些家庭始终不知道外出做工的亲人遭遇了什么，找回这些卡片能让他们得以释怀。",["profession:Mining"]="对勘探者和矿工而言，这些卡片让人想起塌方和疏于管理的矿井所带来的致命危险。"},sec={{t="矿井深处的惨剧",b="在迪菲亚潜行者控制月溪镇之前，矿工们为工会在地下劳作，为王国开采珍贵的矿石。一次塌方毁掉了一条主要矿井通道，数十人被压死在岩石之下。死者复生，成了骷髅矿工、挖掘工和爆破工。工会会员卡仍留在他们枯骨上的衣袋里，成为证明他们生前身份的最后凭据。在暴风城，幸存的工友正在寻找这些卡片，希望查明遇难工人的身份，让他们的家人得以释怀。"}},faq={{q="矿业工会会员卡是什么？",a="矿业工会会员卡是月溪镇矿井工会成员的身份证明。幸存的工人借助这些卡片，查明谁在塌方中遇难。",al={"工会会员卡是什么","矿工会员卡","工会会员卡"}},{q="这些卡片来自哪里？",a="这些卡片可以在月溪镇地下坍塌矿道中的亡灵劳工身上找到，包括骷髅矿工、亡灵挖掘工和亡灵爆破工。",al={"哪里能找到工会会员卡","谁掉落矿工会员卡","会员卡掉落地点"}},{q="矿工为什么变成了亡灵？",a="一次塌方将矿工们困在了深深的矿井中。究竟是什么使他们变成亡灵，无人知晓；如今，他们的遗骸仍在月溪镇地下坍塌的矿道中游荡。",al={"矿工为什么变成骷髅","矿工是怎么死的","死亡矿井亡灵"}},{q="谁希望找回这些卡片？",a="在塌方中逃过一劫、如今住在暴风城的工友们正在寻找这些卡片。他们希望将事情的经过告诉遇难矿工的家人，让他们的心灵得到安宁。",al={"谁收工会会员卡","收集记忆任务给予者","交还工会会员卡"}}},fp="18,179,19.484.0,29.152.0,31.150.0,26.147.0,31.173.0"}
P.entries["item:minshina-s-skull"] = {n="明希纳的颅骨",s="在回音群岛，明希纳的颅骨中束缚着明希纳的灵魂，他是一名暗矛巨魔，也是加德林大师的兄弟。扎拉赞恩将部族赶出群岛后，把他的灵魂困在颅骨中，并用颅骨为黑暗仪式提供力量。",h="在回音群岛，明希纳的颅骨中束缚着明希纳的灵魂，他是一名暗矛巨魔，也是加德林大师的兄弟。扎拉赞恩将部族赶出群岛后，把他的灵魂困在颅骨中，并用颅骨为黑暗仪式提供力量。",kw={"能量法阵","暗矛","回音群岛","加德林","明希纳","森金村","颅骨","扎拉赞恩"},ang={["faction:Horde"]="回音群岛就在杜隆塔尔近海，夺回颅骨是在早期对扎拉赞恩掌控群岛之势的一次打击。",["race:Troll"]="对暗矛而言，扎拉赞恩亵渎明希纳的行径违背了先祖传统。夺回他的颅骨关乎部族的荣誉。"},sec={{t="受困的灵魂",b="扎拉赞恩夺取回音群岛、驱逐暗矛时，明希纳被俘并惨遭杀害。这个背叛部族的巫医将受害者的灵魂束缚在明希纳被斩下的颅骨中，不让他安息。颅骨位于最南端岛屿的一座能量法阵内，使明希纳始终受制于扎拉赞恩的魔法。加德林大师在梦中听见兄弟呼唤自己，深受折磨，于是寻求勇敢的旅行者进入被占据的群岛，夺回颅骨，解除扎拉赞恩对明希纳灵魂的控制。"}},faq={{q="明希纳是谁？",a="明希纳是一名暗矛巨魔，也是森金村加德林大师的兄弟。扎拉赞恩在回音群岛背叛部族时，他惨遭杀害。",al={"明希纳背景故事","明希纳是谁","加德林大师的兄弟"}},{q="明希纳的灵魂为何被困在他的颅骨中？",a="扎拉赞恩用黑暗魔法将明希纳的灵魂束缚在他被斩下的头颅中。颅骨被放置在主岛的一座能量法阵内，使明希纳的灵魂受制于扎拉赞恩的意志，无法回归先祖。",al={"为何囚禁他的灵魂","扎拉赞恩颅骨仪式","灵魂困在颅骨中"}},{q="颅骨在哪里？",a="颅骨位于回音群岛最南端、面积最大的岛屿上。它被放置在山丘顶端的一座能量法阵内，周围有蜡烛、仪式标记和其他颅骨，由扎拉赞恩的奴仆看守。",al={"明希纳的颅骨在哪里","能量法阵位置","回音群岛颅骨位置"}},{q="把颅骨交给加德林大师后会发生什么？",a="当你将颅骨带回森金村，交给加德林大师时，黑暗魔法便会解除。明希纳的幽灵形体会短暂显现，鞠躬致谢，然后平静地离去，前往先祖的国度。",al={"解救明希纳","加德林颅骨奖励","明希纳的结局"}}},fp="16,242,16.507.0,17.142.0,44.206.0,27.192.0,56.206.1"}
P.entries["item:mirror-lake-water-sample"] = {n="明镜湖水的样本",s="人们在艾尔文森林的明镜湖采集湖水，交给暴风城的詹妮亚·坎农。法师们将检验湖水，查看奥术能量流是否改变了当地的水质。",h="人们在艾尔文森林的明镜湖采集湖水，交给暴风城的詹妮亚·坎农。法师们将检验湖水，查看奥术能量流是否改变了当地的水质。",kw={"奥术污染","艾尔文森林","瓶子","詹妮亚·坎农","明镜湖","暴风城","水样","巫师圣殿"},ang={["class:Mage"]="作为在巫师圣殿受训的法师，采集这份样本是你早期的职责之一。这项任务教你留意周围环境中的魔网地脉，并识别失控魔法的渗漏。"},sec={{t="检验艾尔文的水质",b="詹妮亚·坎农派遣有潜力的学徒前往明镜湖采集湖水。湖泊位于Stormwind Gate的西南方不远处，学徒们在那里用特制的瓶子装取瀑布下方的水。\n\n暴风城的巫师圣殿担心，灾难性的冲突过后，世界的魔法脉络仍未平息。那里的法师将检验样本，查看附近居民使用的水道中是否混入了游离的魔法污染。"}},faq={{q="明镜湖水的样本是什么？",a="明镜湖水的样本是从艾尔文森林的瀑布采集的水，装在詹妮亚的瓶子里。新手法师采集这些水，供巫师圣殿检验。",al={"明镜湖样本","水样物品","詹妮亚的水"}},{q="詹妮亚·坎农为什么需要这份水样？",a="近期席卷艾泽拉斯的魔法动荡扰乱了原本稳定的魔法能量流。詹妮亚·坎农担心，失控的魔法能量可能改变自然环境，并污染当地的饮用水。",al={"为何检验明镜湖","詹妮亚·坎农的目的","魔法污染的水"}},{q="在哪里采集样本？",a="样本取自流入明镜湖的瀑布下方，位于艾尔文森林的暴风城大门西南方。",al={"哪里采集样本","明镜湖位置","样本瀑布"}},{q="如果水受到了魔法污染，会有什么后果？",a="詹妮亚·坎农担心，如果魔网能量流污染了水源，长期饮用明镜湖的水可能会引发不良的魔法效应。",al={"污染水的影响","明镜湖是否有毒"}}},fx={["935f4959"]={q="明镜湖水的样本来自哪里，又是谁采集的？",a="这份样本直接采自注入明镜湖的瀑布底部，就在艾尔文森林中，暴风城城门的西南方不远处。你使用法师训练师詹妮亚·坎农提供的空瓶，亲自为暴风城的施法者取水，让他们得以检查周边野外魔法流的状况。",al={"明镜湖水的样本来自哪里","谁制作了明镜湖水的样本","明镜湖水的样本来源"}}},fp="24,166,28.411.0,37.151.0,46.177.0,30.123.0,60.154.0"}
P.entries["item:mist-veil-s-lockbox"] = {n="迷雾之纱号的保险箱",s="迷雾之纱号的保险箱躺在黑海岸近海的一艘暗夜精灵沉船中。箱内装着船长的日志和私人物品，在沿岸鱼人伏击并击沉船只时一同沉入海底。",h="迷雾之纱号的保险箱躺在黑海岸近海的一艘暗夜精灵沉船中。箱内装着船长的日志和私人物品，在沿岸鱼人伏击并击沉船只时一同沉入海底。",kw={"奥伯丁","黑海岸","高尔博德·钢手","保险箱","迷雾之纱号","鱼人","沉船","银色清晨号"},ang={["faction:Alliance"]="作为联盟的一员，你可以悼念遇难的船员，并帮助奥伯丁的航海者们。",["race:NightElf"]="作为一名暗夜精灵，你可以帮助找回遇难船长的日志，让船长的灵魂在黑海岸近海安息。"},sec={{t="沉入深海",b="暗夜精灵船只迷雾之纱号在驶向奥伯丁的途中沉没。沿岸鱼人伏击了它和它的姊妹船银色清晨号，攻陷了两艘船。船长在袭击中丧生。船长的日志和私人物品仍封存在被淹没的船舱里的保险箱中，周围满是鱼人。"},{t="船员的安息",b="幸存的水手抵达了奥伯丁，但失去船只和船长的悲痛仍萦绕着他们。高尔博德·钢手正在寻找迷雾之纱号的保险箱，希望能妥善祭奠并安葬船长最后的遗物。从淹没的残骸中找回保险箱，或许能给陆地上的幸存者带来些许慰藉。"}},faq={{q="迷雾之纱号的保险箱里有什么？",a="迷雾之纱号的保险箱里装着船长的日志和私人物品。船长在沉船时丧生，奥伯丁的幸存船员希望找回这些遗物，以此缅怀逝去的船长。",al={"迷雾之纱号的保险箱里的物品","保险箱里装着什么","箱子里有什么"}},{q="迷雾之纱号是如何沉没的？",a="迷雾之纱号在驶向奥伯丁的途中遭到沿岸鱼人的伏击。鱼人攻陷了这艘船，它与姊妹船银色清晨号一同沉没。",al={"船为什么失事","谁击沉了迷雾之纱号","迷雾之纱号发生了什么"}},{q="保险箱在哪里？",a="保险箱位于黑海岸近海、奥伯丁以北的水下，在迷雾之纱号沉船被淹没的船体内。沉船里满是鱼人。",al={"迷雾之纱号的保险箱在哪里","迷雾之纱号的位置","保险箱的位置"}},{q="谁想找回保险箱？",a="奥伯丁的高尔博德·钢手正在为幸存船员寻找保险箱，希望借此悼念逝去的船长，让船员们的内心得到安宁。",al={"谁收取保险箱","谁发布任务","高博尔的保险箱任务"}}},fp="19,179,18.284.0,17.291.0,35.199.0,27.152.0,27.131.0,32.131.0"}
P.entries["item:mo-grosh-crystal"] = {n="莫格罗什水晶",s="在洛克莫丹东北部，莫格罗什食人魔开采并守护着具有特殊炼金性质的稀有水晶。矮人工程师用它们来中和黑铁的炸药。",h="在洛克莫丹东北部，莫格罗什食人魔开采并守护着具有特殊炼金性质的稀有水晶。矮人工程师用它们来中和黑铁的炸药。",kw={"黑暗笼罩","辛德维尔七世","洛克莫丹","莫格罗什水晶","莫格罗什","巨石水坝"},ang={["profession:Mining"]="身为矿工，你看得出这些原矿来自食人魔领地深处。它们与有机试剂混合时，会产生不同寻常的反应。",["race:Dwarf"]="身为矮人，你知道守护巨石水坝需要巧思。矮人工程师将食人魔开采的珍宝化为抵御黑铁阴谋的保障。"},sec={{t="食人魔的稀有珍货",b="莫格罗什食人魔在洛克莫丹东北部的要塞中开采水晶。这个氏族崇尚蛮力，不擅精细的金属工艺，却十分珍视这些石头。执行者、神秘的萨满祭司和身形高大的首领都随身带着它们。这些水晶十分稀少，因此食人魔在莫格罗什要塞内严加看守。"},{t="应对黑铁的威胁",b="首席工程师辛德维尔七世正在寻找一块莫格罗什水晶、蜘蛛潜伏者的毒液和鳄鱼的眼泪。他得知黑铁破坏者计划袭击巨石水坝。矮人工程师将这种矿物与那些试剂混合，制成一种化合物，在山谷遭到洪水淹没之前使那些不稳定的炸药失效，解除爆炸威胁。"}},faq={{q="莫格罗什水晶来自哪里？",a="莫格罗什食人魔在洛克莫丹东北部开采并保存这些水晶。莫格罗什要塞内的任何氏族成员都可能携带水晶，包括秘法师、蛮兵、执行者和萨满祭司。",al={"莫格罗什水晶位置","哪里能找到莫格罗什水晶","谁掉落莫格罗什水晶"}},{q="这种水晶有什么用途？",a="巨石水坝的首席工程师辛德维尔七世需要一块水晶来配制中和剂。水晶与潜伏者的毒液和鳄鱼的眼泪混合后，能使黑铁用来破坏水坝的炸药失效。",al={"莫格罗什水晶有什么作用","莫格罗什水晶用途","辛德维尔七世为什么需要水晶"}},{q="食人魔为什么开采这些水晶？",a="莫格罗什食人魔在要塞周围的丘陵中开采稀有水晶。它们如何使用这些水晶，并无记载。",al={"食人魔为什么有水晶","食人魔水晶背景故事"}}},fx={["1713c585"]={q="莫格罗什水晶是什么？",a="莫格罗什水晶是一种极其稀有的矿物，由莫格罗什食人魔在洛克莫丹东北部的据点中开采。它因不同寻常的特性而备受重视，首席工程师辛德维尔七世认定它是调制一种特殊混合剂的关键材料，这种混合剂可使威胁巨石水坝的黑铁炸药失效。",al={"莫格罗什水晶是什么","莫格罗什水晶背景","莫格罗什水晶身份"}}},fp="16,170,23.326.0,31.326.1,37.180.0,29.200.0,40.119.0"}
P.entries["item:modr-fragment"] = {n="莫德尔碎片",s="在迅猛龙肆虐的维尔加挖掘场，莫德尔碎片散落在遗物和松土之间。碎片上刻着古老的泰坦文字，是戈阿兹之石缺失的四块碎片之一。",h="在迅猛龙肆虐的维尔加挖掘场，莫德尔碎片散落在遗物和松土之间。碎片上刻着古老的泰坦文字，是戈阿兹之石缺失的四块碎片之一。",kw={"阿度斯","挖掘","戈阿兹之石","高尔姆","莫德尔碎片","奈尔鲁","上古之神","泰坦","湿地","维尔加"},ang={["faction:Alliance"]="身为联盟的旅者，你帮助勘察员维尔加深入迅猛龙肆虐的挖掘场，为铁炉堡保存珍贵的历史研究成果。",["race:Dwarf"]="身为矮人，你知道探险者协会正在寻找莫德尔碎片这样的遗失碎片，以解读Titan的遗产，揭开你们一族久远的历史。"},sec={{t="戈阿兹之石的碎片",b="勘察员维尔加在湿地的挖掘场发现了戈阿兹之石，这块巨大的石板上刻着古老的泰坦文字。凶猛的迅猛龙将探险者协会赶出了挖掘场，使他们未能完成工作。译出的铭文在四处缺口中断，掩去了关于神圣计划与厄运预言的警告。莫德尔碎片便是缺失的碎片之一，挖掘者逃命时，将它留在了遗物和翻起的泥土之间。"},{t="地下的秘密",b="勘察员维尔加可以将莫德尔碎片与阿度斯、高尔姆和奈尔鲁碎片拼合，还原完整的铭文。译出的文字讲述了世界初生时的往事，并提到“上古之神……被锁在大地之下”。沼泽地的挖掘工作揭开了一场争斗的痕迹，那场争斗始于世界诞生之初，至今仍被封缚在地下。"}},faq={{q="莫德尔碎片是什么？",a="莫德尔碎片是从戈阿兹之石上断裂下来的一块刻字石片。戈阿兹之石是一件古老的泰坦圣物，由勘察员维尔加在湿地的维尔加挖掘场发现。",al={"莫德尔碎片","莫德是什么","莫德遗物"}},{q="谁在寻找这块碎片？",a="勘察员维尔加是探险者协会的一名考古学家，他正在寻找这块碎片，以补全石板上缺失的文字。他驻守在迅猛龙盘踞的挖掘场边缘。",al={"谁需要莫德尔碎片","维尔加碎片任务"}},{q="集齐四块碎片后会怎样？",a="将莫德尔碎片与阿度斯、高尔姆和奈尔鲁碎片拼合，勘察员维尔加就能修复戈阿兹之石。完整的泰坦文字提到“上古之神……被锁在大地之下”。",al={"戈阿兹之石修复完成","发现历史结局","戈阿兹之石写了什么"}},{q="在哪里能找到这块碎片？",a="你可以在湿地米奈希尔港以东的维尔加挖掘场各处找到莫德尔碎片。它藏在古代遗物陶罐或松土中，周围有凶猛的迅猛龙守卫。",al={"莫德尔碎片位置","哪里能找到莫德"}}},fx={c1df2f2b={q="莫德尔碎片来自哪里？是谁制造的？",a="莫德尔碎片是戈阿兹之石的一部分。这件古老遗物是在湿地米奈希尔港以东的挖掘场发现的。石上刻有泰坦文字，是泰坦留下的遗物。泰坦在远古时代塑造了世界，并留下了关于其神圣计划和末日预言的神秘记录。",al={"莫德尔碎片的来源","谁制造了莫德尔碎片","莫德尔碎片来自哪里"}}},fp="13,167,25.455.0,25.315.1,26.164.0,33.181.0,50.181.1,28.194.0"}
P.entries["item:moldy-tome"] = {n="发霉的书籍",s="希尔斯布莱德海岸上的发霉的书籍，在一次海难后已残破不堪。它曾是阴谋之书的一部分，如今仍吸引着寻求恶魔召唤知识的术士。",h="希尔斯布莱德海岸上的发霉的书籍，在一次海难后已残破不堪。它曾是阴谋之书的一部分，如今仍吸引着寻求恶魔召唤知识的术士。",kw={"碧玉矿洞","地狱猎犬","希尔斯布莱德","发霉的书籍","南海镇","破损的手稿","阴谋之书","术士"},ang={["class:Warlock"]="身为术士，你寻找发霉的书籍，是为了帮助找回驱使地狱猎犬所需的仪式。"},sec={{t="遗失于波涛",b="阴谋之书曾是保存在洛丹伦的一部珍稀的黑暗魔法典籍。有人蓄意损毁了它，将它撕成两半。其中一半如今被称为发霉的书籍，随船南下，运往米奈希尔港和铁炉堡。那艘船始终未能抵达目的地。它沉没在南海镇以西的险恶海域，幸存下来的半部书则被冲上了碧玉矿洞以南的海岸。潮气和海浪毁坏了书页，鱼人则在希尔斯布莱德海岸四处搜寻可用之物。"},{t="寻回黑暗典籍",b="尽管羊皮纸已经发霉腐烂，发霉的书籍仍记载着强大的恶魔知识。寻找它的术士冒险闯入海岸上的营地。克罗姆·粗臂在铁炉堡指引其中一些术士，约拉·安尼森则在幽暗城指引另一些术士。将它与来自千针石林洞穴的另一半——破损的手稿——合在一起，便能复原这部典籍，获得召唤并束缚地狱猎犬所需的准确咒文。"}},faq={{q="发霉的书籍是什么？",a="发霉的书籍是珍稀典籍阴谋之书的一半，这部黑暗典籍记载着召唤恶魔的仪式。它在一次海难中遗失，被海水浸透，已经腐烂。",al={"发霉的书","这是什么物品","发霉的书籍背景故事"}},{q="发霉的书籍最终流落何处？",a="发霉的书籍被冲上了希尔斯布莱德丘陵的海岸，位于南海镇以西、碧玉矿洞以南。海岸上的鱼人将它留在自己的营地里。",al={"发霉的书籍位置","发霉的书籍在哪","哪里能找到发霉的书籍"}},{q="这部典籍为什么会在船上？",a="一艘船载着发霉的书籍从洛丹伦驶向米奈希尔港，准备将它交给铁炉堡的学者。船还未完成航程，便在希尔斯布莱德近海沉没了。",al={"为何遗失在海上","海难中的典籍","典籍的运送"}},{q="补全阴谋之书需要什么？",a="将发霉的书籍与它的另一半——破损的手稿——合在一起，就能补全阴谋之书。那份手稿最终流落到了千针石林的裂蹄堡。",al={"典籍的另一半","缺失的书页","阴谋之书的各部分"}}},fx={f96f31c9={q="发霉的书籍来自哪里？",a="发霉的书籍原本是一本名为阴谋之书的孤本的一部分，这本书曾保存在洛丹伦的宏伟厅堂中。很久以前，这本独一无二的魔典遭到破坏，大量羊皮纸书页被从装订处撕走。残存的书籍原定从希尔斯布莱德向南运送，渡海前往米奈希尔港和铁炉堡，但载着它的船在南海镇以西的海岸失事，潮湿的书页就此在浅水中腐烂。",al={"发霉的书籍来源","谁写了发霉的书籍","发霉的书籍曾存放在哪里","发霉的书籍历史"}},["53a1a6b9"]={q="为什么有人想要发霉的书籍？",a="学者和黑暗法术的研习者寻找它，是因为阴谋之书从来只有一本。书中的奥术篇章记载着稀有且严加保密的术士知识，其中包括掌握召唤和束缚地狱猎犬之术所必需的秘密。铁炉堡的克罗姆·粗臂和幽暗城的约拉·安尼森等学者，哪怕只能短暂一睹其中的禁忌文字也心向往之，因此，找回这部浸水的残卷对重聚全书至关重要。",al={"为什么寻找发霉的书籍","谁想要发霉的书籍","发霉的书籍为何重要","术士为什么想要发霉的书籍"}}},fp="10,171,17.420.0,24.412.1,23.159.0,32.145.0,27.166.0,49.169.0"}
P.entries["item:moonpetal-lily"] = {n="月牙百合花",s="在泰达希尔的淡水池边，月牙百合花的花瓣因其恢复功效而备受珍视。治疗者用它们配制药剂和治疗药水。",h="在泰达希尔的淡水池边，月牙百合花的花瓣因其恢复功效而备受珍视。治疗者用它们配制药剂和治疗药水。",kw={"奥达希尔","解毒药","迪兰妮亚·月光","埃沃隆","月牙","月牙百合花","幽影谷","泰达希尔"},ang={["profession:Herbalism"]="危急时刻，治疗者会亲手采集月牙百合花。这些花展现了泰达希尔植物的恢复力量。",["race:NightElf"]="作为一名在幽影谷接受训练的年轻kaldorei，你会学习月牙百合花等本地植物如何疗伤。这是与自然共处的启蒙一课。"},sec={{t="池畔草木",b="月牙百合花生长在淡水池塘湿润的岸边。它们常见于幽影谷中奥达希尔的西北方。如同这棵年轻的世界之树上其他的植物，它们也汲取着泰达希尔幽静林地的精华。宽大的花瓣在水边泛着光泽，充足的水分让它们茁壮生长。"},{t="天然解毒药",b="暗夜精灵的治疗者和草药师珍视月牙百合花的治疗功效。与紫蓝色蘑菇等森林植物混合后，这些百合花有助于缓解症状、稳定病情。治疗者用它们熬制解毒药，对抗致命毒素，包括黑丝洞中树林蜘蛛的毒液。"}},faq={{q="月牙百合花生长在哪里？",a="月牙百合花生长在泰达希尔的幽影谷中，位于奥达希尔西北方的两处淡水池塘岸边。",al={"哪里能找到月牙百合花","月牙百合花位置","百合花采集点"}},{q="月牙百合花有什么用途？",a="月牙百合花具有恢复和治疗功效。在幽影谷，迪兰妮亚·月光将它们与紫蓝色蘑菇和树林蜘蛛的脓液混合，熬制治疗蜘蛛毒的解毒药。",al={"月牙百合花用途","月牙百合花有什么作用"}},{q="谁需要用这些百合花制成的解毒药？",a="埃沃隆是一名暗夜精灵，在黑丝洞附近被树林蜘蛛咬伤。他需要用月牙百合花制成的解毒药才能活命。",al={"解毒药是给谁的","埃沃隆中毒"}},{q="在泰达希尔之外也能采到月牙百合花吗？",a="月牙百合花生长在泰达希尔幽静的水池周围。在幽影谷枝叶掩映之处，人们熟知这种花。",al={"百合花在别处生长吗","月牙百合花其他区域"}}},fx={["1aae6896"]={q="月牙百合花是什么？",a="月牙百合花是一种大型水生花卉，原生于泰达希尔宁静的水域。它以强效的天然治疗能力而闻名，常生长在阴凉林间水池和池塘边潮湿的土壤中，例如幽影谷奥达希尔附近的水池。",al={"月牙百合花是什么","月牙百合花信息","关于月牙百合花"}}},fp="14,156,18.314.0,17.289.0,31.114.0,35.186.0,45.132.0,55.110.0"}
P.entries["item:moonstalker-fang"] = {n="月夜猛虎的牙齿",s="在奥伯丁附近，旅人们为维兹班恩·曲针的采样装置收集月夜猛虎的牙齿。这些牙齿来自黑海岸的月夜猛虎。",h="在奥伯丁附近，旅人们为维兹班恩·曲针的采样装置收集月夜猛虎的牙齿。这些牙齿来自黑海岸的月夜猛虎。",kw={"传声盒323","黑海岸","月夜猛虎","月夜猛虎的牙齿","影爪","维兹班恩·曲针"},ang={["class:Hunter"]="身为猎人，你需要敏锐的感官来应对moonstalkers，这些伏击猎物的掠食者能隐匿在黑海岸昏暗的林冠之中。",["race:Gnome"]="身为侏儒，你或许能认出维兹班恩·曲针的远程通信装置运用了侏儒工程学。他含糊不清的言语和不同寻常的采样选择，仍让人心生疑惑。"},sec={{t="研磨装置",b="月夜猛虎的牙齿来自在黑海岸森林边缘猎食的刃齿豹。它们的长牙能够切开血肉和骨头。维兹班恩·曲针是一位古怪的侏儒工匠，他却将这些牙齿用在了别处。在奥伯丁北面的大桥附近，传声盒 323将这些坚硬的獠牙碾成粉末，用于他的生态调查。"}},faq={{q="月夜猛虎的牙齿从哪里来？",a="月夜猛虎的牙齿来自黑海岸的月夜猛虎，包括幼兽、成年个体、雄性首领、雌性首领，以及潜行的影爪。",al={"哪里获取月夜猛虎的牙齿","谁掉落月夜猛虎的牙齿","獠牙来源"}},{q="谁需要月夜猛虎的牙齿？",a="维兹班恩·曲针需要六颗月夜猛虎的牙齿，用于传声盒 323，那是他设在奥伯丁北面河桥附近的自动监测装置。",al={"谁需要獠牙","什么任务需要獠牙","传声盒 323交任务"}},{q="獠牙进入机器后会怎样？",a="传声盒 323的齿轮将坚硬的獠牙磨成细粉，供维兹班恩进行野外实验。",al={"传声盒 323有什么用","为什么研磨獠牙"}}},fp="16,140,20.312.0,37.125.0,28.138.0,45.88.0"}
P.entries["item:moonwell-water-tube"] = {n="月亮井水瓶",s="在奥伯丁，月亮井水蕴含着具有净化之力的自然魔法。这瓶水用于检验一块神秘的红色水晶，它位于黑海岸东部的山脊之间。",h="在奥伯丁，月亮井水蕴含着具有净化之力的自然魔法。这瓶水用于检验一块神秘的红色水晶，它位于黑海岸东部的山脊之间。",kw={"当水流淌而下","奥伯丁","黑海岸","空水瓶","费伍德森林","月亮井水瓶","红色水晶"},ang={["class:Druid"]="德鲁伊深知，月亮井水是承载自然平衡的重要载体，适合用来对抗违背自然的腐化。",["race:NightElf"]="对暗夜精灵而言，用受过祝福的月亮井水探查外来的腐化，体现了他们依靠Elune的恩典揭示隐藏真相的传统。"},sec={{t="净化之水的容器",b="试管中装满了奥伯丁的月亮井水。这座圣池与艾露恩相连，蕴含着恢复与净化的魔法。即使只有少量井水，也能用于对抗腐化，或检验奇异的魔法力量。"},{t="调查红色水晶",b="研究者准备了这支试管，用来检验一块出现在黑海岸东部崖壁旁的巨大红色水晶。费伍德森林遭到腐化的高地耸立在山壁上方，因此他们担心水晶也源自那片黑暗。当受过祝福的井水流过水晶的切面时，不透明的晶石会短暂变得透明，显露出内部低鸣的奥秘。"}},faq={{q="井水取自何处？",a="井水取自奥伯丁的神圣月亮井，那里是黑海岸西部海岸的暗夜精灵庇护地。",al={"在哪里装满试管","试管水源","奥伯丁月亮井水"}},{q="为何要将月亮井水用于红色水晶？",a="月亮井水蕴含着浓缩的自然与月亮魔法。将它浇在奇异的红色水晶上，可以检验晶石的魔法本质，并使其不透明的表面短暂变得清澈。",al={"为何使用月亮井水","盛水试管的用途","井水有何作用"}},{q="研究者为何担忧这块水晶？",a="水晶位于与费伍德森林接壤的东部群山下方。费伍德森林受到的深重恶魔污染，让学者们担心这块外来的晶体会将腐化带入下方的黑海岸。",al={"为何检验水晶","红色水晶的危险","与费伍德森林的关联"}}},fp="19,146,28.203.0,29.339.1,30.106.0,42.174.0,52.175.0"}
P.entries["item:mossy-tumor"] = {n="青苔之瘤",s="涌泉湖周围的青苔之瘤，标志着腐化正在泰达希尔蔓延。这些从受腐化林精的树皮和血肉上割下的毒瘤，显露出邪恶力量正在这棵年轻的世界之树中扎根。",h="涌泉湖周围的青苔之瘤，标志着腐化正在泰达希尔蔓延。这些从受腐化林精的树皮和血肉上割下的毒瘤，显露出邪恶力量正在这棵年轻的世界之树中扎根。",kw={"腐化","达纳苏斯","青苔之瘤","雷利亚·绿树","泰达希尔","林精","涌泉湖"},ang={["class:Druid"]="身为致力于维护自然平衡的德鲁伊，看到林精这样的植物守护者身上长出毒瘤，你或许会深感不安，意识到泰达希尔出了极为严重的问题。",["race:NightElf"]="身为暗夜精灵，你知道族人种下泰达希尔，是为了重建他们与自然之间失落的联系。新家园这么快就出现了病变瘤体，是个令人不安的预兆。"},sec={{t="泰达希尔病患的征兆",b="泰达希尔的林精原本是为滋养和照料这棵巨树的枝条而造，但许多林精如今已变得充满敌意，疾病缠身。青苔之瘤就是这种疾病在血肉之躯上的显现。这些瘤体饱含毒素，遍布涌泉湖周围的林精沼泽兽、林精践踏者和老年林精身上。雷利亚·绿树与达纳苏斯的守护者们派遣旅人割除这些瘤体，将其彻底焚毁，以免毒素进一步渗入岛上的土壤。"}},faq={{q="什么是青苔之瘤？",a="青苔之瘤是从受污染的林精身上取下的病变瘤体。其中的恶毒毒素表明，泰达希尔的自然之灵正遭受非自然的腐化。",al={"青苔之瘤","这是什么瘤体","林精瘤体"}},{q="在哪里能找到青苔之瘤？",a="在泰达希尔北部涌泉湖周围受腐化的林精身上，可以找到青苔之瘤，包括林精践踏者、沼泽兽和老年林精。",al={"哪里获取瘤体","青苔之瘤掉落","林精位置"}},{q="雷利亚·绿树为什么需要这些瘤体？",a="雷利亚·绿树需要这些瘤体，以遏制侵蚀泰达希尔的腐化。他让人收集瘤体并将其烧成灰烬，以免其中浓缩的毒素重新渗入土壤和水中。",al={"雷利亚·绿树瘤体","为何焚烧瘤体"}},{q="林精为什么会染病？",a="一股邪恶力量正在泰达希尔各处扎根，扭曲着这里的照料者和野生生物。暗夜精灵正在调查这场疾病的真正源头，而身上已出现明显瘤体的林精则被认为无药可救。",al={"林精为何染病","林精腐化"}}},fp="11,189,33.427.0,22.149.0,31.164.0,46.184.0,42.220.0"}
P.entries["item:mountain-lion-blood"] = {n="山地狮的血液",s="遍布希尔斯布莱德和奥特兰克的山地狮的血液引起了药剂师林度恩的兴趣。在塔伦米尔，林度恩正在寻找新鲜血液，用来调制皇家药剂师学会令人畏惧的痛苦药剂。",h="遍布希尔斯布莱德和奥特兰克的山地狮的血液引起了药剂师林度恩的兴趣。在塔伦米尔，林度恩正在寻找新鲜血液，用来调制皇家药剂师学会令人畏惧的痛苦药剂。",kw={"奥特兰克","药剂师林度恩","痛苦药剂","希尔斯布莱德","山地狮的血液","皇家药剂师学会","塔伦米尔"},ang={["faction:Horde"]="作为部落的一员，在塔伦米尔周围收集野兽试剂，能增强你在希尔斯布莱德对抗敌对人类据点的力量。",["race:Undead"]="作为一名Undead，你收集的每一瓶血液都能帮助皇家药剂师学会研制生物武器，为被遗忘者稳固对洛丹伦的控制。"},sec={{t="丘陵中的试剂",b="山地狮游荡在希尔斯布莱德和奥特兰克的高地与丘陵间。猎人珍视它们的毛皮和利爪，而皇家药剂师学会的被遗忘者则想要它们体内的血液。塔伦米尔的药剂师林度恩相信，新鲜的山地狮血液可以作为一种强效药剂的基础，给活人带来苦难。"},{t="助长新的瘟疫",b="药剂师林度恩在塔伦米尔进行的实验，为皇家药剂师学会完善被遗忘者的新的瘟疫提供了支持。林度恩收集精力旺盛的野兽的血液，改良一种名为痛苦药剂的混合物，试验如何将当地的有机化合物用于对付黑暗女王的敌人。"}},faq={{q="山地狮的血液有什么用途？",a="塔伦米尔的药剂师林度恩需要十瓶山地狮的血液来调制痛苦药剂。皇家药剂师学会正在研究新的疾病。",al={"山地狮的血液用途","谁需要狮血","痛苦药剂血液"}},{q="在哪里可以收集到山地狮的血液？",a="山地狮的血液来自游猎于希尔斯布莱德丘陵，以及附近奥特兰克山脉积雪峭壁间的狮子。",al={"哪里找山地狮的血液","山地狮的血液位置","哪些狮子掉落血液"}},{q="药剂师林度恩为什么特别需要野生猫科动物的血液？",a="林度恩相信，强健好斗的山地狮体内的体液可以作为一种毒性药剂的基础，给希尔斯布莱德的活人居民带来巨大的痛苦。",al={"为什么需要狮血","林度恩为什么需要狮血"}},{q="山地狮的血液能用于炼金术配方吗？",a="不能。山地狮的血液是药剂师林度恩研究所用的实验试剂，并非常规炼金术配方的材料。",al={"炼金师能用山地狮的血液吗","狮血用于炼金术吗"}}},fx={dcf44a54={q="山地狮的血液是什么？",a="这是从在希尔斯布莱德丘陵和奥特兰克山脉崎岖山坡上游荡的山地狮身上采集的新鲜血液。它对普通炼金术士或工匠毫无用处，却具有皇家药剂师协会重视的生物特性，可用于致命的炼金实验。",al={"山地狮的血液是什么","山地狮血液的背景","这是什么血"}},["7c379830"]={q="山地狮的血液来自哪里？是谁制造的？",a="它并非经制作或加工而成，而是直接从洛丹伦北部土生土长的野猫身上采集的。游荡在希尔斯布莱德和奥特兰克之间高地上的山地狮，会被为驻扎在塔伦米尔的被遗忘者药剂师效力的代理人猎杀并放血。",al={"山地狮的血液来自哪里","山地狮血液的来源","谁制造了山地狮的血液"}}},fp="19,159,20.341.0,22.323.0,37.145.0,43.138.0,59.159.0,59.128.0"}
P.entries["item:muddy-journal-pages"] = {n="沾满泥污的日记书页",s="沾满泥污的日记书页是多年前从暮色森林的一处凶案现场找到的。这些书页饱经风雨，沾着泥土，至今仍由旅店老板斯密茨保管。虽然无法证实作者的身份，他仍将书页留作当地一桩悬案的证据。",h="沾满泥污的日记书页是多年前从暮色森林的一处凶案现场找到的。这些书页饱经风雨，沾着泥土，至今仍由旅店老板斯密茨保管。虽然无法证实作者的身份，他仍将书页留作当地一桩悬案的证据。",kw={"夜色镇","埃伯洛克","哈迦德","沾满泥污的日记书页","斯密茨"},ang={["class:Rogue"]="身为潜行者，将被遗忘的笔迹样本与饱经风雨的日记残页拼凑起来，便能体会到在击杀隐匿的凶手之前，需要进行何等缜密的取证工作。",["faction:Alliance"]="对联盟而言，查明暴风城贵族被屠杀的真相，能让暮色森林那些饱受战火侵扰的聚落中一桩久悬未决的案件终于有个了结。"},sec={{t="屠杀的证据",b="来访的贵族在暮色森林惨遭杀害后，旅店老板斯密茨在泥沼中找到了这些书页。他当时是和调查员哈迦德一起前往现场的。镇上既没有笔迹样本，也没有确凿的记录能将这些文字与嫌疑人联系起来，因此斯密茨悄悄将书页保存在夜色镇的旅店里。他等待着一位调查员从南方诸王国搜集散落的记录，将笔迹与那名住在森林深处的隐士比对。"}},faq={{q="沾满泥污的日记书页是在哪里找到的？",a="几年前，来访的贵族在暮色森林的林间惨遭杀害，旅店老板斯密茨和哈迦德在现场找到了这些书页。",al={"斯密茨在哪里找到书页","泥污书页的来源","泥污日记的位置"}},{q="为什么斯密茨刚找到书页时无法利用它们？",a="当地的调查员没有可供比对的笔迹样本，因此无法将书页上的笔迹与嫌疑人联系起来。",al={"为何秘密保存书页","斯密茨为何没有上交书页","斯密茨的证据难题"}},{q="谁需要查看这些书页？",a="必须将书页带给夜色镇守夜人的领袖指挥官阿尔泰娅·埃伯洛克，向她汇报贵族遇害案的调查情况。",al={"泥污书页交给谁","上交沾满泥污的日记书页","埃伯洛克泥污书页"}},{q="这些书页与什么罪行有关？",a="这些书页与几年前来访贵族在暮色森林林间惨遭杀害的案件有关，夜色镇当时未能侦破此案。",al={"哪场屠杀","斯塔文做了什么","来访贵族惨遭杀害"}}},fx={["7e79311d"]={q="沾满泥污的日记书页是什么？",a="这些是沾满污渍、被撕破的日记页，多年前在暮色森林一场残酷的贵族惨案现场被发现。它们由斯塔文·密斯特曼托所写，记录了他堕落的过程，也提供了人们苦苦寻觅的书面证据，证明他曾在屠杀现场，并已陷入疯狂。",al={"沾满泥污的日记书页是什么","沾满泥污的日记书页","这个物品是什么"}},bcc5553e={q="沾满泥污的日记书页来自哪里？是谁写的？",a="这些书页由斯塔文·密斯特曼托写下，在那些贵族遭到谋杀时遗落在泥泞中。旅店老板斯密茨和哈格德调查这场血案时发现了它们，但斯密茨一直保留多年，因为他没有笔迹样本，无法确认书页的作者。",al={"谁写了沾满泥污的日记书页","泥污书页来自哪里","沾满泥污的日记书页的作者"}},f7c3dc88={q="指挥官埃伯洛克为什么需要沾满泥污的日记书页？",a="指挥官阿尔泰娅·埃伯洛克负责夜色镇的防务，在对森林中的威胁采取行动前，需要确凿证据。结合你在王国各处收集到的笔迹证据，这些书页足以确证斯塔文有罪，并促使守夜人终于对付他。",al={"为什么把书页交给埃伯洛克","谁想要沾满泥污的日记书页","泥污书页为什么重要"}}},fp="19,238,28.458.1,41.141.0,59.129.0,29.152.1,37.144.0"}
P.entries["item:mudsnout-blossom"] = {n="Mudsnout Blossom",s="泥头花生长在塔伦米尔以南的奈杉德哨岗。泥头豺狼人守护着这些恶臭的毒蘑菇，而药剂师林度恩正为药剂研究寻找它们。",h="泥头花生长在塔伦米尔以南的奈杉德哨岗。泥头豺狼人守护着这些恶臭的毒蘑菇，而药剂师林度恩正为药剂研究寻找它们。",kw={"药剂师林度恩","苦楚药剂","希尔斯布莱德丘陵","泥头花","泥头豺狼人","奈杉德哨岗","塔伦米尔"},ang={["profession:Herbalism"]="身为草药师，你或许以为这是一种花，但Mudsnout Blossom其实是一种性质不稳定、气味恶臭的真菌，深受毒物学家和黑暗炼金师珍视。",["race:Undead"]="身为被遗忘者，你知道皇家药剂师学会采集泥头花，是为了利用其毒性，并改进生化武器。"},sec={{t="有毒的真菌",b="在塔伦米尔以南，泥头花生长于奈杉德哨岗。尽管名字里有个花字，它们却是硕大而恶臭的蘑菇，在当地泥头豺狼人营地间的污秽土壤中茂盛生长。豺狼人拼死守卫着这片领地。这些蘑菇的孢子和菌肉会毒害活物，带来剧痛，并使躯体迅速腐烂。"},{t="皇家药剂师学会的研究原料",b="在塔伦米尔，药剂师林度恩将泥头花用于化学实验。希尔瓦娜斯·风行者女士命令皇家药剂师学会研制一种瘟疫，将天灾军团和活着的人类一并消灭。这些蘑菇具有腐蚀性，能使血肉枯萎，因此成了林度恩配制苦楚药剂的基础原料。"}},faq={{q="泥头花是什么？",a="尽管名字里有个花字，泥头花却是一种硕大、气味刺鼻的毒蘑菇，生长在希尔斯布莱德丘陵的潮湿土壤中。",al={"泥头花背景故事","泥头花是花吗","泥头花是什么植物"}},{q="泥头花生长在哪里？",a="泥头花遍布奈杉德哨岗，这座废弃农庄位于塔伦米尔以南，流经南海镇的河流以东。大批泥头豺狼人盘踞在这一带。",al={"泥头花位置","哪里能找到泥头花","奈杉德哨岗蘑菇"}},{q="皇家药剂师学会为什么要收集它们？",a="塔伦米尔的药剂师林度恩需要泥头花来配制苦楚药剂。被遗忘者研究毒素，以协助研制能够消灭活人和天灾军团的瘟疫。",al={"林度恩为什么需要泥头花","苦楚药剂原料","药剂师林度恩蘑菇"}},{q="皇家药剂师学会用这些花做什么？",a="药剂师林度恩收集这些恶臭的蘑菇，用来配制下一种药剂，这是被遗忘者研究疾病与毒药的一部分。",al={"泥头花实验","泥头花药剂用途"}}},fx={f0998bd9={q="泥头花来自哪里？",a="泥头花是一种大型、气味恶臭的蘑菇，生长在希尔斯布莱德丘陵南部的奈杉德哨岗田野中。它们在当地泥头豺狼人居住的地方茁壮生长；豺狼人会凶狠地守护这片区域，不过它们究竟是有意栽培这些刺鼻的真菌，还是只是在其中筑巢，目前尚不确定。",al={"泥头花的来源","泥头花来自哪里","谁制作了泥头花"}}},fp="16,166,14.327.0,37.322.1,27.124.0,32.184.0,52.183.0,60.137.0"}
P.entries["item:mudsnout-composite"] = {n="泥头花药",s="在塔伦米尔，泥头花药被制备用于皇家药剂师学会对新型瘟疫的研究。药剂师林度恩用采自希尔斯布莱德丘陵的泥头花制成这种药膏，再将其送往幽暗城。",h="在塔伦米尔，泥头花药被制备用于皇家药剂师学会对新型瘟疫的研究。药剂师林度恩用采自希尔斯布莱德丘陵的泥头花制成这种药膏，再将其送往幽暗城。",kw={"炼金房","药剂师林度恩","苦楚药剂","大药剂师法拉尼尔","泥头花","泥头花药","皇家药剂师学会"},ang={["profession:Herbalism"]="作为一名草药师，你能看出药剂师如何将泥头花捣碎，制成武器。",["race:Undead"]="作为一名亡灵，每一批泥头花药都在为黑暗女王的命令效力：研制针对生者和Scourge的瘟疫，以确保被遗忘者的未来。"},sec={{t="腐烂的基础",b="药剂师林度恩用采自希尔斯布莱德丘陵的泥头花制成泥头花药。这种药膏本身就有毒，但大药剂师法拉尼尔必须将其与腐烂胶质混合，才能激发出更致命的毒性。这些原料共同构成了黑暗女王的苦楚药剂中的一种关键化学成分。"},{t="药剂师的往来",b="泥头花药从塔伦米尔运抵幽暗城后，由皇家药剂师学会在炼金房接收。野外研究人员在各地收集试剂，并将样本送往首都，交由大师们提炼。希尔瓦娜斯要求尽快取得对付活人和天灾军团的成果，而法拉尼尔称赞这种药膏构思精妙，为实现他们的目标奠定了基础。"}},faq={{q="泥头花药有什么用途？",a="泥头花药是一种用泥头花制成的药膏。大药剂师法拉尼尔在幽暗城用腐烂胶质处理这种药膏，用于配制苦楚药剂。",al={"泥头花药用途","泥头花药有什么作用"}},{q="是谁研制了这种药膏？",a="药剂师林度恩在希尔斯布莱德丘陵的塔伦米尔研制了这种药膏，将新鲜的花朵捣碎成膏，再送往北方。",al={"谁制作了泥头花药","泥头花药研制者"}},{q="大药剂师法拉尼尔为什么需要它？",a="大药剂师法拉尼尔需要这种药膏，用于皇家药剂师学会对新型瘟疫的研究。林度恩的药膏为他们研究致命毒素提供了草药基料。",al={"为什么送给法拉尼尔","法拉尼尔 泥头"}}},fp="18,193,16.326.0,25.385.1,40.176.0,26.148.0,44.174.0"}
P.entries["item:mudsnout-mixture"] = {n="泥头花水",s="在幽暗城，大药剂师法拉尼尔正在为被遗忘者的致命毒药调配基液。泥头花水的原料，是从塔伦米尔向北运来的蘑菇。",h="在幽暗城，大药剂师法拉尼尔正在为被遗忘者的致命毒药调配基液。泥头花水的原料，是从塔伦米尔向北运来的蘑菇。",kw={"药剂师","腐烂胶质","苦楚药剂","法拉尼尔","希尔斯布莱德","林度恩","泥头花水","幽暗城"},ang={["faction:Horde"]="作为身在塔伦米尔的部落冒险者，你兼任信使与外勤人员，携带有毒的混合药剂穿行于洛丹伦，帮助被遗忘者巩固在希尔斯布莱德的立足之地。",["race:Undead"]="身为亡灵，你能亲眼见识皇家药剂师学会如何施展冷酷的才智：将荒野中的材料提炼成用于杀死活人的化学武器。"},sec={{t="腐烂胶质",b="塔伦米尔的药剂师林度恩试图制造一种剧毒的新型生物武器。他将泥头花制成的泥头花药向北送往幽暗城。这些有毒的蘑菇生长在豺狼人的领地奈杉德哨岗。大药剂师法拉尼尔看出了泥头花药的潜力，加入了自己调制的腐烂胶质。由此制成的泥头花水性质不稳定。它能稳定蘑菇化合物，让其中的剧毒成分得以在丘陵地带进一步催化提炼。"},{t="催化痛苦",b="泥头花水需要关键的催化剂，才能让其中的污染成分发挥作用。法拉尼尔派信使带着这瓶药水、一瓶强效巨魔之血药剂、有毒的刺脊纳迦鳞片和碎鳍鱼人的眼睛返回塔伦米尔。药剂师林度恩用这些材料催化泥头花水，制成致命的苦楚药剂，这种标志性的毒药旨在让被遗忘者的活人敌人遭受毁灭。"}},faq={{q="泥头花水有什么用途？",a="泥头花水是苦楚药剂的化学基液。药剂师林度恩正在塔伦米尔完善这种实验性毒药，用来杀死被遗忘者的敌人。",al={"泥头花水用途","泥头花水有什么作用","泥头花水用法"}},{q="谁制造了泥头花水？",a="大药剂师法拉尼尔在幽暗城将自己调制的腐烂胶质加入未经处理的泥头花药，制成泥头花水。",al={"谁制造泥头花水","泥头花水制造者"}},{q="为什么需要豺狼人的身体部位？",a="泥头花水不需要豺狼人的任何身体部位。泥头花药的原料是泥头花，这种有毒的蘑菇生长在奈杉德哨岗，周围盘踞着泥头豺狼人。药剂师林度恩先将蘑菇混合制成泥头花药，再由法拉尼尔加入自己调制的腐烂胶质。",al={"为什么是泥头","豺狼人毒药背景"}},{q="如何激活泥头花水？",a="药剂师林度恩使用一瓶强效巨魔之血药剂，以及在希尔斯布莱德海岸收集的刺脊纳迦鳞片和碎鳍鱼人眼睛，激活其中尚未生效的污染成分。",al={"激活泥头花水","苦楚药剂材料"}}},fp="16,147,18.462.0,20.418.1,38.170.0,33.127.0,37.241.0,29.181.0"}
P.entries["item:murloc-head"] = {n="鱼人的头颅",s="在西部海岸，鱼人的头颅是令人不寒而栗的证物，证明南海镇正设法遏制的威胁。法尔林·奥里涅尔中尉为治安官雷德帕斯收集这些砍下的头颅，后者要求提供清剿鱼人的证据。",h="在西部海岸，鱼人的头颅是令人不寒而栗的证物，证明南海镇正设法遏制的威胁。法尔林·奥里涅尔中尉为治安官雷德帕斯收集这些砍下的头颅，后者要求提供清剿鱼人的证据。",kw={"法尔林·奥里涅尔","法尔林 的证据","希尔斯布莱德丘陵","治安官雷德帕斯","鱼人","鱼人的头颅","南海镇","西部海岸"},ang={["faction:Alliance"]="身为联盟的一员，清剿西部海岸有助于保护南海镇的渔业经济，并保障其在洛丹伦的海岸线安全。"},sec={{t="更骇人的证据",b="西部海岸的鱼人生性凶暴，直接威胁着南海镇的渔民和沿海旅人。联盟战士时常清剿海滩，但治安官Marcus Redpath要求先看到证据，才肯认可威胁有所减轻的报告。法尔林·奥里涅尔中尉雇用战士，让他们带回鱼人的头颅。法尔林对这份差事深感厌恶，眼前的景象让他对南海镇的海鲜也失去了胃口。"}},faq={{q="法尔林·奥里涅尔为什么要收集鱼人的头颅？",a="治安官马库斯·雷德帕斯需要实物证据，证明海滩上的鱼人已被清剿。法尔林·奥里涅尔中尉收集它们被砍下的头颅，以满足他的要求。",al={"法尔林 证据","为什么要鱼人的头颅","南海镇谁要鱼人的头颅"}},{q="这些鱼人在哪里出没？",a="这些鱼人出没于西部海岸，也就是希尔斯布莱德丘陵境内、南海镇以西的海岸。",al={"鱼人的头颅位置","希尔斯布莱德哪里能获得鱼人的头颅","西部海岸鱼人"}},{q="法尔林为什么如此厌恶它们？",a="法尔林觉得鱼人有违自然，令人作呕。它们被砍下的头颅让他恶心不已，以至于他连鱼都不肯吃了，而鱼正是南海镇的主食之一。",al={"法尔林 的反应","法尔林 吃鱼"}},{q="收集头颅能解决南海镇的鱼人问题吗？",a="这些头颅为治安官雷德帕斯提供了他要求的证据。他收下头颅，并派法尔林去应对东部海滩的威胁。",al={"鱼人会停止进攻吗","法尔林 任务链"}}},fx={ab7abae9={q="什么是鱼人的头颅？",a="这是在希尔斯布莱德丘陵海岸被杀死的鱼人那颗刚砍下的头颅。它冰冷、黏滑，还渗着恶臭的液体，是在保卫南海镇时斩杀怪物的确凿物证。",al={"鱼人的头颅是什么","鱼人的头颅信息","鱼人的头颅物品"}},["598cfa24"]={q="鱼人的头颅从哪里来？",a="它们是从南海镇以西、西部海岸出没的鱼人身上直接砍下来的。这些不是制作出来的物品，而是从侵扰联盟驻军的海岸掠袭者身上取得的血腥战利品。",al={"鱼人的头颅在哪里掉落","谁制造了鱼人的头颅","鱼人的头颅来源"}}},fp="11,228,24.399.0,43.164.0,30.100.0,35.155.0,60.131.0"}
P.entries["item:musquash-root"] = {n="麝鼠根",s="麝鼠根生长在湿地的巨石水坝下方。很少有人采集它，但暴风城地下一个隐秘的术士集会需要用它配制药剂。",h="麝鼠根生长在湿地的巨石水坝下方。很少有人采集它，但暴风城地下一个隐秘的术士集会需要用它配制药剂。",kw={"贵族的陈酿","维沙克公爵","麝鼠根","巨石水坝","蒂罗亚之泪","湿地","加尔德斯"},ang={["class:Warlock"]="作为已宰的羔羊地下的一名术士，你需要这种根来让多管闲事的贵族闭嘴，保护你在城中那处岌岌可危的庇护所。",["profession:Herbalism"]="作为草药师，你能看出巨石水坝瀑布下方的潮湿土壤如何滋养着奇异而危险的植物。"},sec={{t="稀有的材料",b="麝鼠根生长在巨石水坝瀑布下方的潮湿土壤中。那里雾气弥漫，位置偏僻，采集并不容易。很少有草药师寻找它，但研习黑暗法术的人十分看重它的化学和炼金特性。"},{t="术士的阴谋",b="黑爪加尔德斯身处暴风城地下的已宰的羔羊，正在寻求麝鼠根和蒂罗亚之泪。这些稀有植物将被配成一种不易察觉的药剂，用来对付维沙克公爵。他是贵族的成员，已经开始调查城中隐秘的术士集会。"}},faq={{q="哪里能找到麝鼠根？",a="麝鼠根生长在湿地的巨石水坝下方，就在瀑布底部。",al={"麝鼠根在哪里","麝鼠根位置","如何找到麝鼠根"}},{q="麝鼠根有什么用途？",a="黑爪加尔德斯想用麝鼠根和蒂罗亚之泪配制药剂，让维沙克公爵无暇他顾。他希望借此阻止维沙克推动对暴风城术士集会的调查。",al={"麝鼠根有什么作用","麝鼠根用途","为什么需要麝鼠根"}},{q="谁想要采集这种根？",a="黑爪加尔德斯指派人手取回麝鼠根。他是一名术士，身处暴风城法师区的已宰的羔羊下方的地下墓穴中。",al={"谁需要麝鼠根","麝鼠根任务发布者","谁索要麝鼠根"}},{q="维沙克公爵是谁？",a="维沙克公爵是暴风城贵族的成员。得知城中存在术士集会后，他开始敦促议会展开正式调查。",al={"维沙克是谁","维沙克公爵"}}},fx={["32cf7ee1"]={q="麝鼠根是什么？",a="麝鼠根是一种稀有植物，只生长在湿地巨石水坝下方的瀑布底部，那里水雾弥漫，潮湿异常。它以强效的天然特性闻名于黑暗药剂师和术士之间，与其他稀有植物混合后，可用作调制欺诈药剂和毒药的关键材料。",al={"麝鼠根是什么","麝鼠根背景","麝鼠根资料"}},d9341dd1={q="麝鼠根来自哪里，又是谁制造的？",a="麝鼠根是一种自然生长的植物，并非人工造物。它只在湿地繁茂生长，扎根于宏伟的巨石水坝正下方瀑布脚下潮湿的岩石和浸透水的土壤中。",al={"麝鼠根来源","麝鼠根生长在哪里","谁制造了麝鼠根"}}},fp="13,142,17.226.0,20.283.1,29.90.0,31.201.0,30.158.0,20.160.0"}
P.entries["item:mysterious-fossil"] = {n="神秘的化石",s="勘察员雷姆塔维尔在黑海岸沿岸发掘出了神秘的化石。探险者协会将它送往大洋彼岸进行研究。",h="勘察员雷姆塔维尔在黑海岸沿岸发掘出了神秘的化石。探险者协会将它送往大洋彼岸进行研究。",kw={"黑海岸","探险者协会","弗拉冈特","灰须","米奈希尔港","神秘的化石","雷姆塔维尔"},ang={["faction:Alliance"]="身为联盟的一员，你可以追寻这件遗物的转运路线，从黑海岸的野外斥候，一路追踪到达纳苏斯和米奈希尔港的学者。",["race:Dwarf"]="身为矮人，你可以将这块化石视为又一块缺失的拼图，帮助探险者协会探寻古老的泰坦传承与被遗忘的谜团。"},sec={{t="奇异的发现",b="勘察员雷姆塔维尔在黑海岸荒僻的海岸作业时，发掘出了一块不同寻常的化石。他安排将它交给矮人学者，而不是留在荒野之中。在达纳苏斯，首席考古学家杜瑟·灰须看出了这块来自卡利姆多岩石中的化石非同寻常。"},{t="跨越大洋的联系",b="首席考古学家杜瑟·灰须发现，这块化石与曾在铁炉堡的一次探险者协会集会上展出的一块罕见化石颇为相似。考古学家弗拉冈特研究过那块化石，并怀疑其中蕴藏着有待唤醒的力量。为了确认新化石的来历，并查明它可能蕴藏着什么，灰须将它送往大洋彼岸，交给正在米奈希尔港深水旅店等候的弗拉冈特。"}},faq={{q="神秘的化石是在哪里发现的？",a="勘察员雷姆塔维尔在黑海岸古老的北部海岸作业时，发现了神秘的化石。",al={"化石位置","发现地点","化石来源"}},{q="探险者协会为什么想要这块化石？",a="首席考古学家杜瑟·灰须看出了这块化石与考古学家弗拉冈特的研究之间的联系。弗拉冈特怀疑，这类化石可能蕴藏着可以被唤醒的力量。",al={"矮人为何想要化石","探险者协会 关注原因","化石用途"}},{q="考古学家弗拉冈特是谁？",a="考古学家弗拉冈特为探险者协会从事研究，曾研究过类似的石化遗物。他目前住在米奈希尔港的深水旅店，等待有人护送他前往湿地的维尔加挖掘场。",al={"弗拉冈特 是谁","弗拉冈特 位置","弗拉冈特 在哪里"}},{q="首席考古学家杜瑟·灰须是谁？",a="首席考古学家杜瑟·灰须是探险者协会驻达纳苏斯的高级代表。灰须负责监管矮人在卡利姆多北部各地的研究与考古工作。",al={"灰须","灰须 是谁","达纳苏斯矮人考古学家"}}},fp="17,134,19.267.0,21.388.1,38.104.0,48.171.0,31.232.0,39.182.0"}
P.entries["item:nak-s-skull"] = {n="纳克的颅骨",s="在南贫瘠之地，纳克率领钢鬃战团对抗部落。他的颅骨既是他败亡的证明，也让碎牙得以向背叛自己的昔日同族复仇。",h="在南贫瘠之地，纳克率领钢鬃战团对抗部落。他的颅骨既是他败亡的证明，也让碎牙得以向背叛自己的昔日同族复仇。",kw={"贫瘠之地","内部的背叛","陶拉祖营地","卡兹","洛克·奥克班恩","碎牙","纳克","纳克的颅骨","野猪人","钢鬃"},ang={["faction:Horde"]="身为部落的一员，你可以取下纳克这类钢鬃军阀的首级，减轻陶拉祖营地与十字路口之间补给线的压力。"},sec={{t="复仇的凭证",b="纳克、卡兹和洛克·奥克班恩从剃刀沼泽出发，率军在贫瘠之地各处发动袭击。他们的战团袭击部落的定居点和道路，而十字路口的守军尚不知道，这三名指挥官正在策划超出寻常部族冲突规模的攻势。在陶拉祖营地，被俘的钢鬃成员碎牙遭到族人遗弃，只能在牢笼中等死。如今，他一心要向昔日的同胞复仇。碎牙要求部落冒险者带回纳克及其同伙被割下的颅骨，作为他们已死的证明。他打算借此瓦解南方的劫掠队伍。"}},faq={{q="纳克是谁？",a="纳克是一名钢鬃野猪人指挥官，与卡兹和洛克·奥克班恩一同率军劫掠。这三人从剃刀沼泽出动，袭击南贫瘠之地各处的部落旅人和定居点。",al={"纳克是谁","纳克的背景故事","纳克 贫瘠之地"}},{q="谁想要纳克的颅骨？",a="碎牙想要纳克的颅骨，他是关押在陶拉祖营地的一名钢鬃野猪人俘虏。他遭到同族遗弃，一心要向背叛他的首领们复仇。",al={"谁想要颅骨","纳克的颅骨交给谁","碎牙 颅骨"}},{q="碎牙为什么想要同族的颅骨？",a="纳克、卡兹和洛克·奥克班恩抛弃了碎牙，任由他在囚禁中等死。为了报复，他帮助部落找到他们，并要求带回他们被割下的头颅，以证明他们已死。",al={"为何背叛自己的部族","碎牙的动机","碎牙为何想要颅骨"}},{q="收集纳克的颅骨有助于保护十字路口吗？",a="是的。碎牙说，纳克及其同伙指挥钢鬃袭击十字路口和中部商路。击败他们能削弱这个部族协同发动的攻势。",al={"十字路口的安全","阻止野猪人袭击"}}},fp="11,169,20.535.0,12.191.0,22.158.0,55.148.0,56.172.0"}
P.entries["item:nek-rosh-s-head"] = {n="纳克罗什的头颅",s="在湿地，纳克罗什的头颅证明了龙喉氏族酋长已被击杀。斯托菲队长收下了它，作为米奈希尔港所受威胁已被消除的证据。",h="在湿地，纳克罗什的头颅证明了龙喉氏族酋长已被击杀。斯托菲队长收下了它，作为米奈希尔港所受威胁已被消除的证据。",kw={"斯托菲队长","酋长","龙喉氏族","米奈希尔","纳克罗什","湿地"},ang={["faction:Alliance"]="对联盟而言，将纳克罗什的头颅交给斯托菲队长，有助于保卫米奈希尔港，使其免遭迫在眉睫的进攻，也能赢得铁炉堡王国的好感。",["race:Dwarf"]="身为矮人，你知道自Second War以来，龙喉氏族便一直为祸卡兹莫丹。带回这位酋长被斩下的头颅，能为沼泽地的守卫者伸张期盼已久的正义。"},sec={{t="决定性的一击",b="龙喉氏族氏族在沼泽地各处集结兵力和攻城武器，威胁着联盟港口米奈希尔港。氏族的投石车被烧毁后，港口的安危便取决于能否杀死纳克罗什酋长。他被斩下的头颅向斯托菲队长和铁炉堡当局证明，这位军阀对湿地的控制已被打破。"}},faq={{q="纳克罗什曾是谁？",a="纳克罗什曾是湿地龙喉氏族氏族残部的酋长。他指挥部队向附近的联盟领地发动袭击，开展战事。",al={"纳克罗什是谁","纳克罗什酋长","纳克罗什曾是谁"}},{q="谁想要纳克罗什的头颅？",a="斯托菲队长想要纳克罗什的头颅，以此证明这位酋长已被击杀。他负责指挥米奈希尔港的防御，并代表铁炉堡发放奖赏。",al={"谁收头颅","纳克罗什头颅交付","纳克罗什的头颅交到哪里"}},{q="为何要杀死纳克罗什？",a="纳克罗什指挥着威胁米奈希尔港的龙喉氏族部队。联盟力图摧毁氏族的攻城武器并杀死其酋长，以削弱该氏族在这一地区的势力。",al={"为何杀死纳克罗什","为何击败纳克罗什"}}},fx={e464fcda={q="什么是纳克罗什的头颅？",a="这是纳克罗什酋长被砍下的头颅。他是指挥湿地龙喉氏族的军阀。这颗头颅是令人毛骨悚然却无可辩驳的证据，证明铁炉堡山地卫兵在当地最大的敌人终于被杀死了。",al={"纳克罗什的头颅是什么","纳克罗什的头颅物品","纳克罗什被砍下的头颅"}},["160e4c8d"]={q="纳克罗什的头颅来自哪里？是谁制造的？",a="你在湿地的龙喉营地击败纳克罗什酋长后，可以从他身上直接取得这颗头颅。它不是制作或制造出来的，而是从倒下的兽人酋长身上砍下，作为战利品和他死讯的凭证。",al={"纳克罗什的头颅来自哪里","如何获得纳克罗什的头颅","纳克罗什的头颅来源"}},ce210494={q="斯托菲队长为什么要纳克罗什的头颅？",a="斯托菲队长需要无可辩驳的证据，证明龙喉氏族的首领已经倒下。纳克罗什已死，他们的战争投石车也已被摧毁，斯托菲知道龙喉氏族很难恢复元气，米奈希尔港和湿地终于可以免受有组织的袭击。",al={"斯托菲为什么要纳克罗什的头颅","他们为什么要纳克罗什的头颅","纳克罗什的头颅有什么用"}}},fp="15,176,17.341.0,17.130.0,26.160.0,36.191.0"}
P.entries["item:neru-fragment"] = {n="奈尔鲁碎片",s="奈尔鲁碎片从翻动过的泥土中出土，上面留有戈阿兹之石的一部分古老泰坦文字。这件遗物发现于湿地的维尔加挖掘场，其上的文字讲述了艾泽拉斯的远古历史。",h="奈尔鲁碎片从翻动过的泥土中出土，上面留有戈阿兹之石的一部分古老泰坦文字。这件遗物发现于湿地的维尔加挖掘场，其上的文字讲述了艾泽拉斯的远古历史。",kw={"挖掘","戈阿兹之石","松软的泥土","奈尔鲁碎片","勘察员维尔加","发现历史","湿地"},ang={["race:Dwarf"]="对探险者协会而言，找回奈尔鲁碎片这样的石板残片，是揭开Titan秘密、拼凑矮人起源的关键。"},sec={{t="戈阿兹之石的碎片",b="勘察员维尔加率领的矮人探险队发现了戈阿兹之石。这件遗物碎成了四块：阿度斯、莫德、高尔姆和奈尔鲁。迅猛龙占据了挖掘场，迫使挖掘工作停顿，奈尔鲁碎片则仍埋在这些凶猛野兽之间的松软泥土下。找回它后，便能将它与其他碎片拼合，复原石板。碎片上留存的文字提及一项神圣的计划和一个注定无法实现的预言，为矮人学者提供了一份有待破译的记录。"},{t="解读复原的石板",b="集齐全部四块碎片后，勘察员维尔加复原了戈阿兹之石，并继续翻译上面的泰坦文字。如今可以辨认的文字讲述了被锁在大地之下的上古之神。"}},faq={{q="奈尔鲁碎片是什么？",a="奈尔鲁碎片是从一件更大的遗物——戈阿兹之石上碎裂下来的一块古老石片。矮人探险队在湿地发掘出了它，随后迅猛龙便占据了挖掘场。",al={"奈尔鲁碎片背景故事","奈尔鲁碎片是什么","奈尔鲁石板碎片"}},{q="在哪里能找到这块碎片？",a="奈尔鲁碎片散落在湿地米奈希尔港以东的维尔加挖掘场。它通常埋在松软的泥土下，或藏在废弃的文物之间。",al={"哪里能找到奈尔鲁碎片","奈尔鲁碎片位置","如何获得奈尔鲁碎片"}},{q="集齐全部四块碎片后会发生什么？",a="集齐全部四块碎片后，勘察员维尔加会重新拼合戈阿兹之石，并继续翻译上面的泰坦文字，追寻残存文字所暗示的谜团。",al={"完整的戈阿兹之石","戈阿兹之石上写了什么","发现历史结局"}}},fx={["1f660d59"]={q="奈尔鲁碎片来自哪里？是谁制造的？",a="这块碎片来自在湿地维尔加挖掘场出土的古老戈阿兹之石。石上的铭文使用泰坦文字，但现存的任务文本并未说明它的制作者。",al={"奈尔鲁碎片的来源","谁制造了奈尔鲁碎片","奈尔鲁碎片来自哪里"}},b6f45f31={q="勘察员维尔加为什么需要奈尔鲁碎片？",a="勘察员维尔加刚发掘出戈阿兹之石，挖掘场就被迅猛龙攻陷了；他发现铭文有四处明显断裂。他急需奈尔鲁碎片和另外三块残片来拼合石板，继续解读其中关于神圣计划和注定覆灭的预言。",al={"为什么要寻找奈尔鲁碎片","维尔加为什么需要奈尔鲁碎片","奈尔鲁碎片的用途"}}},fp="13,161,23.442.0,27.190.1,26.162.0,28.175.0,50.193.1"}
P.entries["item:nessa-s-collection"] = {n="尼莎的货物",s="在鲁瑟兰村，从附近水域收集的鱼骨和鱼鳞正被整理好，准备交给奥伯丁的莱尔德研究。尼莎的货物展现了泰达希尔根部周围水生生物的庞大体形。",h="在鲁瑟兰村，从附近水域收集的鱼骨和鱼鳞正被整理好，准备交给奥伯丁的莱尔德研究。尼莎的货物展现了泰达希尔根部周围水生生物的庞大体形。",kw={"奥伯丁","鱼骨","莱尔德","尼莎·影歌","尼莎的货物","鲁瑟兰村","泰达希尔","维斯派塔斯"},ang={["race:NightElf"]="身为暗夜精灵，你可以通过这批货物，了解泰达希尔周围的水域与大陆水域有何不同。"},sec={{t="世界之树的馈赠",b="尼莎·影歌住在泰达希尔底部的鲁瑟兰村，她在那里收集鱼骨和鱼鳞，以比较岛屿与卡利姆多大陆的海洋生物。巨树周围水域的鱼长得格外硕大。尼莎将实物证据送过海，交给奥伯丁码头一带的鱼商莱尔德。包裹经由鲁瑟兰的角鹰兽管理员维斯派塔斯转运，为泰达希尔日益旺盛的生命力提供了切实的证据。"},{t="奇妙的对比",b="在黑海岸，莱尔德发现这些标本的尺寸远超大陆上的同类。这批货物中的颌骨，大小几乎是黑海岸沿岸本地鱼类颌骨的两倍，鱼鳞则有紧握的拳头那么大。对沿海的暗夜精灵而言，这个包裹清楚地展现了泰达希尔周围的水域与卡利姆多北部阴沉海岸之间的巨大差异。"}},faq={{q="尼莎的货物里有什么？",a="这批货物里有鱼骨和鱼鳞，其中颌骨的大小几乎是黑海岸沿岸本地鱼类颌骨的两倍，鱼鳞则有紧握的拳头那么大。这些鱼捕自鲁瑟兰村周围的水域。",al={"尼莎的货物内容","包裹里有什么","鱼骨包裹"}},{q="这批货物要送给谁？",a="尼莎将这批货物寄给莱尔德，他是在黑海岸奥伯丁码头一带卖鱼的暗夜精灵商贩。",al={"尼莎的货物送给谁","莱尔德是谁","递送目的地"}},{q="尼莎为什么收集这些鱼类标本？",a="尼莎收集这些标本，是为了将泰达希尔周围生长旺盛的大鱼与卡利姆多大陆的海洋生物作比较。",al={"为什么寄鱼骨","尼莎的鱼类对比","泰达希尔物产丰饶的原因"}},{q="这批货物如何运抵奥伯丁？",a="你将包裹带给鲁瑟兰的角鹰兽管理员维斯派塔斯，由他安排将包裹运过海，送到奥伯丁交给莱尔德。",al={"如何递送","维斯派塔斯递送","角鹰兽包裹"}}},fx={["6bde19ac"]={q="什么是尼莎的货物？",a="尼莎的货物是一包从鲁瑟兰村周边水域收集来的鱼骨和鱼鳞。它展现了泰达希尔世界之树根部繁盛的奇特海产，并被妥善包装，准备运过海洋送往卡利姆多大陆。",al={"尼莎的货物是什么","尼莎的货物","尼莎的货物物品"}},eb414ab6={q="尼莎的货物来自哪里？是谁收集的？",a="这批货物由居住在泰达希尔南部山脚下鲁瑟兰村的暗夜精灵尼莎·影歌收集。当地岛民渔夫捕获的鱼类个头大得惊人，她从中挑选了珍贵的标本，准备运往海外。",al={"谁收集了尼莎的货物","尼莎的货物来自哪里","尼莎货物的来源"}},d01c5154={q="谁需要尼莎的货物？",a="奥伯丁一位名叫莱尔德的鱼贩正等着这些标本，好对它们进行研究。尼莎希望将鲁瑟兰村渔获惊人的体型与活力同大陆上的鱼类作比较，而莱尔德也很想检查那些尺寸是平常两倍的颌骨，以及有拳头那么大的鳞片。",al={"莱尔德为什么要尼莎的货物","为什么要运送尼莎的货物","尼莎货物的用途"}}},fp="18,132,24.419.0,20.355.0,34.237.0,36.98.0,42.120.0,40.145.0"}
P.entries["item:nether-gem"] = {n="虚空宝石",s="虚空宝石将澈水湖上一位神秘人物的影像传过提瑞斯法林地，送到幽暗城的比索·埃斯沙德面前。两人之间有何联系，等待你去揭晓。",h="虚空宝石将澈水湖上一位神秘人物的影像传过提瑞斯法林地，送到幽暗城的比索·埃斯沙德面前。两人之间有何联系，等待你去揭晓。",kw={"比索·埃斯沙德","澈水湖","冈瑟尔·阿坎努斯","虚空宝石","流浪的巫妖","幽暗城"},ang={["class:Mage"]="身为法师，你能看出奥术大师如何借助魔法占卜和投射的影像跨越遥远的距离，免去旅途中的风险。",["race:Undead"]="身为亡灵，你知道宝石的送达标志着被遗忘者的一次外交胜利，让冈瑟尔·阿坎努斯成为对抗Scourge和血色十字军的强大盟友。"},sec={{t="奥术传讯的媒介",b="冈瑟尔·阿坎努斯在澈水湖中的孤岛上打造了虚空宝石，或为它施加了魔法。他凭自己的意志摆脱了巫妖王的控制，却因心存猜疑，与新生的被遗忘者国度保持距离。遗失的法术书归还后，冈瑟尔将宝石交给一位使者，以示善意。在幽暗城的魔法区顶部，比索·埃斯沙德将魔力注入宝石。冈瑟尔的魔法影像出现在法师公会领袖面前，让两位法师得以跨越提瑞斯法林地交谈。这次会面为冈瑟尔效忠希尔瓦娜斯并加入被遗忘者铺平了道路。"}},faq={{q="虚空宝石有什么作用？",a="虚空宝石让冈瑟尔·阿坎努斯能够与比索·埃斯沙德远距离交流。当比索在幽暗城将魔力注入宝石时，冈瑟尔的虚幻影像便会显现，让两位法师能够直接交谈。",al={"虚空宝石用途","什么是虚空宝石","虚空宝石有什么作用"}},{q="谁制作了虚空宝石？",a="冈瑟尔·阿坎努斯提供了虚空宝石。他住在澈水湖中的一座岛上，遗失的法术书归还后，他将宝石交给一位使者，托其带给老战友比索。",al={"谁制作了虚空宝石","虚空宝石来自哪里","冈瑟尔宝石"}},{q="虚空宝石对被遗忘者为何意义重大？",a="虚空宝石帮助冈瑟尔·阿坎努斯加入了被遗忘者。他不信任其他亡灵，担心他们仍是天灾军团的奴仆，但宝石让他得以与比索·埃斯沙德重建联系，并向希尔瓦娜斯宣誓效忠。",al={"虚空宝石为何重要","冈瑟尔 被遗忘者","被遗忘者虚空宝石"}}},fp="10,160,29.595.1,28.211.0,27.175.1,50.228.1"}
P.entries["item:ng-5"] = {n="NG-5",s="在石爪山脉，加克希姆·尘链需要用NG-5来实施他的爆破计划。这种性质不稳定的化学品名为硝酸甘油炸药，是他引爆满载炸药的货车、制造混乱以分散敌人注意力所需的引燃剂。",h="在石爪山脉，加克希姆·尘链需要用NG-5来实施他的爆破计划。这种性质不稳定的化学品名为硝酸甘油炸药，是他引爆满载炸药的货车、制造混乱以分散敌人注意力所需的引燃剂。",kw={"炸药","爆炸物","加克希姆·尘链","侏儒","ng-5","ng5","硝酸甘油炸药","石爪山"},ang={["profession:Engineering"]="工程师们会认出，NG-5就是硝酸甘油炸药，一种性质不稳定的化学催化剂。当普通黑火药的威力不足以用于重型军械时，工匠们便格外看重它。",["race:Gnome"]="身为侏儒，你或许能体会这种冒险巧思：用不稳定的化学品引爆整车整车的炸药，仅仅是为了分散敌人的注意力。"},sec={{t="不稳定的试剂",b="加克希姆·尘链是石爪山脉的一名侏儒特工，他的工程计划需要用到NG-5。这种化合物的正式名称是硝酸甘油炸药，是一种危险的化学溶液，需要小心处理——或者凭着侏儒那股不顾后果的热情放手一试。加克希姆说，它能提供引爆整车炸药所需的反应，制造巨大的爆炸，分散他在这一带的对手的注意力。"}},faq={{q="NG-5是什么？",a="NG-5是硝酸甘油炸药的简称，这种化学品极不稳定，在高级爆破和侏儒工程学中用作引燃试剂。",al={"ng5是什么","硝酸甘油炸药是什么","ng 5物品"}},{q="谁需要NG-5，用来做什么？",a="加克希姆·尘链是石爪山脉的一名侏儒工程师，他需要用NG-5作为引燃剂，引爆几辆装满炸药的货车，以此分散敌人的注意力。",al={"谁需要ng-5","加克希姆·尘链ng-5","为什么要获取ng5"}},{q="处理NG-5危险吗？",a="处理NG-5极其危险。供应商警告送货人务必万分小心，还开玩笑说，谁要不是加克希姆的盟友，多半会把自己炸得粉身碎骨。",al={"ng5安全吗","ng-5爆炸物","ng5会爆炸吗"}}},fx={["43a87313"]={q="NG-5来自哪里？是谁制造的？",a="NG-5又名硝基甘油醚，是从加克希姆·尘链的一位熟人那里取得的；此人专门调制特殊化合物。它是一种极不稳定的炼金混合物，专为爆炸反应调制。对方交出药剂时再三警告：毫无戒心的信使很容易被炸得粉身碎骨。",al={"谁制造了ng-5","在哪里可以获得ng-5","ng-5的制造者"}}},fp="4,190,18.319.0,13.115.0,23.170.0,28.183.0"}
P.entries["item:nida-s-necklace"] = {n="希拉里的项链",s="在湖畔镇，希拉里正在寻找她遗失在止水湖里的项链。那是她年幼时父亲送给她的礼物，她和其他孩子在码头边钓鱼时，项链滑落，沉入了水中。",h="在湖畔镇，希拉里正在寻找她遗失在止水湖里的项链。那是她年幼时父亲送给她的礼物，她和其他孩子在码头边钓鱼时，项链滑落，沉入了水中。",kw={"喵喵","闪光的淤泥","希拉里","止水湖","湖畔镇","妮达","妮达的项链","赤脊山","肖恩"},ang={["faction:Alliance"]="湖畔镇的守卫面临着周边地区的威胁。途经此地的联盟冒险者可以帮助当地的孩子找回遗失的纪念物。"},sec={{t="遗落湖底",b="希拉里和朋友肖恩在湖畔镇的岸边钓鱼时，弄丢了项链。那是父亲送给她的礼物，她十分珍惜。湖水深处栖息着凶猛的野兽和好斗的鱼人，所以当地的孩子们都待在码头上。项链仍在水下，埋在湖底的淤泥里。"}},faq={{q="这条项链是谁的？",a="项链的主人是希拉里，一个住在赤脊山湖畔镇的小女孩。那是她父亲送给她的。",al={"项链的主人","妮达项链主人","这是谁的项链","希拉里项链主人"}},{q="项链是怎么掉进止水湖的？",a="希拉里和肖恩在水边钓鱼时，项链滑落，沉入了止水湖。",al={"怎么掉进湖里的","项链为什么在水里","项链怎么丢的"}},{q="孩子们为什么不潜下去找回项链？",a="家长们不许孩子在止水湖里游泳。湖水深处栖息着危险的掠食者和好斗的鱼人，威胁着镇上的居民。",al={"妮达为什么不游泳去找","肖恩为什么拿不到项链","希拉里为什么不游泳去找"}},{q="喵喵是谁？",a="喵喵是希拉里的宠物猫。这只猫在湖畔镇陪伴着她，和小主人一起迎接项链的归来。",al={"小猫是谁","妮达的猫","希拉里的猫"}}},fx={a22bd4db={q="希拉里的项链是从哪里来的？",a="这条项链是希拉里父亲送给她的礼物。它虽没有多少历史或魔法价值，却是送给湖畔镇一名小女孩的珍贵传家纪念物。",al={"谁制造了希拉里的项链","希拉里的项链来自哪里","谁把项链送给了希拉里"}},["14f3017c"]={q="为什么有人在寻找希拉里的项链？",a="希拉里在止水湖的码头附近钓鱼时弄丢了项链。她的父母不许孩子潜入怪物横行的湖水中，因此她的朋友肖恩请路过的冒险者冒险潜入湖底，替她找回这件珍贵的纪念品。",al={"为什么要找希拉里的项链","谁想要希拉里的项链","希拉里为什么想找回项链"}}},fp="17,165,18.314.0,33.106.0,46.102.0,47.157.0,14.120.0"}
P.entries["item:nightmare-shard"] = {n="噩梦碎片",s="哀嚎洞穴中的一块发光的碎片带着污染，令菲拉·古风无法坐视。她将其中纯净却受扰的翡翠梦境精华封入噩梦碎片，并将它送交资深德鲁伊，传递一个不向外人透露的警讯。",h="哀嚎洞穴中的一块发光的碎片带着污染，令菲拉·古风无法坐视。她将其中纯净却受扰的翡翠梦境精华封入噩梦碎片，并将它送交资深德鲁伊，传递一个不向外人透露的警讯。",kw={"翡翠梦境","菲拉·古风","发光的碎片","哈缪尔·符文图腾","在噩梦中","玛斯雷·驭熊者","噩梦碎片","哀嚎洞穴"},ang={["class:Druid"]="对德鲁伊而言，碎片揭示了翡翠梦境已遭到腐化侵扰。它证实了他们对哀嚎洞穴中纳拉雷克斯命运的担忧。",["faction:Horde"]="对部落旅者而言，碎片将严峻的消息带到了雷霆崖的长者高地。哈缪尔·符文图腾正在那里努力巩固牛头人在更广泛的塞纳里奥同道中的地位。"},sec={{t="腐化的幻象",b="在哀嚎洞穴深处，菲拉·古风检查了一块神秘的发光的碎片，发现它的能量比预想的更加黑暗。它映照出翡翠梦境中一种非自然的病变，犹如清醒时的噩梦。菲拉·古风将这股受污染的精华封入噩梦碎片，命人立即将它送往塞纳里奥议会的资深领袖手中。"},{t="秘而不宣的凶兆",b="当噩梦碎片送到长者高地的大德鲁伊哈缪尔·符文图腾或达纳苏斯的玛斯雷·驭熊者手中时，他们凝视碎片深处，都感到惊骇。那幻象令他们不安，也证实了他们暗中的疑虑：梦境内部出了极其严重的问题。德鲁伊们担心引起民众恐慌，于是收下碎片，并告诫信使不要再谈起所见之事。"}},faq={{q="噩梦碎片是什么？",a="菲拉·古风检查了一块从哀嚎洞穴带回的发光的碎片后，将噩梦碎片托付给一名信使。它蕴含着纯净却受扰的翡翠梦境精华，呈现出的却是黑暗、腐化的幻象，而非平和的自然能量。",al={"噩梦碎片是什么","噩梦碎片背景故事"}},{q="谁制造了噩梦碎片？",a="菲拉·古风检查了一块从哀嚎洞穴带回的发光的碎片后，将噩梦碎片交给一名信使。她辨认出其中的腐化，嘱咐信使将它直接送交资深德鲁伊研究。",al={"谁制造了噩梦碎片","碎片来自哪里"}},{q="德鲁伊领袖为何对此如此惊恐？",a="凝视碎片时，哈缪尔·符文图腾和玛斯雷·驭熊者看到了一个扭曲翡翠梦境的噩梦。他们担忧危险将至，也怕引起民众恐慌，于是禁止继续议论此事，只让塞纳里奥议会的资深成员知晓。",al={"哈缪尔为何担忧","玛斯雷为何藏起碎片"}},{q="碎片需要送到哪里？",a="部落冒险者受命将碎片送往雷霆崖长者高地，交给大德鲁伊哈缪尔·符文图腾。联盟旅者则将它交给达纳苏斯塞纳里奥议会的玛斯雷·驭熊者。",al={"碎片交给谁","噩梦碎片交付"}}},fp="15,214,18.327.0,12.369.1,28.241.0,32.186.0,43.240.1,42.205.0"}
P.entries["item:nightsaber-fang"] = {n="夜刃豹的牙齿",s="在泰达希尔，猎人从游荡于林间的夜刃豹身上取下獠牙。林地居民也会寻找这些牙齿，用作施法材料。",h="在泰达希尔，猎人从游荡于林间的夜刃豹身上取下獠牙。林地居民也会寻找这些牙齿，用作施法材料。",kw={"多兰纳尔","獠牙","夜刃豹","施法材料","萨特","泰达希尔","赛恩·腐蹄"},ang={["class:Hunter"]="身为猎人，你在荒野中猎杀夜刃豹，取下它的獠牙，以此证明自己的技艺。将它身体的部分交给腐化的林地之灵，会扭曲狩猎的精神。",["race:NightElf"]="身为暗夜精灵，你知道夜刃豹是备受珍视的伙伴，也是Elune的象征。为了一个奸诈的萨特而猎杀这些神圣的掠食者，会带来耻辱。"},sec={{t="狩猎的战利品",b="夜刃豹在泰达希尔的树冠下捕猎，是卡利姆多北部最致命的天然掠食者之一。暗夜精灵敬重它们的敏捷、凶猛，以及它们与艾露恩之间深厚的灵魂纽带。猎人杀死夜刃豹后，可以取下它锋利的獠牙，作为自身技艺的证明。森林中的某些家伙则搜寻这些獠牙，用于更为黑暗的仪式。"},{t="萨特的施法材料",b="在多兰纳尔外，萨特赛恩·腐蹄专挑热心却缺乏经验的旅人下手。他声称需要林地中的施法材料，说服初来乍到的人去收集夜刃豹的牙齿、巨翼枭的羽毛和蜘蛛丝。交出这些材料就是在帮助这个骗子，而他会在天真的英雄交货时公然嘲笑他们。"}},faq={{q="夜刃豹的牙齿从哪里来？",a="夜刃豹的牙齿来自游荡于泰达希尔的掠食者夜刃豹，尤其是多兰纳尔周围森林中的夜刃豹。",al={"夜刃豹的牙齿获取地点","谁掉落夜刃豹的牙齿","夜刃豹的牙齿来源"}},{q="泰达希尔有谁想要夜刃豹的牙齿？",a="多兰纳尔外的萨特赛恩·腐蹄会请过往的冒险者为他带来夜刃豹的牙齿。",al={"谁需要夜刃豹的牙齿","夜刃豹的牙齿交给谁","谁收购夜刃豹的牙齿"}},{q="赛恩·腐蹄为什么想要夜刃豹的牙齿？",a="赛恩声称，他在森林中的工作需要用动物身体的部分作为施法材料，却对工作的性质守口如瓶，并以欺骗轻信的旅人为乐。",al={"赛恩为什么要牙齿","赛恩·腐蹄的施法材料用途","赛恩的委托动机"}},{q="除了牙齿，赛恩还要哪些施法材料？",a="除了两颗夜刃豹的牙齿，赛恩还要两根巨翼枭的羽毛和两片树林蜘蛛丝。",al={"赛恩还需要什么","赛恩的委托物品","赛恩需要的其他施法材料"}}},fp="15,118,18.331.0,17.310.1,36.115.0,41.98.0,45.138.1,58.112.0"}
P.entries["item:nissa-s-remains"] = {n="妮萨的残骸",s="妮萨的残骸属于一位贵族女子，她出身于提瑞斯法林地北部曾经富甲一方的阿加曼德家族。尼莎和家人在第三次大战期间惨遭杀害，沦为天灾军团麾下毫无心智的仆从，如今正被昔日的劳工追猎，以报血仇。",h="妮萨的残骸属于一位贵族女子，她出身于提瑞斯法林地北部曾经富甲一方的阿加曼德家族。尼莎和家人在第三次大战期间惨遭杀害，沦为天灾军团麾下毫无心智的仆从，如今正被昔日的劳工追猎，以报血仇。",kw={"阿加曼德磨坊","布瑞尔","库勒曼·法席恩","阿加曼德家族","妮萨·阿加曼德","妮萨的残骸","提瑞斯法林地"},ang={["faction:Horde"]="消灭复生的阿加曼德家族并清剿他们的磨坊，有助于肃清威胁布瑞尔和幽暗城的Scourge残余，保卫提瑞斯法林地北部。",["race:Undead"]="对被遗忘者而言，夺回提瑞斯法意味着清除昔日奴役他们的Scourge，以及那些因愚蠢的傲慢而让普通劳工沦为亡灵的富有贵族。"},sec={{t="傲慢的遗祸",b="第三次大战之前，阿加曼德家族是提瑞斯法林地最富有、最有权势的家族。他们兴旺的磨坊遍布北部丘陵。当亡灵瘟疫席卷洛丹伦时，家族的族长们拒绝逃离。他们加固庄园，并说服家臣和劳工留下抵抗。他们的傲慢让他们付出了生命的代价。天灾军团杀死了阿加曼德家族，随后又将他们复活，变成受巫妖王意志支配、毫无心智的奴仆。"},{t="刻骨的复仇",b="在布瑞尔，那些后来在希尔瓦娜斯·风行者女王麾下挣脱控制的幸存者，依然记得阿加曼德家族那致命的傲慢。库勒曼·法席恩曾是他们磨坊中的劳工，他痛恨昔日的主人，因为他们诱使工人沦为了亡灵。他委托冒险者消灭复生的阿加曼德家族，并带回他们的遗骸，其中也包括妮萨的残骸。对法席恩和其他被遗忘者而言，摧毁这些遗物，能让他们在复仇中获得一丝阴郁的解脱。"}},faq={{q="妮萨·阿加曼德是谁？",a="妮萨·阿加曼德出身于贵族阿加曼德家族，这个家族拥有提瑞斯法林地规模庞大的阿加曼德磨坊。当天灾军团席卷洛丹伦时，她与亲族一同死去，随后被复活，成为受巫妖王控制的亡灵爪牙。",al={"尼莎是谁","尼莎的故事","妮萨·阿加曼德"}},{q="库勒曼·法席恩为什么想要妮萨的残骸？",a="库勒曼·法席恩生前在阿加曼德家族的磨坊工作。他痛恨这个家族，因为他们拒绝逃离，还说服忠心的工人留下送死。收集这个家族的遗骸，让他得以向昔日的主人复仇。",al={"库勒曼为何想要遗骸","为何杀死阿加曼德家族","库勒曼·法席恩的动机"}},{q="这些遗骸在哪里收集？",a="妮萨·阿加曼德出没于提瑞斯法林地北部已成废墟的阿加曼德磨坊。她与复生的亲族和毫无心智的天灾军团奴仆一起，在破败的农舍间游荡。",al={"尼莎在哪里","妮萨·阿加曼德的位置"}},{q="尼莎像被遗忘者一样保有自由意志吗？",a="没有。与挣脱巫妖王控制的被遗忘者不同，尼莎和家人依然是毫无心智的亡灵，受天灾军团奴役。他们没有幽暗城居民所拥有的自主意识与自由。",al={"尼莎是被遗忘者吗","尼莎有自由意志吗","尼莎属于天灾军团吗"}}},fp="15,240,17.460.0,18.437.0,22.243.0,47.228.0,33.176.0,49.195.0"}
P.entries["item:nitroglycerin"] = {n="硝化甘油",s="在巴尔莫丹，硝化甘油帮助矮人在牛头人的土地上推进挖掘。他们的士兵和军官随身携带这种不稳定的化学品，而它也能用来对付这座堡垒。",h="在巴尔莫丹，硝化甘油帮助矮人在牛头人的土地上推进挖掘。他们的士兵和军官随身携带这种不稳定的化学品，而它也能用来对付这座堡垒。",kw={"巴尔莫丹","巴尔丹","贫瘠之地","炸药","加恩·石塔","硝化甘油","加恩的报复"},ang={["profession:Engineering"]="工程师知道，硝化甘油是一种用于配制炸药的爆炸物。木浆能吸收它，硝酸钠则有助于使它保持稳定并能够引爆。",["race:Tauren"]="身为牛头人，你知道巴尔莫丹周围那些不稳定的化学品，是石塔部族遭受毁灭的痛苦印记。"},sec={{t="工业爆破",b="巴尔莫丹的矮人用重型钻机和不稳定的化学品挖掘石塔牛头人的祖地。在挖掘场和设防的要塞里，他们随时备着硝化甘油，用来炸开深坑、崩裂山丘。随着挖掘继续，士兵和军官都随身携带着装有这种液体的小瓶，塞瑞克·黑炉公爵也不例外。"},{t="以其人之道还治其人之身",b="勘察员卡兹戈姆死后，加恩·石塔决心摧毁这座侵占族人土地的堡垒。这位流离失所的牛头人勇士研究了矮人的工程图纸，得知硝化甘油与木浆、硝酸钠混合后，能制成威力足以打击巴尔莫丹驻军的炸药。"}},faq={{q="硝化甘油从哪里来？",a="南贫瘠之地巴尔莫丹的矮人部队携带着硝化甘油，包括巴尔丹士兵、火枪手、军官，以及要塞中的塞瑞克·黑炉公爵。",al={"哪里能找到硝化甘油","谁掉落硝化甘油","硝化甘油来源"}},{q="硝化甘油有什么用途？",a="加恩·石塔将硝化甘油与木浆、硝酸钠混合，制成威力强大的炸药，用来对付巴尔莫丹的军事堡垒。",al={"硝化甘油有什么用","硝化甘油用途","加恩的报复材料"}},{q="矮人最初为什么要携带它？",a="巴尔莫丹的勘探者和驻军使用炸药、蒸汽机和不稳定的化学品，在考古挖掘场破开地层。",al={"矮人为什么携带硝化甘油","巴尔莫丹炸药"}},{q="加恩·石塔是谁？",a="加恩·石塔是一位被放逐的牛头人战士，矮人修建巴尔莫丹的挖掘场和要塞时，以工业手段大肆破坏，将他的部族赶出了祖地。",al={"加恩是谁","加恩·石塔"}}},fp="13,181,21.348.0,29.333.1,35.166.0,35.138.0,52.142.0,23.199.0"}
P.entries["item:nondescript-letter"] = {n="笔迹潦草的信件",s="卡尔文·蒙泰古从丧钟镇向东寄出一封笔迹潦草的信件，收信人是布瑞尔的旅店老板瑞尼。他把信交给刚刚苏醒的被遗忘者，让他们借此离开山谷，前往恐惧之末旅店。",h="卡尔文·蒙泰古从丧钟镇向东寄出一封笔迹潦草的信件，收信人是布瑞尔的旅店老板瑞尼。他把信交给刚刚苏醒的被遗忘者，让他们借此离开山谷，前往恐惧之末旅店。",kw={"潜行者的交易","布瑞尔","卡尔文·蒙泰古","丧钟镇","旅店老板瑞尼","笔迹潦草的信件","瑞尼"},ang={["class:Rogue"]="在潜行者看来，卡尔文·蒙泰古鬼鬼祟祟的举止和瑞尼骤然转变的态度，暗示着阴谋与地下势力之间的暗语传信。",["race:Undead"]="作为刚刚复生的被遗忘者，送这封信让你早早有了离开丧钟镇、探索提瑞斯法林地各处聚落的理由。"},sec={{t="信使的差事",b="卡尔文·蒙泰古请丧钟镇附近刚刚复生的被遗忘者将一个没有标记的信封送往东边的布瑞尔。他声称自己与僵尸和蜘蛛战斗，已经疲惫不堪，还说这封信是给一位名叫瑞尼的旅店老板的。他许下丰厚报酬的承诺，听起来却像句空话，而这趟差事让旅人走出山谷，前往恐惧之末旅店。"},{t="可疑的书信",b="旅店老板瑞尼起初装作这封信带来了好消息，寄信的是她住在丧钟镇、如圣人般善良的母亲。发现信使没有上当后，她便收起笑脸，露出不耐烦的神色。她一把夺过信，不肯透露寄信人和信中内容，还命令送信人离开，除非对方打算付钱住店。"}},faq={{q="笔迹潦草的信件是什么？",a="笔迹潦草的信件是一个普通、没有标记的信封，由卡尔文·蒙泰古在丧钟镇交给刚刚苏醒的被遗忘者，请他们送给布瑞尔的旅店老板瑞尼。",al={"笔迹潦草的信件","这封信是什么","卡尔文的信"}},{q="谁寄出了这封信，又由谁接收？",a="卡尔文·蒙泰古在丧钟镇将信交给信使。收信人是布瑞尔恐惧之末旅店的旅店老板瑞尼。",al={"谁寄的信","谁收信","寄信人"}},{q="信里究竟写了什么？",a="信中的内容始终没有公开。当你询问时，旅店老板瑞尼便收起那副欢快的假面孔，怒气冲冲地说，这封信的来历和内容都与你无关。",al={"信里写了什么","信件内容","能否阅读信件"}},{q="卡尔文·蒙泰古为什么要找人送信？",a="卡尔文声称自己忙于对付当地的僵尸和蜘蛛，无暇亲自送信。这趟送信的差事让旅人走出丧钟镇，也让他们认识布瑞尔的旅店和休憩之所。",al={"为什么寄信","卡尔文的动机","为什么去布瑞尔"}}},fp="18,205,18.327.0,25.323.1,31.146.0,42.131.0,34.163.0,43.190.0"}
P.entries["item:nori-s-mug"] = {n="诺里斯的杯子",s="在丹莫罗，诺里斯·激流托人将一杯 晨酒 送往安威玛尔。旅人将饮料送到德南·弗卡特手中，再把空杯子还给主人。",h="在丹莫罗，诺里斯·激流托人将一杯 晨酒 送往安威玛尔。旅人将饮料送到德南·弗卡特手中，再把空杯子还给主人。",kw={"把杯子带回来","丹莫罗","德南·弗卡特","晨酒","诺里斯·激流","诺里斯的杯子"},ang={["race:Dwarf"]="身为矮人，你知道在丹莫罗的暴风雪中，一杯热饮能让人暖和起来。诺里斯盼着你把他的杯子带回来。"},sec={{t="信使归来",b="诺里斯·激流借出自己的杯子，让旅人带着它穿过丹莫罗冰冷的山隘。杯中装着热腾腾的 晨酒，要送给安威玛尔的德南·弗卡特，让他喝下后暖暖身子，抵御严寒。德南喝完后，杯子便要送还给诺里斯。他提醒旅人，杯子可不是树上长出来的，并盼着拿回自己结实的酒杯。"}},faq={{q="诺里斯的杯子有什么用途？",a="诺里斯的杯子用来盛放滚烫的 热酒，送给安威玛尔的德南·弗卡特。德南喝完后，空杯子便要送还给诺里斯·激流。",al={"诺里斯的杯子的用途","杯子里装的是什么","诺里斯的杯子"}},{q="这个杯子是谁的？",a="杯子的主人是诺里斯·激流。他希望旅人将饮料送到安威玛尔后，把杯子还给他。",al={"诺里斯是谁","杯子的主人","这是谁的杯子"}},{q="诺里斯为什么坚持要拿回杯子？",a="诺里斯希望拿回杯子，因为用他的话说，杯子可不是树上长出来的。他想让人把借走的酒杯还给他。",al={"为什么要归还杯子","诺里斯为什么想拿回杯子","杯子不是树上长出来的"}},{q="杯子里喝的是什么？",a="杯子里装的是滚烫的 热酒，这种热饮用来抵御丹莫罗刺骨的严寒。",al={"杯中装的是什么","晨酒 是什么","晨酒 饮料"}}},fp="10,154,18.339.0,28.137.0,18.103.0,45.128.0,28.88.0"}
P.entries["item:notched-rib"] = {n="锯齿肋骨",s="在阿加曼德磨坊，锯齿肋骨证明被遗忘者正在打破天灾军团对提瑞斯法的控制。",h="在阿加曼德磨坊，锯齿肋骨证明被遗忘者正在打破天灾军团对提瑞斯法的控制。",kw={"阿加曼德磨坊","布瑞尔","碎颅士兵","亡灵卫兵迪林格尔","锯齿肋骨","断骨士兵","天灾军团","提瑞斯法林地"},ang={["race:Undead"]="身为被遗忘者，你在这场生存之战中收集这些碎骨，对抗巫妖王麾下那些妄图将你重新拖回奴役之中的无脑爪牙。"},sec={{t="残酷的战斗凭证",b="在提瑞斯法林地北部，天灾军团正集结身披残破护甲的骷髅。碎颅士兵和断骨士兵会攻击遇到的任何活物或拥有自由意志的生物。刀剑在它们脆弱的骨头上留下凹痕与刻痕。亡灵卫兵要求被遗忘者斥候和志愿者拿出击杀这些无脑入侵者的证据。一根带着战斗伤痕的肋骨，表明巫妖王麾下又一个奴仆已被击碎。"},{t="守住磨坊",b="阿加曼德磨坊位于布瑞尔西北方，占据着关键位置。如果天灾军团在破败的农庄和风车间站稳脚跟，这些亡灵就能以此为据点，深入袭击提瑞斯法。亡灵卫兵迪林格尔监视着北方的道路，派遣勇士打散骷髅部队，阻止它们集结壮大。带回布瑞尔的锯齿肋骨表明，被遗忘者的防线依然稳固，正一根根击碎天灾军团先锋的骨头，逐渐消耗它们的兵力。"}},faq={{q="什么是锯齿肋骨？",a="锯齿肋骨是从提瑞斯法林地北部一名被唤起的天灾军团士兵身上取下的伤痕累累的骨头。它向亡灵卫兵迪林格尔证明，一名敌人已被消灭。",al={"锯齿肋骨","什么是锯齿肋骨","锯齿肋骨物品"}},{q="锯齿肋骨来自哪里？",a="锯齿肋骨来自在布瑞尔西北方的阿加曼德磨坊巡逻的碎颅士兵和断骨士兵。",al={"哪里能找到锯齿肋骨","谁掉落锯齿肋骨","锯齿肋骨来源"}},{q="谁需要这些骨头？",a="亡灵卫兵迪林格尔在布瑞尔外的道路旁收集锯齿肋骨和焦黑的颅骨，以确认天灾军团的进攻已被击退。",al={"谁收取锯齿肋骨","锯齿肋骨交付","谁需要锯齿肋骨"}},{q="天灾军团为什么在阿加曼德磨坊集结？",a="这些无脑亡灵正试图在阿加曼德磨坊建立据点，以便袭击提瑞斯法林地各处，威胁被遗忘者的定居点。",al={"阿加曼德磨坊的天灾军团","磨坊为什么有骷髅","阿加曼德磨坊的天灾军团威胁"}}},fp="11,75,20.419.0,18.431.0,22.173.0,32.119.0,22.147.0,46.156.0"}
P.entries["item:nugget-slug"] = {n="高强度齿轮",s="淤泥沼泽的工具桶里装着高强度齿轮，荆棘谷地精用它们固定重型设备。工匠们寻找这些十七点五号紧固件，用来修整不稳定的机械。",h="淤泥沼泽的工具桶里装着高强度齿轮，荆棘谷地精用它们固定重型设备。工匠们寻找这些十七点五号紧固件，用来修整不稳定的机械。",kw={"贫瘠之地","高强度齿轮","调查设备","淤泥沼泽","工具桶","荆棘谷地精","维妮·布特巴克"},ang={["profession:Engineering"]="对工程师来说，专用的十七点五号零件并不适合不稳定的地精工程造物samophlange。等着它在爆炸中迅速解体吧。"},sec={{t="淤泥沼泽的工业紧固件",b="在荆棘谷地精的开采场，高强度齿轮用于固定重型设备。它们专为要求严苛的工业装配而制，规格为十七点五号。它们在日常贸易中用途不大。但工匠们需要它们来制作定制的地精机械。"},{t="修整主动式负载平衡器",b="维妮·布特巴克需要大量高强度齿轮，来彻底检修一台从贫瘠之地找回的不稳定的主动式负载平衡器。荆棘谷地精在淤泥沼泽的钻探作业区散落着许多工具桶，让拾荒者能从回收工作中获利颇丰。\n\n维妮的修理以突如其来的失败告终。主动式负载平衡器在她修理时爆炸了。"}},faq={{q="什么是高强度齿轮？",a="高强度齿轮是一种用于重型机械的十七点五号金属紧固件。这些紧固件用于连接石油钻机和主动式负载平衡器等复杂机械的部件。",al={"什么是高强度齿轮","高强度齿轮背景故事","齿轮紧固件"}},{q="哪里能找到高强度齿轮？",a="高强度齿轮存放在散落于淤泥沼泽各处的工具桶里，那里是荆棘谷地精位于贫瘠之地东北部的钻探营地。",al={"哪里能找到高强度齿轮","高强度齿轮位置","淤泥沼泽工具桶"}},{q="维妮·布特巴克为什么需要它们？",a="维妮·布特巴克想要修整并修复一台从贫瘠之地找回的主动式负载平衡器。她用完了十七点五号紧固件，于是派冒险者去附近的荆棘谷地精营地回收更多。",al={"谁需要高强度齿轮","维妮为什么需要齿轮","什么什么平衡器修理"}},{q="用高强度齿轮能修好主动式负载平衡器吗？",a="不能。维妮把回收来的高强度齿轮装到主动式负载平衡器上，开始检修。随后，它就在她面前炸开了。",al={"机器能运转吗","什么什么平衡器爆炸","维妮修理结果"}}},fx={f3aea894={q="高强度齿轮从何而来？由谁制造？",a="这些特殊的十七点五口径弹丸是荆棘谷地精在淤泥沼泽使用的工业器材。他们的工人和工程师将其储存在工具桶中，散放在贫瘠之地东部的钻探和挖掘工地周围。",al={"高强度齿轮从何而来","谁制造高强度齿轮","高强度齿轮的来源"}}},fp="11,185,38.263.0,30.327.1,22.174.0,29.131.0,38.228.0,48.115.1"}
P.entries["item:ogre-s-monocle"] = {n="食人魔的单片眼镜",s="在暮色森林南部，扎克乌尔戴着一副巨大的单片眼镜。镜片的尺寸恰好符合夜色镇的维克托·安特拉斯制作观星望远镜的需要。",h="在暮色森林南部，扎克乌尔戴着一副巨大的单片眼镜。镜片的尺寸恰好符合夜色镇的维克托·安特拉斯制作观星望远镜的需要。",kw={"齿轮","夜色镇","仰望星空","食人魔的单片眼镜","望远镜","维克托·安特拉斯","沃古尔食人魔山","扎克乌尔"},ang={["faction:Alliance"]="取回镜片既能为南部林地除掉一个危险的恶徒，也能帮助夜色镇饱受困扰的居民从群星中寻得慰藉。",["profession:Engineering"]="Cog 的蓝图体现了侏儒一贯的雄心：在野外无法取得精密研磨的镜片时，就用巨型眼镜代替。"},sec={{t="奇特的镜片",b="食人魔扎克乌尔戴着一副巨大的单片眼镜，与他庞大的身躯十分相称。夜色镇的维克托·安特拉斯开始按照侏儒工程师 Cog 的蓝图制作观星仪器时，发现普通镜片都太小了。扎克乌尔的眼镜是这一带唯一尺寸和曲率都合适的磨光玻璃，能让制成的望远镜聚焦光线。"},{t="从 沃古尔 手中夺取",b="沃古尔食人魔山坐落在暮色森林南部的阴影中，扎克乌尔与他那些凶蛮的同族就住在那里。这个蛮横的家伙显然不愿交出他那件独特的配饰。要取得镜片，你必须在他的地盘上击败他，再将镜片带回夜色镇，让维克托能够仰望夜空。"}},faq={{q="谁带着食人魔的单片眼镜？",a="暮色森林南部的食人魔扎克乌尔带着这副单片眼镜，身在沃古尔食人魔山。",al={"谁掉落单片眼镜","谁有食人魔的单片眼镜","扎克乌尔 物品"}},{q="维克托·安特拉斯为什么需要食人魔的镜片？",a="维克托·安特拉斯按照侏儒 考格 的蓝图制作望远镜，需要一块格外大的镜片。扎克乌尔的单片眼镜是暮色森林中唯一符合要求的玻璃。",al={"为什么需要单片眼镜","单片眼镜有什么用","望远镜镜片"}},{q="食人魔是怎么得到巨型单片眼镜的？",a="这段记载没有说明扎克乌尔如何得到这副单片眼镜。它只提到，他有一副眼镜，镜片大到足以用在维克托的望远镜上。",al={"食人魔为什么有单片眼镜","食人魔老花镜背景故事"}},{q="沃古尔食人魔山在哪里？",a="沃古尔食人魔山位于暮色森林南部的丘陵中，在连接夜色镇与西部边界的大路以南。",al={"沃古尔 在哪里","暮色森林食人魔山"}}},fx={["94fbe42d"]={q="食人魔的单片眼镜是什么？",a="食人魔的单片眼镜是一枚尺寸巨大的光学镜片，由居住在暮色森林南部沃古尔食人魔山的显赫食人魔扎克乌尔佩戴。食人魔极少拥有如此精致的光学器具，而这枚巨大的玻璃镜片却特别适合用于重型光学设备。",al={"食人魔的单片眼镜是什么","食人魔单片眼镜物品","食人魔眼镜"}}},fp="14,186,14.351.0,22.286.0,31.87.0,54.175.0,36.131.0,40.127.0"}
P.entries["item:okra"] = {n="秋葵",s="在萨丁农场，秋葵为西部荒野的农户提供食物。这种作物生长在农场的田地里，能让养活他们的炖汤更加浓稠。",h="在萨丁农场，秋葵为西部荒野的农户提供食物。这种作物生长在农场的田地里，能让养活他们的炖汤更加浓稠。",kw={"作物","农场","秋葵","萨丁","萨尔玛·萨丁","蔬菜","杂味炖肉"},ang={["faction:Alliance"]="暴风城的贵族享用着进口肉食，而边疆的联盟农户却在西部荒野的废墟间种植okra这类顽强的作物。",["profession:Cooking"]="云游的厨师知道，一锅好炖汤需要的不只是生肉。Okra能为野外搜罗来的粗硬食材增添淀粉，让它们成为一顿浓稠的热餐。"},sec={{t="萨丁农场的常备作物",b="西部荒野的大片土地因迪菲亚匪徒和失控的收割傀儡袭击而荒芜，萨丁农场却仍在出产蔬菜。秋葵生长在农场周围耕过的田地里，在恶劣的环境中顽强存活。当来自暴风城的贸易和补给断绝时，它便为当地农户提供食物。"},{t="西部荒野炖肉",b="萨尔玛·萨丁著名的杂味炖肉离不开秋葵。她将切好的豆荚与定居者能在尘土飞扬的平原上猎得的各种肉料混在一起，包括秃鹫肉、血牙野猪的鼻子和沿海鱼人的眼睛。豆荚受热后逐渐化开，让稀薄的汤汁变成浓稠、饱腹又能恢复体力的一餐。对于坚守家园的定居者来说，新鲜的秋葵能将四处搜罗来的零星食材变成一顿热腾腾的晚饭。"}},faq={{q="西部荒野的秋葵长在哪里？",a="秋葵生长在西部荒野中央道路旁的萨丁农场，扎根于耕过的田地中。这些绿色植物在农夫萨丁家园附近的田垄里茁壮生长。",al={"秋葵位置","哪里能找到秋葵","秋葵长在哪里"}},{q="秋葵有什么用途？",a="萨尔玛·萨丁在萨丁农场采集秋葵，用来制作她的招牌菜杂味炖肉。其中的天然淀粉能让汤汁变得浓稠，将秃鹫肉、野猪鼻子和鱼人眼睛熬成丰盛的一餐。",al={"秋葵用途","秋葵有什么用","为什么需要秋葵"}},{q="秋葵为何对萨丁一家如此重要？",a="贸易中断，王国提供的援助又寥寥无几，农户只能依靠自己种植的作物和猎得的食物生活。秋葵是萨丁农场仅存的少数栽培作物之一，帮助养活这家人和过往的旅客。",al={"萨丁的秋葵","秋葵为何重要"}}},fx={["301f0b5e"]={q="秋葵是什么？",a="秋葵是一种可食用的蔬菜，生长在西部荒野翻耕过的土壤中。萨丁农场 等农场种植着这种作物，它的荚果十分耐受当地恶劣的气候，是艰难度日的农户们可靠的主粮作物。",al={"秋葵是什么","秋葵物品","秋葵植物"}},["5bbd3a8c"]={q="秋葵来自哪里？",a="秋葵由西部荒野当地的农场种植，其中尤以 萨丁农场 的萨尔玛·萨丁和农夫萨丁最为知名。尽管大片乡野已荒废破败，秋葵这类顽强的作物仍在尚存的耕地中生长。",al={"秋葵来自哪里","谁种植秋葵","秋葵来源"}},b45f6830={q="萨尔玛·萨丁为什么需要秋葵？",a="萨尔玛·萨丁需要新鲜的秋葵，这是她那道著名的杂味炖肉不可或缺的食材。将秋葵切片，与野味和当地出产的肉类一同慢炖，能让鲜美的汤汁更加浓稠，为平原上的人们提供丰盛饱腹的一餐。",al={"为什么需要秋葵","萨尔玛·萨丁为什么需要秋葵","谁需要秋葵"}}},fp="4,136,26.306.0,13.393.0,33.147.0,22.188.0,38.219.0"}
P.entries["item:ordanus-head"] = {n="奥达努斯的头颅",s="在林中树居，奥达努斯的头颅被取下，作为守护者奥达努斯已死的证明。血精灵法师布莱林·火拳正在灰谷寻求这颗头颅。",h="在林中树居，奥达努斯的头颅被取下，作为守护者奥达努斯已死的证明。血精灵法师布莱林·火拳正在灰谷寻求这颗头颅。",kw={"灰谷","布莱林·火拳","塞纳留斯","丛林守护者","奥达努斯","奥达努斯的头颅","林中树居","石爪山","烈日石居"},ang={["class:Druid"]="身为德鲁伊，携带着塞纳留斯一位年长子嗣被砍下的头颅，会令人清楚地意识到，奥术巫师至今仍对荒野的守护者怀着刻骨而血腥的仇恨。",["faction:Horde"]="对于部落成员而言，击杀奥达努斯并将他的头颅交给布莱林，有助于巩固部落在石爪山与灰谷争议边境一带的立足点，削弱当地暗夜精灵的领导力量。"},sec={{t="往日的仇怨",b="守护者奥达努斯是一位古老的丛林守护者，也是塞纳留斯的年长子嗣之一。布莱林·火拳奉主人的命令登上石爪山脉的高处，试图终结德鲁伊在山顶对魔法的压制，并向奥达努斯复仇。在她出手之前，这位守护者就被秘密转移到了灰谷腹地。布莱林用奥术占卜窥探森林的树冠，找到了他藏身于林中树居枝杈间的庇护所。她要求带回他被砍下的头颅，以此证明这位荒野半神已为自己的傲慢付出代价。"},{t="傲慢的代价",b="布莱林与奥达努斯早已相识，对他怀有宿怨，也憎恨那些试图压制魔法的德鲁伊。奥达努斯生前自视甚高，甚至认为自己凌驾于古老的上层精灵贵族之上。布莱林·火拳夺取他的头颅，借此回击塞纳留斯留下的传承，并宣告任何荒野守护者都无法阻挡原始魔法力量的回归。"}},faq={{q="守护者奥达努斯是谁？",a="守护者奥达努斯是一位古老的丛林守护者，也是塞纳留斯的年长子嗣之一。很久以前，他曾与暗夜精灵贵族中的奥术施法者发生冲突，并以对奥术修习者极为傲慢而闻名。",al={"奥达努斯是谁","奥达努斯的故事","奥达努斯是什么"}},{q="这颗头颅在哪里取得？",a="这颗头颅取自林中树居高架木台上的守护者奥达努斯，那里是灰谷中部一处设有防御工事的暗夜精灵树冠聚居地。",al={"奥达努斯的头颅在哪里","奥达努斯的位置","林中树居的奥达努斯"}},{q="布莱林·火拳为什么想要他的头颅？",a="布莱林·火拳很久以前就认识奥达努斯，并憎恶他的傲慢；他甚至认为自己比上层精灵更高贵。她也憎恨德鲁伊和塞纳留斯的子嗣，因为他们试图阻断魔法的流动，还在她赶到之前将奥达努斯从山顶秘密转移。",al={"布莱林为何想要奥达努斯的头颅","布莱林的仇怨","为何杀死奥达努斯"}},{q="交付头颅之后会发生什么？",a="将奥达努斯的头颅交给烈日石居的布莱林，便偿清了她的血债，她会将承诺过的强大馈赠赐予那位雇佣兵。",al={"奥达努斯的头颅交付","奥达努斯死后","布莱林·火拳的任务奖励"}}},fx={e1459048={q="奥达努斯的头颅从何而来？",a="这件令人不寒而栗的战利品直接取自守护者奥达努斯。他是森林半神塞纳留斯最年长的儿子之一。人们曾以为他在石爪峰顶安然无恙，但奥达努斯逃到了灰谷，藏身于林中树居高处，最终还是被猎杀。",al={"奥达努斯头颅的来源","奥达努斯的头颅从何而来","奥达努斯的头颅属于谁"}}},fp="13,146,22.579.0,19.368.1,23.225.0,29.161.0,40.265.0,41.141.1"}
P.entries["item:orendil-s-cure"] = {n="奥雷迪尔的药剂",s="在灰谷北部，奥雷迪尔·阔叶为阿斯特兰纳的一个孩子熬制药剂。他用稀有的巴斯兰的头发，治疗蕾拉·怀特姆恩那神秘而致命的疾病。",h="在灰谷北部，奥雷迪尔·阔叶为阿斯特兰纳的一个孩子熬制药剂。他用稀有的巴斯兰的头发，治疗蕾拉·怀特姆恩那神秘而致命的疾病。",kw={"灰谷","阿斯特兰纳","巴斯兰的头发","奥雷迪尔·阔叶","奥雷迪尔的药剂","皮尔图拉斯·怀特姆恩","蕾拉"},ang={["profession:Herbalism"]="灰谷的本土植物蕴藏着强大的药力。巴斯兰的头发就是其中一种草药，只生长在森林中少数阴暗的角落。",["race:NightElf"]="对阿斯特兰纳的暗夜精灵而言，拯救蕾拉是整个群体的当务之急。奥雷迪尔这样的隐士带来林地中的知识，而对Elune的信仰则带来神力的援助。"},sec={{t="一位父亲的希望",b="年幼的蕾拉·怀特姆恩在阿斯特兰纳身患重病，命在旦夕，寻常药物都无济于事。她的父亲皮尔图拉斯·怀特姆恩向奥雷迪尔·阔叶求助，这位隐士住在灰谷北部，精通草药医术。奥雷迪尔用从巴斯兰鬼屋闹鬼的废墟中采来的成捆稀有草药巴斯兰的头发，为蕾拉熬制了一剂药。药瓶送到时，皮尔图拉斯看到了希望。然而，这剂药只能延缓病情，因此他必须继续寻找奥雷迪尔建议的其他药物。"}},faq={{q="奥雷迪尔的药剂有什么用途？",a="奥雷迪尔的药剂用于缓解并治疗蕾拉·怀特姆恩的病症，她是阿斯特兰纳的一名暗夜精灵幼童。突如其来的重病让她卧床不起。",al={"奥雷迪尔的药剂用途","药剂有什么作用","药剂给谁用"}},{q="这剂药是谁配制的？",a="奥雷迪尔·阔叶配制了这剂药。他是一位隐居在灰谷北部林地的暗夜精灵草药师，以精通森林植物和草药医术而闻名。",al={"谁配制了奥雷迪尔的药剂","奥雷迪尔的药剂配制者"}},{q="配制这剂药用了什么材料？",a="这剂药使用了巴斯兰的头发，这是一种纤细而少见的植物，采自灰谷北部巴斯兰鬼屋的废墟间。",al={"药剂材料","奥雷迪尔的药剂含有什么"}},{q="这瓶药水能让孩子完全康复吗？",a="不能。皮尔图拉斯得知，奥雷迪尔的药剂只能延缓女儿的病情，于是他去寻找奥雷迪尔建议的更强效的药物：月神之泪。",al={"药剂治好了蕾拉吗","蕾拉康复了吗"}}},fx={["8e86537e"]={q="奥雷迪尔的药剂是什么？",a="奥雷迪尔的药剂是由灰谷北部的草药师奥雷迪尔·阔叶调制的药剂。它专门用于治疗突发的严重疾病，是一场紧急救治行动的一部分，目的是挽救一名患上神秘疾病的暗夜精灵幼童。",al={"奥雷迪尔的药剂背景","奥雷迪尔的药剂是什么","奥雷迪尔的药剂"}},["6add91d1"]={q="为什么需要奥雷迪尔的药剂？",a="在阿斯特兰纳，皮尔图拉斯·怀特姆恩年幼的女儿蕾拉拉病入膏肓。常规疗法无效后，她的父亲绝望地向奥雷迪尔·阔叶求助。草药师调制了这份特制药剂，希望能在疾病夺走孩子的生命之前稳住她的病情。",al={"为什么需要奥雷迪尔的药剂","谁需要奥雷迪尔的药剂","为什么要运送奥雷迪尔的药剂"}}},fp="14,163,15.497.0,32.142.0,21.161.0,38.126.0,43.152.1"}
P.entries["item:oslow-s-toolbox"] = {n="奥斯洛的工具箱",s="工头奥斯洛需要工具来修缮湖畔镇的防御工事，但工具却沉在止水湖底。工具箱从闪金镇运来，途中黑石兽人用投石车击中了运货船，箱子随之沉入湖中。",h="工头奥斯洛需要工具来修缮湖畔镇的防御工事，但工具却沉在止水湖底。工具箱从闪金镇运来，途中黑石兽人用投石车击中了运货船，箱子随之沉入湖中。",kw={"工头奥斯洛","止水湖","湖畔镇","奥斯洛","赤脊山","沉箱","丢失的工具","工具箱"},ang={["faction:Alliance"]="在黑石的围攻下，湖畔镇几乎与外界隔绝。找回奥斯洛的补给，对维护镇上的防御工事至关重要。"},sec={{t="厄运渡湖",b="工头奥斯洛需要施工工具来维护湖畔镇的防御工事和建筑。黑石兽人围攻赤脊山，通往镇上的桥梁也已被摧毁。这批工具来自闪金镇，因此由一艘划艇运过止水湖。黑石部队用投石车击中了船只，划艇和奥斯洛沉重的箱子一同沉入深水，落在鱼人出没的地方。"}},faq={{q="奥斯洛的工具箱为什么会在湖底？",a="这批工具当时正从闪金镇运往湖畔镇。由于桥梁已被摧毁，货物只能乘船穿过止水湖。黑石兽人用投石车击中了划艇，船只沉没，工具箱也落入湖底。",al={"工具箱为什么在水里","奥斯洛是怎么丢失工具的","沉没工具箱的故事"}},{q="这个工具箱是谁的？",a="工具箱属于工头奥斯洛，他负责湖畔镇的施工和修缮。没有合适的装备，几乎不可能在持续的袭击下维护镇上的防御工事。",al={"奥斯洛是谁","工具箱主人奥斯洛","工头奥斯洛的工具"}},{q="工具沉在止水湖的什么地方？",a="工具装在一个沉入止水湖的箱子里，就在划艇残骸附近。岸边有一处显眼的鱼人营地，箱子就在营地南面的水下巨石之间。",al={"工具箱位置","沉箱在哪里","船沉在哪里"}},{q="沉箱周围有什么威胁？",a="残骸周围的水域遍布敌对的鱼人和捕食性的水生野兽。危险的湖水潜藏者在湖水深处游弋。",al={"工具箱附近的危险","止水湖的敌人","什么在守着奥斯洛的工具"}}},fx={["543d5407"]={q="工头奥斯洛为什么需要找回他的工具箱？",a="湖畔镇遭到猛烈围攻，城镇与外界隔绝，必需物资也极度匮乏。身为城镇工头，奥斯洛需要工具来维护和修理湖畔镇的建筑与防御工事。由于闪金镇送来的货车无法通过被毁坏的桥梁，替换工具掉进了湖里，关键的建造工作因此停滞。找回工具对城镇的存续至关重要。",al={"奥斯洛为什么想要工具箱","奥斯洛为什么需要工具","为什么要找回奥斯洛的工具箱"}}},fp="15,106,18.372.0,49.208.0,22.198.0,43.173.0,36.144.0"}
P.entries["item:osric-s-crate"] = {n="奥斯瑞克的箱子",s="在哨兵岭，奥斯瑞克的箱子为人民军带来了暴风城新制的护甲。守军没有暴风城军队的援助，独自面对迪菲亚潜行者和四处劫掠的豺狼人。",h="在哨兵岭，奥斯瑞克的箱子为人民军带来了暴风城新制的护甲。守军没有暴风城军队的援助，独自面对迪菲亚潜行者和四处劫掠的豺狼人。",kw={"杜加尔·朗德瑞克","狮鹫","奥斯瑞克","奥斯瑞克的箱子","人民军","军需官刘易斯","哨兵岭","西部荒野"},ang={["faction:Alliance"]="对联盟而言，每一批抵达哨兵岭的武器和护甲，都有助于守住王国的西部边境，使其免于落入迪菲亚潜行者之手。"},sec={{t="前线补给",b="军需官刘易斯接收这批货物，并将防具分发给志愿参战的战士。王室没有给予人民军任何正式援助。这些新制的护甲旨在帮助志愿者守住阵地。"},{t="狮鹫信使网络",b="一只狮鹫从杜加尔·朗德瑞克位于暴风城贸易区的栖所出发，将箱子运往哨兵岭的索尔那里。空运避开了穿过艾尔文森林、跨越西部荒野边界的危险道路，那里的强盗可能伏击旅人。战时，狮鹫帮助边境驻军维持补给。"}},faq={{q="奥斯瑞克的箱子里装着什么？",a="奥斯瑞克的箱子里装着暴风城打造的防护铠甲。军需官刘易斯接收这批货物，准备将它们分发给保卫哨兵岭的战士。",al={"箱子里有什么","奥斯瑞克的箱子里的物品","奥斯瑞克的箱子内容"}},{q="奥斯瑞克是谁？",a="奥斯瑞克是暴风城的一名护甲匠，为坚守西部荒野的人民军备好了这批货物。",al={"奥斯瑞克是谁","谁寄出了奥斯瑞克的箱子"}},{q="谁来接收箱子？",a="军需官刘易斯接收箱子。他在西部荒野的哨兵岭为人民军管理补给和装备。",al={"箱子送往哪里","奥斯瑞克的箱子交给谁","箱子接收人"}},{q="为什么用狮鹫运送箱子？",a="强盗和不法之徒让途经暴风城、艾尔文森林和西部荒野的道路危机四伏。一只狮鹫将护甲从暴风城的杜加尔·朗德瑞克那里迅速而安全地运到哨兵岭的索尔手中。",al={"为什么空运箱子","为什么使用狮鹫","奥斯瑞克的箱子空运"}}},fx={["34d354cb"]={q="奥斯瑞克的箱子是什么？",a="奥斯瑞克的箱子是一批从暴风城运出的护甲。这批护甲是为驻守西部荒野哨兵岭的守军准备的，他们在抵御迪菲亚潜行者时，装备已经严重短缺。",al={"奥斯瑞克的箱子是什么","奥斯瑞克的箱子物品","奥斯瑞克的箱子里有什么"}},["091b5cbb"]={q="奥斯瑞克的箱子来自哪里，是谁准备的？",a="这个箱子来自暴风城，由奥斯瑞克准备并发出，用于补给人民军。狮鹫管理员杜加尔·朗德瑞克将它托付给你，让你乘狮鹫穿越王国，将它送往西部荒野。",al={"谁制作了奥斯瑞克的箱子","奥斯瑞克的箱子来自哪里","奥斯瑞克的箱子来源"}},["11fb3015"]={q="为什么有人需要奥斯瑞克的箱子？",a="哨兵岭的军需官刘易斯和人民军急需箱子里的护甲。王国军队已经放弃西部荒野，匪徒四处横行，每一件护具都关乎守军的生死。",al={"为什么运送奥斯瑞克的箱子","军需官刘易斯为什么需要奥斯瑞克的箱子","奥斯瑞克的箱子用途"}}},fp="13,181,22.237.0,22.301.0,29.174.0,13.101.0,23.128.0,38.199.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="一组软泥怪采样瓶",s="铁炉堡的一组软泥怪采样瓶将用于费伍德森林的危险采样工作。拉里斯·空轮提供的瓶子能盛放受污染和受诅咒的软泥，而不会被溶蚀。",h="铁炉堡的一组软泥怪采样瓶将用于费伍德森林的危险采样工作。拉里斯·空轮提供的瓶子能盛放受污染和受诅咒的软泥，而不会被溶蚀。",kw={"容器","受诅咒","费伍德森林","铁炉堡","采样瓶","拉里斯·空轮","软泥怪","包裹","软泥","受污染"},ang={["faction:Alliance"]="作为联盟的一员，收集这些样本能帮助你跟上被遗忘者的皇家药剂师学会那些令人不安的研究进展。",["race:Gnome"]="身为侏儒，拉里斯·空轮可以借软泥研究向铁炉堡的矮人证明，收留侏儒难民的辛劳没有白费。"},sec={{t="野外研究设备",b="拉里斯·空轮将十二个空瓶交给前往费伍德森林的旅人。其中六个用于盛放受诅咒的软泥，另外六个用于盛放受污染的软泥。未经处理的样本具有腐蚀性，能蚀穿普通行囊。坚固、密封的玻璃瓶能将酸性残留物封存在内，跨越大陆，送到拉里斯在铁炉堡的工作台上。"},{t="软泥之谜",b="拉里斯·空轮对软泥的兴趣远不止一种古怪的爱好。他曾见过皇家药剂师学会的被遗忘者研究员在艾泽拉斯各地采集这些奇异的生物，因此想知道他们掌握了什么。他怀疑软泥可能是与世界创生有关的原始分泌物。野外调查员用他的瓶子收集证据，他希望这些证据能为自己在探险者协会中赢得赞誉。"}},faq={{q="一组软泥怪采样瓶里装着什么？",a="包裹里装着十二个空样本瓶：六个用于盛放受诅咒的软泥，另外六个用于盛放受污染的软泥。",al={"包裹内容","包裹里有什么","里面的软泥采样瓶"}},{q="谁提供这个包裹？",a="铁炉堡的侏儒学者兼研究员拉里斯·空轮向联盟冒险者提供这个包裹。",al={"谁提供采样瓶","拉里斯·空轮任务物品","软泥采样瓶包裹哪里获取"}},{q="这些容器要在哪里使用？",a="这些容器要在费伍德森林使用。冒险者在那里击败受污染和受诅咒的软泥怪，然后从倒下的生物身上采集残留物。",al={"软泥采样瓶在哪里使用","软泥怪在哪个区域","软泥采样瓶位置"}},{q="拉里斯·空轮为什么想要这些软泥样本？",a="拉里斯曾见过被遗忘者的皇家药剂师学会在世界各地采集软泥，因此想揭开软泥的秘密。他怀疑软泥可能是与艾泽拉斯创生有关的原始分泌物，并希望这些证据能提升自己在探险者协会中的地位。",al={"为什么收集软泥","空轮的研究","拉里斯为什么需要软泥"}}},fx={d8bf9111={q="一组软泥怪采样瓶是什么？",a="这是一套由铁炉堡的侏儒研究员拉里斯·空轮组装的野外工具。包裹里装着一组特制的瓶子，用来采集并安全保存样本，这些样本取自遍布费伍德森林的腐化软泥怪和淤泥怪。",al={"一组软泥怪采样瓶是什么","软泥怪采样瓶包裹","空软泥怪采样瓶组"}}},fp="32,181,24.324.0,23.402.0,52.91.0,26.110.0,44.137.0,50.260.0"}
P.entries["item:painted-gnoll-armband"] = {n="彩色豺狼人臂章",s="在西泉要塞，彩色豺狼人臂章是击杀河爪豺狼人的凭证。它们成群逼近艾尔文森林的西部边境。",h="在西泉要塞，彩色豺狼人臂章是击杀河爪豺狼人的凭证。它们成群逼近艾尔文森林的西部边境。",kw={"悬赏","瑞尼尔副队长","艾尔文森林","豺狼人","彩色豺狼人臂章","河爪","石碑湖","西泉要塞"},ang={["faction:Alliance"]="作为联盟冒险者，你收集这些臂章，就能在暴风城常备军被调往他处时，帮助西泉要塞守住暴风城的西部边境。"},sec={{t="河爪的信物",b="河爪战士和拾荒者佩戴着粗糙的臂章，上面绘有简陋的部族图案。这些臂章来自艾尔文森林荒野边境一带的河爪豺狼人。暴风城的守军在石碑湖附近和西泉要塞以南的树林中面临着日益严重的威胁。"},{t="西泉要塞的悬赏",b="暴风城的军队分散在王国各地，兵力捉襟见肘，西泉要塞因此难以守住西部边境。瑞尼尔副队长长期悬赏，征募人手击杀河爪斥候和河爪豺狼人。这些彩绘臂章让副队长们得以核算赏金，并削减附近农田周围的豺狼人数量。"}},faq={{q="西泉要塞为什么需要这些臂章？",a="西泉要塞的瑞尼尔副队长收集这些臂章，作为河爪豺狼人已被击杀的凭证。要塞的士兵无法独力应对步步进逼的豺狼人，因此暴风城向带回这些信物的人支付赏金。",al={"为什么收集臂章","谁需要彩色豺狼人臂章","瑞尼尔副队长悬赏"}},{q="哪些豺狼人佩戴这些彩绘臂章？",a="河爪豺狼人佩戴这些彩绘臂章。河爪前锋和河爪豺狼人盘踞在西泉要塞以南的树林和石碑湖周围的湖岸。",al={"臂章掉落地点","谁掉落彩色豺狼人臂章","哪些豺狼人有臂章"}},{q="河爪豺狼人为什么会出现在艾尔文森林？",a="河爪豺狼人群沿着艾尔文森林的边境向东推进，在石碑湖附近和森林边缘扎营。王国驻军兵力不足，它们便在此狩猎、拾荒，威胁附近的定居点。",al={"豺狼人为何在此","豺狼人入侵艾尔文森林","河爪艾尔文森林"}},{q="臂章上的彩绘有什么意义？",a="彩绘是从河爪豺狼人身上取得的战利品的标记，有助于向瑞尼尔副队长证明击杀成果。这些图案并未被赋予明确的等级或含义。",al={"为什么绘有彩绘","豺狼人臂章图案"}}},fx={["586b453e"]={q="彩色豺狼人臂章是什么？",a="彩色豺狼人臂章是河爪豺狼人佩戴的一种粗陋饰物。这些臂章由族群成员制作并涂上颜色，标志着它们在艾尔文森林边境一带的活动。对 暴风城军队 而言，这些臂章是劫掠的豺狼人已被击杀的确凿物证。",al={"彩色豺狼人臂章是什么","彩色豺狼人臂章背景","豺狼人臂章"}}},fp="21,142,22.279.0,29.306.0,48.226.0,41.166.0,41.226.0,54.140.0"}
P.entries["item:panther-cage-key"] = {n="豹笼钥匙",s="豹笼钥匙是一把小巧的金属钥匙，由白沙岗哨的维兹罗持有。它能打开千针石林一支遇袭商队的残骸中的加固笼子，里面关着一头暴怒的猛兽。",h="豹笼钥匙是一把小巧的金属钥匙，由白沙岗哨的维兹罗持有。它能打开千针石林一支遇袭商队的残骸中的加固笼子，里面关着一头暴怒的猛兽。",kw={"半人马","超适应齿轮","豹笼钥匙","千针石林","白沙岗哨","维兹罗"},ang={["faction:Horde"]="协助维兹罗有助于平息半人马劫掠造成的动荡，保障千针石林白沙岗哨周边道路的安全。",["profession:Engineering"]="这把钥匙能打开关着一位工匠的不稳定原型装置的笼子，证明了古怪的发明家会把最精密的机械藏在所能想象的最危险的地方。"},sec={{t="险境中的锁",b="一支行进中的商队在白沙岗哨以北遭到半人马劫掠者袭击并洗劫，地精工匠维兹罗险些丧命。劫掠者翻遍了货车残骸和货物，却有一样东西完全没有碰：一只坚固的笼子，里面关着一头凶猛的稀有豹子。猛兽的脖子上挂着维兹罗引以为傲的发明——超适应齿轮。半人马不愿靠近这头咆哮的野兽，对笼子避之不及，因此只有用维兹罗的钥匙才能打开笼门，取回装置。"}},faq={{q="谁提供豹笼钥匙？",a="维兹罗会将钥匙交给冒险者。这位地精工匠正在千针石林西北部的白沙岗哨休息。",al={"谁给豹子钥匙","哪里获取豹笼钥匙","豹笼钥匙来源"}},{q="这把钥匙能打开什么？",a="它能打开白沙岗哨北面不远处一支被毁商队的破损货车间的铁笼，里面关着一头暴怒而危险的豹子。",al={"豹子钥匙能开什么","豹笼位置","笼子在哪里"}},{q="半人马为什么没有洗劫笼子？",a="半人马洗劫了商队的其他地方，但笼中的豹子凶猛骇人，就连这些劫掠者也不肯碰它的笼子。",al={"半人马为什么留下豹子","半人马害怕豹子"}},{q="除了猛兽，笼子里还有什么？",a="维兹罗珍爱的超适应齿轮系在豹子的脖子上，想取回这项发明的人必须打开笼子，直面这头猛兽。",al={"为什么打开笼子","豹子身上有什么"}}},fx={b335554a={q="维兹罗为什么要取回豹笼钥匙？",a="维兹罗·轴闪把钥匙交给你，只是为了让你打开他那辆被毁货车上的笼子，杀死里面凶猛的豹子。那头野兽脖子上戴着他珍爱的超适应齿轮。他希望事情办妥后，你把钥匙和发明一并归还，好确认货车残骸和他的危险财物都已清点完毕。",al={"为什么需要豹笼钥匙","维兹罗为什么需要钥匙","为什么要豹笼钥匙"}}},fp="16,160,17.423.0,34.115.0,25.142.0,37.137.0,42.139.0"}
P.entries["item:parker-s-lunch"] = {n="帕克的午餐",s="达希在湖畔镇备好帕克的午餐，供卫兵帕克巡逻时享用。这顿饭让人得以一窥赤脊山守卫者之间的情谊与朴素的慰藉。",h="达希在湖畔镇备好帕克的午餐，供卫兵帕克巡逻时享用。这顿饭让人得以一窥赤脊山守卫者之间的情谊与朴素的慰藉。",kw={"一顿免费的午餐","达希","卫兵帕克","湖畔镇","帕克的午餐","赤脊山"},ang={["faction:Alliance"]="首都的援军迟迟未到，镇民与所剩无几的卫兵相互扶持，维持着湖畔镇的日常运转。",["profession:Cooking"]="对于边境卫兵来说，长时间置身于敌意野兽出没的荒野时，一份打包好的热饭便是一种慰藉。"},sec={{t="路上的一餐",b="达希是湖畔镇旅店的女服务员，她为卫兵帕克备好了一顿饭。他在向南通往暮色森林的道路上巡逻，那里缺乏掩护，而赤脊山正遭受豺狼人和黑石兽人的袭击。驻军人手紧缺，又得不到暴风城的援助，卫兵们只能长时间孤独地站岗守望。达希的小小心意让帕克填饱了肚子，也让这两位镇民之间萌生了一段羞涩的恋情。"}},faq={{q="谁准备了帕克的午餐？",a="达希是湖畔镇旅店的女服务员，她为正在外面巡逻的卫兵帕克准备了帕克的午餐。一位旅行者将午餐送到他手中。",al={"谁做了帕克的午餐","谁给了我帕克的午餐","达希 赤脊山 午餐"}},{q="在哪里能找到卫兵帕克？",a="卫兵帕克在从湖畔镇向西南通往暮色森林边界的土路干道上巡逻。他来回行进，警戒着四处游荡的豺狼人。",al={"卫兵帕克位置","卫兵帕克在哪里","寻找卫兵帕克"}},{q="卫兵帕克收到午餐后做了什么？",a="帕克被达希的体贴打动，想找个办法回报她的好意。他安排人从草药师那里给她送去新鲜的水仙花。",al={"帕克 午餐后续","达希和帕克","帕克 收到午餐的反应"}},{q="达希为什么不亲自送午餐？",a="豺狼人和黑石入侵者威胁着湖畔镇外的道路。达希只是一位普通镇民，而帕克受过训练，又有护甲保护，能够在这些道路上巡逻。",al={"达希为什么不能送来","为什么要在赤脊山送午餐"}}},fx={["2351e721"]={q="帕克的午餐是什么？",a="帕克的午餐是旅店助手达希准备的一份便餐。她特意将它打包起来，为卫兵帕克补充体力。帕克要花很长时间在镇子南边通往暮色森林的险恶道路上巡逻，工作十分辛苦。",al={"帕克的午餐是什么","帕克的午餐物品"}},b73a829b={q="为什么要把卫兵帕克的午餐送过去？",a="卫兵帕克驻守在湖畔镇相对安全的区域之外，沿着边境道路提防四处游荡的豺狼人和黑石兽人。他无法擅自离岗回旅店，只能依靠达希这样的镇民和路过的旅人送来食物，才能在执勤时填饱肚子。",al={"为什么要送帕克的午餐","帕克为什么想要午餐","卫兵帕克为什么需要午餐"}}},fp="14,154,19.382.0,28.143.0,32.148.0,52.147.1,44.158.0"}
P.entries["item:partially-filled-vessel"] = {n="装着半瓶水的瓶子",s="特纳隆·雷拳在奥达希尔将装着半瓶水的瓶子交给年轻的暗夜精灵新兵。瓶中盛着幽影谷受过祝福的月井水，将被送往多兰纳尔。",h="特纳隆·雷拳在奥达希尔将装着半瓶水的瓶子交给年轻的暗夜精灵新兵。瓶中盛着幽影谷受过祝福的月井水，将被送往多兰纳尔。",kw={"奥达希尔","科瑞萨斯·月怒","大地之冠","多兰纳尔","月井","装着半瓶水的瓶子","幽影谷","特纳隆·雷拳","瓶子"},ang={["class:Druid"]="身为德鲁伊，你携带圣水，是为了协助塞纳里奥议会滋养世界之树，并检查它的健康状况。",["race:NightElf"]="身为年轻的暗夜精灵，携带这个瓶子意味着你将走出幽影谷的庇护之地，投身于照料泰达希尔的更广泛事务。"},sec={{t="神圣的运送",b="年轻的卡多雷新兵从幽影谷隐蔽的月井中采集受过祝福的井水。在奥达希尔，特纳隆·雷拳将一份水样倒入瓶中，让新兵带着它穿行于泰达希尔。为了照料这座岛屿的健康，还必须从这棵树上的其他月井中采集更多井水。"},{t="前往多兰纳尔",b="带着瓶子向南穿过山谷的大门，再沿着石板路向西前往多兰纳尔。这段旅程将带领年轻的冒险者走出幽影谷这片受庇护的成长之地，踏入泰达希尔更广阔的荒野。在多兰纳尔中央的月井旁，科瑞萨斯·月怒会接过瓶子，并指引仪式的下一步。"}},faq={{q="瓶子里装着什么？",a="瓶中盛着幽影谷神圣月井中的纯净井水，由德鲁伊特纳隆·雷拳倒入。",al={"瓶子里有什么","瓶中所盛之物","里面是什么水"}},{q="为什么瓶子只装了一部分水？",a="幽影谷的月井只提供第一份水样。为了照料泰达希尔，需要从多口月井中采集井水，才能将瓶子装满。",al={"为何只装了部分水","为什么没有装满"}},{q="我该把这个瓶子交给谁？",a="带着瓶子向南离开幽影谷，再沿着石板路向西前往多兰纳尔。将它交给照料镇上月井的科瑞萨斯·月怒。",al={"瓶子交给谁","送到哪里","交付瓶子"}},{q="为什么要在泰达希尔各处运送月井水？",a="德鲁伊和女祭司通过月井水监测并滋养泰达希尔。在月井之间运送井水，有助于让祝福遍及这棵新生世界之树饱受困扰的枝干。",al={"为何运送月井水","井水的用途","为何运水"}}},fp="23,159,17.262.0,18.309.0,26.93.0,32.142.0,29.159.0,52.198.0"}
P.entries["item:pendant-of-shadow"] = {n="暗影坠饰",s="莫甘斯在伊尔加拉之塔携带着暗影坠饰，追寻着月神镰刀。塞欧克瑞图斯要求将这件护符带到阿祖拉之塔，以证明莫甘斯已被击杀。",h="莫甘斯在伊尔加拉之塔携带着暗影坠饰，追寻着月神镰刀。塞欧克瑞图斯要求将这件护符带到阿祖拉之塔，以证明莫甘斯已被击杀。",kw={"莫甘斯","暗影坠饰","赤脊山","月神镰刀","塞欧克瑞图斯","阿祖拉之塔","伊尔加拉之塔"},ang={["class:Mage"]="身为法师，为塞欧克瑞图斯取回护符，体现了法师肩负的责任：阻止那些肆意妄为、威胁王国的叛逆施法者。",["class:Warlock"]="身为术士，莫甘斯的经历表明，追寻月神镰刀这类力量不稳定的禁忌神器，引来阿祖拉之塔的审视，会带来怎样的危险。"},sec={{t="黑暗术士的信物",b="莫甘斯是一名叛逆的术士，在伊尔加拉之塔持有暗影坠饰。他曾探寻月神镰刀的奥秘，这件古老圣物蕴含着强大而不稳定的力量。塞欧克瑞图斯担心莫甘斯会给赤脊山和暴风城王国带来灾难。这位法师派冒险者潜入伊尔加拉，终结莫甘斯的阴谋，并取回护符作为他已死的证明。"}},faq={{q="在哪里能找到暗影坠饰？",a="莫甘斯位于赤脊山东北部的伊尔加拉之塔顶层，坠饰就在他身上。",al={"暗影坠饰位置","暗影坠饰在哪","如何获得暗影坠饰"}},{q="谁想要暗影坠饰？",a="塞欧克瑞图斯要求将这件护符送到他手中，他位于艾尔文森林东部的阿祖拉之塔。",al={"谁收取暗影坠饰","交付暗影坠饰","塞欧克瑞图斯坠饰"}},{q="塞欧克瑞图斯为什么需要这枚坠饰？",a="塞欧克瑞图斯需要这枚坠饰，以证明莫甘斯已被击杀，不会再追寻危险的月神镰刀。",al={"塞欧克瑞图斯为何想要它","暗影坠饰用途"}},{q="携带坠饰的莫甘斯构成了什么威胁？",a="莫甘斯曾追寻月神镰刀。塞欧克瑞图斯担心，一旦这名术士得到那件神器，就会在赤脊山和周边王国释放灾难性的力量。",al={"莫甘斯在做什么","莫甘斯背景故事"}}},fx={d0e37f9a={q="暗影坠饰是什么？",a="暗影坠饰是堕落术士摩根斯佩戴的一枚黑暗护符，他盘踞在赤脊山的伊尔加拉之塔顶端。这枚坠饰与摩根斯佩的邪恶野心和黑暗法术密切相关，是他落败的凭证，巫师塞欧克瑞图斯需要它，因为他担心若不加以制止，摩根斯佩会在暴风城掀起灾祸。",al={"暗影坠饰是什么","暗影坠饰的背景","暗影坠饰信息"}}},fp="17,180,23.403.1,38.99.0,32.92.0,38.121.1,47.171.1"}
P.entries["item:pendant-of-the-sea-lion"] = {n="海狮坠饰",s="在雷姆洛斯神殿，德鲁伊将海狮坠饰的两个部分合为一体。完整的护符标志着学徒已准备好学习水栖形态。",h="在雷姆洛斯神殿，德鲁伊将海狮坠饰的两个部分合为一体。完整的护符标志着学徒已准备好学习水栖形态。",kw={"水栖形态","德迪利特·星焰","玛斯雷·驭熊者","月光林地","海狮坠饰","雷姆洛斯","图拉克·符文图腾"},ang={["class:Druid"]="作为德鲁伊，合成坠饰标志着你的修行迈过了一道重要关口。它让你能够化为海狮，在水下呼吸并迅速游动。",["race:Tauren"]="作为一名踏上塞纳里奥议会之路的tauren，当你把坠饰带给图拉克·符文图腾时，便是在向祖先致敬，并践行月光林地的教诲。"},sec={{t="深海的信物",b="德鲁伊必须学会应对水中的危险，才能获得海狮的水栖形态。坠饰分为两个部分，一部分象征着躲避水中捕食者的敏捷，另一部分象征着长时间潜水所需的耐力。在月光林地的雷姆洛斯神殿，这两个部分被合为一体。"},{t="精通的证明",b="坠饰制成后，学徒会将它带给一位年长的导师。图拉克·符文图腾在雷霆崖的高地上等候，玛斯雷·驭熊者则身在达纳苏斯。这件护符证明学徒已完成德迪利特·星焰的试炼，长者便可传授化为水栖形态的奥秘。"}},faq={{q="海狮坠饰有什么用途？",a="坠饰证明德鲁伊学徒已完成水中敏捷与耐力的试炼，准备好学习水栖形态。",al={"海狮坠饰有什么作用","海狮坠饰用途","为什么要获得海狮坠饰"}},{q="坠饰在哪里合成？",a="坠饰的两个部分分别象征敏捷与耐力，在月光林地的雷姆洛斯神殿合为一体。",al={"如何制作海狮坠饰","在哪里合成坠饰的两个部分"}},{q="在雷霆崖，我该把坠饰交给谁？",a="在雷霆崖，你要把完整的坠饰交给长者高地上的图拉克·符文图腾。",al={"雷霆崖坠饰交给谁","图拉克·符文图腾坠饰","部落水栖形态交任务"}},{q="暗夜精灵也能获得这件坠饰吗？",a="可以。暗夜精灵德鲁伊在月光林地接受同样的试炼，然后将合成的坠饰带给达纳苏斯的玛斯雷·驭熊者。",al={"联盟海狮坠饰","达纳苏斯海狮坠饰"}}},fp="23,154,19.299.0,16.307.0,51.119.0,31.128.0,49.89.0,39.130.0"}
P.entries["item:perenolde-tiara"] = {n="匹瑞诺德王冠",s="匹瑞诺德王冠在奥特兰克废墟中重现。这件镶嵌着翡翠的传家宝出自铁炉堡的矮人工匠之手，暴风城的收藏家们正在寻觅它。",h="匹瑞诺德王冠在奥特兰克废墟中重现。这件镶嵌着翡翠的传家宝出自铁炉堡的矮人工匠之手，暴风城的收藏家们正在寻觅它。",kw={"奥特兰克","翡翠","格雷尔伯格","铁炉堡","守财奴","匹瑞诺德","雷明顿","瑞治维尔","王冠"},ang={["faction:Alliance"]="身为联盟的一员，你眼前的遗物勾起了对匹瑞诺德家族的痛苦回忆，这个家族在Second War期间的背叛几乎摧毁了最初的洛丹伦联盟。",["race:Dwarf"]="身为矮人，你能从这些翡翠中看出铁炉堡的珠宝工艺，它们由铁炉堡的珠宝大师切割、镶嵌，献给北方的人类王室。"},sec={{t="覆灭王国的遗宝",b="匹瑞诺德家族曾统治奥特兰克，直到王国在第二次战争期间覆灭。他们的珍宝中有一顶精巧的王冠，由铁炉堡的珠宝大师打造，镶嵌着璀璨的翡翠。艾登匹瑞诺德国王的背叛使奥特兰克沦为废墟后，这顶王冠便消失在满目疮痍的险峻山岭间。"},{t="守财奴的珍宝",b="食人魔法师守财奴格雷尔伯格在奥特兰克的废墟中搜寻遗弃的财宝时，挖出了这顶王冠。这件遗物的消息传到了雷明顿·瑞治维尔伯爵耳中，他是暴风城的一位富有贵族，为家族博物馆收集著名的遗物。如今，伯爵想要从食人魔手中夺取这顶王冠。"}},faq={{q="匹瑞诺德王冠是什么？",a="匹瑞诺德王冠是奥特兰克王室匹瑞诺德家族的传家宝。铁炉堡的矮人珠宝匠打造了它，并为它镶嵌翡翠，后来它在王国覆灭时遗失。",al={"匹瑞诺德王冠的故事","这顶王冠是什么","奥特兰克王冠"}},{q="王冠如今在谁手中？",a="食人魔法师守财奴格雷尔伯格在奥特兰克冰雪覆盖的废墟中找到了王冠。他守着王冠，同时继续在这个覆灭的王国中搜寻更多宝藏。",al={"王冠在哪里","谁掉落王冠","格瑞尔伯格王冠"}},{q="雷明顿·瑞治维尔伯爵为什么想要它？",a="雷明顿·瑞治维尔伯爵为他在暴风城的家族博物馆收集历史悠久、声名显赫的古物。他想要这顶王冠，因为它是一个覆灭的人类王国留下的王室珍宝。",al={"谁想要王冠","雷明顿为什么想要它","雷明顿·瑞治维尔的动机"}},{q="匹瑞诺德家族是什么人？",a="匹瑞诺德家族曾统治奥特兰克王国。在第二次战争期间，艾登匹瑞诺德国王背叛了联盟，投向兽人部落，他的王国也随之沦为废墟。",al={"匹瑞诺德家族","奥特兰克的统治者"}}},fx={da959daa={q="匹瑞诺德王冠来自哪里，是谁制作的？",a="这顶王冠来自已经覆灭的北方王国奥特兰克，曾是王室匹瑞诺德家族珍贵的传家宝。据说，它并非出自人类工匠之手，而是由铁炉堡的矮人珠宝大师制作，他们在这件华美的饰物上镶嵌了最上等的翡翠。",al={"谁制作了匹瑞诺德王冠","匹瑞诺德王冠来源","王冠在哪里制作"}}},fp="15,167,27.319.0,17.295.0,28.187.0,28.152.0,43.172.0,24.161.0"}
P.entries["item:phial-of-scrying"] = {n="占卜之水",s="在黑海岸，斥候们用占卜之水从远方联系安努。这位知识古树提供了这件附魔容器，它能唤出一只占卜之碗，让斥候隔着遭到腐化的林地进行占卜。",h="在黑海岸，斥候们用占卜之水从远方联系安努。这位知识古树提供了这件附魔容器，它能唤出一只占卜之碗，让斥候隔着遭到腐化的林地进行占卜。",kw={"黑海岸","主宰之剑","安努","占卜之水","占卜之碗","暮光之锤"},ang={["class:Druid"]="身为德鲁伊，你知道占卜之碗将天然之水与沟通魔法融为一体。它们让森林的守护者能够隔着遭到腐化的土地传递低语。",["race:NightElf"]="身为黑海岸的暗夜精灵，你知道占卜之水这样的占卜工具，有助于监视遭到外来邪教侵蚀的神圣林地。"},sec={{t="遥望黑海岸",b="占卜之水盛着神秘的水，能在地面上暂时形成一只碗。深入黑海岸调查的斥候用它进行远距离占卜。在主宰之剑这样的险地，他们可以直接与安努交谈，无须返回他的林地。"},{t="揭露邪教",b="安努交给斥候占卜之水，用来监视暮光之锤教徒。一位远古主宰倒下的地方，一柄巨大的飞刃贯穿了他的身躯，斥候就在此处建立占卜联结。幻象证实，黑暗教徒正聚集在这具远古遗骸周围，寻找那些被遗忘的力量碎片，它们即便在死后仍未消散。"}},faq={{q="占卜之水有什么用途？",a="拔开占卜之水的瓶塞，地面上便会形成一只魔法碗。身在野外时，你可以用它跨越遥远的距离，联系安努并与他交谈。",al={"使用占卜之水","占卜之碗用途","这瓶水有什么用"}},{q="谁提供占卜之水？",a="古老的树人安努派遣黑海岸的斥候前往南方侦察主宰之剑时，会将占卜之水交给他们。",al={"谁给占卜之水","哪里获取占卜之水"}},{q="占卜之水丢失或用尽了怎么办？",a="如果你丢失了占卜之水，或在完成任务前将它用掉，正在黑海岸冥想的安努可以再给你一瓶。",al={"占卜之水丢失","再领一瓶占卜之水","补领占卜之水"}},{q="安努为什么要占卜主宰之剑的情况？",a="安努知道一位古老的领主倒在了主宰之剑，并请你前往那里搜寻暮光之锤教徒。随着调查深入，他们的目的逐渐清晰。",al={"为何占卜主宰之剑","安努主宰之剑任务"}}},fp="16,173,23.242.0,19.313.1,34.155.0,34.122.0,47.120.0,44.171.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="克罗姆扎军旗的碎片",s="在十字路口以西的雷戈萨·死门的地堡里，一面残破的旗帜见证了敌军攻势的溃败。督军克罗姆扎率领这支科卡尔复仇部队从凄凉之地而来。",h="在十字路口以西的雷戈萨·死门的地堡里，一面残破的旗帜见证了敌军攻势的溃败。督军克罗姆扎率领这支科卡尔复仇部队从凄凉之地而来。",kw={"旗帜","半人马","反击","十字路口","死门","科卡尔","克罗姆扎","雷戈萨"},ang={["faction:Horde"]="击败克罗姆扎并夺取他的旗帜，阻止了半人马的一次大规模进攻。杜隆塔尔、莫高雷和十字路口之间的北部道路已经安全了。",["race:Tauren"]="身为牛头人，你知道半人马的侵扰长期困扰着游牧部族。克罗姆扎的先锋部队已被消灭，通往莫高雷的小路也更安全了。"},sec={{t="半人马入侵的战利品",b="督军克罗姆扎率领一支战团从凄凉之地向东进发，展开反击。贫瘠之地各处的科卡尔酋长接连被杀，愤怒的半人马向十字路口以西的防御地堡发起了进攻。从克罗姆扎倒下的战旗上割下的一条布片，向雷戈萨·死门证明了这次进攻已被粉碎，部落南部的商路得以保全。"}},faq={{q="这块旗帜碎片有什么用？",a="把这块破布带给十字路口以西地堡里的雷戈萨·死门。它证明督军克罗姆扎已被击杀，他的劫掠部队已被击溃，贫瘠之地北部的防御战就此结束。",al={"旗帜用途","为什么保留旗帜","旗帜碎片怎么用"}},{q="督军克罗姆扎是谁？",a="克罗姆扎是一名来自凄凉之地的科卡尔指挥官。当地的科卡尔首领被杀后，他率军向部落哨站发起了正面反击。",al={"克罗姆扎是谁","克罗姆扎的故事","督军克罗姆扎"}},{q="科卡尔为什么进攻地堡？",a="巴拉克、维罗戈、赫兹鲁尔和其他当地酋长被杀后，愤怒的半人马从凄凉之地集结援军，向驻扎在十字路口以西的部落势力复仇。",al={"为什么反击","科卡尔入侵原因","贫瘠之地反击原因"}},{q="萨尔会得知这场胜利吗？",a="会的。雷戈萨·死门承诺将消息直接传给奥格瑞玛的大酋长萨尔，赞扬那些击退入侵的守卫者。",al={"萨尔奖励","萨尔知道吗"}}},fp="26,163,31.357.0,35.193.0,25.140.0,37.197.0,33.139.0"}
P.entries["item:plainstrider-beak"] = {n="陆行鸟的喙",s="在贫瘠之地各处，猎人们将陆行鸟的喙带回十字路口。狩猎大师以此为凭，确认威胁当地补给的鸟群已遭到捕杀。",h="在贫瘠之地各处，猎人们将陆行鸟的喙带回十字路口。狩猎大师以此为凭，确认威胁当地补给的鸟群已遭到捕杀。",kw={"贫瘠之地","十字路口","陆行鸟的喙","陆行鸟威胁","瑟格拉·黑棘","陆行鸟"},ang={["class:Hunter"]="作为猎人，在卡利姆多的开阔平原上猎杀陆行鸟并收集它们的喙，能让你初步学会如何潜行追踪并捕获猎物。",["faction:Horde"]="作为部落的一员，捕杀十字路口以东滋扰当地的鸟群，有助于保护为这座前哨站输送物资的贸易与补给路线。"},sec={{t="狩猎的凭证",b="陆行鸟在十字路口周围觅食，威胁着这里的补给。周围的草原上游荡着巨型平原陆行鸟、疾奔平原陆行鸟和暴躁的平原陆行鸟。瑟格拉·黑棘要求前来的猎人带回它们的喙，以证明补给线和仓库附近的鸟群已遭到捕杀。"}},faq={{q="瑟格拉·黑棘为什么需要陆行鸟的喙？",a="瑟格拉·黑棘要求猎人捕杀陆行鸟，因为这些鸟侵扰着十字路口周围的食物补给。它们的喙证明，这场狩猎减轻了当地补给面临的威胁。",al={"为什么收集鸟喙","瑟格拉 陆行鸟的喙任务","为什么要鸟喙"}},{q="哪些生物能提供这些喙？",a="猎人从游荡在贫瘠之地草原上的巨型平原陆行鸟、疾奔平原陆行鸟和暴躁的平原陆行鸟身上取得这些喙。",al={"什么掉落陆行鸟的喙","陆行鸟的喙来源","哪里获取鸟喙"}},{q="为什么并非每只被杀死的陆行鸟都能提供一枚喙？",a="这些鸟动作迅捷，挣扎时可能使喙开裂、破碎，或受损到无法作为完好的战利品。猎人只收集完整的喙。",al={"为什么掉率低","陆行鸟的喙不掉落"}}},fp="17,120,21.282.0,50.177.0,34.101.0,54.148.0"}
P.entries["item:plainstrider-feather"] = {n="平原陆行鸟的羽毛",s="在红云台地，年轻的猎人从游荡于莫高雷平原的鸟类身上收集平原陆行鸟的羽毛。纳拉其营地用这些羽毛制作衣物和部族饰品，以此向供养村落的生灵表达敬意。",h="在红云台地，年轻的猎人从游荡于莫高雷平原的鸟类身上收集平原陆行鸟的羽毛。纳拉其营地用这些羽毛制作衣物和部族饰品，以此向供养村落的生灵表达敬意。",kw={"纳拉其营地","羽毛","格鲁尔·鹰风","莫高雷","平原陆行鸟","红云台地","开始狩猎"},ang={["class:Hunter"]="身为猎人，在红云台地追踪敏捷的平原陆行鸟，考验着你的耐心和追踪本领，也教会你尊重猎物。",["race:Tauren"]="身为年轻的牛头人，收集平原陆行鸟的羽毛，能教会你珍惜Earth Mother的生灵，并充分利用猎物的每个部位来获取食物和衣物。"},sec={{t="猎人的初次献礼",b="红云台地的年轻牛头人学习追踪和狩猎，为部族获取所需之物。平原陆行鸟漫步在长满青草的台地上，提供食物和实用的羽毛。纳拉其营地用它们的羽毛制作衣物和装备。年轻的猎人将羽毛和鲜肉交给格鲁尔·鹰风，满足营地的需要。这份献礼是他们的第一项考验，通过后，鹰风酋长才会认可他们，并在雷霆崖迎接他们。"}},faq={{q="平原陆行鸟的羽毛有什么用途？",a="纳拉其营地用平原陆行鸟的羽毛制作衣物和仪式用品。格鲁尔·鹰风从年轻的猎人手中收集羽毛，补充部族的物资。",al={"羽毛用途","平原陆行鸟的羽毛用途","为什么收集羽毛"}},{q="谁在红云台地收集平原陆行鸟的羽毛？",a="年轻的猎人应格鲁尔·鹰风的要求，在红云台地收集平原陆行鸟的羽毛。他借此补充纳拉其营地的储备，并考验他们在供养部族时是否恪守职责。",al={"谁要羽毛","谁需要羽毛","格鲁尔·鹰风 羽毛"}},{q="哪里可以找到平原陆行鸟？",a="平原陆行鸟游荡在红云台地的开阔草地和莫高雷的草海平原上。",al={"哪里能找到平原陆行鸟","平原陆行鸟位置","羽毛采集"}},{q="格鲁尔·鹰风为什么需要这些羽毛来举行部族仪式？",a="在牛头人的文化中，狩猎既是谋生的手段，也是一项竞技活动。将肉和羽毛带回鹰风酋长那里，表明年轻的猎人在前往雷霆崖之前，已经具备供养部族的能力。",al={"开始狩猎 背景故事","牛头人狩猎考验","为什么猎杀平原陆行鸟"}}},fp="20,225,25.400.0,40.153.0,52.186.0,33.85.0,64.179.0"}
P.entries["item:plainstrider-kidney"] = {n="平原陆行鸟的肾脏",s="在贫瘠之地各处，猎人采集平原陆行鸟的肾脏，用于卡利姆多独特的酿酒传统。大多数旅人对这种内脏毫无胃口，但它却是酿制一种奇特酒液的必备原料。",h="在贫瘠之地各处，猎人采集平原陆行鸟的肾脏，用于卡利姆多独特的酿酒传统。大多数旅人对这种内脏毫无胃口，但它却是酿制一种奇特酒液的必备原料。",kw={"酿酒师德罗恩","老陈","平原陆行鸟","平原陆行鸟的肾脏","棘齿城","风暴烈酒","贫瘠之地"},ang={["class:Hunter"]="身为猎人，你必须在草原上小心处理平原陆行鸟的尸体，保持内脏完好，以便与棘齿城的酿酒师交易。",["profession:Cooking"]="身为厨师，你或许难以接受将鸟类肾脏发酵成美酒。在卡利姆多的荒野中，生存往往意味着充分利用猎物的每一个部位。"},sec={{t="非同寻常的酿酒原料",b="贫瘠之地广袤干旱的平原上，栖息着高大却不会飞的平原陆行鸟。猎人常取它们的羽毛和肉来制作工具和简单的口粮，而棘齿城的酿酒师德罗恩收集它们的内脏，却另有用途。德罗恩说，要重现老陈传说中酿造的烈性麦酒，就需要平原陆行鸟的肾脏。他声称，肾脏能赋予酒液独特的劲道，这一传统由一脉不拘常规的酿酒师代代相传。"}},faq={{q="平原陆行鸟的肾脏有什么用途？",a="棘齿城的酿酒师德罗恩需要平原陆行鸟的肾脏，来重现一批传说中的风暴烈酒麦酒。他说，他的导师直接从四处云游的熊猫人酿酒师老陈那里学到了配方。",al={"平原陆行鸟的肾脏用途","为什么需要平原陆行鸟的肾脏","平原陆行鸟的肾脏作用"}},{q="为什么有人会用动物内脏酿造麦酒？",a="卡利姆多的奇特酒液常以当地强健野生动物身上的部位为原料，赋予酒液浓烈难忘的风味和独特的劲道。酿酒师德罗恩说，调制这些浓烈奔放的配方，会让他愉快地想起穴居人酒之类不拘常规的佳酿。",al={"啤酒中的肾脏","风暴烈酒为什么要加肾脏","酒中的动物部位"}},{q="哪些生物能提供这些肾脏？",a="奔走于贫瘠之地的多种平原陆行鸟都能提供这些肾脏，包括行动迅捷、性情暴躁和体型较大的品种。",al={"哪里掉落平原陆行鸟的肾脏","谁掉落平原陆行鸟的肾脏","平原陆行鸟的肾脏来源"}},{q="除了肾脏，还需要哪些原料？",a="酿酒师德罗恩需要五个平原陆行鸟的肾脏、五根草原狮的獠牙和一个雷霆蜥蜴的角，才能完成他的调制。",al={"其他酿酒原料","德罗恩 还需要什么","风暴烈酒原料"}}},fp="19,181,32.415.0,39.198.0,46.215.0,36.86.0,56.126.0"}
P.entries["item:plainstrider-meat"] = {n="平原陆行鸟肉",s="在红云台地，平原陆行鸟肉是纳拉其营地的食物来源之一。年轻的牛头人猎取这些鸟的肉和羽毛，证明自己的本领和自立能力。",h="在红云台地，平原陆行鸟肉是纳拉其营地的食物来源之一。年轻的牛头人猎取这些鸟的肉和羽毛，证明自己的本领和自立能力。",kw={"纳拉其营地","鹰风酋长","格鲁尔·鹰风","莫高雷","平原陆行鸟","平原陆行鸟肉","红云台地","开始狩猎"},ang={["class:Hunter"]="身为猎人，你可以在莫高雷辽阔的平原上，以行动敏捷的平原陆行鸟检验自己的追踪本领和射术。",["race:Tauren"]="身为红云台地上的牛头人青年，猎取平原陆行鸟是你赢得鹰风酋长的尊重、获得踏入雷霆崖资格的最初几步之一。"},sec={{t="台地的食物来源",b="红云台地上的纳拉其营地依靠周围草原上的猎物维生。当食物储备不足时，平原陆行鸟肉便能为村民充饥。这些鸟的羽毛也用于制作衣物和仪式饰品。牛头人的生活依赖大地，要生存下去，就必须在尊重自然的同时，只取所需。"},{t="年轻猎人的试炼",b="格鲁尔·鹰风派年轻的猎人前往红云台地各处，追踪行动敏捷的平原陆行鸟。他们收集鸟肉和羽毛，证明自己的追踪本领和自立能力。随后，他们会去拜见格鲁尔的父亲，鹰风酋长。"}},faq={{q="平原陆行鸟肉有什么用途？",a="年轻的猎人在红云台地收集平原陆行鸟肉，替格鲁尔·鹰风补充纳拉其营地的食物储备。",al={"为什么需要平原陆行鸟肉","平原陆行鸟肉任务","平原陆行鸟肉的用途"}},{q="谁需要这些肉？",a="格鲁尔·鹰风让年轻的猎人猎取平原陆行鸟，补充部族的食物储备，同时证明自己有能力供养族人。",al={"谁需要平原陆行鸟肉","格鲁尔·鹰风鸟肉"}},{q="哪里能找到平原陆行鸟肉？",a="平原陆行鸟栖息在莫高雷的草原上，红云台地也有它们的踪迹，猎人会在那里猎取鸟肉。",al={"哪里获取平原陆行鸟肉","平原陆行鸟位置","收集平原陆行鸟肉"}},{q="为什么猎取平原陆行鸟对牛头人很重要？",a="牛头人猎取平原陆行鸟，既是为了获取食物，也是一种精神修行。将猎物带回营地，既表达了对大地母亲的敬意，也展现了自立和供养部族的能力。",al={"牛头人狩猎文化","为什么猎取平原陆行鸟"}}},fp="17,165,23.293.0,22.221.0,35.116.0,23.135.0,37.99.0,64.176.0"}
P.entries["item:plainstrider-scale"] = {n="平原陆行鸟的鳞片",s="在莫高雷各地，人们寻找平原陆行鸟的鳞片，供血蹄村的茂尔·祈雨配制药剂。这种坚韧的鳞片有助于遏制不断扩散的感染。",h="在莫高雷各地，人们寻找平原陆行鸟的鳞片，供血蹄村的茂尔·祈雨配制药剂。这种坚韧的鳞片有助于遏制不断扩散的感染。",kw={"血蹄村","茂尔·祈雨","马兹拉纳其","莫高雷","平原陆行鸟","药剂","鳞片","陆行鸟"},ang={["race:Tauren"]="作为一名Tauren，你学会从大地上采集药材，利用平原上的野生动物维系部族的生存。"},sec={{t="稀有的药材",b="平原陆行鸟漫步在莫高雷，强壮的双腿上覆盖着坚韧的鳞片。这些鳞片保护着它们，但只有部分鳞片足够坚实，可以磨碎后用于民间药方。"},{t="医治毒伤的药剂",b="血蹄村的茂尔·祈雨被马兹拉纳其咬伤了肩膀，那是一只传说中的陆行鸟，双眼泛着恶魔般的红光，撕咬带有剧毒。伤口让茂尔高烧不退，神志不清。为了在不断扩散的感染致命之前将其清除，他需要一片平原陆行鸟的鳞片、一颗狼心、一根平原狮的腿骨和一个猛鹫的胃。"}},faq={{q="平原陆行鸟的鳞片有什么用途？",a="血蹄村的茂尔·祈雨需要平原陆行鸟的鳞片来配制药剂。他将鳞片与莫高雷其他掠食动物的身体部位混合，用来医治马兹拉纳其的毒牙造成的感染伤口。",al={"平原陆行鸟的鳞片有什么作用","平原陆行鸟的鳞片用途","为什么需要平原陆行鸟的鳞片"}},{q="在哪里能找到平原陆行鸟的鳞片？",a="在莫高雷开阔的草原上游荡的野生平原陆行鸟身上，可以找到平原陆行鸟的鳞片。",al={"哪里获取平原陆行鸟的鳞片","如何获取平原陆行鸟的鳞片","平原陆行鸟的鳞片位置"}},{q="茂尔·祈雨为什么会受到感染？",a="茂尔·祈雨被马兹拉纳其咬伤了肩膀，那是一只双眼赤红、撕咬带毒的陆行鸟。伤口使他的高烧日益严重，神志也变得不清。",al={"茂尔怎么生病的","茂尔为什么生病","马兹拉纳其的撕咬"}},{q="茂尔配制药剂还需要哪些材料？",a="茂尔需要平原陆行鸟的鳞片、草原狼的心脏、平原狮的腿骨和猛鹫的胃来配制药剂。",al={"茂尔·祈雨的药材","医治马兹拉纳其毒伤的药剂","马兹拉纳其任务物品"}}},fp="18,142,17.156.0,28.325.1,40.203.0,39.85.0,32.167.0,53.115.0"}
P.entries["item:plainstrider-talon"] = {n="平原陆行鸟的爪子",s="在莫高雷各地，牛头人萨满祭司采集平原陆行鸟的爪子，用于制作净化图腾。这些锋利的爪子来自当地体型庞大、不会飞行的平原陆行鸟，能帮助净化被污染的水源。",h="在莫高雷各地，牛头人萨满祭司采集平原陆行鸟的爪子，用于制作净化图腾。这些锋利的爪子来自当地体型庞大、不会飞行的平原陆行鸟，能帮助净化被污染的水源。",kw={"血蹄村","净化图腾","莫高雷","穆尔·雷角","平原陆行鸟","平原陆行鸟的爪子","水源投毒","冰蹄水井"},ang={["class:Shaman"]="身为萨满祭司，你能看出牛头人的仪式如何利用利爪等野兽身体的部分，制作净化图腾，并从当地的自然之灵汲取力量。",["race:Tauren"]="身为牛头人，你通过狩猎向莫高雷野生动物的牺牲致敬。当地精的掠夺造成创伤时，每一头猎物都能帮助Earth Mother疗伤。"},sec={{t="平原的纽带",b="体型庞大、不会飞行的平原陆行鸟漫步在莫高雷开阔的草原上，用强健的双腿和锋利的爪子刨开坚硬的草原土壤觅食，并抵御捕食者。对血蹄村的牛头人而言，猎物身体的每个部分都蕴含着灵性的共鸣。当地精的经营活动污染了冰蹄水井等神圣水源后，萨满祭司穆尔·雷角开始寻求平原陆行鸟的爪子和草原狼的爪子。在牛头人的仪式制作中，取自当地捕食者和觅食动物的材料，将大地的灵性精华引入图腾，使其能够清除非自然的毒素。"}},faq={{q="哪些生物会掉落平原陆行鸟的爪子？",a="在莫高雷的草原上，成年平原陆行鸟、年老的平原陆行鸟，以及臭名昭著的陆行鸟马兹拉纳其都会掉落平原陆行鸟的爪子。",al={"谁掉落平原陆行鸟的爪子","哪里获得平原陆行鸟的爪子","平原陆行鸟的爪子来源"}},{q="平原陆行鸟的爪子有什么用途？",a="血蹄村的穆尔·雷角需要平原陆行鸟的爪子和草原狼的爪子来制作净化图腾，净化受到污染的冰蹄水井。",al={"平原陆行鸟的爪子用途","为什么需要爪子","平原陆行鸟的爪子任务"}},{q="为什么穆尔·雷角需要动物身体的部分来净化水源？",a="牛头人的萨满之道依靠与莫高雷的自然之灵和谐共处。将当地野生动物的力量凝聚于仪式图腾中，便能唤起大地的原始力量，对抗荆棘谷地精所属的地精带来的非自然污染物。",al={"为什么使用动物的脚爪和利爪","萨满净化仪式爪子"}},{q="是谁在莫高雷的水井中下毒？",a="在莫高雷活动的荆棘谷地精成员及其爪牙污染了部族的神圣水井。他们的行径破坏了当地环境，也威胁着牛头人各部族。",al={"谁污染了水井","谁在莫高雷水源中下毒","水源投毒元凶"}}},fp="18,188,19.568.0,41.136.0,38.171.0,63.212.0,40.189.0"}
P.entries["item:podrig-s-order"] = {n="博迪瑞格的订单",s="在瑟伯切尔，博迪瑞格的订单要求从幽暗城运来新武器。",h="在瑟伯切尔，博迪瑞格的订单要求从幽暗城运来新武器。",kw={"高顿·温德哈姆","哈德瑞克","卡洛斯·拉佐克","波德瑞格","博迪瑞格的订单","瑟伯切尔","银松森林"},ang={["profession:Blacksmithing"]="身为铁匠，你知道锻造的武器在前线有多么重要，那里的战斗不断消耗着驻军的物资。",["race:Undead"]="身为Undead，你能看到幽暗城如何为瑟伯切尔这样的前哨站提供补给，让黑暗女王的士兵有武器对抗Scourge。"},sec={{t="武装瑟伯切尔",b="亡灵卫兵博迪瑞格奉执行官哈德瑞克之命清点物资后，发现瑟伯切尔的大部分储备尚且充足。备用武器却已严重短缺。他的公文列出了驻守银松森林前哨站的亡灵卫兵所需的刀剑和其他武器，这片边疆正受到天灾军团、凶猛野兽和其他危险的威胁。"},{t="经蝙蝠管理员转交",b="订单将送往幽暗城贸易区的武器商高顿·温德哈姆手中，因为银松森林潮湿的墓穴让武器锻造十分困难。信使将文书交给蝙蝠管理员卡洛斯·拉佐克，借助被遗忘者的飞行路线，加快从首都运送武器的速度。"}},faq={{q="博迪瑞格的订单上写了什么？",a="博迪瑞格的订单列出了瑟伯切尔的亡灵卫兵所需的备用武器，他们原有的武器已在战地遗失或损坏。",al={"订单写了什么","博迪瑞格的订单内容","博迪瑞格订单详情"}},{q="博迪瑞格的订单是谁写的？",a="亡灵卫兵博迪瑞格清点瑟伯切尔的军械库后，遵照执行官哈德瑞克的指示写下了这份订单。",al={"谁写的","博迪瑞格订单作者"}},{q="谁会收到这份订单？",a="这份订单的收件人是幽暗城贸易区的武器商高顿·温德哈姆。",al={"谁收到订单","博迪瑞格订单送往哪里","博迪瑞格订单收件人"}},{q="瑟伯切尔为什么需要新武器？",a="亡灵卫兵需要新武器，因为在银松森林与天灾军团及其他敌对势力的交战中，他们的装备经常损坏或遗失。",al={"为何需要武器","瑟伯切尔武器短缺"}}},fp="14,82,20.335.0,24.268.0,34.124.0,25.121.0,23.96.0,40.152.0"}
P.entries["item:pork-belly-pie"] = {n="猪肉馅饼",s="在艾尔文森林，比利·马科伦正等着斯通菲尔德农场送来的馅饼，吃到后才肯透露一条失踪项链的线索。尽管两家积怨已久，波尼斯大婶还是烤了馅饼。",h="在艾尔文森林，比利·马科伦正等着斯通菲尔德农场送来的馅饼，吃到后才肯透露一条失踪项链的线索。尽管两家积怨已久，波尼斯大婶还是烤了馅饼。",kw={"波尼斯 斯通菲尔德大婶","回去找比利","比利·马科伦","艾尔文森林","马科伦","猪肉馅饼","斯通菲尔德"},ang={["faction:Alliance"]="对于在艾尔文乡间帮忙的联盟旅人来说，送馅饼这件事揭示了暴风城农业腹地根深蒂固的纷争。",["profession:Cooking"]="即使两家结有世仇，波尼斯大婶亲手烤的馅饼依然有着不小的影响力，不过她的配方仍是个秘密。"},sec={{t="世仇农场间的贿赂",b="斯通菲尔德家族和马科伦家族多年来一直为了土地和颜面争吵。年幼的比利·马科伦对波尼斯大婶的猪肉馅饼毫无抵抗力。斯通菲尔德家一条贵重的传家项链失踪后，比利不肯说出自己知道的事，非要冒险者给他带来一块热乎乎的馅饼才肯开口。波尼斯不情愿地烤了馅饼，恨不得这个贪吃的小子被馅饼噎住。"}},faq={{q="猪肉馅饼有什么用？",a="波尼斯·斯通菲尔德大婶烤这个馅饼，是为了让年幼的比利·马科伦开口。他知道一些关于斯通菲尔德家传家项链失踪的事，但非要吃到她做的食物才肯说。",al={"馅饼用途","为什么要猪肉馅饼","馅饼怎么用"}},{q="猪肉馅饼是谁烤的？",a="波尼斯·斯通菲尔德大婶在斯通菲尔德农场烤制这个馅饼。她厌恶比利·马科伦和他的家人，但为了找回自家丢失的项链，还是做了馅饼。",al={"谁做的馅饼","烤馅饼的人","斯通菲尔德老奶奶的馅饼"}},{q="比利·马科伦为什么想吃仇家做的食物？",a="尽管斯通菲尔德家和马科伦家结有世仇，比利·马科伦还是想吃波尼斯大婶做的食物。比起记着家族的仇怨，他更想吃猪肉馅饼。",al={"比利为什么想吃馅饼","马科伦为什么想吃斯通菲尔德家的食物"}},{q="玩家能吃猪肉馅饼吗？",a="不能。这个馅饼是给比利·马科伦的，无法通过食用来恢复生命值或法力值。",al={"能吃吗","猪肉馅饼能吃吗"}}},fx={["6505ed9f"]={q="猪肉馅饼是什么？",a="这是一种用五花肉烘烤的咸味肉馅饼，尽管艾尔文森林南部的两户农家积怨甚深，它仍以美味闻名。这种刚从斯通菲尔德家的厨房出炉的馅饼，是诱使马科伦家的男孩比利吐露消息的诱人贿赂，因为他声称只有填饱肚子才能想起事情。",al={"猪肉馅饼是什么","猪肉馅饼背景故事","关于猪肉馅饼"}}},fp="14,167,29.366.0,36.188.0,29.161.0,53.181.0,35.85.0"}
P.entries["item:powdered-azurite"] = {n="蓝铜粉",s="在希尔斯布莱德丘陵，蓝铜粉取自碧玉矿洞。索恩格瑞姆·火眼需要它来为崭露头角的部落战士锻造凶悍的护甲。",h="在希尔斯布莱德丘陵，蓝铜粉取自碧玉矿洞。索恩格瑞姆·火眼需要它来为崭露头角的部落战士锻造凶悍的护甲。",kw={"碧玉矿洞","蓝铜矿","野蛮护甲","希尔斯布莱德","蓝铜粉","试剂","索恩格瑞姆·火眼"},ang={["class:Warrior"]="身为战士，远赴异地采集蓝铜粉既能考验你的耐力，也能为索恩格瑞姆·火眼带来所需的试剂，让他为你锻造蕴含野蛮力量的护甲。",["faction:Horde"]="身为部落的一员，夺取这种精制粉末意味着深入东部王国，从希尔斯布莱德丘陵的联盟手中夺走资源。"},sec={{t="稀有的矿物化合物",b="蓝铜粉来自希尔斯布莱德丘陵地下的矿脉。人类工人从碧玉矿洞中开采蓝色矿石，再将其研磨、包装，用于贸易和金属加工。技艺娴熟的铁匠将这种粉末与致密的金属混合，让护甲更加坚固耐用。"},{t="锻造野蛮护甲",b="部落铁匠看重蓝铜粉在金属加工中增强强度的作用，尽管它来自无尽之海彼岸由人类控制的矿道。索恩格瑞姆·火眼是贫瘠之地一位年迈的兽人护甲匠，他需要少量蓝铜粉，以及精炼的铁和火焰试剂。将这种粉末掺入熔融的金属后，他便能锤打出野蛮护甲的厚重甲片。"}},faq={{q="蓝铜粉有什么用途？",a="索恩格瑞姆·火眼将蓝铜粉与铁锭和不稳定的试剂配合使用，为部落勇士锻造野蛮护甲的各个部件。",al={"蓝铜粉用途","蓝铜粉是什么"}},{q="哪里可以找到蓝铜粉？",a="人类矿工在碧玉矿洞中采集蓝铜粉，那里位于东部王国希尔斯布莱德丘陵的南部海岸。",al={"哪里找蓝铜粉","蓝铜粉位置","谁掉落蓝铜粉"}},{q="贫瘠之地的护甲匠为什么需要希尔斯布莱德的试剂？",a="索恩格瑞姆·火眼寻求上等材料，用来打造配得上传奇战士的护甲。铁很容易找到，但碧玉矿物在淬炼中的特性，值得他派遣勇士渡海获取。",al={"为什么是希尔斯布莱德","索恩格瑞姆矿物来源"}}},fp="16,168,23.218.0,20.366.0,34.133.0,36.128.0,67.193.0"}
P.entries["item:powers-of-the-void"] = {n="虚空灵能",s="在北郡，一本被盗的典籍引起了杜希拉·拉萨雷的注意。一名准备投奔迪菲亚潜行者的修士学徒离开时，从北郡修道院图书馆有人看守的侧厅偷走了《虚空灵能》。杜希拉想用这本书研究黑暗魔法。",h="在北郡，一本被盗的典籍引起了杜希拉·拉萨雷的注意。一名准备投奔迪菲亚潜行者的修士学徒离开时，从北郡修道院图书馆有人看守的侧厅偷走了《虚空灵能》。杜希拉想用这本书研究黑暗魔法。",kw={"迪菲亚潜行者","杜希拉·拉萨雷","小鬼","卡德加","北郡修道院","虚空灵能","被盗书籍","被盗的典籍","术士"},ang={["class:Warlock"]="身为术士，找回被盗典籍的任务将考验你的意志，看你是否有资格学习召唤小鬼。",["race:Human"]="身为人类，你可以看到，北郡的Holy Order将危险的魔法记录与教务文献一同保存，不让修士学徒接触。"},sec={{t="北郡的禁书",b="《虚空灵能》原本存放在北郡修道院图书馆有人看守的书架深处。修道院的档案中既有神圣经文和教务记录，也有研究暗影与虚空能量的学术著作。相传，这部典籍出自大法师卡德加之手。书中的内容十分危险，因此修道院的管理者派人看守，不让普通访客接触。如此一来，北郡的术士导师杜希拉·拉萨雷若想翻阅它，就难免引起教士们的怀疑。"},{t="迪菲亚的盗窃与追索",b="一名北郡的修士学徒背弃誓言、投奔迪菲亚潜行者时，带走了这部典籍。他逃往附近的葡萄园时，从修道院偷走了几本珍贵的书籍。杜希拉派有潜力的术士学徒前往迪菲亚强盗营地，从他们的帐篷里找回这本书。她想用书中的黑暗知识开展自己的研究。这项任务考验着学徒是否有胆量束缚异界的恶魔。"}},faq={{q="《虚空灵能》是什么？",a="《虚空灵能》是一本研究暗影与虚空能量的稀有秘术典籍，相传出自大法师卡德加之手。被盗之前，这部典籍存放在北郡修道院图书馆有人看守的侧厅。",al={"虚空灵能是什么","虚空灵能书籍","被盗的典籍是什么"}},{q="这本书为什么被锁在北郡修道院？",a="北郡修道院保存着历史档案，其中包括记载禁忌魔法的危险典籍。有关虚空能量与恶魔学识的书籍都被锁藏起来，以免遭到修士学徒和误入歧途的施法者滥用。",al={"为什么存放在修道院","牧师为什么保管这本书","北郡图书馆侧厅"}},{q="迪菲亚潜行者是怎么得到这本书的？",a="北郡修道院的一名修士学徒叛逃，加入了迪菲亚潜行者，并从禁止随意出入的图书馆中带走了几本珍贵的书籍。他把这些书藏在了北郡农场的强盗营地里。",al={"谁偷走了书","迪菲亚被盗书籍","迪菲亚怎么得到这本书"}},{q="杜希拉·拉萨雷为什么想要《虚空灵能》？",a="杜希拉·拉萨雷想用这部典籍中的知识钻研自己的黑暗法术。身为北郡的术士导师，她若进入修道院有人看守的图书馆，就会引起怀疑。",al={"杜希拉为什么想要这本书","谁想要这本书","杜希拉·拉萨雷被盗典籍"}},{q="找回典籍能向杜希拉证明什么？",a="找回典籍能考验学徒是否有胆量束缚恶魔。杜希拉会先用这项任务考验他们，再教他们召唤自己的第一个小鬼。",al={"术士为什么需要这本书","召唤小鬼考验","被盗典籍奖励"}}},fx={["082e56cb"]={q="《虚空灵能》是谁写的？",a="这部奥术论著据说出自传奇大法师卡德加之手，他在穿越黑暗之门前，曾研究过许多深奥而危险的魔法领域。书中关于虚空深处的禁忌知识被认为过于危险，不宜随意翻阅，因此北郡修道院的牧师和学者将其封存在图书馆一处受到保护的侧厅，直到一名背信弃义的学徒将它偷走。",al={"虚空灵能作者","谁写了虚空灵能","虚空灵能创作者"}}},fp="18,251,28.476.0,25.427.0,27.217.0,47.198.0,44.183.0,51.175.0,48.147.0"}
P.entries["item:prairie-alpha-tooth"] = {n="草原狼前锋的牙齿",s="在雷霆崖周围，草原狼前锋 游荡在莫高雷开阔的平原上。穆尔·雷角需要它们的牙齿来净化蛮鬃之井。",h="在雷霆崖周围，草原狼前锋 游荡在莫高雷开阔的平原上。穆尔·雷角需要它们的牙齿来净化蛮鬃之井。",kw={"血蹄村","莫高雷","穆尔·雷角","草原狼前锋的牙齿","草原狼前锋","水井","蛮鬃图腾"},ang={["class:Shaman"]="身为萨满祭司，你通过维系大地的平衡来安抚水井之灵。献上顶级掠食者的獠牙，便能稳固这份自然的和谐。",["race:Tauren"]="身为牛头人，取下一颗 prairie alpha 的獠牙，就是履行猎手的神圣职责：怀着敬意获取所需之物，并将那份原始精华归还大地，治愈遭到毒害的土地。"},sec={{t="净化的祭品",b="莫高雷的水井滋养着牛头人，要保持井水纯净，就需要举行表达敬意与牺牲的仪式。血蹄村的穆尔·雷角需要在雷霆崖下游荡的 草原狼前锋 的牙齿，来净化蛮鬃之井。这些凶猛的狼群首领体现着荒野的力量。献上它们的牙齿，是对猎手、猎物与大地之灵之间平衡的敬重。"}},faq={{q="草原狼前锋的牙齿有什么用途？",a="穆尔·雷角会在仪式中使用八颗草原狼前锋的牙齿，净化蛮鬃之井，那是血蹄村附近最后一口受到污染的水井。",al={"首领牙齿用途","莫高雷狼牙用途","蛮鬃图腾物品"}},{q="草原狼前锋 在哪里游荡？",a="草原狼前锋 游荡在莫高雷中部和北部开阔的草原上，尤其是雷霆崖脚下的崖壁周围。",al={"草原狼前锋 在哪里","首领狼位置","草原狼前锋出没地点"}},{q="为什么净水仪式需要狼牙？",a="牛头人的仪式尊崇自然的平衡。净化需要从莫高雷凶猛的本土野兽身上取下神圣的部分，象征着牺牲与当地野生动物的生命力。",al={"净水为什么需要狼牙","穆尔·雷角牙齿仪式背景"}}},fp="19,134,20.357.0,39.147.0,34.146.0,53.169.0"}
P.entries["item:prairie-wolf-heart"] = {n="草原狼的心脏",s="血蹄村的茂尔·祈雨需要一颗草原狼的心脏，用来配制解毒药。",h="血蹄村的茂尔·祈雨需要一颗草原狼的心脏，用来配制解毒药。",kw={"血蹄村","茂尔·祈雨","马兹拉纳其","莫高雷","草原捕食者","草原狼的心脏","狼心"},ang={["class:Hunter"]="身为猎人，你会学习追踪在莫高雷平原上捕猎的狼群，并了解栖息在那里的野兽。",["race:Tauren"]="身为牛头人，你知道动物的身体部位可以用来配制实用的药物，帮助你在莫高雷的荒野中生存。"},sec={{t="毒伤的解药",b="茂尔·祈雨住在血蹄村，正饱受传说中的平原陆行鸟马兹拉纳其的毒液折磨。咬伤引发了高烧，毒素随时可能蔓延全身。茂尔正在寻找草原狼的心脏，以及美洲狮的骨头和鸟胃，用来配制草原上的传统药方，希望在谵妄致命之前阻止感染。"}},faq={{q="草原狼的心脏有什么用途？",a="血蹄村的茂尔·祈雨需要一颗草原狼的心脏来配制民间药方。他将它与其他动物器官混合，用来治疗马兹拉纳其造成的毒伤。",al={"狼心用途","为什么获取狼心","草原狼的心脏用途"}},{q="在哪里可以获得草原狼的心脏？",a="草原狼、草原狼前锋和草原捕食者在莫高雷的平原上捕猎，从它们的尸体上可以取得心脏。",al={"狼心位置","谁掉落狼心","如何找到草原狼的心脏"}},{q="茂尔·祈雨为什么需要动物器官来治疗伤口？",a="马兹拉纳其造成的咬伤发生感染，引发了高烧和谵妄。茂尔依靠牛头人的草原药方，用狼心、山狮腿骨、平原陆行鸟的鳞片和猛鹫的胃来清除感染，以免危及性命。",al={"为什么用狼心制药","茂尔的药方"}},{q="任何狼的心脏都能用来配制这种药吗？",a="茂尔要的是一颗狼心。他配药所需的心脏来自莫高雷平原上的草原狼、草原狼前锋或草原捕食者。",al={"任意狼心","哪些狼掉落狼心"}}},fp="18,89,28.330.0,38.170.0,43.121.0,63.220.0,42.143.0"}
P.entries["item:prairie-wolf-paw"] = {n="草原狼的爪子",s="在莫高雷各地，人们从猎食平原的狼身上收集草原狼的爪子。血蹄村的穆尔·雷角将它们与陆行鸟的爪子一起用来制作净化图腾。",h="在莫高雷各地，人们从猎食平原的狼身上收集草原狼的爪子。血蹄村的穆尔·雷角将它们与陆行鸟的爪子一起用来制作净化图腾。",kw={"血蹄村","莫高雷","穆尔·雷角","平原陆行鸟的爪子","水源投毒","草原狼","草原狼的爪子","冰蹄水井"},ang={["class:Shaman"]="用当地动物的身体部位制成的净化图腾，汲取大地的生命精华，清除违背自然的腐化。",["race:Tauren"]="对牛头人而言，收集狼爪是一项守护大地的庄严职责：大地上的原生野兽帮助净化先祖的水井，治愈地精贪婪所造成的污染。"},sec={{t="平原上的天然材料",b="草原狼 在莫高雷起伏的草原上成群猎食，与 草原捕食者 和狼群首领一同出没。它们威胁着年轻的猎人和当地的牲畜，而它们在平原灵性平衡中的地位，对牛头人萨满祭司而言十分重要。在萨满祭司眼中，狼爪不仅是战利品：它们蕴含着大地与生俱来的生命力。"},{t="净化水井",b="当地精的经营活动污染了莫高雷的神圣水源时，萨满祭司穆尔·雷角需要借助大地的有形之物来对抗污染。狼爪与陆行鸟的爪子结合，为净化图腾提供灵性的共鸣。制成图腾后，便能开始净化冰蹄水井。"}},faq={{q="哪些生物掉落草原狼的爪子？",a="草原狼、草原捕食者 和 草原狼前锋 在莫高雷的平原上猎食，主要出没于血蹄村西南方，它们都能提供草原狼的爪子。",al={"谁掉落草原狼的爪子","哪里获取草原狼的爪子","草原狼的爪子来源"}},{q="谁需要草原狼的爪子？",a="血蹄村的牛头人萨满祭司穆尔·雷角需要它们，帮助制作净化图腾，用来净化受到污染的水井。",al={"谁需要草原狼的爪子","穆尔·雷角 狼爪","草原狼的爪子交给谁"}},{q="为什么净化水源需要狼爪？",a="牛头人萨满祭司引导大地的自然生命力来对抗腐化。狼爪与鸟爪结合，帮助将莫高雷的鲜活之灵凝聚在元素图腾中，以清除地精的毒素。",al={"为什么需要狼爪","草原狼的爪子背景故事","穆尔·雷角为何需要爪子"}},{q="这些爪子能帮助净化哪口水井？",a="这些爪子用于制作净化图腾，帮助净化被地精入侵者及其爪牙投毒的冰蹄水井。",al={"哪口水井","冰蹄水井净化"}}},fp="16,198,30.301.0,19.306.0,39.155.0,28.130.0,42.193.0,44.116.0"}
P.entries["item:pridewing-venom-sac"] = {n="巨翼双足飞龙的毒囊",s="阿斯特兰纳的暗夜精灵正在搜集暗色湖周围的巨翼双足飞龙的毒囊。据报告，部落密探采集这些毒液，用于秘密袭击，哨兵 决心切断他们的毒液来源。",h="阿斯特兰纳的暗夜精灵正在搜集暗色湖周围的巨翼双足飞龙的毒囊。据报告，部落密探采集这些毒液，用于秘密袭击，哨兵 决心切断他们的毒液来源。",kw={"阿斯特兰纳","暗色湖","风翼","辛德瑞尔·速火","石爪山","毒囊","双足飞龙"},ang={["faction:Alliance"]="阻止部落密探获取 pridewing 的毒液，有助于保护在石爪山和灰谷争议边界一带巡逻的边境巡逻队，使他们免遭暗处刺客的袭击。",["race:NightElf"]="身为暗夜精灵，你或许会为不得不猎杀无辜的野兽感到惋惜，但保护精灵的生命免遭淬毒刀刃的伤害更为紧要。"},sec={{t="峭壁间的威胁",b="巨翼双足飞龙 在灰谷以南的峭壁间猎食，尤其常见于暗色湖周围。这些空中的掠食者原生于石爪山脉，从它们体内的腺体中可以采集毒液。来自塞拉摩的报告表明，部落刺客正用这种毒液涂抹刀刃，秘密袭击暗夜精灵的定居点。在阿斯特兰纳，哨兵 派遣斥候猎杀这些双足飞龙，赶在部落密探之前收集它们的毒腺。"}},faq={{q="哪些生物会掉落巨翼双足飞龙的毒囊？",a="暗色湖周围的 幼年雄性风巢飞龙、雄性风巢飞龙捕猎者、雄性风巢飞龙族长 和 雌性风巢飞龙 会掉落这些毒囊。",al={"哪里获取巨翼双足飞龙的毒囊","谁掉落巨翼双足飞龙的毒囊","巨翼双足飞龙 毒液来源"}},{q="阿斯特兰纳为什么需要巨翼双足飞龙的毒囊？",a="辛德瑞尔·速火收到报告，称部落密探将 雄性风巢飞龙 的毒液涂在武器上，悄无声息地袭击联盟。收缴或摧毁这些毒腺可以阻止此类袭击。",al={"为什么收集毒囊","辛德瑞尔·速火 毒液"}},{q="灰谷的谁会收取这些毒囊？",a="辛德瑞尔·速火在灰谷的暗夜精灵城镇阿斯特兰纳收集这些毒囊，保护她的人民免遭秘密袭击。",al={"谁收取 巨翼双足飞龙 毒液","巨翼双足飞龙 任务交付"}},{q="雄性风巢飞龙 天生就与部落结盟吗？",a="不是。暗色湖周围的 雄性风巢飞龙 是野兽，并非自愿与部落结盟。兽人密探利用它们的毒液进行战争。",al={"巨翼双足飞龙 属于部落吗","巨翼双足飞龙 为兽人效力吗"}}},fx={e2bba8d5={q="什么是巨翼双足飞龙的毒囊？",a="巨翼双足飞龙的毒囊是一种从栖息在石爪山脉的巨翼双足飞龙身上采集的器官，其中含有这些长翼掠食者用来制服猎物的强效天然毒素。在暗夜精灵与部落脆弱的对峙中，这种毒液已成为备受青睐的秘密袭击武器，阿斯特兰纳的守卫因此提高了警惕。",al={"巨翼双足飞龙的毒囊是什么","巨翼双足飞龙的毒囊物品","巨翼双足飞龙的毒囊有哪些"}},["816b56c2"]={q="巨翼双足飞龙的毒囊来自哪里？",a="这些毒囊直接取自巨翼双足飞龙的身体——它们是凶猛的野生双足飞龙，栖居在石爪山脉的暗色湖附近。毒囊是野兽自身产生的天然器官，并非人工制品，因此必须在峭壁间猎杀双足飞龙，并赶在部落特工采集之前取出毒液。",al={"巨翼双足飞龙的毒囊来源","巨翼双足飞龙的毒囊来自哪里","哪些生物掉落巨翼双足飞龙的毒囊"}}},fp="19,193,21.446.0,43.97.0,45.181.0,42.133.0,51.133.0"}
P.entries["item:prismatic-punch-card"] = {n="彩色穿孔卡片",s="在诺莫瑞根，彩色穿孔卡片拥有最高安全权限。铁炉堡的侏儒难民正在寻找它能解锁的档案。",h="在诺莫瑞根，彩色穿孔卡片拥有最高安全权限。铁炉堡的侏儒难民正在寻找它能解锁的档案。",kw={"卡斯派普","抢救数据","工程实验室","诺莫瑞根","矩阵式打孔计算机","彩色穿孔卡片"},ang={["profession:Engineering"]="作为工程师，你能从按顺序处理的穿孔卡片编程和自动化终端网络中，看出诺莫瑞根工匠制造的计算机械达到了怎样的高超水准。",["race:Gnome"]="作为侏儒，你能从打孔计算机安全系统中看到，即使家园已经陷落，侏儒的聪明才智和官僚制度仍在运作。"},sec={{t="安全问题",b="侏儒逃离诺莫瑞根时，穴居人和有毒辐射将他们赶出了这座城市。大量研究资料和市政档案仍留在城内深处。侏儒设置了层层权限，保护高级系统。要使用位于下层工程实验室的矩阵式打孔计算机 3005-D，卡片必须经过一系列终端处理。\n\n卡片最初是白色，随后依次升级为黄色、蓝色和红色。在最后一台终端上，它会被打孔制成彩色穿孔卡片。卡片上编码的权限等级被标注为：有待发明一个全新的数字来表示。"},{t="至关重要的传讯",b="大机械师卡斯派普从铁炉堡的难民聚居区派遣冒险者，前往诺莫瑞根受到污染的大厅，取回他声称至关重要、不可或缺的数据。彩色穿孔卡片上的二进制信息揭示了传讯的内容：有人通知卡斯派普，他送洗的衣物已经可以领取了。"}},faq={{q="如何制作彩色穿孔卡片？",a="将一张红色穿孔卡片插入诺莫瑞根下层工程实验室的矩阵式打孔计算机 3005-D。首先，需要在遍布城内的A型、B型和C型终端上，依次升级一张白色穿孔卡片。",al={"如何获得彩色穿孔卡片","制作彩色穿孔卡片","穿孔卡片升级顺序"}},{q="彩色穿孔卡片储存了什么数据？",a="卡片注明，其安全等级有待发明一个新的数字来表示，后面还附有一长串二进制代码。大机械师卡斯派普说，这些数据至关重要。",al={"卡片上写了什么","穿孔卡片二进制翻译","解码后的穿孔卡片"}},{q="谁想要彩色穿孔卡片？",a="大机械师卡斯派普是一名流亡铁炉堡的侏儒工程师，他在抢救数据任务中要求取得这张卡片。他说，卡片中保存着侏儒撤离诺莫瑞根时遗留的紧急情报，价值不可估量。",al={"彩色穿孔卡片交给谁","卡斯派普任务","谁需要卡片"}},{q="矩阵式打孔计算机终端位于何处？",a="这些终端按照权限等级分布在诺莫瑞根各处。打孔计算机 3005-A位于靠近地表的列车站和车间入口附近。B型终端位于清洁区后方的宿舍，C型终端位于城内更深处，D型终端则位于下层工程实验室。",al={"终端位置","打孔计算机在哪里","在哪里给卡片打孔"}}},fx={f4168582={q="彩色穿孔卡片是什么？",a="彩色穿孔卡片是诺莫瑞根内部计算系统生成的一种数据卡，拥有极高的访问权限。据说，它的自动安全分级高得连侏儒数学都还没创造出足以描述它的数字。实际上，它储存着城市深处终端生成的二进制编码文本，是侏儒分级数据检索流程的最高一级。",al={"彩色穿孔卡片是什么","彩色穿孔卡片背景故事","诺莫瑞根彩色卡片"}},["7551673e"]={q="彩色穿孔卡片来自哪里，由谁制造？",a="这种卡片产自沦陷的诺莫瑞根深处，由位于工程实验室下层的高安全级别自动终端矩阵式打孔计算机 3005-D生成。它并非由人手工制作，而是在使用者将经过适当升级的红色穿孔卡片送入装置后，由侏儒的机械化网络编码生成。",al={"彩色穿孔卡片起源","谁制造了彩色穿孔卡片","彩色穿孔卡片获取地点"}}},fp="20,134,20.538.0,22.316.1,41.204.0,48.169.1,35.200.0,51.268.0"}
P.entries["item:pristine-spider-silk"] = {n="新鲜的蜘蛛丝",s="暮色森林的毒蜘蛛产出的细线，是暴风城法师制作能承受附魔的长袍所需的材料。",h="暮色森林的毒蜘蛛产出的细线，是暴风城法师制作能承受附魔的长袍所需的材料。",kw={"黑寡妇幼蛛","腐肉潜伏者","暮色森林","法师长袍","新鲜的蜘蛛丝","巫师圣殿","维恩·拉尔森"},ang={["class:Mage"]="身为暴风城的法师，你受命前往暮色森林采集这种细线，并赢得一件与你日益精进的奥术造诣相称的长袍。",["profession:Tailoring"]="身为裁缝，你使用的是从致命蜘蛛身上采集的纤细而坚韧的丝线。这是制作魔法长袍的优质天然纺织原料。"},sec={{t="编织奥术",b="暴风城的法师需要足够坚韧的丝线，既能承受附魔，又经得起学徒日常穿用。裁缝通常使用普通蜘蛛丝，但暮色森林的 食腐独行蛛 和 黑寡妇幼蛛 产出的丝线更加坚韧。巫师圣殿 的法师会派正在成长的学徒前往那片森林采集蛛丝。随后，裁缝大师维恩·拉尔森会用这些蛛丝为学徒织成一件长袍。"}},faq={{q="新鲜的蜘蛛丝来自哪里？",a="新鲜的蜘蛛丝来自暮色森林的 腐肉潜伏者 和 黑色小蜘蛛。",al={"哪里获取新鲜的蜘蛛丝","谁掉落新鲜的蜘蛛丝","新鲜的蜘蛛丝位置"}},{q="谁用这些蛛丝制作衣物？",a="维恩·拉尔森是暴风城法师区的制衣师，她用采集来的蛛丝为 巫师圣殿 织成长袍。",al={"谁使用新鲜的蜘蛛丝","谁用蛛丝制作长袍","维恩·拉尔森长袍"}},{q="法师为什么需要这种特定的蛛丝？",a="法师需要足够坚韧的蛛丝，让学徒的长袍既能承受附魔，又经得起穿用。暮色森林的蜘蛛产出的蛛丝具备所需的强度和品质。",al={"为何使用新鲜蛛丝","魔法蜘蛛丝用途"}}},fx={dfaa8e27={q="新鲜的蜘蛛丝是什么？",a="新鲜的蜘蛛丝是出没于暮色森林的蛛形生物吐出的丝，格外纤细，洁净无瑕。阴暗森林的树木上常粘着破损的普通蛛网，但只有最纯净、毫无瑕疵的丝缕才符合要求。制衣师和巫师十分珍视它出众的品质与质地，将其作为必要的基础织料，缝制适合法师修习时穿着的精美衣物。",al={"新鲜的蜘蛛丝","新鲜的蜘蛛丝是什么","新鲜的蜘蛛丝物品"}}},fp="20,108,18.366.0,42.88.0,35.120.0,44.157.0"}
P.entries["item:prowler-claws"] = {n="徘徊者的爪子",s="在贫瘠之地各处，猎手们将徘徊者的爪子带回十字路口，交给瑟格拉·黑棘。这些爪子证明，猎手能够追踪并击败潜行于平原上的徘徊者。",h="在贫瘠之地各处，猎手们将徘徊者的爪子带回十字路口，交给瑟格拉·黑棘。这些爪子证明，猎手能够追踪并击败潜行于平原上的徘徊者。",kw={"贫瘠之地","十字路口","徘徊者的爪子","贫瘠之地的徘徊者","草原徘徊者","瑟格拉·黑棘"},ang={["class:Hunter"]="身为猎人，追踪savannah prowlers并取得它们的爪子，考验着你的潜行、追踪以及近距离应对野兽的本领。",["faction:Horde"]="身为部落的一员，协助猎杀十字路口周围的徘徊者，能够保护卡利姆多中部道路上的信使、商队和定居者。"},sec={{t="潜行猎手的战利品",b="徘徊者藏在贫瘠之地的高草中，耐心而狡诈地等待出击的时机。与吃草的平原陆行鸟和斑马不同，这些大型猫科野兽会伏击踏入其猎场的生物。要取得它们弯曲的爪子，就得面对依靠潜行、捍卫领地的掠食者。对部落的战士和斥候而言，这场狩猎考验着他们能否在潜行猎手的领地内追踪它，并将它变成猎物。"},{t="女猎手所需的证明",b="十字路口的女猎手瑟格拉·黑棘要求初来者先带回徘徊者的爪子，再接受更艰巨的试炼。这些爪子证明，猎手能够循着足迹穿过草原，并抵挡掠食者的攻击。带着爪子归来的人，已经证明自己能在平原上的危险野兽之间保持警惕。"}},faq={{q="在哪里可以获得徘徊者的爪子？",a="徘徊者出没于贫瘠之地中部的草原，尤其是十字路口西南方的平原。取下它们的爪子并带回来。",al={"徘徊者的爪子位置","如何获得徘徊者的爪子","哪里能找到徘徊者的爪子"}},{q="谁需要这些爪子，为什么？",a="十字路口经验丰富的女猎手瑟格拉·黑棘需要七个徘徊者的爪子。将爪子交给她，考验的是你追踪危险掠食者并与之战斗的能力。",al={"谁需要徘徊者的爪子","交付徘徊者的爪子","瑟格拉爪子任务"}},{q="为什么猎杀徘徊者是一项重要的考验？",a="徘徊者是善于潜行的食肉野兽，会从高大的灌木丛中悄悄跟踪旅人和猎物。猎杀它们，考验的是你能否避开伏击，并击败狡诈而致命的野兽。",al={"为什么猎杀徘徊者","徘徊者危险吗"}}},fp="13,154,23.425.0,22.323.0,29.143.0,30.170.0,56.179.0"}
P.entries["item:pure-hearts"] = {n="纯洁的心",s="在幽暗城，纯洁的心能从扭曲虚空引来魅魔。凯伦丁·哈加尔将这些仪式材料交给被遗忘者术士，供他们召出恶魔，并尝试击败她、将她束缚。",h="在幽暗城，纯洁的心能从扭曲虚空引来魅魔。凯伦丁·哈加尔将这些仪式材料交给被遗忘者术士，供他们召出恶魔，并尝试击败她、将她束缚。",kw={"凯伦丁·哈加尔","魔法区","纯洁的心","魅魔","召唤","誓缚","幽暗城"},ang={["class:Warlock"]="身为术士，使用纯洁的心标志着你在恶魔学识上的一个转折，也证明了你抵御扭曲虚空诱惑的意志力。",["race:Undead"]="身为Undead，你利用未受玷污的心来操纵恶魔的欲望。这种冷酷而务实的巫术正是被遗忘者行事方式的体现。"},sec={{t="引诱虚空的饵料",b="凯伦丁·哈加尔将纯洁的心交给在幽暗城魔法区召唤魅魔的术士。这些未受玷污的灵魂精华被放在召唤法阵上，引诱恶魔穿越扭曲虚空，进入凡人的世界。魅魔一旦现身，术士就必须抵御她蛊惑心智的魅惑法术，并将她击倒。击败魅魔便能确立魔法上的支配地位，并将她遣回扭曲虚空。随后，凯伦丁·哈加尔会传授术士随时召唤她的法术。"}},faq={{q="纯洁的心有什么用途？",a="纯洁的心引诱魅魔穿越扭曲虚空，让她在凡人世界的幽暗城魔法区召唤法阵中现身，术士便可在那里与她交战并将她束缚。",al={"纯洁的心用途","为何使用纯洁的心","纯洁的心有什么作用"}},{q="谁提供纯洁的心？",a="凯伦丁·哈加尔是幽暗城的一位被遗忘者术士训练师，他将纯洁的心交给准备召唤魅魔的术士。",al={"谁提供纯洁的心","纯洁的心任务给予者"}},{q="魅魔为何会响应纯洁的心？",a="魅魔以腐化与诱惑为乐，而无瑕之心的光辉是她们无法抗拒的诱饵，会引诱她们穿越扭曲虚空，来到术士的召唤法阵。",al={"魅魔为何想要纯洁的心","纯洁的心背景故事"}},{q="仪式结束后，你能留下纯洁的心吗？",a="不能。魅魔被召出并制服后，纯洁的心的残余物会交还给凯伦丁·哈加尔，作为完成束缚试炼的证明。",al={"能否保留纯洁的心","纯洁的心的去向"}}},fp="11,206,19.499.0,34.183.0,29.123.0,43.149.0,52.151.0"}
P.entries["item:purified-kor-gem"] = {n="净化过的科尔宝石",s="在铁炉堡城外乔丹·斯迪威尔的熔炉旁，锻造一件圣光武器需要净化过的科尔宝石。首先，必须用精灵魔法净化这块被污染的宝石。",h="在铁炉堡城外乔丹·斯迪威尔的熔炉旁，锻造一件圣光武器需要净化过的科尔宝石。首先，必须用精灵魔法净化这块被污染的宝石。",kw={"奥伯丁","黑暗深渊","被污染的科尔宝石","丹莫罗","乔丹·斯迪威尔","净化过的科尔宝石","正义试炼","桑迪斯·织风"},ang={["class:Paladin"]="身为圣骑士，你通过取得并净化这块宝石来证明自己的虔诚。随后，你将它从卡利姆多带往丹莫罗，用它协助锻造一件圣光武器。",["faction:Alliance"]="身为联盟的一员，你借助奥伯丁暗夜精灵的智慧，帮助丹莫罗山坡上的一位人类铁匠。"},sec={{t="从污秽到神圣",b="纳迦在灰谷海岸下方的黑暗深渊中守着被污染的科尔宝石。一位圣骑士将它带给奥伯丁的暗夜精灵桑迪斯·织风。在那里，桑迪斯运用奥术与自然之力，清除宝石中水生力量与暗影的污染。宝石得到净化，已能传导神圣之力。"},{t="铁匠的杰作",b="乔丹·斯迪威尔是铁炉堡城外的一位人类武器匠，他需要这块宝石来打造一件杰作。他早已备好设计图，想打造一件配得上白银之手的武器，却一直缺少锻造所需的稀有材料。净化过的科尔宝石、白石橡木和稀有矿石赋予这件武器灵性的核心，使其能够传导圣骑士的正义之怒。"}},faq={{q="净化过的科尔宝石有什么用途？",a="这块宝石要交给乔丹·斯迪威尔，他是丹莫罗境内、铁炉堡城外的一位铁匠。他用它为接受试炼的圣骑士锻造一件受过祝圣的武器。",al={"净化过的科尔宝石用途","为何需要科尔宝石","科尔宝石用途"}},{q="这块宝石来自哪里？",a="纳迦在灰谷海岸下方的黑暗深渊中守着这块被污染的宝石。",al={"科尔宝石来源","科尔宝石掉落地点","科尔宝石掉落者"}},{q="谁来净化这块宝石？",a="奥伯丁的暗夜精灵桑迪斯·织风会净化被污染的科尔宝石，使它恢复纯净。",al={"如何净化科尔宝石","谁净化科尔宝石","桑迪斯·织风 科尔宝石"}},{q="任何冒险者都能使用净化过的科尔宝石吗？",a="正在接受正义试炼的圣骑士会寻找这块宝石。神圣的勇士将净化后的水晶和其他稀有材料带给乔丹·斯迪威尔，他便会为他们锻造武器。",al={"科尔宝石是否圣骑士专用","是否人人都能使用净化过的科尔宝石"}}},fx={a30b14db={q="净化过的科尔宝石是什么？",a="净化过的科尔宝石是一种稀有的神圣矿物材料，已被清除污秽的污染。它最初是一块从黑暗深渊的纳迦手中取得的腐化宝石，后来由奥伯丁的桑迪斯·织风悉心清除了其中的黑暗影响，使其潜在特性能够安全地用于神圣事务。",al={"净化过的科尔宝石是什么","净化过的科尔宝石含义","净化过的科尔宝石资料"}}},fp="16,161,27.299.0,23.338.0,38.161.0,29.83.0,21.114.0,52.161.0"}
P.entries["item:putrid-claw"] = {n="腐烂的爪子",s="腐烂的爪子被送到亡灵卫兵迪林格尔手中，证明布瑞尔附近的天灾军团正受到遏制。无意识的亡灵在镇西的树林里游荡，尤其是旧桥附近。",h="腐烂的爪子被送到亡灵卫兵迪林格尔手中，证明布瑞尔附近的天灾军团正受到遏制。无意识的亡灵在镇西的树林里游荡，尤其是旧桥附近。",kw={"腐烂的爪子","布瑞尔","亡灵卫兵迪林格尔","破损的尸体","腐烂的死者","天灾军团","提瑞斯法林地"},ang={["race:Undead"]="作为一名刚离开丧钟镇的被遗忘者新兵，清剿无意识的Scourge会提醒你：重获自由，就意味着必须时刻抵御那些与你曾经一样的无意识躯壳。"},sec={{t="无意识亡灵的战利品",b="无意识的天灾军团不断越境进入提瑞斯法林地。腐烂的死者和破碎的尸体在东部边界游荡，聚集在道路沿线和布瑞尔西边的旧桥附近。亡灵卫兵悬赏清剿这些恐怖的怪物，以保护旅人和驻军的补给线。一只被砍下的腐烂的爪子，证明又有一具蹒跚的尸体被彻底消灭。"}},faq={{q="腐烂的爪子有什么用？",a="布瑞尔的亡灵卫兵迪林格尔收取腐烂的爪子，作为领取赏金的凭证。这些爪子证明，当地的被遗忘者新兵正在削减游荡于提瑞斯法林地的天灾军团数量。",al={"腐烂的爪子用途","为什么收集腐烂的爪子","谁需要腐烂的爪子"}},{q="腐烂的爪子从哪里来？",a="腐烂的爪子来自游荡在布瑞尔西边闹鬼树林中的腐烂的死者和被毁坏的尸体，尤其是在河上旧桥附近。",al={"哪里获得腐烂的爪子","腐烂的爪子掉落","腐烂的死者掉落"}},{q="为什么提瑞斯法林地会有天灾军团？",a="洛丹伦遭到毁灭后，巫妖王麾下无意识的天灾军团残部不断向西越境进入提瑞斯法。若无人清剿，它们就会威胁道路和聚居地。",al={"布瑞尔附近为什么有僵尸","提瑞斯法的天灾军团"}},{q="被遗忘者为什么不放任无意识的亡灵游荡？",a="希尔瓦娜斯女王和被遗忘者挣脱了巫妖王的控制，重获自主意志。无意识的天灾军团受黑暗本能或他残存的命令驱使，一见到活人或自由的亡灵就会攻击。",al={"被遗忘者与无意识僵尸","为什么杀死其他亡灵"}}},fp="11,191,22.354.0,31.155.0,32.140.0,38.170.0,59.205.0"}
P.entries["item:pyrewood-shackle"] = {n="焚木镣铐",s="在焚木村，附魔镣铐将饱受苦难的居民束缚在大法师阿鲁高的诡异魔法之下。这些镣铐与每当夜幕降临便笼罩村民的黑暗命运息息相关。",h="在焚木村，附魔镣铐将饱受苦难的居民束缚在大法师阿鲁高的诡异魔法之下。这些镣铐与每当夜幕降临便笼罩村民的黑暗命运息息相关。",kw={"阿鲁高","道恩维沃尔","月怒","焚木村","瑟伯切尔","镣铐","银松森林","狼人"},ang={["class:Mage"]="身为法师，你能辨认出融入普通钢铁中的肆无忌惮的变化与束缚魔法。",["race:Undead"]="身为被遗忘者，你知道阿鲁高泛滥的巫术正威胁着你们的边境。收集这些附魔镣铐，是消除影牙城堡影响的关键。"},sec={{t="阿鲁高的束缚魔法",b="焚木村的居民白天以人类的模样过着平常的生活，日落时便化为凶野的月怒狼人。大法师阿鲁高给村民戴上了附魔镣铐，作为他研究狼人巫术的实验的一部分。在瑟伯切尔，被遗忘者的奥术研究者达拉尔·道恩维沃尔研究着这些镣铐，探究其附魔的作用。他收集并检视镣铐上残留的能量，希望能理解阿鲁高的魔法，削弱这位疯狂大法师对这一地区的控制。"}},faq={{q="焚木镣铐有什么用途？",a="在瑟伯切尔，达拉尔·道恩维沃尔研究着镣铐上的附魔。他希望借助其中的魔法破解大法师阿鲁高的法术，消除这位大法师在银松森林的影响。",al={"焚木村 镣铐用途","为何收集镣铐","达拉尔·道恩维沃尔的镣铐"}},{q="谁携带着这些镣铐？",a="银松森林南部焚木村中受诅咒的居民携带着这些镣铐。他们白天是人类，夜晚则是月怒狼人，无论何种形态都戴着镣铐。",al={"谁掉落焚木镣铐","镣铐来源","哪里能找到焚木镣铐"}},{q="村民为什么会在夜间变形？",a="大法师阿鲁高肆无忌惮的实验和附魔使焚木村的居民在夜间发生变化。镣铐上的附魔让他们在白天呈现普通人类的模样，而黑暗则显露出他们凶野的狼人形态。",al={"焚木村为何变成狼人","焚木村诅咒","焚木村狼人秘密"}},{q="达拉尔·道恩维沃尔是谁？",a="达拉尔·道恩维沃尔是银松森林瑟伯切尔的一名被遗忘者法师。他研究大法师阿鲁高留下的奥术异象，寻求解除这位大法师诅咒的方法。",al={"达拉尔·道恩维沃尔","达拉尔是谁"}}},fp="16,141,22.410.1,36.176.0,27.155.1,40.234.1,24.167.0"}
P.entries["item:quinn-s-potion"] = {n="奎恩的药水",s="在瑟伯切尔，药剂师伦弗利尔配制了奎恩的药水，帮助一名受伤的斥候康复。奎恩·尤瑞克在银松森林的一次巡逻中遭遇惨败，需要这瓶药水。",h="在瑟伯切尔，药剂师伦弗利尔配制了奎恩的药水，帮助一名受伤的斥候康复。奎恩·尤瑞克在银松森林的一次巡逻中遭遇惨败，需要这瓶药水。",kw={"药剂师伦弗利尔","亡灵哨兵","伊瓦农场","奎恩·尤瑞克","奎恩的药水","瑟伯切尔","银松森林"},ang={["race:Undead"]="身为被遗忘者，你知道皇家药剂师学会很少费心配制简单的野外疗伤药，除非这些药能帮助保住守卫银松森林边境的斥候。"},sec={{t="伦弗利尔的疗方",b="药剂师伦弗利尔为亡灵哨兵奎恩·尤瑞克配制了一剂药。奎恩在伊瓦农场附近身受重伤，无法动弹，消息传到了瑟伯切尔的皇家药剂师学会。伦弗利尔配制了这剂药，帮助他康复。虽然野外的轻微伤亡很少能让伦弗利尔暂时放下为希尔瓦娜斯进行的黑暗研究，他还是提供了药剂，让这名斥候恢复足够的体力，能够动身赶路。"}},faq={{q="奎恩的药水有什么用途？",a="奎恩的药水能帮助亡灵哨兵奎恩·尤瑞克从银松森林北部所受的伤势中康复。它能让他恢复足够的体力，重新动身赶路。",al={"奎因药水用途","奎因药水有什么作用","为何配制奎因药水"}},{q="这瓶药水是谁配制的？",a="这剂药由药剂师伦弗利尔配制，他是皇家药剂师学会的一名炼金师，驻守在瑟伯切尔的墓穴中。",al={"奎恩的药水是谁配制的","是谁配制的","伦弗利尔药水"}},{q="药水需要送到哪里？",a="把药水送到瑟伯切尔北面，交给奎恩·尤瑞克，他正躲在名为伊瓦农场的农庄附近。",al={"药水送到哪里","奎因位置","奎恩·尤瑞克所在位置"}},{q="奎恩·尤瑞克为什么需要药水？",a="奎恩当时正随一支亡灵哨兵巡逻队在银松森林北部侦察。在伊瓦农场，食尸鬼邪恶的伊瓦袭击了这些斥候，导致奎恩身受重伤，困在那里。",al={"奎因为何受伤","奎恩·尤瑞克遭遇了什么","奎因受伤"}}},fp="14,154,16.415.0,32.156.0,23.123.0,43.109.0,41.169.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="兰恩·血牙的颅骨",s="在灰谷，兰恩·血牙的颅骨证明，一名堕落的熊怪酋长已经倒下。阿斯特兰纳的暗夜精灵收下了它，视其为林地王国的一大凶险威胁已经终结的标志。",h="在灰谷，兰恩·血牙的颅骨证明，一名堕落的熊怪酋长已经倒下。阿斯特兰纳的暗夜精灵收下了它，视其为林地王国的一大凶险威胁已经终结的标志。",kw={"灰谷","阿斯特兰纳","血牙的颅骨","血牙","熊怪","莱恩·狼行者","莱恩的净化","兰恩·血牙"},ang={["faction:Alliance"]="送回这件骇人的战利品，彰显了联盟勇士的胆魄，他们与Sentinels并肩守卫着灰谷脆弱的边境。",["race:NightElf"]="对暗夜精灵而言，这颗颅骨象征着一场沉重的胜利，也纪念着泰洛尼斯未竟的任务。它还让人想起，恶魔的腐化给他们昔日的熊怪盟友带来了多么深重的摧残。"},sec={{t="保卫灰谷的战利品",b="在恶魔的污染与荒野的腐化之下，灰谷的熊怪陷入了嗜杀的疯狂。兰恩·血牙领导着其中最凶悍的部族之一。他的颅骨向暗夜精灵哨兵证明，他已经倒下，对当地熊怪的控制也已瓦解，让阿斯特兰纳获得了些许喘息。"},{t="缅怀逝者",b="哨兵莱恩·狼行者在阿斯特兰纳收下了兰恩·血牙的颅骨，标志着阵亡斥候泰洛尼斯发起的调查就此结束。泰洛尼斯生前出发寻找的达图尔的变形魔棒，如今已被修复，陈列在颅骨旁边。它们一同纪念着那些为守护神圣森林而战的人。"}},faq={{q="兰恩·血牙是谁？",a="兰恩·血牙领导着灰谷的一个堕落熊怪部族，暗夜精灵哨兵将他视为当地最凶险的威胁之一。",al={"兰恩·血牙是谁","兰恩·血牙的故事","血牙是谁"}},{q="哨兵为什么需要他的颅骨？",a="莱恩·狼行者在阿斯特兰纳收下这颗颅骨，作为兰恩·血牙已经倒下的证明。它被安放在达图尔的魔棒旁边，以纪念那些为保卫灰谷而牺牲的人。",al={"为何需要颅骨","莱恩·狼行者的颅骨","颅骨的用途"}},{q="泰洛尼斯是谁？",a="泰洛尼斯是莱恩·狼行者的多年挚友，也是灰谷哨兵的盟友。他为已故巫师达图尔制作的一根魔棒寻找宝石，希望借此减缓熊怪的攻势，却在法拉希姆湖被鱼人杀害。莱恩·狼行者和到访的冒险者接下了他的任务。",al={"泰洛尼斯的故事","泰洛尼斯是谁","泰洛尼斯 阿斯特兰纳"}}},fx={["4d0a3ce4"]={q="什么是兰恩·血牙的颅骨？",a="这是兰恩·血牙被砍下的颅骨。他是灰谷出没的凶狠危险的腐化熊怪之一。它被当作击败他的凭证，标志着他给哨兵和森林带来的恐怖终于结束。",al={"兰恩·血牙的颅骨","兰恩的颅骨是什么","兰恩·血牙的头颅"}},f5c7858d={q="兰恩·血牙的颅骨来自哪里？",a="在灰谷杀死兰恩·血牙后，便可直接取得他的颅骨。它不是凡人锻造或制作的神器，而是从这位酋长身上取得的骇人战利品。",al={"兰恩的颅骨来自哪里","谁制造了兰恩·血牙的颅骨","兰恩·血牙的颅骨来源"}}},fp="22,115,31.284.0,19.305.1,23.136.0,36.164.0,16.287.0"}
P.entries["item:raptor-head"] = {n="迅猛龙的头颅",s="在贫瘠之地各处，迅猛龙的头颅都是交付十字路口加兹罗格悬赏的凭证。卫兵的军饷从一座哨塔中失窃，一只野生迅猛龙在行窃时被当场抓获。",h="在贫瘠之地各处，迅猛龙的头颅都是交付十字路口加兹罗格悬赏的凭证。卫兵的军饷从一座哨塔中失窃，一只野生迅猛龙在行窃时被当场抓获。",kw={"贫瘠之地","十字路口","加兹罗格","迅猛龙的头颅","迅猛龙窃贼","被偷走的银币","赤鳞"},ang={["class:Hunter"]="在贫瘠之地干燥的灌木丛中追踪 Sunscale 迅猛龙，将考验你对付草原上那些极具攻击性、又十分狡猾的群居猎手的本领。",["faction:Horde"]="十字路口是部落在卡利姆多中部的交通枢纽。清除这些行窃的掠食者，便能保障驻军的补给和军饷安全。"},sec={{t="十字路口的悬赏",b="一箱卫兵军饷遭窃，十字路口哨塔里的银币不翼而飞。守卫们当场抓住了一只行窃的野生迅猛龙，简直难以置信。加兹罗格已悬赏猎杀这些在贫瘠之地游荡的狡猾爬行动物。把它们砍下的头颅带回哨站，就能削减这些掠食者的数量，免得它们再偷窃部落的补给。"}},faq={{q="加兹罗格为什么要迅猛龙的头颅？",a="一批用于支付十字路口卫兵军饷的银币装在箱子里，从他们的哨塔中被盗走了。令所有人难以置信的是，一只迅猛龙在行窃时被当场抓获。加兹罗格希望有人在贫瘠之地猎杀这些野兽，免得它们再次袭扰聚居地。",al={"为什么收集迅猛龙的头颅","加兹罗格 迅猛龙","迅猛龙的头颅悬赏"}},{q="野生迅猛龙为什么会偷银币？",a="加兹罗格承认，他也不知道野兽为什么会想要金属钱币。卡利姆多的迅猛龙以令人不安的狡诈而臭名昭著，这起盗窃案让十字路口的卫兵颜面扫地，急于报复。",al={"迅猛龙为什么想要银币","迅猛龙偷钱币","迅猛龙窃贼之谜"}},{q="哪些迅猛龙身上能取得这些头颅？",a="这些头颅可以从游荡在贫瘠之地中部和南部的 赤鳞迅猛龙身上取得，包括 赤鳞鞭尾龙、赤鳞尖啸龙 和 赤鳞镰爪龙。伊沙姆哈尔和 “跳跃者”塔克等臭名昭著的野兽也能提供头颅。",al={"哪里能取得迅猛龙的头颅","哪些迅猛龙掉落头颅","贫瘠之地迅猛龙"}},{q="交付头颅后会发生什么？",a="等加兹罗格收到十二颗头颅，迅猛龙的威胁有所减轻后，接下来就要追查那批失窃的银币究竟被带到了哪里。",al={"迅猛龙窃贼后续","收集迅猛龙的头颅之后"}}},fp="11,150,24.355.0,34.228.0,36.207.0,32.207.0,40.139.0"}
P.entries["item:rare-earth"] = {n="稀土",s="稀土正在多兰纳尔等待运往德纳兰位于奥拉密斯湖附近的营地。这些富含矿物质的土壤来自达纳苏斯，供他在泰达希尔进行植物实验。",h="稀土正在多兰纳尔等待运往德纳兰位于奥拉密斯湖附近的营地。这些富含矿物质的土壤来自达纳苏斯，供他在泰达希尔进行植物实验。",kw={"达纳苏斯","德纳兰","多兰纳尔","采药","奥拉密斯湖","稀土","塞拉尔·刃叶"},ang={["profession:Herbalism"]="草药师可以向塞拉尔·刃叶和德纳兰求教，他们研究特殊土壤如何改变泰达希尔幼树的生长和特性。",["race:NightElf"]="作为照料年轻的世界之树的暗夜精灵，你可以看到奥拉密斯湖的实验如何揭示生命适应泰达希尔荒野枝桠的方式。"},sec={{t="达纳苏斯的土壤",b="从达纳苏斯运来的稀土迟迟才抵达多兰纳尔。德纳兰是住在奥拉密斯湖东岸的一位古怪的植物学家，他订下这份包裹，是为了研究泰达希尔年轻生态系统中的植物。草药师塞拉尔·刃叶如今将这些土壤托付给南行的旅人，希望能在效力消退之前送到德纳兰手中。"}},faq={{q="稀土有什么用途？",a="德纳兰是奥拉密斯湖畔的草药师和植物研究者，他将用稀土进行实验。他用矿物化合物和来自达纳苏斯的肥沃土壤培育泰达希尔的本土植物。",al={"稀土用途","德纳兰用稀土做什么","稀土作用"}},{q="谁将稀土送给德纳兰？",a="草药师塞拉尔·刃叶在多兰纳尔保管着包裹。它从达纳苏斯运来时已经晚了，她请向南前往奥拉密斯湖的旅人将它带给德纳兰。",al={"谁提供稀土","稀土从哪里获得","塞拉尔·刃叶的包裹"}},{q="德纳兰为什么担心这批货物？",a="这批货物在前往多兰纳尔的途中耽搁了，德纳兰只能在湖边等待。货物送到时，他担心土壤可能已不再新鲜，无法满足实验所需。",al={"稀土是否变质","德纳兰新鲜土壤","土壤为何迟到"}}},fp="10,160,17.313.0,28.170.0,36.170.0,43.172.0"}
P.entries["item:rattlecage-skull"] = {n="断骨骷髅的颅骨",s="在丧钟镇，初学的被遗忘者术士从无脑的亡灵身上收集颅骨。温雅·玛山德用这些颅骨考验他们的意志，之后才会传授召唤的黑暗法术。",h="在丧钟镇，初学的被遗忘者术士从无脑的亡灵身上收集颅骨。温雅·玛山德用这些颅骨考验他们的意志，之后才会传授召唤的黑暗法术。",kw={"丧钟镇","召唤小鬼","控制小鬼","断骨骷髅","断骨骷髅的颅骨","提瑞斯法林地","温雅·玛山德"},ang={["class:Warlock"]="身为被遗忘者术士，收集这些颅骨是你磨炼自制力的第一个里程碑。这证明你拥有奴役第一个恶魔所需的冷酷意志。",["race:Undead"]="身为Undead，击碎低等、没有思想的骷髅，体现了被遗忘者凭借纯粹意志取得支配权的信念。拥有自由意志的亡灵以此区别于无脑的奴仆。"},sec={{t="新学徒的试炼",b="在丧钟镇，温雅·玛山德指引着刚刚复生、拥有黑暗魔法天赋的被遗忘者。她派他们去制服破败铁匠铺附近的断骨骷髅，并带回斩下的颅骨。这场试炼考验初出茅庐的术士能否让来自这个世界之外的生物服从自己的命令。这也为突破虚空、束缚第一个恶魔仆从打下基础。"}},faq={{q="断骨骷髅的颅骨有什么用途？",a="温雅·玛山德在丧钟镇收集三块断骨骷髅的颅骨。被遗忘者术士带来这些颅骨，证明自己的专注与决心，之后她才会教他们召唤并束缚小鬼。",al={"什么是断骨骷髅的颅骨","断骨骷髅的颅骨用途","谁需要断骨骷髅的颅骨"}},{q="断骨骷髅的颅骨从何而来？",a="断骨骷髅的颅骨来自断骨骷髅，这些无脑的亡灵在丧钟镇废弃铁匠铺附近杂草丛生的道路和残破的地面上游荡。",al={"哪里获取断骨骷髅的颅骨","谁掉落断骨骷髅的颅骨","断骨骷髅的颅骨位置"}},{q="温雅·玛山德为何要求术士在试炼中收集骷髅的颅骨？",a="温雅·玛山德相信，无知者无法获得力量，而掌控力量就意味着让外来的力量屈从于自己的意志。杀死无脑的骷髅并取下它们的头颅，表明学徒能够驾驭混乱的能量，而不会被其吞噬。",al={"术士为何需要颅骨","温雅·玛山德的试炼"}},{q="收集这些颅骨后能学到什么？",a="献上颅骨后，温雅·玛山德会传授召唤并束缚小鬼的秘密仪式，让年轻的术士获得第一个真正的恶魔仆从。",al={"断骨骷髅的颅骨能换来什么","控制小鬼奖励"}}},fp="16,155,17.352.0,36.172.0,37.145.0,68.239.0,55.160.0"}
P.entries["item:raven-claw-talisman"] = {n="鸦爪神符",s="在班奈希尔兽穴，鸦爪神符与唤醒沉睡德鲁伊所需的其他圣物一同存放。这件暗夜精灵的神圣遗物是四件唤醒圣物之一，用于引导猛禽德鲁伊从翡翠梦境安全归来。",h="在班奈希尔兽穴，鸦爪神符与唤醒沉睡德鲁伊所需的其他圣物一同存放。这件暗夜精灵的神圣遗物是四件唤醒圣物之一，用于引导猛禽德鲁伊从翡翠梦境安全归来。",kw={"阿斯瑞达斯·熊皮","班奈希尔","兽穴","多兰纳尔","猛禽德鲁伊","鸦爪神符","唤醒圣物","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，你能从鸦爪神符看出，猛禽德鲁伊如何借助仪式法器，保护游历翡翠梦境的灵魂。",["race:NightElf"]="身为暗夜精灵，你从瘤背熊怪手中取回这件圣物，便是在守护古老的传统和沉睡的同胞。"},sec={{t="唤醒的关键",b="鸦爪神符存放在班奈希尔兽穴内一个指定的箱子里，泰达希尔的猛禽德鲁伊正是在这里进入了深度冥想的沉睡。他们的休眠处于微妙的灵魂交界。若没有合适的仪式法器，与清醒世界失去联系的德鲁伊可能会被困在翡翠梦境中。多兰纳尔的阿斯瑞达斯·熊皮需要这枚神符，以及黑色羽毛、天蓝宝石和筑巢符文，才能举行唤醒仪式，让沉睡者安全归来。"},{t="兽穴中的威胁",b="堕落的瘤背熊怪占据了班奈希尔兽穴，让其中的神圣宝箱和沉睡的德鲁伊陷入险境。它们的亵渎使这处圣所与外界的援助隔绝，圣物也可能遗失或遭到毁坏。阿斯瑞达斯·熊皮呼吁泰达希尔的守卫者勇闯兽穴中蜿蜒的泥土通道，取回鸦爪神符，以免那些迷失的德鲁伊永远困在梦境之中。"}},faq={{q="鸦爪神符有什么用途？",a="鸦爪神符是四件神圣的唤醒圣物之一，唤醒在翡翠梦境中深度休眠的猛禽德鲁伊需要用到它。",al={"鸦爪神符有什么用","鸦爪神符用途","为什么需要鸦爪神符"}},{q="在哪里能找到鸦爪神符？",a="鸦爪神符存放在鸦爪之箱中，位于泰达希尔多兰纳尔以西的班奈希尔兽穴泥土隧道内。",al={"鸦爪神符在哪里","鸦爪之箱位置","如何找到鸦爪神符"}},{q="谁需要鸦爪神符？",a="多兰纳尔的暗夜精灵德鲁伊阿斯瑞达斯·熊皮需要这枚神符，为迷失的同胞准备唤醒仪式。",al={"谁需要鸦爪神符","谁收取鸦爪神符","交给谁"}},{q="为什么没有它，德鲁伊就无法醒来？",a="德鲁伊的休眠涉及在翡翠梦境中进入复杂而微妙的冥想状态。若没有唤醒圣物来稳固唤醒仪式，沉睡者的灵魂就可能一直迷失在那里。",al={"德鲁伊为什么需要圣物才能醒来","为什么需要唤醒圣物","没有圣物德鲁伊能醒来吗"}}},fp="19,210,18.440.0,28.413.0,41.164.0,39.153.0,34.139.0,40.175.0"}
P.entries["item:razorflank-s-medallion"] = {n="卡尔加·刺肋的徽章",s="卡尔加·刺肋的徽章藏在剃刀沼泽深处，由统治这座要塞的老妪随身携带。将徽章带回，便能向暗夜精灵哨兵证明她已伏诛。",h="卡尔加·刺肋的徽章藏在剃刀沼泽深处，由统治这座要塞的老妪随身携带。将徽章带回，便能向暗夜精灵哨兵证明她已伏诛。",kw={"阿迦玛甘","卡尔加·刺肋","法芬德尔","独眉","剃刀沼泽","卡尔加·刺肋的徽章","萨兰纳尔"},ang={["faction:Alliance"]="身为联盟冒险者，夺回这枚徽章便是为阵亡的斥候赫尔拉斯和矮人探险者独眉复仇。此举也保障了从萨兰纳尔边境通往菲拉斯的道路安全。",["race:NightElf"]="身为暗夜精灵，杀死卡尔加并取得她的徽章，便能让你的族人安全地研究阿迦玛甘遭到腐化的神圣安息之地。"},sec={{t="老妪伏诛的证据",b="卡尔加·刺肋是剃刀野猪人的首领，随身携带着这枚徽章。在萨兰纳尔，法芬德尔得知了赫尔拉斯和矮人独眉等探险者的死讯，随后派遣联盟冒险者讨伐野猪人首领。这枚徽章向守卫菲拉斯边境的暗夜精灵哨兵证实了卡尔加的死讯。他们由此便能知道，集结在沼泽内的部队已经失去了首领。"}},faq={{q="谁携带着卡尔加·刺肋的徽章？",a="卡尔加·刺肋在剃刀沼泽深处，随身携带着这枚徽章。她就是统领那里野猪人的老妪。",al={"谁掉落卡尔加·刺肋的徽章","卡尔加·刺肋的徽章来源","卡尔加的徽章"}},{q="谁要求将这枚徽章带回？",a="萨兰纳尔的法芬德尔要求带回这枚徽章。他需要证据，证明卡尔加已被杀死。",al={"谁需要卡尔加·刺肋的徽章","交付卡尔加·刺肋的徽章","法芬德尔的徽章"}},{q="法芬德尔为何需要卡尔加已死的证据？",a="卡尔加在剃刀沼泽内集结了一支敌对的野猪人部队，威胁着周边地区。赫尔拉斯和独眉也在阵亡的斥候之列。这枚徽章让暗夜精灵确信，眼前的威胁已被消除，他们可以继续调查。",al={"为何杀死卡尔加","徽章的用途","为何需要徽章"}}},fx={b119a669={q="什么是卡尔加·刺肋的徽章？",a="卡尔加·刺肋的徽章是卡尔加·刺肋随身携带的个人信物。她是居住在剃刀沼泽深处的野猪人老妪和首领。这枚徽章不只是装饰品，更是她统御剃刀沼泽中成群部族的鲜明象征，因此是她败亡的标志性战利品。",al={"什么是卡尔加·刺肋的徽章","卡尔加·刺肋的徽章背景","卡尔加·刺肋的徽章"}}},fp="22,157,25.393.0,35.98.0,41.100.0,49.269.0"}
P.entries["item:reagent-pouch-shaman"] = {n="试剂袋",s="杜隆塔尔的火刃氏族教徒携带着萨满祭司制作第一份火焰灵契所需的试剂。泰尔夫·祖拉姆将这些试剂与来自钢鬃野猪人的火焰焦油混合，制成药剂，让年轻的萨满祭司得以窥见火焰的领域。",h="杜隆塔尔的火刃氏族教徒携带着萨满祭司制作第一份火焰灵契所需的试剂。泰尔夫·祖拉姆将这些试剂与来自钢鬃野猪人的火焰焦油混合，制成药剂，让年轻的萨满祭司得以窥见火焰的领域。",kw={"火刃氏族","火焰的召唤","杜隆塔尔","尘风洞穴","火焰灵契","火焰图腾","试剂袋","泰尔夫·祖拉姆"},ang={["class:Shaman"]="身为萨满祭司，取回试剂袋是你获得火焰图腾所要经历的一项试炼。它教会你，遭到腐化的元素力量也能被重新引导，为平衡效力。",["class:Warlock"]="身为术士，你认得这些袋子，它们是邪能教徒施展巫术的物资。他们用于仪式的元素是为恶魔火焰法术准备的，而非用于与自然交流。"},sec={{t="火焰的配料",b="火刃氏族教徒携带着年轻萨满祭司制作第一份火焰灵契所需的试剂。隐士泰尔夫·祖拉姆将他们袋中的粉末和油料与来自钢鬃野猪人的火焰焦油混合。这些配料共同制成一种药剂，让萨满祭司得以窥见火焰的领域，并与火焰之灵建立联系。"},{t="污浊之源，澄澈之眼",b="火刃氏族教徒将火焰用于毁灭和邪能巫术，但他们袋中的元素依然属于热量与燃烧。萨满祭司教导人们，元素力量之间存在着相互制衡的关系：火焰既能创造，也能毁灭。萨满祭司可以取用教徒的工具，借助其中的元素，真正开启与元素之灵的交流。"}},faq={{q="试剂袋有什么用途？",a="泰尔夫·祖拉姆用这些试剂调制火焰灵契。饮下它后，萨满祭司便能获得洞察幻象的视野，寻找元素之灵，并取得火焰图腾。",al={"试剂袋用途","试剂袋有什么用","试剂袋萨满祭司任务"}},{q="在哪里能找到试剂袋？",a="你可以从杜隆塔尔尘风洞穴中的火刃氏族教徒身上取得试剂袋。洞穴位于剃刀岭东北方的岩石高地上。",al={"试剂袋掉落","哪里获取试剂袋","火刃氏族试剂袋位置"}},{q="萨满祭司为什么需要术士的试剂？",a="火刃氏族教徒的袋中装着与火焰魔法有关的材料。他们用这些试剂举行火焰仪式，因此这些试剂也能成为调制火焰灵契的有效催化剂。",al={"为什么用术士物品","为什么用火刃氏族试剂","萨满祭司使用邪能物品"}}},fp="22,209,23.316.0,28.307.0,35.189.0,32.126.0,40.160.0"}
P.entries["item:reconstructed-tome"] = {n="翻修过的书籍",s="在术士手中，翻修过的书籍汇集了密教散落的教义。书页中记载着从扭曲虚空召唤并束缚地狱猎犬的仪式。",h="在术士手中，翻修过的书籍汇集了密教散落的教义。书页中记载着从扭曲虚空召唤并束缚地狱猎犬的仪式。",kw={"束缚","龙喉氏族","地狱猎犬","棘齿城","翻修过的书籍","斯坦哈德·法尔杉","阴谋之书"},ang={["class:Warlock"]="身为术士，拼合翻修过的书籍便能掌握支配地狱猎犬的黑暗仪式。它对魔法的饥渴可以用来对付敌方施法者。"},sec={{t="重新拼合的魔典",b="联盟和部落的术士都在寻找阴谋之书的残页。他们将魔典重新拼合，并向研究秘术的学者请教，这些学者渴望在完整的书籍上交之前，一窥其中罕见的教义。"},{t="召唤地狱猎犬的关键",b="斯坦哈德·法尔杉是贫瘠之地棘齿城港口附近的一位召唤大师，他收下了修复的书籍和从龙喉氏族施法者手中夺来的导能魔棒。书中的仪式为他的侍从提供了咒语，帮助术士召唤一只贪婪的地狱猎犬，将其击败，并使其屈从于自己的意志。"}},faq={{q="翻修过的书籍有什么用途？",a="翻修过的书籍记载着密教的教义，以及召唤和束缚地狱猎犬的仪式。术士将它与导能魔棒一起带给棘齿城的斯坦哈德·法尔杉，用于举行仪式。",al={"翻修过的书籍的用途","为何需要翻修过的书籍","翻修过的书籍的用法"}},{q="斯坦哈德·法尔杉是谁？",a="斯坦哈德·法尔杉是一位召唤专家，住在贫瘠之地棘齿城港口上方。他主持术士的试炼，考验那些想要奴役更危险恶魔的人。",al={"斯坦哈德是谁","斯坦哈德·法尔杉的职责"}},{q="研究这本书的学者为什么想要一份抄本？",a="帮助解读残页的学者发现，密教的秘术典籍既罕见又引人入胜。矮人和被遗忘者的研究者渴求这些恶魔知识，其内容远超他们平日所读。",al={"谁翻译了它","学者与翻修过的书籍"}},{q="除了书籍，仪式还需要什么？",a="斯坦哈德需要三根导能魔棒，好让他的侍从维持召唤仪式。湿地的龙喉氏族施法者持有这些法棒。",al={"需要的其他物品","翻修过的书籍需要搭配什么"}}},fp="18,172,22.250.0,20.291.1,40.182.0,22.160.0,51.199.0,54.146.0"}
P.entries["item:recruitment-letter"] = {n="募兵信",s="塔克林·寻路者将杜隆塔尔有潜力的冒险者派往西方，在贫瘠之地服役。他的信指引身强体健的志愿者前往卡加尔·战痕管理的边境哨站。",h="塔克林·寻路者将杜隆塔尔有潜力的冒险者派往西方，在贫瘠之地服役。他的信指引身强体健的志愿者前往卡加尔·战痕管理的边境哨站。",kw={"贫瘠之地","部落应征者","十字路口","卡加尔·战痕","剃刀岭","募兵信","塔克林·寻路者"},ang={["faction:Horde"]="身为部落的一员，携带这封信意味着你将从杜隆塔尔的地方防卫，转入卡利姆多边疆的现役军旅生涯。",["race:Orc"]="身为年轻的兽人，向卡加尔·战痕这样的老兵呈交一封签好字的服役信函，是你在大酋长萨尔领导的新部落中赢得荣誉的起步。"},sec={{t="应征戍边",b="塔克林·寻路者观察着在剃刀岭一带证明自身实力的年轻战士和斥候。他挑选出那些看起来足以胜任前线任务的人，交给他们一封前往贫瘠之地服役的信。走过怒水河上的桥梁，新兵便离开了杜隆塔尔相对安稳的红土地，加入部落的防卫队伍，抵御野猪人、半人马和联盟斥候。"},{t="向战痕报到",b="卡加尔·战痕在河对岸的哨站接收新兵。这位饱经风霜的老兵管理着哨站，并在签字批准入伍前评估每一名应征者。获准入伍的新兵很快就会被派往更西边的十字路口，那里的边境哨站兵力捉襟见肘。"}},faq={{q="这封募兵信是谁写的？",a="塔克林·寻路者负责发放这封信。这名兽人斥候驻守在从剃刀岭出发的道路沿线，留意着向西行进、能够胜任军务的新兵。",al={"谁发放募兵信","谁写的信","塔克林·寻路者的信"}},{q="这封信需要送到哪里？",a="你要将信交给卡加尔·战痕。他位于杜隆塔尔与贫瘠之地交界处的兽人哨站，过了怒水河上的桥梁就能到达。",al={"募兵信送到哪里","交付募兵信","信交给谁"}},{q="信签好后会发生什么？",a="卡加尔会在文书上签字，正式批准你入伍，然后命令你深入平原，前往急需援军的十字路口报到服役。",al={"卡加尔签字后会怎样","募兵信的后续任务"}},{q="部落为什么要在贫瘠之地征召冒险者？",a="部落征召冒险者，是因为贫瘠之地幅员辽阔、危机四伏，又连接着部落的主要聚居地。半人马氏族、好斗的刺背野猪人和联盟的行动让威胁始终不断，前线指挥官需要每一个能出力的人。",al={"为什么招募","贫瘠之地为什么征兵"}}},fp="18,168,27.348.0,23.286.0,34.141.0,34.139.0,39.174.0,57.263.0"}
P.entries["item:red-burlap-bandana"] = {n="红色粗麻面罩",s="在北郡山谷修道院附近的葡萄园旁，维里副队长收集被杀死的迪菲亚盗贼身上的红色面罩。这些布料是兄弟会中低阶拦路强盗和扒手的标记。",h="在北郡山谷修道院附近的葡萄园旁，维里副队长收集被杀死的迪菲亚盗贼身上的红色面罩。这些布料是兄弟会中低阶拦路强盗和扒手的标记。",kw={"面罩","盗贼兄弟会","迪菲亚","面具","北郡","红色粗麻面罩","维里"},ang={["class:Rogue"]="作为一名正在成长的潜行者，你可以从北郡那些笨拙的拦路贼身上看到，缺乏纪律的亡命之徒会多快沦为当地执法者的轻易猎物。",["faction:Alliance"]="作为联盟的一员，你可以看到红色面罩已经出现在北郡修道院门前，这表明暴风城正在失去对王国乡野边境的控制。"},sec={{t="兄弟会的标记",b="在北郡，迪菲亚潜行者的新兵和普通暴徒戴着红色粗麻面罩。这种廉价而粗糙的布料遮住了他们的面容，也表明他们效忠于日益壮大的叛乱势力。他们带着这些面巾进入东边的果园，当地卫兵将这种红布视为附近盗贼已被击杀的证据。"}},faq={{q="维里副队长为什么要收集这些面罩？",a="维里副队长收集这些面罩，用来证明冒险者已经杀死了北郡修道院附近的迪菲亚暴徒。这些盗贼公然佩戴红布，因此面罩可以证实悬赏目标已被击杀。",al={"为什么收集面罩","维里面罩","盗贼兄弟会交任务"}},{q="谁会佩戴红色粗麻面罩？",a="迪菲亚潜行者的拦路贼和暴徒佩戴红色粗麻面罩。粗糙的布料遮住了他们的面容，也表明他们效忠于这群亡命之徒。",al={"谁戴红色面罩","迪菲亚面罩背景","谁掉落红色面罩"}},{q="迪菲亚盗贼为什么在北郡活动？",a="迪菲亚斥候和强盗在北郡修道院东边溪流的对岸扎营，搜刮并偷窃补给。修道院的驻军兵力捉襟见肘，附近的果园因此任由拦路强盗出没。",al={"迪菲亚为什么在北郡","修道院附近的盗贼"}},{q="这些面罩为什么是红色的？",a="深红色染料让廉价的粗麻面罩染上了红色。这种颜色用于迪菲亚潜行者的旗帜和制服，帮助成员在野外辨认彼此。",al={"迪菲亚面罩为什么是红色","红布的含义"}}},fx={c4ebebb0={q="红色粗麻面罩是什么？",a="红色粗麻面罩是迪菲亚潜行者成员佩戴的标志性布面罩。它用粗麻布廉价制成，染成红色，既能遮住佩戴者的面容，也表明其效忠于这个不法公会。在北郡，它是暴徒在河东出没和活动的直接证据。",al={"红色粗麻面罩的身份标志","红色面罩是什么","迪菲亚潜行者面罩的故事"}}},fp="18,180,25.319.0,43.189.0,34.148.0,47.188.0,28.172.0"}
P.entries["item:red-leather-bandana"] = {n="红色皮质面罩",s="在西部荒野，红色皮质面罩是反抗暴风城王权者的标志。迪菲亚潜行者戴着它遮掩面容，表明自己的立场。",h="在西部荒野，红色皮质面罩是反抗暴风城王权者的标志。迪菲亚潜行者戴着它遮掩面容，表明自己的立场。",kw={"兄弟会","迪菲亚","加里安","面罩","红色皮质面罩","哨兵岭","西部荒野"},ang={["class:Rogue"]="身为盗贼，你知道这种深红色面罩是人类领地中地下匪帮的标志。佩戴它的盗贼组织严密，如同军队。",["faction:Alliance"]="对联盟而言，每从一名倒下的亡命之徒身上取走一条红色面罩，就意味着少了一名威胁西部荒野饥饿农民和困顿民兵的匪徒。"},sec={{t="兄弟会的标志",b="在西部荒野的田地和废弃农场间，拦路强盗、劫掠者和反叛的劳工戴着深红色面罩，遮掩面容。哨兵岭的人民军将每一条面罩都视为效忠艾德温·范克里夫麾下盗匪团伙的证据。哨兵加里安向旅人收集这些面罩，以追踪兄弟会在这一带的动向，以及日渐减少的人数。"}},faq={{q="迪菲亚为什么戴红色皮质面罩？",a="迪菲亚戴着红色面罩，在劫掠农场和道路时遮掩面容。面罩也表明他们效忠于艾德温·范克里夫反抗暴风城的起义。",al={"迪菲亚面罩","为什么戴红色面罩","迪菲亚面罩含义"}},{q="西部荒野的谁在收集这些面罩？",a="哨兵岭人民军的哨兵加里安请旅人收集这些面罩。他用这些面罩追踪匪帮的动向，并确认四处流窜的匪徒已经死亡。",al={"谁收红色面罩","加里安面罩任务","哨兵岭面罩交付"}},{q="哪里能找到这些面罩？",a="西部荒野各处营地、田野和矿洞中的迪菲亚盗贼、拦路强盗和走私者都携带着这些面罩。",al={"红色面罩掉落","刷红色面罩","谁掉落红色皮质面罩"}}},fp="19,153,23.372.1,44.153.1,47.179.0,31.112.0"}
P.entries["item:red-linen-bandana"] = {n="红色亚麻面罩",s="在艾尔文森林各地，红色亚麻面罩是迪菲亚潜行者的标志，也遮住了佩戴者的面容。东谷伐木场的萨拉·迪博雷恩想用这些布料制作衣物和绷带。",h="在艾尔文森林各地，红色亚麻面罩是迪菲亚潜行者的标志，也遮住了佩戴者的面容。东谷伐木场的萨拉·迪博雷恩想用这些布料制作衣物和绷带。",kw={"迪菲亚面罩","东谷","艾尔文森林","亚麻布","红色亚麻面罩","萨拉·迪博雷恩"},ang={["class:Rogue"]="身为盗贼，你熟悉那种系在下半张脸上的深红色布料。它是都城周围林地中拦路强盗和扒手的标志。",["profession:Tailoring"]="在艾尔文的乡间，织工能将匪徒面罩上的亚麻布制成劳作时穿的衣物。"},sec={{t="迪菲亚的标志",b="在北郡山谷，初入伙的成员和普通暴徒戴着粗糙的麻布面罩。深红色的亚麻布表明，正式成员效忠于艾德温·范克里夫的盗贼兄弟会。它也象征着对暴风城王权的反抗。"},{t="布料的新用途",b="萨拉·迪博雷恩请旅人从不法之徒的营地收集面罩。这些面罩虽属于匪徒，亚麻布却是好料子。洗净后再加以缝制，这些布料就能变成结实的衣物和绷带，供森林中辛勤劳作的人们使用。"}},faq={{q="迪菲亚为何佩戴红色亚麻面罩？",a="迪菲亚成员佩戴红色亚麻面罩来遮住面容。这种布料也表明他们效忠于艾德温·范克里夫的兄弟会，并反抗暴风城。",al={"迪菲亚面罩含义","为何戴红色面罩","迪菲亚红色面罩"}},{q="这些面罩与北郡的面罩有何不同？",a="北郡山谷的暴徒戴着粗糙的麻布面罩。艾尔文森林各地的正式迪菲亚成员则佩戴质地更细的红色亚麻布。",al={"麻布与亚麻布区别","北郡面罩","麻布面罩"}},{q="谁想收集这些面罩？",a="东谷伐木场的萨拉·迪博雷恩想要这些面罩。她会将面罩洗净、拆成线，再织成实用的衣物。",al={"谁收红色亚麻面罩","萨拉·迪博雷恩面罩","面罩任务交付"}},{q="哪些敌人携带红色亚麻面罩？",a="艾尔文森林各地的迪菲亚成员都携带红色亚麻面罩。其中包括迪菲亚强盗、迪菲亚伏击者、潜行者、码头工人，以及收货人莫根这样的头目。",al={"谁掉落红色亚麻面罩","哪里刷面罩","迪菲亚面罩掉落"}}},fp="17,190,18.223.0,16.251.0,42.165.0,54.122.0,36.127.0,39.178.0"}
P.entries["item:red-wool-bandana"] = {n="红色毛纺面罩",s="在暴风城监狱里，红色毛纺面罩的碎布是迪菲亚潜行者的标志。被囚禁的亡命之徒从牢房的毛毯上撕下布片，戴在身上，作为铁窗之下不屈的象征。",h="在暴风城监狱里，红色毛纺面罩的碎布是迪菲亚潜行者的标志。被囚禁的亡命之徒从牢房的毛毯上撕下布片，戴在身上，作为铁窗之下不屈的象征。",kw={"迪菲亚","麦克·拉斯科","尼科瓦·拉斯克","红色毛纺面罩","暴风城","鲜血的颜色","监狱"},ang={["faction:Alliance"]="对联盟的守卫者而言，收回这些面罩既是为年幼的Mac Raskol讨回严酷的公道，也是对盘踞城中监狱的暴徒的一次打击。",["profession:Tailoring"]="这些粗糙的面罩表明，身陷囹圄的人在绝望中也能用双手拆开粗毛毯，让纤维重新派上用场。"},sec={{t="缝入反抗",b="在暴风城监狱里，迪菲亚潜行者的囚犯坚守着自己的身份。他们偷偷从监狱的毛毯上撕下布片，缝成红色面罩，佩戴起来作为帮派标志。守卫将这些面巾视为违禁品，一旦发现，就可能引发致命的暴动。对囚犯而言，每一条面罩都在宣告，即使身陷镣铐，他们的兄弟情谊与反抗仍未消亡。"},{t="祖母的复仇",b="红色毛纺面罩因一名十四岁狱卒麦克·拉斯科尔的死而为人所知。他撞见囚犯撕碎毛毯制作面巾，便试图惩戒他们。迪菲亚罪犯从背后刺杀了他。他悲痛的祖母尼科瓦如今正在寻找冒险者，要他们进入暴乱中的地牢，剿杀暴徒，带回猩红的布片作为复仇的凭证。"}},faq={{q="监狱里的囚犯从哪里弄来这些面罩？",a="迪菲亚囚犯从监狱配发的毛毯上撕下布片，制成面罩。他们被缴了械，关进牢房，便把仅有的简陋卧具变成反抗的标志，戴在身上。",al={"面罩从哪里来","监狱面罩来源","红色面罩如何制作"}},{q="谁要收集这些面罩？",a="尼科瓦·拉斯克是暴风城一位悲痛的祖母，她请冒险者收集这些面罩。她十四岁的孙子麦克曾在监狱担任守卫，因撞见囚犯制作面巾而遭到杀害。",al={"谁需要红色毛纺面罩","鲜血的颜色任务给予者","尼科瓦·拉斯克面罩"}},{q="囚犯为什么如此在意佩戴红色面巾？",a="迪菲亚潜行者以红色面具和面罩作为帮派标志与制服。在铁窗之内，这些布片让囚犯得以维系等级、士气与团结。",al={"为什么戴红色面罩","迪菲亚红色标志","红色面罩的含义"}},{q="哪些囚犯身上带着面罩？",a="监狱里几乎所有参与暴乱的迪菲亚成员都带着一条，包括迪菲亚俘虏、迪菲亚狱友、迪菲亚囚徒、迪菲亚叛军和迪菲亚罪犯。",al={"谁掉落红色毛纺面罩","监狱面罩掉落"}}},fx={["7f0c1a2a"]={q="什么是红色毛纺面罩？",a="红色毛纺面罩是暴风城监狱里被囚禁的迪菲亚潜行者成员制作的深红色围巾。囚犯们把监狱发放的毛毯撕碎并染色，制成这种布制信物，以公开展示他们对迪菲亚潜行者的效忠，并在铁窗之后维持帮派身份。",al={"什么是红色毛纺面罩","红色毛纺面罩物品","监狱里的红色面罩"}}},fp="16,166,20.335.0,25.366.0,54.181.0,35.218.0,60.156.0,25.134.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="剩余的最纯净的水",s="萨满祭司在卡利姆多和洛丹伦各地收集布瑞恩调制药剂所需的水。最后剩下的几滴水，将随他们踏上一段险途。",h="萨满祭司在卡利姆多和洛丹伦各地收集布瑞恩调制药剂所需的水。最后剩下的几滴水，将随他们踏上一段险途。",kw={"圣泉火盆","布瑞恩","水之召唤","腐化的化身","最纯净的水","银松森林","水之图腾"},ang={["class:Shaman"]="身为萨满祭司，你要将这些水滴从干旱的贫瘠之地带到银松森林遭瘟疫侵蚀的海岸，这是你掌握水之力量的试炼之一。这场朝圣之旅是你获得水之图腾的必经之路。",["faction:Horde"]="身为部落的一员，你从卡利姆多的部落领地出发，前往被遗忘者在银松森林岌岌可危的领地。这场朝圣之旅跨越遥远的距离，以灵性的复苏对抗Scourge的瘟疫。"},sec={{t="净化污水的药剂",b="布瑞恩在贫瘠之地，用从卡利姆多和洛丹伦各地收集的水调制药剂。其中一部分能让萨满祭司看见远方的元素。余下的几滴水则留作更艰巨的用途。萨满祭司带着它们前往银松森林海岸，瑟伯切尔附近的圣泉火盆就在那里。水滴会与一只被污染的元素生物死后留下的护腕一同投入火中焚烧。纯净的水破除亡灵瘟疫的腐化，召来未受污染的水之灵，与萨满祭司交流，使他们完成与水元素的沟通。"}},faq={{q="这些水滴有什么用途？",a="这些水滴要与腐化的水元素化身留下的护腕一起，投入银松森林海岸的圣泉火盆。仪式会净化遭到腐化的元素圣坛，并召来未受腐化的水之灵。",al={"剩余水滴有什么作用","剩余水滴的用途","最纯净的水的用法"}},{q="这些液体从何而来？",a="它们是布瑞恩调制的净化药剂剩余的部分，她是一位住在贫瘠之地南部山丘上的兽人萨满祭司。她会在萨满祭司学徒接受精神试炼期间调制这种药剂。",al={"谁调制了最纯净的水","水滴的来源","布瑞恩的水滴"}},{q="为什么要远赴银松森林举行仪式？",a="瑟伯切尔以西的银松森林海岸上，有一座水之圣坛遭到了亡灵瘟疫的腐化。那里的元素之灵变得扭曲而充满敌意。远赴异地净化那处水池，考验着萨满祭司的虔诚与驾驭元素的能力。",al={"为何选择银松森林","为何前往银松森林","银松森林的水之圣坛"}},{q="水滴接触火盆时会发生什么？",a="水滴与被腐化的护腕一同投入火盆的烈焰后，会在火中噼啪作响。咒语会净化残留的瘟疫，并召来纯净的水元素化身。",al={"火盆仪式","火盆上会发生什么","圣泉火盆仪式"}}},fp="31,152,27.549.0,30.221.0,31.181.0,61.235.0,41.179.0"}
P.entries["item:remedy-of-arugal"] = {n="阿鲁高的拯救",s="在银松森林，达拉尔·道恩维沃尔正寻找阿鲁高的法术，以弄清他的狼人魔法如何运作。",h="在银松森林，达拉尔·道恩维沃尔正寻找阿鲁高的法术，以弄清他的狼人魔法如何运作。",kw={"阿鲁高","阿鲁高的愚行","达拉尔·道恩维沃尔","积满灰尘的法术书","月怒","阿鲁高的拯救","瑟伯切尔","银松森林"},ang={["class:Mage"]="身为被遗忘者法师，你或许和达拉尔·道恩维沃尔一样，鄙视阿鲁高笨拙而鲁莽的实验，同时也看到了召唤魔法失控的危险。",["race:Undead"]="身为被遗忘者的一员，你协助取得这道法术，是对抗威胁银松森林边境的凶野狼人的早期关键一步。"},sec={{t="法师的遗留之物",b="占据影牙城堡之前，大法师阿鲁高曾栖身于银松森林河桥北面的一座废弃麦田农场。他将自己的诡异法术记在法术书中，留在农具与腐朽的地板之间。其中一份名为阿鲁高的拯救的卷轴，记述了他早期研究变形术时使用的方法和魔法公式，正是这些实验让当地人遭受了诅咒。"},{t="被遗忘者的审视",b="达拉尔·道恩维沃尔是瑟伯切尔的一名被遗忘者施法者，他对阿鲁高的地位不屑一顾，认为此人的才智脆弱而浅薄。尽管如此，道恩维沃尔仍需弄清狼人诅咒的运作方式。取回阿鲁高的拯救，就能让被遗忘者的密探掌握道恩维沃尔所需的奥术知识，遏制阿鲁高不断蔓延的威胁，并为希尔瓦娜斯女士守住银松森林。"}},faq={{q="阿鲁高的拯救是什么？",a="阿鲁高的拯救是叛变的法师阿鲁高写下的一道法术。它记载了他最初在银松森林进行狼人魔法实验时使用的奥术方法。",al={"阿鲁高的拯救是什么","阿鲁高的拯救物品","拯救法术"}},{q="阿鲁高的拯救被遗留在哪里？",a="阿鲁高将阿鲁高的拯救留在一座废弃麦田农场楼上的积尘法术书中，农场就在银松森林河桥的北面。",al={"哪里能找到阿鲁高的拯救","阿鲁高的拯救位置","农场法术书"}},{q="达拉尔·道恩维沃尔为什么想要这道法术？",a="达拉尔·道恩维沃尔想研究阿鲁高使用的魔法，让被遗忘者能够找到应对之法，守住银松森林。",al={"达拉尔为什么需要阿鲁高的拯救","达拉尔·道恩维沃尔的拯救法术"}},{q="谁在守卫农场里的法术书？",a="阿鲁高麾下的狼形奴仆盘踞在农场中。一旦有人翻动二楼那些积满灰尘的法术书，一只月怒夜行者就会跃出，保护主人的物品。",al={"农场里什么会发动攻击","法术书伏击"}}},fp="16,96,18.379.0,17.375.0,29.124.0,33.136.0,42.113.0,38.171.0"}
P.entries["item:rendered-spores"] = {n="提炼过的孢子",s="提炼过的孢子正从药剂师赫布瑞姆手中出发，穿越贫瘠之地，赶在变质前送往雷霆崖。药剂师扎玛必须在城下使这份乳液稳定下来。",h="提炼过的孢子正从药剂师赫布瑞姆手中出发，穿越贫瘠之地，赶在变质前送往雷霆崖。药剂师扎玛必须在城下使这份乳液稳定下来。",kw={"药剂师赫布瑞姆","药剂师扎玛","贫瘠之地","十字路口","乳液","预见之池","提炼过的孢子","雷霆崖"},ang={["race:Tauren"]="身为牛头人，你看到被遗忘者药剂师在神圣的预见之池中，用贫瘠之地的奇异植物进行实验。他们的工作体现了雷霆崖内部结成的那个充满不安、却又务实的联盟。",["race:Undead"]="身为亡灵，你所属族群的皇家药剂师学会正在卡利姆多各地寻找生物化合物，以帮助被遗忘者。行动迅速的信使将赫布瑞姆这样的实地研究员与扎玛这样的专家联系起来。"},sec={{t="不稳定的混合物",b="药剂师赫布瑞姆用贫瘠之地潮湿绿洲附近采集的菌类孢子，制成提炼过的孢子。他将这些奇异的孢子加工成具有活性的化学乳液，但它很不稳定。四十五分钟后，乳液就会分解，无法再用于科学研究。"},{t="送往预见之池",b="药剂师赫布瑞姆无法在偏远的哨站完成乳液的精炼。这份乳液必须送到他那位被遗忘者同僚药剂师扎玛手中，她就在雷霆崖的灵魂高地下方。在预见之池，扎玛拥有所需的设备和试剂，可以重新密封这些孢子，并为皇家药剂师学会完成后续加工。"}},faq={{q="提炼过的孢子有什么用途？",a="药剂师赫布瑞姆将真菌物质制成乳液，供皇家药剂师学会研究。在雷霆崖，药剂师扎玛用它继续研究那些在贫瘠之地蔓延的奇异生长物。",al={"提炼过的孢子的用途","扎玛 如何使用孢子","为什么要提炼孢子"}},{q="为什么乳液有时间限制？",a="药剂师赫布瑞姆制成的乳液很不稳定，刚混合好就开始变质。它的活性只能维持四十五分钟，因此必须在失去活性前穿越平原，送到雷霆崖。",al={"提炼过的孢子为何限时","孢子为何过期","提炼过的孢子的有效时间"}},{q="这些孢子是谁制成的？",a="药剂师赫布瑞姆是驻扎在贫瘠之地十字路口的被遗忘者研究员，他将绿洲附近采集的未经加工的菌类孢子制成不稳定的液态化合物。",al={"谁制成了提炼过的孢子","谁提炼孢子","赫布瑞姆 孢子"}},{q="这份混合物需要送到哪里？",a="这份混合物必须送到药剂师扎玛手中，她住在牛头人主城雷霆崖的灵魂高地下方，那里是预见之池。",al={"提炼过的孢子送到哪里","扎玛 的位置","预见之池的位置"}}},fp="15,153,18.219.0,31.310.0,34.217.0,40.211.0,25.134.0,34.120.0"}
P.entries["item:renferrel-s-findings"] = {n="伦弗利尔的研究成果",s="在银松森林，伦弗利尔的研究成果将研究资料送往南方的塔伦米尔。药剂师伦弗利尔在瑟伯切尔整理了这些笔记，交给正在协助被遗忘者研制新的瘟疫的药剂师林度恩。",h="在银松森林，伦弗利尔的研究成果将研究资料送往南方的塔伦米尔。药剂师伦弗利尔在瑟伯切尔整理了这些笔记，交给正在协助被遗忘者研制新的瘟疫的药剂师林度恩。",kw={"研究成果","林度恩","新的瘟疫","伦弗利尔","皇家药剂师学会","瑟伯切尔","塔伦米尔"},ang={["faction:Horde"]="身为部落的一员，你知道携带伦弗利尔文件的信使将瑟伯切尔和塔伦米尔等前哨站联系起来，巩固着部落在洛丹伦各地的立足之地。",["race:Undead"]="身为亡灵，你知道这些文件服务于希尔瓦娜斯·风行者的雄心：完善新的瘟疫，用来对付Scourge以及侵占被遗忘者领地的生者之敌。"},sec={{t="研制中的瘟疫",b="在瑟伯切尔，药剂师伦弗利尔记录着他对新的瘟疫的研究。皇家药剂师学会奉黑暗女王——希尔瓦娜斯·风行者女士的直接命令开展工作。散布在洛丹伦各地的研究人员必须通力合作，才能取得突破。伦弗利尔将研究成果送往南方的塔伦米尔，让那里的研究同僚能够在他的成果上继续钻研。"},{t="前往塔伦米尔",b="这些文件将银松森林与希尔斯布莱德丘陵以及被遗忘者的炼金网络联系起来。药剂师林度恩正在塔伦米尔等待伦弗利尔的笔记，以便与自己针对生者和天灾军团的研究进行比较。可靠的信使必须穿越希尔斯布莱德争夺不断的道路；没有他们，学会分散在各地的研究很快就会陷入停滞。"}},faq={{q="伦弗利尔的研究成果包含什么？",a="伦弗利尔的研究成果包含药剂师伦弗利尔在银松森林的最新研究和实验数据。这些笔记涉及被遗忘者研制新的瘟疫的工作。",al={"研究成果是什么","伦弗利尔的研究","笔记里有什么"}},{q="这些研究资料应交给谁？",a="这些文件应交给药剂师林度恩。他在塔伦米尔进行瘟疫研究，那里是被遗忘者在希尔斯布莱德丘陵的一处定居点。",al={"伦弗利尔的研究成果交给谁","研究成果送往哪里","交付对象"}},{q="药剂师们为何要分享笔记？",a="希尔瓦娜斯·风行者女士已命令皇家药剂师学会研制新的瘟疫。药剂师们相信，相互比较研究结果会比独自钻研更快取得突破。",al={"为何分享研究成果","为何送给林度恩","药剂师之间的交流"}},{q="药剂师伦弗利尔在哪里进行实验？",a="药剂师伦弗利尔在瑟伯切尔进行实验，那里是被遗忘者在银松森林腹地的主要前哨站。",al={"伦弗利尔在哪里","药剂师伦弗利尔的位置","伦弗利尔的研究成果是谁写的"}}},fx={bf8d559a={q="伦弗利尔的研究成果从何而来？是谁编写的？",a="这些文献由药剂师伦弗利尔撰写。他是一位雄心勃勃的研究者，驻扎在银松森林的瑟伯切尔。在被遗忘者的命令下，他勤勉工作，写下这些笔记，记录自己调制实验性药剂的进展与突破。",al={"谁写了伦弗利尔的研究成果","伦弗利尔的研究成果从何而来","伦弗利尔的研究成果作者"}},["21b2c0f4"]={q="为什么有人想要伦弗利尔的研究成果？",a="皇家药剂师协会正承受着希尔瓦娜斯·风行者女士施加的巨大压力，必须研制出一种新瘟疫。伦弗利尔相信合作能加快这项阴暗的事业，于是将研究成果寄给了塔伦米尔的药剂师林度恩。林度恩迫切希望研究这位同僚的方法，并将其融入自己的工作。",al={"为什么要送交伦弗利尔的研究成果","谁想要伦弗利尔的研究成果","林度恩为什么想要伦弗利尔的研究成果"}},f680c460={q="什么是伦弗利尔的研究成果？",a="伦弗利尔的研究成果是药剂师伦弗利尔汇编的一批炼金笔记和研究文件。这些资料详细记录了他代表皇家药剂师协会开展的持续实验，并打算直接分享给洛丹伦的同行。",al={"什么是伦弗利尔的研究成果","伦弗利尔的研究成果物品","这些研究成果是什么"}}},fp="20,209,23.354.0,14.377.0,36.173.0,41.139.0,39.189.0,56.127.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="有关迪菲亚兄弟会的报告",s="在暴风要塞，关于迪菲亚潜行者的调查结果被呈交王庭。城市建筑师巴隆斯·阿历克斯顿将报告托付给了揭露这场阴谋的冒险者。",h="在暴风要塞，关于迪菲亚潜行者的调查结果被呈交王庭。城市建筑师巴隆斯·阿历克斯顿将报告托付给了揭露这场阴谋的冒险者。",kw={"觐见国王","巴隆斯·阿历克斯顿","迪菲亚","报告","暴风要塞","范克里夫","西部荒野"},ang={["faction:Alliance"]="递交这份报告，便将保卫西部荒野、向暴风城领袖们警示边境叛乱的长期斗争呈到了王庭面前。",["race:Human"]="作为王国的人类子民，你携带的报告讲述了暴风城贵族家族与重建这座城市的石匠之间尚未平息的冲突。"},sec={{t="一份发往王座的公文",b="城市建筑师巴隆斯·阿历克斯顿长期调查了西部荒野及周边地区的动乱，随后为暴风城的领袖们撰写了这份报告。他将报告托付给了查明这场阴谋的冒险者。\n\n报告被送往暴风要塞，等待当面呈交。调查结果涉及阴谋者的计划，以及他们对王国构成的威胁。"},{t="在要塞的接待",b="信使抵达王座厅时，瓦里安·乌瑞恩国王正在外进行外交访问。王室顾问和代年幼国王安度因执政的摄政者代他接收了报告。他们嘉奖了信使，表彰其挫败了范克里夫的计划。\n\n警讯传到摄政者面前时，女伯爵卡特拉娜·普瑞斯托也在场。"}},faq={{q="什么是《有关迪菲亚兄弟会的报告》？",a="这份报告是巴隆斯·阿历克斯顿撰写的正式简报。其中汇集了关于艾德温·范克里夫、他的地下军队，以及迪菲亚针对暴风城策划的更大阴谋的情报。",al={"这份报告是什么","迪菲亚报告物品","巴隆斯·阿历克斯顿报告"}},{q="谁撰写了这份报告？",a="这份报告由暴风城的城市建筑师巴隆斯·阿历克斯顿撰写。在石匠们脱离暴风城、成立迪菲亚潜行者之前，他曾与他们共事。",al={"谁制作了迪菲亚报告","报告作者"}},{q="为什么我要把它送到暴风要塞？",a="巴隆斯·阿历克斯顿认为，揭露这场阴谋的冒险者理应亲自向王室呈交调查结果。他希望你能因保卫王国而获得王室的嘉奖。",al={"为什么要我递送这个","觐见国王递送"}},{q="瓦里安国王读了这份报告吗？",a="没有。你抵达暴风要塞时，瓦里安·乌瑞恩国王正在外进行外交访问。他的宫廷成员和摄政者代他接收了报告。",al={"国王读过吗","瓦里安·乌瑞恩觐见"}}},fp="32,178,25.367.0,21.337.1,45.170.1,22.160.1,43.182.0,33.138.0"}
P.entries["item:resonite-crystal"] = {n="共鸣水晶",s="在滚岩洞穴中，狗头人正疯狂挖掘共鸣水晶。他们的举动引起了烈日石居的摩罗加尔的担忧。",h="在滚岩洞穴中，狗头人正疯狂挖掘共鸣水晶。他们的举动引起了烈日石居的摩罗加尔的担忧。",kw={"滚岩","水晶","土灵","狗头人","摩罗加尔","共鸣水晶","石爪山","泰坦"},ang={["class:Shaman"]="身为萨满祭司，你能感受到共鸣水晶中令人不安的共鸣：那是埋藏在山脉之下的Titan造物留下的、沉睡的原始大地魔法。",["profession:Mining"]="身为矿工，你发现Resonite形成的矿体极为密集，与普通的铜矿脉或锡矿脉截然不同。想要采到它，就必须穿过凶悍的狗头人盘踞之处，深入最底层的地下岩层。"},sec={{t="远古的共鸣",b="共鸣水晶引得狗头人在滚岩峡谷深处疯狂挖掘。他们突然如此关注这些石头，让烈日石居的萨满祭司感到不安。摩罗加尔检查了水晶，发现其中有微弱的魔法嗡鸣。他辨认出了土灵魔法的痕迹，这表明狗头人已经挖入了泰坦塑造的远古地层。"},{t="汲取大地之力",b="共鸣水晶表明，狗头人的挖掘已经深入到足以惊扰远古土灵的地方。泰坦创造了土灵，让他们雕琢塑造世界的根基，而他们的魔法至今仍附着在周围的岩石上。部落的行动人员收集这些水晶，想要弄清狗头人的动机，并利用这些魔法石的力量对付沉睡在地下的存在。"}},faq={{q="哪里能找到共鸣水晶？",a="共鸣水晶位于石爪山脉东南部、滚岩峡谷深处的滚岩洞穴内。",al={"共鸣水晶位置","哪里获取共鸣水晶","共鸣水晶采集"}},{q="狗头人为什么要开采共鸣水晶？",a="狗头人正疯狂开采这些稀有水晶，但摩罗加尔并不知道原因。他请求收集样本，并调查洞穴深处，以查明他们在做什么。",al={"狗头人为何挖矿","狗头人水晶阴谋","滚岩狗头人"}},{q="共鸣水晶中蕴藏着什么力量？",a="摩罗加尔怀疑，这些水晶与山脉之下某种令人不安的存在有关。在收到洞穴中的样本和消息后，他确认了水晶的魔法性质。",al={"共鸣水晶魔法","共鸣水晶是什么","共鸣水晶有魔法吗"}},{q="谁在研究这些水晶？",a="摩罗加尔是石爪山脉烈日石居的一名牛头人，他研究这些水晶，是为了弄清狗头人活动突然增多的原因，并找到对抗已被挖出的邪恶的方法。",al={"谁需要共鸣水晶","摩罗加尔水晶","烈日石居共鸣水晶"}},{q="与水晶有关的土灵是什么？",a="据说土灵由泰坦创造，负责塑造大地。摩罗加尔正在调查他们与共鸣水晶之间可能存在的联系。",al={"土灵是什么","土灵与泰坦的联系"}}},fx={c14b6c8c={q="什么是共鸣水晶？",a="共鸣水晶是一种稀有矿物晶体，产自石爪山脉的滚岩洞穴。狗头人疯狂采矿的行为惊动了摩罗加尔，他希望得到样本和洞穴的消息，以便展开调查。",al={"什么是共鸣水晶","共鸣水晶的背景","共鸣矿石"}},af246400={q="为什么有人想要共鸣水晶？",a="摩罗加尔想要矿石样本，以弄清狗头人疯狂采矿的原因，并查明滚岩峡谷下方有什么。他请一位冒险者探索洞穴并收集水晶。",al={"为什么要收集共鸣水晶","谁想要共鸣水晶","共鸣水晶的用途"}}},fp="16,131,17.290.1,17.334.1,34.123.0,45.172.0,44.170.0,31.194.0,60.129.0"}
P.entries["item:restabilization-cog"] = {n="自适应齿轮",s="在诺莫瑞根大门外，麻风侏儒仍随身携带着自适应齿轮。在卡拉诺斯，工匠们需要完好的齿轮，来制造一台旨在逆转麻风变异的机器。",h="在诺莫瑞根大门外，麻风侏儒仍随身携带着自适应齿轮。在卡拉诺斯，工匠们需要完好的齿轮，来制造一台旨在逆转麻风变异的机器。",kw={"丹莫罗","吉波维特","诺莫瑞根","卡拉诺斯","麻风侏儒","自动净化装置","拉兹·滑链","自适应齿轮"},ang={["profession:Engineering"]="身为工程师，你能看出自适应齿轮如何装配在净化装置等侏儒机器中。",["race:Gnome"]="身为流亡丹莫罗的侏儒，你从遭到腐化的同胞身上取得机械零件，希望为诺莫瑞根那些受难者找到疗法。"},sec={{t="救治所需的零件",b="为了消灭入侵的石腭怪，侏儒们用辐射淹没了诺莫瑞根，但这一尝试失败了。无数侏儒染上疾病，变得充满敌意，随后逃离家园，沦为流亡者。即使陷入疯狂，他们仍携带着精密的侏儒机械。\n\n奥齐·电环和拉兹·滑链相信，这种可怕的变化能够逆转。他们的自动净化装置原型机需要从诺莫瑞根大门外的患病者身上取得零件。完好的自适应齿轮将使机器内部的燃烧系统保持平衡。"}},faq={{q="自适应齿轮有什么用途？",a="在卡拉诺斯，工匠拉兹·滑链需要自适应齿轮来制造净化装置。它们与多档齿轮一起，构成了这台实验机器的部分组件，旨在治愈受到辐射的麻风侏儒。",al={"齿轮用途","自适应齿轮有什么用","为什么收集齿轮"}},{q="在哪里能找到这些齿轮？",a="麻风侏儒和精神错乱的吉波维特携带着这些齿轮。他们在丹莫罗西部的诺莫瑞根外围大门和壕沟一带游荡。",al={"自适应齿轮位置","谁掉落齿轮","哪里刷齿轮"}},{q="净化装置真的能治愈麻风侏儒吗？",a="拉兹·滑链和奥齐·电环相信，经过校准的机械能够逆转变异。净化装置能否让麻风侏儒恢复心智与身体，仍未经验证，寻找疗法的努力还在继续。",al={"净化装置是否有效","麻风侏儒有疗法吗"}}},fx={["8ac7e8f1"]={q="什么是自适应齿轮？",a="自适应齿轮是一种精密机械零件，回收自诺莫瑞根废墟城外损毁的机器，以及在那里游荡的受辐射麻风侏儒。这些齿轮用于维持复杂侏儒装置的结构与旋转平衡，深受工匠珍视，他们需要坚固的预制零件，来稳定奥齐·电环的净化装置这类反复无常的发明。",al={"自适应齿轮是什么","自适应齿轮背景","关于自适应齿轮"}},ceb0040c={q="自适应齿轮来自哪里？",a="这些齿轮出自诺莫瑞根庞大的机械工厂。灾难性的辐射排放发生后，城市开始疏散，无数自动装置以及那些不幸陷入麻风癫狂的幸存者，将这些标准化零件带到了城门外的雪地上。",al={"自适应齿轮由谁制造","自适应齿轮起源","自适应齿轮来自哪里"}}},fp="19,156,21.476.0,39.203.0,30.142.0,54.220.0"}
P.entries["item:ring-of-zoram"] = {n="佐拉姆之戒",s="在佐拉姆，城中统治者的戒指沉入海底数千年后，再次重现于世。如今它落在纳迦手中，而塔尔伦正在寻找开启一尊古代雕像的钥匙。",h="在佐拉姆，城中统治者的戒指沉入海底数千年后，再次重现于世。如今它落在纳迦手中，而塔尔伦正在寻找开启一尊古代雕像的钥匙。",kw={"古代雕像","灰谷","薇丝比娅","佐拉姆之戒","卢泽尔","塔尔伦","佐拉姆海岸"},ang={["faction:Alliance"]="从纳迦手中夺回戒指，有助于暗夜精灵学者塔尔伦在灰谷纷争不断的边境找回Kaldorei的历史。",["race:NightElf"]="这枚戒指是一件留存至今的Sundering之前的遗物，见证了奥术带来的狂妄与淹没大地的海水撕裂Kaldorei帝国之前的岁月。"},sec={{t="沉没之城的戒指",b="在永恒之井崩塌之前，佐拉姆坐落于卡利姆多西海岸，是暗夜精灵帝国的一颗明珠。城中的统治者佩戴着佐拉姆之戒，戒指内圈刻着一段用暗夜精灵语写成的奇异密码。一万年前，大灾变撕裂了大陆，戒指也随城市一同沉入海中。它沉在如今的佐拉姆海岸水下。"},{t="纳迦寻回之物",b="数千年来，淤泥与废墟掩埋着这枚戒指。后来，纳迦开始搜寻灰谷沿岸，住在海岸北段外一座小岛上的纳迦首领卢泽尔，从沉没的残骸中找到了它。暗夜精灵学者塔尔伦寻找这枚戒指，并不只是因为它年代久远。它是开启那些从深海打捞上来的遗物的唯一钥匙，其中就包括封存在海底的古代雕像。"}},faq={{q="佐拉姆之戒有什么用途？",a="在大分裂使佐拉姆沉没之前，城中的统治者佩戴着这枚戒指，它也是开启一把古老锁具的钥匙。如今，塔尔伦正在寻找它，用来开启一尊从水下废墟中寻回的上锁雕像。",al={"佐拉姆之戒用途","戒指有什么用","佐拉姆之戒背景故事"}},{q="佐拉姆之戒在谁手中？",a="入侵佐拉姆海岸的纳迦从废墟中打捞出了这枚戒指。他们的首领卢泽尔在北部海岸外的一座岛上持有它，不过，那位颇有名望的纳迦薇丝比娅也曾携带过它。",al={"戒指在谁手中","佐拉姆之戒掉落","哪里获得佐拉姆之戒"}},{q="塔尔伦为什么想要这枚戒指？",a="塔尔伦想揭开一尊从佐拉姆海岸寻回的古代雕像的秘密。没有佐拉姆之戒作为钥匙，就无法打开雕像的机关。",al={"塔尔伦为何想要戒指","塔尔伦戒指任务"}},{q="佐拉姆城去了哪里？",a="在大灾变之前，佐拉姆是卡利姆多西缘的一座暗夜精灵城市。一万年前，永恒之井向内坍塌，城市随之毁灭，沉入波涛之下，只留下了佐拉姆海岸。",al={"佐拉姆发生了什么","佐拉姆城背景故事"}}},fx={["7e40c0d5"]={q="什么是佐拉姆之戒？",a="佐拉姆之戒是一件古老遗物，曾由沉没之城佐拉姆的统治者佩戴，直到大分裂的巨浪将这座城市淹没。戒指内侧用暗夜精灵语写着一段奇怪的密码，而它正是开启一尊从遗迹中找到的雕像上的古老锁具的钥匙。",al={"什么是佐拉姆之戒","佐拉姆之戒的背景","佐拉姆之戒物品"}},["770adfa7"]={q="佐拉姆之戒从何而来？是谁制造的？",a="这枚戒指源自大分裂前的暗夜精灵城市佐拉姆，位于古卡利姆多的海岸。它曾属于城中统治者；一万年前，灾难性的巨浪淹没了佐拉姆，这件遗物也随之沉入海底，直到最近才被娜迦从遗迹中打捞出来。",al={"佐拉姆之戒的来源","谁制造了佐拉姆之戒","佐拉姆之戒从何而来"}}},fp="13,163,23.386.0,23.375.0,35.192.0,32.200.0,29.173.0,31.228.0"}
P.entries["item:robo-mechanical-guts"] = {n="机械内胆",s="在暴风城，舒尼正收集诺莫瑞根游荡机械的零件。她需要用这些零件修理掘进载具，以协助夺回丹莫罗的那座城市。",h="在暴风城，舒尼正收集诺莫瑞根游荡机械的零件。她需要用这些零件修理掘进载具，以协助夺回丹莫罗的那座城市。",kw={"发条","丹莫罗","诺莫瑞根","回转式挖掘机","机械内胆","舒尼","暴风城"},ang={["profession:Engineering"]="每一团电线和每一个陀螺齿轮，都出自侏儒的自动机械设计。辐射与隔绝改变了这些机械，如今它们四处游荡。",["race:Gnome"]="身为侏儒，拆解失落家园中失控的发条哨兵，或许会让你百感交集。它们的机械零件可以帮助夺回诺莫瑞根。"},sec={{t="为车队回收零件",b="大工匠 格尔宾·梅卡托克 和幸存的侏儒逃离诺莫瑞根后，数以千计的机械被留在了那里。自动机械、发条哨兵和工业机器人仍在这座受辐射污染的城市走廊中游荡。\n\n在暴风城，工匠舒尼正组装 陀螺式挖掘机，准备突破诺莫瑞根的防御，夺回这座失落的城市。她派冒险者进入受污染的大厅，从机器人身上回收还能使用的零件，包括弹簧、电线和陀螺仪组件。"}},faq={{q="机械内胆有什么用途？",a="暴风城的舒尼收集机械内胆，用来修理回转式挖掘机。这些掘进载具旨在帮助收复丹莫罗的诺莫瑞根。",al={"机器人内脏有什么用","机械内胆用途","为什么收集机械内脏"}},{q="这些组件在哪里能找到？",a="你可以从诺莫瑞根外围和深处游荡的敌对发条自动机械、机甲以及受污染的敌人身上回收这些组件。",al={"哪里获取 机械内胆","机器人内脏掉落地点","诺莫瑞根机器人零件"}},{q="舒尼是谁，她为什么需要这么多零件？",a="舒尼是一名驻扎在暴风城矮人区的侏儒工程师。她需要零件来整备近四百台地下挖掘机械，以突破被占据的诺莫瑞根废墟。",al={"舒尼 是谁","舒尼 暴风城","陀螺式挖掘机 车队"}}},fx={b1d0efc3={q="什么是机械内胆？",a="它们是从诺莫瑞根内游荡的发条自动机身上拆下的内部机械、齿轮、线路，以及可回收的机械零件，彼此缠绕交错。在外行眼中，这些东西与废料无异，但其中仍能运作的机械部件提供了至关重要的基础机件，心灵手巧的侏儒工程师可以将其改装，用于复杂的载具工程。",al={"机械内胆是什么","机械内胆物品"}},cf2ae288={q="机械内胆来自哪里，又是谁制造的？",a="这些组件出自诺莫瑞根的工坊，由侏儒发明家制造，为自动劳工和城市防御装置提供动力。辐射灾难袭来、大工匠梅卡托克下令疏散时，无数机械构造体被遗弃在城内，至今仍在残破的通道中游荡，内部机件依然完好。",al={"机械内胆由谁制造","机械内胆来自哪里","机械内胆起源"}},f52d09f9={q="为什么有人需要机械内胆？",a="暴风城的沉默的舒尼急需这些替换零件，来修复一整支旋转钻探挖掘机队。人类都城里的物资有限，因此她将诺莫瑞根中失控的机械视为一座资源丰富的废料场，以维持她的工程机队运转。",al={"为什么收集机械内胆","谁需要机械内胆","舒尼为什么需要机械内胆"}}},fp="20,161,21.513.0,39.171.0,35.145.0,49.191.0"}
P.entries["item:rocket-car-parts"] = {n="火箭车零件",s="火箭车零件是千针石林的闪光平原上四处散落的扭曲金属残骸，都是高速碰撞留下的。鲁莽的侏儒和地精赛车手不断将试验型赛车推向极限之外，源源不断地制造出这些废料，而投机者则将它们收集起来，指望靠赛道事故赚上一笔快钱。",h="火箭车零件是千针石林的闪光平原上四处散落的扭曲金属残骸，都是高速碰撞留下的。鲁莽的侏儒和地精赛车手不断将试验型赛车推向极限之外，源源不断地制造出这些废料，而投机者则将它们收集起来，指望靠赛道事故赚上一笔快钱。",kw={"工程学","侏儒","地精","克拉维尔·浓须","沙漠赛道","火箭车零件","废料回收","闪光平原","千针石林"},ang={["profession:Engineering"]="盐滩上遍地都是烧焦的齿轮和扭曲的排气组件，见证着侏儒与地精工程学理念中混乱而极端的一面。",["race:Dwarf"]="侏儒和地精只关心比赛本身，而克拉维尔·浓须这样有生意头脑的矮人却证明，真正的利润藏在他们身后留下的残骸里。"},sec={{t="速度、残骸与精明生意",b="闪光平原上的沙漠赛道，是地精与侏儒工程学展开无休止的火爆较量的舞台。为了追求无可匹敌的陆地速度，赛车手们经常遭遇灾难性的机械故障、点火引发的爆炸和高速撞车，将金属碎片撒遍盐滩。这些被丢弃的残骸，从弯曲的汽缸、烧焦的齿轮到压瘪的金属板，都不会被遗弃太久。拾荒者和商人会雇用过路的冒险者，搜遍这片白得刺眼的旷野，收集残骸，其中最典型的就是善于投机的矮人克拉维尔·浓须。两支赛车队始终急需备用机械部件，好拼凑出下一辆原型车，因此捡来的残骸很容易直接转卖给当初撞毁它们的车队。"}},faq={{q="这些火箭车零件都是从哪里来的？",a="它们是沙漠赛道上不断发生的撞车、爆炸和机械故障留下的残骸。侏儒和地精车手经常驾驶不稳定的试验型火箭动力赛车，在千针石林广阔的盐滩上不断挑战极限，直到车辆彻底毁坏。",al={"盐滩上为什么有零件","火箭车废料来源","零件从哪里来"}},{q="谁会购买这些回收的废料？",a="像矮人克拉维尔·浓须这样的商人会从流浪者手中收购残骸，再把回收的齿轮、金属板和小装置转卖给侏儒和地精，因为他们总是需要备用材料来修理和改进赛车。",al={"谁需要火箭车零件","克拉维尔·浓须火箭车零件","谁收购残骸"}},{q="捡拾这些零件有危险吗？",a="这些碎片本身只是不会动的残骸，不过偶尔也带着惨烈撞车留下的可怕痕迹，比如夹在金属中的残肢。主要的危险来自盐滩上充满敌意的野生动物，包括在残骸散落之处游荡的蜥蜴、焦灼的蝎子，以及四处觅食的盐地秃鹫。",al={"捡零件安全吗","收集零件时的威胁"}},{q="侏儒和地精会介意这些零件来自撞毁的赛车吗？",a="丝毫不会。无论侏儒还是地精参赛者，都不嫌弃回收材料。他们唯一在意的，就是弄到还能用的机械装置、齿轮和金属板，组装出速度足以在赛道上超越对手的赛车。",al={"赛车手在意残骸吗","地精为什么重复利用废品"}}},fx={["9a01e74a"]={q="什么是火箭车零件？",a="它们是闪光平原上高速赛车事故留下的散落残骸，包括松脱的齿轮、汽缸、扭曲的金属板和拆下来的小玩意。这些零件曾安装在轰鸣的实验赛车上，那些赛车由参加沙漠赛道竞速的地精和侏儒速度狂人制造。",al={"什么是火箭车零件","火箭车零件的背景","这些零件是什么"}}},fp="16,216,34.487.0,46.227.0,31.210.0,36.213.0,68.161.0"}
P.entries["item:rod-of-channeling"] = {n="导能魔棒",s="在湿地，龙喉氏族施法者随身携带着导能魔棒。为召唤地狱猎犬，术士会收集三根魔棒，交给斯坦哈德·法尔杉的侍僧，用来稳定棘齿城的仪式法阵。",h="在湿地，龙喉氏族施法者随身携带着导能魔棒。为召唤地狱猎犬，术士会收集三根魔棒，交给斯坦哈德·法尔杉的侍僧，用来稳定棘齿城的仪式法阵。",kw={"怒牙营地","白骨守卫","龙喉氏族","地狱猎犬","导能魔棒","暗影守卫","斯坦哈德·法尔杉","阴谋之书"},ang={["class:Warlock"]="身为术士，你会在阴谋之书的试炼中收集三根导能魔棒。当你束缚自己的第一只地狱猎犬时，它们会帮助控制仪式。"},sec={{t="束缚之器",b="要束缚狂暴的地狱猎犬，术士需要的不只是意志力。斯坦哈德·法尔杉要求准备三根配套的魔棒，让他的侍僧一同引导魔法，在术士束缚野兽时稳定召唤法阵。龙喉氏族 黑暗法师携带这些魔棒，用于自己的施法活动。在怒牙营地及周边的湿地废墟中，白骨守卫和暗影守卫都带着这种魔棒。战斗让魔棒磨损，留下缺口，但它们仍能聚集混乱的虚空能量。"}},faq={{q="导能魔棒有什么用途？",a="这些魔棒要交给棘齿城上方的斯坦哈德·法尔杉。他的侍僧用它们引导魔法，稳定召唤并束缚敌对地狱猎犬所需的法阵。",al={"什么是导能魔棒","导能魔棒用途","为什么需要导能魔棒"}},{q="在哪里能找到导能魔棒？",a="湿地的龙喉氏族施法者随身携带这些魔棒，尤其是怒牙营地周围的龙喉白骨守卫和龙喉暗影守卫。",al={"哪里获取导能魔棒","谁掉落导能魔棒","导能魔棒位置"}},{q="斯坦哈德为什么需要三根魔棒？",a="斯坦哈德的侍僧会协助进行召唤地狱猎犬的仪式。每位侍僧都需要一件法器，在术士制服野兽时维持魔法通道的稳定。",al={"为什么要三根魔棒","为什么要三根导能魔棒"}},{q="龙喉氏族为什么使用这些魔棒？",a="龙喉氏族氏族将这些魔棒用于黑暗萨满法术和暗影秘术，这些都是旧部落的遗存。该氏族的白骨守卫和暗影守卫在湿地持续不断的领土争夺战中，用它们引导诅咒、通灵术和暗影魔法。",al={"龙喉氏族魔棒","龙喉氏族为什么有魔棒"}}},fp="17,163,22.464.0,39.158.0,38.133.0,33.140.0,39.227.0"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="罗尔夫和马拉凯的铭牌",s="在艾尔文东部，罗尔夫和马拉凯的铭牌上刻着王国的徽记，但它们的主人却在巡逻途中失踪了。卫兵托马斯正在寻找这些铭牌，以查明手下的遭遇。",h="在艾尔文东部，罗尔夫和马拉凯的铭牌上刻着王国的徽记，但它们的主人却在巡逻途中失踪了。卫兵托马斯正在寻找这些铭牌，以查明手下的遭遇。",kw={"东谷","艾尔文","卫兵托马斯","马拉凯","铭牌","鱼人","罗尔夫","暴风城卫兵"},ang={["faction:Alliance"]="即使身处联盟腹地，当地卫兵在守护乡间商路时，仍面临着致命的危险。",["race:Human"]="对艾尔文的人类而言，这些铭牌意味着他们失去了自己的儿子和守护者。两人的死表明，当军队忙于应付别处的战事时，王国便显得脆弱。"},sec={{t="噩耗得到证实",b="卫兵托马斯负责指挥艾尔文东部的哨站。罗尔夫和马拉凯在河岸一带失踪后，他便担心两人已遭不测。他们的铭牌证实，这两名卫兵死于步步进犯的鱼人之手。王国兵力捉襟见肘之际，这些士兵一直坚守防线，抵御荒野中的威胁，如今暴风城驻军却失去了他们。"},{t="服役的凭证",b="人类卫兵在城中执勤或在乡间巡逻时，都会携带表明身份的铭牌。这些铭牌表明他们效忠王室，并奉王室之命行使职权。将罗尔夫和马拉凯的铭牌交还卫兵托马斯，便能让他查明失踪手下的下落，并在战地报告中记录他们的牺牲。他还能就商路附近定居的好战鱼人部族发出警告。"}},faq={{q="罗尔夫和马拉凯的铭牌是什么？",a="罗尔夫和马拉凯的铭牌是暴风城卫兵携带的服役身份证明。这两名卫兵驻守艾尔文森林东部时，遭到鱼人伏击并被杀害。",al={"铭牌是什么","罗尔夫的铭牌","马拉凯的铭牌"}},{q="这些铭牌属于谁？",a="这些铭牌属于卫兵罗尔夫和马拉凯。他们听命于卫兵托马斯，负责看守闪金镇与东谷伐木场之间的河流和道路。",al={"罗尔夫和马拉凯是谁","谁的铭牌"}},{q="我该把这些铭牌交给谁？",a="把铭牌交给卫兵托马斯。他在闪金镇与东谷伐木场之间道路东侧的桥梁处守望。",al={"谁在寻找铭牌","交到哪里","铭牌交付"}},{q="这些铭牌为何对卫兵托马斯如此重要？",a="卫兵托马斯派这两名卫兵出去巡逻，并担心他们已遭不测。他们的铭牌证实了两人的死讯，让他得以记录他们的牺牲，并向暴风城警告日益严重的鱼人威胁。",al={"托马斯为何要这些铭牌","卫兵托马斯的反应"}}},fp="29,178,19.339.0,17.358.0,39.180.1,34.161.0,39.135.0,51.197.1"}
P.entries["item:rot-blossom"] = {n="腐败之花",s="腐败之花生长在暮色森林遭到亵渎的坟墓间，以枯败的土壤和亡灵残骸为养分。它们邪秽的炼金特性使其颇受追捧。",h="腐败之花生长在暮色森林遭到亵渎的坟墓间，以枯败的土壤和亡灵残骸为养分。它们邪秽的炼金特性使其颇受追捧。",kw={"阿尔泰娅·埃伯洛克","夜色镇","暮色森林","腐败之花","骷髅魔","骷髅恐魔","静谧花园墓场","僵尸酒"},ang={["faction:Alliance"]="在受诅咒的土壤中采集这些阴森的花朵，也能帮助守夜人将饥饿的骷髅挡在夜色镇边界之外。",["profession:Herbalism"]="腐败之花是以死亡的腐朽和墓地土壤为养分的污秽植物，与那些受阳光雨露滋养的草药迥然不同。它们为研究受腐化的植物提供了阴森的样本。"},sec={{t="墓穴之花",b="在暮色森林，腐败之花生长在静谧花园墓场等墓地遭到亵渎的土壤中。当地传言，这些花能在游荡于墓穴间的恐怖骸骨和骸骨魔开裂的颅骨内扎根。对夜色镇的居民而言，采集它们是一件阴森而危险的差事。翻动泥土，就意味着要面对不得安息的亡者。"},{t="骇人的原料",b="腐败之花是当地酿剂的一种原料。制作僵尸酒需要用到它们的黑暗精华，这种污浊的药剂与暮色森林为求生存所做的努力息息相关。受命采花的人在斩杀游荡于闹鬼墓地中的不安骷髅时，也常常为守夜人提供帮助。"}},faq={{q="哪里可以找到腐败之花？",a="腐败之花生长在暮色森林受到腐化的墓地中，尤其是静谧花园墓场。人们也知道，它们会从亡灵 骸骨魔 的残骸中萌发。",al={"腐败之花生长在哪里","腐败之花位置","寻找腐败之花"}},{q="腐败之花有什么用途？",a="当地的酿酒师和炼金师用腐败之花制作僵尸酒，这是一种效力强劲、污浊不堪的混合药剂。",al={"腐败之花用途","为何采集腐败之花","腐败之花为何有用"}},{q="这些花为何会在骷髅体内生长？",a="暮色森林挥之不去的黑暗魔法侵染着大地和不得安息的亡者。腐败之花以死亡带来的腐化与腐朽为养分，能在游荡骷髅的颅骨和胸腔内萌发。",al={"颅骨中的腐败之花","骷髅恐魔 花朵","骷髅 腐败之花"}},{q="采集腐败之花如何帮助夜色镇？",a="在静谧花园等地采集腐败之花，意味着要斩杀肆虐于这些地方的恐怖骸骨和 骷髅魔。这为阿尔泰娅·埃伯洛克和处境艰难的守夜人缓解了燃眉之急。",al={"阿尔泰娅·埃伯洛克 腐败之花","守夜人 腐败之花","帮助夜色镇"}}},fx={["93f3afdd"]={q="什么是腐败之花？",a="腐败之花是一种阴森的奇异植物，生长在暮色森林遭受污染的墓地里。它们不在肥沃的土壤中发芽，反而在腐朽之地茁壮生长，尤其喜欢在亡灵骷髅恐兽和骷髅恶魔的空洞头骨中扎根。这些花浸染着污秽能量，当地一些古怪居民会用腐败之花调制强效药剂，因此四处寻觅它们。",al={"什么是腐败之花","腐败之花物品"}}},fp="11,152,19.329.0,21.281.0,32.165.0,31.94.0,40.188.0,47.215.0"}
P.entries["item:rot-hide-ichor"] = {n="腐皮豺狼人的脓液",s="芬里斯岛上的腐皮豺狼人的脓液引起了皇家药剂师学会的注意。药剂师伦弗利尔在瑟伯切尔收集这种脓液，以查明是什么腐化了这些豺狼人，以及该如何对抗它们。",h="芬里斯岛上的腐皮豺狼人的脓液引起了皇家药剂师学会的注意。药剂师伦弗利尔在瑟伯切尔收集这种脓液，以查明是什么腐化了这些豺狼人，以及该如何对抗它们。",kw={"药剂师伦弗利尔","芬里斯岛","洛丹米尔湖","腐皮豺狼人","腐皮豺狼人的脓液","瑟伯切尔","银松森林"},ang={["race:Undead"]="身为被遗忘者，你能明白研究这种脓液的重要性：它能提供军事情报，帮助巩固银松森林的东翼，并增进皇家药剂师学会对瘟疫科学的掌握。"},sec={{t="血中的瘟疫",b="芬里斯岛上的腐皮豺狼人并非寻常野兽。它们的身体被一种非自然的疫病腐蚀、扭曲，剧毒的脓液在血管中流淌，维持着它们躯体的活动。皇家药剂师学会怀疑，这种液体或许能揭示这群豺狼人是如何遭到腐化的，以及是谁在废弃的城堡中指挥它们。"},{t="药剂研究",b="在瑟伯切尔，药剂师伦弗利尔收集一瓶瓶脓液用于研究。被遗忘者希望分离出驱动这些豺狼人的化学物质和魔法力量，找出它们的弱点，再派遣部队渡过洛丹米尔湖，发起全面进攻。"}},faq={{q="腐皮豺狼人的脓液来自哪里？",a="腐皮豺狼人的脓液来自遍布芬里斯岛的腐皮豺狼人，这座岛位于银松森林大陆部分以东的洛丹米尔湖中。",al={"腐皮豺狼人的脓液获取地点","如何找到腐皮豺狼人的脓液","豺狼人脓液位置"}},{q="药剂师伦弗利尔为什么需要这种脓液？",a="药剂师伦弗利尔研究这种液体，是为了查明是什么腐化了这些豺狼人，并在进攻岛屿之前，找出被遗忘者可以利用的肉体或炼金术方面的弱点。",al={"伦弗利尔为何需要脓液","伦弗利尔任务缘由","腐皮豺狼人的脓液用途"}},{q="腐皮豺狼人属于天灾军团吗？",a="腐皮豺狼人是被瘟疫扭曲的亡灵。被遗忘者正在调查，究竟是谁或什么力量创造了它们，并在芬里斯岛上指挥它们。",al={"腐皮是否属于天灾军团","谁控制腐皮","腐皮豺狼人是什么"}},{q="所有豺狼人都有这种脓液吗？",a="不是。这种脓液来自腐皮族群，它们的血肉受到了邪恶死灵疫病的腐化。",al={"所有豺狼人都掉落脓液吗","普通豺狼人的血液"}}},fp="14,168,21.303.0,19.267.0,36.117.0,46.166.0,32.142.0,30.109.0"}
P.entries["item:rough-quartz"] = {n="粗石英",s="在杜隆塔尔，粗石英来自大地之魂。萨满祭司将这块石头带给一位长者，由长者将它嵌入第一根大地图腾。",h="在杜隆塔尔，粗石英来自大地之魂。萨满祭司将这块石头带给一位长者，由长者将它嵌入第一根大地图腾。",kw={"大地的召唤","坎纳甘·地鸣","大地图腾","大地之魂","粗石英","试炼谷"},ang={["class:Shaman"]="对身为萨满祭司的你而言，粗石英标志着你首次与大地元素沟通。它为你的法术提供根基，也标志着你踏上了作为诸灵媒介的道路。"},sec={{t="大地图腾之心",b="粗石英是大地之魂赠予在杜隆塔尔或莫高雷与诸灵沟通的萨满祭司的礼物。在外行人眼中，它就像一块普通的沙漠卵石。这块石头象征着坚韧、耐心和坚定不移的力量。在试炼谷，坎纳甘·地鸣将它嵌入雕刻好的木头，制成大地图腾。这块石英成为灵性的焦点，将年轻的萨满祭司与艾泽拉斯充满生机的土地连接起来。"}},faq={{q="粗石英有什么用途？",a="萨满长者将粗石英嵌入初学者的第一根大地图腾，作为图腾的灵性核心。这块石头也表明，初学者已经与大地元素之灵沟通过。",al={"粗石英有什么作用","粗石英用途","为什么需要粗石英"}},{q="谁会给你粗石英？",a="在杜隆塔尔或莫高雷的大地的召唤仪式中，你与大地之魂沟通后，它便会赐予你粗石英。",al={"哪里获得粗石英","谁掉落粗石英"}},{q="在杜隆塔尔，我该把这块石头交给谁？",a="将粗石英带给试炼谷的萨满祭司训练师坎纳甘·地鸣。坎纳甘会用它制成你的大地图腾。",al={"粗石英交到哪里","交付粗石英","谁收粗石英"}},{q="这块石英还有其他用途吗？",a="没有。粗石英只是用于制作大地图腾的神圣仪式物品，在日常贸易中没有用途。",al={"粗石英能卖吗","粗石英能用于制作吗"}}},fp="12,143,24.439.0,40.172.0,31.143.0,40.127.0,38.102.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="海格纳的弹药",s="海格纳的弹药被遗弃在灰色洞穴附近的雪地里。信使还没来得及把这箱弹药送到丹莫罗的枪械师海格纳·重枪手中，就被饥饿的雪怪吓跑了。",h="海格纳的弹药被遗弃在灰色洞穴附近的雪地里。信使还没来得及把这箱弹药送到丹莫罗的枪械师海格纳·重枪手中，就被饥饿的雪怪吓跑了。",kw={"弹药","箱子","丹莫罗","灰色洞穴","海格纳","洛斯罗","重枪","雪怪"},ang={["class:Hunter"]="身为丹莫罗的猎人，要让海格纳的火药保持干燥，弹丸储备充足。矮人的火器需要源源不断的弹药供应。",["profession:Engineering"]="身为工程师，你需要用弹丸和火药来测试制成的火器与实验性武器。"},sec={{t="搁浅的货物",b="海格纳·重枪在从寒脊山小径通往安威玛尔的山路旁经营着一家武器店。铁炉堡的火枪手、巡山人和矮人迫击炮小队都在白雪覆盖的高地上操练，因此他的存货消耗得像火药燃烧一样快。\n\n洛斯洛从卡拉诺斯寄出了这批弹丸，但货物始终没能送上货架。运货的信使在离灰色洞穴太近的地方扎了营。雪怪袭来时，信使惊慌逃走，把沉重的箱子留在了它们的猎场里。"}},faq={{q="海格纳·重枪是谁？",a="海格纳·重枪是一名矮人枪械师，在通往安威玛尔的道路旁开着一家店。他为在丹莫罗峭壁间练习的当地射手、猎人和军中炮手提供补给。",al={"重枪","海格纳是谁","枪械商人"}},{q="弹药箱是怎么丢失的？",a="一名运送弹药箱的信使在灰色洞穴附近扎了营。洞里的雪怪发动袭击时，受惊的信使逃走了，把沉重的箱子留在了雪地里。",al={"弹药为何丢失","弹药出了什么事","信使弹药"}},{q="灰色洞穴在哪里？",a="灰色洞穴位于卡拉诺斯西南方的群山中，由多处洞窟相连而成。雪怪在这里筑巢，威胁着周围山坡上独自赶路的旅人。",al={"灰色洞穴位置","雪怪洞穴在哪"}}},fx={["4221fe47"]={q="什么是海格纳的弹药？",a="这是一箱新弹药，专为通往安威玛尔的路旁那家海格纳·重枪的店铺装运。当地的矮人火枪手和迫击炮小队经常在附近练习，海格纳依靠这样稳定的大批供货来补足库存，让顾客有弹药可用。",al={"海格纳的弹药是什么","海格纳的弹药箱","这些军火是什么"}},["008970c2"]={q="海格纳的弹药来自哪里？",a="这箱弹药由卡拉诺斯的罗斯洛·鲁治供应并发出。不幸的是，负责将它向西南方的安威玛尔运送的信使，在灰色洞穴附近遭到凶猛的雪怪伏击，逃跑时将整批货物遗弃在雪地里。",al={"海格纳的弹药由谁制造","海格纳的弹药来自哪里","谁送出了弹药"}},["6d6b5eaa"]={q="为什么海格纳·重枪需要这批弹药？",a="海格纳的库存眼看就要彻底耗尽。附近的巡山人、火枪手和迫击炮小队在打靶练习时消耗火药和弹丸的速度极快，新货一到，就会有大批迫不及待的买家等着购买。",al={"为什么需要海格纳的弹药","为什么想要海格纳的弹药","谁需要海格纳的弹药"}}},fp="17,177,19.477.0,25.175.0,32.152.0,26.171.0"}
P.entries["item:rune-inscribed-parchment"] = {n="符文羊皮纸",s="在试炼谷，高内克将史克里克的信交给有志成为萨满祭司的兽人。信中召唤他们成为精神领袖，传达元素之灵的意志。",h="在试炼谷，高内克将史克里克的信交给有志成为萨满祭司的兽人。信中召唤他们成为精神领袖，传达元素之灵的意志。",kw={"杜隆塔尔","高内克","羊皮纸","符文羊皮纸","萨满祭司","史克里克","试炼谷"},ang={["class:Shaman"]="作为萨满祭司，这封短信标志着你踏上元素之路的第一步。在史克里克的教导下，你学习敬奉先祖，掌控元素。",["race:Orc"]="作为兽人，你在杜隆塔尔传承先祖的智慧。重新寻回萨满祭司的传统，是新部落的核心所在。"},sec={{t="灵魂的召唤",b="兽人萨满祭司新手在试炼谷资深监工的指导下开始训练。当新兵为高内克完成最初的试炼时，高内克会交给他们一份写满符文的文书，由当地的萨满祭司导师史克里克寄来。这封信召唤他们与元素进行更深层的交流。在兽人之中，萨满祭司是生者与先祖之间的沟通者。这份文书标志着他们从倚重蛮力，转向以严谨的修行敬奉先祖。"}},faq={{q="符文羊皮纸是什么？",a="高内克在试炼谷将这封手写的信交给兽人萨满祭司新手。信中指引他们前去向史克里克报到，接受正式的指导。",al={"符文羊皮纸","这件物品是什么","萨满祭司羊皮纸"}},{q="羊皮纸是谁写的？",a="试炼谷的萨满祭司训练师史克里克写下了这份羊皮纸，指引年轻的新兵学习元素与先祖之灵的道路。",al={"谁寄来了羊皮纸","羊皮纸作者"}},{q="为什么兽人认为萨满祭司是被选中之人？",a="兽人萨满祭司作为精神领袖指引族人，聆听元素之灵的声音，并传达先祖的意志。史克里克提醒学徒，他们的职责包括治疗盟友，以及驾驭元素之怒打击敌人。",al={"为什么成为萨满祭司","兽人萨满祭司的职责"}}},fp="24,154,24.414.0,37.140.0,24.153.0,49.220.0"}
P.entries["item:rune-inscribed-pendant"] = {n="刻有符文的坠饰",s="在银松森林，一枚刻有符文的坠饰随一批运往安伯米尔的货物抵达了瑟伯切尔。肯瑞托用这类坠饰引导奥术能量。",h="在银松森林，一枚刻有符文的坠饰随一批运往安伯米尔的货物抵达了瑟伯切尔。肯瑞托用这类坠饰引导奥术能量。",kw={"奥利斯特","安伯米尔","达拉尔·道恩维沃尔","达拉然","肯瑞托","坠饰","刻有符文的坠饰","瑟伯切尔"},ang={["class:Mage"]="身为法师，你能从这些符文中认出肯瑞托的工艺。在引导强大法术时，这些符文能稳定狂暴的魔力流。",["race:Undead"]="身为守卫银松森林的被遗忘者一员，你知道，像这件坠饰这样截获的达拉然聚焦物，能提供线索，揭示安伯米尔城墙后正在集结的人类抵抗力量。"},sec={{t="肯瑞托遗物",b="在一批运往安伯米尔达拉然飞地的绘图物资中，人们发现了一枚刻有符文的坠饰。坠饰上精细的奥术铭文揭示了它的用途：集中并增强法师的法术。更多用于引导能量的坠饰正运抵这一地区，瑟伯切尔的被遗忘者不禁猜测肯瑞托正在筹备什么。"},{t="安伯米尔计划的线索",b="在瑟伯切尔，暗影牧师奥利斯特察觉到达拉然法师加固的据点潜藏着危险。他将坠饰送交达拉尔·道恩维沃尔，以便进一步研究。道恩维沃尔认出它与法师们的行动有关。肯瑞托正在安伯米尔境内收集奥术聚焦物，为强大的防御或进攻法术做准备。"}},faq={{q="刻有符文的坠饰有什么用途？",a="肯瑞托法师用这种坠饰引导并控制强大的魔力流。它能让复杂的法术凝聚成形。",al={"坠饰有什么作用","坠饰用途","符文坠饰用途"}},{q="这件坠饰来自哪里？",a="这件坠饰随一批运往银松森林安伯米尔的货物而来，肯瑞托残部已在那里筑起防御工事。",al={"哪里能找到坠饰","坠饰来源","在哪里发现的"}},{q="谁在瑟伯切尔分析这件坠饰？",a="暗影牧师奥利斯特将坠饰与截获的地图一同做了简短检查。他将坠饰送交瑟伯切尔的达拉尔·道恩维沃尔，后者认出了肯瑞托的手笔。",al={"谁研究坠饰","谁想要坠饰","达拉尔坠饰"}},{q="被遗忘者为什么担忧这件坠饰？",a="大批运来的引导坠饰表明，安伯米尔的肯瑞托正在筹备一场大规模的魔法行动。被遗忘者担心这可能威胁他们对银松森林的控制。",al={"被遗忘者为何在意","安伯米尔的威胁","坠饰为何危险"}}},fx={bf28d080={q="刻有符文的坠饰是什么？",a="这是一件由达拉然强大的法师制作并使用的奥术神器。肯瑞托经常借助此类坠饰聚集并引导巨大的魔法能量。它们并非普通饰物，而是强大奥术力量的导体。",al={"符文坠饰是什么","符文坠饰的身份","这是什么达拉然坠饰"}}},fp="22,166,15.327.0,27.338.1,44.111.0,33.125.0,42.165.0,40.185.0"}
P.entries["item:rune-inscribed-tablet"] = {n="符文石板",s="在试炼谷，高内克将一块刻有讯息的石板交给年轻的暗矛巨魔萨满祭司。它指引有潜力的通灵者前往史克里克那里，开始正式与元素沟通。",h="在试炼谷，高内克将一块刻有讯息的石板交给年轻的暗矛巨魔萨满祭司。它指引有潜力的通灵者前往史克里克那里，开始正式与元素沟通。",kw={"暗矛","杜隆塔尔","高内克","符文石板","萨满祭司","史克里克","训练师","试炼谷"},ang={["class:Shaman"]="作为萨满祭司，这块石板标志着你正式迈出了掌握大地、火焰、流水与空气的第一步。它提醒你，你的力量源自先祖之灵。",["race:Troll"]="作为暗矛巨魔，你响应一位兽人训练师的召唤，这象征着你的族人与新结识的部落盟友之间日益深厚的纽带，以及共同的灵性道路。"},sec={{t="通往诸灵的召唤",b="高内克将这块刻有符文的石板交给在试炼谷证明了自己实力的新兵。这是巨魔萨满祭司Ishi-yo送来的，指引他们去见萨满祭司训练师史克里克。对暗矛巨魔而言，这块石板开启了与兽人同行的道路，将他们古老的灵性传统与大酋长萨尔重振的萨满传承相结合。"}},faq={{q="符文石板有什么用途？",a="高内克将石板交给试炼谷中年轻的巨魔萨满祭司。它指引他们前往史克里克那里，开始接受正式的灵性教导。",al={"石板用途","石板有什么用","符文石板用途"}},{q="是谁送来这块石板的？",a="这块石板是巨魔萨满祭司伊希尤送来的。它指引新兵去见史克里克，这位兽人萨满祭司训练师就在试炼谷的大兽穴外，已经知道他们要来。",al={"谁写了石板","石板送信人","谁刻了石板"}},{q="谁会收到这块石板？",a="高内克将这块石板交给初来乍到的暗矛巨魔萨满祭司，作为他们在杜隆塔尔收到的首次职业召唤。",al={"谁会收到符文石板","哪个职业会收到石板"}}},fp="21,159,24.315.0,43.130.0,21.178.0,25.105.0"}
P.entries["item:rune-of-nesting"] = {n="筑巢符文",s="在班奈希尔兽穴，筑巢符文是四件神圣遗物之一。它能帮助阿斯瑞达斯·熊皮准备仪式，让猛禽德鲁伊从翡翠梦境中安全苏醒。",h="在班奈希尔兽穴，筑巢符文是四件神圣遗物之一。它能帮助阿斯瑞达斯·熊皮准备仪式，让猛禽德鲁伊从翡翠梦境中安全苏醒。",kw={"阿斯瑞达斯·熊皮","班奈希尔兽穴","巢穴之箱","猛禽德鲁伊","翡翠梦境","唤醒圣物","筑巢符文"},ang={["class:Druid"]="对德鲁伊而言，筑巢符文让人想到塞纳里奥议会的神圣仪式，以及圣所遭到入侵时，沉睡的同胞所面临的危险。",["race:NightElf"]="对暗夜精灵而言，唤醒遗物的遗失和兽穴遭到亵渎，反映出泰达希尔的野生生物与熊怪正受到日益严重的腐化。"},sec={{t="唤醒仪式的神圣媒介",b="筑巢符文存放在筑巢之箱中，位于班奈希尔兽穴蜿蜒曲折的洞室深处。暗夜精灵德鲁伊在地下兽穴中沉睡，通过翡翠梦境与自然交流。为了安全归来，猛禽德鲁伊需要由神圣遗物引导的精密唤醒仪式。符文是四件遗物之一：鸦爪神符、黑色羽毛、天蓝宝石和筑巢符文。这些遗物共同发挥作用，帮助沉睡的德鲁伊重返清醒的世界。"},{t="班奈希尔的危机",b="遭到腐化的瘤背熊怪占据了班奈希尔兽穴，使沉睡其中的守护者陷入险境。没有这些遗物，德鲁伊可能会被困在翡翠梦境中，而入侵者正在亵渎他们的圣所。找回筑巢符文和其余几件遗物，就能让多兰纳尔的阿斯瑞达斯·熊皮准备仪式，安全地唤醒他们。"}},faq={{q="筑巢符文有什么用途？",a="阿斯瑞达斯·熊皮需要筑巢符文来举行仪式，让猛禽德鲁伊从翡翠梦境的沉睡中安全苏醒。它是仪式所需的四件唤醒圣物之一。",al={"筑巢符文有什么作用","筑巢符文用途"}},{q="在哪里能找到筑巢符文？",a="筑巢符文存放在巢穴之箱中，位于泰达希尔多兰纳尔以西的班奈希尔兽穴地下通道内。",al={"筑巢符文在哪里","巢穴之箱位置"}},{q="沉睡的德鲁伊为什么不能自行醒来？",a="德鲁伊在翡翠梦境中沉睡时，会进入一种微妙的恍惚状态。没有神圣遗物和唤醒仪式，他们可能无法归来，心智将四处飘荡，肉身则暴露在危险之中。",al={"德鲁伊为什么需要唤醒仪式","德鲁伊为什么无法醒来"}},{q="除了筑巢符文，还需要哪些遗物？",a="仪式需要四件唤醒圣物：筑巢符文、鸦爪神符、黑色羽毛和天蓝宝石。",al={"其他唤醒圣物","唤醒圣物物品"}}},fp="15,179,28.497.0,19.354.0,37.212.0,35.133.0,58.204.0,59.139.0"}
P.entries["item:runes-of-summoning"] = {n="召唤符文",s="在幽暗城的魔法区，凯伦丁·哈加尔向术士提供召唤虚空行者的符文。仪式将一个未受束缚的虚空行者引入法阵，让初出茅庐的术士将其降服。",h="在幽暗城的魔法区，凯伦丁·哈加尔向术士提供召唤虚空行者的符文。仪式将一个未受束缚的虚空行者引入法阵，让初出茅庐的术士将其降服。",kw={"凯伦丁·哈加尔","魔法区","召唤符文","誓缚","幽暗城","虚空行者","术士"},ang={["class:Warlock"]="身为术士，你用符文证明自己对Void的支配力，将混乱的暗影化为长久效忠的仆从。",["race:Undead"]="身为Undead，你追随被遗忘者施法者深入幽暗城，他们不顾古老的禁忌，在洛丹伦废墟之下束缚虚空生物。"},sec={{t="魔法区的降服仪式",b="凯伦丁·哈加尔将召唤符文交给准备好驾驭虚空行者的术士。在幽暗城的魔法区，被遗忘者施法者研究如何操纵虚空。术士在哈加尔所在位置下方已激活的召唤法阵中施放符文。仪式撕开虚空，召出一个生物，等待术士将其制服，束缚为仆从。"}},faq={{q="召唤符文有什么用途？",a="术士在幽暗城魔法区的召唤法阵中使用符文，将一个未受束缚的虚空行者从虚空引入物质世界。随后，术士便可击败它，使其服从自己的意志。",al={"召唤符文用途","召唤符文有什么用","召唤符文用法"}},{q="谁提供召唤符文？",a="凯伦丁·哈加尔是幽暗城魔法区的被遗忘者术士训练师，他会在束缚虚空行者训练的最后阶段提供符文。",al={"谁提供召唤符文","召唤符文训练师","凯伦丁·哈加尔符文"}},{q="必须在哪里激活符文？",a="将符文带到魔法区中凯伦丁·哈加尔平台正下方的紫色召唤法阵。",al={"召唤符文使用地点","召唤符文位置","幽暗城召唤法阵"}},{q="召出这个生物后会发生什么？",a="虚空行者一被召出就会发动攻击。术士必须用法术和武器将其制服。这个生物被击败后，便会受契约约束，成为仆从，凯伦丁·哈加尔也会传授永久召唤它的法术。",al={"使用符文后会发生什么","制服虚空行者","召唤虚空行者之后"}}},fp="18,188,32.366.0,41.187.0,36.155.0,34.110.0,42.200.0"}
P.entries["item:sack-of-murloc-heads"] = {n="一袋鱼人的头颅",s="在希尔斯布莱德的海滩上，人们收集了一袋鱼人的头颅，作为出兵清剿当地海岸祸害的骇人凭证。法尔林·奥里涅尔中尉将袋子交给过路的冒险者，请他们送到南海镇的治安官雷德帕斯手中。",h="在希尔斯布莱德的海滩上，人们收集了一袋鱼人的头颅，作为出兵清剿当地海岸祸害的骇人凭证。法尔林·奥里涅尔中尉将袋子交给过路的冒险者，请他们送到南海镇的治安官雷德帕斯手中。",kw={"悬赏","法尔林·奥里涅尔","头颅","希尔斯布莱德","治安官雷德帕斯","鱼人","南海镇"},ang={["faction:Alliance"]="作为联盟的一员，你看到了南海镇捉襟见肘的后勤，以及守军为维系这处联盟北方据点而承担的繁琐日常重担。"},sec={{t="官僚事务与海岸祸害",b="南海镇不断遭受辛迪加匪徒、被遗忘者散兵和沿海野生鱼人的袭击。当地军官必须向镇上的领导者证明，沿海的威胁正在被清除，以争取经费和支持。法尔林·奥里涅尔中尉收集砍下的头颅作为证据，却对这批货物心生厌恶。他受不了这血淋淋的场面，于是把袋子交给旅人，而没有亲自将这些骇人的证据送给治安官雷德帕斯。"}},faq={{q="一袋鱼人的头颅是什么？",a="一袋鱼人的头颅是一个粗麻布袋，里面装着从希尔斯布莱德西部海滩收集来的鱼人断头。它为南海镇的驻军指挥官提供了实物证据，证明平定海岸的行动正在进行。",al={"一袋头颅","鱼人头颅袋","这件物品是什么"}},{q="法尔林中尉为什么不亲自送去？",a="法尔林·奥里涅尔中尉觉得，提着一袋恶臭腐烂的鱼人头颅实在令人作呕。他把这趟横穿南海镇、令人不快的送货差事交给了一位愿意帮忙的冒险者。",al={"法尔林为何让人代送","法尔林的借口","懒惰的法尔林"}},{q="谁接收这袋头颅？",a="治安官雷德帕斯接收这袋头颅。他指挥南海镇的防御，评估镇上的安全状况，并要求提供防御行动的证据。",al={"头颅交给谁","送到哪里","治安官雷德帕斯交任务"}},{q="南海镇为什么需要鱼人头颅作为证据？",a="南海镇需要鱼人头颅作为证据，因为鱼人不断袭击海岸，威胁港口。军官必须核实巡逻队是否维持了周边的安全，而实实在在的战利品有助于防止士兵在站岗时无所事事，却冒领功劳。",al={"为何收集鱼人头颅","击杀凭证"}}},fx={["3f14ed35"]={q="一袋鱼人的头颅来自哪里？是谁制作的？",a="这袋东西装着你在希尔斯布莱德丘陵南部海岸猎杀的鱼人的头颅。法尔林·奥里涅尔中尉将它们装在一起，准备呈交给他的长官，不过他很快就把这包令人作呕的东西交还给你，让你代他送去。",al={"谁制作了一袋鱼人的头颅","这袋头颅来自哪里","谁交来一袋鱼人的头颅"}}},fp="20,217,29.433.0,33.166.0,47.170.0,22.139.0,50.248.0"}
P.entries["item:sack-of-supplies"] = {n="装满货物的袋子",s="一支商队运往雷兹拉克的货物，散落在烈风峡谷的鹰身人巢穴之间。尘风鹰身人在货物途经杜隆塔尔时将其劫走。",h="一支商队运往雷兹拉克的货物，散落在烈风峡谷的鹰身人巢穴之间。尘风鹰身人在货物途经杜隆塔尔时将其劫走。",kw={"杜隆塔尔","尘风鹰身人","加兹鲁维","烈风峡谷","雷兹拉克","装满货物的袋子"},ang={["faction:Horde"]="从当地的掠食者手中夺回物资，有助于让奥格瑞玛周边的边疆建设继续推进，避免代价高昂的延误。"},sec={{t="遭劫的商队",b="雷兹拉克在奥格瑞玛城外的工作需要稳定的物资供应。这位地精工程师由加兹鲁维从棘齿城雇来，为部落修建工事。一支商队载着约定交付的货物，途经奥格瑞玛以南的峡谷道路附近时，遭到了尘风鹰身人的伏击。它们将货物拖进烈风峡谷的巢穴，把一袋袋物资散落在筑巢地旁的泥土和碎石之间。"}},faq={{q="这些物资袋里装着什么？",a="袋中装着供加兹鲁维的工程使用的建筑材料和贸易货物，用于支持奥格瑞玛附近的兽人建设项目。没有这些物资，雷兹拉克就无法完成工作。",al={"物资袋内容","袋子里有什么","雷兹拉克的物资"}},{q="是谁偷走了物资？",a="尘风鹰身人偷走了物资。它们是一个野蛮的鸟形种族，盘踞在烈风峡谷高处的岩隙和沟壑中。",al={"谁拿走了物资","谁偷走了袋子"}},{q="雷兹拉克是谁？",a="雷兹拉克是一名地精工程师，由加兹鲁维从棘齿城派来，帮助部落修建和维护杜隆塔尔的线路基础设施。",al={"雷兹拉克是谁","雷兹拉克的故事"}}},fp="16,156,19.381.0,34.197.0,23.118.0,14.122.0"}
P.entries["item:salty-scorpid-venom"] = {n="含盐的蝎毒",s="含盐的蝎毒是一种腐蚀性液体，采自徘徊在千针石林闪光平原上的蝎子。它富含来自荒漠地表的天然盐分，深受那些试图研制易爆、超高温燃料的侏儒火箭赛车手珍视。",h="含盐的蝎毒是一种腐蚀性液体，采自徘徊在千针石林闪光平原上的蝎子。它富含来自荒漠地表的天然盐分，深受那些试图研制易爆、超高温燃料的侏儒火箭赛车手珍视。",kw={"菲兹尔·铜栓","沙漠赛道","含盐的蝎毒","掠夺蝎","恐蝎","蝎毒","闪光平原","千针石林"},ang={["profession:Engineering"]="在闪光平原钻研发明的人们，总是在常规的石油和煤炭之外寻找出路，试验将生物毒素用作易爆的助燃剂。",["race:Gnome"]="也只有侏儒的奇思妙想，才会考虑将致命的沙漠毒液与负催化剂混合，再注入火箭引擎，只为让单圈用时缩短几秒。"},sec={{t="易爆的助燃剂",b="在闪光平原干旱大地上爬行的蝎子，已经适应了矿物质极其丰富的环境。经过世代积累，毒蝎和恐蝎等野兽的毒液吸收了大量当地的盐分。菲兹尔·铜栓这样的侏儒工匠看重这种腐蚀性化合物，是因为它有望成为高燃烧强度引擎燃料的添加剂，而非用来调制解毒剂或普通毒药。"},{t="赛道角逐的燃料",b="在沙漠赛道，侏儒与地精之间的工程技术较量，驱使发明家们在火箭赛车中试用越来越危险的材料。菲兹尔·铜栓相信，将含盐的毒液熬煮浓缩，用特殊催化剂处理，再混入推进剂箱，就能产生足够的炽热高温，在盐滩上超越地精赛车手。"}},faq={{q="哪些生物会产生含盐的蝎毒？",a="这种毒液采自游荡在千针石林盐滩上的危险蝎子，尤其是蝎子掠夺者和恐蝎。",al={"含盐的蝎毒掉落来源","蝎毒获取地点","蝎毒来源"}},{q="这种毒液为什么含有这么多盐分？",a="这些蝎子完全生活在闪光平原覆盖着矿物硬壳的地面上。它们的身体会吸收干涸湖床中富集的盐分，使毒腺中的毒液带有明显的盐分。",al={"为何含盐","盐滩毒液成因","蝎子盐分背景"}},{q="谁想要这种毒液，又是为了什么？",a="驻扎在沙漠赛道的侏儒工程师菲兹尔·铜栓，正在寻找这种毒液，以调配一种实验性混合燃料，让燃烧产生的高温足以推动他的火箭赛车赢得胜利。",al={"蝎毒需求者","菲兹尔·铜栓需要毒液的原因","菲兹尔·铜栓任务物品"}}},fx={["9840b612"]={q="含盐的蝎毒是什么？",a="这是一种富含矿物质的强效液体，采自出没于闪光平原的蝎子。干旱酷烈的盐碱盆地使当地的蝎子恐魔和掠夺者体内的毒液含盐量异常高。这种毒液作为天然毒素固然致命，但其活跃的化学特性让它对侏儒技师而言更像一种有趣的原始试剂，而非单纯的毒药。",al={"含盐的蝎毒是什么","含盐的蝎毒","平原上的蝎毒"}}},fp="19,215,27.321.0,27.317.0,43.99.0,26.173.0,29.181.0"}
P.entries["item:samophlange-item"] = {n="主动式负载平衡器",s="在贫瘠之地，主动式负载平衡器藏在一座自动控制台内。地精技师也说不清这个奇怪的部件有什么用途。",h="在贫瘠之地，主动式负载平衡器藏在一座自动控制台内。地精技师也说不清这个奇怪的部件有什么用途。",kw={"贫瘠之地","控制台","棘齿城","调查设备","斯布特瓦夫","工匠协会","安德麦"},ang={["profession:Engineering"]="身为工程师，你或许看得出Samophlange的设计过于复杂。它精巧的外表下藏着一个极其脆弱的机械装置，只要放到地上就会损坏。"},sec={{t="令人费解的装置",b="主动式负载平衡器藏在贫瘠之地的一座控制台内，周围布满迷宫般的线路和中空管道。必须仔细搜寻，才能将这个部件从外壳中取出。它看起来像是钟表和蒸汽机械中的关键部件，但地精工匠却弄不明白它的用途。他们打算将它送往安德麦的技工协会，不过这个脆弱的部件可能经不起粗手粗脚的搬运。"},{t="好奇与灾难",b="棘齿城的工程师斯布特瓦夫打算将主动式负载平衡器送交技工协会的资深专家研究。地精的好奇心却妨碍了这个计划。斯布特瓦夫把这个精密装置放下来，想查看它的内部构造时，它往往就碎成了一堆废料。"}},faq={{q="什么什么平衡器是什么？",a="什么什么平衡器是从贫瘠之地的一座控制台中取出的奇怪机械部件。它的用途不明，周围的控制台里挤满了管道和电线，看起来都没什么用处。",al={"主动式负载平衡器有什么用","主动式负载平衡器用途","这是什么物品"}},{q="谁想要什么什么平衡器？",a="棘齿城的工程师斯布特瓦夫希望有人把什么什么平衡器带给他，好让他研究一番，再将它送往技工协会。",al={"谁需要主动式负载平衡器","主动式负载平衡器交给谁"}},{q="斯布特瓦夫会拿它做什么？",a="斯布特瓦夫打算将什么什么平衡器送往安德麦，交给技工协会研究。他先把它放下来检查，结果这个脆弱的机械装置就坏了。",al={"斯布特瓦夫 主动式负载平衡器","主动式负载平衡器会怎么样"}},{q="什么什么平衡器从哪里来？",a="什么什么平衡器装在贫瘠之地北部的一座操作台内，藏在层层令人摸不着头脑、看似毫无用处的机械后面。",al={"主动式负载平衡器位置","在哪里找到"}}},fp="18,140,22.353.0,25.264.1,22.204.0,26.124.0,34.156.1,36.142.0"}
P.entries["item:samophlange-manual"] = {n="主动式负载平衡器说明书",s="在奥格瑞玛，雷里·格里斯高布正在寻找主动式负载平衡器说明书散落的书页。这本手册记载了修理和操作荆棘谷地精的 主动式负载平衡器 的方法。",h="在奥格瑞玛，雷里·格里斯高布正在寻找主动式负载平衡器说明书散落的书页。这本手册记载了修理和操作荆棘谷地精的 主动式负载平衡器 的方法。",kw={"贫瘠之地","考博普拉格","石矿洞","工程学","说明书","雷里·格里斯高布","调查设备","斯布特瓦夫","荆棘谷地精"},ang={["faction:Horde"]="这本说明书让奥格瑞玛效力于部落的地精得以在荆棘谷地精眼皮底下，研究公司的钻探机械并将其改作他用。",["profession:Engineering"]="这本说明书揭示了荆棘谷地精的专有技术，也展现了地精工匠如何向同行保守商业秘密和实用图纸。"},sec={{t="奇械的秘密",b="考博普拉格严守着荆棘谷地精有关 主动式负载平衡器 的知识。这位野心勃勃的监工不让大多数工人接触说明书，只把零散的书页交给最忠心的下属。当这台装置脱离公司掌控后，若不从石矿洞的考博普拉格及其手下那里收齐残缺的说明书，就没有人能修好它。"},{t="对手的野心",b="雷里·格里斯高布离开荆棘谷地精后，在奥格瑞玛定居，想要弄清 主动式负载平衡器 的构造。考博普拉格从未器重过他，因此雷里只能依靠积极进取的旅人找回说明书的封面和散页。重新拼好的手册，让与部落共事的地精工匠有了难得的机会，一窥荆棘谷地精的工程技术。"}},faq={{q="主动式负载平衡器说明书是什么？",a="主动式负载平衡器说明书记载了如何操作和修理荆棘谷地精那台复杂而古怪的机械装置。",al={"主动式负载平衡器说明书是什么","主动式负载平衡器 书籍","主动式负载平衡器 指南"}},{q="说明书原本归谁所有？",a="考博普拉格是贫瘠之地东北部石矿洞的一名荆棘谷地精监工，说明书由他保管。他严守其中的秘密，只把单独的书页交给最信任的工人。",al={"说明书在谁手里","考博普拉格 说明书","谁写的说明书"}},{q="说明书为什么被撕成散页？",a="考博普拉格将说明书拆散，以免对手和不受信任的下属弄懂整台装置。他留下封面，将其中特定的五页分给了手下的矿工和操作员。",al={"为什么寻找说明书书页","散落的说明书书页","书页为什么缺失"}},{q="谁想阅读完整的说明书？",a="雷里·格里斯高布是奥格瑞玛的一名工程师，他想要重新拼好的说明书，以便弄懂并修好从贫瘠之地带回的损坏的主动式负载平衡器。",al={"谁需要说明书","雷里·格里斯高布","谁想要主动式负载平衡器说明书"}},{q="什么什么平衡器 有什么用途？",a="荆棘谷地精以外的人似乎都不知道 什么什么平衡器 有什么用途。公司曾在贫瘠之地淤泥沼泽西南方的一处小型研究站，用一台这样的装置进行试验，但就连研究它的工程师也没能弄明白多少。",al={"主动式负载平衡器 有什么作用","主动式负载平衡器 的用途","主动式负载平衡器 用途"}}},fp="18,165,26.354.0,18.351.0,31.117.0,32.197.0,34.191.0,39.147.0,31.252.0"}
P.entries["item:sample-ichor"] = {n="脓液样本",s="在银松森林，脓液样本中残留着死灵法术与术士魔法的痕迹。药剂师伦弗利尔从维系腐皮豺狼人生命的体液中提炼出了它。",h="在银松森林，脓液样本中残留着死灵法术与术士魔法的痕迹。药剂师伦弗利尔从维系腐皮豺狼人生命的体液中提炼出了它。",kw={"药剂师伦弗利尔","比索·埃斯沙德","魔法区","腐皮","腐皮起源","脓液样本","银松森林","幽暗城"},ang={["class:Mage"]="身为法师，你知道运用传统奥术分析来研究黑暗魔法的价值。比索·埃斯沙德使用专门的占卜法术来解读样本中的残留痕迹。",["class:Warlock"]="身为术士，你或许能认出药剂师伦弗利尔在脓液中检测到的术士法术，它们与死灵法术相互交织，暗示邪能手段曾被用于束缚这些亡灵野兽。"},sec={{t="揭开腐皮豺狼人的秘密",b="药剂师伦弗利尔将脓液样本送往幽暗城，以便进一步研究。他从腐皮豺狼人及其残存的遗骸中采集样本，然后将这些污秽的液体分解为基本成分。他的分析表明，这种脓液是通过交织着术士魔法的死灵仪式制成的。由于制作它的技艺超出了普通炼金术的范畴，伦弗利尔将样本送交比索·埃斯沙德进行占卜。"}},faq={{q="脓液样本是什么？",a="脓液样本是药剂师伦弗利尔从腐皮豺狼人的体液中制备的精炼提取物。他将其分解为基本成分，以了解这些行尸走肉般的野兽是如何被魔法创造出来的。",al={"脓液样本","这种脓液是什么","脓液样本是什么"}},{q="谁需要查看这份样本？",a="比索·埃斯沙德需要检查这份样本。他是一名驻守在幽暗城魔法区的亡灵法师，他精通占卜与魔法学识，能在那里揭示普通炼金术无法辨明的痕迹。",al={"脓液交给谁","脓液样本交付","比索·埃斯沙德脓液"}},{q="脓液中蕴含着什么魔法？",a="脓液中融合了术士魔法与死灵法术。比索·埃斯沙德指出，瓶中的液体交织着强大而古老的附魔，需要更深入的占卜才能彻底揭示其中的奥秘。",al={"脓液中有什么魔法","脓液魔法类型","腐皮魔法"}},{q="药剂师们为什么没有自行完成分析？",a="皇家药剂师学会擅长炼金术、毒素和肉体疫病，而复杂的奥术交织则需要专精于此的巫师。比索·埃斯沙德能够辨识魔法学派，解析药剂师凭借常规手段无法破解的深奥法术。",al={"药剂师为何送交比索","为何不放弃腐皮豺狼人的脓液"}}},fp="12,164,24.380.0,25.196.0,29.202.0,39.183.0,59.236.0"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="赞吉尔的药剂样品",s="一名信使带着赞吉尔的药剂样品，渡海前往塔伦米尔。这种药剂出自巫医赞吉尔之手，会使携带者变得虚弱。瑟尔格·希诺特或许能找到解药，并揭开毒药的作用原理。",h="一名信使带着赞吉尔的药剂样品，渡海前往塔伦米尔。这种药剂出自巫医赞吉尔之手，会使携带者变得虚弱。瑟尔格·希诺特或许能找到解药，并揭开毒药的作用原理。",kw={"改良药剂","希尔斯布莱德","毒药","潜行者","瑟尔格·希诺特","淤泥沼泽","塔伦米尔","赞吉尔"},ang={["class:Rogue"]="身为部落潜行者，你将这份危险的样品带给瑟尔格·希诺特，向他学习致命毒药的调制、处理和涂抹方法。",["faction:Horde"]="身为部落旅人，你带着这种药剂，乘坐飞艇、沿着道路穿越一片大陆，循着从卡利姆多通往洛丹伦的被遗忘者领地的路线前行。"},sec={{t="剧毒信物",b="一名密探潜入贫瘠之地淤泥沼泽附近的荆棘谷地精高塔后，带走了这种药剂。样品取自加里维克斯的锁箱中藏匿的物资，而赞吉尔的药剂已使这名密探身中剧毒。申苏尔派这名中毒的密探带着样品，横渡无尽之海。在希尔斯布莱德丘陵的塔伦米尔，药剂师瑟尔格·希诺特拥有分离毒素、查明其成分的罕见技艺。"},{t="制毒秘术",b="瑟尔格·希诺特研究这种改良药剂，帮助中毒的信使，并揭示如何在野外调制和使用强效毒药。部落潜行者寻求这些知识，以掌握本行更为阴暗的技艺。"}},faq={{q="这是什么药剂？",a="这是一种与巫医赞吉尔有关的炼金药剂，取自贫瘠之地淤泥沼泽附近的荆棘谷地精高塔。任何直接接触它的人，都会受到其强效毒素的影响，持续陷入虚弱。",al={"赞吉尔的药剂是什么","赞吉尔的药剂样品","赞吉尔的毒药样品"}},{q="为什么要把它带给瑟尔格·希诺特？",a="瑟尔格·希诺特是希尔斯布莱德丘陵塔伦米尔的一名药剂师。凭借他的学识，可以中和这种药剂的毒性，并在毒素造成永久伤害前配制出可靠的解药。",al={"瑟尔格·希诺特是谁","为什么带去塔伦米尔","赞吉尔药剂的解药"}},{q="赞吉尔是谁？",a="流亡者赞吉尔是一名丛林巨魔巫医，以制造令人陷入疯狂的药剂、毒药和诱变剂而闻名。他的剧毒配方早已流出故乡的丛林，传入荆棘谷地精等组织的雇佣兵和工业活动之中。",al={"赞吉尔是谁","流亡者赞吉尔","赞吉尔的故事"}},{q="该如何前往塔伦米尔送交样品？",a="从杜隆塔尔乘坐飞艇，前往提瑞斯法林地的幽暗城。然后沿大路向南穿过银松森林，再循路标向东进入希尔斯布莱德丘陵，抵达塔伦米尔。",al={"如何前往塔伦米尔","前往希尔斯布莱德","塔伦米尔路线"}}},fp="34,213,13.394.0,22.207.1,21.236.0,41.185.0,14.243.0,43.189.0"}
P.entries["item:sample-snapjaw-shell"] = {n="钳嘴龟壳样本",s="贫瘠之地的钳嘴龟壳样本中，留存着淡水绿洲的生命力。牛头人德鲁伊将它们送往无尽之海彼岸，帮助治愈银松森林。",h="贫瘠之地的钳嘴龟壳样本中，留存着淡水绿洲的生命力。牛头人德鲁伊将它们送往无尽之海彼岸，帮助治愈银松森林。",kw={"贫瘠之地","茉拉·符文图腾","绿洲","钳嘴龟壳样本","瑟伯切尔","银松森林","钳嘴龟","龟壳"},ang={["class:Druid"]="对塞纳里奥议会的德鲁伊而言，研究绿洲中的snapjaws，能让他们深入了解生命如何延续，以及如何治愈枯萎的土地。",["race:Tauren"]="身为牛头人，你可以将这块甲壳的旅程视为对Earth Mother的承诺。你的族人将援助与自然的疗愈带到大海彼岸，甚至送到亡灵盟友手中。"},sec={{t="绿洲的生命火花",b="钳嘴龟在贫瘠之地葱郁而奇异的绿洲中繁衍生息。它们坚固的甲壳即使离开身体许久，内部仍透着微光，涌动着能量。观察着这片土地迅速变化的牛头人德鲁伊，在这些甲壳中看到了卡利姆多野地里顽强的生命火花。它们的活力表明，即使环境严酷干旱，生命依然能够蓬勃生长。"},{t="治愈远方的土地",b="牛头人博学者派信使带着甲壳渡海，交给瑟伯切尔的茉拉·符文图腾。茉拉驻守在银松森林遭受枯萎侵蚀的广袤土地上，寻找帮助被遗忘者治愈北方土地的方法。她研究着钳嘴龟甲壳中留存的生命力，希望找到让衰败的森林复苏、让垂死的土壤重新孕育生机的办法。"}},faq={{q="这块钳嘴龟壳有什么特别之处？",a="钳嘴龟壳样本在采集后很久，内部仍透着微光，涌动着生命的脉动。它来自贫瘠之地奇异淡水绿洲周围的钳嘴龟，那里的自然能量异常充沛。",al={"甲壳为何特别","什么是钳嘴龟壳","发光的甲壳"}},{q="谁需要这份样本？",a="牛头人德鲁伊茉拉·符文图腾在银松森林的瑟伯切尔需要这块甲壳。她在那里帮助被遗忘者寻找治愈垂死土地的方法。",al={"谁需要甲壳","甲壳交到哪里","茉拉 符文图腾任务"}},{q="为什么要把贫瘠之地的甲壳千里迢迢送到银松森林？",a="银松森林的林地正日渐衰败，饱受枯萎侵蚀，而贫瘠之地的绿洲却突然涌现出蓬勃生机，并延续至今。德鲁伊希望从卡利姆多野兽的生命力中，找到治愈洛丹伦受损土壤的方法。",al={"为何送往银松森林","甲壳与银松森林的联系"}},{q="这块甲壳危险吗？是否受到了污染？",a="没有。甲壳散发的是纯粹的生命力，而非黑暗魔法。贫瘠之地神秘而突然的生长中留存着能量，德鲁伊认为，那是值得培育的自然韧性。",al={"甲壳是否邪恶","甲壳是否受到腐化"}}},fp="20,149,21.326.0,21.350.0,38.194.0,22.140.0,51.200.0,34.157.0"}
P.entries["item:samuel-s-remains"] = {n="塞缪尔的遗骸",s="在丧钟镇附近，塞缪尔的遗骸从一名 天灾军团 奴仆身上被收集起来，安葬在玛拉身旁。",h="在丧钟镇附近，塞缪尔的遗骸从一名 天灾军团 奴仆身上被收集起来，安葬在玛拉身旁。",kw={"丧钟镇","玛拉·菲普斯","玛拉 的坟墓","玛拉 的临终遗愿","新兵艾尔雷斯","塞缪尔·菲普斯","塞缪尔的遗骸"},ang={["race:Undead"]="身为亡灵，你很早就会明白，尊重命运悲惨的死者，正是自由的被遗忘者与 Scourge 那些毫无心智的奴仆之间的道德分界。"},sec={{t="悲剧的重逢",b="在亡灵瘟疫席卷洛丹伦之前，塞缪尔·菲普斯和妻子玛拉在提瑞斯法林地过着平静的生活。塞缪尔 染疫身亡，成了 天灾军团 毫无心智的仆从。玛拉逃过了亡灵的命运，却死在 塞缪尔 手中。临终前，她请求在他受诅咒的躯体安息后，将自己葬在他身旁。丧钟镇的新兵艾尔雷斯派刚刚苏醒的被遗忘者前往镇子东北方，找到四处游荡的 塞缪尔，取回他的遗骨，葬在当地墓地的前排。"}},faq={{q="塞缪尔·菲普斯生前是谁？",a="塞缪尔·菲普斯是一名人类，在第三次大战之前居住于提瑞斯法林地。天灾军团 瘟疫夺去了他的生命，随后又将他复活，变成巫妖王麾下的亡灵奴仆。在无意识的饥渴驱使下，他最终杀死了自己的妻子玛拉。",al={"塞缪尔·菲普斯","塞缪尔 是谁","塞缪尔 的过往"}},{q="在哪里能找到塞缪尔的遗骸？",a="塞缪尔的遗骸可以从他游荡的躯体上取回，他就在丧钟镇东北方道路沿线的残破营地中。终结他浑浑噩噩的存在，便能取回他的遗骨。",al={"寻找 塞缪尔 的遗骸","塞缪尔·菲普斯 在哪里","塞缪尔 的位置"}},{q="被遗忘者为什么要将他葬在妻子身旁？",a="玛拉的临终遗愿是安息在深爱的丈夫身旁，尽管他亲手杀死了她。新兵艾尔雷斯遵从她的请求，以此表明刚刚获得自由的被遗忘者仍怀有怜悯、对死者的敬意，以及使他们有别于 天灾军团 的人性。",al={"为什么埋葬 塞缪尔","玛拉 的坟墓","玛拉 的临终遗愿"}}},fp="16,88,16.522.0,21.221.0,33.177.0,45.258.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="阿库麦尔蓝宝石",s="黑暗深渊一带的纳迦正在采掘发光的阿库麦尔蓝宝石。水之灵依附在这些水晶上，耶努萨克雷正寻求帮助，要在它们的奥术力量遭到利用之前将其收缴。",h="黑暗深渊一带的纳迦正在采掘发光的阿库麦尔蓝宝石。水之灵依附在这些水晶上，耶努萨克雷正寻求帮助，要在它们的奥术力量遭到利用之前将其收缴。",kw={"阿库麦尔","黑暗深渊","水晶","耶努萨克雷","纳迦","蓝宝石","水之灵","佐拉姆海岸"},ang={["class:Mage"]="这些蓝宝石天然浸润着水，因此成为传导强大奥术材料力量的珍贵媒介。",["class:Shaman"]="身为大地之环的萨满祭司，你能感知到束缚在这些宝石中的水之灵，也能看出纳迦的采掘对元素构成了威胁。"},sec={{t="深渊宝石",b="在灰谷的佐拉姆海岸，黑暗深渊积水的洞穴入口处生长着阿库麦尔蓝宝石。水之灵依附在这些富含元素能量的晶体上，使其成为施展魔法的强大助力。斥候报告说，地下的纳迦正在从洞壁上采掘这些宝石，萨满祭司耶努萨克雷于是寻求冒险者的帮助，要将它们收缴。这些宝石若落在纳迦手中，就可能为毁灭性的奥术仪式提供能量。"}},faq={{q="阿库麦尔蓝宝石是什么？",a="阿库麦尔蓝宝石是遍布黑暗深渊洞壁的鲜亮水晶。水之灵依附其上，赋予这些宝石深厚的奥术与元素共鸣。",al={"这是什么水晶","阿库麦尔蓝宝石的传说","这些是什么宝石"}},{q="纳迦为什么要收集这些蓝宝石？",a="耶努萨克雷怀疑，纳迦打算利用水晶中的水与奥术能量，在水下神殿中施展危险的法术，但它们的确切意图尚不明朗。",al={"纳迦为什么想要蓝宝石","纳迦采掘水晶"}},{q="谁在寻找这些蓝宝石？",a="耶努萨克雷是大地之环的一名萨满祭司，驻守在灰谷佐拉姆海岸的佐拉姆加前哨站，他请旅人收集这些蓝宝石，避免它们落入纳迦手中。",al={"谁想要阿库麦尔蓝宝石","谁交付 阿库麦尔精华"}},{q="这些水晶与巨兽阿库麦尔有直接联系吗？",a="这些水晶得名于深渊中那头可怕的多头蛇阿库麦尔，却是自然生长在洞壁上的。它们的名字反映了它们与废墟中那股黑暗存在的邻近关系。",al={"与阿库麦尔的联系","来自阿库麦尔吗"}}},fx={["12f03799"]={q="阿库麦尔蓝宝石来自哪里？是谁制作的？",a="这些大型蓝宝石簇天然生长在黑暗深渊初始洞穴的岩壁上。它们并非由凡人雕琢，而是在洞窟环境能量浸润下形成的天然矿物。水之精魂会自然依附于这些水晶，赋予它们与生俱来的元素力量。",al={"阿库麦尔蓝宝石的来源","谁制作了阿库麦尔蓝宝石","阿库麦尔蓝宝石来自哪里"}}},fp="19,179,16.380.0,30.139.0,44.176.0,35.158.0,54.186.0"}
P.entries["item:sapphire-of-sky"] = {n="天蓝宝石",s="在班奈希尔兽穴，天蓝宝石帮助唤回沉睡的猛禽德鲁伊，让他们从翡翠梦境归来。它是暗夜精灵守护的四件神圣唤醒圣物之一。",h="在班奈希尔兽穴，天蓝宝石帮助唤回沉睡的猛禽德鲁伊，让他们从翡翠梦境归来。它是暗夜精灵守护的四件神圣唤醒圣物之一。",kw={"阿斯瑞达斯·熊皮","班奈希尔兽穴","天空之箱","猛禽德鲁伊","翡翠梦境","唤醒圣物","天蓝宝石"},ang={["class:Druid"]="身为德鲁伊，你能明白，当灵魂进入翡翠梦境时，神圣的锚点为何如此重要。没有它们，与自然交流也可能致命。",["race:NightElf"]="身为暗夜精灵，你知道，守护班奈希尔兽穴中的圣物，有助于在日益蔓延的腐化中维系泰达希尔脆弱的秩序。"},sec={{t="唤醒仪式",b="猛禽德鲁伊在泰达希尔根系深处的班奈希尔兽穴中冬眠，与荒野交流。从如此深沉的冥想中醒来，充满凶险。四件圣物守护着归途：黑色羽毛、鸦爪神符、筑巢符文和天蓝宝石。这颗宝石补全了唤回沉睡灵魂所需的和谐之力，让他们得以从翡翠梦境归来。没有它，他们就有可能永远被困在那里。"},{t="班奈希尔的威胁",b="腐化的瘤背熊怪占据了班奈希尔兽穴，圣物仍留在各自的存放处。天蓝宝石被妥善收存在天空之箱中，宝箱位于蜿蜒的地下通道里。熊怪在德鲁伊周围肆虐，而他们依然沉睡。多兰纳尔的阿斯瑞达斯·熊皮需要天蓝宝石和其余圣物，以便在沉睡者永远迷失之前唤醒他们。"}},faq={{q="天蓝宝石是什么？",a="天蓝宝石是一颗神圣的宝石，也是保存在班奈希尔兽穴的四件唤醒圣物之一。它与三件飞禽护符共同发挥作用，引导猛禽德鲁伊安全离开翡翠梦境。",al={"天蓝宝石背景故事","这颗宝石是什么","天蓝宝石"}},{q="天蓝宝石存放在哪里？",a="天蓝宝石存放在天空之箱中，位于泰达希尔中部班奈希尔兽穴的地下迷宫里。",al={"哪里能找到天蓝宝石","天空之箱位置","宝石位置"}},{q="为什么现在急需这颗宝石？",a="腐化的瘤背熊怪入侵了班奈希尔兽穴，让沉睡的德鲁伊陷入了极大的危险。德鲁伊深陷冥想，无法轻易自行醒来。阿斯瑞达斯·熊皮需要这颗宝石和其余圣物，举行需要谨慎施行的唤醒仪式，赶在沉睡者永远迷失之前唤醒他们。",al={"为什么要取得宝石","唤醒圣物用途"}},{q="谁会使用这件神器？",a="猛禽德鲁伊以及阿斯瑞达斯·熊皮这样的仪式守护者，会用这颗宝石唤醒沉睡的同胞，让他们结束与自然的深度交流。",al={"谁使用天蓝宝石","德鲁伊仪式宝石"}}},fp="15,171,19.457.0,23.394.0,28.199.0,34.132.0,37.295.0,23.152.0"}
P.entries["item:sara-balloo-s-plea"] = {n="萨拉·巴鲁的请求",s="悲痛中的萨拉·巴鲁请求一位联盟勇士，将她亲笔写下的请求带给国王麦格尼·铜须。",h="悲痛中的萨拉·巴鲁请求一位联盟勇士，将她亲笔写下的请求带给国王麦格尼·铜须。",kw={"国王的礼物","王座厅","铁炉堡","麦格尼·铜须","萨拉·巴鲁","萨拉·巴鲁的请求"},ang={["faction:Alliance"]="作为联盟勇士，你将萨拉的请求呈到国王面前。她信任你，是因为你为联盟效力。",["race:Dwarf"]="作为矮人，你将萨拉的心声带到王座厅，让King Magni听到每一位巡山人或平民的声音，即使他们正身处悲痛之中。"},sec={{t="寡妇的请求",b="悲痛让萨拉无力前往王座厅，于是她将自己的心声托付给一位效忠联盟的冒险者。她请求麦格尼国王铭记那些为王国效力的普通矮人家庭所承受的哀痛与付出的牺牲。"}},faq={{q="萨拉·巴鲁的请求是什么？",a="萨拉·巴鲁的请求是一封写给国王麦格尼·铜须的亲笔信。萨拉独自承受着哀痛，希望得到他的关注。",al={"萨拉·巴鲁的请求","寡妇信件 铁炉堡","萨拉的信"}},{q="萨拉·巴鲁为什么需要别人代为送信？",a="萨拉悲痛欲绝，认为以这样的状态觐见铁炉堡国王会妨碍她表达请求。因此，她将送信一事托付给一位联盟勇士。",al={"为何送信","萨拉为何不能前往","萨拉的悲痛"}},{q="这封信是送给谁的？",a="国王麦格尼·铜须在铁炉堡的王座厅接收萨拉的来信。",al={"谁收到请求","送给谁","麦格尼的信"}},{q="送达这封信会带来什么？",a="呈上这封信后，麦格尼国王得知了萨拉·巴鲁痛失亲人的遭遇，王室也由此开始采取行动，向她逝去的家人致敬。",al={"请求任务线","国王的礼物关联","接下来会怎样"}}},fx={["2b83ea9f"]={q="萨拉·巴鲁的请求来自哪里，又是谁写的？",a="这封信由萨拉·巴鲁亲笔写成，她是铁炉堡一位悲痛的矮人妇女。丧失亲人的痛苦令她难以承受，于是她亲自写下这封信，向铁炉堡的王座陈情，并将信托付给一位联盟勇士，而没有独自踏上前往王座厅的伤心之旅。",al={"谁写了萨拉·巴鲁的请求","萨拉·巴鲁的请求来自哪里","谁写成了萨拉·巴鲁的请求"}},["4ac5e6cf"]={q="为什么有人需要萨拉·巴鲁的请求？",a="国王麦格尼·铜须需要这封信，以听取一位悲伤子民的诉求。萨拉·巴鲁悲痛欲绝，无法亲自觐见君主，只能依靠你将这份请求直接交到铁炉堡统治者的手中。",al={"为什么需要萨拉·巴鲁的请求","谁需要萨拉·巴鲁的请求","为什么要递交萨拉·巴鲁的请求"}}},fp="18,110,16.229.0,27.127.0,53.166.0,26.76.0,40.136.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="萨瑞鲁斯·法伯尼的头颅",s="萨瑞鲁斯·法伯尼的头颅从贫瘠之地越过边境，被送往灰谷，作为这名巫师已死的证据。这名亡灵法师玷污了灰谷的水域，哨兵 因此索要他的头颅。",h="萨瑞鲁斯·法伯尼的头颅从贫瘠之地越过边境，被送往灰谷，作为这名巫师已死的证据。这名亡灵法师玷污了灰谷的水域，哨兵 因此索要他的头颅。",kw={"贫瘠之地","鬼雾峰","头颅","法师召唤者","萨瑞鲁斯·法伯尼","银风避难所","维尔莉妮·星坠","水元素"},ang={["faction:Alliance"]="这次行动需要深入贫瘠之地敌对的部落领地，消灭一名危险的叛逆施法者。",["race:NightElf"]="取下法伯尼的头颅，就是为 Sentinels 复仇，惩治这个亵渎大地之灵的奥术亵渎者。"},sec={{t="亵渎者的末路",b="萨瑞鲁斯·法伯尼是一名被遗忘者施法者，盘踞在贫瘠之地北部的鬼雾峰顶。他腐化并束缚了成群的水元素，激起了暗夜精灵的愤怒。银风避难所的哨兵维尔莉妮·星坠认出了他的手段，派遣勇士越过边境，深入部落领地，终结他的实验。星坠 只肯接受他被斩下的头颅，以此证明这个出言嘲弄的法师已经死去，灰谷动荡的水域也能得到些许安宁。"}},faq={{q="萨瑞鲁斯·法伯尼是谁？",a="萨瑞鲁斯·法伯尼是一名亡灵法师，在贫瘠之地北部的鬼雾峰顶建立了据点。他扭曲并召唤了大量水元素，激怒了暗夜精灵，因此哨兵维尔莉妮·星坠下令将他除掉。",al={"萨瑞鲁斯 是谁","萨瑞鲁斯·法伯尼 的故事","法伯尼 是谁"}},{q="哨兵维尔莉妮·星坠为什么要他的头颅？",a="维尔莉妮·星坠要确认这个傲慢的巫师确实已经死去。萨瑞鲁斯一边玷污这片区域的水之灵，一边嘲弄她，只有他被斩下的头颅才能让她相信威胁已经消除。",al={"为什么要取他的头颅","维尔莉妮·星坠 头颅","死亡证明"}},{q="萨瑞鲁斯·法伯尼在哪里？",a="萨瑞鲁斯·法伯尼盘踞在贫瘠之地北部的鬼雾峰顶，就在灰谷边境以南。",al={"哪里能找到 法伯尼","萨瑞鲁斯 的位置","鬼雾峰法师"}},{q="法伯尼为什么要玷污水元素？",a="萨瑞鲁斯·法伯尼利用奥术召唤，迫使众多水元素服从他的意志，并将它们腐化。他肆意操纵这些元素，扰乱了灰谷附近水流的自然平衡，招致了 哨兵 的迅速反击。",al={"为什么要腐化元素","水元素腐化","法伯尼 的动机"}}},fx={a996e76e={q="萨瑞鲁斯·法伯尼的头颅来自哪里？",a="这个被砍下的头颅来自萨瑞鲁斯·法伯尼。他是一名被遗忘者法师，在贫瘠之地北部的鬼雾峰盘踞。法伯尼在灰谷边境附近行动，亵渎水元素、不断挑衅暗夜精灵。最终，哨兵维尔莉妮·星坠派遣一位冒险者深入敌境，终结了他的嘲弄行径。",al={"萨瑞鲁斯头颅的来源","法伯尼的头颅来自哪里"}}},fp="24,177,18.497.1,26.241.1,50.217.0,35.104.1,44.240.0"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="萨科斯的爪子",s="在试炼谷南部的峭壁间，萨科斯的爪子上留着一位负伤猎人奋力一击的痕迹。哈纳祖的重击损伤了这只蝎子的螯爪，随后它的毒刺便将他击倒。",h="在试炼谷南部的峭壁间，萨科斯的爪子上留着一位负伤猎人奋力一击的痕迹。哈纳祖的重击损伤了这只蝎子的螯爪，随后它的毒刺便将他击倒。",kw={"爪子","杜隆塔尔","哈纳祖","残破的爪子","萨科斯","蝎子","试炼谷"},ang={["faction:Horde"]="身为部落的一员，在试炼谷取得这件战利品，是在杜隆塔尔严酷的荒野中对勇气和武力的一次早期考验。",["race:Troll"]="身为巨魔，将爪子带给哈纳祖，能让这位濒死的暗矛同胞保有几分尊严。他会得知，自己临终前的最后一击在那头野兽身上留下了伤痕。"},sec={{t="复仇的战利品",b="年轻的暗矛巨魔哈纳祖在试炼谷狩猎时遇上了萨科斯。这只巨蝎的毒刺刺穿了他的胸膛，让他倒在附近的一棵树下，血流不止。在毒刺袭来之前，哈纳祖击碎了这头野兽的螯爪。那只被斩下的残破爪子证明，萨科斯已被杀死。对这位负伤的猎人而言，野兽身上的伤痕证明他拼死的一击留下了印记，也是毒液流遍全身时，他守住战士荣誉的最后一丝寄托。"}},faq={{q="这只爪子为何残破不堪？",a="萨科斯在与巨魔猎人哈纳祖的一场殊死搏斗中，被击碎了螯爪。虽然萨科斯用毒刺刺中了哈纳祖的胸膛，但在它的螯爪夹住巨魔的腿之前，哈纳祖便已击中了这头野兽。",al={"爪子为何破损","谁击碎了萨科斯的爪子","残破爪子的故事"}},{q="谁想要萨科斯的爪子？",a="哈纳祖请求拿来这只爪子。他身受重伤，倒在试炼谷的一棵树下，担心自己会死在那里。他希望有人杀死萨科斯，以保全自己的荣誉；得知此事已成，他便有了坚持下去的意志，直到高内克派人前来救援。",al={"谁需要萨科斯的爪子","交给谁","哈纳祖的爪子"}},{q="这只爪子来自哪里？",a="这只爪子来自萨科斯，一只体型庞大、性情凶猛的蝎子，游荡在杜隆塔尔试炼谷南部悬崖一带的高地上。",al={"萨科斯的位置","萨科斯在哪里","哪里获取残破的爪子"}}},fp="22,191,21.449.0,24.189.0,33.219.0,30.147.0"}
P.entries["item:sarltooth-s-talon"] = {n="萨尔图斯的爪子",s="在维尔加挖掘场上方，萨尔图斯的爪子标志着迅猛龙袭击的终结。奥莫尔·铁衣要用这只爪子证明那头野兽已被杀死。",h="在维尔加挖掘场上方，萨尔图斯的爪子标志着迅猛龙袭击的终结。奥莫尔·铁衣要用这只爪子证明那头野兽已被杀死。",kw={"挖掘","奥莫尔·铁衣","迅猛龙","萨尔图斯","爪子","湿地","维尔加"},ang={["class:Hunter"]="作为猎人，追踪萨尔图斯这样狡猾的兽群首领，并取下一只爪子作为战利品，考验着射击与野兽控制的本领。",["race:Dwarf"]="作为矮人，取回这只爪子，就是为那些奉国王麦格尼·铜须之命、为探险者协会效力而丧生的矮人考古学家复仇。"},sec={{t="复仇的战利品",b="奥莫尔·铁衣在山脊上目睹迅猛龙攻入维尔加挖掘场，屠杀了矮人探险队。他无力阻止这场屠杀。在奥莫尔看来，一头名叫萨尔图斯的巨型迅猛龙很可能就是这群野兽的首领。为了替死去的同胞复仇，奥莫尔要求杀死这头野兽，并带回它的一只爪子作为证明。这只爪子标志着萨尔图斯对这片古老矮人废墟的统治就此终结。"}},faq={{q="萨尔图斯的爪子来自哪里？",a="萨尔图斯的爪子来自萨尔图斯，这头体型庞大的迅猛龙首领在湿地维尔加挖掘场上方的西侧山脊游荡。",al={"谁掉落萨尔图斯的爪子","萨尔图斯位置","如何获得爪子"}},{q="谁想要萨尔图斯的爪子？",a="奥莫尔·铁衣想要这只爪子。这名矮人驻守在维尔加挖掘场上方的眺望台，要求拿出证据，证明屠杀他队员的野兽已被杀死。",al={"谁收爪子","在哪里交爪子","奥莫尔·铁衣任务"}},{q="奥莫尔·铁衣为什么需要萨尔图斯已死的证据？",a="奥莫尔相信，正是萨尔图斯率领迅猛龙群驱赶并杀害了那些矮人挖掘者。在他看来，这只爪子能为死去的同伴伸张正义，告慰他们的亡魂。",al={"为什么杀萨尔图斯","萨尔图斯做了什么"}},{q="挖掘场的矮人遭遇了什么？",a="矮人在这里挖掘，为探险者协会寻找古代文物。野生迅猛龙伏击了工人，杀死了大多数人，将幸存者赶到了附近的山脊上。",al={"维尔加挖掘场背景故事","挖掘场为什么有迅猛龙"}}},fx={["28fc0e8a"]={q="什么是萨尔图斯的爪子？",a="这是从萨尔图斯身上取下的一只断爪。萨尔图斯是一只凶暴的迅猛龙，据信它率领着那群袭击维尔加挖掘场的野兽。奥莫尔·铁衣要这只爪子作为确凿证据，证明野兽已被杀死，也证明那些阵亡的矮人挖掘者已经得以报仇。",al={"什么是萨尔图斯的爪子","萨尔图斯的爪子背景"}}},fp="17,153,21.384.0,39.137.0,28.174.0,57.173.0,52.167.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="萨丝拉的祭品",s="在月神殿，萨丝拉的祭品让萨丝拉的灵魂有机会获得安宁。她的银色丝囊取自这只栖居于泰达希尔的强大蜘蛛。",h="在月神殿，萨丝拉的祭品让萨丝拉的灵魂有机会获得安宁。她的银色丝囊取自这只栖居于泰达希尔的强大蜘蛛。",kw={"达纳苏斯","艾露恩","萨丝拉","女祭司艾茉拉","萨丝拉的祭品","银色丝囊","蜘蛛","泰达希尔","月神殿"},ang={["class:Priest"]="身为牧师，你可以将这个仪式视为神圣的仁慈之举。艾露恩姐妹会用圣水净化污秽，而非仅仅丢弃被杀死的野兽。",["race:NightElf"]="身为暗夜精灵，你知道，杀死遭到腐化的野生生物是一项沉重的职责。让萨丝拉的灵魂重归Elune的恩典，便是对这份职责的尊重。"},sec={{t="圣水中的净化",b="萨丝拉曾是泰达希尔一只古老而受敬重的生灵，直到疯狂与腐化悄然蔓延至巨树的枝头，将她吞噬。艾露恩姐妹会请你带回她的银色丝囊，将其作为神圣的祭品，而非战利品。在月神殿的喷泉中，她的遗骸浸入圣水。仪式洗去了毒害萨丝拉心智的污秽，解放了她饱受折磨的灵魂。随后，她的灵魂安然现身于圣殿之中，有望在Elune的恩典下重获新生。"}},faq={{q="什么是萨丝拉的祭品？",a="萨丝拉的祭品是取自萨丝拉的银色丝囊，她是一只在泰达希尔遭到腐化的强大蜘蛛。艾露恩姐妹会用这些丝囊举行仪式，净化她的灵魂。",al={"丝囊是什么","萨丝拉的祭品物品","萨丝拉祭品"}},{q="为什么必须将丝囊放入喷泉？",a="达纳苏斯的月神殿中，喷泉盛着奉献给艾露恩的圣水。将萨丝拉的遗骸浸入其中，便能洗去令她陷入疯狂的腐化，让她的灵魂摆脱痛苦。",al={"为什么用神殿喷泉","为什么献祭萨丝拉","喷泉有什么作用"}},{q="献上祭品后会发生什么？",a="当你将祭品放入圣水，腐化便会被净除，萨丝拉的幽魂随之显现。她安详地绕着水池行走，表明她的灵魂已获得安宁。",al={"喷泉旁会发生什么","萨丝拉的灵魂显现","喷泉事件"}},{q="谁主持这个仪式？",a="女祭司艾茉拉主持这个仪式。她是驻守月神殿的艾露恩姐妹会成员，指引你让萨丝拉安息，并将她的遗骸献给女神。",al={"谁给予萨丝拉的祭品","女祭司艾茉拉任务","谁净化萨丝拉"}}},fp="19,171,31.542.0,28.176.0,50.196.0,44.187.1,25.187.0"}
P.entries["item:satyr-horns"] = {n="萨特的角",s="在灰谷，萨特的角吸引着寻求复仇的树妖和前往棘齿城的商人。这些角来自萨特，它们的腐化已在这片古老的森林中扎根。",h="在灰谷，萨特的角吸引着寻求复仇的树妖和前往棘齿城的商人。这些角来自萨特，它们的腐化已在这片古老的森林中扎根。",kw={"安妮莉亚","林歌神殿","伊莉亚娜","夜道谷","皮克希尔","萨特的角","萨提纳尔","碎木岗哨","萨维亚"},ang={["faction:Horde"]="部落战士从碎木岗哨出发，清剿威胁伐木作业的萨特，再把角卖给前往棘齿城的地精买家。",["race:NightElf"]="对kaldorei而言，割取萨特的角是一项痛苦的职责。他们借此清除祖传森林中的同族，那些同族舍弃了自己的传承，转而为恶魔效力。"},sec={{t="复仇的战利品与交易的货物",b="灰谷的萨特头上长着角，那是恶魔腐化的标志。在艾森娜神殿，树妖伊莉亚娜怀着悲痛收集这些角，为死去的姐妹安妮莉亚复仇。皮克希尔是一名在碎木岗哨歇脚的地精旅人，她收购这些角用于交易。棘齿城对萨特的角需求日增，猎手可以在那里出售这些从被杀恶魔身上取下的残骸。"},{t="清剿腐化据点",b="萨特的角必须从这些野兽身上割下；普通商贩并不出售。萨特盘踞在灰谷各处的据点，包括萨维亚腐化的林地、萨提纳尔的谷地和夜道谷的废墟。清剿这些据点能够遏制残存的恶魔污染，也能为悲痛的守护者和急切的商人带去猎杀的凭证。"}},faq={{q="伊莉亚娜为什么想要萨特的角？",a="伊莉亚娜收集萨特的角，是为了替被灰谷萨特杀害的姐妹安妮莉亚复仇。这些角证明萨特的数量正在减少，也让安妮莉亚的灵魂得以安息。",al={"伊莉亚娜 角","安妮莉亚 萨特","林歌神殿任务"}},{q="皮克希尔为什么收集萨特的角？",a="皮克希尔是一名精于生意的旅人，暂住在碎木岗哨，收集萨特的角，准备带往棘齿城。她得知这些角在那座地精港口能卖个好价钱，便在启程前雇用猎手冒险猎取。",al={"皮克希尔 碎木岗哨","皮克希尔为什么要角","棘齿城 萨特的角"}},{q="哪里最容易找到长着这些角的萨特？",a="萨特栖居在灰谷的几处腐化区域。东北部的萨维亚和萨提纳尔，以及森林中东部的夜道谷，都有许多萨特出没。",al={"灰谷萨特位置","萨特在哪里","萨特营地"}},{q="萨特是什么，为什么会长角？",a="萨特原本是古代暗夜精灵，在上古之战期间订立契约，变成了形似野兽的恶魔生物。它们的蹄子、尾巴和角，都是燃烧军团赋予它们的恶魔腐化的标志。",al={"萨特是什么","萨特为什么长角"}}},fx={["2131c67f"]={q="什么是萨特的角？",a="萨特的角是从灰谷潜伏的萨特头上砍下来的弯曲邪恶之角。作为古代暗夜精灵遭受恶魔腐化后的产物，萨特长着这些骇人的畸角，象征着他们所受的诅咒。对于冒险者来说，这些角主要是萨特覆灭的冷酷证明，或是在卡利姆多各地交易的珍贵异域奇物。",al={"什么是萨特的角","萨特之角物品","萨特的角是什么"}},["8a39621c"]={q="为什么有人想要萨特的角？",a="不同阵营想要萨特之角的原因各不相同。对于林歌神殿的树妖伊莉亚娜来说，这些角是她向杀害妹妹安妮莉亚的腐化恶魔复仇的确凿凭证。与此同时，像皮克希尔这样的投机商人会收集它们，在繁忙的棘齿城出售；那里对异域炼金材料、奇珍和野兽部件的需求一直很旺盛。",al={"谁想要萨特的角","为什么收集萨特的角","为什么需要萨特的角"}}},fp="11,163,34.327.0,30.359.0,35.170.0,36.223.0,58.155.0,44.212.0"}
P.entries["item:savannah-lion-tusk"] = {n="草原狮的獠牙",s="在贫瘠之地，草原狮的獠牙既是狩猎战利品，也是酿造老陈·风暴烈酒那传说中的烈性麦酒的原料。",h="在贫瘠之地，草原狮的獠牙既是狩猎战利品，也是酿造老陈·风暴烈酒那传说中的烈性麦酒的原料。",kw={"贫瘠之地","酿酒师德罗恩","老陈·风暴烈酒","迪舒","修玛","棘齿城","草原狮的獠牙"},ang={["class:Hunter"]="身为猎人，在贫瘠之地追踪凶猛的狮群，是对你技艺的考验。它们危险的獠牙在战斗中足以致命，对当地酿酒师而言也颇有价值。"},sec={{t="奇特的酿酒原料",b="游荡在贫瘠之地的大型猫科野兽长着尖锐而粗重的獠牙。徘徊者、雌性猎手、雄狮统领的狮群，以及狮王休玛这样的野兽，都长着这种獠牙。旅人常常取下这些牙齿，作为狩猎成功的证明。棘齿城的酿酒师德罗恩用这些獠牙，加上平原陆行鸟的肾脏和雷霆蜥蜴的角，重现老陈·风暴烈酒那款以他本人命名的著名佳酿。这种烈性麦酒的酒劲堪称传奇，凡人鲜有能承受得住的。"}},faq={{q="酿酒师德罗恩为什么需要草原狮的獠牙？",a="棘齿城的酿酒师德罗恩需要这些獠牙，来重现以老陈·风暴烈酒本人命名的佳酿。他的导师将配方传给了他，而要重现这种黑啤酒独特的风味和酒劲，需要三种产自贫瘠之地的原料，獠牙就是其中之一。",al={"为什么用獠牙酿啤酒","德罗恩狮子獠牙","酿酒师德罗恩配方"}},{q="哪些野兽长有草原狮的獠牙？",a="贫瘠之地各处草原狮群的成员都长有这种獠牙。其中包括草原狮王、草原雄狮、草原母狮、草原雌狮、草原徘徊者，以及迪舒和狮王休玛这样的稀有野兽。",al={"狮子獠牙哪里掉落","谁掉落狮子獠牙","草原狮的獠牙来源"}},{q="狮子真的长有獠牙吗？",a="草原上的大型猫科野兽长着硕大的犬齿，在卡利姆多险峻的荒野中，这些牙齿长得粗壮而突出。当地的猎人和拓荒者称其为獠牙。",al={"为什么狮子的牙齿叫獠牙","狮子獠牙与犬齿的区别","狮子獠牙结构"}}},fp="18,104,28.414.0,51.240.0,39.188.0,29.151.0"}
P.entries["item:scaber-stalk"] = {n="粗柄蘑菇",s="在黑海岸，巴瑞萨斯·月影正在寻找生长于峭壁之泉后方隐秘洞穴中的粗柄蘑菇。",h="在黑海岸，巴瑞萨斯·月影正在寻找生长于峭壁之泉后方隐秘洞穴中的粗柄蘑菇。",kw={"奥伯丁","巴瑞萨斯·月影","洞穴蘑菇","峭壁之泉","黑海岸","毒帽蘑菇","粗柄蘑菇"},ang={["profession:Herbalism"]="这些地下生长的蘑菇并非市面上常见的草药，却能让人了解洞穴中独特的气候和逐渐侵入的阴影如何影响当地的真菌。",["race:NightElf"]="身为暗夜精灵，你听从古树之林的警告，小心对待这些洞穴蘑菇；一股腐化力量正在峭壁之泉附近滋生。"},sec={{t="稀有的真菌标本",b="粗柄蘑菇生长在黑海岸东北部群山中、峭壁之泉后方的地下洞穴里。这些颜色苍白的蘑菇在潮湿幽深的洞穴群中茁壮生长，远离寻常的森林植被。它们的生长之地偏远而危险，因此鲜有人能采集到，奥伯丁的巴瑞萨斯·月影便委托斥候冒险深入那片黑暗。"},{t="瀑布中的阴影",b="古树之林曾警告当地的暗夜精灵，不要前去采集粗柄蘑菇。林中年迈的树灵察觉到，一股黑暗的邪恶力量正在峭壁之泉的洞穴中扎根，并日益壮大。炼金师珍视粗柄蘑菇和稀有的毒帽蘑菇，用它们试制药剂，但前去寻找这些蘑菇的人，可能会遭遇正在群山之下扎根的邪恶。"}},faq={{q="粗柄蘑菇生长在哪里？",a="粗柄蘑菇生长在黑海岸东北部群山中、峭壁之泉后方的潮湿洞穴里。",al={"粗柄蘑菇位置","粗柄蘑菇在哪里","粗柄蘑菇洞穴"}},{q="谁在寻找粗柄蘑菇？",a="奥伯丁的巴瑞萨斯·月影正在寻找粗柄蘑菇和一株毒帽蘑菇，用来调制一种特殊药水。",al={"谁使用粗柄蘑菇","巴瑞萨斯·月影的蘑菇","谁需要粗柄蘑菇"}},{q="巴瑞萨斯·月影为什么不亲自采集粗柄蘑菇？",a="古树之林的树灵察觉到一股危险的新生邪恶力量藏身于瀑布后方，于是警告巴瑞萨斯不要靠近那处洞穴。",al={"为什么不亲自采集","巴瑞萨斯的警告","壁泉洞穴警告"}},{q="还有什么与粗柄蘑菇一同生长？",a="洞穴中还生长着致命的毒帽蘑菇，这是巴瑞萨斯进行炼金研究所需的另一种稀有标本。",al={"洞穴里的其他蘑菇","毒帽蘑菇和粗柄蘑菇","壁泉的蘑菇"}}},fp="12,91,22.313.0,21.337.1,28.101.0,24.98.0,58.141.0,40.122.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="老瞎眼的鳞片",s="在西部荒野沿海，葛瑞森船长正在寻找老瞎眼已死的证据。这位幽灵徘徊在西部荒野灯塔，那个鱼人的袭击曾让灯塔的灯火熄灭。",h="在西部荒野沿海，葛瑞森船长正在寻找老瞎眼已死的证据。这位幽灵徘徊在西部荒野灯塔，那个鱼人的袭击曾让灯塔的灯火熄灭。",kw={"葛瑞森船长","海岸威胁","鱼人","老瞎眼","老瞎眼的鳞片","西部荒野","西部荒野灯塔"},ang={["faction:Alliance"]="作为一名穿越无尽之海、驶向暴风城的联盟水手，协助终结老瞎眼的袭击，就能让西部荒野的灯塔保持明亮，让船只免于触礁。"},sec={{t="海岸祸害的战利品",b="老瞎眼让西部荒野的海岸成了杀戮之地。葛瑞森船长是被束缚在西部荒野灯塔的幽灵，据他说，那个狡猾的鱼人纠集了意志薄弱的鱼人，一起袭击海岸。瞎眼赶走了灯塔看守人一家，导致格雷森的船撞上礁石时，灯塔仍是一片漆黑。\n\n当这家人回来重新点燃灯火时，瞎眼再次发动袭击，将他们全家杀害。格雷森想要得到那怪物的一片鳞片，以此证明海岸上最凶残的掠食者已被除掉。"}},faq={{q="老瞎眼的鳞片有什么用途？",a="葛瑞森船长需要这片鳞片，作为老瞎眼已死的证据。这位幽灵徘徊在西部荒野灯塔，寻求复仇，因为格雷森的船失事时，瞎眼让灯塔的灯火熄灭，随后又杀害了灯塔看守人全家。",al={"谁需要鳞片","瞎眼鳞片交付","老瞎眼的鳞片用途"}},{q="老瞎眼是谁？",a="老瞎眼是一个凶残狡猾的鱼人首领，在西部荒野的沙岸上游荡。他能组织并胁迫同族，对沿岸哨站发动配合严密的致命袭击。",al={"瞎眼是谁","瞎眼背景故事","老瞎眼"}},{q="老瞎眼为什么要袭击灯塔？",a="老瞎眼最初袭击灯塔，是为了赶走看守人及其家人，让海岸陷入黑暗。当他们回来重新点燃灯火时，他又纠集同族发动袭击，杀害了这家所有人。船只从此失去指引，无法看清沿岸危险的浅滩。",al={"为何袭击灯塔","灯塔袭击","瞎眼灯塔"}}},fx={["6e72b95e"]={q="老瞎眼的鳞片是什么？",a="这是一片直接取自老瞎眼身上的坚硬鳞片，外形独特，而他正是肆虐西部荒野海岸、臭名昭著的鱼人首领。带着这片鳞片，就能确凿地证明这个致命的海岸掠夺者终于被杀死了。",al={"老瞎眼的鳞片是什么","老瞎眼的鳞片物品","瞎眼鳞片"}},["383f15e9"]={q="老瞎眼的鳞片来自哪里？",a="这片鳞片来自老瞎眼天生的鳞皮，这个异常狡猾而凶残的鱼人在西部荒野海岸游荡。它并非凡人锻造或制作，而是在战斗中击败他后，从他的尸体上取下的。",al={"老瞎眼的鳞片来源","哪里能获得老瞎眼的鳞片","谁制作了老瞎眼的鳞片"}},e7059369={q="葛瑞森船长为什么需要老瞎眼的鳞片？",a="葛瑞森船长是一位徘徊在西部荒野灯塔的船长幽灵，他渴望复仇，也渴望了结心愿。老瞎眼吓跑了灯塔看守一家，导致格雷森的船触礁那晚灯塔没有亮起，而那家人回来后，他又再次袭击，将他们全部杀害。格雷森要求拿来这片鳞片，作为那头怪物已经死去、海岸变得更加安全的确凿证据。",al={"格雷森为什么需要鳞片","为什么需要老瞎眼的鳞片","谁需要老瞎眼的鳞片"}}},fp="21,165,27.481.0,43.240.0,20.178.0,43.277.0"}
P.entries["item:scarlet-armband"] = {n="血色十字军臂章",s="在丧钟镇，血色十字军臂章是侵入被遗忘者领地的狂热分子的标志。执行官阿伦要求收集这些臂章，以证明新近复生者已经展开反击。",h="在丧钟镇，血色十字军臂章是侵入被遗忘者领地的狂热分子的标志。执行官阿伦要求收集这些臂章，以证明新近复生者已经展开反击。",kw={"丧钟镇","执行官阿伦","血色十字军臂章","血色信徒","血色十字军","血色新兵","提瑞斯法林地"},ang={["race:Undead"]="作为一名新近复生的被遗忘者，收集血色十字军臂章会让你直面生者世界的憎恨。你能否生存下去，取决于你能否抵御血色十字军，保护自己。"},sec={{t="狂热的徽记",b="血色十字军臂章是血色十字军追随者的标志，从新兵到刚加入的信徒都会佩戴。十字军的红色徽记警示着丧钟镇新近复生的被遗忘者：危险就在近旁。十字军战士不区分天灾军团那些没有心智的仆从与黑暗女王麾下拥有自由意志的臣民。在他们眼中，每一具行走的尸体都必须被烧毁。执行官阿伦收集这些臂章，是为了确认丧钟镇东南方的敌军斥候已经被消灭，也为了确认新生的被遗忘者有能力保卫他们初建的国家。"}},faq={{q="执行官阿伦为什么需要血色十字军臂章？",a="执行官阿伦需要血色十字军臂章，以证明丧钟镇东南方血色十字军营地中的敌人正被逐步清除。血色十字军威胁着刚刚苏醒的被遗忘者，而这些信物表明，他们的前哨斥候和新兵已被消灭。",al={"为什么收集臂章","阿伦臂章任务","血色十字军臂章用途"}},{q="谁佩戴这些臂章？",a="血色新兵、血色信徒和信使迈文·考加尔都佩戴这些臂章。他们是驻扎在丧钟镇附近的血色十字军低阶成员。",al={"谁掉落血色十字军臂章","哪里能找到臂章"}},{q="血色十字军为什么憎恨被遗忘者？",a="血色十字军憎恨被遗忘者，因为这些狂热分子认为，巫妖王麾下没有心智的天灾军团与拥有自由意志的被遗忘者毫无区别。他们将所有亡灵都视为必须铲除的怪物。",al={"血色十字军为什么攻击亡灵","血色十字军与被遗忘者的对抗","血色十字军狂热分子"}},{q="能找到这些臂章的营地在哪里？",a="营地位于提瑞斯法林地，就在丧钟镇东南方不远处，坐落在镇子外围的丘陵中。",al={"血色十字军营地位置","丧钟镇血色十字军营地","血色信徒在哪里"}}},fp="15,158,21.513.0,46.244.0,25.169.0,47.204.0,52.110.0"}
P.entries["item:scarlet-crusade-documents"] = {n="血色十字军文件",s="在丧钟镇附近的血色十字军营地，一名信使携带着血色十字军文件，穿行于提瑞斯法。截获的命令列出了战地指挥官的姓名及其部队的行动指示，为被遗忘者的军事领袖提供了血色十字军在林地各处布防的情报。",h="在丧钟镇附近的血色十字军营地，一名信使携带着血色十字军文件，穿行于提瑞斯法。截获的命令列出了战地指挥官的姓名及其部队的行动指示，为被遗忘者的军事领袖提供了血色十字军在林地各处布防的情报。",kw={"布瑞尔","丧钟镇","执行官阿伦","执行官塞加德","迈文·考加尔","血色十字军文件","血色信使","重要情报"},ang={["race:Undead"]="作为一名已经苏醒的被遗忘者，运送这些文件让你走出丧钟镇墓地的试炼，投身由布瑞尔指挥的更大规模的战事。"},sec={{t="截获的命令",b="迈文·考加尔从丧钟镇东南方的血色十字军营地携带这些文件出发。文件奉大领主之命，向血色十字军提瑞斯法地区指挥部的各位队长下达指示。派瑞恩队长必须进一步加固西南方的哨塔，并收集布瑞尔亡灵的情报。瓦松队长必须镇压北方哨塔附近的亡灵活动，而麦罗斯队长则负责监视瘟疫之地的边境。这些命令列出了血色十字军战地军官的姓名，以及他们在提瑞斯法林地各处的驻地和职责。"},{t="送往布瑞尔",b="执行官阿伦明白，丧钟镇的当地部队无法充分利用这些情报。缴获的文件成了一名刚刚苏醒的被遗忘者离开丧钟镇的通行证。带着它们向东北方前进，经过炉灰庄园，抵达布瑞尔，将它们交给布瑞尔城镇大厅外的执行官塞加德。掌握这些命令后，被遗忘者的军事领袖便能筹划迅速出击，打击盘踞在林地各处的血色十字军指挥官。"}},faq={{q="是谁携带着这些文件？",a="血色十字军信使迈文·考加尔在丧钟镇东南方的血色十字军营地携带着这些文件。",al={"谁掉落这些文件","血色十字军信使","迈文·考加尔"}},{q="文件里有什么情报？",a="这些文件奉大领主之命，向血色十字军提瑞斯法地区指挥部下达指示。派瑞恩队长必须加固西南方的哨塔，并收集布瑞尔亡灵的情报。瓦松队长必须镇压北方哨塔附近的亡灵活动，麦罗斯队长则必须监视瘟疫之地的边境。",al={"文件上写了什么","文件内容"}},{q="谁需要查看这些文件？",a="你为丧钟镇的执行官阿伦夺回文件，他随后委托你将文件送交执行官塞加德，后者在布瑞尔城镇大厅外统筹这一地区的军事行动。",al={"送到哪里","文件交给谁"}},{q="为什么这些文件对被遗忘者很重要？",a="这些命令揭示了血色十字军军官在提瑞斯法林地各处的部署位置。被遗忘者可以利用它们消灭敌方首领，重挫这些狂热之徒在这一地区的士气。",al={"被遗忘者为什么需要这些文件","血色十字军文件的重要性"}}},fp="25,243,18.495.0,17.427.0,33.115.0,41.295.0,33.180.0,50.172.0"}
P.entries["item:scarlet-insignia-ring"] = {n="血色十字军徽记之戒",s="在提瑞斯法林地，血色十字军徽记之戒是血色十字军成员的标志。在布瑞尔，被遗忘者收集这些戒指，作为又一名狂热者倒下的证明。",h="在提瑞斯法林地，血色十字军徽记之戒是血色十字军成员的标志。在布瑞尔，被遗忘者收集这些戒指，作为又一名狂热者倒下的证明。",kw={"布瑞尔","亡灵卫兵伯吉斯","执行官塞加德","死亡证明","血色十字军","血色十字军徽记之戒","提瑞斯法林地","瓦里玛萨斯"},ang={["faction:Horde"]="身为部落的一员，收集这些戒指可以削弱幽暗城周围狂热的血色十字军，帮助部落巩固在东部王国的立足之地。",["race:Undead"]="身为被遗忘者的一员，从死去的血色十字军战士身上夺下这些戒指，便是宣告提瑞斯法属于死者，并执行黑暗女王和瓦里玛萨斯的命令。"},sec={{t="狂热的信物",b="提瑞斯法林地的每一名血色十字军战士都带着一枚徽记之戒，从新入伍的新兵、狂热的修士，到麦拉其和派瑞恩两位上尉，无一例外。每枚戒指上都刻着血色十字军的烈焰徽记，在这个被猜忌吞噬的组织中表明成员身份。在外人看来，这些戒指标识着洛丹伦最为狂热的人类残部。"},{t="恐惧魔王的悬赏",b="布瑞尔的亡灵卫兵伯吉斯奉瓦里玛萨斯之命收集这些戒指，后者是希尔瓦娜斯女士麾下的恐惧魔王副官。被遗忘者将血色十字军视为蔓延在他们新近占据的家园上的瘟疫。新兵将戒指带回布瑞尔，以此证明一名血色十字军战士已死，也证明自己对幽暗城王座的忠诚。"}},faq={{q="谁佩戴这些徽记之戒？",a="驻扎在提瑞斯法林地的血色十字军成员几乎都佩戴着徽记之戒。佩戴者包括新兵、传教士、狂热者和先锋，以及战地军官派瑞恩上尉、麦拉其上尉和瓦松上尉。",al={"谁掉落戒指","哪些血色十字军有戒指","戒指持有者"}},{q="亡灵卫兵伯吉斯为什么要收集血色十字军徽记之戒？",a="亡灵卫兵伯吉斯收集这些戒指，作为血色十字军战士被击杀的证明。布瑞尔的被遗忘者驻军奉瓦里玛萨斯和黑暗女王之命，用这些戒指衡量新兵的忠诚，以及他们清除洛丹伦人类的战果。",al={"为何收集戒指","需要死亡证明的原因","伯吉斯戒指"}},{q="戒指上的徽记代表什么？",a="戒指上刻着血色十字军的标志，代表着他们为彻底清除洛丹伦一切亡灵而发动的圣战。血色十字军战士满怀骄傲地佩戴着它，将其视为正义的象征，而他们的执念却驱使他们屠戮组织之外的所有人。",al={"血色十字军标志","徽记是什么","戒指徽记"}},{q="瓦里玛萨斯在收集这些戒指的行动中扮演什么角色？",a="瓦里玛萨斯是希尔瓦娜斯·风行者在幽暗城的首席副官。他统管提瑞斯法林地针对敌对活人的军事行动，使血色十字军成为执行官塞加德和亡灵卫兵伯吉斯等被遗忘者指挥官的首要目标。",al={"瓦里玛萨斯的命令","瓦里玛萨斯为何要戒指","恐惧魔王的参与"}}},fp="21,155,18.319.0,23.321.0,31.226.0,56.262.0,45.244.0,58.256.0"}
P.entries["item:scavenged-goods"] = {n="破烂装备",s="在丧钟镇周围，被遗忘者从装备箱中收集破烂装备。新近复生的亡灵依靠这些废弃物资，为随后苏醒的新兵提供武器和衣物。",h="在丧钟镇周围，被遗忘者从装备箱中收集破烂装备。新近复生的亡灵依靠这些废弃物资，为随后苏醒的新兵提供武器和衣物。",kw={"亡灵卫兵萨尔坦","丧钟镇","装备箱","被遗忘者的补给","破烂装备","丧钟镇搜集物资"},ang={["race:Undead"]="身为被遗忘者，你需要靠废弃的装备生存；活人不会给予你任何援助或怜悯。"},sec={{t="自力更生",b="新的被遗忘者在丧钟镇的墓地中苏醒，身上除了腐烂的裹尸布，几乎一无所有。附近的聚落和王国都不向亡灵提供援助，因此他们必须搜寻可用之物，满足自身所需。亡灵卫兵萨尔坦从村中各处的补给箱里收集废弃的武器、工具和衣物，再将它们分发给下一批苏醒的新兵。"}},faq={{q="破烂装备用来做什么？",a="亡灵卫兵萨尔坦收集破烂装备，为刚从墓地中苏醒的被遗忘者配备武器和衣物。没有附近箱子里的物资，他们就只能赤手空拳、衣不蔽体地踏入提瑞斯法林地。",al={"破烂装备的用途","为什么收集破烂装备","萨尔坦用破烂装备做什么"}},{q="这些物资在哪里？",a="这些物资存放在丧钟镇各处的装备箱中，箱子位于村舍外和残破建筑周围。",al={"哪里能找到破烂装备","破烂装备的位置","装备箱在哪里"}},{q="谁在征集破烂装备？",a="亡灵卫兵萨尔坦是丧钟镇的一名军官，他让刚刚苏醒的被遗忘者收集物资。他教导他们自力更生，也为随后苏醒的新兵做好准备。",al={"谁需要破烂装备","亡灵卫兵萨尔坦的任务"}}},fp="15,161,22.332.0,34.183.0,28.96.0,33.170.0"}
P.entries["item:scavenger-paw"] = {n="食腐狼的爪子",s="在丧钟镇，食腐狼的爪子取自那些在山丘间游荡的幼小、毛皮凌乱的狼。刚刚苏醒的被遗忘者收集这些砍下的狼爪，交给当地的照料者缝制成简陋的护具。",h="在丧钟镇，食腐狼的爪子取自那些在山丘间游荡的幼小、毛皮凌乱的狼。刚刚苏醒的被遗忘者收集这些砍下的狼爪，交给当地的照料者缝制成简陋的护具。",kw={"丧钟镇","新兵艾尔雷斯","蓬毛食腐狼","食腐狼的爪子","被诅咒者","幼年食腐狼"},ang={["profession:Tailoring"]="作为裁缝，你可以看到新兵艾尔雷斯如何将狼爪和蝙蝠翅膀缝制成简陋的装备，供初建的被遗忘者聚居地使用。",["race:Undead"]="作为刚刚苏醒的被遗忘者，你的血肉已经腐烂，装备也寥寥无几。你可以从当地的捕食者身上收集材料，拼凑出足够的护甲，以应对提瑞斯法的危险。"},sec={{t="丧钟镇的拼凑护甲",b="丧钟镇那些刚刚重返人世的被遗忘者几乎没有多余的物资。天灾军团和血色十字军步步紧逼提瑞斯法，因此每一片皮、每一块骨头都得派上用场。新兵艾尔雷斯协助暗影牧师萨维斯，收集食腐狼的爪子和蝙蝠翅膀。她用这些材料制作堪用的衣物和护甲，供那些刚从坟墓中爬出、仍因重返人世而茫然失措的被遗忘者使用。"}},faq={{q="食腐狼的爪子有什么用途？",a="新兵艾尔雷斯在丧钟镇收集食腐狼的爪子，将未经处理的动物肢体缝制成基础的护甲和衣物，供新生的被遗忘者使用。",al={"食腐狼的爪子用途","爪子用途","为何收集爪子"}},{q="在哪里能找到这些爪子？",a="你可以从小食腐狼和蓬毛食腐狼身上找到这些爪子，它们是在丧钟镇周围的树林和田野间游荡的野狼。",al={"爪子掉落地点","哪里获取爪子","哪些狼掉落爪子"}},{q="谁在索要这些爪子？",a="新兵艾尔雷斯需要这些爪子。她协助暗影牧师萨维斯，救治受伤的新兵、缝制装备，并为外出执行任务的人配备行装。",al={"谁需要食腐狼的爪子","爪子任务发布者","新兵艾尔雷斯爪子"}}},fp="13,178,27.408.0,33.132.0,23.117.0,24.158.0"}
P.entries["item:scorched-spider-fang"] = {n="烧焦的蜘蛛牙",s="湿地各处的洞穴捕猎者和吸血捕猎者都带有烧焦的蜘蛛牙。暴风城的弗伦·长须需要五十颗，用来加固联盟战士的锁甲。",h="湿地各处的洞穴捕猎者和吸血捕猎者都带有烧焦的蜘蛛牙。暴风城的弗伦·长须需要五十颗，用来加固联盟战士的锁甲。",kw={"洞穴捕猎者","火焰淬炼锁甲","弗伦·长须","吸血捕猎者","烧焦的蜘蛛牙","暴风城","湿地"},ang={["class:Warrior"]="身为战士，你将面对弗伦·长须的试炼：收集五十颗獠牙。这项任务既考验你的耐力，也为你的锁甲提供原料。",["profession:Blacksmithing"]="身为铁匠，你能看出弗伦如何将烧焦的几丁质和獠牙融入锁环，遵循超越寻常熔炼技艺的罕见矮人制甲传统。"},sec={{t="矮人铁匠的配方",b="在暴风城，铁匠弗伦·长须用不同寻常的方法加固锁甲。他需要五十颗来自湿地巨型蜘蛛的烧焦獠牙。这些獠牙质地致密，含有毒素，经过高温后变得更加坚硬。弗伦在淬炼锁环时，将这种材料融入其中。"},{t="湿地的潜伏者",b="洞穴捕猎者和吸血捕猎者长着弗伦所需的獠牙。它们栖居在湿地下陷的山谷和洞穴中，周围潮湿腐败。它们的上颚坚硬，带着焦痕。要收集五十颗獠牙，就得深入低洼洞穴，面对成群的蜘蛛。"}},faq={{q="烧焦的蜘蛛牙有什么用途？",a="暴风城的弗伦·长须需要五十颗烧焦的蜘蛛牙，为联盟战士锻造坚固的胸甲。这项工作还需要来自石爪山和剃刀沼泽的材料。",al={"烧焦的蜘蛛牙有什么用","烧焦的蜘蛛牙用途","谁需要烧焦的蜘蛛牙"}},{q="在哪里可以找到烧焦的蜘蛛牙？",a="湿地的洞穴捕猎者和吸血捕猎者都带有烧焦的蜘蛛牙。可以在它们潮湿的洞穴、山坡和挖掘洞窟中寻找。",al={"烧焦的蜘蛛牙掉落地点","哪些蜘蛛掉落烧焦的蜘蛛牙","哪里刷烧焦的蜘蛛牙"}},{q="铁匠为什么需要这么多蜘蛛牙来制作护甲？",a="弗伦·长须用不同寻常的矮人技艺加固锁甲。他用硬化的獠牙、燃素和野兽的角来处理锁环。",al={"为什么需要五十颗獠牙","弗伦为什么需要蜘蛛牙"}},{q="任何冒险者都能收集并交付这些獠牙吗？",a="任何途经湿地的人都可以杀死蜘蛛，取下它们的上颚。弗伦只为那些志在赢得火焰淬炼锁甲的进取战士打造护甲。",al={"烧焦的蜘蛛牙是否仅限战士","谁能交付烧焦的蜘蛛牙"}}},fx={a7a99cbb={q="烧焦的蜘蛛牙是什么？",a="烧焦的蜘蛛牙是经过高温作用而硬化的毒牙，取自潜伏在湿地的 洞穴捕猎者 和 吸血捕猎者 等掠食性蛛类。它们外表焦黑易碎，密度却异常之高，因此深受寻找稀有材料、运用高深锻造技艺的熟练护甲匠珍视。",al={"烧焦的蜘蛛牙是什么","烧焦的蜘蛛牙","烧焦的牙"}},c6d8f632={q="烧焦的蜘蛛牙来自哪里？",a="这些毒牙并非凡人之手打造，而是直接取自湿地的巨型蛛类，具体而言就是 吸血捕猎者 和 洞穴捕猎者。长期受到地下环境的影响，加上毒液天然的炼金作用，使这些毒牙变得焦黑，并具有仿佛经过烈火淬炼的韧性。",al={"烧焦的蜘蛛牙来自哪里","烧焦的蜘蛛牙起源","烧焦的蜘蛛牙来源"}}},fp="20,165,25.253.0,24.267.0,40.185.0,39.138.0,62.133.0,51.175.0"}
P.entries["item:scroll-of-messaging"] = {n="通讯卷轴",s="在石爪山脉，加克希姆·尘链为通讯卷轴想好了用途。这位侏儒工程师打算利用卷轴的传讯法术远程引爆炸药。",h="在石爪山脉，加克希姆·尘链为通讯卷轴想好了用途。这位侏儒工程师打算利用卷轴的传讯法术远程引爆炸药。",kw={"炸药","加克希姆·尘链","ng-5","远程引爆装置","通讯卷轴","石爪山脉","荆棘谷地精"},ang={["faction:Alliance"]="对联盟特工而言，这张卷轴有助于破坏荆棘谷地精的机械，阻碍他们摧毁石爪山脉的森林。",["profession:Engineering"]="这张卷轴展示了侏儒工程学如何利用奥术魔法，为远程炸药接收信号。"},sec={{t="易爆的讯息",b="加克希姆·尘链计划将一条讯息化作荆棘谷地精伐木场的一场爆炸。他会将卷轴的传讯咒语与易爆的NG-5炸药结合起来。这场爆炸将引开守卫的注意，让特工有时间潜入，窃取工程设计图和机密信件。"}},faq={{q="通讯卷轴有什么用途？",a="加克希姆·尘链利用通讯卷轴的传讯魔法进行远程引爆。配合NG-5，他就能从远处引发爆炸。",al={"通讯卷轴用途","通讯卷轴有什么用","加克希姆·尘链为什么要卷轴"}},{q="这张卷轴要交给谁？",a="这张卷轴要交给石爪山脉的侏儒工程师加克希姆·尘链。",al={"通讯卷轴交给谁","通讯卷轴送到哪里","卷轴接收者"}},{q="加克希姆·尘链为什么需要远程炸药？",a="加克希姆·尘链需要在荆棘谷地精的作业区制造一场大规模的骚乱，以引开注意。这场混乱将掩护特工潜入、窃取工程图纸，并取回用来阻止荆棘谷地精滥伐森林的文件。",al={"加克希姆·尘链使用炸药的原因","为什么要炸荆棘谷地精","石爪山脉引开注意"}},{q="NG-5是什么？",a="NG-5是加克希姆·尘链使用的一种化学炸药。它与卷轴的魔法信号相结合，就构成了远程引爆装置。",al={"ng-5","ng-5是什么","ng-5炸药"}}},fx={["2071477e"]={q="什么是通讯卷轴？",a="通讯卷轴是一张带有奥术法术的魔法羊皮纸。加克希姆·尘链想要找到它，将其作为一种非常规催化剂，与他不稳定的爆炸物NG-5结合，以便制造一种可远程引爆的炸药，用来对付石爪山的荆棘谷地精。",al={"什么是通讯卷轴","通讯卷轴的背景","关于通讯卷轴"}}},fp="19,98,18.314.0,41.152.0,25.84.0,39.220.0,13.130.0"}
P.entries["item:sea-creature-bones"] = {n="海洋生物的骸骨",s="在黑海岸，海洋生物的骸骨来自被冲上岸的巨型海兽尸体。温尼斯·布莱葛为达纳苏斯的月神殿收集骨骼样本，那里正在调查这些海兽搁浅的原因。",h="在黑海岸，海洋生物的骸骨来自被冲上岸的巨型海兽尸体。温尼斯·布莱葛为达纳苏斯的月神殿收集骨骼样本，那里正在调查这些海兽搁浅的原因。",kw={"奥伯丁","搁浅的海洋生物","黑海岸","灰雾鱼人","温尼斯·布莱葛","薄雾海","海洋生物的骸骨","月神殿"},ang={["class:Druid"]="古老的海洋掠食者离奇死亡，表明卡利姆多近海的水域出现了深层的异动。这让所有致力于维护生态平衡的守护者感到不安。",["race:NightElf"]="突如其来的大规模搁浅让崇尚自然和谐的暗夜精灵深感不安。他们将这些搁浅事件视为凶兆，需要月神殿予以关注。"},sec={{t="海岸上的凶兆",b="巨型海洋生物开始将自己冲上黑海岸的浅滩，并在那里死去。其中有巨大的蛇颈龙，体型远超当地海域的同类。暗夜精灵将搁浅数量的骤增视为不祥之兆。温尼斯·布莱葛受月神殿派遣来到奥伯丁，收集搁浅生物的骸骨。角鹰兽将样本运往达纳苏斯，以供仔细检验。"},{t="腐尸与食腐者",b="庞大的尸体吸引了当地的食腐者。灰雾鱼人聚集在死去和濒死的生物周围，啃食它们的血肉，并凶狠地守卫着这片觅食地。这些鱼人太过弱小，无法猎杀如此庞大的野兽，但调查人员和冒险者必须突破薄雾海沿岸成群鱼人的阻挠，才能取得骨骼碎片用于研究。"}},faq={{q="这些生物为什么会被冲上岸？",a="确切原因仍然不明。偶尔搁浅属于自然灾害，但艾露恩的女祭司们认为，搁浅数量突然大幅增加并非自然现象，令人不安，她们已经展开正式调查。",al={"蛇颈龙为何搁浅","黑海岸死鲸","生物为何在黑海岸搁浅"}},{q="谁需要这些骸骨？",a="驻扎在奥伯丁的调查员温尼斯·布莱葛为达纳苏斯的月神殿收集骸骨。那里的学者和女祭司希望查明究竟是什么扰乱了海洋。",al={"谁收骸骨","海洋生物的骸骨交给谁","温尼斯 黑海岸"}},{q="是鱼人杀死了这些巨兽吗？",a="不是。灰雾鱼人太过弱小，无法杀死如此庞大的海兽。它们在这些生物被冲上岸后成群聚集，啃食尸体。",al={"鱼人杀死了蛇颈龙吗","灰雾鱼人杀死海怪"}},{q="这些骸骨是从哪里取得的？",a="这些骸骨来自搁浅在黑海岸沿岸的巨型尸体，尤其是奥伯丁南面的沙滩和薄雾海沿岸。",al={"哪里能找到海洋生物的骸骨","搁浅海洋生物的位置"}}},fp="18,223,22.411.0,22.319.0,39.208.0,22.166.0,40.143.0,35.129.0"}
P.entries["item:sea-turtle-remains"] = {n="海龟的残骸",s="在黑海岸沿岸，巨型海龟死在岸边和海面之下。它们的遗骸被送往奥伯丁的研究人员手中，用于研究日益增多的搁浅事件。",h="在黑海岸沿岸，巨型海龟死在岸边和海面之下。它们的遗骸被送往奥伯丁的研究人员手中，用于研究日益增多的搁浅事件。",kw={"奥伯丁","搁浅的海龟","黑海岸","温尼斯·布莱葛","海龟的残骸","泰达希尔","月神殿","被冲上岸"},ang={["class:Druid"]="巨型海洋生物的非自然死亡表明，更深层的腐化正在扰乱卡利姆多沿岸的自然平衡。",["race:NightElf"]="大批海洋生物在你祖辈故土的近海搁浅，这是不祥之兆，尤其是疑似的源头就在环绕泰达希尔的水域之中。"},sec={{t="令人不安的搁浅",b="巨大的海洋生物被冲上黑海岸的海滩，还有一些躺在沉船附近的水下。在奥伯丁，温尼斯·布莱葛负责监督从尸体上采集碎骨和组织的工作。达纳苏斯的月神殿急需这些样本。那里的学者和女祭司担心，这些生物可能正在逃离泰达希尔周围水域中某种非自然的异动。"},{t="浅滩食腐者",b="收集遗骸十分危险。沿岸的鱼人部族经常聚集在巨大的尸体周围，啃净骨头上的血肉，并在旁边筑巢。学者们需要新鲜的碎骨和组织，赶在食腐者毁掉证据之前，查明这些生物为何在迁徙中丧命。"}},faq={{q="这些遗骸有什么用途？",a="温尼斯·布莱葛在奥伯丁收集遗骸，将它们整理好，供达纳苏斯月神殿的学者和女祭司研究。他们试图查明，为何有如此多的海洋生物死在黑海岸沿岸。",al={"为什么收集海龟遗骸","海龟骨头用途","黑海岸海龟任务"}},{q="海龟为什么会在黑海岸搁浅？",a="研究人员尚未找到原因，但他们担心，海洋生物正在逃离泰达希尔周围水域中某种令人不安的东西。这些搁浅事件并非个例；它们表明海洋生物正普遍陷入困境。",al={"海龟为什么死亡","黑海岸海龟搁浅","搁浅的海洋生物"}},{q="在哪里能找到这些尸体？",a="巨型海龟的尸体散落在黑海岸沿岸。一些躺在奥伯丁以西沉船附近的浅水中，另一些则散布在鱼人营地环绕的海滩上。",al={"海龟遗骸位置","哪里能找到海龟骨骸"}},{q="谁在研究这些遗骸？",a="温尼斯·布莱葛在奥伯丁收集遗骸，并将详细报告送往达纳苏斯月神殿的艾露恩姐妹会。",al={"谁需要遗骸","温尼斯·布莱葛"}}},fp="18,149,19.379.0,26.287.0,32.199.0,53.195.0,32.181.0,30.150.0"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="神秘访客的资料",s="典狱官塞尔沃特将一份关于探访暴风城监狱囚犯巴基尔·斯瑞德的男子的报告密封起来。这份机密记录或许能帮助调查者追踪一个游走于暴风城政界与犯罪圈子之间的人。",h="典狱官塞尔沃特将一份关于探访暴风城监狱囚犯巴基尔·斯瑞德的男子的报告密封起来。这份机密记录或许能帮助调查者追踪一个游走于暴风城政界与犯罪圈子之间的人。",kw={"巴隆斯·阿历克斯顿","巴基尔·斯瑞德","麦里克","马迪亚斯·肖尔","密封的描述","监狱","典狱官塞尔沃特"},ang={["class:Rogue"]="身为潜行者，你可以看出，当马迪亚斯·肖尔将这名男子的相貌与SI:7的情报进行比对时，假名、伪造的证件和探监行为是如何引起他注意的。",["faction:Alliance"]="身为联盟成员，你可以看出暴风城安保的薄弱之处：阴谋分子凭借伪造的证件，就能通过监狱大门。"},sec={{t="神秘的庇护者",b="多年来，监狱中的囚犯巴基尔·斯瑞德一直无人探望。后来，一个沉默寡言的男子开始每周来一两次，持有署名为麦里克的有效证件。典狱官塞尔沃特留意到了此人，并记下了他的相貌。他将这份相貌描述密封起来，以免在正式调查者采取行动之前被好事者窥见。"},{t="从石匠到密探",b="城市建筑师巴隆斯·阿历克斯顿未能根据这份描述找到明确符合的人。他怀疑访客可能与迪菲亚叛乱有关，于是将密封的信封送交暴风城情报机构SI:7的首领马迪亚斯·肖尔。肖尔认出此人是个手段致命的雇佣兵，使用过包括马尔松在内的多个名字。如今，这名雇佣兵替葛瑞格·莱斯科瓦勋爵干着见不得人的勾当。"}},faq={{q="这份描述是谁写的？",a="暴风城监狱的主管典狱官塞尔沃特撰写并密封了这份文件。一名陌生男子开始定期探望被关押的迪菲亚首领巴基尔·斯瑞德，这引起了他的怀疑。",al={"谁写的","描述的作者","谁写的便条"}},{q="文件中描述的访客是谁？",a="访客携带着署名为麦里克的证件。典狱官塞尔沃特记下了他的相貌，以便调查者辨认他的身份。",al={"谁在探望斯瑞德","麦里克是谁","访客身份"}},{q="访客为何要与巴基尔·斯瑞德会面？",a="多年来一直无人探望的巴基尔·斯瑞德，开始定期接待访客。调查者正在查阅这份密封的相貌描述，以查明访客的目的。",al={"为何探望斯瑞德","斯瑞德访客的目的"}},{q="这份密封文件需要送到哪里？",a="先将文件交给暴风城的城市建筑师巴隆斯·阿历克斯顿。阿历克斯顿查看这份陌生人的相貌描述后，会让你将它送交位于旧城区的军情七处总部的马迪亚斯·肖尔。",al={"送到哪里","谁需要这份描述"}}},fx={["7193ccc9"]={q="关于 斯瑞德 访客的描述为什么如此重要？",a="多年来，巴基尔·斯瑞德被遗弃在监狱中，从未有人探望。当一名携带着署名为“麦里克”的文书的神秘人物突然开始每周探望他时，典狱官塞尔沃特怀疑背后藏着更深的阴谋。揭开这名访客的身份，对于查明暴风城中究竟是谁在与迪菲亚潜行者被囚禁的首领积极联络至关重要，因此调查者开始求助于马迪亚斯·肖尔的情报网，以查明这名神秘联络人的身份。",al={"为什么需要这份描述","为什么需要 斯瑞德 的密封描述","访客描述为什么重要"}}},fp="38,215,19.325.0,25.380.1,27.196.0,42.127.2,46.153.2,49.206.1"}
P.entries["item:sealed-envelope"] = {n="密封的信封",s="菲兹克斯将荆棘谷地精的机密封在密封的信封中，要将它交给棘齿城的斯布特瓦夫。",h="菲兹克斯将荆棘谷地精的机密封在密封的信封中，要将它交给棘齿城的斯布特瓦夫。",kw={"设计图","菲兹克斯","棘齿城","密封的信封","斯布特瓦夫","石爪山","超级收割机6000","荆棘谷地精"},ang={["faction:Horde"]="将这些文件从石爪山带往南方，能帮助棘齿城的中立地精削弱荆棘谷地精肆意掠夺资源的伐木活动。",["profession:Engineering"]="信封里装着Super Reaper 6000的技术图纸，这台出自地精之手的机器破坏力惊人，也能带来丰厚的利润。"},sec={{t="商业间谍",b="荆棘谷地精将地精工程师菲兹克斯赶出其在石爪山脉的伐木场后，他偷偷带走了公司的机密。信封里装着内部手册、操作规程和技术规格。其中包括超级收割机 6000的设计图，这台机器专为大规模清伐而造。"},{t="送往棘齿城",b="菲兹克斯将文件送往南方，交给中立地精港口棘齿城的一名工程师斯布特瓦夫。热砂港的商业对手对菲兹克斯本人没什么好感，也不怎么信任他，但这些设计在工程上的价值毋庸置疑。它们揭示了荆棘谷地精在机械方面的巧思，也让独立工程师有机会利用其先进的伐木技术。"}},faq={{q="密封的信封里装着什么？",a="信封里装着荆棘谷地精的内部文件、技术手册，以及伐木机器超级收割机 6000的设计图。菲兹克斯仓促离开公司时偷走了这些资料。",al={"信封内容","密封的信封里有什么","密封的信封物品"}},{q="这包文件是谁准备的？",a="荆棘谷地精将地精工程师菲兹克斯赶出其在石爪山脉的伐木场后，心怀不满的他准备了这个信封。",al={"谁准备了信封","谁给了密封的信封","菲兹克斯的信封"}},{q="这封信要交给谁？",a="信封要交给斯布特瓦夫，他是贫瘠之地港口城镇棘齿城的一名地精工匠。",al={"谁接收信封","信封送往哪里","交给斯布特瓦夫"}},{q="斯布特瓦夫为什么想要这些文件？",a="斯布特瓦夫厌恶荆棘谷地精，而这些文件提供了宝贵的改进方案和设计图，让公司以外的工匠能够理解并采用其强大的机械设计。",al={"斯布特瓦夫为什么想要它","荆棘谷地精技术棘齿城"}}},fp="15,109,19.315.0,19.342.0,35.192.0,25.138.0,30.99.0,43.185.0"}
P.entries["item:sealed-note-to-elling"] = {n="给埃林的密信",s="在暴风城，乔贞将一封密函送往提亚斯奶酪坊的店主埃林·提亚斯手中。这位渔夫的消息让提亚斯卷入了对一名失踪外交官的秘密调查。",h="在暴风城，乔贞将一封密函送往提亚斯奶酪坊的店主埃林·提亚斯手中。这位渔夫的消息让提亚斯卷入了对一名失踪外交官的秘密调查。",kw={"埃林·提亚斯","乔贞","给埃林的密信","暴风城","失踪的外交官","贸易区","提亚斯奶酪"},ang={["class:Rogue"]="身为一名熟悉暴风城地下关系网的潜行者，你或许知道埃林·提亚斯的身份远不止奶酪商人。这封秘密往来的信函，正符合那些关系网的行事方式。",["faction:Alliance"]="身为联盟的一员，你为王室效力，传递乔贞的消息。通过这种方式，你帮助推进了一项对暴风城政治稳定至关重要的调查。"},sec={{t="秘密交接",b="在暴风城，乔贞对这封密信的交付有严格要求：亲手交给埃林·提亚斯，并且守口如瓶。事关重大，容不得半点口风不严。提亚斯在贸易区经营着一家奶酪店。在那里，乔贞的消息将外交官失踪案的调查带到了他的柜台前。"}},faq={{q="密信里写了什么？",a="这封信在送到埃林·提亚斯手中之前始终保持密封。信中载有乔贞的报告，并指引送信人向提亚斯进一步询问外交官失踪一事。",al={"信件内容","信里写了什么","信件正文"}},{q="为什么一个奶酪商人会收到秘密情报？",a="埃林·提亚斯在贸易区经营着一家不起眼的奶酪店，以此掩饰身份。在这层表象之下，他有一张遍布全城的庞大地下耳目网。这让他在需要谨慎行事的调查中颇有价值。",al={"为什么是埃林·提亚斯","为什么是奶酪店","提亚斯是间谍吗"}},{q="乔贞是谁？",a="乔贞是一名渔夫，就在暴风城英雄谷的水边。他与埃林·提亚斯和德拉维主教有些旧交，后者会找他处理一些需要避人耳目的秘密事务。",al={"谁写的信","乔贞的故事","看守乔贞"}},{q="失踪外交官一案是怎么回事？",a="一名奉命前往塞拉摩会见吉安娜·普罗德摩尔的暴风城外交官始终没有抵达。王室当局正秘密调查每一条可疑线索，以免在城中引起恐慌。",al={"失踪外交官的故事","外交官是谁","外交官为什么失踪"}}},fx={["76232759"]={q="给埃林的密信是什么？",a="这是乔贞交给你的一封机密信件，专门写给埃林·提亚斯，供他亲耳听取、亲眼阅读。信件以火漆封缄来确保秘密，承载着有关失踪外交官调查的紧急情报，托付给你穿过暴风城，安全地亲手送达。",al={"给埃林的密信是什么","给埃林的密信物品","乔贞的信是什么"}},["2cd529f3"]={q="给埃林的密信来自哪里？",a="这封信由乔贞亲笔写下并封好。在询问并评估有关王国失踪外交官的线索后，乔贞写下这封秘密信函，直接交到你手中，让你送给埃林·提亚斯。",al={"给埃林的密信由谁撰写","密信来自哪里","谁交出了给埃林的密信"}},["92e95eae"]={q="为什么需要给埃林的密信？",a="外交官失踪一事极为敏感，关乎国家安全。乔贞无法在街头公开谈论，因此这封信承担了秘密引荐和向埃林·提亚斯移交情报的作用，让提亚斯参与调查，同时避免惊动窥探的目光。",al={"为什么要递送密信","埃林·提亚斯为什么需要这封信","乔贞的信为什么重要"}}},fp="21,176,16.297.0,39.169.0,53.235.0,14.197.0,40.177.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="给守夜人巴库斯的密信",s="在暴风城，埃林·提亚斯给暮色森林的守夜人巴库斯寄去一封密信。他请这位守夜人卫兵报告夜色镇附近的迪菲亚活动。",h="在暴风城，埃林·提亚斯给暮色森林的守夜人巴库斯寄去一封密信。他请这位守夜人卫兵报告夜色镇附近的迪菲亚活动。",kw={"夜色镇","暮色森林","埃林·提亚斯","守夜人","密信","失踪的外交官","守夜人巴库斯"},ang={["class:Rogue"]="身为潜行者，你可以看到提亚斯如何依靠一名普通卫兵获取当地情报。这让他能够收集远在城墙之外的情报。",["faction:Alliance"]="身为联盟的一员，你可以看到，当官方渠道失灵时，私人关系和非正式情报如何帮助这个阵营维系支离破碎的领地。"},sec={{t="给守卫的口信",b="埃林·提亚斯答应用自己的人脉帮助寻找失踪的外交官。他封好一封写给守夜人巴库斯的信，后者是一名驻守暮色森林的守夜人卫兵。\n\n提亚斯派一位旅人向南穿过森林，亲手送去这封信。他希望巴库斯报告在夜色镇附近发现的任何迪菲亚踪迹。"},{t="提亚斯遍布远方的耳目",b="埃林·提亚斯在暴风城的贸易区售卖奶酪，在城外也有人脉。他的信送到了守夜人巴库斯手中，后者是夜色镇时刻保持警惕的守夜人的一名卫兵。\n\n夜色镇面临着亡灵和凶猛野兽的威胁。巴库斯很高兴收到提亚斯的来信，这表明提亚斯在暴风城之外也赢得了尊重。"}},faq={{q="这封信是谁写的？",a="这封信是埃林·提亚斯写的。他在暴风城的贸易区经营着提亚斯奶酪坊，暗中还从事间谍和情报掮客的工作。",al={"给守夜人巴库斯的密信是谁写的","信的作者","谁给的信"}},{q="为什么要把信送给守夜人巴库斯？",a="守夜人巴库斯在夜色镇的守夜人服役，也是埃林·提亚斯信任的联络人。提亚斯请他报告当地发现的迪菲亚潜行者在暮色森林一带活动的踪迹或传闻。",al={"守夜人巴库斯是谁","为什么送给巴库斯","巴库斯的职责"}},{q="在哪里能找到守夜人巴库斯？",a="守夜人巴库斯在暮色森林中夜色镇正北方不远处的道路上巡逻。他监视着从森林通往镇子的道路。",al={"巴库斯在哪里","守夜人巴库斯的位置","寻找守夜人巴库斯"}},{q="信送到之后会发生什么？",a="巴库斯认得提亚斯的名字，也信任他的请求。他放下了平日对旅人的戒心，同意调查林中的可疑活动。",al={"巴库斯说了什么","送信之后"}}},fx={["8647b8fc"]={q="给守夜人巴库斯的密信是什么？",a="这是暴风城的奶酪商大师埃林·提亚斯写给暮色森林的守夜人巴库斯的一封机密信件。提亚斯托你带去这封信，请巴库斯协助收集当地迪菲亚潜行者活动的情报，以推进对失踪外交官的调查。",al={"给守夜人巴库斯的密信是什么","给守夜人巴库斯的密信用途","提亚斯 给 巴库斯 的信"}}},fp="29,149,20.285.0,25.309.1,20.137.0,39.189.0,34.110.0,41.163.0"}
P.entries["item:searing-collar"] = {n="灼热项圈",s="在杜隆塔尔的骷髅石，火刃氏族的教徒在仪式中佩戴灼热项圈。灼烫的金属项圈烧灼着他们的血肉，使教徒逐渐与恶魔之力相契合。",h="在杜隆塔尔的骷髅石，火刃氏族的教徒在仪式中佩戴灼热项圈。灼烫的金属项圈烧灼着他们的血肉，使教徒逐渐与恶魔之力相契合。",kw={"火刃氏族","恶魔","杜隆塔尔","邪能","玛高兹","灼热项圈","骷髅石"},ang={["class:Warlock"]="身为术士，你或许能看出，灼热项圈是将邪能腐化导入凡人血肉的粗陋媒介。",["race:Orc"]="身为兽人，在杜隆塔尔的门户发现教徒使用这些项圈，会让你沉重地意识到：受恶魔奴役的阴影依然挥之不去。"},sec={{t="腐化之器",b="火刃氏族在奥格瑞玛东边不远处的骷髅石集结，举行黑暗仪式。教徒、新信徒和暴徒颈上都戴着灼热项圈，忍受着在皮肤上烙下印记、灼伤血肉的高温。隐士玛高兹正在研究这些残酷的器具。他怀疑，灼烧与金属上附着的附魔会使佩戴者逐渐与恶魔能量相契合。腐化正在部落眼皮底下的兽人社会中蔓延，这些项圈在其中究竟起着什么作用？"}},faq={{q="什么是灼热项圈？",a="火刃氏族的教徒在仪式中将灼热项圈戴在颈上。灼烫的金属烧灼着他们的血肉，帮助他们逐渐与恶魔之力相契合。",al={"灼热项圈是什么","灼热项圈背景故事","项圈有什么作用"}},{q="谁会佩戴这些项圈？",a="藏身于骷髅石内的火刃氏族成员佩戴着这些项圈，其中包括教徒、狂热者、暴徒、学徒和新信徒。",al={"谁在使用这些项圈","谁掉落灼热项圈","火刃氏族项圈"}},{q="教徒为什么要灼烧自己的血肉？",a="火刃氏族在仪式中使用灼热的金属。教徒承受灼烧与恶魔附魔，使自己的身体和灵魂逐渐与恶魔之力相契合。",al={"为什么灼烧自己的血肉","为什么佩戴灼热项圈","项圈的用途"}},{q="谁想检查灼热项圈？",a="在杜隆塔尔扎营的调查者玛高兹收集灼热项圈，以研究上面的附魔，并查明火刃氏族的影响。",al={"谁需要灼热项圈","谁在研究这些项圈","玛高兹项圈"}}},fp="14,140,25.448.0,25.149.0,24.139.0,41.162.0,41.141.0"}
P.entries["item:searing-coral"] = {n="灼热珊瑚",s="在湿地沿岸，人们从海底活着的铁珊瑚上采集灼热珊瑚。工匠和铁匠看重其中耐热的矿物，用它来强化护甲。",h="在湿地沿岸，人们从海底活着的铁珊瑚上采集灼热珊瑚。工匠和铁匠看重其中耐热的矿物，用它来强化护甲。",kw={"弗伦·长须","铁珊瑚","铁炉堡","科罗莫特·钢尺","米奈希尔港","灼热珊瑚","战士护甲","湿地"},ang={["class:Warrior"]="身为战士，采集灼热珊瑚能向铁炉堡的护甲大师证明你的决心。他们会为你量身打造一件胸甲，用于激烈的前线战斗。",["profession:Blacksmithing"]="身为铁匠，你可以见识到侏儒的巧思如何与传统矮人金属工艺结合，将海洋矿物制成淬炼过的板甲。"},sec={{t="稀有的海岸资源",b="灼热珊瑚生长在米奈希尔港以南冰冷的海水中。活着的铁珊瑚在咸水中茁壮生长，产出的材料富含矿物，能够承受极高的温度。采集者必须撬下坚硬的珊瑚，而野生鱼人和其他水生野兽就在附近游荡。"},{t="锻造中的用途",b="矮人铁匠向来没有使用灼热珊瑚的传统。在铁炉堡，科罗莫特·钢尺等充满好奇心的侏儒工匠，采用了资深护甲锻造师弗伦·长须传授的方法。他们熔炼珊瑚，将其锤入金属合金，为有志向的战士打造轻便耐用的护甲。"}},faq={{q="灼热珊瑚生长在哪里？",a="灼热珊瑚生长在湿地米奈希尔港以南近海浅水下的铁珊瑚群中。",al={"灼热珊瑚位置","哪里能找到灼热珊瑚","铁珊瑚位置"}},{q="铁炉堡里谁需要灼热珊瑚？",a="科罗莫特·钢尺是铁炉堡侏儒区的一名侏儒技师，正在寻找灼热珊瑚。他用从传奇矮人护甲锻造师弗伦·长须那里学来的锻造方法进行试验。",al={"谁使用灼热珊瑚","科罗莫特·钢尺珊瑚","弗伦·长须珊瑚"}},{q="珊瑚如何锻造成护甲？",a="灼热珊瑚的结构异常致密，而且耐热。将它放入熔炉熔炼，再锤入金属合金，便能强化复合甲板，制成格外坚固的护具。",al={"珊瑚锻造","珊瑚能熔炼吗","灼热珊瑚冶金"}},{q="采集灼热珊瑚危险吗？",a="找到珊瑚后，采集本身并无危险。要到达它生长的地方，就得游入湿地沿岸的开阔水域，那里有野生鱼人和凶猛的水生野兽游荡。",al={"灼热珊瑚烫吗","采集铁珊瑚"}}},fx={["3e3d13aa"]={q="灼热珊瑚是什么？",a="灼热珊瑚是一种富含矿物的稀有海洋生长物，采自米奈希尔港南面湿地沿海水下的 铁珊瑚 群落。虽然它来自海洋，但其致密而奇特的性质，使熟练的铁匠能够像处理金属一样熔炼、锤打和加工它。",al={"灼热珊瑚是什么","灼热珊瑚信息","灼热珊瑚背景"}},["1c0d8f00"]={q="灼热珊瑚来自哪里？",a="灼热珊瑚是天然的水生生物，并非人造的器物。世上已知只有一处生长着这种珊瑚：湿地的米奈希尔港以南沿海水域中，淹没在水下的铁珊瑚丛之间。",al={"灼热珊瑚的来源","灼热珊瑚来自哪里","谁制作了灼热珊瑚"}}},fp="13,170,23.267.0,23.290.0,30.115.0,37.187.0,35.198.0,38.167.0"}
P.entries["item:secure-crate"] = {n="保险箱",s="在贫瘠之地，一只保险箱正等着旅人将它送往棘齿城。箱中的药水和炼金制品将运往东部王国。",h="在贫瘠之地，一只保险箱正等着旅人将它送往棘齿城。箱中的药水和炼金制品将运往东部王国。",kw={"贫瘠之地","黑水湾","药水","棘齿城","施法材料","保险箱","航运","码头管理员迪兹维格"},ang={["faction:Horde"]="身为部落的旅人，你知道棘齿城的中立港口通过地精航运连接着卡利姆多与东部王国。",["profession:Herbalism"]="身为草药师，你能看出海两岸的炼金师和草药师如何依靠边疆商路交换原料。"},sec={{t="信使的货物",b="信使、商队和地精船只承担着卡利姆多与东部王国之间的货运。当贫瘠之地的商队未能按时出发时，旅人便会将这只保险箱之类的易碎货物送往海岸。箱中装着药水、炼金制品和施法材料，要送给无尽之海彼岸的合作伙伴。箱子已经密封，以抵御贫瘠之地沿途的风尘和航程中的海浪飞沫。"},{t="途经棘齿城港口",b="箱子的陆路旅程在棘齿城码头结束，码头管理员迪兹维格在这里监管货运。棘齿城是一座中立港口，供跨海货物中转，其中也包括运往黑水湾的货物。迪兹维格依照热砂港的账簿办事，先登记包裹和货物，再将它们装上下一艘离港的船。棘齿城将卡利姆多与边疆连接起来。"}},faq={{q="保险箱里装着什么？",a="保险箱里装着药水、炼金材料和其他补给品，要送给东部王国的合作伙伴。",al={"箱中物品","箱子里有什么","保险箱物品"}},{q="箱子要送往哪里？",a="将它送到棘齿城码头的码头管理员迪兹维格手中。他会安排将它装上一艘驶往卡利姆多黑水湾的商船。",al={"箱子目的地","保险箱送往哪里"}},{q="为什么把箱子交给冒险者，而不是商队？",a="寄件人无法及时赶到棘齿城，而定期往来的商队已经出发。受雇的信使必须赶在涨潮前将箱子送到码头。",al={"为什么持有箱子","错过商队"}},{q="谁在棘齿城接收箱子？",a="码头管理员迪兹维格会在棘齿城码头接收箱子，记入货运账簿，再装上下一艘乘潮出航的船。",al={"谁接收箱子","迪兹维格的箱子"}}},fp="12,139,17.376.0,27.382.0,32.111.0,30.151.0,62.163.0,31.158.0"}
P.entries["item:senir-s-report"] = {n="森内尔的报告",s="在丹莫罗寒冷的山麓，森内尔·白须将他对霜鬃巨魔的调查结果送往铁炉堡，呈交给参议员巴林·红石。",h="在丹莫罗寒冷的山麓，森内尔·白须将他对霜鬃巨魔的调查结果送往铁炉堡，呈交给参议员巴林·红石。",kw={"巴林·红石","霜鬃","铁炉堡","麦格尼·铜须","参议院","森内尔·白须","森内尔的报告","报告"},ang={["faction:Alliance"]="身为联盟的一员，你递送森内尔的报告，既能帮助保卫丹莫罗，也要周旋于铁炉堡统治者之间棘手的政治纷争。",["race:Dwarf"]="身为矮人，递送森内尔的报告会让你卷入铁炉堡的分歧，一方是国王麦格尼·铜须的敕令，另一方是参议院所要求的权力。"},sec={{t="王命",b="森内尔的报告汇集了巡山人在丹莫罗群山间侦察霜鬃巨魔时的见闻。他还附上了兄弟格瑞林对寒脊山谷情况的报告。格瑞林在当地的行动得到了国王麦格尼·铜须的批准。\n\n森内尔将调查结果送交铁炉堡王座厅的参议员巴林·红石。他提醒信使，不要提及他为整理这些材料寻求了多少外界帮助。"},{t="王座厅的纷争",b="森内尔·白须的报告送达王廷，引起了轩然大波。参议员巴林·红石既为巨魔的威胁而愤怒，也为报告所凭借的权威而恼火。麦格尼绕过了立法监督，而白须则奉行未经制约的王命。\n\n此举加深了参议员们的不满，他们要求掌控议事程序。麦格尼果断的统治方式与参议院对权力的诉求之间，矛盾愈发尖锐。"}},faq={{q="森内尔的报告是什么？",a="森内尔·白须的报告记录了他对丹莫罗霜鬃巨魔的调查。他将报告送往铁炉堡的矮人参议院。",al={"森内尔的报告","这份报告是什么","报告"}},{q="这份报告应该交给谁？",a="森内尔·白须将报告呈交给铁炉堡王座厅的参议员巴林·红石，他就在国王麦格尼·铜须的王座附近。",al={"谁接收报告","报告交给谁","报告接收人"}},{q="为什么红石参议员读完报告后如此愤怒？",a="红石参议员勃然大怒，因为随附的格瑞林·白须的报告表明，格瑞林奉麦格尼国王之命行事，却没有征询参议院的意见。王室未经参议员批准便擅自处理防务，令红石深感不满。",al={"巴林为何愤怒","参议员为何愤怒","红石的反应"}},{q="为什么森内尔要求你不要提及曾帮助过他？",a="森内尔·白须要求你对提供帮助一事保密，好让上级相信，是他独自在积雪的山丘间完成了危险的侦察。他想维护自己勤勉能干的巡山人声誉。",al={"为何保密","森内尔的秘密","森内尔的功劳"}}},fx={["078e838e"]={q="森内尔的报告来自哪里，是谁写的？",a="森内尔·白须在丹莫罗侦察了当地霜鬃巨魔的威胁，并找到援手应对霜鬃巨魔要塞后，亲自起草了这份公文。除了他自己的调查结果，公文还附有他兄弟格瑞林奉国王麦格尼·铜须之命撰写的寒脊山谷报告，将两人的报告从白雪覆盖的边地送往首都的宏伟厅堂。",al={"谁写了森内尔的报告","森内尔的报告来自哪里","森内尔的报告的作者"}},e0c0da53={q="为什么有人需要森内尔的报告？",a="参议员巴林·红石和铁炉堡参议院需要正式的实地评估，以掌握丹莫罗的地区局势和军事行动。然而，这份公文明确宣示了麦格尼国王对当地军事调动的单方面决定权，因此具有强烈的政治意味，让参议院得知了他们认为绕过其监督的王室行动。",al={"为什么要递送森内尔的报告","红石为什么需要森内尔的报告","森内尔的报告的用途"}}},fp="14,133,17.399.0,25.430.1,23.143.0,38.131.0,56.253.1,50.210.0"}
P.entries["item:serena-s-head"] = {n="塞瑞娜·血羽的头颅",s="在贫瘠之地北部的无水岭，塞瑞娜·血羽的头颅被悬赏索取，以证明她已死去。达索克·快刀打算将其悬挂在部落的补给车上，警告鹰身人不要再发动袭击。",h="在贫瘠之地北部的无水岭，塞瑞娜·血羽的头颅被悬赏索取，以证明她已死去。达索克·快刀打算将其悬挂在部落的补给车上，警告鹰身人不要再发动袭击。",kw={"十字路口","达索克·快刀","无水岭","鹰身人","雷克萨","塞瑞娜·血羽","塞瑞娜·血羽的头颅","巫翼"},ang={["class:Rogue"]="达索克·快刀看重干净利落、冷酷无情的行事作风。他赞赏那些能潜入敌人栖息处后方、毫不犹豫地处决目标的雇佣兵。",["faction:Horde"]="部落商队将杜隆塔尔、莫高雷和遥远的前哨站连接起来。将塞瑞娜·血羽的头颅悬挂在补给车上，就是在宣告部落对这片荒野的统治。"},sec={{t="道路上的警告",b="塞瑞娜·血羽率领无水岭的巫翼鹰身人，袭击途经贫瘠之地北部的商旅。她的姐妹死于兽王雷克萨之手，因此她对部落补给线的袭击愈发凶残。兽人盗贼达索克·快刀下令猎杀塞瑞娜，以挫败这群鹰身人的士气。他要将她被斩下的头颅悬挂在一支即将出发的商队中，让那些在峭壁上窥伺的鹰身人看见这个警告。"}},faq={{q="达索克·快刀为什么想要塞瑞娜·血羽的头颅？",a="达索克想要塞瑞娜·血羽已死的证据，并打算将她的头颅悬挂在部落的补给商队中。他希望借此吓退幸存的巫翼鹰身人，让她们不敢再靠近旅人。",al={"为何取 塞瑞娜 的头颅","达索克 塞瑞娜 头颅","达索克 如何处置头颅"}},{q="塞瑞娜·血羽为什么袭击部落商队？",a="塞瑞娜·血羽袭击部落商队，是为了替被半食人魔勇士雷克萨杀死的姐妹报仇。她在贫瘠之地各处袭击部落的补给线和过往旅人。",al={"塞瑞娜 为何袭击商队","塞瑞娜·血羽 的动机","贫瘠之地鹰身人袭击"}},{q="这件战利品来自哪里？",a="这件战利品取自塞瑞娜·血羽，她是栖居在贫瘠之地西北尽头、无水岭峭壁间的鹰身人族母。",al={"哪里能找到塞瑞娜·血羽的头颅","塞瑞娜·血羽 的位置","如何取得 塞瑞娜 的头颅"}}},fp="13,176,21.411.1,47.194.0,53.175.1,33.126.0"}
P.entries["item:serpentbloom"] = {n="毒蛇花",s="毒蛇花是一种罕见的地下草药，只生长在哀嚎洞穴的幽暗深处。它强效的天然特性引起了被遗忘者的皇家药剂师学会的浓厚兴趣。",h="毒蛇花是一种罕见的地下草药，只生长在哀嚎洞穴的幽暗深处。它强效的天然特性引起了被遗忘者的皇家药剂师学会的浓厚兴趣。",kw={"药剂师扎玛","贫瘠之地","草药","皇家药剂师学会","毒蛇花","雷霆崖","哀嚎洞穴"},ang={["profession:Herbalism"]="受过训练的草药师目光敏锐，能在旁人眼中只有潮湿岩石的地方，找到这些罕见的洞穴花朵。",["race:Undead"]="获取毒蛇花能直接帮助药剂师扎玛和皇家药剂师学会，他们正在异域寻找能增强被遗忘者实力的植物资源。"},sec={{t="罕见的地下植物",b="毒蛇花只生长在贫瘠之地下方哀嚎洞穴潮湿阴暗的隧道中。这里的生态因失控的翡翠梦境能量而扭曲，这种植物扎根其中，在远离阳光的地方茁壮生长，茎叶间常有毒蛇筑巢。由于洞穴中遍布凶猛的野兽和堕落的德鲁伊，深入其中的人很少能带回可用的样本。"},{t="药剂师的关注",b="药剂师扎玛在雷霆崖下方的预见之池活动，代表幽暗城的皇家药剂师学会收集毒蛇花。被遗忘者不断在卡利姆多各地寻找剧毒、奇异且药性强烈的植物，为效力于黑暗女王的研究提供材料。扎玛相信，大量采集毒蛇花能为被遗忘者的炼金术研究带来宝贵的突破。"}},faq={{q="毒蛇花生长在哪里？",a="毒蛇花只生长在哀嚎洞穴深处，这片迷宫般的洞穴群位于贫瘠之地十字路口的西南方。它紧贴地面，生长在洞穴阴暗潮湿的隐蔽角落。",al={"哪里能找到毒蛇花","毒蛇花位置","哀嚎洞穴草药"}},{q="皇家药剂师学会为什么需要毒蛇花？",a="药剂师扎玛是皇家药剂师学会派驻雷霆崖的成员，正在寻找这种植物用于研究。被遗忘者研究来自卡利姆多各地的奇异危险植物，以研制新的化学药剂，并支持希尔瓦娜斯·风行者更广泛的目标。",al={"谁需要毒蛇花","药剂师扎玛草药","为什么收集毒蛇花"}},{q="采集毒蛇花为什么很危险？",a="哀嚎洞穴中遍布迅猛龙、鳄鱼和堕落的德鲁伊，除了这些常见的威胁，毒蛇花本身也经常藏有毒蛇。扰动植株往往会招致这些藏匿的毒蛇攻击。",al={"毒蛇花危险","毒蛇花毒蛇"}},{q="草药师能更容易地找到毒蛇花吗？",a="能。受过草药学训练的人善于察觉植物的踪迹，能够在洞穴地面的阴暗角落中追踪到成片的毒蛇花。",al={"草药学寻找毒蛇花","追踪毒蛇花"}}},fx={bee22cd2={q="毒蛇花是什么？",a="毒蛇花是一种极为罕见的植物，原生于贫瘠之地哀嚎洞穴最幽暗的深处。这种草药扎根于潮湿的地下区域，因其类似蛇类的特性而与众不同——惊扰它时，常会引出盘踞在根部周围的凶猛毒蛇。",al={"毒蛇花是什么","毒蛇花草药","毒蛇花介绍"}}},fp="12,133,25.327.0,19.368.0,29.186.0,56.295.0,41.163.0,45.131.0"}
P.entries["item:sethir-s-journal"] = {n="塞希尔的日记",s="在泰达希尔，塞希尔的日记是通过潜行取得的。日记中的记载证实，卡利姆多大陆上的腐化已经蔓延到了世界之树。",h="在泰达希尔，塞希尔的日记是通过潜行取得的。日记中的记载证实，卡利姆多大陆上的腐化已经蔓延到了世界之树。",kw={"黑海岸","命运的召唤","神谕林地","萨特","远古的塞希尔","塞希尔的日记","塞尤娜","泰达希尔"},ang={["class:Rogue"]="身为潜行者，你可以运用潜行和偷窃，在战士与外交使者失败的地方获取关键情报。",["race:NightElf"]="身为暗夜精灵，你面对的证据表明，泰达希尔也无法免受那股正在卡利姆多大陆上悄然蔓延的古老恶魔腐化的侵蚀。"},sec={{t="腐化的线索",b="泰达希尔的诞生承载着恢复精灵永生的希望，然而一种无形的病害已在它的枝桠间扎根。在达纳苏斯，塞尤娜怀疑远古的塞希尔掌握着答案。这个独居的萨特潜伏在神谕林地附近的一根外围树枝上。过去的斥候曾尝试交涉或正面进攻，却都丧了命，于是有人借助潜行和偷窃取得了塞希尔的日记。日记中的文字揭示，侵蚀海那边黑海岸森林与水域的神秘疫病，已经蔓延到了泰达希尔内部。"}},faq={{q="塞希尔的日记是什么？",a="塞希尔的日记由远古的塞希尔随身携带，他是一个充满敌意的萨特，住在泰达希尔神谕林地附近的外围枝桠间。日记详细记载了正在这一带蔓延的腐化。",al={"塞希尔的日记是什么","塞希尔 日记背景","塞希尔的日记属于谁"}},{q="如何取得这本日记？",a="过去与塞希尔交涉或交战的尝试，都以失败和死亡告终。必须借助潜行，从他的行囊中偷出日记。",al={"如何获得塞希尔的日记","哪里获得 塞希尔 的日记","偷窃 塞希尔"}},{q="日记揭示了什么？",a="潜行者训练师塞尤娜说，这本日记证明，侵蚀黑海岸森林与水域的怪病已经蔓延到了泰达希尔。",al={"塞希尔 的日记写了什么","塞希尔 的日记内容"}},{q="远古的塞希尔是谁？",a="远古的塞希尔是一个独居的萨特，栖身于神谕林地边缘一根僻静的树枝上。他以暴力对付闯入者，并掌握着有关世界之树上悄然蔓延的腐化的情报。",al={"塞希尔 是谁","远古的塞希尔"}}},fp="16,144,19.475.1,25.171.0,28.130.0,29.130.0,26.207.0"}
P.entries["item:sevren-s-orders"] = {n="塞弗伦的命令",s="在布瑞尔，执政官塞弗伦派遣一名久经考验的被遗忘者特工前往幽暗城。命令指示这名特工去魔法区找比索·埃斯沙德。",h="在布瑞尔，执政官塞弗伦派遣一名久经考验的被遗忘者特工前往幽暗城。命令指示这名特工去魔法区找比索·埃斯沙德。",kw={"比索·埃斯沙德","布瑞尔","魔法区","执政官塞弗伦","浪子巫妖","塞弗伦的命令","幽暗城"},ang={["class:Mage"]="身为法师，递送命令让你得以面见比索·埃斯沙德，他是被遗忘者王国最杰出的施法者之一。",["race:Undead"]="身为Undead，带着塞弗伦的印信，你将从在提瑞斯法当地效力，转而为幽暗城的奥术精英办事。"},sec={{t="都城的召令",b="随着被遗忘者巩固对洛丹伦的控制，那些在提瑞斯法林地对抗天灾军团、证明了自身实力的精干特工被召往南方。执政官塞弗伦写下命令，作为交给比索·埃斯沙德的介绍信和凭证，后者是黑暗女王麾下最杰出的奥术施法者之一，身在魔法区。塞弗伦只知道，这项任务涉及与一名离群的巫妖接触。幽暗城的高阶法师以全部权威支持这道召令。"}},faq={{q="这些命令是谁写的？",a="这些命令由执政官塞弗伦写下，他负责管理布瑞尔的被遗忘者事务。",al={"塞弗伦的命令的作者","塞弗伦是谁","谁交付塞弗伦的命令"}},{q="这些命令是交给谁的？",a="这些命令是写给比索·埃斯沙德的，他是幽暗城魔法区的一位被遗忘者高阶法师。",al={"谁接收命令","塞弗伦的命令送到哪里","比索·埃斯沙德是谁"}},{q="命令中提到的任务是什么？",a="命令要求招募一名离群的巫妖，为被遗忘者效力。这项危险的任务落在了一名已在对抗天灾军团时证明过自身实力的特工身上。",al={"巫妖任务是什么","比索想要什么","巫妖归顺任务"}},{q="为什么选我去送信？",a="比索要求派来一名在对抗天灾军团时证明过自身实力的特工。执政官塞弗伦认为，你在提瑞斯法林地的表现足以胜任比索提出的危险任务。",al={"为什么选我","塞弗伦为什么选我"}}},fp="15,150,22.460.0,23.76.0,40.107.0,44.139.0,33.157.0"}
P.entries["item:shadowhide-pendant"] = {n="暗皮坠饰",s="在赤脊山，与莫甘斯勾结的豺狼人之间流传着暗皮坠饰这种护符。湖畔镇收取十枚坠饰，作为当地法律得到执行的证明。",h="在赤脊山，与莫甘斯勾结的豺狼人之间流传着暗皮坠饰这种护符。湖畔镇收取十枚坠饰，作为当地法律得到执行的证明。",kw={"拜里弗·科纳彻尔","豺狼人","湖畔镇","范高雷中尉","莫甘斯","坠饰","赤脊山","暗皮","所罗门的律法"},ang={["class:Warrior"]="身为战士，你面对的是好勇斗狠、体格魁梧的暗皮豺狼人。他们的部队考验着守护通往湖畔镇道路的前线卫士。",["faction:Alliance"]="身为忠于联盟的冒险者，你可能会受命维护王国法律。湖畔镇这样的边疆定居点很少得到暴风城驻军的支援，因此当地镇长只能依靠你。"},sec={{t="反抗的信物",b="暗皮坠饰这种护符流传于暗皮的战士、蛮兵和施法者之间。在赤脊山的群山深处，这个氏族集结在范高雷中尉麾下，并受到了叛逆奥术施法者莫甘斯的操控。在湖畔镇居民眼中，这些粗陋的护符标志着一股有组织的威胁，他们替王室的敌人袭扰各处定居点。"},{t="湖畔镇的公正",b="所罗门镇长奉行的暴风城法律规定，主动协助王国已知罪犯者，处以死刑。王室援军人数不足，因此湖畔镇大厅的拜里弗·科纳彻尔依靠冒险者维持治安。十枚暗皮坠饰便能证明，听命于莫甘斯的豺狼人已经受到了边疆法律的制裁。"}},faq={{q="暗皮坠饰是什么？",a="暗皮坠饰是赤脊山的暗皮豺狼人氏族成员佩戴的一种粗陋护符。当地镇长收取这些坠饰，作为入侵的豺狼人已在保卫城镇的战斗中被击杀的证据。",al={"暗皮坠饰是什么","暗皮坠饰背景故事","赤脊山坠饰"}},{q="拜里弗·科纳彻尔为什么需要这些坠饰？",a="拜里弗·科纳彻尔收集这些坠饰，作为所罗门的律法得到执行的证明。暗皮氏族与叛逃巫师莫甘斯勾结，恐吓当地民众，因此镇上将所有隶属该氏族的豺狼人都视为应处以死刑的敌人。",al={"为什么收集坠饰","拜里弗·科纳彻尔悬赏","科纳彻尔任务"}},{q="谁携带这些坠饰？",a="普通的劫匪、蛮兵和狂暴的豺狼人都携带这些坠饰，赤脊山荒野中的沉默的罗恩和范高雷中尉等也不例外。",al={"谁掉落坠饰","哪些豺狼人有坠饰","暗皮坠饰来源"}},{q="暗皮氏族与莫甘斯是什么关系？",a="莫甘斯是盘踞在东部山麓的叛逆奥术施法者，他利用邪恶的力量迫使暗皮豺狼人服从自己的意志。他将这些豺狼人当作步兵，派去恐吓湖畔镇，推行自己的阴谋。",al={"豺狼人与莫甘斯","豺狼人为什么为莫甘斯效力","暗皮 摩根斯"}}},fp="18,127,18.341.0,19.340.0,29.212.0,46.256.0,27.145.0,66.218.0"}
P.entries["item:shaman-voodoo-charm"] = {n="萨满巫毒符咒",s="在班奈希尔兽穴中，瘤背萨满使用萨满巫毒符咒。它的邪恶魔法能将沉睡的德鲁伊的灵魂与肉体分离。",h="在班奈希尔兽穴中，瘤背萨满使用萨满巫毒符咒。它的邪恶魔法能将沉睡的德鲁伊的灵魂与肉体分离。",kw={"班奈希尔兽穴","翡翠梦境","熊怪","瘤背","奥本·怒爪","萨满巫毒符咒","沉睡的德鲁伊","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，你认为这种符咒是对神圣沉眠的可怕亵渎。它的黑暗魔法将梦者困在翡翠梦境中，把肉体变成傀儡。",["race:NightElf"]="身为暗夜精灵，你知道班奈希尔兽穴中的符咒揭示了瘤背对 kaldorei 最神圣的共同安眠之地之一的亵渎有多深。"},sec={{t="扭曲的魔法",b="泰达希尔的瘤背部族已陷入疯狂与腐化。在班奈希尔兽穴中，这个部族的萨满施展着超乎寻常荒野巫术的魔法。他们的巫毒咒符能将沉睡的德鲁伊的意识从凡间剥离，困在翡翠梦境之中。随后，熊怪会驱使那具失去灵魂的躯体行动。暗夜精灵的守护者就这样变成了没有心智的卫兵，杀死任何进入兽穴的人。"},{t="破解诅咒",b="奥本·怒爪成了这一仪式的受害者。他的灵魂被困在翡翠梦境中，而被魔法驱动的躯体则在兽穴深处肆虐。奥本穿透帷幕，请求冒险者杀死瘤背萨满，带回一枚他们的符咒。他希望研究符咒上的邪恶魔法，弄清熊怪扭曲的法术，找到解放自己那被夺走的肉身的方法。"}},faq={{q="萨满巫毒符咒有什么用途？",a="瘤背萨满用这种符咒将沉睡的德鲁伊的灵魂与肉体分离，并将灵魂困在翡翠梦境中。符咒的魔法会驱使失去灵魂的肉身攻击入侵者。",al={"巫毒咒符用途","符咒有什么作用","萨满符咒用途"}},{q="谁携带着这些符咒？",a="泰达希尔的班奈希尔兽穴深处，瘤背萨满携带着这些符咒。",al={"谁掉落符咒","哪里能找到萨满巫毒符咒","瘤背 萨满符咒"}},{q="奥本·怒爪为什么需要一枚符咒？",a="奥本·怒爪被困在翡翠梦境中，而他被魔法驱动的躯体却在四处肆虐。他需要研究符咒的邪恶气息与魔法，找到破解熊怪法术的方法。",al={"奥本 为什么想要符咒","奥本·怒爪符咒","沉睡的德鲁伊物品"}},{q="熊怪为什么会使用巫毒魔法？",a="腐化驱使泰达希尔的瘤背萨满修习黑暗魔法。他们的符咒散发着邪恶而反常的气息，与熊怪素来对自然之灵和元素的崇敬背道而驰。",al={"熊怪为什么使用巫毒","熊怪巫毒背景故事"}}},fp="19,134,17.393.0,20.378.1,41.170.0,25.89.0,32.180.0,34.204.0"}
P.entries["item:shard-of-water"] = {n="水灵碎片",s="在贫瘠之地的海岸上，水之先知伊斯伦从一位直面过腐化的萨满祭司手中接过水灵碎片。",h="在贫瘠之地的海岸上，水之先知伊斯伦从一位直面过腐化的萨满祭司手中接过水灵碎片。",kw={"贫瘠之地","水之召唤","水之先知伊斯伦","水灵碎片","银松森林","水之图腾"},ang={["class:Shaman"]="作为萨满祭司，获得碎片便意味着你已完成与水之灵的协调，也走完了获取水之图腾的漫长旅程。"},sec={{t="元素纯净的信物",b="萨满祭司必须理解平衡、生命与守护的意义，才能掌握水的力量。在水之召唤中，他们前往遭到腐化的泉水，甚至渡海来到饱受枯萎侵蚀的银松森林。净化被污染的水之后，萨满祭司便会获得水灵碎片。将这枚水晶信物带回贫瘠之地岩石遍布的海岸，交给水之先知伊斯伦，便能证明受试者的资格，并获得制作水之图腾的最后关键。"}},faq={{q="水灵碎片有什么用途？",a="你将碎片带给贫瘠之地东岸的水之先知伊斯伦，作为通过试炼的证明。交出碎片便能完成你与水的沟通，并获得水之图腾。",al={"水灵碎片用途","水灵碎片有什么用","为什么会有水灵碎片"}},{q="谁需要这件物品？",a="水之先知伊斯伦是一位萨满祭司，住在棘齿城以南、商旅海岸沿岸的一间小屋里，她要求你带来碎片，以确认你已净化了被污染的水。",al={"谁需要水灵碎片","水灵碎片在哪里交","水之先知伊斯伦碎片"}},{q="为什么要把试炼设在银松森林那么远的地方？",a="水意味着治愈与守护，而腐化会让生命停滞。银松森林被污染的水考验着你能否在深重的腐朽之中恢复元素的和谐。",al={"银松森林水任务","为什么是银松森林","萨满祭司银松森林"}}},fp="14,108,25.403.0,36.165.0,23.141.0,48.163.0"}
P.entries["item:shaw-s-report"] = {n="肖尔的报告",s="在西部荒野，肖尔的报告将SI:7的情报送到格里安·斯托曼手中。这份由马迪亚斯·肖尔撰写的报告，讲述了石匠行会、艾德温·范克里夫，以及暴风城重建后他们与王室之间的积怨。",h="在西部荒野，肖尔的报告将SI:7的情报送到格里安·斯托曼手中。这份由马迪亚斯·肖尔撰写的报告，讲述了石匠行会、艾德温·范克里夫，以及暴风城重建后他们与王室之间的积怨。",kw={"迪菲亚","艾德温·范克里夫","格里安·斯托曼","马迪亚斯·肖尔","肖尔的报告","si:7","石匠行会","西部荒野"},ang={["class:Rogue"]="肖尔的报告展现了马迪亚斯·肖尔的势力所及之广。他领导着暴风城的谍报网络SI:7。",["faction:Alliance"]="这份报告揭露了暴风城内部的腐败。王国拖欠建筑师们的报酬，助长了一场威胁王国农田的叛乱。"},sec={{t="关于石匠的情报",b="肖尔的报告从SI:7位于暴风城的秘密总部送抵哨兵岭。它让人民军首次清楚地了解到，究竟是谁在领导蹂躏西部荒野的匪徒。艾德温·范克里夫曾领导石匠行会，该公会的石匠在暴风城毁于第一次兽人战争后重建了这座城市。\n\n王室与贵族拒绝向他们支付公道的报酬，怨恨就此生根。肖尔的情报表明，这些流离失所的工匠与如今正席卷王国外围领土的叛乱有关。"}},faq={{q="肖尔的报告是什么？",a="肖尔的报告是马迪亚斯·肖尔为格里安·斯托曼准备的一份密封情报档案。肖尔领导着暴风城的秘密机构SI:7，报告中收录了王室掌握的有关石匠行会及艾德温·范克里夫过往的情报。",al={"肖尔的报告","肖尔写了什么","肖尔的报告内容"}},{q="报告揭示了艾德温·范克里夫的哪些事情？",a="报告指出，艾德温·范克里夫曾是石匠行会的首领。他在第一次兽人战争后主持了暴风城的重建工作，随后因王国统治者拒绝支付应得的报酬，与手下的工匠一同发动了叛乱。",al={"报告中的范克里夫","报告如何描述范克里夫"}},{q="格里安·斯托曼为什么需要这份报告？",a="格里安·斯托曼需要这份报告，因为他正率领人民军抵御西部荒野匪徒有组织的袭击。没有王国正规军的援助，他只能依靠马迪亚斯·肖尔的情报，查明是谁在指挥这些亡命之徒，以及他们的动机。",al={"为何把报告送给格里安","斯托曼为何需要报告"}},{q="斯托曼对报告有何反应？",a="这份报告令格里安·斯托曼深感不安。在他的记忆中，艾德温·范克里夫是一位勤勉而技艺精湛的工匠，没有更多证据，他很难相信这样一位受人尊敬的建筑师竟会沦为恶徒。",al={"格里安的反应","斯托曼的反应"}}},fx={c86c6e50={q="肖尔的报告来自哪里，是谁写的？",a="这份报告由暴风城情报机构SI:7的首领马迪亚斯·肖尔起草。肖尔在旧城区的总部工作，将SI:7收集到的有关石匠行会历史和艾德温·范克里夫的情报汇编成文，准备送回哨兵岭，交给格里安·斯托曼。",al={"谁写了肖尔的报告","谁制作了肖尔的报告","肖尔的报告来自哪里"}}},fp="13,221,31.491.1,22.250.0,49.224.0,44.254.0,41.211.0"}
P.entries["item:shimmering-frond"] = {n="发光的树叶",s="在神谕林地，一株奇异的植物散发着扭动闪烁的光晕。它的叶片属于一种原生于悲伤沼泽的植物，故乡远在无尽之海的另一边。",h="在神谕林地，一株奇异的植物散发着扭动闪烁的光晕。它的叶片属于一种原生于悲伤沼泽的植物，故乡远在无尽之海的另一边。",kw={"植物学","德纳兰","奥拉密斯湖","神谕林地","发光的树叶","长着叶片的奇异植物","悲伤沼泽","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，你或许会觉得，一株外来的沼泽植物竟在泰达希尔新近隆起的枝干上茁壮生长，实在是件奇事。",["profession:Herbalism"]="身为草药师，你能体会到，一株悲伤沼泽的植物要跨越海洋，在异乡的土壤中茁壮生长，需要多么罕见的生命力。"},sec={{t="远方的标本",b="神谕林地附近的树木间，生长着一株光芒四射的植物。它的光晕不断脉动，叶片在林间的光线下闪闪发亮。德纳兰在奥拉密斯湖畔照料种植盆，他认出这些叶片属于东部王国悲伤沼泽的一种植物。那片遥远沼泽中的种子如何跨越无尽之海，在泰达希尔扎根，至今仍是个谜。德纳兰正在自己的土壤中培育标本，以便研究。"}},faq={{q="发光的树叶来自哪里？",a="你可以从泰达希尔神谕林地的一株奇异植物上采集到这片树叶。它的叶片在林间的光线下闪烁，散发着扭动、脉动的光芒。",al={"发光的树叶获取地点","发光的树叶位置","长着叶片的奇异植物"}},{q="谁对发光的树叶感兴趣？",a="德纳兰是一位在奥拉密斯湖畔开展植物研究的暗夜精灵博物学家，他想检查这片树叶。他对泰达希尔各处扎根的奇异植物很感兴趣。",al={"谁需要发光的树叶","发光的树叶交给谁","德纳兰发光的树叶"}},{q="这株植物在泰达希尔为何如此不同寻常？",a="这株植物来自东部王国的悲伤沼泽，那里远在无尽之海的另一边。它出现在泰达希尔令人意外，因为它既非卡利姆多的原生植物，也非世界之树的原生植物。",al={"发光的树叶为何特殊","植物来源","悲伤沼泽植物"}},{q="把树叶交给德纳兰之后会发生什么？",a="德纳兰将标本栽种在奥拉密斯湖畔的种植盆中。他会测试它的快速生长能力和奇异特性。",al={"德纳兰如何处理树叶","萌发的树叶背景故事"}}},fp="16,152,20.421.0,42.151.0,42.139.0,47.183.0,47.116.0"}
P.entries["item:shimmerweed"] = {n="微光草",s="在闪光岭，霜鬃巨魔采集微光草，用于他们的仪式。烈酒村的雷杰德·麦酒想在自己的烈性啤酒中试试它的辛烈风味。",h="在闪光岭，霜鬃巨魔采集微光草，用于他们的仪式。烈酒村的雷杰德·麦酒想在自己的烈性啤酒中试试它的辛烈风味。",kw={"烈酒村","丹莫罗","霜鬃","完美的烈性啤酒","雷杰德·麦酒","闪光岭","微光草"},ang={["profession:Herbalism"]="身为草药师，你能看出各地的植物如何被用于当地的酿酒传统和仪式炼金术。",["race:Dwarf"]="身为矮人，你能看出巧思如何将附近峭壁上的一种奇异植物变成酿酒实验的材料。"},sec={{t="巨魔的作物",b="在丹莫罗低地上方的高处，霜鬃巨魔在闪光岭冰封的峭壁上种植微光草。他们收割这种植物，存放在遍布营地的编织篮中。在那里，它被用于神圣的仪式。除了巨魔，很少有登山者会留意这种草药，不过一些富有创意的外来者已经对它产生了兴趣。"},{t="秘密配料",b="在烈酒村，酿酒大师雷杰德·麦酒怀疑，微光草或许就是他酿造终极矮人烈性啤酒时缺少的那味配料。他已经察觉到这种草药辛烈而鲜明的风味，想把它放进发酵桶里试试。于是，雷杰德雇用旅人潜入霜鬃营地，避开充满敌意的巨魔，带回成筐的草药。"}},faq={{q="微光草生长在哪里？",a="微光草生长在闪光岭，那是丹莫罗境内、烈酒村西北方一处冰封的高地。霜鬃巨魔种植这种植物，并将采集来的草药存放在营地各处的篮子里。",al={"微光草位置","哪里能找到微光草","闪光岭植物"}},{q="霜鬃巨魔用微光草做什么？",a="霜鬃巨魔在神秘的部族仪式和典礼中使用微光草。外来者并不清楚其中的具体细节，但在闪光岭，这种草药在他们的文化与精神活动中占有一席之地。",al={"巨魔使用微光草的用途","巨魔为什么想要微光草"}},{q="雷杰德·麦酒为什么想要微光草？",a="雷杰德·麦酒想用微光草在烈酒村酿造出完美的矮人烈性啤酒。他已经察觉到它独特的味道，希望新采来的成筐草药能为试酿的麦芽醪带来配方所需的浓烈风味。",al={"雷杰德·麦酒任务","谁想要微光草","为什么用微光草酿酒"}},{q="丹莫罗以外的地方也生长着微光草吗？",a="在杜隆塔尔这样的干旱地区，也有人采集过微光草，德雷克塔尔等先知看重它，会用它调制强效草药合剂和药剂。这种植物也生长在卡兹莫丹冰封的群峰之外。",al={"杜隆塔尔微光草","丹莫罗以外的微光草"}}},fx={["1978b4f9"]={q="闪光草是什么？",a="闪光草是一种独特的植物，由霜鬃巨魔栽培在丹莫罗高处的雪地里，尤其常见于闪光岭一带。这种草药以奇特的风味和特性著称，巨魔将其采集后装入篮中，用于当地的部族仪式，而近来，一些雄心勃勃的矮人酿酒师也对它产生了兴趣，想在试酿的麦酒中检验它的强劲效力。",al={"微光草是什么","微光草植物","关于微光草"}},d2fd1cd1={q="闪光草来自哪里，是谁培育的？",a="闪光草是丹莫罗的霜鬃巨魔栽培的天然植物，他们在闪光岭上照料这种植物，收获后装入篮中。霜鬃巨魔种植它是为了举行自己的仪式，而这种强效草药的野生品种也生长在杜隆塔尔等遥远的土地上，当地荒野中的草药师和萨满祭司很看重它的药水酿制价值。",al={"微光草来自哪里","谁培育了微光草","微光草的来源"}}},fp="11,155,15.319.0,19.352.0,28.175.0,49.209.0,44.230.0,50.210.0"}
P.entries["item:shindrell-s-note"] = {n="辛德瑞尔的便笺",s="在阿斯特兰纳，辛德瑞尔·速火写下一封信，报告城镇附近及灰谷沿海的腐化迹象。她将这份情报送往森林东部，交给凯尼斯·静风。",h="在阿斯特兰纳，辛德瑞尔·速火写下一封信，报告城镇附近及灰谷沿海的腐化迹象。她将这份情报送往森林东部，交给凯尼斯·静风。",kw={"灰谷","阿斯特兰纳","林歌神殿","凯尼斯·静风","夜歌森林","辛德瑞尔·速火","辛德瑞尔的便笺"},ang={["class:Druid"]="辛德瑞尔的观察帮助凯尼斯·静风和其他德鲁伊追查困扰灰谷的异常枯萎现象的根源。",["race:NightElf"]="这封信展现了守卫灰谷聚居地的Sentinels如何与研究森林病害的塞纳里奥德鲁伊协作。"},sec={{t="穿越森林的信函",b="随着动荡在森林中蔓延，哨兵与德鲁伊协力监视灰谷的边界。在阿斯特兰纳，哨兵辛德瑞尔·速火写下了西部海岸和中部林冠间令人不安的异动。她将报告寄给凯尼斯·静风，他是一位德鲁伊，驻守在东部夜歌森林的林歌神殿。信使们带着辛德瑞尔亲眼所见的情况，协助凯尼斯调查逐渐侵入神圣林地的腐化。"}},faq={{q="辛德瑞尔的便笺是什么？",a="哨兵辛德瑞尔·速火的实地报告描述了阿斯特兰纳附近及灰谷沿海的异动与疑似腐化的迹象。",al={"这张便笺是什么","辛德瑞尔的便笺","便笺写了什么"}},{q="这张便笺要交给谁？",a="这张便笺是写给凯尼斯·静风的，他是一位暗夜精灵德鲁伊，驻守在灰谷东部夜歌森林的林歌神殿。",al={"交给谁","送到哪里","便笺是给谁的"}},{q="为什么要写这张便笺？",a="凯尼斯·静风担心腐化正在西部森林扎根，因此要求收集那里的异常事件报告。辛德瑞尔汇总了自己的见闻，帮助他判断威胁。",al={"为什么写便笺","辛德瑞尔说的是什么腐化","报告的用途"}},{q="辛德瑞尔·速火住在哪里？",a="辛德瑞尔·速火是一位暗夜精灵哨兵，驻守在灰谷中部的聚居地阿斯特兰纳。",al={"辛德瑞尔在哪里","辛德瑞尔·速火的位置","谁寄来的"}}},fx={ed6c40b2={q="辛德瑞尔的便笺来自哪里？是谁写的？",a="这份便笺由哨兵辛德瑞尔·速火在阿斯特兰纳写下。它是一份正式的实地报告，详细记述了她在灰谷海岸沿线及周围林地观察到的令人不安的事件。",al={"谁写了辛德瑞尔的便笺","谁制作了辛德瑞尔的便笺","辛德瑞尔便笺的来源"}}},fp="16,162,26.450.0,25.139.0,33.121.0,25.183.0,38.102.0"}
P.entries["item:shipment-of-boots"] = {n="一箱靴子",s="在贫瘠之地沿岸，一箱靴子就放在棘齿城以南的南海营地里。崔斯里克从藏宝海湾寄出这箱货物，供加兹鲁维的贸易网络使用，但海盗在货物抵港前就将它劫走了。",h="在贫瘠之地沿岸，一箱靴子就放在棘齿城以南的南海营地里。崔斯里克从藏宝海湾寄出这箱货物，供加兹鲁维的贸易网络使用，但海盗在货物抵港前就将它劫走了。",kw={"藏宝海湾","崔斯里克","加兹鲁维","棘齿城","一箱靴子","南海海盗","被盗的赃物"},ang={["class:Rogue"]="身为潜行者，你可以悄悄穿过沿岸的南海营地。那里的海盗巡逻十分密集，因此，悄然潜入是夺回加兹鲁维被劫货物最安全的办法。"},sec={{t="遭劫的货物",b="加兹鲁维安排藏宝海湾的服装商人崔斯里克向棘齿城运送靴子。在商旅海岸巡逻的南海海盗伏击了货船，将货箱搬到了港口以南的海滩营地。他们把赃物分散藏在帐篷和棚屋之间，这批货物至今仍在那里，远离棘齿城的码头。"}},faq={{q="这批靴子是谁寄出的？",a="藏宝海湾的地精商人崔斯里克从这座南方港口寄出了这批靴子。",al={"靴子是谁做的","靴子从哪里来","崔斯里克的靴子"}},{q="这批靴子原本该由谁接收？",a="加兹鲁维为棘齿城订购了这批靴子。他是那里的首席工程师兼管理者，这批货物原本是为了满足当地工人的需要，并支持他的贸易。",al={"靴子属于谁","加兹鲁维的靴子货物"}},{q="这批靴子怎么落到了海盗手里？",a="南海海盗在贫瘠之地沿岸伏击了货船，洗劫船上的货物，并将货箱搬到了棘齿城以南的营地。",al={"南海海盗为什么有靴子","谁偷了靴子"}},{q="在哪里能找到这批货物？",a="这批货物就在棘齿城以南沿岸的南海海盗营地里，混在他们劫掠来的货物之中。",al={"靴子的位置","一箱靴子在哪里","寻找靴子货物"}}},fp="17,211,17.348.0,32.80.0,38.152.0,42.149.0,32.107.0"}
P.entries["item:shipment-of-iron"] = {n="一箱铁材",s="在希尔斯布莱德农场，一箱生铁存放在人类的铁匠铺里。这批金属支撑着当地的武器生产，因此成了被遗忘者部队的目标，他们试图切断为镇民供应武器的补给线。",h="在希尔斯布莱德农场，一箱生铁存放在人类的铁匠铺里。这批金属支撑着当地的武器生产，因此成了被遗忘者部队的目标，他们试图切断为镇民供应武器的补给线。",kw={"战斗 希尔斯布莱德","达萨利亚","希尔斯布莱德农场","一箱铁材","塔伦米尔","维林坦"},ang={["faction:Horde"]="作为部落的一员，在战役转向南海镇之前，切断希尔斯布莱德的补给能削弱农民的武装抵抗。",["profession:Blacksmithing"]="对铁匠来说，生铁维系着山谷中人类的武器生产。没有铁锭，Verringtan的熔炉就只能闲置。"},sec={{t="为抵抗提供支撑",b="在希尔斯布莱德丘陵各地，人类农民对塔伦米尔展开了顽强的抵抗。他们的力量很大程度上来自希尔斯布莱德农场西南边缘的铁匠铺，铁匠维林坦和他的学徒在那里日夜赶工，用大批运来的铁材打造武器和护甲。被遗忘者指挥官下令熄灭炉火、杀死铁匠，并夺取储存的金属，用于部落的战事，希望借此摧毁农民的抵抗意志。"}},faq={{q="一箱铁材存放在哪里？",a="这批铁材存放在希尔斯布莱德农场西南边缘的铁匠作坊内。铁匠维林坦和他的学徒严密看守着它。",al={"一箱铁材位置","铁材在哪里","希尔斯布莱德铁材位置"}},{q="被遗忘者为什么想要这批铁材？",a="这批铁材用于武装当地的人类民兵，被遗忘者想要切断这条补给线。高级执行官达萨利亚还打算在攻势转向夷平南海镇时，将这些储备投入部落的战争机器。",al={"为什么偷铁材","塔伦米尔铁材","战斗 希尔斯布莱德铁材用途"}},{q="最初是谁在使用这批铁材？",a="铁匠维林坦和他的四名铁匠学徒用这些铁材武装镇民和农场工人，将普通农民变成了抵抗亡灵的地方防卫力量。",al={"铁材归谁所有","维林坦铁材","希尔斯布莱德铁匠"}},{q="是谁下令取回一箱铁材的？",a="高级执行官达萨利亚在塔伦米尔指挥被遗忘者的行动，她在战斗希尔斯布莱德期间下令杀死铁匠并夺取铁材。",al={"谁发布任务","达萨利亚铁材任务"}}},fx={["8a003d21"]={q="一箱铁材是什么？",a="一箱铁材是存放在希尔斯布莱德农场人类铁匠铺中的一批原料金属。它是铁匠维林坦和他的学徒锻造武器与护甲的主要材料，这些装备供当地抵抗被遗忘者的希尔斯布莱德居民使用。",al={"一箱铁材是什么","一箱铁材","希尔斯布莱德的铁材货物"}}},fp="16,106,22.445.0,35.153.0,37.217.0,35.182.0,46.154.0"}
P.entries["item:shipping-schedule"] = {n="Shipping Schedule",s="在杰罗德码头，迪菲亚潜行者沿着艾尔文的水路运送违禁品。他们的码头管理员守着一份记录赤脊山与西部荒野之间货运往来的日程表，SI:7 想要得到它。",h="在杰罗德码头，迪菲亚潜行者沿着艾尔文的水路运送违禁品。他们的码头管理员守着一份记录赤脊山与西部荒野之间货运往来的日程表，SI:7 想要得到它。",kw={"迪菲亚","码头管理员","艾尔文森林","杰罗德码头","马迪亚斯·肖尔","船运时间表","si:7","走私"},ang={["class:Rogue"]="作为一名盗贼，你可以从码头管理员的口袋里偷走日程表，检验自己的潜行和扒窃本领，看看是否达到 SI:7 对有意加入的特工的要求。"},sec={{t="杰罗德码头的走私活动",b="杰罗德码头位于闪金镇以南，坐落在 纳菲瑞提河 的艾尔文一侧河岸。迪菲亚潜行者夺取了这里，将其作为河运枢纽。他们从这里出发，沿着水路在赤脊山与西部荒野之间运送违禁品，避开暴风城卫队的耳目。他们的码头管理员将船运时间表随身保管，上面记载着每一批货物。"},{t="SI:7 的目标",b="马迪亚斯·肖尔领导着暴风城的情报机构 SI:7，并下令窃取这份日程表。它能揭示迪菲亚的补给路线，窃取它也能考验新特工。这次行窃必须在码头小屋内进行，从码头管理员的口袋里偷走日程表。如果特工被抓，SI:7 会否认与其有任何关联。不能留下任何线索，让人追查到其位于暴风城的营房。"}},faq={{q="船运时间表是什么？",a="船运时间表记载着杰罗德码头的迪菲亚潜行者码头管理员经手的违禁品货运。它记录了经由艾尔文森林内陆水路，在赤脊山与西部荒野之间运送的货物。",al={"迪菲亚船运时间表","这是什么文件","码头管理员日程表"}},{q="谁想要取回这份日程表？",a="SI:7 的首领马迪亚斯·肖尔想要取回这份日程表。他借此追踪迪菲亚的走私活动，并在实地考验有潜力的盗贼。",al={"谁需要日程表","马迪亚斯·肖尔 日程表","谁拿走 船运时间表"}},{q="在哪里能找到日程表？",a="迪菲亚码头主管在杰罗德码头的码头小屋内随身携带着日程表。码头位于艾尔文森林闪金镇以南的 纳菲瑞提河 河畔，必须在那里从他身上取得这份文件。",al={"船运时间表 位置","码头管理员在哪里","如何获得日程表"}},{q="杰罗德码头有什么用途？",a="迪菲亚潜行者夺取了杰罗德码头，将其作为走私中转站。这里的河道将他们在赤脊山的行动与西部荒野的据点连接起来。",al={"杰罗德码头 迪菲亚","迪菲亚 为什么占据杰罗德码头","迪菲亚 码头 艾尔文"}}},fx={["45ccd8c3"]={q="船运时间表来自哪里，是谁编写的？",a="这份时间表由迪菲亚潜行者驻守在闪金镇以南杰罗德码头的码头管理员保管。它详细记录了这个不法团伙的河运活动，追踪在赤脊山和西部荒野之间走私的非法货物与违禁品的流向。",al={"谁编写了船运时间表","船运时间表的来源","谁编写了迪菲亚船运时间表"}}},fp="17,181,28.335.0,25.350.0,30.208.0,34.141.0,28.208.0,33.167.0"}
P.entries["item:sida-s-bag"] = {n="塞达的背包",s="在湿地，塞达的背包被铁须之墓附近的一只软泥怪吞进了体内。塞达是米奈希尔港的居民，每周都会前去探访；一次，她把背包扔向一只软泥怪后逃走了，背包和里面的物品都得从这些满身酸液的生物体内找回来。",h="在湿地，塞达的背包被铁须之墓附近的一只软泥怪吞进了体内。塞达是米奈希尔港的居民，每周都会前去探访；一次，她把背包扔向一只软泥怪后逃走了，背包和里面的物品都得从这些满身酸液的生物体内找回来。",kw={"丹莫德","铁须之墓","米奈希尔港","软泥怪","塞达","塞达的背包","湿地"},ang={["faction:Alliance"]="米奈希尔港饱受困扰的难民和镇民，依靠过往的旅人对付那些从洪水泛滥的湿地悄然逼近、四处捕食的可怕生物。"},sec={{t="惊慌中的自卫",b="塞达每周都会前往丹莫德附近的铁须之墓。可怕的软泥怪浑身滴着黏液，在那里伏击了她，惊慌之下，她把背包扔向了其中一只。那只软泥怪将背包吸进了体内。这一举动分散了软泥怪的注意，让塞达得以活着逃回米奈希尔港，而她的财物却困在了某只不知名的软泥怪体内。"},{t="从软泥中寻回",b="铁须之墓周围的软泥怪，有的通体赤红，有的体形巨大，看上去却都差不多。不断击杀沼泽中的软泥怪，直到被吞下的背包完好地显露出来，就能找到塞达的背包。酸性污泥浸透了这个结实的袋子，但里面的物品仍保存完好。塞达取回自己的东西，随后丢开那层破损、沾满软泥的外皮，把洗得褪了色的袋子送给替她勇闯沼泽的人。"}},faq={{q="塞达的背包为什么会在软泥怪体内？",a="塞达探访铁须之墓时，遭到浑身滴着黏液的软泥怪袭击，顿时惊慌失措。为了逃命，她把背包扔向其中一只，结果被它整个吞了下去。",al={"软泥怪怎么吞下背包的","背包为什么在软泥怪体内","塞达怎么丢的背包"}},{q="哪些软泥怪身上有塞达的背包？",a="塞达分不清那些软泥怪，所以湿地东北部铁须之墓周围任何一只四处捕食的软泥怪，都可能吞下了背包。深红软泥怪、黑色软泥怪和巨型软泥怪都在那里游荡。",al={"哪里能找到塞达的背包","什么掉落塞达的背包","哪只软泥怪有背包"}},{q="塞达为什么要探访铁须之墓？",a="塞达每周都会从米奈希尔港出发，前往丹莫德附近那座古老的矮人墓穴。她从不向别人透露这些探访背后的私人缘由。",al={"塞达与铁须的关系","为什么去铁须之墓"}},{q="塞达的背包里装着什么？",a="塞达把找回的物品倒在地上，又收拢起来，没有让人看清究竟是什么。她只说，这些东西太重要了，绝不能任由它们在软泥怪体内溶解。",al={"塞达从背包里拿出了什么","背包里的物品"}}},fx={["113113dd"]={q="塞达的背包是什么？",a="塞达的背包是居住在米奈希尔港的塞达的私人背包。她照常前往湿地的铁须之墓时遭到软泥怪袭击，慌乱逃跑之际把背包扔向其中一只软泥怪。那只软泥怪将背包整个吞下，背包就此困在它胶状的身体里。",al={"塞达的背包是什么","塞达的背包","谁是塞达的背包"}},afbd2451={q="塞达为什么想要拿回她的背包？",a="塞达急需的是丢失背包里锁着的东西，而不是背包本身。你从铁须之墓的软泥怪残骸中把背包撬出来并交还给米奈希尔港的塞达后，她会立刻把沾满黏液的东西倒在地上，捡起里面的物品，再把空背包还给你。",al={"塞达为什么想要她的背包","塞达的背包为什么","为什么有人想要塞达的背包"}}},fp="10,224,18.300.0,24.369.0,34.160.0,29.204.0,37.154.0,27.179.0"}
P.entries["item:signed-recruitment-letter"] = {n="签过字的募兵信",s="卡加尔·战痕从前沿哨所向西送出签过字的募兵信。他的签章指示新兵前往十字路口报到服役。",h="卡加尔·战痕从前沿哨所向西送出签过字的募兵信。他的签章指示新兵前往十字路口报到服役。",kw={"征兵","十字路口","前沿哨所","卡加尔·战痕","瑟格拉·黑棘","签过字的募兵信","贫瘠之地","萨尔"},ang={["class:Shaman"]="身为萨满祭司，你要向瑟格拉·黑棘报到，这位兽人萨满祭司受萨尔之托，协助保卫贫瘠之地。",["faction:Horde"]="身为部落的一员，你带着这封信，结束在杜隆塔尔的基础服役，加入部落更广阔的边疆部队。"},sec={{t="应征者的调遣",b="在前沿哨所，卡加尔·战痕为新兵前往贫瘠之地服役做准备。哨所位于怒水河东岸，新兵从杜隆塔尔渡河而来。当应征者向卡加尔证明自己已准备就绪时，他就会在介绍信上盖章签字。命令要求新兵沿路向西前往十字路口。在那里，瑟格拉·黑棘负责协调物资供应和这片干旱平原的防务。"},{t="哨所间的嫌隙",b="卡加尔的命令中流露出他对那位等待新兵报到的军官的轻蔑。他称瑟格拉·黑棘是个尖酸刻薄的萨满祭司，总对士兵说些绕来绕去的话。卡加尔公开质疑大酋长萨尔为何如此器重她。即便如此，这封公函仍必须送到瑟格拉手中，新兵才能在十字路口获得后续任务。"}},faq={{q="签过字的募兵信有什么用途？",a="签过字的募兵信将你从前沿哨所的卡加尔·战痕麾下调往贫瘠之地服役。它向十字路口的瑟格拉·黑棘证明，卡加尔认为你已准备就绪。",al={"这封信有什么用","募兵信用途","签过字的信 贫瘠之地"}},{q="是谁在信上签的字？",a="卡加尔·战痕在信上签字。这位兽人老兵负责管理杜隆塔尔与贫瘠之地交界处的前沿哨所，在新兵完成那里的初步任务后，他便会签字。",al={"谁写的信","卡加尔的信","谁签的字"}},{q="我该把信交给谁？",a="你要把信交给瑟格拉·黑棘，她是一位颇有影响力的兽人萨满祭司，驻守在十字路口中央的交叉路口。",al={"信送到哪里","信交给谁","收信人"}},{q="卡加尔为什么对瑟格拉·黑棘出言不逊？",a="卡加尔说瑟格拉言辞尖刻、难以相处，认为她在有活要干时还在浪费时间说话。大酋长萨尔十分器重她，但卡加尔怀疑她的领导能力。",al={"卡加尔与 瑟格拉 的不和","卡加尔为什么讨厌 瑟格拉"}}},fp="25,164,22.389.0,23.320.0,53.190.0,22.183.0,31.120.0,49.182.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="异种蝎卵",s="巨人旷野各处的土壤下都埋藏着异种蝎卵。部落研究者收集这些卵，以了解正在贫瘠之地南部扩散的虫群。",h="巨人旷野各处的土壤下都埋藏着异种蝎卵。部落研究者收集这些卵，以了解正在贫瘠之地南部扩散的虫群。",kw={"十字路口","掘地铲","寻卵","巨人旷野","科兰","土丘","异种蝎","异种蝎卵","贫瘠之地"},ang={["faction:Horde"]="对部落而言，十字路口附近这些拥有智慧的虫群威胁着卡利姆多中部的商路与领土。"},sec={{t="神秘虫群",b="巨人旷野上隆起了 异种蝎 的土丘，怪异的虫形生物在其中翻动泥土。它们的卵埋在坚硬的土壤下，由领地意识强烈的 异种蝎 守护。部落对这些生物知之甚少，但十字路口的斥候发现，它们表现出的协作能力和智慧超出了普通野兽。尚未孵化的卵或许能帮助奥格瑞玛的学者了解 异种蝎 的生命周期与天性。"},{t="挖掘与危险",b="异种蝎卵必须用经过改装的掘地铲从土丘中挖出。这些生物会拼死保卫地下的育幼巢穴，成群袭击任何威胁到未孵化幼体的人。巨魔研究者科兰需要完整的样本进行研究，赶在虫群向卡利姆多更远处扩散之前。"}},faq={{q="什么是异种蝎卵？",a="异种蝎卵是一窝窝尚未孵化的卵，埋藏在贫瘠之地南部的土丘中，尤其集中在巨人旷野一带。",al={"异种蝎卵","什么是异种蝎卵","异种虫 土丘"}},{q="谁需要收集这些卵？",a="十字路口的巨魔研究者科兰为他在奥格瑞玛的上级收集这些卵，他们希望研究 异种蝎 的生理与行为。",al={"谁需要虫卵","科兰任务","寻卵任务给予者"}},{q="为什么要研究 异种蝎？",a="部落对 异种蝎 知之甚少。科兰发现它们表现出的智慧和协作能力超出了寻常野兽，而这些生物在贫瘠之地的出现令部落领袖忧心忡忡。",al={"为何研究 异种虫","异种虫 威胁","异种虫 有智慧吗"}},{q="如何收集这些卵？",a="收集者用经过改装的掘地铲从 异种蝎 的土丘中撬出虫卵，而凶猛的虫群会奋力保卫巢穴。",al={"如何获取虫卵","掘地铲","采集异种蝎卵"}}},fp="26,168,18.405.0,21.294.0,23.125.0,31.142.0,35.191.0,26.96.0"}
P.entries["item:silixiz-s-tower-key"] = {n="希里克斯的塔楼钥匙",s="工头希里克斯随身带着淤泥沼泽附近荆棘谷地精塔楼的钥匙。碎手氏族的特工必须从他口袋里偷走钥匙，这是秘密破坏任务的一部分。",h="工头希里克斯随身带着淤泥沼泽附近荆棘谷地精塔楼的钥匙。碎手氏族的特工必须从他口袋里偷走钥匙，这是秘密破坏任务的一部分。",kw={"贫瘠之地","工头希里克斯","碎手氏族","申苏尔","希里克斯","淤泥沼泽","塔楼钥匙","荆棘谷地精"},ang={["class:Rogue"]="作为部落盗贼，取得希里克斯的塔楼钥匙是加入碎手氏族的考验。这需要熟练掌握潜行和偷窃。",["faction:Horde"]="作为部落的一员，你携带的这件战利品，与反抗荆棘谷地精在贫瘠之地北部的掠夺和化学实验有关。"},sec={{t="潜行的考验",b="淤泥沼泽以北，荆棘谷地精的塔楼戒备森严。总工头普兹克·加里维克斯掌管着这座孤立的哨塔，地精雇佣兵则在院内巡逻。塔楼外，工头希里克斯随身带着塔楼钥匙。一名来自奥格瑞玛的碎手氏族特工必须偷走并保管好这把钥匙。蛮力无济于事：特工必须悄然潜入，从希里克斯的口袋里偷取钥匙，证明自己的潜行本领，然后才能登上毒气弥漫的塔楼上层。"}},faq={{q="在哪里能找到工头希里克斯？",a="工头希里克斯就在荆棘谷地精的塔楼外，位于贫瘠之地东北部、淤泥沼泽正北方。",al={"希里克斯位置","工头希里克斯在哪里","寻找希里克斯"}},{q="杀死工头希里克斯能拿到钥匙吗？",a="不能。无法从希里克斯的尸体上取得钥匙。特工必须在他活着时从他口袋里偷取。",al={"希里克斯钥匙掉落","能否杀死希里克斯","拾取希里克斯钥匙"}},{q="谁需要这把钥匙？",a="碎手氏族的联络人要求将钥匙交给申苏尔，他是奥格瑞玛的盗贼训练师。",al={"谁需要钥匙","交付希里克斯钥匙","希里克斯的塔楼钥匙任务"}},{q="这把钥匙有什么用？",a="这把钥匙证明特工潜入过淤泥沼泽附近荆棘谷地精的塔楼。它要与总工头普兹克·加里维克斯的头颅和赞吉尔的改良药剂一起交给碎手氏族。",al={"希里克斯钥匙能打开什么","希里克斯钥匙用途","使用塔楼钥匙"}}},fp="19,195,18.451.0,32.115.0,48.103.0,22.94.0,25.198.1"}
P.entries["item:silver-dawning-s-lockbox"] = {n="银色清晨号的保险箱",s="黑海岸近海，一艘被沿海鱼人击沉的船只残骸中，躺着银色清晨号的保险箱。箱中装着遇难船长的私人物品和航海日志。",h="黑海岸近海，一艘被沿海鱼人击沉的船只残骸中，躺着银色清晨号的保险箱。箱中装着遇难船长的私人物品和航海日志。",kw={"奥伯丁","黑海岸","高尔博德·钢手","保险箱","鱼人","沉船","银色清晨号"},ang={["race:Dwarf"]="高尔博德·钢手主动承担起悼念遇难船长的责任，将他们的遗物归还给幸存的船员。",["race:NightElf"]="保险箱保存着一位 kaldorei 船长最后的文字和遗物，这位船长在卡利姆多北部近海保卫自己的船只时遇难。"},sec={{t="海底遗物",b="银色清晨号横渡大海驶向奥伯丁时，遭到了沿海鱼人的袭击。鱼人在港口以北击沉了这艘船，船长也在袭击中丧生。灌满海水的船体内仍存放着船长的私人保险箱，里面装着航海日志和私人物品。找回这些遗物，或许能让岸上幸存的船员得到最后一丝慰藉。"}},faq={{q="银色清晨号的保险箱在哪里？",a="保险箱就在银色清晨号翻覆沉没的残骸内，位于黑海岸近海、奥伯丁以北的海底。",al={"保险箱位置","银色清晨号 的箱子在哪","银色清晨号 残骸"}},{q="银色清晨号遭遇了什么？",a="银色清晨号驶向奥伯丁时，遭到了沿海鱼人的伏击。鱼人攻陷了这艘船，船只连同船长一起沉入了海中。",al={"银色清晨号 为何沉没","银色清晨号 背景故事","船如何失事"}},{q="保险箱里有什么？",a="保险箱里装着银色清晨号船长的私人物品和航海日志。",al={"银色清晨号 箱内物品","箱子里有什么"}},{q="谁在寻找保险箱？",a="驻守奥伯丁的矮人高尔博德·钢手请会游泳的人从沉船残骸中取回保险箱，好让遇难船长幸存的船员缅怀船长。",al={"谁要保险箱","谁给任务","交还保险箱"}}},fp="24,179,15.344.0,46.130.0,36.149.0,27.76.0,27.167.0"}
P.entries["item:silvery-spinnerets"] = {n="银色丝囊",s="银色丝囊取自泰达希尔北部涌泉湖附近的萨丝拉。她的银色蛛网曾为月神殿收集具有治疗功效的晚露。艾露恩姐妹会寻求这些丝囊，用于举行纪念她灵魂的神圣仪式。",h="银色丝囊取自泰达希尔北部涌泉湖附近的萨丝拉。她的银色蛛网曾为月神殿收集具有治疗功效的晚露。艾露恩姐妹会寻求这些丝囊，用于举行纪念她灵魂的神圣仪式。",kw={"萨丝拉","女祭司艾茉拉","萨丝拉的祭品","银色丝囊","月神的泪水","月神殿","涌泉湖"},ang={["class:Priest"]="对于Elune的仆从而言，取回丝囊是一场神圣的葬礼仪式。这是在祈求月亮母亲救赎一只生灵，而非将她的死亡仅仅视为除害。",["race:NightElf"]="萨丝拉的悲惨结局提醒着卡多雷，即便是Elune所钟爱的生灵，也可能被侵害泰达希尔的病痛击倒。"},sec={{t="圣洁蛛丝与腐化",b="萨丝拉曾在涌泉湖附近，借着月光织出微光闪烁的蛛网。她的银色蛛丝将暮霭凝成具有治疗功效的露水，深受达纳苏斯的艾露恩姐妹会珍视。然而，泰达希尔的腐化侵袭了她，使她陷入狂暴的疯狂。萨丝拉威胁着自己的子嗣和周围的森林。女祭司艾茉拉请求旅人结束她的痛苦，取回她的丝囊，让这只曾在巨树枝桠间备受敬重的生灵得到仁慈的解脱。"},{t="祈求重生的献祭",b="Sisterhood在月神殿内的中央喷泉，将取回的丝囊献给Elune。在名为萨丝拉的祭品的仪式中，女祭司们祈求月亮女神接纳这只生灵的灵魂，净化那吞噬了她肉身的疯狂，并赐予她重生后的安宁。"}},faq={{q="银色丝囊从哪里获得？",a="从萨丝拉身上取得。她是一只巨大的蜘蛛，出没于泰达希尔北部边缘的涌泉湖附近。",al={"哪里能找到银色丝囊","银色丝囊掉落","谁掉落银色丝囊"}},{q="女祭司艾茉拉为什么需要丝囊？",a="女祭司艾茉拉希望将丝囊作为神圣的祭品献给艾露恩。这场仪式纪念萨丝拉昔日的纯洁，并祈求女神净化她的灵魂，赐予她安宁与重生。",al={"艾茉拉为什么需要丝囊","月神的泪水用途"}},{q="萨丝拉的蛛网有何特别之处？",a="萨丝拉吐出泛着微光的银色蛛丝，在月光下收集暮霭。凝聚的露水蕴含强大的恢复魔法，深受艾露恩姐妹会珍视，她们将其储存在月神殿中，用于治疗。",al={"萨丝拉的蛛网","萨丝拉做了什么"}},{q="既然萨丝拉是神圣的生灵，为什么还要杀死她？",a="腐化使萨丝拉与泰达希尔的其他野生生物一样，陷入无法治愈的疯狂。她的攻击行为危及森林，也威胁着自己的子嗣，因此女祭司们认为，杀死她是一种令人悲痛的仁慈之举。",al={"为什么杀死萨丝拉","萨丝拉为什么发疯"}}},fp="18,177,29.453.0,23.332.1,40.123.0,47.192.0,37.213.0,46.220.0"}
P.entries["item:simple-memorandum"] = {n="简易备忘录",s="在寒脊山谷，初出茅庐的侏儒战士被派往安威玛尔，接受斯兰·库尔曼的训练。他们为夺回诺莫瑞根的战争做着准备。",h="在寒脊山谷，初出茅庐的侏儒战士被派往安威玛尔，接受斯兰·库尔曼的训练。他们为夺回诺莫瑞根的战争做着准备。",kw={"安威玛尔","寒脊山谷","丹莫罗","诺莫瑞根","简易备忘录","斯兰·库尔曼","战士训练"},ang={["class:Warrior"]="身为战士，你在安威玛尔开始接受斯兰·库尔曼的正式战斗训练。你的战斗不再局限于最初的零星交锋。",["race:Gnome"]="身为流亡的侏儒，你与同胞怀着共同的目标，在矮人盟友身旁磨炼战斗技艺。你为解放诺莫瑞根做着准备。"},sec={{t="安威玛尔的召唤",b="年轻的侏儒战士手持介绍信，在寒脊山谷迎战野兽和穴居人。简易备忘录指引持信人去找安威玛尔的战士训练师斯兰·库尔曼。\n\n侏儒凭借才智和机械装置作战，但夺回诺莫瑞根还需要力量和严格的战斗训练。这份备忘录让持信人在初步训练之后，向斯兰学习战斗技艺。"}},faq={{q="简易备忘录是什么？",a="简易备忘录是一份写给寒脊山谷侏儒新手战士的书面消息。它指示他们向安威玛尔的矮人战士训练师报到。",al={"简易备忘录","这张便笺是什么","备忘录物品"}},{q="简易备忘录是谁写的？",a="简易备忘录没有署名。斯登·粗臂猜测它出自斯兰·库尔曼之手，但其中关于夺回诺莫瑞根的字句表明，这是一份侏儒的指令。它命令你向安威玛尔的矮人战士训练师斯兰报到。",al={"备忘录是谁写的","便笺是谁送的","简易备忘录的作者"}},{q="读完简易备忘录后会怎样？",a="读完简易备忘录后，你要将它带给安威玛尔的斯兰·库尔曼。他认可你夺回失落家园的决心，并愿意传授你战士的基本战斗技巧。",al={"备忘录有什么用","送到哪里","交付简易备忘录"}},{q="为什么由矮人训练侏儒战士？",a="矮人训练侏儒战士，是因为诺莫瑞根沦陷后，侏儒难民在铁炉堡和安威玛尔安顿下来。斯兰·库尔曼这样的矮人老兵传授战斗技艺，帮助流亡的盟友接受训练，夺回遭受辐射的城市。",al={"斯兰为什么训练侏儒","矮人训练侏儒"}}},fx={b027c55a={q="为什么要把简易备忘录交给我？",a="这份备忘录是侏儒的指令，命你向安威玛尔内的矮人战士训练师斯兰·库尔曼报到。身为流离失所的侏儒战士，你的首要指令是为夺回诺莫瑞根的战争做好准备，而斯兰·库尔曼已承诺帮助你和你的族人为此备战。你在寒脊山谷帮助斯登·粗臂时，他把这份便条转交给了你。",al={"为什么要用简易备忘录","简易备忘录的用途","为什么需要简易备忘录"}}},fp="17,142,21.407.0,30.159.0,32.237.0,49.185.0,39.244.0"}
P.entries["item:simple-rune"] = {n="简易符文",s="在寒脊山谷，斯兰·库尔曼用简易符文召集有潜力的年轻矮人战士，前往安威玛尔接受训练。",h="在寒脊山谷，斯兰·库尔曼用简易符文召集有潜力的年轻矮人战士，前往安威玛尔接受训练。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人符文","简易符文","斯兰·库尔曼","战士训练"},ang={["class:Warrior"]="作为一名矮人战士，简易符文标志着你迈出了接受正式训练的第一步，资深教官斯兰·库尔曼将指导你。",["race:Dwarf"]="身为矮人，斯兰·库尔曼的符文将引导你学习战斗的基础：握斧的方法、护甲的分量，以及实战中的汗水。"},sec={{t="战斗的召唤",b="开始清除寒脊山谷威胁的年轻战士，会收到斯兰·库尔曼的正式召令。符文上的战斗印记并无魔力，只是指示每位新兵前往安威玛尔内部，向斯兰·库尔曼报到。在那里，他传授基础战斗技巧，并提供实用建议，帮助他们在丹莫罗危机四伏的荒野中生存。"}},faq={{q="简易符文有什么用途？",a="简易符文指引新兵前往安威玛尔内部，接受斯兰·库尔曼的正式指导。寒脊山谷的年轻战士收到这块符文石板，从中得知训练指示。",al={"简易符文用途","符文有什么用","简易符文任务物品"}},{q="是谁送出了简易符文？",a="简易符文由斯兰·库尔曼送出。这位身在安威玛尔内部的矮人战士训练师，一直留意着那些在山谷中帮忙、有潜力的战士。",al={"谁写了符文","谁给了我简易符文","符文的寄送者"}},{q="我该把简易符文带到哪里？",a="将简易符文交给寒脊山谷中部、安威玛尔内部的斯兰·库尔曼。",al={"该去哪里","符文交付","斯兰·库尔曼位置"}}},fx={["0f0eb9fb"]={q="简易符文是什么？",a="简易符文是一块刻有文字的矮人石头，会交给寒脊山谷中有潜力的战士。它并不带有神秘的魔法，而是斯兰·库尔曼发出的书面召令，召唤初出茅庐的战士到安威玛尔向他报到，开始接受正式的战斗训练。",al={"简易符文是什么","简易符文的背景","简易符文物品"}},["2d1fc984"]={q="斯兰·库尔曼为什么要让你拿到简易符文？",a="斯兰·库尔曼送来符文，是为了招收你接受正式的战士训练。他从你在寒脊山谷一带最初的事迹中看到了潜力，希望让你打好矮人武艺的根基，并教你在当地威胁日益加剧之际，真正懂得如何为铁炉堡而战。",al={"斯兰·库尔曼为什么送来符文","为什么需要简易符文","为什么想要简易符文"}}},fp="11,120,17.305.0,39.169.0,26.137.0,32.83.0"}
P.entries["item:simple-sigil"] = {n="简易符记",s="在幽影谷，简易符记召集暗夜精灵战士新兵，前往奥莉希亚那里接受训练。这标志着他们迈出了保卫泰达希尔的第一步。",h="在幽影谷，简易符记召集暗夜精灵战士新兵，前往奥莉希亚那里接受训练。这标志着他们迈出了保卫泰达希尔的第一步。",kw={"奥莉希亚","伊尔萨莱恩","卡多雷战士","幽影谷","简易符记","泰达希尔","战士训练"},ang={["class:Warrior"]="作为一名kaldorei战士，简易符记是你踏入守护泰达希尔的武艺传承的第一份凭证。",["race:NightElf"]="作为暗夜精灵，你看到了kaldorei面临的紧迫局势：奥莉希亚和其他训练师正在招募有能力的人手，对抗世界之树枝叶间日益蔓延的腐化。"},sec={{t="战斗的召唤",b="在幽影谷，管理员伊尔萨莱恩指引年轻的暗夜精灵寻找自己的使命。一名信使送来了战士训练师奥莉希亚的简易符记，伊尔萨莱恩将它交给初出茅庐的战士。符记上的文字要求每位新兵前去报到，接受指导。在世界之树迎来动荡之际，这枚符记标志着他们武艺训练的开始。"},{t="防卫的重担",b="奥莉希亚借助符记，向新兵讲述卡多雷当前的迫切需求。泰达希尔近来的生长、林间野兽中蔓延的腐化，以及菲拉斯等遥远土地的重新发现，让暗夜精灵的守卫者人手愈发紧缺。这枚符记并不蕴含力量。它欢迎新兵加入守卫者的行列，肩负起保护族人、抵御新威胁的职责。"}},faq={{q="简易符记是什么？",a="简易符记是交给幽影谷暗夜精灵战士新兵的一枚刻有文字的信物。管理员伊尔萨莱恩将它交给新兵，上面的文字指引他们向奥莉希亚报到，接受训练。",al={"简易符记物品","简易符记有什么用","这枚符记是什么"}},{q="是谁送来了简易符记？",a="一名信使将简易符记从幽影谷的战士训练师奥莉希亚那里送到管理员伊尔萨莱恩手中，再由他交给战士新兵。",al={"谁制作了符记","谁送来了简易符记"}},{q="我该拿它做什么？",a="阅读上面的文字，带着简易符记前往幽影谷奥达希尔底部附近的奥莉希亚那里，开始你的战士训练。",al={"简易符记在哪里交","谁收简易符记"}},{q="这枚符记会赋予特殊能力吗？",a="不会。简易符记是一份书面通知，用于引荐立志成为战士的人拜见导师。",al={"符记的力量","简易符记属性"}}},fp="12,138,17.341.0,21.366.0,25.193.0,27.150.0,25.131.0,43.91.0"}
P.entries["item:simple-tablet"] = {n="普通石板",s="在试炼谷，高内克交给初出茅庐的巨魔战士一封信，让他们带给弗朗恩。",h="在试炼谷，高内克交给初出茅庐的巨魔战士一封信，让他们带给弗朗恩。",kw={"暗矛","杜隆塔尔","弗朗恩","高内克","普通石板","大兽穴","试炼谷","战士训练师"},ang={["class:Warrior"]="作为一名战士，这块石板指引你去找弗朗恩接受战斗训练。",["race:Troll"]="作为杜隆塔尔的一名暗矛巨魔，这份召令号召你与兽人并肩作战，壮大部落的前线队伍。"},sec={{t="战斗的召唤",b="高内克交给初出茅庐的巨魔战士一封来自塔尔瑟的信，收信人是大兽穴附近的战士训练师弗朗恩。这封信指引新兵在杜隆塔尔开始战斗训练，并要求他们前去向弗朗恩报到。信中号召他们为部落拿起武器。"}},faq={{q="普通石板是什么？",a="高内克交给试炼谷中立志成为战士的巨魔一封信，指引他们去找弗朗恩接受战斗训练。",al={"普通石板","这块石板是什么","巨魔战士石板"}},{q="谁寄来了这块石板？",a="塔尔瑟在信上署名，并指引新兵去找弗朗恩，他是试炼谷大兽穴外的战士训练师。",al={"谁寄来了普通石板","谁写了石板","石板寄件人"}},{q="我该把石板带到哪里？",a="把普通石板交给弗朗恩，他正在试炼谷的大兽穴外休息。",al={"普通石板交给谁","石板带到哪里","弗朗恩位置"}},{q="谁会收到这块石板？",a="普通石板会交给在试炼谷开始接受成年试炼的巨魔战士。",al={"谁都能获得普通石板吗","哪个职业能获得普通石板"}}},fp="13,85,19.269.0,26.116.0,21.121.0,27.83.0,25.98.0"}
P.entries["item:singed-scale"] = {n="烧焦的鳞片",s="在杜隆塔尔，烧焦的鳞片取自带电的 雷霆蜥蜴 身上焦黑的鳞甲。部落战士带回这些鳞片，以证明自己的耐力，并学习防御战技。",h="在杜隆塔尔，烧焦的鳞片取自带电的 雷霆蜥蜴 身上焦黑的鳞甲。部落战士带回这些鳞片，以证明自己的耐力，并学习防御战技。",kw={"前沿哨所","雷鳞蜥蜴","防御之道","烧焦的鳞片","雷霆蜥蜴","雷霆山","犹塞克"},ang={["class:Warrior"]="对于一名成长中的战士而言，将鳞片带给犹塞克，是学习防护之道、成为部落坚不可摧的盾牌的重要一步。",["faction:Horde"]="在前沿哨所，试炼确保驻守杜隆塔尔和贫瘠之地边境的卫兵与先锋拥有坚韧不拔的耐力。"},sec={{t="耐力的考验",b="部落老兵衡量一名战士的标准，是他在保护盟友时能承受多少打击。在杜隆塔尔西部的峡谷雷霆山，闪电蜥蜴和雷霆蜥蜴周身涌动着风暴能量，电光噼啪作响。猎杀这些野兽，就意味着要承受接连不断的电击和沉重打击。它们焦黑的鳞片证明，一名战士能够承受猛烈的攻势，在重压之下屹立不倒。"},{t="盾牌之道",b="在杜隆塔尔与贫瘠之地交界处的前沿哨所，老兵犹塞克要求新兵先交来五片鳞片，才肯传授战技。他认为，他们必须先练就强健的体魄，才能学习姿态和防御战术。带回鳞片，就证明他们有足够的毅力，将坚韧的皮肤、厚重的护甲和谨慎的步法结合起来，筑成抵御部落之敌的坚固防线。"}},faq={{q="烧焦的鳞片有什么用途？",a="烧焦的鳞片是战士耐力的证明。战士训练师犹塞克要求新兵先交来五片，才肯传授高深的防御技巧。",al={"烧焦的鳞片用途","谁需要烧焦的鳞片","烧焦的鳞片任务"}},{q="在哪里能找到烧焦的鳞片？",a="烧焦的鳞片可以从雷霆山的 雷霆蜥蜴 和 雷肤蜥蜴 身上取得。雷霆山是杜隆塔尔西部的一处峡谷，与贫瘠之地隔河相望。",al={"烧焦的鳞片位置","哪里能获得烧焦的鳞片","如何获得烧焦的鳞片"}},{q="这些鳞片为什么会烧焦？",a="雷霆蜥蜴 通过身体引导闪电和雷暴。持续噼啪作响的元素能量灼烧着它们的外皮，使其变得焦黑，也让鳞片呈现出烧焦的质地。",al={"为什么烧焦","鳞片为什么会烧焦"}},{q="犹塞克是谁，他为什么看重这些鳞片？",a="犹塞克是驻守在贫瘠之地东部前沿哨所的一名老兵。他向成长中的部落战士传授防御战技，但要求他们先与致命的野兽交锋，证明自己足够坚韧。",al={"犹塞克是谁","犹塞克"}}},fp="12,138,19.371.0,21.395.0,32.137.0,32.142.0,26.201.0,53.197.0"}
P.entries["item:skeleton-finger"] = {n="骷髅的手指",s="在暮色森林，骷髅的手指采自那些不得安息的亡者。夜色镇的伊瓦夫人收集这些残骸，以及食尸鬼的獠牙和蜘蛛毒液，用来制作护身符。",h="在暮色森林，骷髅的手指采自那些不得安息的亡者。夜色镇的伊瓦夫人收集这些残骸，以及食尸鬼的獠牙和蜘蛛毒液，用来制作护身符。",kw={"夜色镇","暮色森林","食尸鬼的牙齿","伊瓦夫人","骷髅劫掠者","骷髅的手指","惩罚图腾"},ang={["class:Mage"]="作为一名研究民间占卜术的法师，你或许会觉得，伊瓦夫人用骷髅指骨和天然毒液施加反击附魔，是乡野巫术与交感魔法的一种奇特结合。",["class:Paladin"]="作为一名圣骑士，亵渎骷髅遗骸、随身携带其断肢的做法，或许会让你不寒而栗。在暮色森林可怕的幽暗中，用邪秽之骨保护生者，是迫于无奈的残酷之举。"},sec={{t="不安亡者之骨",b="暮色森林各处都有亡者爬起，从骷髅劫掠者和战士，到操纵死灵法术的法师和恶魔，不一而足。大多数旅人都不愿碰触它们污秽的残骸，占卜师和秘术师却珍视其中冰冷的精华。夜色镇的先知伊瓦夫人收集这些指骨，将其中残留的死灵能量束缚在惩罚图腾中，使这件护符能够反击攻击者。"}},faq={{q="哪些生物会掉落骷髅的手指？",a="暮色森林各处的骷髅袭击者、骷髅医师、骷髅看守、骷髅战士、骷髅恐魔、骷髅魔和骷髅法师都会掉落骷髅的手指。",al={"骷髅的手指掉落地点","什么掉落骷髅的手指","骷髅的手指来源"}},{q="暮色森林里谁需要骷髅的手指？",a="夜色镇的先知伊瓦夫人需要骷髅的手指来制作护符。",al={"谁需要骷髅的手指","骷髅的手指任务发布者","骷髅的手指用途"}},{q="惩罚图腾是什么？",a="惩罚图腾是伊瓦夫人用骷髅的手指、食尸鬼的獠牙和蜘蛛毒液制成的护符。她将其中的黑暗能量束缚成一道光环，伤害任何攻击佩戴者的人。",al={"惩罚图腾用途","伊瓦夫人制作什么"}},{q="伊瓦夫人为什么需要用亡灵残骸制作护身符？",a="伊瓦夫人在仪式中利用当地生物残留的污秽与凶性。她将暮色森林中骷髅、食尸鬼和剧毒野兽的狂暴精华束缚在护符中，惩罚攻击者。",al={"为什么使用白骨魔法","图腾为什么要用骷髅的手指"}}},fx={["7c732e26"]={q="骷髅的手指是什么？",a="骷髅的手指是从暮色森林荒芜的树林和墓穴中游荡的骷髅怪物身上截下的干枯骨骼碎片。该地区受到死灵污染，这些骨指因此得以保存下来，仍残留着让亡灵躁动不安、继续活动的黑暗魔法气息。",al={"骷髅的手指是什么","辨认骷髅的手指"}},a7de6990={q="骷髅的手指来自哪里？",a="这些手指来自在暮色森林闹鬼的墓地和遗迹中被唤起的骷髅遗骸。它们并非人工制作，而是直接从活动的尸体上取下，例如骷髅战士、骷髅魔、骷髅看守和骷髅掠夺者。这些亡者在树林中穿行，受到一种神秘而不断蔓延的污染侵蚀，才得以活动。",al={"骷髅的手指来源","骷髅的手指从哪里来","骷髅的手指是谁制作的"}}},fp="15,157,21.373.0,38.125.0,39.84.0,32.179.0,63.206.0"}
P.entries["item:skin-of-sweet-rum"] = {n="一袋蜂蜜酒",s="闪金镇狮王之傲旅店的一袋蜂蜜酒即将送往湖畔镇，那里的战事已让酒馆的存货所剩无几。",h="闪金镇狮王之傲旅店的一袋蜂蜜酒即将送往湖畔镇，那里的战事已让酒馆的存货所剩无几。",kw={"酒吧老板丹尼尔","旱季","闪金镇","湖畔镇","狮王之傲旅店","一袋蜂蜜酒","蜂蜜酒"},ang={["faction:Alliance"]="身为联盟的旅行者，收集蜂蜜酒会让你看到，黑石兽人的入侵给那些守卫暴风城东部边境的小聚落带来了多大的压力。"},sec={{t="湖畔镇难得的慰藉",b="黑石兽人的入侵切断了通往赤脊山的道路，湖畔镇酒馆的存货日渐短缺。酒吧老板丹尼尔需要酒水来招待镇上的卫兵和难民，于是请旅行者去收集各地的特色佳酿。其中就有来自闪金镇狮王之傲旅店的一袋蜂蜜酒。"}},faq={{q="在哪里能找到一袋蜂蜜酒？",a="你可以在艾尔文森林闪金镇的狮王之傲旅店，向旅店老板或酒保购买一袋蜂蜜酒。",al={"蜂蜜酒位置","哪里买蜂蜜酒","谁卖蜂蜜酒"}},{q="谁需要这袋蜂蜜酒？",a="经营湖畔镇酒馆的酒吧老板丹尼尔需要一袋蜂蜜酒和其他各地佳酿，在旱季期间补充酒架上的存货。",al={"谁需要蜂蜜酒","蜂蜜酒交付","蜂蜜酒任务"}},{q="湖畔镇为什么快没酒了？",a="黑石兽人的入侵切断了通往赤脊山的商路，商队马车无法安全通行，湖畔镇的酒水也几乎耗尽。",al={"为什么没酒了","湖畔镇为什么缺酒","旱季原因"}},{q="除了蜂蜜酒，还需要哪些酒？",a="酒吧老板丹尼尔还需要来自西部荒野的一桶雷霆啤酒、来自暴风城的一桶葡萄酒，以及来自夜色镇的一瓶月光酒。",al={"旱季酒水","酒吧老板丹尼尔酒水清单","还需要什么酒"}}},fx={efbd5e13={q="一袋蜂蜜酒是什么？",a="一袋蜂蜜酒是一个装满甜酒的皮水囊，在艾尔文森林的闪金镇出售。它是南部艾泽拉斯人类王国珍视的几种地方特色烈酒之一。",al={"蜂蜜酒是什么","一袋蜂蜜酒的信息","蜂蜜酒"}}},fp="17,123,28.311.0,37.117.0,19.140.0,39.152.0,48.148.0"}
P.entries["item:skittering-blood"] = {n="粘稠的血液",s="粘稠的血液为皇家药剂师学会研制新的瘟疫提供了原料。这种试剂取自银松森林粘丝洞的蛛形生物，被遗忘者炼金师正在那里寻找对抗天灾军团和人类的武器。",h="粘稠的血液为皇家药剂师学会研制新的瘟疫提供了原料。这种试剂取自银松森林粘丝洞的蛛形生物，被遗忘者炼金师正在那里寻找对抗天灾军团和人类的武器。",kw={"法拉尼尔","新的瘟疫","伦弗利尔","皇家药剂师学会","银松森林","粘稠的血液","粘丝洞","粘丝"},ang={["faction:Horde"]="身为部落的一员，你帮助被遗忘者药剂师在对抗Scourge的战争中，用他们自行研制的武器保卫洛丹伦。",["race:Undead"]="身为Undead，你提供的粘稠的血液帮助Queen Sylvanas和皇家药剂师学会研制对抗阿尔萨斯和活着的人类的生物武器。"},sec={{t="剧毒馏液",b="粘丝潜伏者、粘丝捕猎者及其蛛母暗影编织者克雷希斯的血液含有剧毒。药剂师伦弗利尔发现，将这种血液与灰熊心脏中的毒素一同提炼，便能制成一种极其致命的药剂基液。其中的污染成分使它能用于炼金房的化学实验。"},{t="为新的瘟疫提供原料",b="在幽暗城，大药剂师法拉尼尔指挥皇家药剂师学会研制新的瘟疫。被遗忘者面对着成群的天灾军团和怀有敌意的人类残部，于是转向生物战，以求扭转劣势。法拉尼尔研究着这种血液的毒性，力图研制出一种既能摧毁亡灵之躯，也能摧毁活体血肉的传染病。"}},faq={{q="粘稠的血液有什么用途？",a="皇家药剂师学会将粘稠的血液用于研制被遗忘者的新的瘟疫。它与熊心中的毒素混合后，会形成一种不稳定的混合物，大药剂师法拉尼尔正在研究如何用它对付天灾军团和活着的人类。",al={"粘稠的血液用途","为何收集蜘蛛血液","法拉尼尔用粘稠的血液做什么"}},{q="哪里能找到粘稠的血液？",a="粘稠的血液取自粘丝洞及其周边的粘丝潜伏者、粘丝捕猎者和暗网编织者克雷希斯，那里是银松森林西北部一片阴暗、蛛网密布的林地。",al={"哪里获取粘稠的血液","粘稠的血液位置","谁掉落粘稠的血液"}},{q="谁需要这些样本？",a="银松森林瑟伯切尔的药剂师伦弗利尔需要这种血液。收集到的血液会被送往幽暗城的炼金房，交给大药剂师法拉尼尔。",al={"谁需要粘稠的血液","粘稠的血液任务给予者"}},{q="被遗忘者为什么需要当地野兽的毒液？",a="皇家药剂师学会从洛丹伦遭到腐化的动物体内提取天然毒素。银松森林巨型蛛形生物的毒液提供了原始的生物病原体，经过浓缩后，可被制成用作武器的合成瘟疫。",al={"为何需要蜘蛛毒液","药剂师的野兽研究"}}},fp="16,224,18.307.0,22.345.0,34.245.0,32.185.0,27.156.0,49.221.0"}
P.entries["item:sleepers-key"] = {n="沉睡者的钥匙",s="在石爪峰，沉睡者的钥匙守护着一座神圣的德鲁伊宝库。暗夜精灵德鲁伊为猛禽洞穴储藏室制作了三把附魔钥匙，它便是其中之一。",h="在石爪峰，沉睡者的钥匙守护着一座神圣的德鲁伊宝库。暗夜精灵德鲁伊为猛禽洞穴储藏室制作了三把附魔钥匙，它便是其中之一。",kw={"守门人的钥匙","沉睡者的宝箱","沉睡者的钥匙","石爪峰","猛禽洞穴储藏室","大兽穴"},ang={["class:Druid"]="身为德鲁伊，你能看出猛禽洞穴的钥匙和箱子如何构筑层层防线，用隐秘的箱子和需要钥匙开启的锁具封存强大的遗物。",["faction:Horde"]="身为部落的一员，取得沉睡者的钥匙是一次精心策划的突袭的一部分，目的是深入石爪峰腹地，解除暗夜精灵的防护结界，夺取封存在其宝库中的遗物。"},sec={{t="德鲁伊的防护",b="猛禽洞穴坐落于石爪峰，是卡利姆多德鲁伊的堡垒与圣所。为了让神圣的遗物和强大的珍宝免遭觊觎，暗夜精灵守护者设置了重重锁具与隐秘的箱子。沉睡者的钥匙是三把钥匙之一，它们共同构成一道防护结界。这把钥匙藏在洞穴深处一只隐蔽的箱子里，需要用藏在入口附近的守门人的钥匙开启。另外两把分别是利爪钥匙和古墓钥匙。将三把钥匙全部插入猛禽洞穴储藏室的石锁，结界便会消散，显露出其中的古老物品。"}},faq={{q="沉睡者的钥匙有什么用途？",a="沉睡者的钥匙与古墓钥匙、利爪钥匙共同开启猛禽洞穴储藏室。这座受结界保护的石制宝库位于石爪峰的兽穴深处。",al={"沉睡者的钥匙有什么用","沉睡者的钥匙用途","猛禽洞穴储藏室钥匙"}},{q="沉睡者的钥匙是如何被锁藏起来的？",a="德鲁伊将沉睡者的钥匙放在猛禽洞穴西北部通道内的沉睡者的箱子中。守门人的钥匙可以将它打开；德鲁伊把那把钥匙藏在洞穴入口附近一盏不起眼的灯笼里。",al={"沉睡者的钥匙在哪里","开启沉睡者的贮藏室","守门人的钥匙需求"}},{q="德鲁伊为何用多把钥匙藏护遗物？",a="暗夜精灵德鲁伊设置了复杂的防护措施，以免洞穴遭到攻击时，强大的物品和神圣的传承之物落入敌人手中。他们将钥匙分散藏在隐秘的箱子里，让入侵者难以掠夺宝藏。",al={"为什么有这么多钥匙","猛禽洞穴防御","德鲁伊宝库谜题"}},{q="它为什么叫沉睡者的钥匙？",a="德鲁伊从未解释过这个名字。沉睡者的钥匙与沉睡者的箱子有着相同的名号，后者是猛禽洞穴中存放这把钥匙的隐秘箱子。",al={"沉睡者是谁","沉睡者的钥匙名称含义"}}},fx={["0a862a33"]={q="沉睡者的钥匙是什么？",a="沉睡者的钥匙是石爪峰暗夜精灵德鲁伊制作的三把专用钥匙之一。它藏在猛禽洞穴深处一个上锁的储物箱里，是守护德鲁伊圣物核心宝库的防护系统中不可或缺的一环。",al={"沉睡者的钥匙是什么","沉睡者的钥匙背景","关于沉睡者的钥匙"}},["8275ad63"]={q="沉睡者的钥匙从何而来？是谁制作的？",a="这把钥匙由在石爪峰建立猛禽洞穴的德鲁伊打造。为了保护强大的神器免遭入侵者染指，他们设计了一套复杂的安保方案，将钥匙锁在一个专用箱子里，名为沉睡者的储藏箱。",al={"沉睡者的钥匙是谁制作的","沉睡者的钥匙来源","沉睡者的钥匙从哪里来"}},["3884172c"]={q="为什么有人想要沉睡者的钥匙？",a="部落想要这把钥匙，以绕过德鲁伊层层设下的防御，打开猛禽洞穴宝库。它与利爪钥匙和古墓钥匙合在一起，可以开启石爪峰的石制密室，取出德鲁伊藏在其中的强大圣物。",al={"为什么要找沉睡者的钥匙","为什么需要沉睡者的钥匙","谁想要沉睡者的钥匙"}}},fp="13,149,19.546.0,35.148.0,38.200.0,56.237.0,35.141.0"}
P.entries["item:smoky-iron-ingot"] = {n="烟雾铁锭",s="在狂风挖掘场，狗头人用从石爪山脉开采的矿石熔炼烟雾铁锭。兽人护甲师珍视这些金属锭，用它们为部落战士打造坚固的锁甲装备。",h="在狂风挖掘场，狗头人用从石爪山脉开采的矿石熔炼烟雾铁锭。兽人护甲师珍视这些金属锭，用它们为部落战士打造坚固的锁甲装备。",kw={"野蛮护甲","狗头人","烟雾铁锭","石爪山","索恩格瑞姆·火眼","战士","狂风"},ang={["class:Warrior"]="对部落战士来说，在石爪山收集这些铁锭是对耐力的考验。锻造野蛮锁甲需要用到它们。",["profession:Blacksmithing"]="这些铁锭展现了狗头人挖掘者粗陋的冶炼方法，与训练有素的铁匠所用的精湛技艺形成对照。"},sec={{t="狗头人的粗陋冶金术",b="狗头人在石爪山脉狂风峭壁的隧道中熔炼烟雾铁锭。它们从岩石遍布的山坡上挖出矿石，用冒着浓烟的简陋炉火加热。残渣和木炭附着在铁锭表面，但金属依然致密而坚固。"},{t="锻造野蛮护甲",b="索恩格瑞姆·火眼是一位近乎失明的兽人护甲师，在一处俯瞰贫瘠之地的简陋营地中工作。他索要这些铁锭，为经受过考验的部落战士制作护甲。这种烟熏过的金属与精炼铁锭、蓝铜粉和挥发性燃素一起，构成了野蛮锁甲坚韧的内核。"}},faq={{q="烟雾铁锭从哪里来？",a="石爪山脉东部狂风挖掘场和隧道中的狗头人携带着烟雾铁锭。其中包括挖掘者、切石者、歹徒、地卜师，以及它们的霸主。",al={"哪里能找到烟雾铁锭","烟雾铁锭位置","谁掉落烟雾铁锭"}},{q="烟雾铁锭有什么用途？",a="响应索恩格瑞姆·火眼召唤的战士会收集烟雾铁锭。这位护甲大师住在贫瘠之地十字路口附近的山峰上，需要十五块铁锭来锻造野蛮锁甲。",al={"烟雾铁锭用途","烟雾铁锭有什么用","野蛮护甲任务物品"}},{q="为什么这些铁锭被称为“烟雾”铁锭？",a="狗头人在昏暗的隧道中，用火势微弱的简陋炉火熔炼矿石。煤烟、炭粉和灰烬附着在金属表面，使它无法呈现洁净的光泽。",al={"为什么带有烟雾","烟雾铁锭背景故事"}},{q="任何铁匠都能用这些铁锭锻造吗？",a="不能。这些形状不规则、裹满煤烟的铁锭不适合常规的商业锻造。只有索恩格瑞姆·火眼这样的铁匠，才懂得如何将它们制成定制的战斗装备。",al={"玩家能否锻造烟雾铁锭","烟雾铁锭是否为商品"}}},fp="16,164,23.242.0,24.281.0,37.182.0,36.194.0,40.159.0,43.166.0"}
P.entries["item:smoldering-embers"] = {n="闷烧余烬",s="在焦炭谷，火元素被扑灭后会留下闷烧余烬。暗夜精灵哨兵收集这些余烬，作为火势正被平息的证明。",h="在焦炭谷，火元素被扑灭后会留下闷烧余烬。暗夜精灵哨兵收集这些余烬，作为火势正被平息的证明。",kw={"燃烧摧毁者","燃烧破坏者","焦炭谷","怒灵","凯拉·影矛","游荡的焰灵","闷烧余烬","石爪山","荆棘谷地精"},ang={["class:Druid"]="身为德鲁伊，你眼中的余烬是工业贪欲破坏自然平衡的悲惨明证。元素的怒火让灰烬覆盖的土壤无法恢复生机。",["race:NightElf"]="对暗夜精灵而言，焦炭谷的烈火是卡利姆多的一道伤口。收集这里的余烬是一项庄严的职责，要清除外来者的亵渎，在Elune的注视下重归安宁。"},sec={{t="焦炭谷的残余",b="荆棘谷地精的伐木和工业活动让焦炭谷陷入火海，也惊动了大地深处的毁灭力量。随后，燃烧破坏者、燃烧摧毁者和游荡的烈焰之魂席卷了这片焦黑的盆地。元素被扑灭后，便会留下覆满灰烬的核心，化作闷烧余烬。这些余烬表明，肆虐谷地的烈火正逐渐得到控制。"}},faq={{q="闷烧余烬从何而来？",a="闷烧余烬来自石爪山脉南部焦炭谷中的火元素。燃烧破坏者、燃烧毁灭者和游荡的烈焰都会留下这些余烬。",al={"哪里能找到闷烧余烬","谁掉落闷烧余烬","闷烧余烬来源"}},{q="凯拉·影矛为何需要这些余烬？",a="凯拉·影矛需要这些余烬，作为焦炭谷中的火元素正被清剿的证明。她相信，只要狂暴的灵体仍在肆意游荡，这片伤痕累累的土地就无法在艾露恩的恩泽下恢复生机。",al={"为何收集闷烧余烬","凯拉·影矛的余烬","怒灵目标"}},{q="是什么导致火元素出现在焦炭谷？",a="荆棘谷地精用蛮横的机械作业和肆无忌惮的焚烧清除古老森林，将火元素引到了焦炭谷。他们不计后果的掠夺破坏了大地的稳定，释放出充满敌意的火焰与岩石元素，将地精赶了出去。",al={"焦炭谷发生了什么","石爪山为何有火元素","荆棘谷地精火焰灵体"}}},fx={["4d13fc7e"]={q="什么是闷烧余烬？",a="闷烧余烬是肆虐焦炭谷的毁灭性火元素被消灭后留下的燃烧残骸。燃烧掠夺者、游荡的火焰之灵和燃烧毁灭者等生物被击败后，这些发光的残余物仍会持续燃烧，成为它们在这片毁灭森林中横冲直撞的烈焰已被平息的实证。",al={"什么是闷烧余烬","闷烧余烬背景"}}},fp="17,159,28.404.0,37.182.0,45.208.0,62.277.0"}
P.entries["item:snellig-s-snuffbox"] = {n="斯涅利格的鼻烟盒",s="在失落的舰队，斯涅利格的鼻烟盒仍在沉船间的亡灵主人手中。米奈希尔港的大副菲兹莫斯想要这只鼻烟盒，以此证明他那受诅咒的船员已经安息。",h="在失落的舰队，斯涅利格的鼻烟盒仍在沉船间的亡灵主人手中。米奈希尔港的大副菲兹莫斯想要这只鼻烟盒，以此证明他那受诅咒的船员已经安息。",kw={"受诅咒的船员","菲兹莫斯","库尔提拉斯","失落的舰队","斯涅利格","鼻烟盒","第三舰队","湿地"},ang={["faction:Alliance"]="身为联盟冒险者，找回遇难的库尔提拉斯人水手的遗物，让他们受诅咒的灵魂安息，是你为昔日的海军盟友承担的一项沉重职责。"},sec={{t="第三舰队的纪念物",b="大副斯涅利格仍在湿地北部近海的一艘沉船中紧攥着他的鼻烟盒。库尔提拉斯的第三舰队在那里搁浅时，船上一件隐秘宝藏所关联的神秘力量让水手和军官们葬身水底。溺亡的船员受这股力量束缚，化作饱受折磨的幽灵和骷髅亡灵，再次站了起来。斯涅利格在最靠近海岸的那艘沉船腐朽的底舱中游荡。他的鼻烟盒小巧而普通，留存着他生前航海生活的痕迹。大副菲兹莫斯是这场灾难中唯一活下来的幸存者，他希望有人带回这件遗物，证明至少有一位罹难的船员已从折磨中解脱。"}},faq={{q="斯涅利格的鼻烟盒是什么？",a="斯涅利格的鼻烟盒是大副斯涅利格生前拥有的一只小巧的私人物品容器。他化为亡灵后，仍在湿地北部海岸外的一艘沉船上随身带着它。",al={"这是什么物品","斯涅利格的鼻烟盒","鼻烟盒"}},{q="在哪里能找到斯涅利格的鼻烟盒？",a="你可以从大副斯涅利格身上取得鼻烟盒，他在湿地西北部失落的舰队中、最靠近岸边的那艘沉船底舱里游荡。",al={"斯涅利格在哪里掉落鼻烟盒","寻找斯涅利格","大副斯涅利格位置"}},{q="谁想要这只鼻烟盒？",a="大副菲兹莫斯希望你把鼻烟盒带到米奈希尔港交给他。这位第三舰队唯一活下来的幸存者想用它来证明斯涅利格已经安息。",al={"谁收鼻烟盒","交给谁","菲兹莫斯任务"}},{q="大副斯涅利格为什么会受到诅咒？",a="菲兹莫斯说，第三舰队的一艘船上藏着一件黑暗而可怕的宝藏，船只失事时，它给船员们带来了厄运。他们的灵魂仍被困在腐朽的船体木板中，无法安息。",al={"斯涅利格为什么是亡灵","失落的舰队诅咒","第三舰队的诅咒"}}},fp="18,184,29.620.0,27.168.0,35.152.0,24.167.0,33.194.0"}
P.entries["item:snufflenose-command-stick"] = {n="地鼠指挥棒",s="在棘齿城，麦伯克·米希瑞克斯派出受过训练的地鼠，前往剃刀沼泽寻找蓝叶薯。",h="在棘齿城，麦伯克·米希瑞克斯派出受过训练的地鼠，前往剃刀沼泽寻找蓝叶薯。",kw={"蓝叶薯","指挥棒","地鼠","麦伯克·米希瑞克斯","棘齿城","剃刀沼泽","贫瘠之地"},ang={["profession:Cooking"]="蓝叶薯在世界各地都被视为珍贵的美味佳肴。要找到它们，你需要受过训练的动物和驯兽者的指挥棒，而非普通厨具。"},sec={{t="号令地鼠的棒子",b="麦伯克·米希瑞克斯训练了一批地鼠，让它们在剃刀沼泽深处寻找蓝叶薯。这些块根藏在荆棘密布的隧道下，没有帮助几乎不可能找到。麦伯克是棘齿城的一名商人，他不愿亲自进入野猪人的巢穴。他将地鼠指挥棒交给冒险者，用来指挥地鼠。即使相隔五十步，指挥棒也能引导它们嗅出并挖出块根。"}},faq={{q="地鼠指挥棒有什么用途？",a="地鼠指挥棒能指挥受过训练的 地鼠，在剃刀沼泽寻找隐藏的蓝叶薯。将指挥棒对准地鼠，它就会循着气味挖出块根。",al={"如何使用指挥棒","指挥棒有什么作用","指挥棒用途"}},{q="在哪里可以获得地鼠指挥棒？",a="你可以在棘齿城麦伯克·米希瑞克斯的工坊外获得地鼠指挥棒。随附的还有一个装着受训地鼠的箱子，以及一本使用手册。",al={"哪里获得指挥棒","指挥棒位置","谁提供指挥棒"}},{q="麦伯克·米希瑞克斯为什么想要蓝叶薯？",a="麦伯克·米希瑞克斯寻找蓝叶薯，是因为这种珍稀美味能让他从世界各地富裕的美食界熟客那里赚取丰厚利润。蓝叶薯生长在贫瘠之地的地下深处，那里是野猪人的领地，因此他雇用冒险者去采集。",al={"为什么要块根","蓝叶薯用途","麦伯克 为什么要块根"}},{q="找到蓝叶薯后，可以留下指挥棒吗？",a="不可以。采集到所需的蓝叶薯后，你要带着收获回到棘齿城，将地鼠指挥棒和运输箱归还给麦伯克。",al={"能否保留指挥棒","归还指挥棒"}}},fx={["8cc828c2"]={q="什么是地鼠指挥棒？",a="地鼠指挥棒是嗅鼻公司获得专利的驯养工具，与地精商人麦伯克·米希瑞克斯在棘齿城训练的地鼠配套使用。它专门用于指挥受训的嗅鼻地鼠，向它们发出信号，让它们挖出埋藏隐秘的美味，而普通侦察者根本无从发现这些东西。",al={"什么是指挥棒","嗅鼻指挥棒","什么是地鼠指挥棒"}},["9fdd5faa"]={q="地鼠指挥棒来自哪里？由谁制造？",a="这根指挥棒是嗅鼻公司的专利产品，公司所有者玛维格·铜拴在《地鼠训练手册》中说明了它的用法。棘齿城的麦伯克·米希瑞克斯训练嗅鼻地鼠采集稀有美味，并将指挥棒、箱子和手册放在一起，让雇来的帮手能够妥善控制这些小家伙。",al={"谁制造了指挥棒","指挥棒的来历","指挥棒来自哪里"}},fb1cfa60={q="为什么有人想要地鼠指挥棒？",a="在剃刀沼泽的荆棘丛下，光凭肉眼根本找不到稀有的蓝叶块茎。指挥棒至关重要，因为它能驱使受训的嗅鼻地鼠嗅探五十步之外的气味并挖出块茎，然后把块茎交给麦伯克·米希瑞克斯，就能获得丰厚报酬。",al={"为什么需要这根棒子","为什么要找指挥棒","为什么要获取地鼠指挥棒"}}},fp="25,93,17.432.0,47.178.0,50.166.0,45.247.0,54.141.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="地鼠训练手册",s="在棘齿城，麦伯克·米希瑞克斯身边放着《地鼠训练手册》。这本小册子由地鼠有限公司.的玛维格·铜拴编写，讲解如何派训练有素的地鼠到剃刀沼泽寻找蓝叶薯。",h="在棘齿城，麦伯克·米希瑞克斯身边放着《地鼠训练手册》。这本小册子由地鼠有限公司.的玛维格·铜拴编写，讲解如何派训练有素的地鼠到剃刀沼泽寻找蓝叶薯。",kw={"蓝叶薯","地鼠","手册","麦伯克·米希瑞克斯","棘齿城","剃刀沼泽"},ang={["profession:Cooking"]="手册讲解了如何采集蓝叶薯，这种地下根茎被艾泽拉斯各地的美食家和商人视为珍稀佳肴。"},sec={{t="地精的操作指南",b="地鼠有限公司.的所有者玛维格·铜拴编写了一本指南，介绍如何照料和指挥公司训练的地鼠。它们嗅觉灵敏，能在五十步之外嗅出埋在地下的蓝叶薯。手册讲解了如何从通风的箱子里放出地鼠，并用指挥棒引导它拱土搜寻。勘探者指引它穿过剃刀沼泽的荆棘和野猪人隧道，寻找这些块茎。"}},faq={{q="《地鼠训练手册》有什么用途？",a="手册讲解了如何从箱子里放出麦伯克·米希瑞克斯训练的地鼠，并用指挥棒引导它在剃刀沼泽寻找蓝叶薯。",al={"手册有什么用","为什么要读手册","手册用途"}},{q="在哪里能找到这本手册？",a="你可以在棘齿城找到这本手册，就在麦伯克·米希瑞克斯身旁，旁边还有采集块茎用的箱子和指挥棒。",al={"手册位置","书在哪里","如何获得手册"}},{q="为什么寻找蓝叶薯需要地鼠？",a="蓝叶薯深埋在剃刀沼泽的地下，人型生物几乎不可能发现它们。训练有素的地鼠能在五十步之外嗅出一株。",al={"为什么要用地鼠","不用地鼠能找到块茎吗"}},{q="这本手册是谁写的？",a="地鼠有限公司.的所有者玛维格·铜拴在手册上署了名。他编写这本手册，是为了教新主人如何喂养地鼠、带它们散步，以及用获得专利的指挥棒指挥它们。",al={"手册作者","谁编写的"}}},fx={["1c231f00"]={q="什么是地鼠训练手册？",a="这是一本说明手册，与受训的嗅鼻地鼠和指挥棒配套提供。手册指导冒险者如何在剃刀沼泽的地下隧道中操控这种生物，并说明如何命令地鼠嗅出难以发现的地下蓝叶块茎。",al={"什么是地鼠训练手册","地鼠训练手册是什么","什么是这本手册"}}},fp="26,193,26.388.0,54.184.0,28.114.0,59.142.0,21.165.0"}
P.entries["item:sodium-nitrate"] = {n="硝酸钠",s="在巴尔莫丹，硝酸钠帮助矮人炸开南贫瘠之地的岩石。加恩·石塔寻求这种化学药剂，用来制作对付堡垒的炸药。",h="在巴尔莫丹，硝酸钠帮助矮人炸开南贫瘠之地的岩石。加恩·石塔寻求这种化学药剂，用来制作对付堡垒的炸药。",kw={"巴尔莫丹","巴尔丹","黑炉","加恩·石塔","硝化甘油","加恩的复仇","硝酸钠","木浆"},ang={["profession:Engineering"]="工程师们知道，硝酸钠、硝化甘油和木浆组成了稳定化炸药的配方，也是加恩自制炸药的基础。",["race:Tauren"]="身为牛头人，加恩·石塔用矮人的化学药剂发起反击，为遭到摧毁的祖地复仇。"},sec={{t="工业爆破",b="巴尔莫丹的矮人挖掘者用硝酸钠炸开南贫瘠之地的岩石。巴尔丹远征队带着挖土机和爆破药剂，闯入了石塔部族的祖地。挖掘工地和附近堡垒中的火枪手、士兵和军官都携带着这种化学药剂。"},{t="反击与复仇",b="入侵者摧毁了部族的家园后，加恩·石塔一直监视着他们，并搜集了他们的工程图纸。常规进攻无法突破戒备森严的要塞，这位流亡的牛头人便用敌人的爆破物资反击。他将掠来的硝酸钠与硝化甘油和木浆混合，制成炸药，意图撼动巴尔莫丹的根基。"}},faq={{q="硝酸钠在贫瘠之地有什么用途？",a="铁炉堡矮人用硝酸钠制作炸药，炸开挖掘场的岩石地面。加恩·石塔将它与硝化甘油和木浆混合，制成对付巴尔莫丹的炸药。",al={"硝酸钠用途","硝酸钠有什么用"}},{q="硝酸钠从哪里来？",a="驻扎在南贫瘠之地巴尔莫丹的矮人部队携带着硝酸钠。火枪手、士兵、军官，以及塞瑞克·黑炉公爵等指挥官都备有这种药剂。",al={"谁掉落硝酸钠","哪里获取硝酸钠"}},{q="加恩·石塔为什么需要这种化学药剂？",a="矮人的挖掘毁掉了加恩·石塔祖辈居住的村庄。他没有重型攻城器械，于是研究了矮人的图纸，着手用他们自己的物资制造炸药，以摧毁他们的防御工事。",al={"加恩为什么需要硝酸钠","加恩·石塔炸药"}},{q="硝酸钠本身危险吗？",a="硝酸钠本身是一种氧化剂，也是一种化学盐类，并不会立即爆炸。与燃料及硝化甘油这类对震动敏感的化学物质混合后，它就会变得危险而不稳定。",al={"硝酸钠是炸药吗"}}},fp="14,175,21.313.0,25.375.1,47.185.0,36.176.0,44.233.0,39.199.0"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="所罗门写给夜色镇的求救信",s="湖畔镇面临的威胁日益加剧，所罗门镇长向夜色镇请求援助。他在写给艾尔罗·埃伯洛克公爵的急信中，请求守夜人协助保卫赤脊山。",h="湖畔镇面临的威胁日益加剧，所罗门镇长向夜色镇请求援助。他在写给艾尔罗·埃伯洛克公爵的急信中，请求守夜人协助保卫赤脊山。",kw={"夜色镇","暮色森林","湖畔镇","艾尔罗·埃伯洛克公爵","所罗门镇长","前往夜色镇的信使","守夜人","赤脊山","所罗门的求援"},ang={["faction:Alliance"]="对联盟而言，所罗门的求援表明，在暴风城支援匮乏的情况下，南方的聚居地只能相互求助。",["race:Human"]="身为一名人类旅者，你携带的这封公函道出了赤脊山与暮色森林面临的危机。"},sec={{t="危急中的求援",b="湖畔镇遭到黑石兽人、豺狼人和鱼人的袭击，暴风城派来的援军却寥寥无几。所罗门镇长向夜色镇的埃伯洛克镇长发出正式求援信，请他派遣守夜人民兵北上赤脊山。在艾泽拉斯南部各地，中央军事援助迟迟不到，人类聚居地必须相互求援，才能生存下去。"},{t="夜色镇的困境",b="夜色镇早已疲于抵御亡灵、饥饿的野兽，以及笼罩暮色森林的黑暗，艰难守住边界。守夜人兵力捉襟见肘，所罗门的求援信送达时，镇上已无力抽调守军支援赤脊山。"}},faq={{q="所罗门写给夜色镇的求救信是什么？",a="所罗门写给夜色镇的求救信是所罗门镇长写给夜色镇镇长艾尔罗·埃伯洛克公爵的一封急信。信中请求守夜人协助保卫赤脊山，抵御黑石兽人和豺狼人。",al={"所罗门写给夜色镇的信","所罗门的求援是什么","湖畔镇写给暮色森林的信"}},{q="湖畔镇为何向夜色镇请求军事援助，而不是暴风城？",a="由于政务停滞和内部纷争，暴风城向边远领地派遣的驻军寥寥无几。所罗门镇长只能独自应对日益频繁的袭击，于是向邻近的人类城镇求援。",al={"为何向夜色镇求援","为何不向暴风城求援","所罗门为何需要守夜人"}},{q="艾尔罗·埃伯洛克公爵是谁？",a="艾尔罗·埃伯洛克公爵是夜色镇的镇长，也是暮色森林的主要民政领袖。他管理镇务，并协调守夜人的行动，这支民间防卫力量负责抵御林中的威胁。",al={"埃伯洛克是谁","夜色镇镇长","艾尔罗勋爵"}},{q="夜色镇真的能抽调守夜人援助湖畔镇吗？",a="不能。暮色森林面临亡灵、凶暴的狼人和黑暗魔法的威胁，守夜人勉强才能守住夜色镇周边。它无力抽调战士前往赤脊山。",al={"夜色镇是否援助","守夜人会来吗","埃伯洛克派出卫兵了吗"}}},fx={a3b7e1d6={q="所罗门写给夜色镇的求救信来自哪里？由谁写的？",a="这封信由赤脊山湖畔镇的领袖所罗门镇长亲笔写下。黑石兽人步步紧逼，而暴风城又无法派来王室援军。为了争取邻近聚居地的援助，所罗门在湖畔镇的镇政厅亲自写下了这封紧急求援信。",al={"谁写了所罗门的求救信","所罗门写给夜色镇的求救信的来历"}},["5061acb5"]={q="艾尔罗·埃伯洛克公爵为什么想要所罗门写给夜色镇的求救信？",a="艾尔罗·埃伯洛克公爵需要这封信，因为信中正式详述了湖畔镇岌岌可危的防御状况，以及所罗门镇长直接提出的军事援助请求。作为夜色镇的镇长和夜行者指挥官，埃伯洛克依靠这样的官方信件了解联盟邻邦面临的威胁，并评估自己的城镇能否抽调卫兵。",al={"为什么要递送所罗门的求救信","埃伯洛克为什么需要这封信","所罗门写给夜色镇的求救信的用途"}}},fp="27,149,24.361.0,23.222.1,36.139.0,73.206.0,27.193.0,63.165.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="所罗门写给西部荒野的求救信",s="在湖畔镇，所罗门镇长向西部荒野发出紧急求援，请求协助抵御黑石兽人和豺狼人。他请求格里安·斯托曼派遣人民军前来支援，而暴风城的皇家军队却迟迟没有回应。",h="在湖畔镇，所罗门镇长向西部荒野发出紧急求援，请求协助抵御黑石兽人和豺狼人。他请求格里安·斯托曼派遣人民军前来支援，而暴风城的皇家军队却迟迟没有回应。",kw={"格里安·斯托曼","湖畔镇","所罗门镇长","人民军","赤脊山","所罗门的求救信","暴风城军队","西部荒野"},ang={["faction:Alliance"]="对联盟而言，所罗门的求援表明，当皇家军队迟迟未至时，边远城镇只能转向当地的志愿者求助。",["race:Human"]="身为人类，你能看到乡间聚落已是何等困窘，国王失踪，政务疏忽，让边境地区无力抵御威胁。"},sec={{t="危急中的求援",b="黑石兽人和敌对的豺狼人威胁着赤脊山，所罗门镇长在湖畔镇孤立无援。暴风城的皇家军队尚未大举抵达，守卫这片地区的边境。所罗门已无暇等待首都的支援，只能写信向正规军之外的力量求助。他听说西面的艾尔文正在组建一支志愿防卫队，于是向人民军发出了求援。"},{t="跨越边境的求援",b="所罗门将信寄给格里安·斯托曼，这位久经沙场的战士正在组织西部荒野的边境防御。他希望斯托曼能抽调一些战士支援湖畔镇，直到暴风城派来正规后备部队。一名冒险者负责送信。暴风城的边远领地之间缺乏协调，各地镇长只能自行安排相互援助。"}},faq={{q="所罗门写给西部荒野的求救信是什么？",a="湖畔镇的所罗门镇长写信给格里安·斯托曼，请求西部荒野的人民军派出援军，协助保卫赤脊山。",al={"所罗门的求救信是什么","所罗门写给西部荒野的求救信","湖畔镇西部荒野信件"}},{q="所罗门镇长为什么向西部荒野求助，而不是暴风城？",a="湖畔镇的危机日益加剧，暴风城的皇家军队却尚未大举抵达。所罗门无暇等待王室的援助，只能向附近的一支武装力量求助。",al={"为何向西部荒野求助","为何不向暴风城求助","为何向西部荒野寄出求救信"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼领导着人民军，这是一支由当地农民和定居者组成的志愿防卫组织，保护西部荒野免受迪菲亚潜行者侵扰。",al={"斯托曼是谁","格里安·斯托曼的职责"}},{q="哪些威胁迫使所罗门寄出这封信？",a="黑石兽人正在入侵，豺狼人也在赤脊山各处劫掠，让湖畔镇的守卫疲于应付。",al={"湖畔镇为何陷入危险","什么威胁着赤脊山"}}},fx={["7804da1c"]={q="所罗门写给西部荒野的求救信来自哪里？由谁写的？",a="这封信由身处困境的赤脊山湖畔镇镇长所罗门亲笔写下。暴风城军队未能派出承诺的援军保护他的人民，他在绝望之下亲自写下这封紧急信件，向附近的盟友求援。",al={"谁写了所罗门写给西部荒野的求救信","所罗门的求救信来自哪里","所罗门求救信的作者"}},["6d6e291d"]={q="格里安·斯托曼为什么想要所罗门写给西部荒野的求救信？",a="格里安·斯托曼领导着西部荒野的人民军，这封信让他得知湖畔镇的危急处境。所罗门希望人民军能抽调战士，增强赤脊山日渐衰弱的防御力量，同时镇民仍在等待暴风城安度因国王宫廷的消息和援军。",al={"为什么要递送所罗门的求救信","斯托曼为什么想要这封求救信","这封信有什么用"}}},fp="26,207,24.381.0,26.355.0,35.148.0,72.165.0,25.151.0,53.124.0"}
P.entries["item:soran-ruk-fragment"] = {n="索兰鲁克宝珠的碎片",s="在黑暗深渊，邪教徒持有囚禁索兰鲁克的破碎宝珠的碎片。这些碎片仍带有曾被束缚其中的恶魔留下的邪能。",h="在黑暗深渊，邪教徒持有囚禁索兰鲁克的破碎宝珠的碎片。这些碎片仍带有曾被束缚其中的恶魔留下的邪能。",kw={"黑暗深渊","杜安·卡汉","邪能","索兰鲁克宝珠","索兰鲁克","暮光侍僧"},ang={["class:Warlock"]="身为术士，你可以利用索兰鲁克宝珠这类囚禁恶魔的容器，引导原始的邪能，而无需直接降服恶魔。"},sec={{t="破碎的牢笼",b="索兰鲁克失去了燃烧军团的宠信后，囚禁它的宝珠被打碎了。令主人不满的恶魔，其灵魂可能会被封入宝珠，再交给施展邪能法术的施法者，作为力量之源。黑暗深渊被淹没的废墟中，暮光之锤邪教徒持有宝珠其中一半的较小碎片。他们汲取其中残留的恶魔精华，用于自己的法术。"},{t="在贫瘠之地重铸",b="每块碎片都仍保留着被囚禁恶魔的一丝生命力。杜安·卡汉是隐居在贫瘠之地南部的学者，他毕生研究恶魔容器，并拥有一颗类似的宝珠，名为扎尔加恩宝珠。有野心的术士可以带给他三块小碎片，以及存放在银松森林的那块较大碎片。他能将这件遗物重新铸成完整的宝珠，使其成为获取力量的工具。"}},faq={{q="索兰鲁克是什么？",a="索兰鲁克曾是燃烧军团的一名恶魔，后来失去了军团首领的宠信。作为惩罚，它的灵魂被抽出，囚禁在一颗水晶宝珠中，供凡人的术士和法师汲取能量。",al={"索兰鲁克是谁","索兰鲁克背景故事","索兰鲁克是恶魔吗"}},{q="这些碎片在哪里能找到？",a="在佐拉姆海岸沿线的黑暗深渊，暮光 侍僧携带着较小的碎片，穿行于洞窟般的大厅之中。",al={"哪里获取索兰鲁克宝珠的碎片","谁掉落索兰鲁克宝珠的碎片","索兰鲁克宝珠的碎片位置"}},{q="暮光之锤为何持有这些碎片？",a="暮光之锤邪教徒收集这些碎片，是因为其中仍保留着被囚禁恶魔的魔法精华。他们用腐化的神器为黑暗仪式提供力量，并引导禁忌魔法。",al={"邪教徒为何持有碎片","暮光之锤 索兰鲁克"}},{q="谁能修复索兰鲁克宝珠？",a="杜安·卡汉能够修复索兰鲁克宝珠。这位独居的隐士住在贫瘠之地南部、靠近千针石林边界的地方，研究并重铸燃烧军团的恶魔宝珠。",al={"谁修复宝珠","哪里交付索兰鲁克碎片","杜安·卡汉宝珠"}}},fp="18,150,18.407.0,29.373.1,18.217.0,32.115.0,49.168.0,37.191.0"}
P.entries["item:southsea-treasure"] = {n="南海宝藏",s="南海宝藏藏在棘齿城以南的一艘海盗船上，卑鄙的维尼克斯正想得到这批财宝。海浪剃刀号的最底层船舱位于南海海盗的训练场下方。",h="南海宝藏藏在棘齿城以南的一艘海盗船上，卑鄙的维尼克斯正想得到这批财宝。海浪剃刀号的最底层船舱位于南海海盗的训练场下方。",kw={"大饼干","开锁","波利","棘齿城","碎手氏族","南海宝藏","海浪剃刀号","卑鄙的维尼克斯"},ang={["class:Rogue"]="对于正在成长的潜行者来说，找回南海宝藏既能练习开锁，也能借此接触名为碎手氏族的秘密组织。",["faction:Horde"]="作为部落的一员，破坏南海海盗的藏匿物资有助于当地当局。海盗们不断侵扰贫瘠之地和棘齿城港一带的贸易。"},sec={{t="致命窃案",b="海浪剃刀号停泊在棘齿城以南的商旅海岸沿岸。南海海盗将它用作前哨基地和训练场。他们劫掠来的财物被称为南海宝藏，就藏在最底层的船舱中。\n\n卑鄙的维尼克斯是棘齿城的一名地精无赖，他将这次盗窃作为对有志成为扒手者的考验。他说，上次派去寻找宝箱的五名密探，回来时都已身首异处。警觉的海盗守卫着船只，船舱里还有一只凶猛的生物看守。"},{t="波利的珍藏",b="波利在船舱里守护着南海宝藏。盗贼避开海盗训练师并撬开宝箱的锁后，找到的并非散落的财宝，而是这只充满敌意的鹦鹉。\n\n维尼克斯的大饼干装置可以帮助制服波利。只有这样，才能将宝藏从船舱中取出，完好无损地带回棘齿城。"}},faq={{q="南海宝藏在哪里？",a="南海宝藏位于海浪剃刀号上，这艘船停泊在贫瘠之地棘齿城以南的海岸。宝藏藏在海盗训练舱室下方的最底层船舱中。",al={"宝藏在哪里","海浪剃刀号位置","如何找到南海宝藏"}},{q="谁想要南海宝藏？",a="棘齿城的地精卑鄙的维尼克斯想要南海宝藏。他雇用秘密行动人员潜入船中，为他取回宝藏。",al={"谁提供任务","维尼克斯是谁","谁想要宝藏"}},{q="为什么撬开锁后宝箱是空的？",a="波利在船舱内守护着南海宝藏。撬开宝箱的锁会让这只凶恶的鹦鹉加入战斗；击败波利便能获得宝藏。",al={"波利从哪里来","波利为什么出现","宝藏为什么不在箱子里"}},{q="大饼干是什么，为什么需要它？",a="卑鄙的维尼克斯提供了大饼干，这是一种实验性的地精装置，用于削弱异常凶猛的空中威胁。他打算用它对付波利，也就是船舱里那只致命的守卫鹦鹉。",al={"大饼干是什么","如何击败波利","敌对鹦鹉"}},{q="南海海盗用这艘船做什么？",a="海浪剃刀号是南海海盗的基地和贼窝。船上的第二层设有练习用的锁箱，供船员训练扒手。",al={"海浪剃刀号是什么","贫瘠之地海盗巢穴","南海船舱"}}},fx={c9f033cd={q="什么是南海宝藏？",a="南海宝藏是南海海盗藏匿的战利品，存放在他们停泊于贫瘠之地海岸附近的船只“潮汐剃刀”号上。宝藏深藏于船舱之中，由一只凶名远扬的海盗鹦鹉波莉看守，代表着这些海盗沿商旅海岸劫掠所得的不义之财。",al={"什么是南海宝藏","南海宝藏物品","南海宝藏是什么类型的宝藏"}}},fp="17,189,14.462.0,16.299.1,39.172.0,32.139.0,35.155.1,41.195.0,50.159.0"}
P.entries["item:spectral-comb"] = {n="鬼梳",s="在夜色镇南边一处破败的农庄里，鬼梳能从盲眼玛丽身上收集幽灵的发丝。",h="在夜色镇南边一处破败的农庄里，鬼梳能从盲眼玛丽身上收集幽灵的发丝。",kw={"盲眼玛丽","梳子","夜色镇","暮色森林","幽灵","幽灵的发丝","鬼梳"},ang={["faction:Alliance"]="身为联盟旅人，你可以带着梳子前往夜色镇南边，见证暮色森林昔日农户的悲惨命运。",["profession:Tailoring"]="身为裁缝，你可以用鬼梳从愿意配合的幽灵身上收集虚无的纤维，而无需用寻常手段剪取。"},sec={{t="抚慰不安亡魂的工具",b="普通梳子触不到幽灵的头发，凡人工匠因此鲜有办法收集这类纤维。鬼梳能够穿过灵体虚无的发丝。它被带到夜色镇南边一处破败的农庄，交给盲眼玛丽，一个独自哭号的幽灵。梳理头发能给她带来慰藉，她也乐意使用这把梳子。她留下的幽魂纤维可以织成幽灵的发丝。"}},faq={{q="鬼梳有什么用途？",a="你把梳子交给盲眼玛丽，她是夜色镇南边一个哭泣的幽灵。她梳理头发时，梳子便会收集到虚无的发丝，可以用来纺成具有超自然力量的丝线。",al={"鬼梳用途","为什么需要鬼梳","梳子有什么用"}},{q="盲眼玛丽是谁？",a="盲眼玛丽是一个饱受折磨的灵魂，徘徊在夜色镇南边丘陵中的一座废弃房屋里。悲剧使她陷入疯狂，她挖出了自己的双眼，还害怕别人觉得她死后的模样丑陋不堪。",al={"盲眼玛丽的故事","拿梳子的幽灵是谁","盲眼玛丽"}},{q="为什么不能用普通梳子？",a="普通梳子无法触及灵体虚无的头发。鬼梳则专为穿过幽灵的发丝而制。",al={"为什么用鬼梳","普通梳子与幽灵"}}},fx={e893aa2f={q="什么是鬼梳？",a="鬼梳是一种专门附魔、能够与无形之物互动的灵体梳理工具。普通工具会直接穿过幽灵，无法产生效果，而这把梳子却能触碰、理顺并收集幽灵的发丝。",al={"什么是鬼梳","鬼梳","鬼梳是什么"}}},fp="13,95,24.375.0,35.177.0,18.186.0,37.119.0"}
P.entries["item:spells-of-shadow"] = {n="暗影法术研究",s="在奥格瑞玛地下，暗影法术研究掌握在灼热之刃教徒手中。幽暗城的被遗忘者领袖希望取回这本魔典。",h="在奥格瑞玛地下，暗影法术研究掌握在灼热之刃教徒手中。幽暗城的被遗忘者领袖希望取回这本魔典。",kw={"扭曲虚空的魔法","怒焰裂谷","灼热之刃","暗影法术研究","希尔瓦娜斯","毁灭之力","幽暗城","瓦里玛萨斯"},ang={["class:Warlock"]="身为术士，你能看到灼热之刃教徒如何借助燃烧军团的恶魔恩赐，施展暗影与虚空法术。",["race:Undead"]="身为亡灵，你帮助Sylvanas女士夺取奥格瑞玛地下危险的恶魔知识，增强幽暗城对抗Scourge的力量。"},sec={{t="灼热之刃的典籍",b="灼热之刃教徒将暗影法术研究藏在怒焰裂谷中严加看守的珍宝之中。这个分裂出来的教派与暗影议会有牵连，其成员施展着燃烧军团的恶魔主人赐予的黑暗仪式。书中记载着暗影与邪能法术。教徒和术士将它带在身边，在杜隆塔尔的部落领地下密谋。"},{t="黑暗女王的野心",b="灼热之刃获得恶魔恩赐的消息传到了幽暗城的皇家区。希尔瓦娜斯·风行者女士和她的恐惧魔王副官瓦里玛萨斯认为，这些遗物落在目光短浅的教徒手中实属浪费。瓦里玛萨斯派遣部落冒险者进入怒焰裂谷，夺取暗影法术研究及其配套典籍扭曲虚空的魔法。这些典籍的力量将用于帮助被遗忘者对抗天灾军团和巫妖王。"}},faq={{q="暗影法术研究是什么？",a="暗影法术研究是怒焰裂谷的灼热之刃教徒持有的一本法术书。其中记载着燃烧军团赐予的暗影魔法。",al={"暗影法术研究书籍","暗影法术研究是什么","怒焰裂谷暗影法术研究书籍"}},{q="谁想要这本书？",a="瓦里玛萨斯正在为希尔瓦娜斯·风行者女士寻找这本典籍。他是她的恐惧魔王顾问，居住在幽暗城的皇家区。",al={"谁需要暗影法术研究","暗影法术研究交给谁","暗影法术研究任务发布者"}},{q="在哪里能找到这本书？",a="灼热之刃教徒和术士在怒焰裂谷中随身携带着这本书，那里是奥格瑞玛地下炽热的洞穴。",al={"暗影法术研究位置","哪里获取暗影法术研究","如何获取暗影法术研究"}},{q="被遗忘者为什么想要这本魔典？",a="希尔瓦娜斯女士认为，燃烧军团的黑暗恩赐应当掌握在被遗忘者手中，而非那些目光短浅的教徒手里。她希望用这些魔法增强被遗忘者的力量，以对抗天灾军团和巫妖王。",al={"希尔瓦娜斯为什么想要这本书","瓦里玛萨斯为什么想要暗影法术研究"}}},fp="16,148,26.335.0,24.437.0,29.130.0,20.133.0,28.114.0,39.193.0"}
P.entries["item:spotted-sunfish"] = {n="斑点太阳鱼",s="止水湖的斑点太阳鱼吸引着垂钓者，也引来了饥饿的鱼人。这些鱼为湖畔镇带来了生意，但鱼人让浅水区变得危机四伏。",h="止水湖的斑点太阳鱼吸引着垂钓者，也引来了饥饿的鱼人。这些鱼为湖畔镇带来了生意，但鱼人让浅水区变得危机四伏。",kw={"码头管理员巴伦","止水湖","湖畔镇","鱼人","赤脊山","卖鱼","斑点太阳鱼"},ang={["profession:Cooking"]="作为厨师，你可以用斑点太阳鱼烹饪。这种本地淡水鱼是赤脊山酒馆餐桌上的常见食材。"},sec={{t="珍贵的渔获",b="斑点太阳鱼为湖畔镇的码头带来了生意。湖中渔获源源不断，码头管理员巴伦收购这些鱼，为处境艰难的小镇提供食物，带动贸易。凶悍的鱼人部族在浅水区游荡，扰乱捕鱼。他们将太阳鱼囤积在营地里，旅人可以用武力夺取这些鱼。"}},faq={{q="哪里能找到斑点太阳鱼？",a="斑点太阳鱼生活在赤脊山的止水湖中。垂钓者在湖中捕捞它们，鱼人则将它们囤积在沿岸的营地里。",al={"哪里获取斑点太阳鱼","斑点太阳鱼位置","止水湖鱼类"}},{q="谁收购或需要斑点太阳鱼？",a="码头管理员巴伦在湖畔镇的码头收购斑点太阳鱼。他经营鱼类买卖，出钱收购新鲜的鱼。",al={"谁需要斑点太阳鱼","码头管理员巴伦鱼类","卖鱼任务"}},{q="鱼人为什么带着这些鱼？",a="止水湖沿岸的鱼人收集太阳鱼，供养日益壮大的部族。他们将渔获存放在浅水区沿岸的营地里。",al={"鱼人斑点太阳鱼","鱼人为什么掉落鱼"}},{q="不钓鱼也能获得它们吗？",a="可以。没有鱼竿的旅人可以击败止水湖沿岸的敌对鱼人，夺取他们收集的鱼。",al={"没有鱼竿获取太阳鱼","没有鱼竿太阳鱼"}}},fx={["723094c5"]={q="什么是斑点太阳鱼？",a="斑点太阳鱼是赤脊山止水湖的珍贵淡水鱼。它以美味和商业价值闻名当地，在湖泊深水中繁衍生息，是湖畔镇渔民的主要商品，也是当地鱼人的重要食物来源。",al={"什么是斑点太阳鱼","斑点太阳鱼信息","斑点太阳鱼背景"}},["1a933976"]={q="斑点太阳鱼来自哪里？",a="斑点太阳鱼原生于赤脊山止水湖的清凉湖水中。它们并非人工制作或养殖，而是直接从湖中捕获的野生鱼类，可以在码头和岸边垂钓，也可以从当地鱼人偷猎者手中夺回。",al={"斑点太阳鱼的来源","斑点太阳鱼来自哪里","斑点太阳鱼来源"}}},fp="15,149,14.293.0,32.145.0,34.109.0,36.126.0,36.137.0"}
